/** Same shape `cli.ts` reads; declared here so this file never imports the CLI. */
interface CutEntry {
  rig: string;
  motion: string;
  out: string;
  manifest?: string;
  images?: string;
}
type CutTable = Record<string, CutEntry>;

interface Options {
  rigPath: string;
  motionPath: string;
  outDir: string;
  manifestPath?: string;
  imagesDir?: string;
}

/** How many arguments follow a flag on the command line, as its reader takes them (issue #1174). */
type FlagArity = 'none' | 'one' | 'optional' | 'two' | 'one or more';

/** One argument the harness takes: a row of `HARNESS_FLAGS`. */
interface HarnessFlag {
  /** The one spelling a reader reads. */
  spelling: string;
  /** What follows it, as the table prints it; '' when nothing does. */
  values: string;
  /**
   * What the claim pass takes after the flag: `one` the next argument whatever
   * it is, `two` the next two, `optional` the next unless it starts with `--`,
   * `one or more` every following argument up to the next that starts with
   * `--`. The readers refuse a missing or `--` value before the claim pass runs,
   * so this is the reading they make of a line they accepted.
   */
  arity: FlagArity;
  /** The environment variable its reader also reads, or ''. */
  environment: string;
  /** `caller` for a person or CI; `parent` for a flag a run passes a process it starts. */
  passedBy: 'caller' | 'parent';
  meaning: string;
}

/**
 * Every argument the harness takes (issue #1174). An argument no row claims is
 * refused by name before anything runs: it used to be ignored, and ignored
 * meant "run everything" — `bun selftest.ts --help` started a full run.
 *
 * 🔒 The table and the readers cannot disagree without the process saying so:
 * a reader names its flag through `readerOf`, which refuses a spelling with no
 * row, and before the claim pass every row must have been named by a reader
 * (`--help` and `-h` by the claim pass, which is theirs). `--help` prints
 * `flagTableText()`, a refusal prints it on stderr, and CONTRIBUTING.md carries
 * the same text; `TY45` holds all three.
 */
const HARNESS_FLAGS: readonly HarnessFlag[] = [
  { spelling: '--only', values: '<suite>[,<suite>…]', arity: 'one', environment: '', passedBy: 'caller', meaning: 'a PARTIAL run of the named suites: exits 2 when green, never a verdict' },
  { spelling: '--cuts', values: '<cuts.json>', arity: 'one', environment: 'RIGC_CUTS', passedBy: 'caller', meaning: 'adds a suite that compiles and gates every cut in that table' },
  { spelling: '--shard', values: '<i>/<n>', arity: 'one', environment: 'RIGC_SHARD', passedBy: 'caller', meaning: 'runs the suites dealt to shard i of n: exits 2 when green, never a verdict' },
  { spelling: '--tally-out', values: '<file>', arity: 'one', environment: 'RIGC_TALLY_OUT', passedBy: 'caller', meaning: "with --shard: the shard's tally document, which --merge reads; with --merge: the merged run's, which a publish reads" },
  { spelling: '--merge', values: '<file>…', arity: 'one or more', environment: '', passedBy: 'caller', meaning: "every shard's tally document merged: the verdict" },
  { spelling: '--shards-base', values: '[<file>]', arity: 'optional', environment: '', passedBy: 'caller', meaning: 'with --merge: a green merge writes the durations base, to <file> or over the tracked one' },
  { spelling: '--memory-base', values: '', arity: 'none', environment: '', passedBy: 'caller', meaning: "a green one-process full run writes its platform and Bun line's row of the memory base" },
  { spelling: '--memory-base-children', values: '[<file>]', arity: 'optional', environment: '', passedBy: 'caller', meaning: "with --merge: a green merge writes the children's half of the memory base" },
  { spelling: '--reset-children-base', values: '', arity: 'none', environment: '', passedBy: 'caller', meaning: "lets a writer of the children's figures move a tracked one, up or down, or replace them read at another --jobs" },
  { spelling: '--jobs', values: '<n>', arity: 'one', environment: 'RIGC_JOBS', passedBy: 'caller', meaning: "how many of a suite's independent units run at once; the machine's cores by default" },
  { spelling: '--keep-temp', values: '', arity: 'none', environment: 'RIGC_KEEP_TEMP', passedBy: 'caller', meaning: "keeps this process's temp root and names it on stderr" },
  { spelling: '--help', values: '', arity: 'none', environment: '', passedBy: 'caller', meaning: 'prints this table on stdout and exits 0, before anything is made or swept' },
  { spelling: '-h', values: '', arity: 'none', environment: '', passedBy: 'caller', meaning: 'the same as --help' },
  { spelling: '--unit', values: '<spec.json> <out.json>', arity: 'two', environment: '', passedBy: 'parent', meaning: 'this process is one unit a suite handed out; runs no suite' },
];

/** The line `--help` prints above `flagTableText()`. */
const HELP_HEADER = 'bun selftest.ts [argument…] takes these arguments, and refuses any other by name before it runs anything:';

/** The spellings the readers have named, in the order they named them (`readerOf`). */
const FLAGS_READ = new Set<string>();

/**
 * The row a reader reads, by its spelling — refused, exit 2, when the table has
 * none, because a reader of a flag the table does not list is one whose flag
 * the claim pass would refuse (issue #1174).
 */
function readerOf(spelling: string): HarnessFlag {
  const row = HARNESS_FLAGS.find((flag) => flag.spelling === spelling);
  if (row === undefined) {
    console.error(`selftest: a reader reads ${spelling}, which HARNESS_FLAGS has no row for; add its row, or the claim pass refuses every line that gives it`);
    process.exit(2);
  }
  FLAGS_READ.add(spelling);
  return row;
}

/** The table as `--help`, a refusal and CONTRIBUTING.md print it: one line per row, in the table's order. */
function flagTableText(flags: readonly HarnessFlag[] = HARNESS_FLAGS): string {
  const left = flags.map((flag) => (flag.values === '' ? flag.spelling : `${flag.spelling} ${flag.values}`));
  const width = Math.max(...left.map((text) => text.length));
  return flags
    .map((flag, k) => {
      // A flag that takes no value has a switch for a variable, and its reader takes 1 (`parseKeepTemp`).
      const variable = flag.environment === '' ? [] : [`or ${flag.environment}=${flag.arity === 'none' ? '1' : flag.values}`];
      const notes = [...variable, ...(flag.passedBy === 'parent' ? ['passed by a run to a process it starts'] : [])];
      return `  ${left[k].padEnd(width)}  ${flag.meaning}${notes.length === 0 ? '' : ` (${notes.join('; ')})`}`;
    })
    .join('\n');
}

/** One argument the claim pass did not claim: its 1-based position, the argument as given, and why. */
interface UnclaimedArgument {
  at: number;
  argument: string;
  repeated: boolean;
}

/**
 * Walk `argv` by the table (issue #1174): a row's spelling claims itself and
 * the values its arity takes, and everything else is unclaimed — an unknown
 * argument, a stray positional, or a flag given again (every reader reads the
 * first; a repeat, and its values, are read by none). Pure, so `TY45` holds the
 * arities without starting a process.
 */
function unclaimedArguments(argv: readonly string[], flags: readonly HarnessFlag[] = HARNESS_FLAGS): UnclaimedArgument[] {
  const unclaimed: UnclaimedArgument[] = [];
  const seen = new Set<string>();
  for (let k = 0; k < argv.length; k++) {
    const row = flags.find((flag) => flag.spelling === argv[k]);
    if (row === undefined) {
      unclaimed.push({ at: k + 1, argument: argv[k], repeated: false });
      continue;
    }
    if (seen.has(row.spelling)) unclaimed.push({ at: k + 1, argument: argv[k], repeated: true });
    seen.add(row.spelling);
    const isValue = (j: number): boolean => j < argv.length && !argv[j].startsWith('--');
    if (row.arity === 'one') k = Math.min(k + 1, argv.length - 1);
    else if (row.arity === 'two') k = Math.min(k + 2, argv.length - 1);
    else if (row.arity === 'optional' && isValue(k + 1)) k++;
    else if (row.arity === 'one or more') while (isValue(k + 1)) k++;
  }
  return unclaimed;
}

/** The optimal-string-alignment distance between `a` and `b` capped at 2: one insertion, deletion, substitution or swap of neighbours is 1. */
function editDistanceUpTo2(a: string, b: string): number {
  if (Math.abs(a.length - b.length) > 2) return 2;
  const d: number[][] = Array.from({ length: a.length + 1 }, (_, i) => Array.from({ length: b.length + 1 }, (_, j) => (i === 0 ? j : j === 0 ? i : 0)));
  for (let i = 1; i <= a.length; i++) {
    for (let j = 1; j <= b.length; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + cost);
      if (i > 1 && j > 1 && a[i - 1] === b[j - 2] && a[i - 2] === b[j - 1]) d[i][j] = Math.min(d[i][j], d[i - 2][j - 2] + 1);
    }
  }
  return Math.min(d[a.length][b.length], 2);
}

/**
 * The refusal line for one unclaimed argument. It names a flag only when the
 * rule leaves no choice: `<flag>=<value>` where `<flag>` is a row, or one edit
 * (`editDistanceUpTo2`) from exactly one row's spelling — two as near, and it
 * names neither.
 */
function unclaimedLine(entry: UnclaimedArgument, flags: readonly HarnessFlag[] = HARNESS_FLAGS): string {
  const given = `argument ${entry.at}, ${JSON.stringify(entry.argument)},`;
  if (entry.repeated) return `selftest: ${given} gives ${entry.argument} a second time; every reader reads the first, so give it once`;
  const equals = /^(-[^=]*)=/.exec(entry.argument);
  const joined = equals === null ? undefined : flags.find((flag) => flag.spelling === equals[1]);
  if (joined !== undefined) {
    const how = joined.arity === 'none' ? 'takes no value' : 'takes its value as the next argument, not after =';
    return `selftest: ${given} is not an argument this harness takes; ${joined.spelling} ${how}`;
  }
  const near = flags.filter((flag) => editDistanceUpTo2(entry.argument, flag.spelling) === 1);
  return `selftest: ${given} is not an argument this harness takes${near.length === 1 ? `; one edit from ${near[0].spelling}` : ''}`;
}

/**
 * The cuts table, if one was named. `null` is a normal outcome, not a failure:
 * the public suite does not need it and the extra suite says so out loud.
 *
 * ⚠️ A path that was NAMED and is not there is a different thing entirely, and it
 * exits 2. Treating a typo as "no cuts file" would mean the one caller who asked
 * for the extra suite is the one caller who silently does not get it.
 */
function readCutTable(): { file: string; dir: string; table: CutTable } | null {
  const argv = process.argv.slice(2);
  const cuts = readerOf('--cuts');
  const flag = argv.indexOf(cuts.spelling);
  let named: string | null = null;
  if (flag !== -1) {
    const value = argv[flag + 1];
    if (!value) {
      console.error('selftest: --cuts needs a path');
      process.exit(2);
    }
    named = resolve(value);
  } else if (process.env[cuts.environment]) {
    named = resolve(process.env[cuts.environment] ?? '');
  }
  if (named === null) return null;
  if (!existsSync(named)) {
    console.error(`selftest: --cuts named ${named}, which does not exist`);
    process.exit(2);
  }
  return { file: named, dir: dirname(named), table: JSON.parse(readFileSync(named, 'utf8')) as CutTable };
}

const CUTS = readCutTable();

/**
 * The suites `--only` names, or `null` when the flag is absent and this is the
 * full run (issue #937).
 *
 * ⚠️ Every malformed spelling exits 2 here rather than being read generously: a
 * flag with no value, an empty name between commas, a name given twice, the flag
 * given twice. Each is a run whose caller meant something this parser would
 * otherwise have to guess, and the guess would decide which suites a verdict
 * covers. Whether a name is one this file registers is NOT decided here: the
 * registry is the sequence of `tally.of` calls in `main`, and a second list of
 * suite names kept beside it is the hand-kept table this file refuses. So an
 * unknown name is refused once the registry has been walked (`onlyRefusal`).
 */
function readOnlyList(argv: readonly string[]): ReadonlySet<string> | null {
  const { spelling } = readerOf('--only');
  const at = argv.indexOf(spelling);
  if (at === -1) return null;
  if (argv.indexOf(spelling, at + 1) !== -1) {
    console.error('selftest: --only was given twice; name every suite in one comma-separated list');
    process.exit(2);
  }
  const value = argv[at + 1];
  if (value === undefined || value.startsWith('--')) {
    console.error('selftest: --only needs a comma-separated list of suite names, e.g. --only core,run-tally');
    process.exit(2);
  }
  const refusals: string[] = [];
  const seen = new Set<string>();
  for (const name of value.split(',')) {
    if (name === '') refusals.push(`--only ${value} holds an empty name between its commas`);
    else if (seen.has(name)) refusals.push(`--only ${value} names the suite "${name}" twice`);
    seen.add(name);
  }
  if (refusals.length > 0) {
    for (const refusal of refusals) console.error(`selftest: ${refusal}`);
    process.exit(2);
  }
  return seen;
}

const ONLY = readOnlyList(process.argv.slice(2));

/**
 * Whether this run writes its platform's entry of the memory base when it ends
 * green (issue #1121, `TY26`). Refused beside `--only`: a partial run's final
 * RSS is the high-water of the suites it ran, not of the run the base stands for.
 */
const WRITE_MEMORY_BASE = ((): boolean => {
  const argv = process.argv.slice(2);
  if (!argv.includes(readerOf('--memory-base').spelling)) return false;
  if (ONLY !== null) {
    console.error('selftest: --memory-base writes the high-water RSS of the FULL run; it cannot be given with --only');
    process.exit(2);
  }
  return true;
})();

/** One shard of a sharded run (issue #1116): the `i`th of `n`, 1-based, as `--shard i/n` names it. */
interface ShardSpec {
  i: number;
  n: number;
}

/**
 * `--shard`'s value read as `i/n`, or the refusal naming what is wrong with it.
 * Pure, so `TY27` can hold every refusal by name without starting a process.
 *
 * ⚠️ Read strictly, for `readOnlyList`'s reason: `0/3`, `4/3`, `1/0`, `1.5/3`,
 * `+1/3`, `1/3/2` and ` 1/3` are each a caller who meant something, and a
 * generous reading would decide which suites a shard covers by guessing.
 */
function parseShardSpec(value: string): ShardSpec | string {
  const match = /^([1-9]\d*)\/([1-9]\d*)$/.exec(value);
  if (match === null) {
    return `--shard ${JSON.stringify(value)} is not <i>/<n> with i and n whole numbers from 1, e.g. --shard 2/3`;
  }
  const i = Number(match[1]);
  const n = Number(match[2]);
  if (i > n) return `--shard ${value} names shard ${i} of ${n}; a shard's i runs from 1 to n`;
  return { i, n };
}

/**
 * The value a flag names, from the command line or else from its environment
 * variable — `RIGC_CUTS`'s precedent, and the reason CI's step can stay
 * `bun run selftest` (`CUR112` holds that exact line) while each matrix job
 * names its own shard. `null` when neither names one; a flag with no value
 * exits 2.
 */
function flagOrEnvironment(argv: readonly string[], row: HarnessFlag): string | null {
  const { spelling: flag, environment: variable } = row;
  const at = argv.indexOf(flag);
  if (at !== -1) {
    if (argv.indexOf(flag, at + 1) !== -1) {
      console.error(`selftest: ${flag} was given twice`);
      process.exit(2);
    }
    const value = argv[at + 1];
    if (value === undefined || value.startsWith('--')) {
      console.error(`selftest: ${flag} needs a value`);
      process.exit(2);
    }
    return value;
  }
  const fromEnvironment = process.env[variable];
  return fromEnvironment === undefined || fromEnvironment === '' ? null : fromEnvironment;
}

/**
 * `--shard <i>/<n>` (or `RIGC_SHARD`): this process runs the suites dealt to
 * shard `i` — longest-first over `SHARDS_BASE_PATH`, round-robin by
 * registration index where the base has no entry (issue #1128) — exactly as
 * the full run runs them, and none of the rest (issue #1116). Refused beside `--only` (two
 * ways of choosing suites, and a run choosing by both would be choosing by
 * neither) and beside `--memory-base` (a shard's high-water is not the run's).
 */
const SHARD = ((): ShardSpec | null => {
  const value = flagOrEnvironment(process.argv.slice(2), readerOf('--shard'));
  if (value === null) return null;
  const read = parseShardSpec(value);
  if (typeof read === 'string') {
    console.error(`selftest: ${read}`);
    process.exit(2);
  }
  if (ONLY !== null) {
    console.error('selftest: --shard and --only both choose which suites run; give one of them');
    process.exit(2);
  }
  if (WRITE_MEMORY_BASE) {
    console.error("selftest: --memory-base writes the high-water RSS of the FULL run; a shard's is the high-water of the suites it ran");
    process.exit(2);
  }
  return read;
})();

/**
 * `--tally-out <file>` (or `RIGC_TALLY_OUT`): where this process writes its
 * tally document. Under `--shard`, the shard's — the one thing `--merge` reads.
 * Under `--merge` (issue #1249), the merged run's: the commit, the shards'
 * exits and the census `scripts/prepublish_gate.ts` holds before it accepts a
 * sharded run in place of the one-process selftest a publish would otherwise
 * run. Refused with neither: a one-process run's tally is its summary.
 */
const TALLY_OUT = ((): string | null => {
  const value = flagOrEnvironment(process.argv.slice(2), readerOf('--tally-out'));
  if (value === null) return null;
  if (SHARD === null && !process.argv.slice(2).includes('--merge')) {
    console.error("selftest: --tally-out writes a shard's or a merge's tally document; it needs --shard <i>/<n> (or RIGC_SHARD) or --merge <file>…");
    process.exit(2);
  }
  return resolve(value);
})();

/**
 * `--merge <file>…`: the shard documents whose merge is the verdict (issue
 * #1116) — every argument after the flag up to the next `--` flag. Refused
 * beside any flag that chooses or measures suites in this process: the merge
 * reads what the shards ran, and runs only the suites that read the whole run.
 */
const MERGE = ((): string[] | null => {
  const argv = process.argv.slice(2);
  const at = argv.indexOf(readerOf('--merge').spelling);
  if (at === -1) return null;
  const files: string[] = [];
  for (let k = at + 1; k < argv.length && !argv[k].startsWith('--'); k++) files.push(resolve(argv[k]));
  if (files.length === 0) {
    console.error('selftest: --merge needs the shard documents, e.g. --merge shard-1.json shard-2.json shard-3.json');
    process.exit(2);
  }
  for (const [flag, given] of [['--only', ONLY !== null], ['--shard', SHARD !== null], ['--memory-base', WRITE_MEMORY_BASE]] as const) {
    if (given) {
      // Issue #1144: the children's half is a merge's to write, under its own flag; the parent's is not.
      const children = flag === '--memory-base' ? " — a merge writes only the children's half of the memory base, with --memory-base-children [<file>]" : '';
      console.error(`selftest: --merge reads the shards' documents and cannot be given with ${flag}${children}`);
      process.exit(2);
    }
  }
  return files;
})();
/**
 * `--shards-base [<file>]` (issue #1128): a green merge writes the durations
 * base off its own per-suite seconds — the durations the next `--shard` deals
 * from — to `<file>`, or to `SHARDS_BASE_PATH` when no file follows the flag
 * (CI names a file under its temp directory and uploads it, so the tracked base
 * can be rewritten from CI's own seconds). Refused without `--merge`: one
 * process's or one shard's seconds are not the run's. It changes nothing else:
 * the file is written after the verdict and the memory ceiling, so a red merge
 * exits red before it and writes nothing.
 */
const WRITE_SHARDS_BASE = ((): string | null => {
  const argv = process.argv.slice(2);
  const at = argv.indexOf(readerOf('--shards-base').spelling);
  if (at === -1) return null;
  if (MERGE === null) {
    console.error("selftest: --shards-base writes the durations base off a merged run's per-suite seconds; it needs --merge <file>…");
    process.exit(2);
  }
  if (argv.indexOf('--shards-base', at + 1) !== -1) {
    console.error('selftest: --shards-base was given twice');
    process.exit(2);
  }
  const named = argv[at + 1];
  // '' stands for the tracked path, resolved where it is written (`SHARDS_BASE_PATH` is declared further down).
  return named === undefined || named.startsWith('--') ? '' : resolve(named);
})();
/**
 * `--memory-base-children [<file>]` (issue #1144): a green merge writes the
 * CHILDREN'S half of its platform's memory-base entry — `children: {highWater,
 * jobs}`, the largest child any suite of the merged run measured and the
 * `--jobs` the processes that measured it ran at — to `<file>`, or over
 * `MEMORY_BASE_PATH` when no file follows the flag (CI names a file under its
 * temp directory and uploads it). The entry's parent half — `highWater`,
 * `suites`, `bun` — is kept as the one-process run wrote it, because a shard's
 * high-water is not the run's; a child's peak is the same whichever process
 * started it, so the largest over the shards' documents is the run's.
 *
 * Its own flag rather than `--memory-base` under `--merge`, because that
 * refusal stays true: `--memory-base` writes both halves off ONE process, and
 * a merge has no one process whose high-water is the run's. Refused without
 * `--merge`: a one-process run writes both halves with `--memory-base`, and a
 * shard's children are a share of the run. It changes nothing else: the file
 * is written after the verdict and the memory ceiling, so a red merge exits red
 * before it and writes nothing, and `mergedChildrenBase` refuses a red tally
 * itself as well (`TY41`).
 */
const WRITE_CHILDREN_BASE = ((): string | null => {
  const argv = process.argv.slice(2);
  const at = argv.indexOf(readerOf('--memory-base-children').spelling);
  if (at === -1) return null;
  if (MERGE === null) {
    console.error(
      "selftest: --memory-base-children writes the children's half of the memory base off a merged run's shard documents; it needs --merge <file>… " +
        '(a one-process full run writes both halves with --memory-base)',
    );
    process.exit(2);
  }
  if (argv.indexOf('--memory-base-children', at + 1) !== -1) {
    console.error('selftest: --memory-base-children was given twice');
    process.exit(2);
  }
  const named = argv[at + 1];
  // '' stands for the tracked path, resolved where it is written (`MEMORY_BASE_PATH` is declared further down).
  return named === undefined || named.startsWith('--') ? '' : resolve(named);
})();
/**
 * `--reset-children-base` (issues #1151, #1166): the one spelling under which
 * a writer of the children's figures — `--memory-base` or
 * `--memory-base-children` — moves a tracked figure, up or down, or replaces
 * figures read at another `--jobs`. Without it both writers keep every tracked
 * figure whatever the run read (`writtenChildren`), add one only for a suite
 * the base holds none for, and their line says which they kept beside this
 * run's. A companion rather than a value of either flag:
 * `--memory-base` takes no value, `--memory-base-children`'s value is a path,
 * and the shards base's writer has no such rule, so a bare `--reset` would read
 * as resetting something it does not. Refused without either writer, since it
 * would then change nothing — a caller who typed it expected a write.
 */
const RESET_CHILDREN_BASE = ((): boolean => {
  const argv = process.argv.slice(2);
  const at = argv.indexOf(readerOf('--reset-children-base').spelling);
  if (at === -1) return false;
  if (argv.indexOf('--reset-children-base', at + 1) !== -1) {
    console.error('selftest: --reset-children-base was given twice');
    process.exit(2);
  }
  if (!WRITE_MEMORY_BASE && WRITE_CHILDREN_BASE === null) {
    console.error(
      "selftest: --reset-children-base lets a writer of the children's memory base move a tracked figure, up or down, or replace figures read at another --jobs; " +
        'it needs --memory-base (a green one-process full run) or --merge <file>… --memory-base-children [<file>], and without either it writes nothing',
    );
    process.exit(2);
  }
  return true;
})();
// Read once, above; a child this run starts is not a shard of it.
delete process.env.RIGC_SHARD;
delete process.env.RIGC_TALLY_OUT;

/**
 * `--jobs`'s value read as a whole number from 1, or the refusal naming what is
 * wrong with it (issue #1128). Pure, so `TY32` holds every refusal by name.
 * Read strictly for `parseShardSpec`'s reason: `0`, `-1`, `x`, `1.5`, `+2` and
 * ` 2` are each a caller who meant something a generous reading would guess.
 */
function parseJobs(value: string): number | string {
  if (!/^[1-9]\d*$/.test(value)) return `--jobs ${JSON.stringify(value)} is not a whole number of concurrent units from 1, e.g. --jobs 2`;
  return Number(value);
}

/**
 * `--jobs <n>` (or `RIGC_JOBS`): how many of a suite's independent units run
 * at once (issue #1128) — the units `inParallel` is handed, today the heavy
 * subprocesses of `render-hashes`, the packs by set of `packer` and the
 * posing-heavy controls of `core` (issue #1133). Absent, the
 * machine's cores as Bun reports them, never under 1. `--jobs 1` is the run as
 * it was before the flag existed: every unit in order, in this process's turn.
 *
 * 🔒 Whatever `n`, the printed log is the same text (`TY33`, `RH08`, `PK105`, `CO41`):
 * a unit prints nothing, the suite prints its case lines after every unit it
 * reads has finished, in the order the sequential run prints them.
 */
const JOBS = ((): number => {
  const value = flagOrEnvironment(process.argv.slice(2), readerOf('--jobs'));
  if (value === null) return Math.max(1, Math.floor(navigator.hardwareConcurrency || 1));
  const read = parseJobs(value);
  if (typeof read === 'string') {
    console.error(`selftest: ${read}`);
    process.exit(2);
  }
  return read;
})();

/**
 * `--unit <spec.json> <out.json>`: this process is one unit `inUnits` handed
 * out (issue #1128) — it runs that unit's work and writes its value, and runs
 * no suite. Not a flag for a person; it is how a pack in another process is
 * the same code as a pack in this one.
 */
const UNIT = ((): { input: string; output: string } | null => {
  const argv = process.argv.slice(2);
  const at = argv.indexOf(readerOf('--unit').spelling);
  if (at === -1) return null;
  const input = argv[at + 1];
  const output = argv[at + 2];
  if (input === undefined || output === undefined || input.startsWith('--') || output.startsWith('--')) {
    console.error('selftest: --unit needs <spec.json> <out.json>; it is how a suite hands one of its units to another process');
    process.exit(2);
  }
  return { input, output };
})();

/**
 * `--keep-temp` (or `RIGC_KEEP_TEMP=1`) read strictly (issue #1137): `true` to
 * keep this process's temp root, `false` for the default, or the refusal naming
 * the spelling — `parseJobs`' reason: `--keep-temp=1`, `--keep-temps`,
 * `RIGC_KEEP_TEMP=yes` are each a caller who meant something, and a generous
 * reading would decide by guessing whether the run cleans up. Pure, so `TY39`
 * holds every refusal by name without starting a process.
 */
function parseKeepTemp(argv: readonly string[], fromEnvironment: string | undefined): boolean | string {
  const spelled = argv.filter((arg) => /^--keep[-_]?temp/i.test(arg));
  for (const arg of spelled) if (arg !== '--keep-temp') return `${JSON.stringify(arg)} is not --keep-temp, which is spelled exactly so and takes no value`;
  if (spelled.length > 1) return '--keep-temp was given twice';
  if (fromEnvironment !== undefined && fromEnvironment !== '' && fromEnvironment !== '1') {
    return `RIGC_KEEP_TEMP=${JSON.stringify(fromEnvironment)} is not 1; set it to 1 to keep this run's temp root, or leave it unset`;
  }
  return spelled.length === 1 || fromEnvironment === '1';
}

/**
 * Whether this process keeps its temp root when it ends (issue #1137). Read
 * once and taken out of the environment: a child this run starts — a `--unit`
 * process, a selftest a control starts — removes its own root unless it is
 * asked by its own command line.
 */
const KEEP_TEMP = ((): boolean => {
  const read = parseKeepTemp(process.argv.slice(2), process.env[readerOf('--keep-temp').environment]);
  if (typeof read === 'string') {
    console.error(`selftest: ${read}`);
    process.exit(2);
  }
  return read;
})();
delete process.env.RIGC_KEEP_TEMP;

/**
 * The claim pass (issue #1174), after every reader and before the stale-root
 * sweep and the temp root: what the readers accepted is walked by the table,
 * and an argument it does not claim is refused by name, exit 2 — the run
 * measured nothing — with the table on stderr. `--help` or `-h` on a line with
 * nothing unclaimed prints the table on stdout and exits 0, as `rigc --help`
 * prints its usage on stdout and exits 0 while `rigc <unknown>` prints it on
 * stderr and exits 2. An unclaimed argument beside `--help` is still refused:
 * the refusal carries the same table, and its exit says the line was wrong.
 *
 * Readers first so that each keeps its own refusal: `--keep-temps` is
 * `parseKeepTemp`'s to name, `--only` with no value `readOnlyList`'s.
 */
{
  // `--help` and `-h` are the claim pass's own rows; every other row a reader above has named.
  const help = [readerOf('--help').spelling, readerOf('-h').spelling];
  const unread = HARNESS_FLAGS.filter((flag) => !FLAGS_READ.has(flag.spelling)).map((flag) => flag.spelling);
  if (unread.length > 0) {
    console.error(`selftest: HARNESS_FLAGS has a row no reader reads: ${unread.join(', ')}; remove the row, or read the flag through readerOf`);
    process.exit(2);
  }
  const argv = process.argv.slice(2);
  const unclaimed = unclaimedArguments(argv);
  if (unclaimed.length > 0) {
    for (const entry of unclaimed) console.error(unclaimedLine(entry));
    console.error(`selftest: nothing was run. The arguments it takes:\n${flagTableText()}`);
    process.exit(2);
  }
  if (argv.some((arg) => help.includes(arg))) {
    console.log(`${HELP_HEADER}\n${flagTableText()}`);
    process.exit(0);
  }
}

/** The system temp directory as this process found it — where the run root is made, and what `TY39` counts. */
const SYSTEM_TEMP = tmpdir();
let harnessTempRoot: string | null = null;

/**
 * The name a run root has and nothing else directly under `tmpdir()` has
 * (issue #1156): `rigc-selftest-` and the six characters `mkdtemp` appends.
 * Exactly that shape rather than the prefix and anything after it, because a
 * `rigc-selftest-units-XXXXXX` directly under `tmpdir()` is not a directory
 * this harness makes there any more, and a sweep is only ever entitled to the
 * one name it makes — and to the name a sweep gives a root it has claimed
 * (`.swept-<pid>`, see `sweepStaleRoots`), so a sweeper killed halfway through
 * a removal leaves something the next sweep still finds.
 */
const STALE_ROOT_NAME = /^rigc-selftest-[A-Za-z0-9]{6}(?:\.swept-\d+)?$/;

/**
 * How long a run root must have gone untouched before a later run removes it
 * (issue #1156). A root's modification time moves when an entry directly
 * inside it is made or removed, so the age counts from the run's last direct
 * child, never from its start, and the gap it must outlast is the longest a
 * live run goes without making or removing one — at most the run itself, the
 * longest of which measured on one machine is 1,378 s (#1122). Read on a
 * `--only render-hashes,packer,core --jobs 2` run of 563 s at load 6 to 8, the
 * longest stretch any root went unmoved was 96 s (the parent's; a `--unit`
 * child's root that is never touched after it is made lived at most 39 s). 24 h
 * is the longest run 62 times over, which also covers a loaded machine and one
 * that slept through part of a run; a longer age costs one directory entry
 * per killed run for the extra time, a shorter one risks a live run's root.
 */
const STALE_ROOT_AGE_HOURS = 24;

/** What one sweep did: the roots it removed and the bytes of the files they held, and each it found stale and could not remove, with the reason. */
interface StaleSweep {
  removed: string[];
  bytes: number;
  failed: string[];
}

/**
 * The bytes of the files under `path`, read with `lstat` so a link is counted
 * as itself and never followed; an entry gone before it is read counts 0.
 * Walked before a stale root is removed because it is cheap beside the
 * removal: over a root a killed `--only path-slider` run left (985 entries),
 * 26 ms against the removal's 86 ms (medians of 9, issue #1156).
 */
function treeBytes(path: string): number {
  let stat: ReturnType<typeof lstatSync>;
  try {
    stat = lstatSync(path);
  } catch {
    return 0;
  }
  if (!stat.isDirectory()) return stat.size;
  let entries: string[] = [];
  try {
    entries = readdirSync(path);
  } catch {
    return 0;
  }
  let bytes = 0;
  for (const entry of entries) bytes += treeBytes(join(path, entry));
  return bytes;
}

/**
 * Remove every directory directly in `dir` whose name `name` matches and whose
 * modification time is more than `ageMs` before `now` (issue #1156) — the roots
 * runs killed by a signal left. Pure of the clock: `now` and `ageMs` are
 * handed in, so `TY44` plants a sweep that ignores the age or widens the name
 * by calling this with another value rather than by editing it.
 *
 * Only real directories: an entry is read with `lstat`, so a symlink of a
 * root's name is neither followed nor removed — the harness makes directories
 * there and never links, so a link is something else's, and following it
 * would delete what it points to.
 *
 * Losing a race is not an error, and is made impossible to mistake for one: a
 * stale root is first CLAIMED by renaming it to `<name>.swept-<pid>`, which
 * succeeds for exactly one of n sweepers, and only the claimant walks and
 * removes it; a sweeper whose rename finds the root gone (`ENOENT`) skips it.
 * Measured without the claim, four sweepers over forty stale roots each
 * removed ten and three of them reported six roots "still present after
 * removal" — `rmSync` returned while another process was mid-way through the
 * same tree. A root still present after its claimant's removal is reported
 * with the error, never thrown: a sweep that cannot clean up after another run
 * has no reason to stop this one.
 */
function sweepStaleRoots(dir: string, now: number, ageMs: number, name: RegExp = STALE_ROOT_NAME): StaleSweep {
  const swept: StaleSweep = { removed: [], bytes: 0, failed: [] };
  for (const entry of readdirSync(dir).sort()) {
    if (!name.test(entry)) continue;
    const path = join(dir, entry);
    let stat: ReturnType<typeof lstatSync>;
    try {
      stat = lstatSync(path);
    } catch {
      continue;
    }
    if (!stat.isDirectory() || now - stat.mtimeMs <= ageMs) continue;
    const claimed = join(dir, `${entry.replace(/\.swept-\d+$/, '')}.swept-${process.pid}`);
    try {
      renameSync(path, claimed);
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code !== 'ENOENT') swept.failed.push(`${path}: ${(err as Error).message}`);
      continue;
    }
    const bytes = treeBytes(claimed);
    let error = '';
    try {
      rmSync(claimed, { recursive: true, force: true });
    } catch (err) {
      error = (err as Error).message;
    }
    if (existsSync(claimed)) swept.failed.push(`${claimed}: ${error || 'still present after removal'}`);
    else {
      swept.removed.push(entry);
      swept.bytes += bytes;
    }
  }
  return swept;
}

// Issue #1156: the one sweeper per run is a process that is not a `--unit`
// child — a unit is a share of its parent's run, and the parent has swept.
// Before the root exists, so a run never judges its own; on stderr, so stdout
// is the same text whatever `tmpdir()` held (`TY28`, `TY33`); silent when
// nothing was stale.
if (UNIT === null) {
  const swept = sweepStaleRoots(SYSTEM_TEMP, Date.now(), STALE_ROOT_AGE_HOURS * 3600 * 1000);
  if (swept.removed.length > 0) {
    console.error(
      `selftest: removed ${swept.removed.length} rigc-selftest- root(s) untouched for more than ${STALE_ROOT_AGE_HOURS} h from ${SYSTEM_TEMP}, ` +
        `${(swept.bytes / 1048576).toFixed(1)} MB of files, left by runs killed by a signal`,
    );
  }
  for (const failure of swept.failed) console.error(`selftest: could not remove a stale rigc-selftest- root, ${failure}`);
}

/**
 * The one directory this process makes under `tmpdir()` (issue #1137):
 * `rigc-selftest-XXXXXX`, made on first use, and every temp directory the
 * harness makes is made inside it under its own prefix — so a path still
 * spells `rigc-static-XXXXXX` where a control reads it, and a site cannot leak
 * by forgetting its `rmSync`. Removed once, when the process exits, on every
 * way it exits: a return from `main`, every `process.exit` (the floor's 2, a
 * partial run's 2, a red run's 1, a refused flag after the root exists) and
 * an uncaught throw. `--keep-temp` keeps it and names it on stderr instead, so
 * stdout is the same text either way.
 *
 * ⚠️ A run killed by a signal leaves its root: one directory, where it used to
 * leave every site's. Catching the signal to remove it was measured and
 * rejected — `main` is synchronous, so a JavaScript handler runs only after it
 * returns: a `--only path-slider` run sent SIGTERM mid-suite went on to the
 * end of its suite and exited 2, where without the handler it stopped
 * at once (143).
 *
 * ⚠️ Only this process's own directories live here. A child it starts — a
 * tool, the CLI, another selftest — makes its directories where its own
 * `tmpdir()` says, which this process does not redirect: a child that leaks is
 * a fault of that command, and `TY39`'s count of a child run is how it shows.
 */
function harnessTemp(): string {
  if (harnessTempRoot === null) {
    const root = mkdtempSync(join(SYSTEM_TEMP, 'rigc-selftest-'));
    harnessTempRoot = root;
    process.on('exit', () => {
      if (KEEP_TEMP) console.error(`selftest: --keep-temp kept this process's temp root: ${root}`);
      else rmSync(root, { recursive: true, force: true });
    });
  }
  return harnessTempRoot;
}

/** The `rigc-*` entries directly inside `dir`, by prefix — the name less the six characters `mkdtemp` appends (issue #1137, `TY39`). */
function tempCensus(dir: string): Map<string, number> {
  const counts = new Map<string, number>();
  for (const name of readdirSync(dir).sort()) {
    if (!name.startsWith('rigc-')) continue;
    const prefix = /^(.*-)[A-Za-z0-9]{6}$/.exec(name)?.[1] ?? name;
    counts.set(prefix, (counts.get(prefix) ?? 0) + 1);
  }
  return counts;
}

/** Every prefix that has more entries `after` than `before`, as `<prefix> +<n>`, in prefix order. */
function tempGrowth(before: ReadonlyMap<string, number>, after: ReadonlyMap<string, number>): string[] {
  return [...after]
    .filter(([prefix, count]) => count > (before.get(prefix) ?? 0))
    .sort(([a], [b]) => (a < b ? -1 : 1))
    .map(([prefix, count]) => `${prefix} +${count - (before.get(prefix) ?? 0)}`);
}

/** One independent unit of a suite: a command, the directory it runs from, and the output its sequential call could hold. */
interface ParallelUnit {
  argv: readonly string[];
  cwd: string;
  /** The `maxBuffer` the unit's sequential `spawnSync` was given; past it the two paths would differ, so it is refused. */
  maxBuffer?: number;
  /**
   * What the suite line calls this unit when it is the heaviest (issue #1143).
   * Deterministic text: absent, it is the script's file name, the word after
   * it and the unit's place in its batch (`unitLabel`), which no temp
   * directory's name can reach.
   */
  label?: string;
}

/**
 * What one unit left: what `spawnSync` would have handed back, and what the
 * driver read of the child (issue #1143) — its peak resident set in BYTES,
 * normalised by the factor its driver's calibration child read through the
 * same call (`spawnMaxRssScale`, carried as `scale`), and its seconds.
 * `peakBytes` and `scale` are `null` on the sequential path (`--jobs 1`, or a
 * batch of one): `spawnSync` hands back no resource usage, so that child's
 * peak is not read rather than guessed — and `null` too when the calibration
 * read neither unit.
 */
interface UnitResult {
  status: number | null;
  stdout: string;
  stderr: string;
  peakBytes: number | null;
  scale: 1 | 1024 | null;
  /** What the driver's calibration child read, or `null` on the sequential path and from a driver that wrote none. */
  calibration: UnitCalibration | null;
  seconds: number;
}

/**
 * One measured child of the run (issue #1143): its label and its peak, as
 * `inParallel` took them. `UNIT_PEAKS_TAKEN` holds every one in the order the
 * run took them, and `RunTally.of` reads the ones a suite's call added — which
 * is how the suite line names its heaviest unit with no call site having to
 * remember to report one.
 */
interface UnitPeak {
  label: string;
  peakBytes: number;
  /** The factor the raw `maxRSS` was multiplied by, as the driver's calibration read it. */
  scale: 1 | 1024;
  seconds: number;
}

/** Every child this process measured, in the order it measured them — appended by `inParallel`, read by `RunTally.of` (issue #1143). */
const UNIT_PEAKS_TAKEN: UnitPeak[] = [];

/**
 * The factor that turns a process's OWN `process.resourceUsage().maxRSS` into
 * bytes, read off that same process (issue #1143): `1` when the reading is
 * bytes, `1024` when it is KiB, `null` when it is neither. It is for a process
 * reading itself and for nothing else — a `--unit` child's peak, which the
 * driver reads through another API, is scaled by `spawnMaxRssScale`.
 *
 * ⚠️ There are two APIs and they do not agree on every platform:
 * - `process.resourceUsage().maxRSS` (the Node API, a process reading itself):
 *   bytes on darwin, measured (a `bun -e` child that touched 64 MiB read
 *   92,864,512 beside an `rss` of 92,880,896; Bun 1.3.11) — and KiB on Linux,
 *   as Node documents it and CI showed (below).
 * - `Bun.spawn(...).resourceUsage().maxRSS` (Bun's API, a parent reading a
 *   child that exited): bytes on darwin, measured (the same child read
 *   93,175,808 — 300-odd KiB above its own last reading, the exit's tail) —
 *   and bytes on Linux, which CI showed.
 *
 * On darwin both are bytes, so nothing measured there could tell them apart.
 * PR #1145 scaled every child by the DRIVER's own Node reading, and on Linux
 * CI the suite lines printed `core` children high-water 736924 MB: a ~720 MB
 * worker read in bytes and multiplied by the 1024 the driver's KiB reading
 * asked for. The rule since: a figure's unit is read through the call that
 * produced the figure, never through a neighbour.
 *
 * Here the unit is decided by the reading itself, a process's own `maxRSS`
 * beside its own `process.memoryUsage().rss`, which is bytes on every
 * platform. A peak is never below the resident set it peaked over, and the two
 * candidate units are 1024 apart, so the ratio's distance from 1 decides it at
 * the geometric middle, 32. (Not exactly 1: on darwin a fresh process read
 * `maxRSS` 21,725,184 beside an `rss` of 21,741,568 — the peak is refreshed
 * lazily — so the reading is a ratio, never an inequality.)
 */
function maxRssScale(rawMaxRss: number, rssBytes: number): 1 | 1024 | null {
  if (!(rawMaxRss > 0) || !(rssBytes > 0)) return null;
  const ratio = rssBytes / rawMaxRss;
  if (ratio < 32 && ratio > 1 / 32) return 1;
  if (ratio / 1024 < 32 && ratio / 1024 > 1 / 32) return 1024;
  return null;
}

/**
 * What the unit driver's calibration child allocates and touches before the
 * driver's first unit (issue #1143): 64 MiB, enough that a `bun -e` process's
 * own load (22 MB on darwin, measured) cannot carry the reading out of its
 * window, and small enough to cost the driver ~11 ms (darwin, measured).
 */
const CALIBRATION_BYTES = 64 * 1024 * 1024;

/**
 * What the driver read of its calibration child: the bytes it was asked to
 * hold, the `maxRSS` `Bun.spawn`'s `resourceUsage()` reported for it (`null`
 * when the child failed or no usage came back), its exit, and what it cost.
 */
interface UnitCalibration {
  bytes: number;
  maxRss: number | null;
  exit: number | null;
  ms: number;
}

/**
 * The factor that turns `Bun.spawn(...).resourceUsage().maxRSS` into bytes,
 * read through that same call (issue #1143): the driver's calibration child
 * held `bytes` and reported `maxRss`, and a peak is never below what the
 * process touched, so in bytes the ratio `maxRss / bytes` is at least 1, in
 * KiB at least 1/1024 — the two windows 1,024 apart and split at their
 * geometric middle, 1/32: `[1, 32)` is bytes, `[1/1024, 1/32)` is KiB, and
 * anything else (a ratio under 1/1024, one in `[1/32, 1)` — a peak below the
 * allocation, which no unit reads — or one 32 times the allocation) is
 * neither, `null` with the reason, never a guess. Measured on darwin: 64 MiB
 * read 93,126,656–93,208,576 (ratio 1.388–1.389), 256 MiB 294,518,784–
 * 294,535,168 (1.097). The driver's own `process.resourceUsage()` is not
 * consulted: that is the Node API, and it is the one that differs (see
 * `maxRssScale`).
 */
function spawnMaxRssScale(calibration: UnitCalibration | undefined): { scale: 1 | 1024 | null; why: string } {
  if (calibration === undefined) return { scale: null, why: 'the driver wrote no calibration, so no child of it has a unit' };
  const { bytes, maxRss, exit } = calibration;
  if (maxRss === null || !(maxRss > 0) || !(bytes > 0)) {
    return { scale: null, why: `the calibration child holding ${bytes} bytes exited ${String(exit)} and reported maxRSS ${String(maxRss)}, so its unit is not read` };
  }
  const ratio = maxRss / bytes;
  if (ratio >= 1 && ratio < 32) return { scale: 1, why: `the calibration child holding ${bytes} bytes reported maxRSS ${maxRss}: bytes (ratio ${ratio.toFixed(4)})` };
  if (ratio >= 1 / 1024 && ratio < 1 / 32) return { scale: 1024, why: `the calibration child holding ${bytes} bytes reported maxRSS ${maxRss}: KiB (ratio ${ratio.toFixed(6)})` };
  return { scale: null, why: `the calibration child holding ${bytes} bytes reported maxRSS ${maxRss} (ratio ${ratio.toFixed(6)}), inside neither bytes' window [1, 32) nor KiB's [1/1024, 1/32)` };
}

/**
 * What a unit is called with no `label` of its own: its script, the command
 * word after it, and its place in the batch — `render_hashes.ts base, unit 1
 * of 8` — all read off the command and none off a path, so no temp directory's
 * name reaches the line. Inline code (`bun -e …`) is called `bun -e`, never by
 * its text.
 */
function unitLabel(unit: ParallelUnit, k: number, of: number): string {
  if (unit.label !== undefined) return unit.label;
  const inline = unit.argv[1] === '-e';
  const script = inline ? 'bun -e' : unit.argv[1] === undefined ? basename(unit.argv[0] ?? '?') : basename(unit.argv[1]);
  const after = unit.argv[2];
  const word = !inline && after !== undefined && /^[A-Za-z][\w-]*$/.test(after) ? ` ${after}` : '';
  return `${script}${word}, unit ${k + 1} of ${of}`;
}

/** `spawnSync`'s own default `maxBuffer`, which every sequential call here that names none was held to. */
const SPAWN_MAX_BUFFER = 1024 * 1024;

/**
 * The argument every `bun -e <source>` call here that hands its program
 * arguments passes first, before them (issue #1482). Bun 1.2.0 (then the declared
 * minimum) puts `[eval]` in `process.argv[1]` and so loses the first argument
 * after the source (measured: `bun -e … a b` reads `[bun, …/[eval], b]` there and
 * `[bun, a, b]` on the current Bun). With this one first, the arguments the
 * program reads sit from `process.argv[2]` on both, so every such program reads
 * `process.argv.slice(2)` or the last element, never `process.argv[1]`.
 */
const EVAL_ARGV_SLOT = '[eval]';

/**
 * `process.resourceUsage`, or `null` on a Bun that has none (issue #1482):
 * measured absent on Bun 1.2.0 (then the declared minimum), where a child's
 * `resourceUsage()` from `Bun.spawn` is there. A process that cannot read its
 * own peak reports none (`null`) rather than a figure, and a control that has
 * to read it says it did not (`TY40`).
 */
const PROCESS_RESOURCE_USAGE: (() => { maxRSS: number }) | null = ((): (() => { maxRSS: number }) | null => {
  const runtime: { resourceUsage?: () => { maxRSS: number } } = process;
  const read = runtime.resourceUsage;
  return read === undefined ? null : () => read.call(process);
})();

/**
 * The child that runs a batch of units concurrently (issue #1128). This file is
 * synchronous from `main` down — every suite returns its count, and `tally.of`
 * brackets a call — so the one way to wait on several processes from inside a
 * suite is to wait on ONE process that waits on them: `inParallel` starts this
 * with `spawnSync`, it starts up to `jobs` units with `Bun.spawn`, takes each
 * unit's stdout, stderr, exit and peak RSS, and writes them in the units' order
 * to the file its spec names. Plain JavaScript, because `bun -e` reads it.
 */
const UNIT_DRIVER = [
  'const spec = JSON.parse(await Bun.file(process.argv[process.argv.length - 1]).text());',
  // Issue #1143: the unit of a child's `maxRSS` is read through the call that
  // reads the children — `Bun.spawn`'s `resourceUsage()` — off one child that
  // holds a stated amount, once per driver and before its first unit, and
  // handed back beside every unit's figure (`spawnMaxRssScale` decides it).
  // A spec with no `calibrationBytes` gets no calibration, and then the parent
  // reads no child's peak rather than assuming a unit.
  'let calibration;',
  "if (typeof spec.calibrationBytes === 'number') {",
  '  const began = performance.now();',
  "  const hold = 'const b = Buffer.alloc(' + spec.calibrationBytes + '); let t = 0; for (let i = 0; i < b.length; i += 4096) { b[i] = 1; t += b[i]; } if (t !== Math.ceil(b.length / 4096)) process.exit(3);';",
  "  const child = Bun.spawn([process.execPath, '-e', hold], { stdin: 'ignore', stdout: 'ignore', stderr: 'pipe' });",
  '  await new Response(child.stderr).text();',
  '  await child.exited;',
  '  const usage = child.resourceUsage();',
  '  calibration = { bytes: spec.calibrationBytes, maxRss: child.exitCode === 0 && usage !== undefined ? Number(usage.maxRSS) : null, exit: child.exitCode, ms: performance.now() - began };',
  '}',
  'const results = new Array(spec.units.length);',
  'let next = 0;',
  'const lane = async () => {',
  '  while (next < spec.units.length) {',
  '    const k = next++;',
  '    const unit = spec.units[k];',
  '    const began = performance.now();',
  "    const child = Bun.spawn(unit.argv, { cwd: unit.cwd, stdin: 'ignore', stdout: 'pipe', stderr: 'pipe' });",
  '    const [stdout, stderr] = await Promise.all([new Response(child.stdout).text(), new Response(child.stderr).text()]);',
  '    await child.exited;',
  '    const usage = child.resourceUsage();',
  '    const ended = performance.now();',
  '    results[k] = { status: child.exitCode, stdout, stderr, maxRss: usage === undefined ? null : Number(usage.maxRSS), calibration, seconds: (ended - began) / 1000, began: began / 1000, ended: ended / 1000 };',
  '  }',
  '};',
  'await Promise.all(Array.from({ length: Math.min(spec.jobs, spec.units.length) }, lane));',
  'await Bun.write(spec.out, JSON.stringify(results));',
].join('\n');

/**
 * Run a suite's independent units, up to `jobs` at once, and hand back what
 * each left in the units' own order (issue #1128).
 *
 * 🔒 Why the log cannot interleave: a unit prints nothing to this process — its
 * stdout and stderr come back as values — and the caller prints its case lines
 * only after this returns, which is after EVERY unit has finished, in the order
 * its sequential code already prints them. So `jobs` decides when a unit ran and
 * never what anybody printed. ⚠️ The caller's half of that is to hand over only
 * units whose result does not depend on another unit having run first — each in
 * its own work directory, none reading what another writes — which is the
 * condition `inParallel` cannot check and the call sites state.
 *
 * `jobs` 1, or one unit, is the sequential path: `spawnSync` per unit, in
 * order, exactly the call each site made before. Above that one driver child
 * runs them (`UNIT_DRIVER`), and every unit's peak RSS, as the driver read it of
 * the child, comes back in its result and is appended to `UNIT_PEAKS_TAKEN`
 * (issue #1143) — the reading the parent's own column cannot take (`TY26`
 * reads this process), which the suite's line states as its children's
 * high-water and `TY40` holds under the platform's base. No flag asks for it.
 *
 * `RIGC_UNIT_PEAKS=<file>` stays as the per-unit JOURNAL: one line per unit
 * with its command, peak, seconds and when in the batch it started and ended.
 * The log carries one figure per suite — the largest child and its name —
 * because a line per unit would print 100-odd figures that differ run to run;
 * the journal is where the overlap of a batch's children is read from
 * (the sum alive at once, which the log does not state — see `TY40`).
 */
// `driverSource` is `UNIT_DRIVER` everywhere but `TY33`, which hands in the
// plant — a driver that interleaves its units' lines — to see it read.
function inParallel(units: readonly ParallelUnit[], jobs: number = JOBS, driverSource: string = UNIT_DRIVER): UnitResult[] {
  if (jobs < 1 || !Number.isInteger(jobs)) throw new Error(`inParallel: jobs ${jobs} is not a whole number from 1`);
  if (jobs === 1 || units.length <= 1) {
    return units.map((unit) => {
      const began = performance.now();
      const result = spawnSync(unit.argv[0], unit.argv.slice(1), { cwd: unit.cwd, encoding: 'utf8', maxBuffer: unit.maxBuffer ?? SPAWN_MAX_BUFFER });
      return { status: result.status, stdout: result.stdout, stderr: result.stderr, peakBytes: null, scale: null, calibration: null, seconds: (performance.now() - began) / 1000 };
    });
  }
  const dir = mkdtempSync(join(harnessTemp(), 'rigc-selftest-units-'));
  try {
    const specPath = join(dir, 'units.json');
    const out = join(dir, 'results.json');
    writeFileSync(specPath, JSON.stringify({ jobs, out, calibrationBytes: CALIBRATION_BYTES, units: units.map((unit) => ({ argv: unit.argv, cwd: unit.cwd })) }));
    const driver = spawnSync(process.execPath, ['-e', driverSource, EVAL_ARGV_SLOT, specPath], { encoding: 'utf8' });
    if (driver.status !== 0 || !existsSync(out)) {
      throw new Error(`inParallel: the unit driver exited ${String(driver.status)} over ${units.length} unit(s) and wrote ${existsSync(out) ? 'its results' : 'nothing'}: ${driver.stderr.trim().slice(0, 300)}`);
    }
    // What the driver wrote per unit. Every field past the three `spawnSync`
    // would hand back is optional: `TY33`'s planted driver writes none of them,
    // and a unit with no reading is a unit whose peak is not known, never 0.
    const results = JSON.parse(readFileSync(out, 'utf8')) as Array<{
      status: number | null;
      stdout: string;
      stderr: string;
      maxRss?: number | null;
      calibration?: UnitCalibration;
      seconds?: number;
      began?: number;
      ended?: number;
    }>;
    const peaks = process.env.RIGC_UNIT_PEAKS;
    return results.map((result, k) => {
      const unit = units[k];
      const limit = unit.maxBuffer ?? SPAWN_MAX_BUFFER;
      for (const [stream, text] of [['stdout', result.stdout], ['stderr', result.stderr]] as const) {
        const bytes = Buffer.byteLength(text, 'utf8');
        if (bytes > limit) {
          throw new Error(
            `inParallel: unit ${k} (${unit.argv.slice(1, 4).join(' ')} …) wrote ${bytes} byte(s) to ${stream}, past the ${limit} its sequential spawnSync allowed — ` +
              '--jobs 1 would have cut it off and this path would not, so the two runs would differ',
          );
        }
      }
      // The scale comes from the calibration this driver read through the
      // call that read the unit; a calibration that read neither unit leaves
      // the peak unread (the journal says why) rather than guessed.
      const { scale, why } = spawnMaxRssScale(result.calibration);
      const peakBytes = typeof result.maxRss === 'number' && scale !== null ? result.maxRss * scale : null;
      const seconds = result.seconds ?? 0;
      const label = unitLabel(unit, k, units.length);
      if (peakBytes !== null && scale !== null) UNIT_PEAKS_TAKEN.push({ label, peakBytes, scale, seconds });
      if (peaks !== undefined && peaks !== '') {
        appendFileSync(
          peaks,
          `${JSON.stringify({ jobs, unit: k, of: units.length, label, argv: unit.argv.slice(1).map((a) => basename(a)).join(' '), maxRss: result.maxRss ?? null, calibration: result.calibration ?? null, scale, why, peakBytes, seconds, began: result.began ?? null, ended: result.ended ?? null })}\n`,
        );
      }
      return { status: result.status, stdout: result.stdout, stderr: result.stderr, peakBytes, scale, calibration: result.calibration ?? null, seconds };
    });
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

function optsForCut(dir: string, entry: CutEntry): Options {
  const opts: Options = {
    rigPath: resolve(dir, entry.rig),
    motionPath: resolve(dir, entry.motion),
    outDir: resolve(dir, entry.out),
  };
  if (entry.manifest !== undefined) opts.manifestPath = resolve(dir, entry.manifest);
  if (entry.images !== undefined) opts.imagesDir = resolve(dir, entry.images);
  return opts;
}

function optsForFixture(fixture: Fixture): Options {
  return {
    rigPath: fixture.rigPath,
    motionPath: fixture.motionPath,
    outDir: fixture.outDir,
    manifestPath: fixture.manifestPath,
  };
}

/**
 * A fresh directory for a build to land in, made INSIDE the directory its art
 * lives in (issue #1127) — `<artDir>/<prefix>XXXXXX` — so a build of a fixture
 * or a probe never spells another temp directory's name.
 *
 * ⭐ Why it has to be inside, measured rather than tidy: a page name is the art's
 * path seen from the atlas file (`relative(outDir, …)` in `src/compile.ts`), and
 * so are `skeleton.images` and the model document's `pages`. A build whose
 * output directory sat in a temp directory of its own, beside the art's, wrote
 * `../../rigc-fixtures-XXXXXX/…` into all three — a name chosen at random by
 * whichever process made the directory. `VF09` keys a build on those texts, so
 * one set of inputs counted once per directory it was built from. From inside,
 * the spelling is `../../plates/x.png` wherever the fixture root is — the way
 * `tools/emit_hashes.ts` stages a recipe.
 *
 * 🔒 The prefix is a NAME, never a path: one carrying a separator could put the
 * root anywhere, and is refused by name before anything is made (`TY37`).
 */
function buildRootIn(artDir: string, prefix: string): string {
  if (prefix === '' || /[\\/]/.test(prefix)) {
    throw new Error(`buildRootIn: the prefix ${JSON.stringify(prefix)} is not a plain directory name, so the build root it makes need not be inside ${artDir}`);
  }
  return mkdtempSync(join(artDir, prefix));
}

/**
 * `buildRootIn(home, prefix)` where the art has a home this run made, and a temp directory of its own where it has none —
 * the art is the checkout's (a gallery example, the corpus), which no build here writes into.
 */
function buildRootFor(home: string | undefined, prefix: string): string {
  return home === undefined ? mkdtempSync(join(harnessTemp(), prefix)) : buildRootIn(home, prefix);
}

/** The static probe's motion spec (`STATIC_MOTION`) written beside a probe's rig, and its path — what `gateProbe` writes. */
function staticMotionIn(dir: string): string {
  const motionPath = join(dir, 'probe.motion.json');
  writeFileSync(motionPath, `${JSON.stringify(STATIC_MOTION, null, 2)}\n`);
  return motionPath;
}

/** The four fields a setup stage is, as the editor and `compile` write them. */
const STAGE_BOX_FIELDS = ['x', 'y', 'width', 'height'] as const;

/**
 * A fixture's options with its rig spec copied into `root` stating that the
 * skeleton declares no stage — `"width": null, "height": null` — and nothing
 * else changed. The manifest stays where it is, so every part resolves exactly
 * as the fixture's own build does and the crop is still there to be beaten.
 */
function stagelessOptionsFor(fixture: Fixture, root: string, outName: string): Options {
  const rig = JSON.parse(readFileSync(fixture.rigPath, 'utf8')) as Record<string, unknown>;
  const header = (rig.skeleton ?? {}) as Record<string, unknown>;
  rig.skeleton = { ...header, width: null, height: null };
  const rigPath = join(root, `${basename(fixture.rigPath, '.rig.json')}.stageless.rig.json`);
  writeFileSync(rigPath, `${JSON.stringify(rig, null, 2)}\n`);
  const outDir = join(root, outName);
  mkdirSync(outDir, { recursive: true });
  return { ...optsForFixture(fixture), rigPath, outDir };
}

/** A skeleton's text with every stage field taken out of its header — the shape issue #714 counts in production. */
function withoutStageBox(skeletonText: string): string {
  const root = JSON.parse(skeletonText) as { skeleton?: Record<string, unknown> };
  for (const field of STAGE_BOX_FIELDS) delete root.skeleton?.[field];
  return `${JSON.stringify(root, null, 2)}\n`;
}

/** Which of the four stage fields a skeleton's header states as numbers. */
function stageFieldsOf(skeletonText: string): string[] {
  const header = ((JSON.parse(skeletonText) as { skeleton?: Record<string, unknown> }).skeleton ?? {}) as Record<string, unknown>;
  return STAGE_BOX_FIELDS.filter((field) => typeof header[field] === 'number');
}

/**
 * The overlay fixture: a base plate, two slots that fade, and one ring mesh.
 * Everything the region, timeline, atlas, mesh and physics assertions look at.
 */
// The fixtures live in this process's run root, which the exit removes (issue #1137).
placeFixturesUnder(harnessTemp());
const OVERLAY = overlayFixture();
/**
 * The articulated fixture. Its invariants live on bones the overlay rig does not
 * have — an axis, a detached emitter, a grip ring, a bone chain — so they need
 * their own artifacts to break. Same discipline, second suite.
 */
const ARTICULATED = articulatedFixture();
/**
 * The third fixture earns its place the way its predecessor did, and not by
 * symmetry: it is the only one that declares a cap-containment ceiling, so A30 is
 * VACUOUS on the other two and a break there would be caught by nothing; and it
 * is the only one whose manifest names a slot something other than the rig does,
 * so the mapping that resolves that is worth a break of its own.
 */
const CONTAINED = containedFixture();

// ---------------------------------------------------------------------------
// locating things inside an artifact, so no mutant hardcodes a measured number
// ---------------------------------------------------------------------------

/**
 * Start index of each vertex's run inside a weighted `vertices` array.
 *
 * ⚠️ The encoding is `boneCount, (boneIndex, bindX, bindY, weight) × n` repeated,
 * with no marker and no fixed stride — so a mutant that wants "the first weight
 * of the second vertex" has to walk the run to find it. Writing the index as a
 * literal is how a suite comes to depend on one fixture's exact geometry.
 */
function weightRuns(vertices: number[]): number[] {
  const out: number[] = [];
  for (let i = 0; i < vertices.length; ) {
    out.push(i);
    i += 1 + vertices[i] * 4;
  }
  return out;
}

/** Index of the first vertex bound to more than one bone — the first one that moves. */
function firstBlendedRun(vertices: number[]): number {
  const runs = weightRuns(vertices);
  const at = runs.find((start) => vertices[start] > 1);
  if (at === undefined) throw new Error('the fixture mesh has no multi-bone vertex to re-weight');
  return at;
}

/** The first page line of an atlas: a path on a line of its own. */
function firstPageLine(atlasText: string): string {
  const line = atlasText.split('\n').find((l) => l.endsWith('.png'));
  if (!line) throw new Error('the fixture atlas declares no page');
  return line;
}

/**
 * The atlas with the pages `pick` chooses moved off the disk, and the names
 * they were moved to (issue #1055). A page line is the first line of a page
 * block; it is moved into a directory that is not there with its basename
 * kept, so the file is not on disk while its basename is untouched. `pick` sees
 * the block's lines, so a caller chooses a page by what the block states rather
 * than by position.
 */
function atlasWithPagesOffDisk(atlasText: string, pick: (block: readonly string[]) => boolean): { atlasText: string; moved: string[] } {
  const moved: string[] = [];
  const blocks = atlasText.split('\n\n').map((block) => {
    const lines = block.split('\n');
    if (lines[0] === '' || !pick(lines)) return block;
    lines[0] = lines[0].replace(/[^/]*$/, (base) => `not_on_disk/${base}`);
    moved.push(lines[0]);
    return lines.join('\n');
  });
  if (moved.length === 0) throw new Error('the fixture atlas has no page block the mutant picks');
  return { atlasText: blocks.join('\n\n'), moved };
}

/**
 * The atlas with the pages `pick` chooses replaced, on disk, by bytes rigc
 * cannot read as a PNG (issue #1064) — `atlasWithPagesOffDisk`'s other half.
 * Each chosen page is moved into a directory `unreadable_<tag>/` beside its
 * file, with its basename kept, and the file
 * written there is `bytes` of the real page: the page is on disk (`A17` has
 * nothing to say) and is not a PNG this tree can read.
 */
function atlasWithPagesUnreadable(
  atlasText: string,
  atlasDir: string,
  tag: string,
  bytes: (png: Uint8Array) => Uint8Array,
  pick: (block: readonly string[]) => boolean,
): { atlasText: string; moved: string[] } {
  return atlasWithPageBytes(atlasText, atlasDir, `unreadable_${tag}`, bytes, pick);
}

/**
 * `atlasWithPagesUnreadable` with the directory named by the caller — for an
 * edit that leaves the page readable (issue #1074's tolerance), which a
 * directory called `unreadable_` would misdescribe.
 */
function atlasWithPageBytes(
  atlasText: string,
  atlasDir: string,
  dir: string,
  bytes: (png: Uint8Array) => Uint8Array,
  pick: (block: readonly string[]) => boolean,
): { atlasText: string; moved: string[] } {
  const moved: string[] = [];
  const blocks = atlasText.split('\n\n').map((block) => {
    const lines = block.split('\n');
    if (lines[0] === '' || !pick(lines)) return block;
    const was = lines[0];
    lines[0] = was.replace(/[^/]*$/, (base) => `${dir}/${base}`);
    const target = resolve(atlasDir, lines[0]);
    mkdirSync(dirname(target), { recursive: true });
    writeFileSync(target, bytes(readFileSync(resolve(atlasDir, was))));
    moved.push(lines[0]);
    return lines.join('\n');
  });
  if (moved.length === 0) throw new Error('the fixture atlas has no page block the mutant picks');
  return { atlasText: blocks.join('\n\n'), moved };
}

/** Text where a PNG should be: no signature at all (issue #1064's first state). */
const notAPng = (): Uint8Array => new TextEncoder().encode('this page is text, not an image\n');

/**
 * The page cut halfway through its first IDAT chunk's data (issue #1064's
 * second state): the signature and IHDR intact, the pixel data short. The cut
 * is placed by the file's own chunk walk, not at a byte count typed here.
 */
function cutInsideFirstIdat(png: Uint8Array): Uint8Array {
  const view = new DataView(png.buffer, png.byteOffset, png.byteLength);
  for (let at = PNG_SIGNATURE.length; at + 8 <= png.length; ) {
    const length = view.getUint32(at);
    if (String.fromCharCode(png[at + 4], png[at + 5], png[at + 6], png[at + 7]) === 'IDAT') return png.slice(0, at + 8 + Math.floor(length / 2));
    at += 12 + length;
  }
  throw new Error('the fixture page has no IDAT chunk to cut');
}

/** A PNG's chunks as the file's own walk finds them: type and data. */
function pngChunks(png: Uint8Array): Array<{ type: string; body: Uint8Array }> {
  const view = new DataView(png.buffer, png.byteOffset, png.byteLength);
  const out: Array<{ type: string; body: Uint8Array }> = [];
  for (let at = PNG_SIGNATURE.length; at + 8 <= png.length; ) {
    const length = view.getUint32(at);
    const type = String.fromCharCode(png[at + 4], png[at + 5], png[at + 6], png[at + 7]);
    // A copy, not `slice`: on a `Buffer` that is a view into a shared pool, and an edit would land outside the chunk.
    out.push({ type, body: new Uint8Array(png.subarray(at + 8, at + 8 + length)) });
    if (type === 'IEND') break;
    at += 12 + length;
  }
  return out;
}

/** The PNG rebuilt from `chunks`, every CRC computed — so the only thing wrong with an edited file is the edit. */
function pngOfChunks(chunks: ReadonlyArray<{ type: string; body: Uint8Array }>): Uint8Array {
  const parts = [PNG_SIGNATURE, ...chunks.map((c) => pngChunk(c.type, c.body))];
  const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
  let at = 0;
  for (const p of parts) {
    out.set(p, at);
    at += p.length;
  }
  return out;
}

/**
 * The page with its IHDR width (`axis` 0) or height (`axis` 1) stated as 0
 * and the CRC recomputed (issue #1073): every chunk intact, and the file a PNG
 * of no texels, which the format forbids.
 */
function zeroDimension(axis: 0 | 1): (png: Uint8Array) => Uint8Array {
  return (png) =>
    pngOfChunks(
      pngChunks(png).map((c) => {
        if (c.type !== 'IHDR') return c;
        const body = c.body.slice();
        new DataView(body.buffer).setUint32(axis * 4, 0);
        return { ...c, body };
      }),
    );
}

/**
 * The page with the second half of its first IDAT's data inverted and the
 * chunk's CRC recomputed (issue #1074): the signature, IHDR, the chunk walk
 * and the zlib header intact, the compressed stream past them broken. The
 * half is found by the file's own walk, not typed here.
 */
function brokenStream(png: Uint8Array): Uint8Array {
  let first = true;
  return pngOfChunks(
    pngChunks(png).map((c) => {
      if (c.type !== 'IDAT' || !first) return c;
      first = false;
      const body = c.body.slice();
      for (let i = body.length >> 1; i < body.length; i++) body[i] ^= 0xff;
      return { ...c, body };
    }),
  );
}

/**
 * The page with its compressed stream re-cut into three IDAT chunks, every
 * CRC computed (issue #1074's tolerance): a legal file holding the same image
 * — the format makes the stream the concatenation of every IDAT — which a
 * stream check that inflated one chunk alone would refuse.
 */
function streamInThreeIdats(png: Uint8Array): Uint8Array {
  const chunks = pngChunks(png);
  const data = chunks.filter((c) => c.type === 'IDAT').map((c) => c.body);
  const stream = new Uint8Array(data.reduce((n, d) => n + d.length, 0));
  let at = 0;
  for (const d of data) {
    stream.set(d, at);
    at += d.length;
  }
  const firstIdat = chunks.findIndex((c) => c.type === 'IDAT');
  if (firstIdat < 0 || stream.length < 3) throw new Error('the fixture page has no stream to re-cut');
  const third = Math.ceil(stream.length / 3);
  const idats = [0, 1, 2].map((i) => ({ type: 'IDAT', body: stream.slice(i * third, (i + 1) * third) }));
  return pngOfChunks([...chunks.slice(0, firstIdat), ...idats, ...chunks.filter((c, i) => i > firstIdat && c.type !== 'IDAT')]);
}

/**
 * What the report must print on a build whose pages in `moved` are on disk and
 * cannot be read as PNG (issue #1064): A06 FAILs once per page naming it, A17
 * PASSes (every file is there), A19 raises no failure and SKIPs with a reason
 * carrying `a19` and pointing at A06 — and each moved page is named by exactly
 * one failure line of the whole report, A06's, whose subject the file is.
 */
function pagesUnreadableHold(report: ValidateReport, moved: readonly string[], a19: string): { held: boolean; read: string } {
  const A06 = 'A06_ATLAS_PAGE_SIZE_MATCHES_PNG';
  const A19 = 'A19_OVERLAY_PNGS_HAVE_ALPHA';
  const reasonOf = (code: string): string => report.skipped.find((s) => s.assertion === code)?.reason ?? '';
  const verdictOf = (code: string): string =>
    report.passed.includes(code) ? 'PASS' : report.failures.some((f) => f.assertion === code) ? 'FAIL' : reasonOf(code) !== '' ? 'SKIP' : 'nothing';
  const namings = moved.map((name) => report.failures.filter((f) => f.detail.includes(`"${name}"`)));
  const a06 = report.failures.filter((f) => f.assertion === A06);
  const held =
    verdictOf(A19) === 'SKIP' &&
    reasonOf(A19).includes(a19) &&
    reasonOf(A19).includes(A06) &&
    verdictOf('A17_ATLAS_PAGE_FILES_EXIST') === 'PASS' &&
    a06.length === moved.length &&
    a06.every((f) => f.detail.includes('cannot be read as PNG')) &&
    namings.every((lines) => lines.length === 1 && lines[0].assertion === A06);
  return {
    held,
    read:
      `${moved.length} page(s) unreadable on disk; A06 failed ${a06.length} time(s); A17 ${verdictOf('A17_ATLAS_PAGE_FILES_EXIST')}; ` +
      `each page named by [${namings.map((lines) => lines.map((f) => f.assertion.slice(0, 3)).join('+') || 'nothing').join(', ')}]; ` +
      `A19 ${verdictOf(A19)}: ${reasonOf(A19)}`,
  };
}

/** M12d/M12e's break: the first page block that is not the base plate's, made unreadable on disk. */
function unreadableFirstPartPage(a: Artifacts, atlasDir: string, tag: string, bytes: (png: Uint8Array) => Uint8Array): { atlasText: string; moved: string[] } {
  return firstPartPageAs(a, atlasDir, `unreadable_${tag}`, bytes);
}

/** The first page block that is not the base plate's, rewritten as `bytes` of itself under `dir/`. */
function firstPartPageAs(a: Artifacts, atlasDir: string, dir: string, bytes: (png: Uint8Array) => Uint8Array): { atlasText: string; moved: string[] } {
  const base = coversTheStage(a.atlasText);
  let first = true;
  return atlasWithPageBytes(a.atlasText, atlasDir, dir, bytes, (block) => {
    if (!first || base(block)) return false;
    first = false;
    return true;
  });
}

/** M12d/M12e's reading: the moved page named once, by A06, and A19's SKIP counted off the broken atlas. */
function unreadableFirstPartPageHold(report: ValidateReport, broken: Artifacts, tag: string): { held: boolean; read: string } {
  const blocks = broken.atlasText.split('\n\n');
  const withParts = blocks.filter((block) => !coversTheStage(broken.atlasText)(block.split('\n'))).length;
  const moved = broken.atlasText.split('\n').filter((line) => line.includes(`/unreadable_${tag}/`));
  return pagesUnreadableHold(
    report,
    moved,
    `1 of the ${withParts} page(s) carrying a part were not read — "${moved[0]}" — because the file cannot be read as PNG`,
  );
}

/**
 * A #1064 reading, and that A06's one line about the page says `phrase` —
 * what M12f–M12h add to it: the route is #1064's, the sentence is the card's.
 */
function saidByA06(hold: { held: boolean; read: string }, report: ValidateReport, phrase: string): { held: boolean; read: string } {
  const said = report.failures.filter((f) => f.assertion === 'A06_ATLAS_PAGE_SIZE_MATCHES_PNG' && f.detail.includes(phrase)).length;
  return { held: hold.held && said === 1, read: `${hold.read}; A06 lines saying ${JSON.stringify(phrase)}: ${said}` };
}

/** Where M12i wrote its re-cut page, for its reading to open (a reading sees the report and the atlas, not the directory). */
const M12I_WRITTEN: string[] = [];

/**
 * Whether a page block holds the region that covers the skeleton's whole stage — the base plate's page (`M77`'s reading).
 *
 * ⚠️ Read off the atlas, not the header: since issue #907 the header carries the setup-pose bounding box, which on a
 * fixture whose base plate covers its crop is the stage give or take a float32 step and need not equal it. The
 * fixtures emit one part per page, and the base plate is the part as large as the crop — no part is larger — so the
 * stage-covering page is the one whose `bounds` state the largest extent of any page.
 */
function coversTheStage(atlasText: string): (block: readonly string[]) => boolean {
  const { width, height } = stageOfAtlas(atlasText);
  return (block) => block.includes(`bounds: 0, 0, ${width}, ${height}`);
}

/** A fixture's stage read off its atlas (`coversTheStage`'s reading): the largest extent any page's region states at the page origin. */
function stageOfAtlas(atlasText: string): { width: number; height: number } {
  const extents = [...atlasText.matchAll(/^\s*bounds:\s*0,\s*0,\s*(\d+),\s*(\d+)\s*$/gm)].map((m) => [Number(m[1]), Number(m[2])]);
  const [width, height] = extents.reduce((best, e) => (e[0] * e[1] > best[0] * best[1] ? e : best), [0, 0]);
  return { width, height };
}

/**
 * What `A06` and `A19` must print on a build whose pages in `moved` are not on
 * disk (issue #1055): no PASS and no FAIL of either, a SKIP whose reason
 * carries `a06`/`a19` and points at A17, and each moved page named by exactly
 * one failure line of the whole report — A17's, whose subject it is.
 */
function pagesOffDiskHold(report: ValidateReport, moved: readonly string[], a06: string, a19: string): { held: boolean; read: string } {
  const reasonOf = (code: string): string => report.skipped.find((s) => s.assertion === code)?.reason ?? '';
  const verdictOf = (code: string): string =>
    report.passed.includes(code) ? 'PASS' : report.failures.some((f) => f.assertion === code) ? 'FAIL' : reasonOf(code) !== '' ? 'SKIP' : 'nothing';
  const namings = moved.map((name) => report.failures.filter((f) => f.detail.includes(`"${name}"`)));
  const a17 = report.failures.filter((f) => f.assertion === 'A17_ATLAS_PAGE_FILES_EXIST');
  const said = (code: string, want: string): boolean =>
    verdictOf(code) === 'SKIP' && reasonOf(code).includes(want) && reasonOf(code).includes('A17_ATLAS_PAGE_FILES_EXIST');
  const held =
    said('A06_ATLAS_PAGE_SIZE_MATCHES_PNG', a06) &&
    said('A19_OVERLAY_PNGS_HAVE_ALPHA', a19) &&
    a17.length === moved.length &&
    namings.every((lines) => lines.length === 1 && lines[0].assertion === 'A17_ATLAS_PAGE_FILES_EXIST');
  return {
    held,
    read:
      `${moved.length} page(s) off disk; A17 failed ${a17.length} time(s); each page named by [${namings.map((lines) => lines.map((f) => f.assertion.slice(0, 3)).join('+') || 'nothing').join(', ')}]; ` +
      `A06 ${verdictOf('A06_ATLAS_PAGE_SIZE_MATCHES_PNG')}: ${reasonOf('A06_ATLAS_PAGE_SIZE_MATCHES_PNG')}; ` +
      `A19 ${verdictOf('A19_OVERLAY_PNGS_HAVE_ALPHA')}: ${reasonOf('A19_OVERLAY_PNGS_HAVE_ALPHA')}`,
  };
}

/** The first region name in an atlas: the line right after its page's `pma:`. */
function firstRegionName(atlasText: string): string {
  const lines = atlasText.split('\n');
  const at = lines.findIndex((l) => l.startsWith('pma: '));
  if (at < 0 || !lines[at + 1]) throw new Error('the fixture atlas declares no region');
  return lines[at + 1];
}

// ---------------------------------------------------------------------------
// the supplier check — every `validate` call is also a test of the model side (issue #1025)
// ---------------------------------------------------------------------------
//
// Step 4c of #380 writes each assertion once, against facts that two suppliers
// give it: spine-core's loaded objects (`validate()`) and the model document
// with rigc's core (`validateModel`). The gate is that the two print the same
// lines, in three populations, and the second and third are held HERE, on the
// calls this file already makes, so every existing mutant is a test of both
// suppliers without being rewritten:
//
//   * a call whose pair is the model's own output — the document's
//     `spine.sha256` is the skeleton's digest and its `pages` are the atlas's
//     — has the model side run beside it, and every moved assertion's lines
//     must be the same on both sides. A difference is a fault named by the case
//     the call was made for (the next case line printed, as `RunTally` reads
//     it), and the figures are counted off the run (`VF02`).
//   * a call whose pair was edited after the model was written — an after-emit
//     mutant — that FAILS a moved assertion must carry a twin: the same
//     wrongness forged into the model, handed to `validate` beside the call
//     (`validate(input, twin)`, or a `Mutant` row's `twin`), whose outcome the
//     run records as the identical line or the reader refusing the forged
//     document by the same object's name; or a stated reason no model field
//     can carry it (`encodingOnly`). One with neither is a fault (`VF03`). The
//     twin travels with the call rather than with the case because one case
//     can make several breaks (`S88` makes four), and a later cut declares one
//     by adding an argument where the break is made — the harness is not
//     touched.
//
// A call with no model in hand is counted and, where it fires a moved
// assertion on a file rigc wrote (no editor `hash` in its header), named: a
// firing nobody threaded a model to is a mutant neither population can see.

/** What a record's case reads until the case line that follows the call is printed. */
const UNNAMED_CASE = '(no case line followed the call)';

/**
 * What a twin is: the forge, applied to the call's model document in place, or
 * why no model can carry the wrongness. The forge is handed the call's two
 * texts as well (cut 4c-1): an edit to the ATLAS reaches the model through the
 * one derivation its `pages` section has (`ATLAS_EDIT_TWIN`), and a forge that
 * has to size something by the stage reads the stage the call's pair states —
 * the value the model side is given, not one the document holds.
 */
type SingleTwin = { forge: (doc: Record<string, unknown>, call: { skeletonText: string; atlasText: string }) => void } | { encodingOnly: string };
/**
 * A twin, or — where one break fails two moved assertions whose wrongness no
 * single document can carry at once — a twin per code (issue #1025, cut 4c-5:
 * `T16`'s empty ik key array is A34's, which the reader refuses by the
 * animation's name, and the timeline the runtime then never builds is A47's,
 * which a document carries by leaving the timeline out). A code the map does
 * not name has no twin.
 */
type ModelTwin = SingleTwin | { byCode: Readonly<Record<string, SingleTwin>> };

/**
 * The twin of every break that writes geometry onto a linked mesh (issue #1025,
 * cut 4c-2): a linked-mesh record has no geometry field (`CORE_ATTACHMENT_FIELDS`
 * in `src/core/index.ts`, whose reader refuses a field it does not know), so the
 * keys A44 refuses exist only in the Spine text, and the clause that refuses them
 * stayed with the round trip.
 */
const LINK_GEOMETRY_IS_ENCODING: ModelTwin = {
  encodingOnly:
    'a link that states geometry of its own: a linked-mesh record has no geometry field (`CORE_ATTACHMENT_FIELDS.linkedmesh` in ' +
    'src/core/index.ts) and the reader refuses one it does not know, so the keys exist only in the Spine text',
};

/** One recorded twin outcome. */
interface TwinOutcome {
  case: string;
  code: string;
  outcome: 'identical' | 'refused by name' | 'encoding-only' | 'not reproduced' | 'no twin';
  detail: string;
}

/** The codes of the moved assertions, the ones the two sides are held to. */
const MOVED_CODES: readonly string[] = MOVED_ASSERTIONS.map((m) => m.code);

/** A report line's code, as `caseName` reads a case line's name. */
const lineCode = (line: string): string | null => /^ {2}(?:PASS|SKIP|PROF|FAIL) {2}([A-Z0-9_]+)/.exec(line)?.[1] ?? null;

/** One code's lines in a report, as `reportLines` prints them. */
function linesOfCode(report: ValidateReport | ModelReport, code: string): string[] {
  return reportLines(report as ValidateReport).filter((line) => lineCode(line) === code);
}

/** Whether a report's parse refused its input: A00 on the runtime's side, either model-side rule on the model's. */
const spineRefused = (report: ValidateReport): boolean => report.failures.some((f) => f.assertion === 'A00_ROUNDTRIP_PARSE');
const modelRefused = (report: ModelReport): boolean => report.failures.some((f) => f.assertion === A00_MODEL_READ || f.assertion === A00_MODEL_REGIONS_ON_PAGES);

/** Whether `modelText` was written beside exactly this pair: its digest names the skeleton and its pages are the atlas's. */
function modelIsOfPair(modelText: string, skeletonText: string, atlasText: string): boolean {
  let doc: unknown;
  try {
    doc = JSON.parse(modelText);
  } catch {
    return false;
  }
  if (typeof doc !== 'object' || doc === null) return false;
  const stated = doc as { spine?: { sha256?: unknown }; pages?: unknown };
  if (stated.spine?.sha256 !== spineFileSha256(skeletonText)) return false;
  try {
    return JSON.stringify(pagesOfAtlas(atlasText)) === JSON.stringify(stated.pages);
  } catch {
    return false;
  }
}

/** What a sentinel plant throws, so the rules that read a declaration can be read off the lines they print (`declarationReaders`). */
const DECLARATION_SENTINEL = 'the selftest asked who reads this declaration';

/**
 * The moved assertions that read `what` on this call, read off the model
 * side's own run rather than listed: the supplier of that declaration planted
 * to throw a sentinel, and every code whose lines carry it (issue #1054). A
 * hand-kept list of the rules that read the rig info is how a rule moved over
 * it would go uncompared without anyone seeing.
 */
function declarationReaders(input: Parameters<typeof validateModel>[0], what: DeclaredValue): string[] {
  const sentinel = (): never => {
    throw new Error(DECLARATION_SENTINEL);
  };
  const report = validateModel(input, what === 'rig' ? { rigInfo: sentinel } : { declaredDurations: sentinel });
  return MOVED_CODES.filter((code) => linesOfCode(report, code).some((line) => line.includes(DECLARATION_SENTINEL)));
}

/**
 * The two sides over one call, compared: per moved assertion, the lines each
 * printed and whether they are the same, and the stats the model side set
 * against the runtime's. `supply` plants a model supplier (`VF04`); the
 * harness passes none.
 *
 * A call that withholds from `validate()` a declaration the document states
 * (`modelInputOf`'s `withheld`: a bare directory's missing rig info, or no
 * motion spec) asks the runtime a question the model side has no way to be
 * asked — the document states both on every spec (issue #1054) — so the rules
 * that read it are left out of that call's comparison, by name, and counted
 * (`excluded`); every other rule is compared as on any call.
 */
function compareSuppliers(input: ValidateInput, spine: ValidateReport, modelText: string, supply?: Partial<ModelSupply>): {
  model: ModelReport;
  refused: { spine: boolean; model: boolean };
  differing: Array<{ code: string; spine: string[]; model: string[] }>;
  lines: number;
  /** Lines of the rules that run before the parse (`beforeTheParse`), compared where both parses refused and the reader read the document. */
  beforeParseLines: number;
  /** The rules left out of this call's comparison because the call withheld a declaration they read, and what it withheld. */
  excluded: { withheld: DeclaredValue[]; codes: string[] };
} {
  const { input: modelInput, withheld } = modelInputAndWithheld(input, modelText);
  const model = validateModel(modelInput, supply);
  const refused = { spine: spineRefused(spine), model: modelRefused(model) };
  const excludedCodes = new Set(model.passed.includes(A00_MODEL_READ) ? withheld.flatMap((what) => declarationReaders(modelInput, what)) : []);
  const excluded = { withheld, codes: MOVED_CODES.filter((code) => excludedCodes.has(code)) };
  const differing: Array<{ code: string; spine: string[]; model: string[] }> = [];
  let lines = 0;
  let beforeParseLines = 0;
  if (refused.spine || refused.model) {
    // A rule both sides run before their parse (A08, issue #589) printed its lines on both, so they are compared even here (cut 4c-1).
    if (refused.spine && refused.model && model.passed.includes(A00_MODEL_READ)) {
      for (const { code } of MOVED_ASSERTIONS.filter((m) => m.beforeTheParse === true && !excludedCodes.has(m.code))) {
        const a = linesOfCode(spine, code);
        const b = linesOfCode(model, code);
        beforeParseLines += a.length;
        if (a.join('\n') !== b.join('\n')) differing.push({ code, spine: a, model: b });
      }
    }
    return { model, refused, differing, lines, beforeParseLines, excluded };
  }
  for (const code of MOVED_CODES) {
    if (excludedCodes.has(code)) continue;
    const a = linesOfCode(spine, code);
    const b = linesOfCode(model, code);
    lines += a.length;
    if (a.join('\n') !== b.join('\n')) differing.push({ code, spine: a, model: b });
  }
  for (const [key, value] of Object.entries(model.stats)) {
    // `rig` is the declaration's figure (issue #1114): the model side reads the document's archetype and `validate()` its
    // caller's, so a call that withheld the declaration has `rig=absent` on one side by construction — left out with the
    // rules that read it, as `excluded` leaves them out.
    if (key === 'rig' && withheld.includes('rig')) continue;
    lines++;
    if (spine.stats[key] !== value) differing.push({ code: `stats.${key}`, spine: [String(spine.stats[key])], model: [String(value)] });
  }
  return { model, refused, differing, lines, beforeParseLines, excluded };
}

/**
 * What the model side is handed for a call (issue #1025, cut 4c-1): the
 * document, the call's directory and profile, and what the document does not
 * hold, given off the call's own pair by the instrument's function
 * (`modelGivenOf`): for a `rigc-compiled/2` or `/1` document the stage its
 * skeleton header states and each atlas page's `pma`, and for a `/3` document,
 * which states both (issue #1026), nothing. A pair whose skeleton is not JSON
 * gives nothing, and the rules that need it refuse by name.
 *
 * The rig info and the declared durations are never handed over: every
 * document states both, and the model side refuses either given beside it
 * (issue #1054). Where the call hands `validate()` a declaration the document
 * states otherwise — a mutant that edits the rig info after the compile — the
 * call's declaration is written into the document's own section, so the two
 * sides read one statement; where the call withholds one (a bare directory, no
 * motion spec), it is named in `withheld` and `compareSuppliers` leaves the
 * rules that read it out of that call.
 */
function modelInputAndWithheld(input: ValidateInput, modelText: string): { input: Parameters<typeof validateModel>[0]; withheld: DeclaredValue[] } {
  let given: ReturnType<typeof modelGivenOf>;
  try {
    // Nothing for a rigc-compiled/3 document, which states both itself (issue #1026); the pair's own for a /2 or /1 one.
    given = modelGivenOf(modelText, input.skeletonText, input.atlasText);
  } catch {
    given = undefined;
  }
  const withheld: DeclaredValue[] = [];
  let text = modelText;
  const rig = documentRig(modelText);
  const durations = documentDurations(modelText);
  const restate = (edit: (doc: Record<string, unknown>) => void): void => {
    const doc = JSON.parse(text) as Record<string, unknown>;
    edit(doc);
    text = `${JSON.stringify(doc, null, 2)}\n`;
  };
  if (input.rig === undefined) withheld.push('rig');
  else if (rig !== undefined && JSON.stringify(input.rig) !== JSON.stringify(rig)) restate((doc) => void (doc.rig = input.rig));
  if (input.declaredDurations === undefined) withheld.push('declaredDurations');
  else if (durations !== undefined && JSON.stringify(input.declaredDurations) !== JSON.stringify(durations)) {
    const stated = input.declaredDurations;
    // A duration is restated on the animation the document holds; a call declaring another roster has no document to say it in.
    if (Object.keys(stated).sort().join('\u0000') !== Object.keys(durations).sort().join('\u0000')) withheld.push('declaredDurations');
    else restate((doc) => {
      for (const anim of doc.animations as Array<{ name: string; duration: number }>) anim.duration = stated[anim.name];
    });
  }
  return { input: { modelText: text, atlasDir: input.atlasDir, profile: input.profile, given }, withheld };
}

/** `modelInputAndWithheld`'s input alone — what every caller but the comparison itself hands the model side. */
function modelInputOf(input: ValidateInput, modelText: string): Parameters<typeof validateModel>[0] {
  return modelInputAndWithheld(input, modelText).input;
}

/** The document's skins and each skin's slot keys as the document itself lists them — what a walk restating no order would read (`VF09`, `VF11`). */
const documentsOwnSlotKeyWalk: SlotKeyWalk = (skins) => skins.map((skin) => ({ skin, slots: typeof skin.attachments === 'object' && skin.attachments !== null ? Object.keys(skin.attachments) : [] }));

/** The first double-quoted name in a sentence — the object a FAIL line is about (`region "x"`, `animation "x"`, `page "x"`). */
const firstQuoted = (sentence: string): string | null => /"([^"]*)"/.exec(sentence)?.[1] ?? null;

/**
 * A build the supplier check walked for the first time in its process, and what
 * that walk added (issue #1116) — `null` where the walk added nothing (no
 * runtime facts, or no family answered). What the merge needs to add a build
 * two shards both walked exactly once.
 */
type SupplierSighting =
  | { kind: 'walk'; key: string; walk: { equal: boolean; documentOrderDiffers: boolean } | null }
  | {
      kind: 'family';
      key: string;
      /** Where the build's paths point, read at its first sighting (issue #1127, `TY36`). */
      place: BuildPlace;
      family: { walked: FamilyTally[]; identical: FactCut[]; derivations: DerivationTally[] | null; multiSkin: boolean; documentOrderDiffers: boolean } | null;
    };

/** Where a supplier check stood before a suite (`journalMark`). */
interface SupplierMark {
  counts: Record<string, number>;
  linesByCode: Map<string, number>;
  measuredByCode: Map<string, number>;
  lengths: number[];
}

/** One suite's share of a supplier check, as a shard's document carries it to the merge (`journalSince`, `journalApply`). */
interface SupplierDelta {
  counts: Record<string, number>;
  linesByCode: Array<[string, number]>;
  measuredByCode: Array<[string, number]>;
  faults: Array<{ case: string; fault: string; build?: string }>;
  coreRefused: Array<{ case: string; code: string; why: string; route: string }>;
  twinOutcomes: TwinOutcome[];
  withheld: Array<{ case: string; withheld: DeclaredValue[]; codes: string[] }>;
  unthreaded: Array<{ case: string; codes: string[] }>;
  unwritable: string[];
  sightings: SupplierSighting[];
}

/**
 * `VF09`'s key for one build (issues #1054, #1127): its pair, its document and
 * the declarations its bodies were handed, each hashed — so two builds are one
 * build exactly when every text the walk reads is the same. `VF23` holds it
 * over two directories, which is why it is a function rather than a line.
 */
function familyBuildKey(input: Pick<ValidateInput, 'skeletonText' | 'atlasText' | 'rig' | 'declaredDurations'>, modelText: string): string {
  return [input.skeletonText, input.atlasText, modelText, JSON.stringify(input.rig ?? null), JSON.stringify(input.declaredDurations ?? null)].map(spineFileSha256).join(' ');
}

/** A path component a harness temp directory carries: a `rigc-…-` prefix and the six characters `mkdtemp` appends (issue #1127). */
const HARNESS_TEMP_COMPONENT = /^rigc-.+-[A-Za-z0-9]{6}$/;

/**
 * The directories a harness temp directory sits directly inside, each as given
 * and as resolved — macOS hands out `/var/…` and resolves it to `/private/var/…`:
 * this process's run root first (issue #1137), where every one of its own is
 * made, then the system temp directory, where a child's would be. The run root
 * has to come first: every pair now sits under it, so reading from the system
 * temp directory alone would give one root to every build and no climb from
 * one temp directory into another could be seen.
 */
function tempRoots(): string[] {
  const run = harnessTemp();
  return [...new Set([resolve(run), realpathSync(run), resolve(SYSTEM_TEMP), realpathSync(SYSTEM_TEMP)])];
}

/**
 * Where one recorded build's paths point (issue #1127, `TY36`): the paths it
 * spells that carry a harness temp directory's name or climb out of the temp
 * directory the pair sits in into another, each named; and how many of its
 * page and image paths reach art outside the system temp directory — the
 * checkout's gallery and corpus, which no build here writes into, counted
 * rather than faulted because their spelling is a function of the checkout's
 * path and the temp directory's, not of the process that built them.
 */
interface BuildPlace {
  faults: string[];
  checkout: number;
}

function buildPlaceOf(input: { skeletonText: string; atlasText: string; atlasDir: string }, modelText: string): BuildPlace {
  const faults: string[] = [];
  let checkout = 0;
  const tempRootOf = (path: string): string | null => {
    for (const temp of tempRoots()) {
      const from = relative(temp, path);
      if (from !== '' && !from.startsWith('..') && !isAbsolute(from)) return join(temp, from.split(/[\\/]/)[0]);
    }
    return null;
  };
  const pairRoot = tempRootOf(resolve(input.atlasDir));
  const strings = (text: string): string[] => {
    const out: string[] = [];
    const walk = (node: unknown): void => {
      if (typeof node === 'string') out.push(node);
      else if (Array.isArray(node)) node.forEach(walk);
      else if (typeof node === 'object' && node !== null) Object.values(node).forEach(walk);
    };
    try {
      walk(JSON.parse(text));
    } catch {
      // A forged pair that does not parse spells nothing this reading can name.
    }
    return out;
  };
  let pages: string[] = [];
  try {
    pages = pagesOfAtlas(input.atlasText).map((page) => page.name);
  } catch {
    pages = [];
  }
  let images: string[] = [];
  try {
    const header = (JSON.parse(input.skeletonText) as { skeleton?: { images?: unknown } }).skeleton;
    images = typeof header?.images === 'string' ? [header.images] : [];
  } catch {
    images = [];
  }
  const spelled: Array<[string, string]> = [
    ...pages.map((name): [string, string] => ['atlas page', name]),
    ...strings(input.skeletonText).map((value): [string, string] => ['skeleton string', value]),
    ...strings(modelText).map((value): [string, string] => ['document string', value]),
  ];
  for (const [where, value] of spelled) {
    const component = value.split(/[\\/]/).find((part) => HARNESS_TEMP_COMPONENT.test(part));
    if (component !== undefined) faults.push(`${where} ${JSON.stringify(value)} spells the temp directory "${component}"`);
  }
  for (const [where, value] of [...pages.map((name): [string, string] => ['atlas page', name]), ...images.map((path): [string, string] => ['skeleton.images', path])]) {
    if (isAbsolute(value)) continue;
    const landed = resolve(input.atlasDir, value);
    const root = tempRootOf(landed);
    if (root === null) checkout++;
    else if (pairRoot !== null && root !== pairRoot) faults.push(`${where} ${JSON.stringify(value)} climbs out of the pair's temp directory into another`);
  }
  return { faults, checkout };
}

class SupplierCheck {
  /** `plant` replaces a model supplier on every comparison this check makes — `VF04`'s plants; the run's check passes none. */
  constructor(private readonly plant: Partial<ModelSupply> = {}) {}

  /** Every `validate` call this run made. */
  calls = 0;
  /** Calls with a model document in hand. */
  withModel = 0;
  /** Of those, calls whose pair is the model's own output — population 2. */
  own = 0;
  /** Own calls on which both sides read their input and the lines were compared. */
  compared = 0;
  /** Lines compared over those calls, stats values included. */
  lines = 0;
  /** Own calls on which both sides refused their input (A00 and a model-side parse rule). */
  bothRefused = 0;
  /** Of those, calls on which a rule that runs before the parse printed lines on both sides and they were compared, and how many lines. */
  beforeParse = 0;
  beforeParseLines = 0;
  /** Lines compared per moved assertion over the own calls, so an assertion compared on none is named (`VF02`'s floor). */
  linesByCode = new Map<string, number>();
  /** Calls on which a moved assertion measured something — a PASS or FAIL line rather than SKIP or PROF — per assertion. */
  measuredByCode = new Map<string, number>();
  /**
   * The one walk (issue #1054, `compareFactFamilies` in `tools/verdict_gate.ts`):
   * every fact family of every cut asked on each distinct own build and the
   * declarations its bodies were handed — how many builds, how many calls they
   * stood for, how many builds every family of a cut answered alike, and each
   * family's tally summed with its cut. `VF09` holds the one floor over every
   * family; each cut's control prints its own figure off these.
   */
  familyWalk = { builds: 0, calls: 0 };
  families = new Map<string, FamilyTally>();
  identicalByCut = new Map<FactCut, number>();
  private familyBuilt = new Set<string>();
  /** On multi-skin builds, how many would join their regions in another order had the document been walked in its own skin and slot-key order (`VF09`). */
  joinsDocumentOrderDiffers = 0;
  joinsMultiSkin = 0;
  /** Each derivation's tally summed over the walk's builds (`VF10`, `tools/rig_facts.ts`). */
  derivations = new Map<string, DerivationTally>();
  /** Calls whose pair was edited after the model was written. */
  afterEmit = 0;
  /** Of those, calls that FAIL a moved assertion — population 3. */
  firing = 0;
  /**
   * Multi-skin builds (distinct pairs, over the own calls) on which the two walks
   * of the skins were compared fact by fact, how many agreed, and on how many a walk of the document in its own
   * skin order would have disagreed — the measurement that says the emitter's
   * order is the one that matters.
   */
  walks = { compared: 0, equal: 0, documentOrderDiffers: 0 };
  private walked = new Set<string>();
  /** Faults, each attributed to the case it was found in. */
  faults: Array<{ case: string; fault: string }> = [];
  /**
   * Lines that differ because the core refused the build by name — the body
   * on the model side threw a `CoreInputError` (cut 4c-5a: A10's walk over a
   * construct the core leaves out, or a document with no default skin) — each
   * with the code and the core's sentence (`VF02`).
   */
  coreRefused: Array<{ case: string; code: string; why: string; route: string }> = [];
  twinOutcomes: TwinOutcome[] = [];
  /**
   * Own calls that withheld from `validate()` a declaration the document
   * states (issue #1054): what they withheld, and the rules left out of their
   * comparison because they read it (`compareSuppliers`).
   */
  withheld: Array<{ case: string; withheld: DeclaredValue[]; codes: string[] }> = [];
  /** Calls with no model in hand, and those of them that fired a moved assertion on a file rigc wrote. */
  withoutModel = 0;
  unthreaded: Array<{ case: string; codes: string[] }> = [];
  /** Compiles whose model document the writer refused, so no model could be threaded to their call. */
  unwritable: string[] = [];
  /** Records made since the last case line, whose `case` that line will name. */
  private awaiting: Array<{ case: string }> = [];

  /** Name every record kept since the last case line after the case line just printed. */
  caseLine(name: string): void {
    for (const record of this.awaiting) record.case = name;
    this.awaiting = [];
  }

  /** A record, kept now — so a figure read before the case line counts it — and named by the case line that follows. */
  private keep<T extends { case: string }>(list: T[], record: Omit<T, 'case'>): T {
    const kept = { ...record, case: UNNAMED_CASE } as T;
    list.push(kept);
    this.awaiting.push(kept);
    return kept;
  }

  /**
   * Every distinct build this check walked, in the order it first saw each, with
   * what that first sighting added (issue #1116). Nothing here reads it in a
   * one-process run; a shard hands it to the merge, which is how the merge adds
   * a build two shards both walked ONCE, as one process would have — the
   * per-build figures (`walks`, `familyWalk.builds`, `families`, `derivations`,
   * the joins) and the faults a first sighting raised are a fact about distinct
   * builds, and a sum of two shards' would count a shared build twice.
   */
  private sightings: SupplierSighting[] = [];
  /** Every distinct build this check recorded, first sightings only and in run order, with where its paths point (issue #1127, `TY36`). */
  recordedPlaces(): Array<{ key: string; place: BuildPlace }> {
    return this.sightings.flatMap((sighting) => (sighting.kind === 'family' ? [{ key: sighting.key, place: sighting.place }] : []));
  }

  /** The faults a first sighting raised, by the build it was the first sighting of. */
  private faultBuild = new Map<object, string>();

  /**
   * Every field this class holds, by how a shard's record carries it. A field
   * added to the class and not here makes `journalMark` throw by name: a field
   * the record does not carry is a figure the merge would silently lose.
   */
  private static readonly JOURNAL_FIELDS: Record<string, 'per call' | 'per build' | 'journal'> = {
    plant: 'journal', awaiting: 'journal', sightings: 'journal', faultBuild: 'journal',
    calls: 'per call', withModel: 'per call', own: 'per call', compared: 'per call', lines: 'per call',
    bothRefused: 'per call', beforeParse: 'per call', beforeParseLines: 'per call', linesByCode: 'per call',
    measuredByCode: 'per call', afterEmit: 'per call', firing: 'per call', withoutModel: 'per call',
    faults: 'per call', coreRefused: 'per call', twinOutcomes: 'per call', withheld: 'per call', unthreaded: 'per call',
    unwritable: 'per call',
    familyWalk: 'per build', families: 'per build', identicalByCut: 'per build', familyBuilt: 'per build',
    joinsDocumentOrderDiffers: 'per build', joinsMultiSkin: 'per build', derivations: 'per build', walks: 'per build',
    walked: 'per build',
  };

  /** Where this check stands now, for `journalSince` to read one suite's share off (issue #1116). */
  journalMark(): SupplierMark {
    const unknown = Object.keys(this).filter((key) => !(key in SupplierCheck.JOURNAL_FIELDS));
    if (unknown.length > 0) {
      throw new Error(`SupplierCheck holds ${unknown.map((k) => `"${k}"`).join(', ')}, which a shard's record does not carry — add each to JOURNAL_FIELDS and to journalSince/journalApply`);
    }
    return {
      counts: this.perCallCounts(),
      linesByCode: new Map(this.linesByCode),
      measuredByCode: new Map(this.measuredByCode),
      lengths: [this.faults.length, this.coreRefused.length, this.twinOutcomes.length, this.withheld.length, this.unthreaded.length, this.unwritable.length, this.sightings.length],
    };
  }

  /** The per-call counters, by name. */
  private perCallCounts(): Record<string, number> {
    return {
      calls: this.calls, withModel: this.withModel, own: this.own, compared: this.compared, lines: this.lines,
      bothRefused: this.bothRefused, beforeParse: this.beforeParse, beforeParseLines: this.beforeParseLines,
      afterEmit: this.afterEmit, firing: this.firing, withoutModel: this.withoutModel, familyWalkCalls: this.familyWalk.calls,
    };
  }

  /**
   * What this check gained since `mark`: the per-call figures as differences and
   * slices, and the builds first seen since, each with what it added. The
   * records are the live objects, so a case line printed after the suite still
   * names them before the shard writes its document.
   */
  journalSince(mark: SupplierMark): SupplierDelta {
    const now = this.perCallCounts();
    const counts: Record<string, number> = {};
    for (const [key, value] of Object.entries(now)) counts[key] = value - (mark.counts[key] ?? 0);
    const mapDelta = (live: Map<string, number>, was: Map<string, number>): Array<[string, number]> =>
      [...live].map(([k, v]): [string, number] => [k, v - (was.get(k) ?? 0)]).filter(([, v]) => v !== 0);
    const [f, c, t, w, u, x, s] = mark.lengths;
    return {
      counts,
      linesByCode: mapDelta(this.linesByCode, mark.linesByCode),
      measuredByCode: mapDelta(this.measuredByCode, mark.measuredByCode),
      faults: this.faults.slice(f).map((record) => {
        const build = this.faultBuild.get(record);
        return build === undefined ? record : { ...record, build };
      }),
      coreRefused: this.coreRefused.slice(c),
      twinOutcomes: this.twinOutcomes.slice(t),
      withheld: this.withheld.slice(w),
      unthreaded: this.unthreaded.slice(u),
      unwritable: this.unwritable.slice(x),
      sightings: this.sightings.slice(s),
    };
  }

  /**
   * One suite's share, read back into this check in the order the one-process
   * run would have made it (issue #1116). A build this check has already seen
   * adds nothing and its faults are dropped — that sighting was not the first
   * in the run order, so in one process it would have been a repeat.
   */
  journalApply(delta: SupplierDelta): void {
    this.calls += delta.counts.calls ?? 0;
    this.withModel += delta.counts.withModel ?? 0;
    this.own += delta.counts.own ?? 0;
    this.compared += delta.counts.compared ?? 0;
    this.lines += delta.counts.lines ?? 0;
    this.bothRefused += delta.counts.bothRefused ?? 0;
    this.beforeParse += delta.counts.beforeParse ?? 0;
    this.beforeParseLines += delta.counts.beforeParseLines ?? 0;
    this.afterEmit += delta.counts.afterEmit ?? 0;
    this.firing += delta.counts.firing ?? 0;
    this.withoutModel += delta.counts.withoutModel ?? 0;
    this.familyWalk.calls += delta.counts.familyWalkCalls ?? 0;
    for (const [k, v] of delta.linesByCode) this.linesByCode.set(k, (this.linesByCode.get(k) ?? 0) + v);
    for (const [k, v] of delta.measuredByCode) this.measuredByCode.set(k, (this.measuredByCode.get(k) ?? 0) + v);
    const repeats = new Set<string>();
    for (const sighting of delta.sightings) {
      const seen = sighting.kind === 'walk' ? this.walked : this.familyBuilt;
      if (seen.has(sighting.key)) {
        repeats.add(sighting.key);
        continue;
      }
      seen.add(sighting.key);
      this.sightings.push(sighting);
      if (sighting.kind === 'walk') {
        if (sighting.walk === null) continue;
        this.walks.compared++;
        if (sighting.walk.documentOrderDiffers) this.walks.documentOrderDiffers++;
        if (sighting.walk.equal) this.walks.equal++;
        continue;
      }
      const added = sighting.family;
      if (added === null) continue;
      this.familyWalk.builds++;
      sumPosedTallies(this.families, added.walked);
      for (const cut of added.identical) this.identicalByCut.set(cut, (this.identicalByCut.get(cut) ?? 0) + 1);
      if (added.derivations !== null) sumTallies(this.derivations, added.derivations);
      if (added.multiSkin) this.joinsMultiSkin++;
      if (added.documentOrderDiffers) this.joinsDocumentOrderDiffers++;
    }
    for (const record of delta.faults) {
      if (record.build !== undefined && repeats.has(record.build)) continue;
      const kept = { case: record.case, fault: record.fault };
      this.faults.push(kept);
      if (record.build !== undefined) this.faultBuild.set(kept, record.build);
    }
    this.coreRefused.push(...delta.coreRefused);
    this.twinOutcomes.push(...delta.twinOutcomes);
    this.withheld.push(...delta.withheld);
    this.unthreaded.push(...delta.unthreaded);
    this.unwritable.push(...delta.unwritable);
  }

  observe(input: ValidateInput, spine: ValidateReport, twin: ModelTwin | undefined): void {
    this.calls++;
    const firing = MOVED_CODES.filter((code) => spine.failures.some((f) => f.assertion === code));
    if (input.modelText === undefined) {
      this.withoutModel++;
      if (twin !== undefined) this.keep(this.faults, { fault: 'a twin was declared beside a call with no model in hand, so there is no document to forge it into' });
      if (firing.length > 0 && this.rigcWrote(input.skeletonText)) this.keep(this.unthreaded, { codes: firing });
      return;
    }
    this.withModel++;
    const modelText = input.modelText;
    if (modelIsOfPair(modelText, input.skeletonText, input.atlasText)) {
      this.own++;
      if (twin !== undefined) this.keep(this.faults, { fault: 'a twin was declared beside a call whose pair is its model\'s own build, so there is no break for it to be the twin of' });
      const compared = compareSuppliers(input, spine, modelText, this.plant);
      if (compared.excluded.withheld.length > 0) this.keep(this.withheld, compared.excluded);
      if (compared.refused.spine && compared.refused.model) {
        this.bothRefused++;
        if (compared.beforeParseLines > 0) this.beforeParse++;
        this.beforeParseLines += compared.beforeParseLines;
        for (const d of compared.differing) this.keep(this.faults, { fault: `${d.code} differs where both parses refused — spine-core: ${JSON.stringify(d.spine)}; model: ${JSON.stringify(d.model)}` });
      }
      else if (compared.refused.spine !== compared.refused.model) {
        const said = compared.refused.spine
          ? `A00_ROUNDTRIP_PARSE refused the pair and the model side read the document: ${spine.failures.find((f) => f.assertion === 'A00_ROUNDTRIP_PARSE')?.detail}`
          : `the model side refused its own build's document and the round trip loaded the pair: ${compared.model.failures.map((f) => `${f.assertion}: ${f.detail}`).join('; ')}`;
        this.keep(this.faults, { fault: said });
      } else {
        this.compared++;
        this.lines += compared.lines;
        for (const code of MOVED_CODES) {
          const own = linesOfCode(spine, code);
          this.linesByCode.set(code, (this.linesByCode.get(code) ?? 0) + own.length);
          if (own.some((line) => /^ {2}(PASS|FAIL) /.test(line))) this.measuredByCode.set(code, (this.measuredByCode.get(code) ?? 0) + 1);
        }
        for (const d of compared.differing) {
          // A model-side line that is the core refusing the build by name (a `CoreInputError` its body threw) is that route's
          // line, which cannot be made identical (cut 4c-5a): counted and named by VF02, never folded into the identical lines.
          const refusal = this.coreRefusal(input, modelText, d.code, d.model);
          if (refusal !== null) this.keep(this.coreRefused, { code: d.code, why: refusal.why, route: refusal.route });
          else this.keep(this.faults, { fault: `${d.code} differs — spine-core: ${JSON.stringify(d.spine)}; model: ${JSON.stringify(d.model)}` });
        }
        this.compareWalks(input, modelText);
        this.walkFamiliesOf(input, modelText);
      }
      return;
    }
    this.afterEmit++;
    if (firing.length === 0) {
      // A twin beside a break that fails nothing the model side runs is a declaration nothing reads.
      if (twin !== undefined) this.keep(this.faults, { fault: 'a twin was declared beside a break that fails no moved assertion, so nothing ran it' });
      return;
    }
    this.firing++;
    const outcomes = this.settleTwin(input, spine, modelText, firing, twin);
    for (const outcome of outcomes) this.keep(this.twinOutcomes, outcome);
  }

  /**
   * The core's sentence where the model side's lines of `code` are one FAIL
   * whose detail is a throw, and the body, run again over the same document,
   * throws a `CoreInputError` — a refusal by name. `null` for anything else,
   * so a plain error or a wrong value stays a fault.
   */
  private coreRefusal(input: ValidateInput, modelText: string, code: string, model: readonly string[]): { why: string; route: string } | null {
    const modelInput = modelInputOf(input, modelText);
    return coreRefusalOf(code, model, modelInput.modelText, modelInput);
  }

  /** A file rigc wrote: one whose header carries no editor `hash` — every after-emit edit in this run is of one (census §4). */
  private rigcWrote(skeletonText: string): boolean {
    try {
      const header = (JSON.parse(skeletonText) as { skeleton?: Record<string, unknown> }).skeleton;
      return header !== undefined && !('hash' in header);
    } catch {
      return false;
    }
  }

  /** The order measurement: on a build of more than one skin, the skins' entries walked by both suppliers, name and size, in order. */
  private compareWalks(input: ValidateInput, modelText: string): void {
    const doc = JSON.parse(modelText) as { skins?: unknown[] };
    if (!Array.isArray(doc.skins) || doc.skins.length < 2) return;
    // One reading per build: a build gated under both profiles, or twice by one case, is one compile.
    const build = `${spineFileSha256(input.skeletonText)} ${spineFileSha256(input.atlasText)}`;
    if (this.walked.has(build)) return;
    this.walked.add(build);
    const sighting: SupplierSighting = { kind: 'walk', key: build, walk: null };
    this.sightings.push(sighting);
    const runtime = runtimeFacts(input.skeletonText, input.atlasText);
    if (runtime === null) return;
    const model = modelSkinEntries({ doc: readModel(modelText), json: doc as Record<string, unknown> });
    const spell = walkSpelling;
    this.walks.compared++;
    // What the document's own order would have printed — the walk the census measured unequal on 3 of 52.
    const read = { doc: readModel(modelText), json: doc as Record<string, unknown> };
    const documentOrderDiffers = spell(modelSkinEntries(read, (skins) => [...skins])) !== spell(runtime.skinEntries);
    if (documentOrderDiffers) this.walks.documentOrderDiffers++;
    const equal = spell(runtime.skinEntries) === spell(model);
    sighting.walk = { equal, documentOrderDiffers };
    if (equal) this.walks.equal++;
    else this.faultBuild.set(this.keep(this.faults, { fault: `the skins walk in another order on the two sides — spine-core ${spell(runtime.skinEntries).slice(0, 240)}; model ${spell(model).slice(0, 240)}` }), build);
  }

  /**
   * Every fact family of every cut over one build and the declarations its
   * bodies were handed, through the one walk (issue #1054): once per distinct
   * build, every call counted. A family answered otherwise is a fault named
   * with its cut; a whole family (cuts 4c-1 and 4c-2) the core refused is one
   * too, since nothing but a refusal by name could stand in for its answer.
   */
  private walkFamiliesOf(input: ValidateInput, modelText: string): void {
    this.familyWalk.calls++;
    const build = familyBuildKey(input, modelText);
    if (this.familyBuilt.has(build)) return;
    this.familyBuilt.add(build);
    const sighting: SupplierSighting = { kind: 'family', key: build, place: buildPlaceOf(input, modelText), family: null };
    this.sightings.push(sighting);
    const walked = compareFactFamilies(input.skeletonText, input.atlasText, modelText, { rig: input.rig, declaredDurations: input.declaredDurations }, this.plant);
    if (walked === null) return;
    this.familyWalk.builds++;
    sumPosedTallies(this.families, walked);
    const identical: FactCut[] = [];
    for (const cut of FACT_CUTS) {
      const ofCut = walked.filter((t) => t.cut === cut);
      if (ofCut.length > 0 && ofCut.every((t) => t.differing.length === 0)) {
        this.identicalByCut.set(cut, (this.identicalByCut.get(cut) ?? 0) + 1);
        identical.push(cut);
      }
    }
    const raised = (fault: string): void => void this.faultBuild.set(this.keep(this.faults, { fault }), build);
    for (const t of walked) {
      for (const d of t.differing) raised(`${FACT_FAULT} "${t.family}" (cut ${t.cut}) differ at ${d.question.slice(0, 160)} — spine-core ${d.spine.slice(0, 240)}; model ${d.model.slice(0, 240)}`);
      if (t.cut === '4c-1' || t.cut === '4c-2') for (const r of t.refused) raised(`${FACT_FAULT} "${t.family}" (cut ${t.cut}) differ: the core refused the model side's reading by name — ${r.why.slice(0, 240)}`);
    }
    const derivations = rigFactsDerivationsOf(input.skeletonText, input.atlasText, modelText);
    if (derivations !== null) sumTallies(this.derivations, derivations);
    // What the document's own skin and slot-key order would have joined — the measurement that says the emitter's order is the one that matters.
    const doc = JSON.parse(modelText) as { skins?: unknown[] };
    let multiSkin = false;
    let documentOrderDiffers = false;
    if (Array.isArray(doc.skins) && doc.skins.length > 1) {
      multiSkin = true;
      this.joinsMultiSkin++;
      const read = { doc: readModel(modelText), json: doc as Record<string, unknown> };
      const own = JSON.stringify(modelRegionJoinsWith(read, documentsOwnSlotKeyWalk));
      documentOrderDiffers = own !== JSON.stringify(modelRegionJoinsWith(read));
      if (documentOrderDiffers) this.joinsDocumentOrderDiffers++;
    }
    sighting.family = { walked, identical, derivations, multiSkin, documentOrderDiffers };
  }

  private settleTwin(input: ValidateInput, spine: ValidateReport, modelText: string, firing: string[], whole: ModelTwin | undefined): Array<Omit<TwinOutcome, 'case'>> {
    const out: Array<Omit<TwinOutcome, 'case'>> = [];
    for (const code of firing) {
      const spineLines = linesOfCode(spine, code);
      const twin = whole === undefined || !('byCode' in whole) ? whole : whole.byCode[code];
      if (twin === undefined) {
        out.push({ code, outcome: 'no twin', detail: spineLines[spineLines.length - 1] ?? '' });
        continue;
      }
      if ('encodingOnly' in twin) {
        out.push({ code, outcome: 'encoding-only', detail: twin.encodingOnly });
        continue;
      }
      const doc = JSON.parse(modelText) as Record<string, unknown>;
      try {
        twin.forge(doc, { skeletonText: input.skeletonText, atlasText: input.atlasText });
      } catch (err) {
        out.push({ code, outcome: 'not reproduced', detail: `the twin's forge threw on the call's document: ${(err as Error).message}` });
        continue;
      }
      const model = validateModel(modelInputOf(input, `${JSON.stringify(doc, null, 2)}\n`));
      const modelLines = linesOfCode(model, code);
      if (modelLines.join('\n') === spineLines.join('\n')) {
        out.push({ code, outcome: 'identical', detail: spineLines.find((l) => l.startsWith('  FAIL')) ?? '' });
        continue;
      }
      // A line that is spine-core's own throw names no object — A10's `threw:` over an apply that crashed (cut 4c-5a) — so the object is the
      // break's subject as the call's other failing lines name it, the first that names one; with none, nothing can be matched.
      const own = spine.failures.find((f) => f.assertion === code)?.detail ?? '';
      const object = firstQuoted(own) ?? (own.startsWith('threw: ') ? spine.failures.map((f) => firstQuoted(f.detail)).find((name) => name !== null) ?? null : null);
      const refusal = model.failures.find((f) => f.assertion === A00_MODEL_READ || f.assertion === A00_MODEL_REGIONS_ON_PAGES);
      if (refusal !== undefined && object !== null && refusal.detail.includes(`"${object}"`)) {
        out.push({ code, outcome: 'refused by name', detail: `"${object}" — ${refusal.assertion}: ${refusal.detail.slice(0, 200)}` });
        continue;
      }
      out.push({
        code,
        outcome: 'not reproduced',
        detail: `spine-core ${JSON.stringify(spineLines)}; the twin ${refusal === undefined ? JSON.stringify(modelLines) : `refused without naming ${JSON.stringify(object)}: ${refusal.detail.slice(0, 200)}`}`,
      });
    }
    return out;
  }
}

/**
 * The twin of an edit to the ATLAS text (issue #1025, cut 4c-1): the document's
 * `pages` as the writer spells them from the atlas the call was handed —
 * `pagesOfAtlas`, the one function `build` writes that section with — so the
 * wrongness reaches the model through the section's own derivation rather than
 * a hand-written copy of each edit. Since issue #1026 each page's `pma` and
 * `scale` are in the section too, so an edit of either reaches the model the
 * same way — `M15`'s `pma: true` among them.
 */
const ATLAS_EDIT_TWIN: ModelTwin = {
  forge: (doc, call) => {
    doc.pages = pagesOfAtlas(call.atlasText);
  },
};

/**
 * Why a blank line inside a page block has no model-side twin (issue #1025, cut
 * 4c-1): it is the atlas TEXT's line layout, A07's subject. A08 fires on it only
 * as a consequence — the runtime reads the region line after the blank as a
 * page declaring no size, so the region it named is gone — and the document's
 * `pages` section cannot state that reading: forged through the section's own
 * writer (`ATLAS_EDIT_TWIN`), `readModel` refuses the document for that page's
 * size of 0 (`pages[1] …: width is 0, not a positive finite number`, measured on
 * M08 and S107), a refusal that names the page and not the attachment A08 names.
 */
const BLANK_LINE_LAYOUT_ONLY: ModelTwin = {
  encodingOnly:
    "a blank line inside a page block is the atlas text's layout (A07's subject); the page the runtime reads after it declares no size, which the document's pages cannot state — the reader refuses that page's size of 0 by the page's name, not the attachment's",
};

/** A forge's handle on one skin of a document, by name. */
type DocSkin = { name: string; bones: string[]; attachments: Record<string, Record<string, Record<string, unknown>>> };
function docSkin(doc: Record<string, unknown>, name: string): DocSkin {
  const found = (doc.skins as DocSkin[]).find((skin) => skin.name === name);
  if (found === undefined) throw new Error(`the document has no skin "${name}"`);
  return found;
}

/** A twin that sets one record's `path`, addressed as the Spine file addresses it: skin, slot, placeholder. */
function docRepathTwin(skin: string, slot: string, placeholder: string, path: string, alsoAtlas = false): ModelTwin {
  return {
    forge: (doc, call) => {
      const record = docSkin(doc, skin).attachments[slot]?.[placeholder];
      if (record === undefined) throw new Error(`the document's skin "${skin}" has no record "${placeholder}" in slot "${slot}"`);
      record.path = path;
      if (alsoAtlas) doc.pages = pagesOfAtlas(call.atlasText);
    },
  };
}

/** A Spine animation's `bones` group as the document lists it: `{ bone: { timeline: keys } }` → `[{ name, timelines: [{ name, keys }] }]`, in the group's order. */
function docBoneTimelines(group: Record<string, Record<string, unknown[]>>): Array<{ name: string; timelines: Array<{ name: string; keys: unknown[] }> }> {
  return Object.entries(group).map(([name, timelines]) => ({ name, timelines: Object.entries(timelines).map(([timeline, keys]) => ({ name: timeline, keys })) }));
}

/** A twin that replaces what `idle` keys on bones with `group`, a Spine `bones` group — the document's spelling of the same keys. */
function idleBonesTwin(group: Record<string, Record<string, unknown[]>>): ModelTwin {
  return {
    forge: (doc) => {
      const idle = (doc.animations as Array<{ name: string; bones: unknown[] }>).find((a) => a.name === 'idle');
      if (idle === undefined) throw new Error('the document has no "idle" animation');
      idle.bones = docBoneTimelines(group);
    },
  };
}

/** A twin's way into a document: one animation's timelines on one slot, as the document lists them (`[{ name, keys }]`, in order). */
type DocTimeline = { name: string; keys: Array<Record<string, unknown>> };
function docSlotTimelines(doc: Record<string, unknown>, animation: string, slot: string): DocTimeline[] {
  const animations = doc.animations as Array<{ name: string; slots: Array<{ name: string; timelines: DocTimeline[] }> }>;
  const entry = animations.find((a) => a.name === animation)?.slots.find((x) => x.name === slot);
  if (entry === undefined) throw new Error(`the document keys no slot "${slot}" in animation "${animation}"`);
  return entry.timelines;
}

/** The keys of one timeline of `docSlotTimelines`, named. */
function docKeys(timelines: DocTimeline[], name: string): Array<Record<string, unknown>> {
  const found = timelines.find((t) => t.name === name);
  if (found === undefined) throw new Error(`the slot keys no "${name}" timeline in the document`);
  return found.keys;
}

/** A twin's way into a document's skin entry (issue #1025, cut 4c-2): one record of one skin's table, as the document spells it. */
type DocRecord = Record<string, unknown>;
function docSkinTable(doc: Record<string, unknown>, skin = 'default'): Record<string, Record<string, DocRecord>> {
  const found = (doc.skins as Array<{ name: string; attachments: Record<string, Record<string, DocRecord>> }>).find((s) => s.name === skin);
  if (found === undefined) throw new Error(`the document has no skin "${skin}"`);
  return found.attachments;
}
function docRecord(doc: Record<string, unknown>, slot: string, placeholder: string, skin = 'default'): DocRecord {
  const record = docSkinTable(doc, skin)[slot]?.[placeholder];
  if (record === undefined) throw new Error(`the document's skin "${skin}" has no record "${placeholder}" on slot "${slot}"`);
  return record;
}
/** A weighted record's bindings, per vertex, as the document states them. */
function docBindings(record: DocRecord): Array<Array<{ bone: string; x: number; y: number; weight: number }>> {
  const vertices = record.vertices as { weighted: boolean; bindings?: Array<Array<{ bone: string; x: number; y: number; weight: number }>> };
  if (!vertices.weighted || vertices.bindings === undefined) throw new Error('the record is not weighted');
  return vertices.bindings;
}
/** The first constraint of `kind` the document declares. */
function docConstraint(doc: Record<string, unknown>, kind: string): DocRecord {
  const found = (doc.constraints as DocRecord[]).find((c) => c.kind === kind);
  if (found === undefined) throw new Error(`the document declares no ${kind} constraint`);
  return found;
}
/** One animation's constraint timelines, as the document groups them (`ik`, `transform`, `path`, `physics`, `slider`). */
function docAnimationConstraints(doc: Record<string, unknown>, animation: string): Record<string, unknown[]> {
  const found = (doc.animations as Array<{ name: string; constraints: Record<string, unknown[]> }>).find((a) => a.name === animation);
  if (found === undefined) throw new Error(`the document has no animation "${animation}"`);
  return found.constraints;
}

/** One physics timeline's keys in one animation, as the document lists them (`constraints.physics[] = { name, timelines: [{ name, keys }] }`). */
function docPhysicsKeys(doc: Record<string, unknown>, animation: string, constraint: string, timeline: string): Array<Record<string, unknown>> {
  const entry = (docAnimationConstraints(doc, animation).physics as Array<{ name: string; timelines: DocTimeline[] }>).find((e) => e.name === constraint);
  const found = entry?.timelines.find((t) => t.name === timeline);
  if (found === undefined) throw new Error(`the document's animation "${animation}" keys no "${timeline}" on physics "${constraint}"`);
  return found.keys;
}

/**
 * A twin's way into a document's bone timelines (issue #1025, cut 4c-4): one
 * animation's timelines on one bone, as the document lists them (`[{ name,
 * keys }]`, in order). `add` puts an entry for the bone at the end of the
 * animation's list where it keys none, which is where a Spine break that
 * assigns `animations.<a>.bones.<bone>` puts the key in the file's object.
 */
function docBoneTimelineList(doc: Record<string, unknown>, animation: string, bone: string, add = false): DocTimeline[] {
  const found = (doc.animations as Array<{ name: string; bones: Array<{ name: string; timelines: DocTimeline[] }> }>).find((a) => a.name === animation);
  if (found === undefined) throw new Error(`the document has no animation "${animation}"`);
  let entry = found.bones.find((b) => b.name === bone);
  if (entry === undefined) {
    if (!add) throw new Error(`the document's animation "${animation}" keys no bone "${bone}"`);
    entry = { name: bone, timelines: [] };
    found.bones.push(entry);
  }
  return entry.timelines;
}

/** One timeline of `docBoneTimelineList` replaced by `keys`, or added after the others where the bone keys no such timeline — what a Spine break assigning `…bones.<bone>.<timeline>` does to the file's object. */
function docSetTimeline(timelines: DocTimeline[], name: string, keys: Array<Record<string, unknown>>): void {
  const found = timelines.find((t) => t.name === name);
  if (found !== undefined) found.keys = keys;
  else timelines.push({ name, keys });
}

/**
 * A slot renamed everywhere the document names it as a slot (issue #1025, cut
 * 4c-4): the slot record, each skin's table key, the editor order's slot
 * lists, and each animation's slot entries — the twin of a Spine break that
 * renames the slot and its skin table (`M35`). The rig section is the build's
 * declaration and is left alone, as the break leaves the rig info alone.
 */
function docRenameSlot(doc: Record<string, unknown>, from: string, to: string): void {
  const slot = (doc.slots as Array<{ name: string }>).find((s) => s.name === from);
  if (slot === undefined) throw new Error(`the document has no slot "${from}"`);
  slot.name = to;
  for (const skin of doc.skins as Array<{ attachments: Record<string, unknown> }>) {
    if (!(from in skin.attachments)) continue;
    skin.attachments = Object.fromEntries(Object.entries(skin.attachments).map(([k, v]) => [k === from ? to : k, v]));
  }
  const order = doc.editorOrder as { skins: Array<{ slots: string[] }> } | undefined;
  for (const skin of order?.skins ?? []) skin.slots = skin.slots.map((s) => (s === from ? to : s));
  for (const animation of doc.animations as Array<{ slots: Array<{ name: string }> }>) for (const entry of animation.slots) if (entry.name === from) entry.name = to;
}

/** A slot taken out of the document — its record and the editor order's slot lists — the twin of a Spine break that deletes it from the `slots` array (`O26`); a slot a skin fills cannot be dropped this way. */
function docDropSlot(doc: Record<string, unknown>, name: string): void {
  for (const skin of doc.skins as Array<{ attachments: Record<string, unknown> }>) {
    if (name in skin.attachments) throw new Error(`the document's skins fill slot "${name}", so dropping only its record is not the break`);
  }
  doc.slots = (doc.slots as Array<{ name: string }>).filter((s) => s.name !== name);
  const order = doc.editorOrder as { skins: Array<{ slots: string[] }> } | undefined;
  for (const skin of order?.skins ?? []) skin.slots = skin.slots.filter((s) => s !== name);
}

/**
 * The twin of a Spine break that declares `events` as `{ <name>: {} }` and
 * keys the file's FIRST animation with `keys` (`M45b`–`M45d`, issue #1025,
 * cut 4c-4): the document's `events` section declaring the same names, and
 * the same keys on the animation the file lists first — read off the broken
 * skeleton, since the file's order is the emitter's (`editorAnimationOrder`)
 * and not the document's.
 */
function docEventsTwin(declared: string[], keys: Array<Record<string, unknown>>): ModelTwin {
  return {
    forge: (doc, call) => {
      const first = Object.keys((JSON.parse(call.skeletonText) as { animations: Record<string, unknown> }).animations)[0];
      const animation = (doc.animations as Array<{ name: string; events: unknown[] }>).find((a) => a.name === first);
      if (animation === undefined) throw new Error(`the document has no animation "${first}"`);
      doc.events = declared.map((name) => ({ name }));
      animation.events = keys.map((key) => ({ ...key }));
    },
  };
}

/**
 * A twin that edits the keys of one slot timeline of one animation, as the
 * document lists them (issue #1025, cut 4c-3) — the same keys the break edits
 * in the Spine file, in the document's spelling, which for a slot timeline is
 * the file's (`light`, `dark`, `color`, `value`, `time`).
 */
function docSlotKeysTwin(animation: string, slot: string, timeline: string, edit: (keys: Array<Record<string, unknown>>) => void): ModelTwin {
  return { forge: (doc) => edit(docKeys(docSlotTimelines(doc, animation, slot), timeline)) };
}

/** One attachment timeline's keys in one animation, as the document lists them (`attachments: [{ name: skin, slots: [{ name, attachments: [{ name, deform?, sequence? }] }] }]`). */
function docAttachmentKeys(doc: Record<string, unknown>, animation: string, skin: string, slot: string, attachment: string, timeline: 'deform' | 'sequence'): Array<Record<string, unknown>> {
  type DocAttachment = { name: string } & Record<string, unknown>;
  const anim = (doc.animations as Array<{ name: string; attachments: Array<{ name: string; slots: Array<{ name: string; attachments: DocAttachment[] }> }> }>).find((a) => a.name === animation);
  const found = anim?.attachments.find((k) => k.name === skin)?.slots.find((x) => x.name === slot)?.attachments.find((a) => a.name === attachment)?.[timeline];
  if (!Array.isArray(found)) throw new Error(`the document's animation "${animation}" keys no ${timeline} on ${skin}/${slot}/${attachment}`);
  return found as Array<Record<string, unknown>>;
}

/**
 * Why a break of A09's roster has no model-side twin (issue #1054). The rows
 * that take the Spine file's `animations` out (`M97`, `M97b`, `M97c`) fire A09's
 * "the spec declares X but the skeleton has none", and `S03`'s stray animation
 * its "the skeleton has X with no spec entry": both clauses compare two
 * rosters — the motion spec's declared animations, which `validate()` is
 * handed, and the ones the Spine file holds. Until #1054 the model side was
 * handed the spec's roster too and its twin took the document's animations out
 * beside it. Now the model side reads the declared durations off the document
 * itself, where each animation is stated once with its declared duration on
 * it, so a document cannot state an animation declared and absent, or present
 * and undeclared — forged either way, the declared roster moves with the held
 * one, measured: the twin read SKIP and PASS where spine-core read FAIL. A10's
 * half of the `M97` rows keeps its twin (`SETUP_FROM_THE_BREAK`).
 */
const ANIMATION_ROSTER_ONLY: SingleTwin = {
  encodingOnly:
    "A09's roster clauses compare the motion spec's declared animations with the ones the Spine file holds; the document states each animation once, with its declared duration on it, and the model side reads both off it (issue #1054), so a declared animation the file lacks, or one the file holds and nobody declared, is a disagreement between the spec and the file that no document can state",
};

/** The setup numbers a bone states in the Spine file, under the document's field names — `inherit` is the document's `inheritMode`. */
const BREAK_BONE_FIELDS: ReadonlyArray<readonly [string, string]> = [['x', 'x'], ['y', 'y'], ['rotation', 'rotation'], ['scaleX', 'scaleX'], ['scaleY', 'scaleY'], ['shearX', 'shearX'], ['shearY', 'shearY'], ['inherit', 'inheritMode']];

/**
 * The twin of a break that edits the SETUP pose (issue #1025, cut 4c-5a): every
 * bone's setup number and every slot's colour as the broken Spine file states
 * it, where it differs from the document's, written into the document — read
 * off the break itself rather than restated beside it. A value JSON cannot
 * carry (`rotation: 1e309`, read back as Infinity) goes into the document as
 * the writer would write it, `null`, and the reader refuses it by the bone's
 * name; a finite one the reader admits (a scale chain past the largest double
 * in its product) is posed by the core, whose walk returns the non-finite
 * value in place.
 */
const SETUP_FROM_THE_BREAK: SingleTwin = {
  forge: (doc, call) => {
    const broken = JSON.parse(call.skeletonText) as { bones?: Array<Record<string, unknown>>; slots?: Array<Record<string, unknown>> };
    for (const bone of broken.bones ?? []) {
      const target = (doc.bones as Array<Record<string, unknown>>).find((b) => b.name === bone.name);
      if (target === undefined) continue;
      for (const [spineField, docField] of BREAK_BONE_FIELDS) if (bone[spineField] !== undefined && bone[spineField] !== target[docField]) target[docField] = bone[spineField];
    }
    for (const slot of broken.slots ?? []) {
      const target = (doc.slots as Array<Record<string, unknown>>).find((x) => x.name === slot.name);
      if (target !== undefined && slot.color !== undefined && slot.color !== target.color) target.color = slot.color;
    }
  },
};

/**
 * The twin of a break that sets one bone timeline of the Spine file's first
 * animation (issue #1025, cut 4c-5a: `M70`'s `inherit`, `M95`'s `rotate`): that
 * timeline's keys as the broken file states them, set on the same bone of the
 * same animation in the document, whose bone keys are spelled as the file's.
 */
function boneTimelineFromTheBreak(timeline: string): ModelTwin {
  return {
    forge: (doc, call) => {
      const animations = (JSON.parse(call.skeletonText) as { animations: Record<string, { bones?: Record<string, Record<string, Array<Record<string, unknown>>>> }> }).animations;
      const animation = Object.keys(animations)[0];
      const keyed = Object.entries(animations[animation].bones ?? {}).find(([, tls]) => tls[timeline] !== undefined);
      if (keyed === undefined) throw new Error(`the break keys no "${timeline}" in animation "${animation}"`);
      docSetTimeline(docBoneTimelineList(doc, animation, keyed[0], true), timeline, keyed[1][timeline].map((key) => ({ ...key })));
    },
  };
}

/** How a fault of the one walk opens (issue #1054): `the facts "<family>" (cut <cut>) differ …`, read back per cut by `walkFaults`. */
const FACT_FAULT = 'the facts';

/** The one walk's faults of one cut, each named with its case. */
function walkFaults(c: SupplierCheck, cut: FactCut): string[] {
  return c.faults.filter((f) => f.fault.startsWith(`${FACT_FAULT} "`) && f.fault.includes(`(cut ${cut}) differ`)).map((f) => `${f.case}: ${f.fault}`);
}

/**
 * The one floor (issue #1054): every family of every cut asked on the walk,
 * with a leaf value in spine-core's answers, and — where its facts answer
 * calls — called at least once. Before it the cuts held five floors of four
 * kinds (builds compared, numbers, posed calls, values); a family nothing asked
 * about is held by nothing whichever cut added it.
 */
function familyFloor(c: SupplierCheck): { probes: string[]; rows: string[] } {
  const probes: string[] = [];
  const rows: string[] = [];
  for (const cut of FACT_CUTS) {
    for (const family of FAMILIES_BY_CUT[cut]) {
      const t = c.families.get(family);
      if (t === undefined || t.questions === 0) {
        probes.push(`the family "${family}" (cut ${cut}) was asked nothing on this run`);
        continue;
      }
      if ((t.leaves ?? 0) === 0) probes.push(`the family "${family}" (cut ${cut}) was asked ${t.questions} question(s) and spine-core's answers held no value`);
      if ((t.methods ?? 0) > 0 && (t.calls ?? 0) === 0) probes.push(`the family "${family}" (cut ${cut}) answers ${t.methods} method(s) and was called 0 times`);
      rows.push(`${family} ${t.equal}/${t.questions} over ${t.leaves ?? 0} value(s), ${t.values} number(s)${(t.methods ?? 0) > 0 ? `, ${t.calls ?? 0} call(s)` : ''}`);
    }
  }
  return { probes, rows };
}

/** The run's supplier check. `validate` below feeds it; `main` attributes its findings to case lines; `runVerdictSuppliersSuite` reads it. */
const SUPPLIERS = new SupplierCheck();

/**
 * The model document a call with a compile behind it is handed (issue #1025):
 * `modelDocument` over the compile's model and skeleton and the atlas the build
 * wrote (the compile's, or the pack's). A document the writer refuses is
 * counted and named by `VF02` rather than thrown, so threading the model can
 * move no case's verdict; `validate()` reads `modelText` only beside `reEmit`.
 */
function threadedModel(result: Pick<CompileResult, 'model' | 'skeletonText'>, atlasText: string): string | undefined {
  try {
    return modelDocument(result.model, result.skeletonText, atlasText);
  } catch (err) {
    SUPPLIERS.unwritable.push((err as Error).message);
    return undefined;
  }
}


/**
 * `validate()`, with the supplier check beside every call (the section
 * header). The report is the runtime's and is returned untouched: nothing a
 * case reads moves.
 */
function validate(input: ValidateInput, twin?: ModelTwin): ValidateReport {
  const report = validateOverSpine(input);
  SUPPLIERS.observe(input, report, twin);
  return report;
}

interface Artifacts {
  skeletonText: string;
  atlasText: string;
}

interface Mutant {
  name: string;
  /** The silent failure this break reproduces, and where it was first seen. */
  origin: string;
  /**
   * The assertion that must fire — or `null` for an edit the gate must ACCEPT.
   *
   * ⚠️ The second kind is not decoration. Every time an assertion is WIDENED,
   * the risk moves from "it fires too rarely" to "it fires too often" and then
   * to "it no longer fires at all", and a suite made only of breaks cannot see
   * either end of that. A16 widening to accept `4.3.75-beta` is the first case:
   * the edit must be accepted, its 4.2 and 5.x neighbours must not.
   */
  expect: string | null;
  /**
   * Which rulebook to run the break against. Absent means `MUTANT_PROFILE`
   * (`rig-play`), the profile every other mutant in this file was written for
   * — the suite pins it rather than inheriting a default, so that flipping the
   * CLI's default (#221) cannot quietly stop a mutant's assertion from running
   * at all. A mutant that names a profile is asserting something about the SPLIT
   * rather than about one assertion — see M36a/M36b, the same edit under both.
   */
  profile?: ValidateProfile;
  /**
   * The break. `atlasDir` is the directory the gate resolves page names
   * against, for a break that has to put BYTES on disk rather than edit a text
   * (issue #1064: a page that is present and not a PNG). Every other row
   * ignores it.
   */
  mutate: (a: Artifacts, atlasDir: string) => Artifacts;
  /**
   * The rig info to gate the break under, derived from the pristine build's —
   * for a rule that reads a DECLARATION as well as the file (issue #855: A15
   * reads `invariants.idleDrivesMeshes`). Absent means the pristine rig info,
   * which is what every other row runs under. That the declaration reaches
   * `RigInfo` from a rig spec at all is the rig suite's control, not this one.
   */
  rig?: (rig: CompileResult['rig']) => CompileResult['rig'];
  /**
   * A further reading the report must satisfy beyond which assertion fired,
   * with what was read either way — printed under the verdict, so a pass shows
   * the figures it passed on. For a verdict whose TEXT is the product: a count,
   * a hint that must appear exactly once.
   */
  holds?: (report: ReturnType<typeof validate>, broken: Artifacts) => { held: boolean; read: string };
  /**
   * The model-side twin of this break (issue #1025): the same wrongness forged
   * into the pristine build's model document, or the reason no model field can
   * carry it. Required of a row whose break FAILS an assertion the model side
   * runs (`MOVED_ASSERTIONS`) — the supplier check runs the twin beside the
   * break and records whether the model side printed the identical line or
   * refused the forged document by the same object's name; a firing row with
   * no twin is named by `VF03`. Rows aimed at an assertion still on the round
   * trip alone need none.
   */
  twin?: ModelTwin;
}

const editJson = (text: string, f: (j: Record<string, unknown>) => void): string => {
  const j = JSON.parse(text) as Record<string, unknown>;
  f(j);
  return `${JSON.stringify(j, null, 2)}\n`;
};

/**
 * What A15 should report a declared idle as costing, read off the skeleton TEXT
 * rather than the loaded data A15 reads (issue #855): which of `keyed` drive a
 * mesh, how many mesh attachments they drive, and how many vertices those hold.
 *
 * A mesh's drivers are its slot's bone and every bone its weights name; its
 * vertex count is `uvs.length / 2`, which the file states whatever the vertex
 * encoding. The weight walk is the file's own: when `vertices` is longer than
 * `uvs` each vertex is `count` followed by `count` runs of (bone, x, y, weight).
 */
function idleMeshCost(skeletonText: string, keyed: string[]): { bones: string[]; meshes: number; vertices: number } {
  const j = JSON.parse(skeletonText) as {
    bones: Array<{ name: string }>;
    slots: Array<{ name: string; bone: string }>;
    skins: Array<{ attachments?: Record<string, Record<string, { type?: string; uvs?: number[]; vertices?: number[] }>> }>;
  };
  const slotBone = new Map(j.slots.map((slot) => [slot.name, slot.bone]));
  const want = new Set(keyed);
  const driving = new Set<string>();
  let meshes = 0;
  let vertices = 0;
  for (const skin of j.skins) {
    for (const [slot, table] of Object.entries(skin.attachments ?? {})) {
      for (const att of Object.values(table)) {
        if (att.type !== 'mesh' || !att.uvs || !att.vertices) continue;
        const drivers = new Set<string>([slotBone.get(slot) ?? '']);
        if (att.vertices.length > att.uvs.length) {
          for (let i = 0; i < att.vertices.length; ) {
            const count = att.vertices[i++];
            for (let n = 0; n < count; n++, i += 4) drivers.add(j.bones[att.vertices[i]].name);
          }
        }
        const hit = [...drivers].filter((name) => want.has(name));
        if (hit.length === 0) continue;
        for (const name of hit) driving.add(name);
        meshes++;
        vertices += att.uvs.length / 2;
      }
    }
  }
  return { bones: keyed.filter((name) => driving.has(name)), meshes, vertices };
}

/** The why every A15 declaration row below declares. */
const IDLE_DRIVES_WHY = 'a painting rig: the idle sways every layer on purpose';

/** The overlay probe's idle keying its iris mesh's slot bone AND its control bone — two bones that drive a mesh. */
/** The `bones` group `keyIrisInIdle` gives `idle` — one value, so M91's twin keys what its break keys (issue #1025, cut 4c-1). */
const IRIS_IDLE_BONES: Record<string, Record<string, unknown[]>> = {
  iris: { rotate: [{ time: 0, value: 0 }, { time: 1, value: 4 }] },
  iris_aperture: { scale: [{ time: 0, x: 1, y: 1 }] },
};
const keyIrisInIdle = (a: Artifacts): Artifacts => ({
  ...a,
  skeletonText: editJson(a.skeletonText, (j) => {
    const idle = (j.animations as Record<string, Record<string, unknown>>).idle;
    idle.bones = structuredClone(IRIS_IDLE_BONES);
  }),
});

/** A string no emitted file carries, swapped for a literal JSON reads as Infinity (`1e309`). */
const OVERFLOW_TOKEN = '__rigc_overflow__';

type EmittedBone = { name: string; parent?: string } & Record<string, unknown>;

/**
 * The first bone with a parent that no bone hangs from — or, with `chained`,
 * the first such bone whose parent has a parent of its own, so a scale set on
 * both is a chain below the root.
 */
function leafBoneOf(bones: EmittedBone[], chained = false): EmittedBone {
  const leaf = bones.find(
    (b) =>
      b.parent !== undefined &&
      !bones.some((c) => c.parent === b.name) &&
      (!chained || bones.some((p) => p.name === b.parent && p.parent !== undefined)),
  );
  if (leaf === undefined) throw new Error(`the fixture has no leaf bone${chained ? ' under a non-root parent' : ''} to plant on`);
  return leaf;
}

/** The leaf a plant below edits, read back off the broken text. */
const leafOf = (a: Artifacts, chained = false): string =>
  leafBoneOf((JSON.parse(a.skeletonText) as { bones: EmittedBone[] }).bones, chained).name;

/** The first animation the emitted file declares. */
const firstAnimationOf = (a: Artifacts): string =>
  Object.keys((JSON.parse(a.skeletonText) as { animations: Record<string, unknown> }).animations)[0];

/** The emitted skeleton with `edit` applied to its first leaf bone, and every `OVERFLOW_TOKEN` written as `1e309`. */
function plantOverflow(text: string, edit: (j: Record<string, unknown>, leaf: EmittedBone) => void): string {
  return editJson(text, (j) => edit(j, leafBoneOf(j.bones as EmittedBone[]))).replaceAll(`"${OVERFLOW_TOKEN}"`, '1e309');
}

/** The emitted skeleton with `scaleX: factor` on a leaf bone and on its non-root parent. */
function plantScaleChain(text: string, factor: number): string {
  return editJson(text, (j) => {
    const bones = j.bones as EmittedBone[];
    const leaf = leafBoneOf(bones, true);
    leaf.scaleX = factor;
    const parent = bones.find((b) => b.name === leaf.parent);
    if (parent !== undefined) parent.scaleX = factor;
  });
}

/** Does an A10 failure carry every one of `parts`? The detail is the reading either way. */
function a10Names(report: ReturnType<typeof validate>, ...parts: string[]): { held: boolean; read: string } {
  const details = report.failures.filter((f) => f.assertion === 'A10_NO_NAN_AFTER_STEPPING').map((f) => f.detail);
  const held = details.some((d) => parts.every((p) => d.includes(p)));
  return { held, read: held ? `A10 names ${JSON.stringify(parts)}` : `A10 said ${JSON.stringify(details)}, not ${JSON.stringify(parts)}` };
}

/**
 * Is A10's one detail exactly `sentence` — or, with `whole: false`, does it open
 * with it? The prefix form is only for a sentence that goes on to quote the
 * runtime's own mode table, which is not a row's to restate. Issue #902 is why
 * M94 and M95b read this way rather than through `a10Names`: #902 moved where
 * the setup pose is posed, and "the sentence on an animated rig did not move"
 * is a claim only a whole-sentence comparison can hold.
 */
function a10Is(report: ReturnType<typeof validate>, sentence: string, whole = true): { held: boolean; read: string } {
  const details = report.failures.filter((f) => f.assertion === 'A10_NO_NAN_AFTER_STEPPING').map((f) => f.detail);
  const held = details.length === 1 && (whole ? details[0] === sentence : details[0].startsWith(sentence));
  return {
    held,
    read: held
      ? `A10 says ${JSON.stringify(sentence)}${whole ? ', whole' : ' …'}`
      : `A10 said ${JSON.stringify(details)}, not one detail ${whole ? 'reading' : 'opening'} ${JSON.stringify(sentence)}`,
  };
}

/**
 * `a10Is` on a static rig, and the stats line saying the stepping clause had
 * nothing to step (issue #902) — the half of the reading a PASS row, which
 * carries no detail, can only give there.
 */
function a10SaysOnAStaticRig(report: ReturnType<typeof validate>, sentence: string, whole = true): { held: boolean; read: string } {
  const said = a10Is(report, sentence, whole);
  const stepping = report.stats.nanStepping;
  return {
    held: said.held && stepping === 'skipped',
    read: `${said.read}; the stats line has nanStepping=${String(stepping)}${stepping === 'skipped' ? '' : ', not skipped'}`,
  };
}

/**
 * Issue #1205's probe chain: the first three bones `[a, b, c]` where `c` is a
 * child of `b`, `b` of `a`, and `a` is not the root — spine-core throws posing
 * an ik whose first bone is the root, which would be a different refusal.
 * Found structurally, so a fixture edit moves the probe rather than breaking it.
 */
function ikProbeChain(bones: ReadonlyArray<{ name: string; parent?: string }>): [string, string, string] {
  for (const c of bones) {
    const b = bones.find((x) => x.name === c.parent);
    const a = bones.find((x) => x.name === b?.parent);
    if (b !== undefined && a !== undefined && a.parent !== undefined) return [a.name, b.name, c.name];
  }
  throw new Error('the fixture holds no chain of three bones below its root');
}

/**
 * One break of issue #1205: ik constraints over `pick(chain)` reaching for the
 * root at mix 1 — live, so the mute clause has nothing to say — forged into
 * the Spine file and, as the twin, into the model document.
 */
function ikShapeBreak(constraints: ReadonlyArray<{ name: string; pick: (chain: [string, string, string]) => string[] }>): Pick<Mutant, 'twin' | 'mutate'> {
  const forged = (bones: ReadonlyArray<{ name: string; parent?: string }>): Array<{ name: string; bones: string[]; target: string }> =>
    constraints.map((c) => ({ name: c.name, bones: c.pick(ikProbeChain(bones)), target: bones[0].name }));
  return {
    twin: {
      forge: (doc) => {
        for (const c of forged(doc.bones as Array<{ name: string; parent?: string }>)) (doc.constraints as DocRecord[]).push({ kind: 'ik', declaredIn: 'rig', ...c, mix: 1 });
      },
    },
    mutate: (a) => ({
      ...a,
      skeletonText: editJson(a.skeletonText, (j) => {
        const list = (Array.isArray(j.constraints) ? j.constraints : []) as unknown[];
        j.constraints = [...list, ...forged(j.bones as Array<{ name: string; parent?: string }>).map((c) => ({ type: 'ik', ...c, mix: 1 }))];
      }),
    }),
  };
}

/** A47's lines on a report, and whether exactly one of them opens with `head` and carries `tail`. */
function oneA47Line(report: ReturnType<typeof validate>, head: string, tail: string): { held: boolean; read: string } {
  const lines = report.failures.filter((f) => f.assertion === 'A47_IK_CONSTRAINT_NOT_MUTED_THROUGHOUT').map((f) => f.detail);
  return {
    held: lines.length === 1 && lines[0].startsWith(head) && lines[0].includes(tail),
    read: `${lines.length} A47 line(s)${lines.length ? `: ${lines.join(' | ')}` : ''}`,
  };
}

/** A physics record's value as the parser reads it: the record's number, or the parser's default where it states none. */
function physicsValue(record: Record<string, unknown>, field: 'fps' | 'mass' | 'damping' | 'strength'): number {
  const v = record[field];
  return typeof v === 'number' ? v : PHYSICS_DEFAULTS[field];
}

/**
 * The strength that puts a physics record's step exactly on A23's stability
 * bound (issue #1416, part B), at the record's own fps, mass and damping:
 * `bound / (step · massInverse · step)`, the bound read off
 * `physicsStepStability` rather than restated. The edge mutants stand a
 * relative nudge either side of it, so the line they test is the formula's and
 * no number in them was tuned.
 */
function strengthOnTheStabilityBound(record: Record<string, unknown>): number {
  const step = 1 / physicsValue(record, 'fps');
  const massInverse = 1 / physicsValue(record, 'mass');
  return physicsStepStability(1, massInverse, physicsValue(record, 'damping'), step).bound / (step * massInverse * step);
}

/**
 * The stability clause's line for the broken skeleton's first physics
 * constraint, derived from the values the break left in the file: exactly one
 * A23 line, naming the constraint, the fps, and `k` and the bound as
 * `physicsStepStability` forms them — so the reading holds the sentence to the
 * formula, not to a number copied from a run.
 */
function oneStabilityLine(report: ReturnType<typeof validate>, broken: Artifacts, opens: (name: string) => string, keyed?: { strength: number; time: string }): { held: boolean; read: string } {
  const doc = JSON.parse(broken.skeletonText) as { constraints: Array<Record<string, unknown>> };
  const c = doc.constraints.find((x) => x.type === 'physics');
  if (c === undefined) return { held: false, read: 'the broken skeleton declares no physics constraint' };
  const strength = keyed === undefined ? physicsValue(c, 'strength') : Math.fround(keyed.strength);
  const at = physicsStepStability(strength, 1 / physicsValue(c, 'mass'), physicsValue(c, 'damping'), 1 / physicsValue(c, 'fps'));
  const lines = report.failures.filter((f) => f.assertion === 'A23_PHYSICS_CONSTRAINT_EFFECTIVE').map((f) => f.detail);
  const want = [opens(String(c.name)), `fps ${physicsValue(c, 'fps')}`, ...(keyed === undefined ? [] : [`(the key at t=${keyed.time}s)`])];
  // The two printed numbers are read back: each must be `k` and the bound at the
  // places printed, and they must print apart exactly when they differ — so a
  // value a part in 10⁹ past the bound cannot read as equal to it.
  const printed = lines.length === 1 ? /strength·massInverse·step² = ([0-9.]+) must be < 2·\(1 \+ damping\^\(60·step\)\) = ([0-9.]+)/.exec(lines[0]) : null;
  const places = printed === null ? 0 : (printed[1].split('.')[1] ?? '').length;
  const numbersHold =
    printed !== null &&
    printed[1] === at.k.toFixed(places) &&
    printed[2] === at.bound.toFixed(places) &&
    places >= 4 &&
    (printed[1] === printed[2]) === (at.k === at.bound);
  return {
    held: !at.stable && numbersHold && lines.length === 1 && lines[0].startsWith(want[0]) && want.every((w) => lines[0].includes(w)),
    read: `k ${at.k} against bound ${at.bound}, printed ${printed === null ? 'unread' : `${printed[1]} against ${printed[2]}`}; ${lines.length} A23 line(s)${lines.length ? `: ${lines.join(' | ')}` : ''}`,
  };
}

/**
 * Exactly as many A23 lines as `opens` names, the i-th opening with `opens[i]`
 * and every one carrying each of `carries` (issue #1422) — the reading for a
 * break whose verdict is a sentence about one value, where `oneStabilityLine`
 * reads `k` and the bound.
 */
function a23LinesSay(report: ReturnType<typeof validate>, opens: readonly string[], carries: readonly string[]): { held: boolean; read: string } {
  const lines = report.failures.filter((f) => f.assertion === 'A23_PHYSICS_CONSTRAINT_EFFECTIVE').map((f) => f.detail);
  const held = lines.length === opens.length && lines.every((line, i) => line.startsWith(opens[i]) && carries.every((c) => line.includes(c)));
  return { held, read: `${lines.length} A23 line(s), ${opens.length} wanted${lines.length ? `: ${lines.join(' | ')}` : ''}` };
}

/** The damping row's reason at 1, as the row states it — read off the row rather than retyped, so the mutants hold the sentence to the table. */
function dampingAt1Says(): string {
  const arm = physicsRuleFor('damping')?.basis.find((one) => one.when(1));
  return arm === undefined ? 'no damping arm holds for 1' : arm.kind === 'arithmetic' ? arm.expression : arm.does;
}

/**
 * The largest double below 1, and the first rate at which the runtime's own
 * `damping ** (60 * step)` rounds it to exactly 1 (issue #1422) — the rate is
 * found, not typed: the walk stops at the first fps from 60 where the decay is 1.
 */
const DAMPING_JUST_BELOW_1 = 1 - Number.EPSILON / 2;
const FPS_WHERE_THE_DECAY_ROUNDS_TO_1 = ((): number => {
  for (let fps = 60; fps < 100000; fps++) if (DAMPING_JUST_BELOW_1 ** (60 * (1 / fps)) === 1) return fps;
  return Number.NaN;
})();

