/**
 * Re-file the default skin under the named skin `worn` — its attachments and
 * every animation's attachment timelines keyed on it — leaving no default skin,
 * or an empty one first when `emptyDefault` (M84, M85). Throws when there is no
 * default skin to move, so an edit that moved nothing cannot pass for accepted.
 */
function refileDefaultSkinAsNamed(j: Record<string, unknown>, emptyDefault: boolean): void {
  const skins = (Array.isArray(j.skins) ? j.skins : []) as Array<{ name: string }>;
  const held = skins.find((skin) => skin.name === 'default');
  if (held === undefined) throw new Error('the fixture declares no default skin to re-file');
  held.name = 'worn';
  const rest = skins.filter((skin) => skin !== held);
  j.skins = [...(emptyDefault ? [{ name: 'default', attachments: {} }] : []), ...rest, held];
  for (const animation of Object.values((j.animations ?? {}) as Record<string, { attachments?: Record<string, unknown> }>)) {
    if (animation.attachments?.default === undefined) continue;
    animation.attachments.worn = animation.attachments.default;
    delete animation.attachments.default;
  }
}

/**
 * Move the first region attachment that states no `path` — and whose key no
 * animation mentions — to the key `<key>_filed`, re-pointing its slot's setup
 * attachment, and state the old key as its `name` or not (M82, M83).
 */
function rekeyFirstRegion(j: Record<string, unknown>, keepName: boolean): void {
  const skins = (Array.isArray(j.skins) ? j.skins : []) as Array<{ attachments?: Record<string, Record<string, Record<string, unknown>>> }>;
  const animations = JSON.stringify(j.animations ?? {});
  const slots = (Array.isArray(j.slots) ? j.slots : []) as Array<{ name: string; attachment?: string }>;
  for (const skin of skins) {
    for (const [slotName, table] of Object.entries(skin.attachments ?? {})) {
      for (const [key, att] of Object.entries(table)) {
        if ((att.type ?? 'region') !== 'region' || att.path !== undefined || att.name !== undefined) continue;
        if (animations.includes(JSON.stringify(key))) continue;
        const filed = `${key}_filed`;
        delete table[key];
        table[filed] = keepName ? { name: key, ...att } : att;
        for (const slot of slots) if (slot.name === slotName && slot.attachment === key) slot.attachment = filed;
        return;
      }
    }
  }
  throw new Error('the fixture has no region with no `path` that no animation names — the mutant would prove nothing');
}

/**
 * `rekeyFirstRegion(j, false)`'s re-filing, carried into the model document
 * (issue #1025, cut 4c-1): the record the break re-filed — read off the broken
 * skeleton, where it now stands under `<key>_filed` — moved to the same key in
 * the document's skin, and every slot whose setup showed it pointed at the new
 * key. Read off the break rather than re-chosen, because the choice walks the
 * Spine file's animation text, which names placeholders the document spells
 * elsewhere (measured: the two walks pick different records on the overlay
 * probe).
 */
function docRekeyFiledRegion(doc: Record<string, unknown>, call: { skeletonText: string }): void {
  const broken = JSON.parse(call.skeletonText) as { skins: Array<{ name: string; attachments: Record<string, Record<string, unknown>> }> };
  const slots = doc.slots as Array<{ name: string; setup: string | null }>;
  for (const skin of broken.skins) {
    for (const [slotName, table] of Object.entries(skin.attachments)) {
      for (const filed of Object.keys(table)) {
        if (!filed.endsWith('_filed')) continue;
        const key = filed.slice(0, -'_filed'.length);
        const own = docSkin(doc, skin.name).attachments[slotName];
        if (own?.[key] === undefined) continue;
        own[filed] = own[key];
        delete own[key];
        for (const slot of slots) if (slot.name === slotName && slot.setup === key) slot.setup = filed;
        return;
      }
    }
  }
  throw new Error('the broken skeleton holds no re-filed record the document has under its old key');
}

/**
 * Forge an open path onto the skeleton — a second attachment `forged_track`
 * under the first skin's first slot, `PATH_TRACK`'s geometry, so no slot table
 * or setup pose changes — whose `lengths` is the transcription's own
 * measurement over the closed chain with its last `drop` entries cut (M86, M87).
 */
function forgeMeasuredPath(j: Record<string, unknown>, drop: number): void {
  const skins = (Array.isArray(j.skins) ? j.skins : []) as Array<{ attachments?: Record<string, Record<string, unknown>> }>;
  const slot = Object.keys(skins[0]?.attachments ?? {})[0];
  if (slot === undefined) throw new Error('the fixture has no skinned slot to forge a path under');
  const measured = runtimeCurveLengths(pathChainOf(PATH_TRACK.vertices, true)).map((n) => Math.fround(n));
  if (measured.length !== PATH_TRACK.vertexCount / 3 || drop >= measured.length) {
    throw new Error(`the transcription measured ${measured.length} entries for a ${PATH_TRACK.vertexCount}-vertex path — the cut would prove nothing`);
  }
  skins[0].attachments![slot].forged_track = {
    type: 'path',
    vertexCount: PATH_TRACK.vertexCount,
    vertices: PATH_TRACK.vertices,
    lengths: measured.slice(0, measured.length - drop),
  };
}


