        const unmeasured = abReduce({ ...pinned, ...delaunay }, 'flips-against-delaunay-unmeasured');
        const brief = (t: Retriangulation | undefined): string => JSON.stringify(t === undefined ? t : { ...t, monotonicity: '…' });
        const ta = retriOf(against);
