/**
 * The gallery examples this run compiles and gates, derived once and read twice.
 *
 * 🔒 `runGallerySuite` and `CUR13`/`CUR14` below have to answer the same
 * question — *which examples does this repository have?* — and issue #520 is
 * what two answers cost. `README.md`'s table was a second, hand-kept copy of
 * this set and went one row short: `gallery/look`, the only example that stars a
 * `slider`, was compiled and gated by every run and named by the front page in
 * no row at all. One function, so the comparison below is against the set rather
 * than against a paraphrase of it.
 */
function galleryExampleNames(galleryRoot: string): string[] {
  if (!existsSync(galleryRoot)) return [];
  return readdirSync(galleryRoot)
    .filter(
      (name) => existsSync(join(galleryRoot, name, 'rig.json')) && existsSync(join(galleryRoot, name, 'motion.json')),
    )
    .sort();
}

/** The constraint kinds one example's rig spec declares, wherever in it they are declared. */
function galleryConstraintKinds(galleryRoot: string, example: string): string[] {
  const kinds = new Set<string>();
  const walk = (node: unknown): void => {
    if (Array.isArray(node)) {
      for (const item of node) walk(item);
      return;
    }
    if (node === null || typeof node !== 'object') return;
    for (const [key, value] of Object.entries(node as Record<string, unknown>)) {
      if (key === 'constraints' && Array.isArray(value)) {
        for (const c of value) {
          const kind = (c as { type?: unknown }).type;
          if (typeof kind === 'string') kinds.add(kind);
        }
      }
      walk(value);
    }
  };
  walk(JSON.parse(readFileSync(join(galleryRoot, example, 'rig.json'), 'utf8')) as unknown);
  return [...kinds].sort();
}

/** One row of a gallery index table: the directory its first cell names, and its `Stars` cell. */
interface GalleryIndexRow {
  example: string;
  /** The cell under the `Stars` column, or null when the table declares no such column. */
  stars: string | null;
}

/** A document that indexes the gallery, as that document states it. */
interface GalleryIndex {
  path: string;
  /** The header line, verbatim, or null when the document carries no index table at all. */
  header: string | null;
  /** The nearest heading above the table — where a COUNT of the examples gets written. */
  heading: string | null;
  rows: GalleryIndexRow[];
  /** Rows whose first cell names no gallery directory. Reported, never skipped. */
  unread: string[];
}

/** Number words, so a count stated in prose can be compared with one the tree produced. */
const NUMBER_WORDS: readonly string[] = [
  'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten',
  'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen', 'eighteen', 'nineteen', 'twenty',
];

/**
 * The gallery index table in one document, read as the document writes it.
 *
 * ⚠️ The header is matched on its FIRST column only (`| Example |`), so renaming
 * `Stars` or `What it is` does not quietly drop the document out of the
 * population — the `Stars` column is then reported absent by name instead. What
 * a first column of `Example` cannot survive is being renamed itself, and the
 * floor in `CUR13` is what makes that loud rather than silent: `README.md` has to
 * come back carrying an index, so a restructured front page fails the case
 * rather than narrowing it to nothing.
 */
function readGalleryIndex(path: string, text: string): GalleryIndex {
  const raw = text.split('\n');
  const cellsOf = (line: string): string[] =>
    line.replace(/^\s*\|/, '').replace(/\|\s*$/, '').split('|').map((cell) => cell.trim());
  const at = raw.findIndex((line) => /^\s*\|\s*Example\s*\|/.test(line));
  if (at < 0) return { path, header: null, heading: null, rows: [], unread: [] };
  const header = cellsOf(raw[at]);
  const starsAt = header.findIndex((cell) => cell === 'Stars');
  let heading: string | null = null;
  for (let i = at - 1; i >= 0; i--) {
    if (/^#{1,6}\s/.test(raw[i])) {
      heading = raw[i];
      break;
    }
  }
  const rows: GalleryIndexRow[] = [];
  const unread: string[] = [];
  for (let i = at + 1; i < raw.length && /^\s*\|/.test(raw[i]); i++) {
    if (/^\s*\|[\s:|-]+$/.test(raw[i])) continue; // the alignment row under the header
    const cells = cellsOf(raw[i]);
    const span = /`([^`]+)`/.exec(cells[0] ?? '');
    const named = span === null ? null : span[1].replace(/\/+$/, '').replace(/^gallery\//, '');
    if (named === null || !/^[\w-]+$/.test(named)) {
      unread.push(`${path}:${i + 1} a row whose first cell names no gallery directory — ${raw[i].trim().slice(0, 72)}`);
      continue;
    }
    rows.push({ example: named, stars: starsAt < 0 ? null : (cells[starsAt] ?? null) });
  }
  return { path, header: raw[at], heading, rows, unread };
}

/**
 * What one index document gets wrong about the set of examples, by name.
 *
 * Set equality in both directions, never a count and never a containment: a
 * clause reading *at least one row* is green on a table that lost five (#451),
 * and a clause reading *every row resolves* is green on the table this case was
 * written for, which lost a row rather than gaining a wrong one.
 *
 * 🔸 The heading clause is the third thing #520 found and the reason it is
 * shaped the way it is: the front page said **six** in the heading over a table
 * of six rows over a tree of seven examples, so the figure and the list were
 * wrong together and neither could catch the other. It faults NOTHING when the
 * heading states no number word — the outcome a document is allowed to reach by
 * deleting the figure, which is this repository's usual repair for a hand-kept
 * count and must not be the one outcome that goes red.
 */
function galleryIndexFaults(index: GalleryIndex, examples: readonly string[]): string[] {
  if (index.header === null) {
    return [`${index.path} carries no gallery index table — no row opens with \`| Example |\``];
  }
  const faults = [...index.unread];
  const stated = [...new Set(index.rows.map((row) => row.example))].sort();
  for (const name of examples) {
    if (!stated.includes(name)) {
      faults.push(`${index.path}: gallery/${name} is compiled and gated by this run and the index names no row for it`);
    }
  }
  for (const name of stated) {
    if (!examples.includes(name)) {
      faults.push(`${index.path}: the index names gallery/${name} and the tree holds no example by that name`);
    }
  }
  const said = index.heading === null ? -1 : NUMBER_WORDS.findIndex((word) => new RegExp(`\\b${word}\\b`, 'i').test(index.heading ?? ''));
  if (said >= 0 && said !== stated.length) {
    faults.push(
      `${index.path}: the heading over the table says "${NUMBER_WORDS[said]}" and the table has ${stated.length} row(s) — ` +
        `"${(index.heading ?? '').trim()}"`,
    );
  }
  return faults;
}

/**
 * Every module a file under `src/` imports from outside `src/`, repo-relative.
 *
 * This is the set `CLAUDE.md`'s package bullet states, and the rule it states it
 * for: a module here that is not in `files` installs as a `Cannot find module`
 * on the command that needs it, while the repository itself goes on running.
 */
function modulesSrcReachesOutsideItself(root: string): string[] {
  const out = new Set<string>();
  for (const file of trackedIn(root, 'src', (name) => name.endsWith('.ts')).map((path) => basename(path))) {
    const text = readFileSync(join(root, 'src', file), 'utf8');
    for (const m of text.matchAll(/(?:from|import)\s*'(\.\.?\/[^']+)'/g)) {
      const resolved = relative(root, resolve(join(root, 'src'), m[1])).split('\\').join('/');
      if (!resolved.startsWith('src/')) out.add(resolved);
    }
  }
  return [...out].sort();
}

// ---------------------------------------------------------------------------
// the shipped closure (issue #1061) — CUR113–CUR115's instruments
// ---------------------------------------------------------------------------

/** What `coreClosureFrom` returns: every module reached by value with the module it was first reached from, the runtime's linkers among them, and every reached path the population does not hold. */
interface CoreClosure {
  modules: string[];
  via: ReadonlyMap<string, string | null>;
  linkers: Array<{ module: string; chain: string[] }>;
  problems: string[];
}

/** The static value closure of `roots` over `population`, breadth first, so each module's recorded chain is a shortest one. */
function coreClosureFrom(population: ReadonlyMap<string, string>, roots: readonly string[]): CoreClosure {
  const via = new Map<string, string | null>();
  const queue: string[] = [];
  for (const r of roots) {
    if (via.has(r)) continue;
    via.set(r, null);
    queue.push(r);
  }
  const linkers: Array<{ module: string; chain: string[] }> = [];
  const chainOf = (module: string): string[] => {
    const chain: string[] = [];
    for (let at: string | null = module; at !== null; at = via.get(at) ?? null) chain.unshift(at);
    return chain;
  };
  while (queue.length > 0) {
    const rel = queue.shift() as string;
    const text = population.get(rel);
    if (text === undefined) continue;
    for (const { spec, typeOnly } of specifiersOf(codeOnly(text))) {
      if (typeOnly) continue;
      if (/^@esotericsoftware\/spine-core(\/|$)/.test(spec)) {
        if (!linkers.some((l) => l.module === rel)) linkers.push({ module: rel, chain: [...chainOf(rel), spec] });
        continue;
      }
      if (!spec.startsWith('.')) continue;
      const target = join(dirname(rel), spec).split('\\').join('/');
      if (!via.has(target)) {
        via.set(target, rel);
        queue.push(target);
      }
    }
  }
  const problems = [...via.keys()].filter((m) => !population.has(m)).map((m) => `${m} is reached (${chainOf(m).join(' > ')}) and is not in the population read`);
  return { modules: [...via.keys()].filter((m) => population.has(m)).sort(), via, linkers, problems };
}

/** `population` with `line` added at the top of `rel` — a plant, on a copy. */
function plantedInto(population: ReadonlyMap<string, string>, rel: string, line: string): Map<string, string> {
  const out = new Map(population);
  out.set(rel, `${line}\n${population.get(rel) ?? ''}`);
  return out;
}

/** A closure's members counted by directory, with the top-level `src/` and `tools/` members named — the reading the next cut takes. */
function closureByDirectory(modules: readonly string[]): string {
  const core = modules.filter((m) => m.startsWith('src/core/')).length;
  const assertions = modules.filter((m) => m.startsWith('src/assertions/')).length;
  const top = modules.filter((m) => m.startsWith('src/') && !m.slice(4).includes('/'));
  const other = modules.filter((m) => !m.startsWith('src/'));
  const rest = modules.length - core - assertions - top.length - other.length;
  return `src/core/ ${core}, src/assertions/ ${assertions}, src/ ${top.length} [${top.map((m) => m.slice(4)).join(', ')}]${rest > 0 ? `, other src/ subdirectories ${rest}` : ''}, outside src/ ${other.length} [${other.join(', ')}]`;
}

/**
 * The runtime's YAML reader, or `null` on a Bun that has none (issue #1482).
 *
 * `Bun.YAML` was measured absent on Bun 1.2.0 (then the declared minimum,
 * `typeof Bun.YAML` is `undefined`) and present on the Bun this tree is
 * developed on. No YAML reader is in the dependency tree to fall back to, and a
 * second parser would change what the workflow controls read — so a control
 * that reads a workflow as YAML asks `BUN_YAML` first and, without it, prints a
 * SKIP by name and a HOLE (`reportYamlHole`). A SKIP line is not a control line
 * to the tally, so the run never counts it as a pass.
 *
 * Read through a structural type rather than `Bun.YAML` directly, because the
 * declarations this tree compiles against say the reader is always there.
 */
const BUN_YAML: { parse(input: string): unknown } | null = ((): { parse(input: string): unknown } | null => {
  const runtime: { YAML?: { parse(input: string): unknown } } = Bun;
  return runtime.YAML ?? null;
})();

/**
 * `BUN_YAML.parse`, throwing by name when the reader is absent. Every caller
 * sits behind a `BUN_YAML === null` guard; a call that ever reached here
 * without one would read as that control's "does not parse" FAIL, not a crash
 * of the whole suite and never a pass.
 */
function readYaml(input: string): unknown {
  if (BUN_YAML === null) throw new Error(`Bun.YAML is absent on Bun ${Bun.version}`);
  return BUN_YAML.parse(input);
}

/** The SKIP and HOLE lines of a control that reads a workflow as YAML on a Bun with no `Bun.YAML` (issue #1482). */
function reportYamlHole(name: string): void {
  console.log(`  SKIP  ${name}  (Bun.YAML is absent on Bun ${Bun.version}; this control reads the workflows as YAML)`);
  console.log(`          ⚠️ This is a HOLE in this run, not a pass — run it on a Bun that has Bun.YAML.`);
}

function runCurrencySuite(): number {
  console.log('\n── what a shipped or landing doc STATES about the tool (issue #360) ──');
  let bad = 0;
  const say = (name: string, ok: boolean, detail: string, why: string): void => {
    bad += reportCase(name, ok, detail, why);
  };

  const root = import.meta.dir;
  const packageName = packageNameOf(root);
  const pkg = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8')) as { files?: string[] };
  const allowlist = pkg.files ?? [];
  const { shipped, unreadable } = expandShippedSet(root, allowlist);
  const shipsToo = (path: string): boolean =>
    shipped.has(path) || [...shipped].some((file) => file.startsWith(`${path}/`));
  const docs = currencyDocs(root, shipped);
  const truth = currencyTruth(root);

  const scan = emptyScan();
  for (const doc of docs) {
    mergeScan(scan, scanAssertionTallies(doc, truth));
    mergeScan(scan, scanGateVersion(doc, truth));
    mergeScan(scan, scanWorkedCases(doc, truth, root));
    mergeScan(scan, scanNamedThings(doc, shipsToo, packageName));
  }
  const sitesOf = (limb: string): number => scan.sites.get(limb) ?? 0;
  const tallySites = [...scan.sites].filter(([limb]) => limb.startsWith('tally:'));

  // --- CUR01: the derivation floor ------------------------------------------
  // PKG01's argument, one class over. Every step here can come back empty — a
  // `files` array read as absent, a landing scan that resolves nothing, a form
  // that no longer matches its own phrasing, a gallery with no motion specs, a
  // GATE.md header that moved — and each of those makes a case below pass while
  // reading nothing.
  const markedWithoutDate = docs.filter((doc) => doc.dated && doc.headerDate === null);
  const markedReadme = docs.filter((doc) => doc.dated && doc.path === 'README.md');
  const thinForms = tallySites.filter(([, n]) => n === 0);
  const marked = docs.filter((doc) => doc.dated);
  const misdeclared = docs.filter((doc) => doc.misdeclared !== null);
  // 🔸 `floorProbes` inside `probeDetail` rather than `RD02`'s line (issue
  // #498). Nine of the twenty-four terms are the derivation floors and the
  // detail's selector read none of them, and the shape of the miss is the one
  // this control exists for: `sitesOf` reads a Map, so a limb that matched
  // NOTHING has no entry to print and drops out of `Sites read:` altogether.
  // Planted with the installed-path form spelled `spine-rigd`, the old sentence
  // printed a full, true-looking report with `installed path` simply absent —
  // silent about the only failure the control is built to catch. Nine floors is
  // exactly what `floorProbes` is for, and the branches that already existed
  // become rows rather than a chain in which only the first one prints.
  //
  // ⚠️ `> 0` is written `>= 1` in the table: these are counts off a Map, so the
  // two are the same condition and `floorProbes` states a floor.
  const currencyProbes = [
    ...(misdeclared.length > 0
      ? [
          `a header line opens with the dated-record marker's lead and is then not the marker: ` +
            `${misdeclared.map((doc) => `${doc.path} reads "${doc.misdeclared}"`).join('; ')}. It is ` +
            `"${DATED_RECORD_MARKER}" and nothing else, so a near miss is an escape hatch an author meant to take ` +
            'and did not — which is worse than a file that never asked for one',
        ]
      : []),
    ...(marked.length === 0
      ? [
          'not one document carries the dated-record marker and one is supposed to: either the sentence moved ' +
            'in the tree and not here, or the escape hatch has stopped being taken and a page whose figures are ' +
            'known to be stale is now being read as current',
        ]
      : []),
    ...(unreadable.length > 0 ? [`\`files\` entries this scan could not expand: ${unreadable.join('; ')}`] : []),
    ...(markedWithoutDate.length > 0
      ? [
          `dated-record marker with no ISO date in its first ${CURRENCY_HEADER_LINES} lines: ` +
            `${markedWithoutDate.map((doc) => doc.path).join(', ')} — a marker is an as-of annotation, so it has ` +
            'to say as of when',
        ]
      : []),
    ...(markedReadme.length > 0
      ? ['README.md carries the dated-record marker, which would take the landing page itself out of the scan']
      : []),
    ...(truth.reached !== truth.total
      ? [
          `the live report reached ${truth.reached} of ${truth.total} assertions, so its profile split is not ` +
            "the registry's split and no tally below can be trusted",
        ]
      : []),
    ...(thinForms.length > 0
      ? [`these tally forms matched nothing at all: ${thinForms.map(([limb]) => limb).join(', ')}`]
      : []),
    ...(docs.some((doc) => doc.path === 'README.md') ? [] : ['README.md is not among the documents this scan read']),
    ...(docs.some((doc) => doc.path === CURRENCY_DOCTRINE)
      ? []
      : [
          `${CURRENCY_DOCTRINE} is not among the documents this scan read — the doctrine is reached by name rather ` +
            'than by a tier, so its absence here is a file that moved and a scan that went on printing a count',
        ]),
    ...CURRENCY_EXPORTED_SYMBOLS.filter(
      (symbol) =>
        !new RegExp(`export\\s+(?:async\\s+)?(?:const|let|function|class)\\s+${literalPattern(symbol.identifier)}\\b`).test(
          readFileSync(join(root, 'src/validate.ts'), 'utf8'),
        ),
    ).map(
      (symbol) =>
        `\`${symbol.spelling}\` is read as a statement of ${symbol.quantity} and src/validate.ts exports no ` +
        `\`${symbol.identifier}\` — the form would go on matching a spelling nothing produces`,
    ),
    ...(docs.filter((doc) => doc.tier === 'shipped').length >= allowlist.filter((e) => e.endsWith('.md')).length
      ? []
      : [
          `${docs.filter((doc) => doc.tier === 'shipped').length} shipped doc(s) read against ` +
            `${allowlist.filter((e) => e.endsWith('.md')).length} \`.md\` entr(ies) in \`files\` — the scan is short of the allowlist`,
        ]),
    ...(docs.filter((doc) => doc.tier === 'landing').length > 0
      ? []
      : ['no document one hop off README was reached, so the landing tier read nothing']),
    ...(truth.total > 0 ? [] : ['the assertion registry answered 0 assertions, so every tally below compares against nothing']),
    // Issue #1183: the core report's figures are read off a live run, and that run is held to the lists it derives from.
    ...(truth.core.modelSide === MODEL_SIDE_CODES.length && truth.core.total === new Set([...MODEL_SIDE_CODES, ...roundTripOnlyCodes()]).size
      ? []
      : [
          `the live core report printed ${truth.core.modelSide} code(s) on the model side and ${truth.core.total} in all, where MODEL_SIDE_CODES holds ` +
            `${MODEL_SIDE_CODES.length} and the round trip's own rules ${roundTripOnlyCodes().length} more — the report reached something other than the lists`,
        ]),
    ...(truth.spine > 0 ? [] : ['the `spine` profile answered 0 assertions']),
    ...(truth.excluded === truth.rendererNames.length + truth.archetypeNames.length
      ? []
      : [
          `the profile excludes ${truth.excluded} where the roster names ` +
            `${truth.rendererNames.length} renderer + ${truth.archetypeNames.length} archetype`,
        ]),
    ...(truth.gateVersion !== null ? [] : ['docs/GATE.md gave up no gate version, so CUR03 compares against nothing']),
    ...(truth.galleryKinds.size > 0 ? [] : ['the gallery answered 0 worked kinds']),
    ...floorProbes(
      [
        [tallySites.length, 5, `${tallySites.length} tally form(s) are being scanned for`],
        [sitesOf('profile row'), 1, `${sitesOf('profile row')} profile row(s) were read`],
        [sitesOf('roster:renderer'), 1, `${sitesOf('roster:renderer')} renderer roster(s) were read`],
        [sitesOf('roster:archetype'), 1, `${sitesOf('roster:archetype')} archetype roster(s) were read`],
        [sitesOf('report summary'), 1, `${sitesOf('report summary')} report summary/summaries were read`],
        [sitesOf('gate version'), 2, `${sitesOf('gate version')} gate-version site(s) were read`],
        [sitesOf('worked case'), 5, `${sitesOf('worked case')} worked case(s) were read`],
        [sitesOf('assertion name'), 100, `${sitesOf('assertion name')} assertion name(s) were read`],
        [sitesOf('installed path'), 3, `${sitesOf('installed path')} installed path(s) were read`],
        [sitesOf('exported symbol'), 2, `${sitesOf('exported symbol')} exported-symbol claim(s) were read`],
      ],
      'and a form that has stopped matching its own phrasing leaves the case it feeds printing PASS over zero sites',
    ),
  ];
  const currencyHeld = currencyProbes.length === 0;
  say(
    'CUR01_THE_CURRENCY_SCAN_READ_THE_DOCS_THE_TOOL_AND_THE_GALLERY',
    currencyHeld,
    probeDetail(
      currencyHeld,
      currencyProbes,
      `${docs.length} doc(s) read — ${docs.filter((d) => d.tier === 'shipped').length} shipped, ` +
        `${docs.filter((d) => d.tier === 'landing').length} one hop off README, ` +
        `${docs.filter((d) => d.tier === 'doctrine').length} doctrine; ` +
        `${marked.length} declared a dated record (${marked.map((d) => `${d.path} @ ${d.headerDate}`).join(', ') || 'none'}). ` +
        `The tool answers: registry ${truth.total}, \`spine\` ${truth.spine}, excluded ${truth.excluded} ` +
        `(${truth.rendererNames.length} renderer + ${truth.archetypeNames.length} archetype, off a live ` +
        `report that reached all ${truth.reached}), gate ${truth.gateVersion} from docs/GATE.md, ` +
        `${truth.galleryKinds.size} gallery-worked kind(s) ` +
        `(${[...truth.galleryKinds].map(([k, v]) => `${k}→${v.join('+')}`).join(', ')}). Sites read: ` +
        `${[...scan.sites].map(([limb, n]) => `${limb} ${n}`).join(', ')}`,
      (count) => `${count} step(s) of the derivation did not hold:`,
    ),
    'every value this suite compares against is derived and every site is found by a scan, so both ends can come ' +
      'back empty. A form that stops matching its own phrasing is the quiet one: the case it feeds goes on ' +
      'printing PASS over zero sites. The floors are what make that loud — the marker is one of them, because a ' +
      'sentence that has stopped matching would take the one dated document back into the scan, or, the other ' +
      'way round, leave a near miss reading as a page that never claimed to be dated',
  );

  // --- CUR02: the assertion tallies -----------------------------------------
  const tallyFaults = scan.faults.filter((f) => /holds \d+$|roster says|a quoted report says/.test(f));
  say(
    'CUR02_A_STATED_ASSERTION_TALLY_IS_THE_ONE_THE_VALIDATOR_HOLDS',
    tallyFaults.length === 0,
    tallyFaults.length === 0
      ? `${tallySites.reduce((n, [, v]) => n + v, 0)} stated tall(ies), ${sitesOf('profile row')} profile-table row(s), ` +
        `${sitesOf('roster:renderer') + sitesOf('roster:archetype')} roster row(s) and ` +
        `${sitesOf('report summary')} quoted report summar(ies) all agree with the validator ` +
        `(registry ${truth.total}, \`spine\` ${truth.spine}, ${truth.rendererNames.length} renderer + ` +
        `${truth.archetypeNames.length} archetype excluded)`
      : `${tallyFaults.length} stale tall(ies):\n          ${tallyFaults.join('\n          ')}`,
    'the class that recurred most: 36 / 39 / 40 for one registry, 22 / 25 for one profile, 14 / 15 for what it ' +
      'leaves out, in six documents at once. `src/validate.ts` exports the first two precisely so nobody has to ' +
      'quote them, and the per-kind split comes off a live report — the same array `reportLines` builds the ' +
      'summary a transcript quotes from',
  );

  // --- CUR03: the gate version ----------------------------------------------
  const versionFaults = scan.faults.filter((f) => f.includes('as the current gate'));
  say(
    'CUR03_A_CURRENT_GATE_CLAIM_NAMES_THE_VERSION_GATE_MD_DECLARES',
    versionFaults.length === 0,
    versionFaults.length === 0
      ? `${sitesOf('gate version')} version token(s) on a line asserting currency, all ${truth.gateVersion} — the ` +
        'version docs/GATE.md\'s own header declares'
      : `${versionFaults.length} superseded gate version(s) asserted as current:\n          ` +
        versionFaults.join('\n          '),
    'the bump lands in GATE.md and the sentences that quote it are elsewhere, so a bump repairs them one at a ' +
      'time and forgets one. #359 found three at once and left a fourth; this reads GATE.md\'s header instead. ' +
      'Dated references to a superseded version stay — the trigger is a phrase claiming currency, not the token',
  );

  // --- CUR04: the worked cases ----------------------------------------------
  const workedFaults = scan.faults.filter((f) => f.includes("'s worked case"));
  say(
    'CUR04_A_WORKED_CASE_CELL_NAMES_A_GALLERY_EXAMPLE_THAT_WORKS_THAT_KIND',
    workedFaults.length === 0,
    workedFaults.length === 0
      ? `${sitesOf('worked case')} Worked case cell(s) checked against the gallery's own motion specs; every named ` +
        'example exists and declares the kind of the row it sits in, and no cell is `—` for a kind the gallery works'
      : `${workedFaults.length} Worked case cell(s) out of date:\n          ${workedFaults.join('\n          ')}`,
    'a `—` means "nobody has done this yet", so it goes false the day an example does it — and it did, for the ' +
      'whole gap between gallery/nod landing and #357 telling the two tables about it. The answer is in the ' +
      'gallery\'s motion specs, which is what LS03 reads too',
  );

  // --- CUR05/06: the names and the installed paths ---------------------------
  const namedFaults = scan.faults.filter(
    (f) => f.includes('which the registry does not have') || f.includes('is not in `files`'),
  );
  say(
    'CUR05_AN_ASSERTION_AND_AN_INSTALLED_PATH_A_DOC_NAMES_BOTH_EXIST',
    namedFaults.length === 0,
    namedFaults.length === 0
      ? `${sitesOf('assertion name')} A??_NAME mention(s) all in the registry of ${truth.total} or among the model side's own ` +
        `${MODEL_SIDE_CODES.length - MOVED_ASSERTIONS.length} parse rule(s) a core-entry report prints, and ` +
        `${sitesOf('installed path')} node_modules/${packageName}/ path(s) all in \`files\``
      : `${namedFaults.length} name(s) that resolve to nothing:\n          ${namedFaults.join('\n          ')}`,
    'the cheap half of the same rule, and exhaustive rather than sampled: a renamed assertion leaves every doc ' +
      'that named it pointing at a rule the reader cannot find, and an installed path is the one place PKG02 ' +
      'cannot look, because it is written as plain text rather than as a link',
  );

  // --- CUR06: the scanner against the rows it was built from ----------------
  const probeFaults: string[] = [];
  for (const probe of CURRENCY_RED_FIRST) {
    const stale = emptyScan();
    const staleDoc = readCurrencyDoc('probe.md', 'shipped', probe.stale);
    mergeScan(stale, scanAssertionTallies(staleDoc, truth));
    mergeScan(stale, scanGateVersion(staleDoc, truth));
    mergeScan(stale, scanWorkedCases(staleDoc, truth, root));
    const clean = emptyScan();
    const cleanDoc = readCurrencyDoc('probe.md', 'shipped', probe.clean);
    mergeScan(clean, scanAssertionTallies(cleanDoc, truth));
    mergeScan(clean, scanGateVersion(cleanDoc, truth));
    mergeScan(clean, scanWorkedCases(cleanDoc, truth, root));
    // ⚠️ Against the REPAIRED spelling's own faults, not against zero (issue
    // #506). The two documents differ in one row and are read against the same
    // live truth, so a fault with nothing to do with the stale spelling — a
    // worked case whose command changed, say — stands in both, and the
    // absolute form reads it as this probe's doing and stops testing the probe
    // on exactly the run that matters. The clause below is what pins the
    // baseline to nothing, which is why the subtraction is the identity today
    // and changes what this case measures on no green run.
    if (raisedBy(stale.faults, { was: clean.faults }).length === 0) {
      probeFaults.push(`${probe.row}: the stale spelling was NOT faulted`);
    }
    if (clean.faults.length > 0) {
      probeFaults.push(`${probe.row}: the REPAIRED spelling faulted — ${clean.faults.join('; ')}`);
    }
  }
  // --- CUR08: the counts the CLI's own help prints --------------------------
  //
  // `README.md` states the profile split and this gate holds it there. The HELP
  // stated it too, in a usage string no gate read, and so it kept **20 / 36 /
  // 14** from before `A36`–`A39` landed while the tool ran 25 / 40 / 15 (issue
  // #373). A literal in a usage string is a hand-maintained tally like any
  // other, and the help is the surface an agent meets FIRST.
  //
  // 🚨 The reference is a live report's own PROF lines, not
  // `assertionCountForProfile`. The help calls that function now, so comparing
  // the two would be the code agreeing with itself — the shape of check this
  // repository keeps catching itself writing. A `spine`-profile report reaches
  // every assertion in the registry and names each one it excluded, which
  // yields all three numbers with the counting function nowhere in the path.
  {
    const help = runCli(['--help']).stdout;
    const seen = (re: RegExp): number | null => {
      const m = re.exec(help);
      return m ? Number(m[1]) : null;
    };
    const printedDefault = seen(/THE DEFAULT — (\d+) rules/);
    const printedAll = seen(/all (\d+) rules, opt-in/);
    const printedExtra = seen(/Those extra (\d+) fire on real/);
    // Independent of the counting function, by construction.
    const wantAll = truth.reached;
    const wantExtra = truth.rendererNames.length + truth.archetypeNames.length;
    const wantDefault = wantAll - wantExtra;
    const rows: Array<[string, number | null, number]> = [
      ['THE DEFAULT — N rules', printedDefault, wantDefault],
      ['all N rules, opt-in', printedAll, wantAll],
      ['Those extra N', printedExtra, wantExtra],
    ];
    // A `null` here is a row whose wording moved out from under the pattern,
    // and it counts as WRONG rather than as absent — a scan that stops matching
    // goes silent, which is the one failure a tally gate cannot afford.
    const wrong = rows.filter(([, got, want]) => got !== want);
    say(
      'CUR08_THE_PROFILE_COUNTS_IN_THE_CLI_HELP_ARE_THE_TOOLS_OWN',
      wrong.length === 0 && wantAll > 0 && wantExtra > 0,
      wrong.length === 0
        ? `\`rigc --help\` prints ${printedDefault} / ${printedAll} / ${printedExtra}, and a live spine-profile ` +
          `report reached ${wantAll} assertion(s) and excluded ${truth.rendererNames.length} renderer + ` +
          `${truth.archetypeNames.length} archetype`
        : wrong.map(([row, got, want]) => `"${row}" printed ${got ?? '(no match)'} and the tool has ${want}`).join('; '),
      'the help is the first surface an agent meets and the only one that had no gate, so it kept 20 / 36 / 14 ' +
        'through two assertions landing and a profile split moving (#373)',
    );
  }

  // --- CUR07: the module boundary CLAUDE.md names, against the tree ---------
  //
  // The same defect one surface over, and it is the surface the doctrine cares
  // about most. `CLAUDE.md`'s *Conventions* names the files allowed to link
  // spine-core "because an unnamed exception is how a rule erodes" — and then
  // went stale in exactly that way: `src/deformmeasure.ts` began posing meshes
  // through the runtime (#296, #316) and the sentence still said **Two**
  // (issue #379). Nothing read it, so nothing said so for two weeks.
  //
  // 🔒 The clause that MATTERS is the negative one. `src/compile.ts` staying off
  // the list is what keeps the compiler and the gate from checking each other's
  // assumptions, and until now no test asserted it at all.
  {
    const WORDS = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten'];
    // A VALUE import, which is what "links the runtime" means: a type-only
    // import compiles to nothing and cannot pose anything.
    const linkers: string[] = [];
    const candidates = ['cli.ts', ...trackedIn(root, 'src', (f) => f.endsWith('.ts'))];
    for (const rel of candidates) {
      const text = readFileSync(join(root, rel), 'utf8');
      const importsIt = [...text.matchAll(/import\s+(type\s+)?\{[^}]*\}\s*from\s*'@esotericsoftware\/spine-core'/g)];
      if (importsIt.some((m) => m[1] === undefined)) linkers.push(rel);
    }
    linkers.sort();

    const claudeMd = readFileSync(join(root, 'CLAUDE.md'), 'utf8');
    // Bullets, so the rule stays ordinary prose rather than becoming a table
    // maintained for a test's benefit.
    const bullet = claudeMd
      .split(/\n- /)
      .map((b) => b.replace(/\s+/g, ' '))
      .find((b) => /files link spine-core/.test(b));
    const stated = bullet === undefined ? [] : [...bullet.matchAll(/`(src\/[\w.]+\.ts|cli\.ts)`/g)].map((m) => m[1]);
    const countWord = bullet?.match(/\*\*(\w+)\*\* files link spine-core/)?.[1]?.toLowerCase();
    // `src/compile.ts` is named in that bullet as a PROHIBITION, not as one of
    // the linkers, so it is the one name the comparison must not read as a
    // claim. Naming it here is naming the invariant, which is the point.
    const FORBIDDEN = 'src/compile.ts';
    const claimed = [...new Set(stated.filter((f) => f !== FORBIDDEN))].sort();

    const faults: string[] = [];
    if (bullet === undefined) faults.push('CLAUDE.md has no bullet stating which files link spine-core');
    if (countWord !== WORDS[linkers.length]) {
      faults.push(`the bullet says "${countWord ?? '(none)'}" and the tree has ${linkers.length} (${WORDS[linkers.length] ?? linkers.length})`);
    }
    for (const f of linkers) if (!claimed.includes(f)) faults.push(`${f} links spine-core and the doctrine does not name it`);
    for (const f of claimed) if (!linkers.includes(f)) faults.push(`the doctrine names ${f} as a linker and it does not link spine-core`);
    if (linkers.includes(FORBIDDEN)) faults.push(`🔒 ${FORBIDDEN} LINKS THE RUNTIME — the compiler and the gate must not check each other's assumptions`);

    say(
      'CUR07_THE_FILES_CLAUDE_MD_ALLOWS_TO_LINK_SPINE_CORE_ARE_THE_FILES_THAT_DO',
      faults.length === 0 && linkers.length > 0 && claimed.length > 0,
      faults.length === 0
        ? `${linkers.length} file(s) link the runtime as values — ${linkers.join(', ')} — and the doctrine names ` +
          `exactly those, as "${countWord}". ${FORBIDDEN} is not among them, which is the clause that matters`
        : faults.join('; '),
      'the rule says an unnamed exception is how a rule erodes, and then eroded that way itself (#379): a third ' +
        'file began posing through the runtime and the sentence still said Two. A rule about drift that nothing ' +
        'derives is a comment',
    );
  }

  // --- CUR128: no `Math.hypot` where a length can reach a byte (issue #1377) ---
  //
  // Bun 1.4.2's `Math.hypot` returned 34.27192399143071 on macOS and
  // 34.27192399143072 on Linux for one bit-identical input (rig-c/parts#276),
  // and the probe of #1377 found 1,804 of the gallery's own (dx, dy) pairs on
  // which the two platforms disagree; `Math.sqrt(dx * dx + dy * dy)` agreed on
  // every one, because IEEE 754 requires `*`, `+` and `sqrt` to round correctly
  // and requires nothing of `hypot`. `A18` compiles twice on ONE machine, so it
  // cannot see this. Every call in `src/` became `hypot2` (`src/numeric.ts`).
  //
  // 🔒 The population is read from the tree, not listed: every tracked module
  // under `src/`, every module `src/` imports from outside itself, and the two
  // entries. A module that joins any of those joins the scan. Comments are
  // blanked first, because the tree's own comments name `Math.hypot` to say why
  // it is not used, and a gate that faulted the reason would be deleted.
  {
    const HYPOT = /\bMath\s*(?:\.\s*hypot\b|\[\s*['"`]hypot['"`]\s*\])|\{[^{}]*\bhypot\b[^{}]*\}\s*=\s*Math\b/g;
    const DECLARES = /^(?:export\s+)?(?:default\s+)?(?:async\s+)?(?:function\*?\s+|const\s+|let\s+|class\s+)([A-Za-z_$][\w$]*)/;
    const population = [
      ...trackedFiles(root).filter((rel) => rel.startsWith('src/') && rel.endsWith('.ts')),
      ...modulesSrcReachesOutsideItself(root),
      'cli.ts',
      'cli_core.ts',
      // The rule's one home, named because the plants below write into it.
      'src/numeric.ts',
    ].filter((rel) => existsSync(join(root, rel)));
    const texts = new Map<string, string>([...new Set(population)].sort().map((rel) => [rel, readFileSync(join(root, rel), 'utf8')]));
    /** Each call as `file:line symbol`, the symbol being the top-level declaration it sits in. */
    const hypotCalls = (files: ReadonlyMap<string, string>): string[] => {
      const found: string[] = [];
      for (const [rel, text] of files) {
        // Blanked to the same length line by line, so a line number read off the code is the file's.
        const code = text.replace(/\/\*[\s\S]*?\*\//g, (c) => c.replace(/[^\n]/g, ' ')).replace(/\/\/[^\n]*/g, (c) => ' '.repeat(c.length));
        const lines = code.split('\n');
        let symbol = '(top level)';
        lines.forEach((line, i) => {
          const declared = DECLARES.exec(line);
          if (declared !== null) symbol = declared[1];
          for (const m of line.matchAll(HYPOT)) found.push(`${rel}:${i + 1} ${symbol} calls ${m[0].replace(/\s+/g, ' ')}`);
        });
      }
      return found;
    };
    const standing = hypotCalls(texts);
    const edit = (rel: string, from: string, to: string): Map<string, string> | null => {
      const text = texts.get(rel);
      if (text === undefined || text.split(from).length !== 2) return null;
      return new Map(texts).set(rel, text.replace(from, to));
    };
    const reached = modulesSrcReachesOutsideItself(root).find((rel) => rel.startsWith('tools/')) ?? '';
    const plants: Array<{ what: string; files: Map<string, string> | null; at: string; quiet?: boolean }> = [
      {
        what: 'a call inside segmentDistance in src/mesh.ts',
        files: edit('src/mesh.ts', '  return Math.sqrt(dx * dx + dy * dy);\n}', '  return Math.hypot(dx, dy);\n}'),
        at: 'src/mesh.ts:',
      },
      {
        what: 'a call in a module src/ reaches outside itself',
        files: reached === '' ? null : new Map(texts).set(reached, `${texts.get(reached) ?? ''}\nexport const planted = (dx: number, dy: number): number => Math.hypot(dx, dy);\n`),
        at: `${reached}:`,
      },
      {
        what: 'hypot destructured off Math in src/numeric.ts',
        files: new Map(texts).set('src/numeric.ts', `const { hypot } = Math;\n${texts.get('src/numeric.ts') ?? ''}`),
        at: 'src/numeric.ts:',
      },
      {
        what: 'Math.hypot named in a comment and a block comment',
        files: new Map(texts).set('src/numeric.ts', `// Math.hypot(dx, dy)\n/* Math.hypot */\n${texts.get('src/numeric.ts') ?? ''}`),
        at: 'src/numeric.ts:',
        quiet: true,
      },
    ];
    const probes: string[] = [];
    const cases: string[] = [];
    for (const plant of plants) {
      if (plant.files === null) {
        probes.push(`"${plant.what}": the edit found nothing to change, so this plant was never made`);
        continue;
      }
      const raised = raisedBy(hypotCalls(plant.files), { at: plant.at, was: standing });
      if (plant.quiet === true) {
        if (raised.length > 0) probes.push(`"${plant.what}" is not a call and ${raised.length} fault(s) fired: ${raised[0]}`);
        cases.push(`${plant.what} -> quiet`);
        continue;
      }
      if (raised.length === 0) probes.push(`"${plant.what}" was planted and this gate did not fire`);
      cases.push(`${plant.what} -> ${raised.join('; ')}`);
    }
    const scanned = [...texts.keys()];
    const outside = scanned.filter((rel) => !rel.startsWith('src/'));
    const held = standing.length === 0 && probes.length === 0 && texts.has('src/numeric.ts') && reached !== '';
    say(
      'CUR128_NO_MATH_HYPOT_IN_SRC_OR_WHAT_IT_IMPORTS_SO_A_LENGTH_HAS_ONE_ANSWER_ON_EVERY_PLATFORM',
      held,
      probeDetail(
        held,
        [
          ...standing.map((call) => `${call} — use hypot2 from src/numeric.ts, whose bits are the same on every platform`),
          ...probes,
          ...(texts.has('src/numeric.ts') ? [] : ['src/numeric.ts is not tracked or not read, so the one home of the rule is missing']),
          ...(reached === '' ? ['src/ reaches no module under tools/, so the plant outside src/ was never made'] : []),
        ],
        `${scanned.length} module(s) scanned with comments blanked — every tracked one under src/ and ${outside.join(', ')} — ` +
          `and none calls Math.hypot; over ${cases.length} plant(s): ${cases.join('; ')}`,
      ),
      'issue #1377: Math.hypot is not required to round correctly and Bun 1.4.2 rounds it differently on macOS and Linux ' +
        '(rig-c/parts#276); A18 compares two compiles on one machine and cannot see a byte that moves between two',
    );
  }

  say(
    'CUR06_THE_SCANNER_STILL_FAULTS_THE_ROWS_THIS_GATE_WAS_BUILT_FROM',
    probeFaults.length === 0 && CURRENCY_RED_FIRST.length >= 11,
    probeFaults.length === 0
      ? `${CURRENCY_RED_FIRST.length} row(s) from #357, #359 and this tree, each faulted in its stale spelling and ` +
        'clean in its repaired one'
      : `${probeFaults.length} of ${CURRENCY_RED_FIRST.length} row(s) no longer behave:\n          ` +
        probeFaults.join('\n          '),
    'a scan is a vocabulary of forms and a form that stops matching goes silent, not red. CUR01\'s floors catch a ' +
      'form that stops matching the TREE; this catches one that stops matching the DEFECT. Both directions are ' +
      'required, because a form loose enough to fault the repair is not a gate either',
  );

  // --- CUR09: the marker a reader can see (issue #444) ----------------------
  //
  // 🔒 The whole of this case is the one-string rule, held to on the surface
  // CUR01 depends on. The escape hatch used to be an HTML comment, so the one
  // page in this tree whose figures are deliberately NOT kept current showed a
  // reader nothing at all — the claim on the page and the machinery that exempts
  // it were two different objects, one of them invisible. #442 settled the shape
  // for the gallery's two markers and this is the same argument on the third.
  //
  // Every probe goes through `readCurrencyDoc` rather than through a copy of its
  // rule, so a change to the parser reaches them; and every one is two-sided,
  // because a reader that declared nothing would satisfy every refusal below on
  // its own — the shape `ERT05` exists for.
  {
    const at = (body: string[]): CurrencyDoc => readCurrencyDoc('probe.md', 'landing', body.join('\n'));
    const dated = (line: string): CurrencyDoc => at(['# probe', '', 'Research note, 2026-08-22.', '', line]);
    const RETIRED_COMMENT = '<!-- currency: dated-record -->';
    const nearMiss = `${DATED_RECORD_LEAD} a page that has not been re-measured.`;
    const belowHeader = at(['# probe', 'Research note, 2026-08-22.', ...Array(CURRENCY_HEADER_LINES).fill(''), DATED_RECORD_MARKER]);
    const undated = at(['# probe', '', DATED_RECORD_MARKER]);
    const shown = docs.filter((doc) => doc.dated && doc.raw.slice(0, CURRENCY_HEADER_LINES).includes(DATED_RECORD_MARKER));
    const inProse = docs.filter(
      (doc) => doc.dated && doc.prose.slice(0, CURRENCY_HEADER_LINES).includes(DATED_RECORD_MARKER),
    );
    const probes = [
      // ① the form that parses is the sentence, and it is not also a near miss.
      ...(dated(DATED_RECORD_MARKER).dated ? [] : ['the marker sentence did not declare a dated record']),
      ...(dated(DATED_RECORD_MARKER).misdeclared === null ? [] : ['the marker sentence was reported as a near miss too']),
      // ② exactly one form. The comment it replaced is retired, not deprecated,
      //    and a sentence hidden inside a comment is the same defect returning.
      ...(dated(RETIRED_COMMENT).dated ? ['the retired HTML comment still declares a dated record'] : []),
      ...(dated(RETIRED_COMMENT).misdeclared === null ? [] : ['the retired comment was reported as a near miss rather than as nothing']),
      ...(dated(`<!-- ${DATED_RECORD_MARKER} -->`).dated
        ? ['the marker declared a dated record from inside an HTML comment, where no reader would see it']
        : []),
      // ③ a near miss is a FAULT by name, never silence: an author who opened
      //    with the lead meant to take the escape hatch.
      ...(dated(nearMiss).misdeclared === nearMiss ? [] : ['a line opening with the lead and then not the sentence was not reported as a near miss']),
      ...(dated(nearMiss).dated ? ['a line opening with the lead and then not the sentence declared a dated record anyway'] : []),
      ...(dated(DATED_RECORD_LEAD).misdeclared === DATED_RECORD_LEAD ? [] : ['the lead with nothing after it was not reported as a near miss']),
      // ④ the header bound, both ways.
      ...(belowHeader.dated ? [`the marker declared a dated record from below the ${CURRENCY_HEADER_LINES}-line header bound`] : []),
      // ⑤ the ISO-date clause CUR01 refuses on, seen to reach the state it refuses.
      ...(undated.dated && undated.headerDate === null ? [] : ['a marked page with no ISO date in its header did not reach the state CUR01 refuses']),
      ...(dated(DATED_RECORD_MARKER).headerDate === null ? ['a marked page WITH an ISO date in its header read as having none'] : []),
      // ⑥ and the tree itself: the string is in the file, on a line that renders.
      //    The floor is a probe rather than a bare conjunct in the verdict, because
      //    a case whose detail says everything is fine while the gutter says FAIL
      //    names nothing — measured by running the mutant, which printed exactly that.
      ...(marked.length >= 1
        ? []
        : ['no document in the tree carries the marker, so every clause above was checked against synthetic text only']),
      ...(shown.length === marked.length ? [] : ['a document declared a dated record without carrying the sentence verbatim']),
      ...(inProse.length === marked.length ? [] : ['the marker line does not survive into the running text, so a reader does not see it']),
    ];
    say(
      'CUR09_THE_DATED_RECORD_MARKER_IS_THE_SENTENCE_THE_PAGE_SHOWS',
      probes.length === 0,
      probes.length === 0
        ? `the sentence parses and the retired comment does not; a line that opens with the lead and then is not ` +
          `the sentence is reported by name rather than read as undeclared, and so is the lead alone; the same ` +
          `sentence inside an HTML comment or below the ${CURRENCY_HEADER_LINES}-line header bound declares ` +
          `nothing; a marked page with no ISO date reaches the state CUR01 refuses and one with a date does ` +
          `not; and all ${marked.length} marked document(s) carry the sentence verbatim, on a line the running ` +
          'text keeps'
        : probes.join('\n          '),
      'the marker is the only thing on the page that says how the claim is kept true, so hiding it in a comment ' +
        'left the reader with a claim and no provenance while the machinery sat one layer down — #442 exactly, ' +
        'one suite over. What this case has to prove is that making it visible did not buy a second accepted ' +
        'spelling: the retired comment declares nothing, and the sentence wrapped back into a comment declares ' +
        'nothing either. The near-miss clauses are the other half, because the worst outcome is not a malformed ' +
        'marker but a malformed marker read as a page that never asked to be exempt',
    );
  }

  // --- CUR10: what .gitignore claims to hide, git actually hides (#457) -----
  //
  // ⭐ Why a `.gitignore` case belongs in this suite. Every other case here
  // holds a claim the repository makes about itself to the thing it claims
  // about, and this file makes one on every line: *this path does not appear*.
  // Nothing derived it, and it was false on thirty-one lines at once. A pattern
  // ending in `/` matches a **directory** and nothing else — of the four things
  // a path can turn out to be (a directory, a symlink, a file, or absent) it
  // covers one. So `scratch`, a link into a private store, sat visible to
  // `git status` in this PUBLIC repository one `git add -A` from a commit, and
  // `examples` did the same in a worktree that had symlinked it to reach the
  // corpus. The judgment was made after the first occurrence and written into
  // the file beside ONE path; the other thirty kept the defect for three weeks.
  //
  // 🔒 The measurement is deliberately NOT `git check-ignore` against this
  // checkout. That call resolves the path on disk, so it answers IGNORED for
  // `examples` here — where the corpus is a real directory — and answered NOT
  // in the worktree where the same name was a link to one. A gate that reads
  // today's disk passes on one machine and fails on another, which is the
  // opposite of what a gate is for. Each entry's path is therefore planted in a
  // throwaway repository as a directory, as a symlink and as a file in turn,
  // and git is asked there. That also measures git's behaviour rather than
  // restating the syntax rule, so a pattern form nobody has thought about yet
  // is covered the day it is added.
  //
  // ⚠️ Two-sided, and neither side is a style rule about slashes. The negative
  // half is a path no line mentions, which has to come back ignored in NONE of
  // the three kinds: without it, a harness that wrote the wrong file — or a
  // `check-ignore` that answered 0 for everything — would report a perfect
  // `.gitignore` over nothing at all, which is `ERT05`'s shape. Beside it a
  // control file that both hides a path and re-includes one with `!` has to be
  // read in both directions. Both are synthetic on purpose: hanging the
  // direction half on the tree's own `!` line would turn red the day somebody
  // removed that line for a perfectly good reason, which is a two-sided clause
  // attached to the wrong thing.
  {
    type IgnoreClaim = { line: number; text: string; path: string; expect: 'hidden' | 'shown' };
    const KINDS = ['a directory', 'a symlink', 'a file'] as const;
    type PlantKind = (typeof KINDS)[number];
    type IgnoreScan = {
      claims: IgnoreClaim[];
      unreadable: string[];
      broken: string[];
      leaks: { claim: IgnoreClaim; kinds: PlantKind[] }[];
      unlisted: PlantKind[];
    };
    /** Named by no line in any file below, so every kind of it must come back visible. */
    const UNLISTED = 'a-path-no-gitignore-line-names';

    /** The file as TEXT: what each line claims, and one concrete path to claim it about. */
    const readClaims = (text: string): { claims: IgnoreClaim[]; unreadable: string[] } => {
      const claims: IgnoreClaim[] = [];
      const unreadable: string[] = [];
      text.split('\n').forEach((raw, i) => {
        const line = raw.replace(/\s+$/, '');
        if (line === '' || line.startsWith('#')) return;
        const expect: 'hidden' | 'shown' = line.startsWith('!') ? 'shown' : 'hidden';
        const rel = (expect === 'shown' ? line.slice(1) : line).replace(/^\/+/, '').replace(/\/+$/, '');
        // A pattern this case cannot plant one path for is UNREAD, and unread is
        // reported rather than skipped: a silent skip is the hand-kept exception
        // table wearing a parser's clothes.
        if (rel === '' || rel.includes('**') || /[?[\]\\]/.test(rel)) {
          unreadable.push(`.gitignore:${i + 1} \`${line}\` is a pattern this case cannot plant a single path for, so it was never measured`);
          return;
        }
        claims.push({ line: i + 1, text: line, path: rel.replace(/\*/g, 'x'), expect });
      });
      return { claims, unreadable };
    };

    /** Plant every path as `kind` in a fresh repository carrying `text`, and ask git which it ignores. */
    const askGit = (text: string, paths: string[], kind: PlantKind): { ignored: Set<string>; broken: string | null } => {
      const dir = mkdtempSync(join(harnessTemp(), 'rigc-gitignore-'));
      // A user's global excludes file would otherwise decide some of these, and
      // a machine that has one would measure something this repository does not
      // ship. Point it at a path that does not exist.
      const isolated = ['-c', `core.excludesFile=${join(dir, 'no-such-global-excludes')}`];
      try {
        const init = spawnSync('git', [...isolated, 'init', '-q', dir], { encoding: 'utf8' });
        if (init.error !== undefined || init.status !== 0) {
          return { ignored: new Set(), broken: `git could not make a throwaway repository (${init.error?.message ?? `exit ${String(init.status)}: ${init.stderr.trim()}`})` };
        }
        mkdirSync(join(dir, 'plant-target'));
        writeFileSync(join(dir, 'plant-target', 'inside.txt'), 'x');
        // Shallow first, so a parent directory exists before a child goes under it.
        const order = [...paths].sort((a, b) => a.split('/').length - b.split('/').length || a.localeCompare(b));
        for (const path of order) {
          const full = join(dir, path);
          let taken = false;
          try {
            taken = lstatSync(full, { throwIfNoEntry: false }) !== undefined;
          } catch (err) {
            // `throwIfNoEntry` only suppresses ENOENT. ENOTDIR means a line
            // above this one owns one of its parent directories, and under the
            // file kind it owns it as a file — which threw and took the whole
            // run down until a mutant did exactly that. A crash is not a report.
            return { ignored: new Set(), broken: `"${path}" could not be planted as ${kind} because a line above it owns one of its parent directories: ${(err as Error).message}` };
          }
          if (taken) {
            return { ignored: new Set(), broken: `two lines want the same planted path "${path}", so one of them was never measured on its own` };
          }
          try {
            mkdirSync(dirname(full), { recursive: true });
            if (kind === 'a directory') {
              mkdirSync(full);
              writeFileSync(join(full, 'inside.txt'), 'x');
            } else if (kind === 'a file') writeFileSync(full, 'x');
            else symlinkSync(join(dir, 'plant-target'), full);
          } catch (err) {
            return { ignored: new Set(), broken: `"${path}" could not be planted as ${kind}: ${(err as Error).message}` };
          }
        }
        writeFileSync(join(dir, '.gitignore'), text);
        const probe = spawnSync('git', [...isolated, '-C', dir, 'check-ignore', '--stdin'], { encoding: 'utf8', input: `${paths.join('\n')}\n` });
        // Exit 1 means "none of them"; anything else means git did not answer,
        // and silence read as a clean file is the failure this case is for. One
        // way it really happens, found by running the control mutant: git exits
        // 128 with `pathspec … is beyond a symbolic link` when a line's path
        // nests under a line planted as a link. No line here nests under
        // another today, and one that did would be redundant with the line
        // above it, so this is reported by name rather than accommodated.
        if (spawnFailed(probe) || (probe.status !== 0 && probe.status !== 1)) {
          return { ignored: new Set(), broken: `git check-ignore could not answer for ${kind} (${probe.error?.message ?? `exit ${String(probe.status)}: ${probe.stderr.trim()}`}); this case fails closed rather than reading that as a clean file` };
        }
        return { ignored: new Set(probe.stdout.split('\n').map((l) => l.trim()).filter((l) => l !== '')), broken: null };
      } finally {
        rmSync(dir, { recursive: true, force: true });
      }
    };

    const scanIgnoreText = (text: string): IgnoreScan => {
      const { claims, unreadable } = readClaims(text);
      const paths = [...claims.map((c) => c.path), UNLISTED];
      const broken: string[] = [];
      const seen = new Map<PlantKind, Set<string>>();
      for (const kind of KINDS) {
        const answer = askGit(text, paths, kind);
        if (answer.broken !== null) broken.push(answer.broken);
        seen.set(kind, answer.ignored);
      }
      const hides = (kind: PlantKind, path: string): boolean => seen.get(kind)?.has(path) === true;
      return {
        claims,
        unreadable,
        broken,
        leaks: claims
          .map((claim) => ({ claim, kinds: KINDS.filter((kind) => hides(kind, claim.path) !== (claim.expect === 'hidden')) }))
          .filter((row) => row.kinds.length > 0),
        unlisted: KINDS.filter((kind) => hides(kind, UNLISTED)),
      };
    };

    /** Every way one scan can be wrong. The mutants below run through this same list. */
    const faultsOf = (scan: IgnoreScan): string[] => [
      // The floor is an entry here rather than a conjunct in the verdict, so a
      // planted run's detail names what went wrong instead of reading clean.
      ...(scan.claims.length === 0 ? ['not one pattern was read out of the file, so every clause below was measured against nothing'] : []),
      ...scan.unreadable,
      ...scan.broken,
      ...(scan.unlisted.length === 0
        ? []
        : [
            `"${UNLISTED}" is not the derived path of any line in the file and still came back ignored as ` +
              `${scan.unlisted.join(' and ')}: either some pattern reaches further than the line that wrote it, or this ` +
              'probe answers "hidden" whatever it is asked and every clause beside this one is vacuous',
          ]),
      ...scan.leaks.map(
        (row) =>
          `.gitignore:${row.claim.line} \`${row.claim.text}\` is there to ${row.claim.expect === 'hidden' ? 'HIDE' : 'SHOW'} "${row.claim.path}" and does not when that path is ${row.kinds.join(' or ')}` +
          (row.claim.text.endsWith('/') ? ' — a pattern ending in `/` matches a directory and nothing else, so drop the trailing slash' : ''),
      ),
    ];

    const live = readFileSync(join(root, '.gitignore'), 'utf8');
    const liveScan = scanIgnoreText(live);

    // ① the floor, seen to fire: a file with nothing readable in it.
    const floorFires = faultsOf(scanIgnoreText('# nothing but a comment\n')).length > 0;

    // ② the direction half, on a control file that does both.
    const control = ['probe-hidden', 'probe-dir/*', '!probe-dir/keep.mjs'].join('\n');
    const controlScan = scanIgnoreText(control);
    const controlFaults = faultsOf(controlScan);
    const controlShaped =
      controlScan.claims.filter((c) => c.expect === 'shown').length === 1 &&
      controlScan.claims.filter((c) => c.expect === 'hidden').length === 2;

    // ③ red-first: put the trailing slash back on one entry with a literal path.
    const victim = liveScan.claims.find((c) => c.expect === 'hidden' && !c.text.includes('*'));
    // ⚠️ What this plant RAISED, not what the file says altogether (issues
    // #505, #506). Issue #491 filed this clause with the shape that goes
    // quiet; it is the other one. A count required to be exactly ONE is not
    // satisfied by a standing fault, it is BROKEN by one — an unreadable
    // pattern added anywhere in the file stands in this scan too, and the
    // absolute form then reports the mutant as having faulted more than its
    // own line while the mutant behaved perfectly.
    //
    // 🔸 Measured rather than assumed: on a file with one standing fault this
    // case is red on that fault whatever this clause does, so what the repair
    // buys is not a green run — it is a FAIL whose detail stops naming the
    // plant for something the plant did not do, which is the `CUR09`/`TY12`
    // judgment one layer over. The plant rewrites one line in place and the
    // derived path drops a trailing slash, so nothing moves and subtracting by
    // string is exact. The leak rows are subtracted the same way, by the line
    // and kinds that make one, because `only` has to mean the leak this plant
    // raised and not the only leak in the file.
    const revertFault = ((): string[] => {
      if (victim === undefined) return ['no line in the file has a literal path, so the trailing-slash mutant had nothing to aim at'];
      const back = scanIgnoreText(live.split('\n').map((l, i) => (i + 1 === victim.line ? `${l}/` : l)).join('\n'));
      const raised = raisedBy(faultsOf(back), { was: faultsOf(liveScan) });
      const stood = new Set(liveScan.leaks.map((row) => `${row.claim.line} ${row.kinds.join(', ')}`));
      const newLeaks = back.leaks.filter((row) => !stood.has(`${row.claim.line} ${row.kinds.join(', ')}`));
      const only = newLeaks.length === 1 ? newLeaks[0] : null;
      if (raised.length === 1 && only !== null && only.claim.line === victim.line && only.kinds.join(', ') === 'a symlink, a file') return [];
      return [
        `putting the trailing slash back on .gitignore:${victim.line} \`${victim.text}\` had to fault that line and only that line, on exactly a symlink and a file; instead ` +
          (raised.length === 0 ? 'it raised nothing the unplanted file does not' : raised.join('; ')),
      ];
    })();

    const probes = [
      ...faultsOf(liveScan),
      ...(floorFires ? [] : ['a .gitignore carrying nothing but a comment was read as a clean file, so a scan that stopped matching would go quiet rather than red']),
      ...(controlShaped ? [] : ['the control file did not parse into two hiding lines and one `!` line, so the direction half of this case was never exercised']),
      ...(controlFaults.length === 0 ? [] : [`the control file that both hides and re-includes was not read in both directions: ${controlFaults.join('; ')}`]),
      ...revertFault,
    ];
    say(
      'CUR10_EVERY_GITIGNORE_LINE_HIDES_ITS_PATH_WHATEVER_THAT_PATH_TURNS_OUT_TO_BE',
      probes.length === 0,
      probes.length === 0
        ? `all ${liveScan.claims.length} pattern(s) in .gitignore hide their path — or, for the ` +
          `${liveScan.claims.filter((c) => c.expect === 'shown').length} \`!\` line(s), show it — when it is planted in a throwaway ` +
          `repository as a directory, as a symlink and as a file in turn; a path no line names comes back ignored in none of the ` +
          `three; a control file that both hides and re-includes is read in both directions; a file with nothing readable in it ` +
          `faults on the floor rather than passing; and putting the trailing slash back on \`${victim?.text ?? ''}\` faults that ` +
          'line alone, on a symlink and a file'
        : probes.join('\n          '),
      'the third occurrence of one defect (#457): `examples/` and `/scratch/` matched the directory and not the symlink, so a ' +
        'path this PUBLIC repository keeps out of sight became visible to `git status` — silent, and in the direction of ' +
        'exposure. The judgment after the first occurrence was recorded beside one path and applied to no other, which is why ' +
        'the rule is now the whole file and this case is what re-reads it. Asking git in a throwaway repository rather than ' +
        'here is the load-bearing choice: `git check-ignore` resolves on disk, so the live tree answers with what a name ' +
        'happens to be today',
    );
  }

  // --- CUR11: a byte that makes a text file binary to a text tool (#465) ----
  //
  // ⭐ **The doctrine's opening sentence, arriving in the toolchain instead of
  // in the output.** `cli.ts` carried two literal NUL bytes as separators inside
  // composite map keys — valid UTF-8, correct at runtime, and invisible: a grep
  // over the file that owns rigc's report text matched nothing and exited 1,
  // which is the same output, and the same exit code, as an absence. It had
  // already produced a wrong conclusion in the tracker: several searches came
  // back empty while investigating #440 and were written up as "the breadcrumbs
  // appear in no `.ts` file". They were two screens further down the file that
  // was searched.
  //
  // 🔸 **What is measured here rather than assumed, because the tools disagree
  // and the disagreement is the whole defect.** On this tree, with the byte
  // planted back in:
  //
  //  - `git grep`, `git grep -I` and `git diff` all read the file as TEXT and
  //    found the matches. Git's binary test reads the first 8000 bytes only, and
  //    the byte was at 43961.
  //  - `git ls-files --eol` said `-text`, because that path scans the whole
  //    blob. Two answers from one program, and the one an agent's search runs
  //    through is the other one.
  //  - `git check-attr` said `unspecified` for every path, here and for a PNG:
  //    this repository has no `.gitattributes` and never has. A criterion built
  //    on one would be a list of exceptions with git's name on it.
  //  - The `grep` an agent actually runs skipped the file in silence.
  //
  // ⇒ **Git's own answer is therefore the wrong criterion**, and it is the one
  // the issue proposed: a NUL a few thousand bytes earlier makes git call the
  // file binary, which would take it out of the scan altogether — the gate would
  // go quiet on a worse instance of the same defect. The criterion here is the
  // one that does not have that hole and is still not a list: **a file is text
  // when its whole content decodes as UTF-8.** A NUL is valid UTF-8, so a source
  // file carrying one is still text and still reported; a PNG is not valid
  // UTF-8 at any offset. Measured over all 2378 tracked files, the two
  // partitions agree exactly — 953 text, 1425 not — so this is git's own line,
  // drawn without git's blind spot.
  //
  // 🔒 Git is kept as the SECOND OPINION rather than as the criterion: any file
  // the two partitions disagree about is reported by name, in both directions.
  // That is what stops the criterion from being a private opinion. A text file
  // whose bytes are not UTF-8 would otherwise be skipped in silence, and a
  // "binary" that decodes cleanly would be scanned as source.
  //
  // ⚠️ The negative half is the load-bearing one and it is a real binary out of
  // this tree, not a fabricated one: without it the check is "every file is
  // binary", which passes on a tree of nothing but images.
  {
    type Sighting = { path: string; offset: number; line: number; column: number; source: string; size: number; total: number };
    type Disagreement = { path: string; text: boolean };
    type OpaqueScan = {
      /** Files whose bytes this scan actually read. The floor is that it is not zero. */
      read: number;
      /** Of those, the ones the criterion calls text, and the ones it does not. */
      text: number;
      opaque: number;
      /** Listed and not readable. Reported, never skipped. */
      unread: string[];
      /** Text files carrying the byte. */
      sightings: Sighting[];
      /** Files git and the criterion partition differently. */
      disagreements: Disagreement[];
      /** git declining to answer, which must not read as a clean tree. */
      gitBroke: string | null;
      /** How many files git listed as text — zero over a tree with text in it is a scan that measured nothing. */
      gitText: number;
      /**
       * Tracked symlinks whose target is another path of the same universe, left
       * out of both partitions (issue #831, `AGENTS.md` -> `CLAUDE.md`). git
       * stores a link as the path it names and `git grep` never lists one, while
       * a read here follows it into the target — so the two would be judging
       * different objects, and the target's own bytes are read under its own
       * name. A link to anything else is read as before.
       */
      links: string[];
    };

    // The criterion — a file is TEXT when its whole content decodes as UTF-8 —
    // is `readsAsText` at the top of this file, because `CUR12` reads the same
    // partition and a second spelling of it would be two criteria.

    /** The detector: the byte every text tool in this toolchain stops at. */
    const OPAQUE = 0x00;
    const NEWLINE = 0x0a;

    const sightingOf = (path: string, bytes: Buffer): Sighting | null => {
      const offset = bytes.indexOf(OPAQUE);
      if (offset < 0) return null;
      let line = 1;
      let start = 0;
      for (let i = 0; i < offset; i++) {
        if (bytes[i] === NEWLINE) {
          line++;
          start = i + 1;
        }
      }
      let end = bytes.indexOf(NEWLINE, offset);
      if (end < 0) end = bytes.length;
      // How many there are, not just where the first one is: a message naming
      // one of two would be repaired once and read as finished, which is how
      // `cli.ts` came to carry a second copy of the same separator.
      let total = 0;
      for (let i = offset; i >= 0; i = bytes.indexOf(OPAQUE, i + 1)) total++;
      return {
        path,
        offset,
        line,
        column: offset - start + 1,
        size: bytes.length,
        total,
        // The byte rendered as the escape it should have been, so the message
        // shows the repair rather than describing it.
        source: bytes.toString('utf8', start, end).replace(/\u0000/g, '\\0').trim().slice(0, 110),
      };
    };

    /**
     * Which of these files git reads as TEXT, answered in `dir`. Git declining
     * is returned rather than thrown: silence read as a clean tree is the
     * failure this case exists for.
     */
    const askGit = (dir: string, args: readonly string[]): { text: Set<string>; broke: string | null } => {
      // A user's global excludes file would otherwise decide some of this, and a
      // machine that has one would measure something this repository does not ship.
      const isolated = ['-c', `core.excludesFile=${join(dir, 'no-such-global-excludes')}`];
      const probe = spawnSync('git', [...isolated, ...args], {
        cwd: dir,
        encoding: 'buffer',
        maxBuffer: 256 * 1024 * 1024,
      });
      // Exit 1 means "it matched nothing", which is an answer.
      if (spawnFailed(probe) || (probe.status !== 0 && probe.status !== 1)) {
        return {
          text: new Set(),
          broke:
            `git could not say which files it reads as text in ${dir} ` +
            `(${probe.error?.message ?? `exit ${String(probe.status)}: ${probe.stderr.toString('utf8').trim()}`}); ` +
            'this case fails closed rather than reading that as a clean tree',
        };
      }
      return {
        text: new Set(probe.stdout.toString('utf8').split('\u0000').filter((entry) => entry !== '')),
        broke: null,
      };
    };

    const scanDir = (dir: string, universe: readonly string[], gitArgs: readonly string[]): OpaqueScan => {
      const { text: gitText, broke } = askGit(dir, gitArgs);
      const out: OpaqueScan = { read: 0, text: 0, opaque: 0, unread: [], sightings: [], disagreements: [], gitBroke: broke, gitText: gitText.size, links: [] };
      const members = new Set(universe);
      /** A link that resolves — a dangling one is read below and reported unreadable, as before. */
      const isLinkWithin = (path: string): boolean => {
        try {
          return lstatSync(path).isSymbolicLink() && existsSync(path);
        } catch {
          return false;
        }
      };
      for (const rel of universe) {
        const at = join(dir, rel);
        if (isLinkWithin(at) && members.has(relative(realpathSync(dir), realpathSync(at)))) {
          out.links.push(rel);
          continue;
        }
        let bytes: Buffer;
        try {
          bytes = readFileSync(join(dir, rel));
        } catch (err) {
          // `readFileSync` throws ENOTDIR as readily as ENOENT when an ancestor
          // of the path is not a directory, and a crash is not a report.
          out.unread.push(`"${rel}" is listed in the tree and this scan could not read it: ${(err as Error).message}`);
          continue;
        }
        out.read++;
        const text = readsAsText(bytes);
        if (text) out.text++;
        else out.opaque++;
        if (broke === null && text !== gitText.has(rel)) out.disagreements.push({ path: rel, text });
        if (!text) continue;
        const sighting = sightingOf(rel, bytes);
        if (sighting !== null) out.sightings.push(sighting);
      }
      return out;
    };

    // A message is a thing somebody reads, so the fault list is capped and the
    // remainder counted — `firstFew` at the top of this file, shared with `CUR12`.

    const faultsOf = (scan: OpaqueScan): string[] => [
      // The floor is an entry here rather than a bare conjunct in the verdict, so
      // a planted run's detail names what went wrong instead of reading clean.
      ...(scan.read === 0
        ? ['not one file was read, so every clause below was measured against nothing and this scan cannot say a tree is clean']
        : []),
      ...(scan.gitBroke === null ? [] : [scan.gitBroke]),
      ...(scan.gitBroke === null && scan.text > 0 && scan.gitText === 0
        ? [`git listed no file as text while ${scan.text} decode as UTF-8, so its partition was not read — a pattern it never received (issue #1477) answers "no files" rather than failing`]
        : []),
      ...firstFew(scan.unread, 'unreadable'),
      ...firstFew(
        scan.sightings.map(
          (hit) =>
            `${hit.path} reads as text end to end (${hit.size} bytes, valid UTF-8) and carries ${hit.total} literal ` +
            `NUL(s), the first at byte ${hit.offset}, line ${hit.line} column ${hit.column}: \`${hit.source}\`. Write ` +
            'each as an escape — `\\0` or `\\u0000` — and the string value is identical while the file stops being ' +
            'binary to a text tool. As a raw byte, a search over this file matches nothing and exits 1, which is the ' +
            'same output as an absence',
        ),
        'text file(s) carrying the byte',
      ),
      ...firstFew(
        scan.disagreements.map((row) =>
          row.text
            ? `${row.path} decodes as UTF-8 end to end and git reads it as BINARY: a byte inside the window git tests ` +
              'makes it so, and a criterion taken from git would have dropped this file out of the scan instead of ' +
              'reporting it'
            : `${row.path} does not decode as UTF-8 and git reads it as TEXT: a text tool will search it and this ` +
              'criterion will not, so the file is unscanned by exactly the check that claims to cover it',
        ),
        'file(s) the two partitions read differently',
      ),
    ];

    // The live tree. `git ls-files` is the universe and git's own `-I` partition
    // is the second opinion; both are asked of the repository this file sits in.
    const listed = spawnSync('git', ['ls-files', '-z'], { cwd: root, encoding: 'buffer', maxBuffer: 256 * 1024 * 1024 });
    const treeFault =
      listed.error !== undefined || listed.status !== 0
        ? `git could not list the tracked files (${listed.error?.message ?? `exit ${String(listed.status)}: ${listed.stderr.toString('utf8').trim()}`})`
        : null;
    const tracked = treeFault === null ? listed.stdout.toString('utf8').split('\u0000').filter((entry) => entry !== '') : [];
    // `^` and not the empty pattern (issue #1477): both match every line, so they list the same files, but Bun
    // 1.2.0 (then the declared minimum) drops an empty argument when it starts a process, and `-e ''` reached git
    // as a bare `-e` (exit 129, 0 files). A pattern no Bun can drop is the only one this scan can rely on.
    const liveScan = scanDir(root, tracked, ['grep', '-I', '-l', '-z', '-e', '^']);

    // The controls, planted in a throwaway directory out of THIS tree's own
    // files, so no shape below is a fabricated stand-in and no offset is a
    // literal. The victims are the largest file on each side of the criterion:
    // the biggest text file is the one long enough for git to still read the
    // planted byte's file as text, which is the silent shape, and the biggest
    // non-text file is a real binary rather than an imitation of one.
    const biggestOf = (want: boolean): string | null => {
      let best: { rel: string; size: number } | null = null;
      for (const rel of tracked) {
        let bytes: Buffer;
        try {
          bytes = readFileSync(join(root, rel));
        } catch {
          continue;
        }
        if (readsAsText(bytes) !== want) continue;
        const size = bytes.length;
        if (best === null || size > best.size) best = { rel, size };
      }
      return best?.rel ?? null;
    };
    const textVictim = biggestOf(true);
    const opaqueVictim = biggestOf(false);

    const controlFaults: string[] = [];
    let controlNote = '';
    if (textVictim === null) {
      controlFaults.push('no tracked file reads as text, so the red-first plant had nothing to aim at');
    } else {
      const dir = mkdtempSync(join(harnessTemp(), 'rigc-opaque-'));
      try {
        const source = readFileSync(join(root, textVictim));
        // ① the same file, untouched: the positive control, reported in no way.
        writeFileSync(join(dir, 'pristine.txt'), source);
        // ② the byte at the END of it — as deep as this tree can put one, which
        //    is the shape git still reads as text and a search still goes silent
        //    over. This is issue #465 replayed on a real file at a real offset.
        writeFileSync(join(dir, 'deep.txt'), Buffer.concat([source, Buffer.from([OPAQUE])]));
        // ③ the byte at the FRONT of it: the instance a criterion taken from git
        //    would have dropped, so it has to be reported AND to disagree.
        writeFileSync(join(dir, 'front.txt'), Buffer.concat([Buffer.from([OPAQUE]), source]));
        // ④ a real binary out of this tree: reported in no way. 🔒 the negative
        //    half, and the one the whole case rests on — without it the check
        //    is "every file is binary", which passes on a tree of images.
        //
        //    ⚠️ It FALLS BACK rather than faulting when the tree has no binary
        //    in it. Faulting there would be a clause attached to the wrong
        //    thing: moving the reference frames out of git is a repository
        //    improvement, and it must not turn this case red. What the clause
        //    needs is a file that does not decode as UTF-8, which a real one
        //    supplies with more fidelity and a synthesised one supplies just as
        //    validly; which was used is printed either way. The live tree's own
        //    figure below is the measurement that says how many real ones were
        //    read and excluded.
        if (opaqueVictim !== null) copyFileSync(join(root, opaqueVictim), join(dir, 'opaque.bin'));
        else writeFileSync(join(dir, 'opaque.bin'), Buffer.from([0xff, 0xfe, OPAQUE, 0xff]));
        const opaqueName = opaqueVictim ?? 'four bytes no tracked file supplied, because this tree has no binary in it';

        const planted = scanDir(dir, ['pristine.txt', 'deep.txt', 'front.txt', 'opaque.bin'], [
          'grep', '--no-index', '-I', '-l', '-z', '-e', '^',
        ]);
        const named = planted.sightings.map((hit) => hit.path).sort();
        const differed = planted.disagreements.map((row) => row.path).sort();
        const deep = planted.sightings.find((hit) => hit.path === 'deep.txt');
        if (planted.gitBroke !== null) controlFaults.push(planted.gitBroke);
        if (planted.unread.length > 0) controlFaults.push(...planted.unread);
        if (planted.read !== 4) controlFaults.push(`the planted directory read ${planted.read} of its 4 files`);
        if (named.join(', ') !== 'deep.txt, front.txt') {
          controlFaults.push(
            `the byte planted at the end of \`${textVictim}\` and at the front of it had to be reported and nothing ` +
              `else had to be — the untouched copy and the binary \`${opaqueName}\` are the two halves that ` +
              `keep this from being a check that reports everything — and instead the reported set was ` +
              `[${named.join(', ') || 'nothing at all'}]`,
          );
        }
        if (differed.join(', ') !== 'front.txt') {
          controlFaults.push(
            'git had to read the deep plant as TEXT and the front plant as BINARY — that difference is why the ' +
              `criterion here is not git's — and instead the files the two partitions disagreed about were ` +
              `[${differed.join(', ') || 'none of them'}]`,
          );
        }
        if (deep !== undefined && deep.offset !== source.length) {
          controlFaults.push(`the deep plant was reported at byte ${deep.offset} and it was written at ${source.length}`);
        }
        // ⑤ the floor, seen to fire: a scan that reads nothing must not report a
        //    clean tree.
        if (faultsOf(scanDir(dir, [], ['grep', '--no-index', '-I', '-l', '-z', '-e', '^'])).length === 0) {
          controlFaults.push(
            'a scan given no files at all came back clean, so a scan that stopped finding files would go quiet ' +
              'rather than red',
          );
        }
        controlNote =
          `the byte planted at both ends of \`${textVictim}\` (${source.length} bytes, the largest text file in the ` +
          `tree) is reported at byte ${source.length} and at byte 0, git reads the first of those as text and the ` +
          `second as binary, an untouched copy and \`${opaqueName}\` are reported in no way, and a scan of nothing ` +
          'faults on its floor';
      } finally {
        rmSync(dir, { recursive: true, force: true });
      }
    }

    const probes = [
      ...(treeFault === null ? [] : [treeFault]),
      ...faultsOf(liveScan),
      ...controlFaults,
    ];
    say(
      'CUR11_NO_TRACKED_FILE_THAT_READS_AS_TEXT_CARRIES_A_BYTE_THAT_MAKES_IT_BINARY',
      probes.length === 0,
      probes.length === 0
        ? `${liveScan.read} tracked file(s) read — ${liveScan.text} decode as UTF-8 end to end and ${liveScan.opaque} ` +
          `do not — and not one of the ${liveScan.text} carries a NUL. Git lists ${liveScan.gitText} as text and partitions the same ${liveScan.read} the ` +
          `same way, with no file either of them reads differently` +
          (liveScan.links.length === 0
            ? ''
            : `; ${liveScan.links.length} tracked symlink(s) left out of both, each naming a tracked file read ` +
              `under its own name (${liveScan.links.join(', ')})`) +
          `. The controls: ${controlNote}`
        : probes.join('\n          '),
      'a raw NUL two screens into `cli.ts` (#465) made every search over the file that owns rigc\'s report text come ' +
        'back empty with exit 1 — indistinguishable from an absence, and already the source of one wrong conclusion ' +
        'in the tracker (#440). The criterion for "text" is the hard half and it must not be a list: git\'s own ' +
        'answer looks like one and is not usable, because git tests the first 8000 bytes only and would have dropped ' +
        'this very file out of the scan had the byte been earlier. UTF-8 validity has no such window, and git is kept ' +
        'beside it as a second opinion so a disagreement is named rather than silently deciding which files get read',
    );
  }

  // --- CUR12: a coordinate written into prose is a figure nothing re-takes ---
  //
  // ⭐ **The same class as every case above, pointed at the one figure none of
  // them reads: a citation.** A line number naming a document looks exactly the
  // same whether the legend it points at is still on that line or five lines
  // below it, and a reader who follows it lands somewhere plausible and wrong.
  // Issue #487 re-read the seven this file carried: five named the wrong line,
  // one named a table row that cannot hold the verdict its docstring said was
  // there, and one was right. A form that is wrong six times in seven, in the
  // only file in the repository that writes it, is a form to remove rather than
  // one to maintain — which is why this refuses the shape instead of resolving
  // it. Nothing here would have caught the six; what it catches is the seventh
  // being written again.
  //
  // 🔒 **The criterion is what a LITERAL coordinate is, and that is derivable
  // rather than stylistic.** Every coordinate this run prints is interpolated
  // from a scan that just took it, so the figures in `GT01`'s and `DQ01`'s own
  // output are invisible to this and the comment that copies one down is not.
  // That is the whole line between a figure a run takes and a figure somebody
  // wrote — and this control holds to it in its own header, which is why no
  // example below carries the number that would make it readable.
  //
  // **Three exclusions, each derived, each printed or named:**
  //
  //  1. a file whose header declares it a dated record keeps its coordinates, on
  //     the footing `CUR01` already gives it: its figures were measured once and
  //     are not kept current. The set is printed rather than described, so it
  //     cannot grow quietly into a way to switch this off.
  //  2. FENCED blocks, because a quoted transcript legitimately carries the
  //     coordinates the tool printed into it, and `GT02`/`DQ02` are what hold
  //     those to their runs. Inline code spans are deliberately NOT excluded —
  //     the form this refuses is written inside one.
  //  3. a path that resolves to nothing tracked. `SkeletonJson.ts` names the
  //     runtime's own source: no gate here can resolve it, no edit here can move
  //     it, and `src/rig.ts` reads better for citing it.
  //
  // ⚠️ **What it does not reach, stated rather than implied.** A coordinate
  // written without its path — a bullet continuing the one above it — resolves
  // to nothing on its own and this scan is blind to it. Two of the seven were
  // spelled that way, which is why the repair was to take the form out rather
  // than to trust this to find it; the two that survive in this file both point
  // into the runtime. A BASENAME is resolved when exactly one tracked file
  // carries it, so `validate.ts` is not a different defect with a shorter name.
  {
    /**
     * A `path:line` in running text. The path is resolved below — punctuation
     * does not define the population. ⚠️ It opens on a dot as well as on a word
     * character because a tracked path may: the first version did not, and the
     * plant below — which takes its target off the tracked list rather than
     * choosing one — landed on a dotted directory and went quiet.
     */
    const CITATION = /(^|[^A-Za-z0-9_./-])([A-Za-z0-9_.][A-Za-z0-9_./-]*\.[A-Za-z0-9]+):(\d+)/g;

    const listed = spawnSync('git', ['ls-files', '-z'], { cwd: root, encoding: 'buffer', maxBuffer: 256 * 1024 * 1024 });
    const treeFault =
      listed.error !== undefined || listed.status !== 0
        ? `git could not list the tracked files (${listed.error?.message ?? `exit ${String(listed.status)}: ${listed.stderr.toString('utf8').trim()}`})`
        : null;
    const tracked = treeFault === null ? listed.stdout.toString('utf8').split('\u0000').filter((entry) => entry !== '') : [];
    const trackedSet = new Set(tracked);
    const byBase = new Map<string, string[]>();
    for (const rel of tracked) byBase.set(basename(rel), [...(byBase.get(basename(rel)) ?? []), rel]);

    /** What a cited path names in this repository, or null when it names nothing tracked. */
    const resolveCited = (cited: string): string | null => {
      if (trackedSet.has(cited)) return cited;
      const sameName = byBase.get(cited);
      return sameName !== undefined && sameName.length === 1 ? sameName[0] : null;
    };

    type CitationScan = { read: number; dated: string[]; faults: string[] };
    const scanCitations = (files: ReadonlyArray<{ path: string; text: string }>): CitationScan => {
      const out: CitationScan = { read: 0, dated: [], faults: [] };
      for (const file of files) {
        const raw = file.text.split('\n');
        if (raw.slice(0, CURRENCY_HEADER_LINES).some((line) => line.includes(DATED_RECORD_MARKER))) {
          out.dated.push(file.path);
          continue;
        }
        out.read++;
        const lines = linesOutsideFences(raw);
        for (let i = 0; i < lines.length; i++) {
          const line = lines[i];
          if (line === null) continue;
          for (const found of line.matchAll(CITATION)) {
            const target = resolveCited(found[2]);
            if (target === null) continue;
            out.faults.push(
              `${file.path}:${i + 1} writes \`${found[2]}:${found[3]}\` into running text, and \`${target}\` is a ` +
                'tracked file whose line numbers move under it with nothing going red: name what is there, or quote it',
            );
          }
        }
      }
      return out;
    };

    const liveFiles: { path: string; text: string }[] = [];
    for (const rel of tracked) {
      let bytes: Buffer;
      try {
        bytes = readFileSync(join(root, rel));
      } catch {
        continue;
      }
      if (!readsAsText(bytes)) continue;
      liveFiles.push({ path: rel, text: bytes.toString('utf8') });
    }
    const live = scanCitations(liveFiles);

    // The controls, built out of this tree's own files and held in memory: the
    // scan reads text rather than a directory, so planting on disk would add a
    // filesystem to a check that has none. The victim is the SHORTEST tracked
    // text file — real, and small enough that the plant is the only thing in it
    // this scan can see. Nothing below is a literal: the paths come off the
    // tracked list and the line number is the victim's own length.
    const victim = [...liveFiles].sort(
      (a, b) => a.text.length - b.text.length || a.path.localeCompare(b.path),
    )[0];
    const nested = tracked.find((rel) => rel !== basename(rel) && (byBase.get(basename(rel)) ?? []).length === 1);
    const controlFaults: string[] = [];
    let controlNote = '';
    if (victim === undefined) controlFaults.push('no tracked file reads as text, so the plants below had nothing to aim at');
    else if (nested === undefined)
      controlFaults.push('no tracked path has a basename no other tracked path shares, so the bare-name plant could not be built');
    else {
      const at = victim.text.split('\n').length;
      const cite = (spelling: string): string => `${victim.text}\nit is stated at \`${spelling}:${at}\`, they said\n`;
      const one = (name: string, text: string, want: number): void => {
        const got = scanCitations([{ path: name, text }]);
        if (got.faults.length !== want) {
          controlFaults.push(
            `the ${name} plant was reported ${got.faults.length} time(s) and this control requires ${want}` +
              (got.faults.length === 0 ? '' : ` — it said: ${got.faults.join('; ')}`),
          );
        }
        if (want > 0 && !got.faults.some((fault) => fault.includes(nested))) {
          controlFaults.push(`the ${name} plant was not reported against \`${nested}\`, so it resolved to something else`);
        }
      };
      one('untouched', victim.text, 0);
      one('by-path', cite(nested), 1);
      one('by-name', cite(basename(nested)), 1);
      one('fenced', `${victim.text}\n\`\`\`\nit is stated at ${nested}:${at}\n\`\`\`\n`, 0);
      const datedPlant = scanCitations([
        { path: 'dated', text: `# probe\n\n${DATED_RECORD_MARKER}\n${cite(nested)}` },
      ]);
      if (datedPlant.faults.length !== 0 || datedPlant.dated.length !== 1) {
        controlFaults.push(
          `the dated-record plant was reported ${datedPlant.faults.length} time(s) and left alone ` +
            `${datedPlant.dated.length} time(s); the marker has to take it out of the scan and out of nothing else`,
        );
      }
      controlNote =
        `a copy of \`${victim.path}\` with one line added citing \`${nested}\` is reported once by that path and ` +
        `once by the bare \`${basename(nested)}\`, both naming \`${nested}\`; the same line inside a fence and the ` +
        'same line under a dated-record header are reported in no way, and the untouched copy is reported in no way';
    }

    const probes = [
      ...(treeFault === null ? [] : [treeFault]),
      ...floorProbes(
        [
          [tracked.length, 1, `git listed ${tracked.length} tracked path(s)`],
          [live.read, 1, `${live.read} of them read as text and were scanned`],
        ],
        'a step that comes back empty makes every clause below read a clean tree off nothing',
      ),
      ...firstFew(live.faults, 'coordinate(s)'),
      ...controlFaults,
    ];
    const held = probes.length === 0;
    say(
      'CUR12_NO_LINE_NUMBER_IN_THE_TREE_POINTS_AT_A_TRACKED_FILE',
      held,
      probeDetail(
        held,
        probes,
        `${live.read} tracked file(s) that read as text, scanned outside their fenced blocks, out of ` +
          `${tracked.length} tracked path(s); ${live.dated.length} left alone as dated records ` +
          `(${live.dated.length === 0 ? 'none' : live.dated.join(', ')}) — and not one line of the rest writes a ` +
          `coordinate at a tracked file. The controls: ${controlNote}`,
      ),
      'a citation is the figure this file was full of and had never checked: seven `path:line` coordinates stood in ' +
        'these comments and six of them were wrong — five naming the wrong line, one naming a table row that cannot ' +
        'hold the verdict its docstring said was there (#487). The criterion is what a LITERAL coordinate is, which ' +
        'is why it can be derived at all: every coordinate this run prints is interpolated from the scan that just ' +
        'took it, so a report\'s own figures are invisible here and a comment copying one down is not. ⚠️ It is blind ' +
        'to a coordinate written without its path, which is how two of the seven were spelled — the repair for those ' +
        'was to take the form out, not to trust this to find them',
    );
  }

  // --- CUR13/CUR14: the gallery index tables, against the gallery (#520) ----
  //
  // ⭐ The same defect as `CUR07`, on the surface a stranger meets first.
  // `README.md` carried a table of **six** examples under a heading that said
  // **six**, and `bun run selftest` compiled and gated **seven** — the missing
  // one being `gallery/look`, the only example that stars a `slider`, which is
  // to say the only one demonstrating the parameter axis at all. `grep -c slider
  // README.md` answered 0.
  //
  // 🔒 Why nothing caught it, which is the part worth keeping: three gates cross
  // this surface and every one of them derives its population from what the page
  // SAYS. `PKG02` resolves the links that are there. The currency cases above
  // check the figures a doc states. `GT01`–`GT06` hold each example README's
  // quoted output and never look upward at the index that should name the
  // directory. An absent row states nothing, resolves nothing and quotes
  // nothing, so it is invisible by construction to all three. The population has
  // to come from the TREE, and `galleryExampleNames` is where it comes from.
  //
  // ⚠️ Scope, because the edges decide what this is worth. The documents that
  // index the gallery are the front page and the gallery's own page — `README.md`
  // and the `.md` files directly under `gallery/` — and NOT every table in the
  // tree whose first column says `Example`: `NOTICE.md`, `docs/LADDER.md` and
  // `docs/INGEST.md` each carry one about the benchmark corpus, which is a
  // different set entirely. A per-example README is out for the same reason.
  {
    const galleryRoot = join(root, 'gallery');
    const examples = galleryExampleNames(galleryRoot);
    const candidates = [
      'README.md',
      ...(existsSync(galleryRoot) ? trackedIn(root, 'gallery', (name) => name.endsWith('.md')) : []),
    ];
    const indexes = candidates
      .filter((path) => existsSync(join(root, path)))
      .map((path) => readGalleryIndex(path, readFileSync(join(root, path), 'utf8')))
      .filter((index) => index.header !== null);

    const live = indexes.flatMap((index) => galleryIndexFaults(index, examples));

    // 🌱 The two directions, driven through the same reader the verdict uses,
    // on text this case writes. A control on the TREE would be a control that
    // goes quiet the day the tree is correct, which is every day after the
    // repair; these stay.
    const rowFor = (name: string): string =>
      `| [\`gallery/${name}\`](gallery/${name}) | **\`ik\` constraints** | what it is |`;
    const synthetic = (names: readonly string[], heading: string): GalleryIndex =>
      readGalleryIndex(
        'probe.md',
        [heading, '', '| Example | Stars | What it is |', '| --- | --- | --- |', ...names.map(rowFor), ''].join('\n'),
      );
    const complete = synthetic(examples, '## probe');
    const faithful = galleryIndexFaults(complete, examples);
    const dropped = raisedBy(galleryIndexFaults(synthetic(examples.slice(1), '## probe'), examples), { was: faithful });
    const invented = raisedBy(
      galleryIndexFaults(synthetic([...examples, 'a-directory-the-tree-does-not-have'], '## probe'), examples),
      { was: faithful },
    );
    const miscounted = raisedBy(galleryIndexFaults(synthetic(examples, '## probe — zero rigs'), examples), {
      was: faithful,
    });
    const counted = raisedBy(
      galleryIndexFaults(synthetic(examples, `## probe — ${NUMBER_WORDS[examples.length] ?? 'many'} rigs`), examples),
      { was: faithful },
    );
    const controlFaults = [
      ...(dropped.length === 0 ? ['an index one row short of the tree was not faulted'] : []),
      ...(invented.length === 0 ? ['an index naming a directory the tree does not have was not faulted'] : []),
      ...(miscounted.length === 0 ? ['a heading whose number word contradicts its own table was not faulted'] : []),
      ...faithful.map((fault) => `an index naming exactly the tree's examples was faulted anyway — ${fault}`),
      ...counted.map((fault) => `a heading whose number word matches its own table was faulted anyway — ${fault}`),
      ...(complete.rows.length === examples.length
        ? []
        : [`the reader found ${complete.rows.length} row(s) in a table this case wrote ${examples.length} into`]),
    ];

    const probes = [
      ...floorProbes(
        [
          [examples.length, 1, `${examples.length} example(s) under gallery/ carry both a rig and a motion spec`],
          [indexes.length, 1, `${indexes.length} of ${candidates.length} candidate document(s) carry an index table`],
          [indexes.filter((index) => index.path === 'README.md').length, 1, 'README.md carries a gallery index table'],
          [indexes.reduce((n, index) => n + index.rows.length, 0), 1, 'the reader got a row out of those tables'],
        ],
        'and a step that comes back empty makes this case compare two empty sets and print green',
      ),
      ...live,
      ...controlFaults,
    ];
    const held = probes.length === 0;
    say(
      'CUR13_EVERY_GALLERY_EXAMPLE_THIS_RUN_GATES_IS_A_ROW_IN_EVERY_INDEX_OF_THEM',
      held,
      probeDetail(
        held,
        probes,
        `${indexes.length} index table(s) — ${indexes.map((index) => index.path).join(', ')} — name exactly the ` +
          `${examples.length} example(s) this run compiles and gates (${examples.join(', ')}), each heading's own ` +
          'count word included, with no row left over',
      ),
      'the front page is the one surface that SHIPS, and it indexed six of seven examples under a heading that ' +
        'said six — the missing one being the only rig in the tree that stars a `slider`, so the parameter axis ' +
        'was unreachable from the door npm puts a reader at. The verdict is set equality in both directions and ' +
        'deliberately not a count: a table that lost five rows clears any floor written as *at least one*, and a ' +
        'table that gained a fictional one clears any written as *every example appears*. The heading clause faults ' +
        'nothing when the heading carries no number word, because deleting a hand-kept figure is the repair this ' +
        'repository asks for and must not be the outcome that goes red',
    );

    // --- CUR14: the Stars cell against the rig spec --------------------------
    //
    // 🔸 #520 asked whether `Stars` is derivable. Measured: **half of it is, and
    // the half that is not cannot be rescued by narrowing the match.** Three of
    // the seven examples star a constraint kind their rig declares (`walk`/`ik`,
    // `ride`/`path`, `look`/`slider`); the other four star things that are not
    // constraints at all — a mesh generator, a timeline type, a deform model —
    // and rigc's vocabulary REUSES the tokens across those namespaces.
    // `gallery/portrait` writes `` `transform` `` in a code span, meaning the
    // deform transform kind, and declares no `transform` constraint; so the
    // reverse direction — *a kind named in a cell is one the example declares* —
    // reports a defect on a correct row, whether it reads the whole cell or only
    // its code spans.
    //
    // ⇒ What is held is the forward direction alone, and this comment is the
    // "say so in the control's own words" the card asked for: a cell may say
    // more than the rig declares, and nothing here objects. What it may not do
    // is leave a declared constraint kind out — which is exactly what a `look`
    // row would have done if #520 had been closed by pasting a row in without
    // the word `slider` in it, leaving the parameter axis as absent from the
    // front page as it was before.
    {
      const declared = new Map(examples.map((name) => [name, galleryConstraintKinds(galleryRoot, name)]));
      const missing: string[] = [];
      let measured = 0;
      let noStars = 0;
      for (const index of indexes) {
        for (const row of index.rows) {
          const kinds = declared.get(row.example) ?? [];
          if (kinds.length === 0) continue;
          if (row.stars === null) {
            noStars++;
            continue;
          }
          for (const kind of kinds) {
            measured++;
            if (!new RegExp(`\\b${kind}\\b`).test(row.stars)) {
              missing.push(
                `${index.path}: gallery/${row.example}'s rig declares a \`${kind}\` constraint and its Stars cell ` +
                  `does not say "${kind}" — "${row.stars}"`,
              );
            }
          }
        }
      }
      const starsProbes = [
        ...floorProbes(
          [
            [measured, 1, `${measured} (index row, declared constraint kind) pair(s) were compared`],
            [[...declared.values()].filter((kinds) => kinds.length > 0).length, 1, 'some example declares a constraint at all'],
          ],
          'and a scan that pairs nothing reports a clean gallery off no comparison',
        ),
        ...(noStars === 0 ? [] : [`${noStars} row(s) sat in an index table that declares no \`Stars\` column, so their cells were never read`]),
        ...missing,
      ];
      const starsHeld = starsProbes.length === 0;
      say(
        'CUR14_A_GALLERY_INDEX_ROW_NAMES_THE_CONSTRAINT_KINDS_ITS_EXAMPLE_DECLARES',
        starsHeld,
        probeDetail(
          starsHeld,
          starsProbes,
          `${measured} (row, kind) pair(s) across ${indexes.length} index table(s): every constraint kind a rig spec ` +
            `declares is a word its own Stars cell says — ` +
            examples
              .filter((name) => (declared.get(name) ?? []).length > 0)
              .map((name) => `${name} ${(declared.get(name) ?? []).join('+')}`)
              .join(', '),
        ),
        'the row alone was not the repair. A `look` row whose Stars cell described a head turn would have satisfied ' +
          'CUR13 completely and left `grep -c slider README.md` at 0, which is the sentence #520 actually opens with. ' +
          '⚠️ One direction only, and the reason is a measurement rather than an omission: rigc spells a deform ' +
          'model, an attachment kind and a constraint kind out of one vocabulary, so `gallery/portrait`\'s correct ' +
          '`transform` cell is indistinguishable from a false claim about a `transform` constraint. A cell may ' +
          'therefore say more than its rig declares; it may not say less',
      );
    }
  }

  // --- CUR15: what CLAUDE.md says the package is, against what it is (#524) --
  //
  // `CUR07` derives one paragraph of `CLAUDE.md` from the tree. Three bullets
  // below it stood a second sentence naming a set the tree derives, and nothing
  // read it: *"The published package is an allowlist, not the repository:
  // `cli.ts`, `src/`, and the only two modules `src/` reaches outside itself"*.
  // ⚠️ It named FOUR of the nineteen entries `files` then held — `cli.ts`,
  // `src`, `tools/plate.ts`, `tools/font5x7.ts` — and issue #524 says three,
  // which its own arithmetic contradicts fifteen entries later.
  //
  // 🔑 **The verdict is deliberately NOT `CUR07`'s.** `CUR07` compares for
  // equality because the doctrine wants its spine-core exceptions named — "an
  // unnamed exception is how a rule erodes". The package is the opposite case:
  // the outcome this repository wants is a document that names NO entry and
  // cites `npm pack --dry-run`, which is what `RELEASING.md` did with the same
  // drift (#516). Equality is therefore the one verdict that must not be used
  // here — it is satisfied by a bullet that writes all nineteen out, which is
  // the hand-kept copy of a machine-readable list this card exists to refuse.
  //
  // ⇒ So the set compared is not the package. It is **the modules `src/` reaches
  // outside itself**, which is the only set the bullet's RULE is about, and the
  // clause is that the bullet names that set and nothing else in `files`.
  // Naming every path fails it by nineteen rows; naming the package's contents
  // at all fails it; and the two modules stay named, which is what the rule
  // needs to be read at all.
  //
  // 🔒 The clause that had never existed anywhere is the last one: every module
  // in that derived set is actually covered by `files`. The bullet states the
  // consequence of getting this wrong — an installed package throwing `Cannot
  // find module` while the repository goes on running — and until now nothing
  // in the tree checked the fact, only the sentence.
  //
  // ⚠️ What was tried and rejected, because the near miss is the finding. #524
  // asks for a population of *documents that enumerate the package*, faulting
  // none when none does. That population is not recognisable from the text: the
  // one document in this tree that has ALREADY taken the repair — RELEASING.md,
  // rewritten by #516 — names `bin/rigc.cjs`, `.claude-plugin` and `skills` in
  // code spans, in one sentence, in the paragraph explaining what the package
  // holds. Three entries there against four in the defect, so any count-based
  // rule separating the defect from the model repair is a threshold of exactly
  // four with nothing but those two documents holding it up. The scope is
  // therefore `CUR07`'s — one named file, one bullet found by its own rule
  // sentence — and this comment is where that stands instead of a checker.
  {
    const claudeMd = readFileSync(join(root, 'CLAUDE.md'), 'utf8');
    const bullet = claudeMd
      .split(/\n- /)
      .map((text) => text.replace(/\s+/g, ' '))
      .find((text) => /crosses a directory has to be added to/.test(text));
    const derived = modulesSrcReachesOutsideItself(root);

    /** The `files` entry a code span names, or null — `src/` excluded, being the bullet's SUBJECT. */
    const entryNamed = (span: string): string | null => {
      const path = span.replace(/\/+$/, '');
      if (path === 'src' || path.startsWith('src/')) return null;
      for (const entry of allowlist) if (path === entry || path.startsWith(`${entry}/`)) return path;
      return null;
    };
    const claimedIn = (text: string): string[] =>
      [
        ...new Set(
          [...text.matchAll(/`([^`]+)`/g)].map((m) => entryNamed(m[1])).filter((path): path is string => path !== null),
        ),
      ].sort();

    /**
     * What one spelling of the bullet gets wrong, which is the judge the
     * controls below call rather than a second reading that would agree with
     * this one by construction.
     */
    const bulletFaults = (text: string): string[] => {
      const claimed = claimedIn(text);
      const said = text.match(/\*\*(\w+)\*\* modules `src\/` reaches outside itself/)?.[1]?.toLowerCase();
      const out: string[] = [];
      if (said !== NUMBER_WORDS[derived.length]) {
        out.push(
          `the bullet says "${said ?? '(none)'}" and ${derived.length} module(s) outside src/ are imported from it ` +
            `(${NUMBER_WORDS[derived.length] ?? String(derived.length)})`,
        );
      }
      for (const module of derived) {
        if (!claimed.includes(module)) out.push(`src/ imports ${module} from outside itself and the bullet does not name it`);
      }
      for (const named of claimed) {
        if (!derived.includes(named)) {
          out.push(
            `the bullet names \`${named}\` — a \`files\` entry that src/ does not reach — so it is describing the ` +
              "package's contents rather than the rule, which is the enumeration #524 removed",
          );
        }
      }
      return out;
    };

    const claimed = bullet === undefined ? [] : claimedIn(bullet);
    const countWord = bullet?.match(/\*\*(\w+)\*\* modules `src\/` reaches outside itself/)?.[1]?.toLowerCase();
    const faults = [
      ...(bullet === undefined
        ? ['CLAUDE.md has no bullet stating the rule about an import that crosses a directory']
        : bulletFaults(bullet)),
      // 🔒 The fact rather than the sentence, and the clause nothing in this
      // tree had ever checked: a module `src/` reaches that `files` leaves out
      // installs as `Cannot find module` while the repository goes on running.
      ...derived
        .filter((module) => !shipsToo(module))
        .map((module) => `🔒 src/ imports ${module} and \`files\` does not ship it — the installed package throws Cannot find module`),
    ];

    // 🌱 The trap both halves of #524 name, driven through the same judge rather
    // than asserted: a bullet that also writes the WHOLE allowlist out has to
    // fail, or this is a rule that rewards enumerating; a bullet that names none
    // of the derived set has to fail too, or the rule loses the names it is
    // about; and the spelling that states exactly the derived set has to come
    // back clean, or the case is a rule no document can satisfy.
    const RULE = 'A new runtime import that crosses a directory has to be added to `files` in `package.json`.';
    const ideal =
      `${RULE} The only **${NUMBER_WORDS[derived.length]}** modules \`src/\` reaches outside itself are ` +
      `${derived.map((module) => `\`${module}\``).join(' and ')}. \`npm pack --dry-run\` lists what would ship.`;
    const faithful = bulletFaults(ideal);
    const enumerated = raisedBy(bulletFaults(`${ideal} It holds ${allowlist.map((e) => `\`${e}\``).join(', ')}.`), {
      was: faithful,
    });
    const silent = raisedBy(bulletFaults(`${RULE} What is in it is not written out here.`), { was: faithful });
    const controlFaults = [
      ...(enumerated.length === 0 ? ['a bullet that also writes out every `files` entry was not faulted'] : []),
      ...(silent.length === 0 ? ['a bullet naming none of the modules src/ reaches was not faulted'] : []),
      ...faithful.map((fault) => `a bullet stating exactly the derived set was faulted anyway — ${fault}`),
      ...(entryNamed('src/') === null && entryNamed('src/compile.ts') === null
        ? []
        : ["the bullet's own subject `src/` was read as one of the entries it enumerates"]),
      ...(entryNamed('package.json') === null && entryNamed('npm pack --dry-run') === null
        ? []
        : ['a code span that is not a `files` entry was read as one']),
      ...(derived.every((module) => entryNamed(module) === module) ? [] : ['a module src/ reaches was not read as a `files` entry']),
    ];

    const probes = [
      ...floorProbes(
        [
          [derived.length, 1, `${derived.length} module(s) outside src/ are imported from inside it`],
          [claimed.length, 1, `${claimed.length} \`files\` entr(ies) are named in the bullet`],
          [allowlist.length, 2, `\`files\` holds ${allowlist.length} entr(ies)`],
        ],
        'and a derivation that comes back empty lets this compare two empty sets and call the doctrine current',
      ),
      ...faults,
      ...controlFaults,
    ];
    const held = probes.length === 0;
    say(
      'CUR15_THE_MODULES_CLAUDE_MD_SAYS_SRC_REACHES_OUTSIDE_ITSELF_ARE_THE_ONES_IT_DOES',
      held,
      probeDetail(
        held,
        probes,
        `src/ imports ${derived.length} module(s) from outside itself — ${derived.join(', ')} — the doctrine names ` +
          `exactly those as "${countWord}" and no other of the ${allowlist.length} \`files\` entr(ies), and \`files\` ` +
          'ships every one of them',
      ),
      'the same sentence-drift `CUR07` was written for, on the bullet three below it: the doctrine defined the ' +
        'published package by naming four of the entries `files` held and went on doing it while fifteen more ' +
        'arrived. ⚠️ The verdict is NOT `CUR07`\'s equality against that list, and the difference is the whole ' +
        'design — equality is satisfied by a bullet that writes every entry out, and a document enumerating the ' +
        'package is the defect rather than the repair (#516 deleted the identical list from RELEASING.md). The set ' +
        'held here is the one the rule is about, so naming the package at all fails by every entry named. 🔒 And ' +
        'the last clause is a fact nothing had ever checked: that `files` actually ships what `src/` reaches',
    );
  }

  // --- CUR16: the allowlist is closed under relative import (#527) ----------
  //
  // 🔒 `CUR15`'s last clause holds this fact over ONE corner of the graph — the
  // modules `src/` reaches — because that corner is what its bullet's rule is
  // about. The fact is a property of the whole package: a shipped module that
  // imports a module `files` leaves out installs as `Cannot find module` on the
  // command that needs it, and which directory the importer happens to sit in
  // has nothing to do with that.
  //
  // ⚠️ **The residue was measured before this was written**, because "wider" is
  // a claim and not a description. On the tree of 2026-09-13: `src/` reached two
  // modules outside itself, so `CUR15` covered two edges, while the shipped code
  // set carried 79 relative import edges between 37 files. Those figures are a
  // record of that day and the case's own detail line is the live one. `cli.ts`
  // reaching a new `tools/` helper, or `tools/plate.ts` reaching one, is the
  // same defect with the same consequence and `CUR15` is green on it — driven
  // below on an importer outside `src/` rather than asserted here.
  //
  // ⇒ This is a gate on the FACT, deliberately, and not on the sentence that
  // described it. `ROADMAP.md` carried a second copy of the claim `CUR15`
  // falsified — *"nothing in the tree fails when a module is added and not
  // listed"* — and a scanner over that prose cannot be built. Measured, not
  // assumed: `CUR15`'s own bullet finder reports nothing on `ROADMAP.md`, so
  // widening its file set adds a file a scan reads nothing in; and the only
  // finder that reaches the paragraph is one keyed to the defect's own wording,
  // which has one site today and none the moment it is repaired. A scan whose
  // floor can only be zero is what `CUR01`'s floors exist to refuse. So the
  // sentence is deleted rather than re-scoped, and what it described is held
  // here, where it is derived from `package.json` and the import graph.
  //
  // 🚫 The general form was tried and rejected: *no landing document may assert
  // that no gate covers X*. The population is 96 such sentences across 19 of the
  // 22 documents this suite reads, one of which was the defect, and deciding any
  // of them needs X resolved to a control name — a hand-kept map from prose to
  // gate, which is the `✅ applied` antipattern this repository already has a
  // judgment about. Nor does a temporal marker separate them: *"yet"* and
  // *"still"* appear on 2 of the 96, and the defect carried neither.
  {
    const RELATIVE_IMPORT = /(?:from|import|require)\s*\(?\s*['"](\.\.?\/[^'"]+)['"]/g;
    const shippedCode = [...shipped].filter((file) => /\.(ts|tsx|js|mjs|cjs)$/.test(file)).sort();
    const onDisk = (path: string): boolean => existsSync(join(root, path)) && statSync(join(root, path)).isFile();
    const specifiersIn = (text: string): string[] => [...new Set([...text.matchAll(RELATIVE_IMPORT)].map((m) => m[1]))];
    const targetOf = (file: string, spec: string): string =>
      relative(root, resolve(join(root, dirname(file)), spec)).split('\\').join('/');

    /**
     * What one module's relative imports get wrong, given what ships and what
     * is on disk. The controls below call THIS, rather than a second reading
     * that would agree with the verdict by construction.
     */
    const importFaults = (
      file: string,
      text: string,
      ships: (path: string) => boolean,
      isFile: (path: string) => boolean,
    ): string[] => {
      const out: string[] = [];
      for (const spec of specifiersIn(text)) {
        const target = targetOf(file, spec);
        if (!isFile(target)) {
          out.push(
            `${file} imports '${spec}' and ${target} is not a file this resolver can land on — teach it, or the ` +
              'closure it reads is not the one npm installs',
          );
        } else if (!ships(target)) {
          out.push(
            `🔒 ${file} imports '${spec}' and \`files\` does not ship ${target} — the installed package throws ` +
              'Cannot find module on the command that needs it',
          );
        }
      }
      return out;
    };

    let edges = 0;
    let crossing = 0;
    const closureFaults: string[] = [];
    for (const file of shippedCode) {
      const text = readFileSync(join(root, file), 'utf8');
      const specs = specifiersIn(text);
      edges += specs.length;
      crossing += specs.filter((spec) => dirname(targetOf(file, spec)) !== dirname(file)).length;
      closureFaults.push(...importFaults(file, text, shipsToo, onDisk));
    }

    // 🌱 Three plants through the same judge. The first two are the verdict's
    // own two directions; the third is the measurement behind "this is not
    // `CUR15` in another spelling" — the same defect on an importer outside
    // `src/`, which `CUR15`'s derivation never opens.
    const SHIPS_PROBE = 'tools/shipped_probe.ts';
    const shipsProbe = (path: string): boolean => path === SHIPS_PROBE;
    const faithful = importFaults('src/probe.ts', `import { drawText } from '../${SHIPS_PROBE}';`, shipsProbe, () => true);
    const unshipped = raisedBy(
      importFaults('src/probe.ts', "import { drawText } from '../tools/unshipped_probe.ts';", shipsProbe, () => true),
      { was: faithful },
    );
    const absent = raisedBy(
      importFaults('src/probe.ts', `import { drawText } from '../${SHIPS_PROBE}';`, shipsProbe, () => false),
      { was: faithful },
    );
    const outsideSrcClean = importFaults('cli.ts', `import { drawText } from './${SHIPS_PROBE}';`, shipsProbe, () => true);
    const outsideSrc = raisedBy(
      importFaults('cli.ts', "import { drawText } from './tools/unshipped_probe.ts';", shipsProbe, () => true),
      { was: outsideSrcClean },
    );
    const controlFaults = [
      ...(unshipped.length === 0 ? ['a shipped module importing a module `files` does not ship was not faulted'] : []),
      ...(absent.length === 0 ? ['an import landing on no file at all was not faulted'] : []),
      ...(outsideSrc.length === 0
        ? ['the same defect on an importer outside `src/` — the half `CUR15` cannot read — was not faulted']
        : []),
      ...faithful.map((fault) => `a shipped module importing another shipped module was faulted anyway — ${fault}`),
      ...outsideSrcClean.map((fault) => `the same, with the importer outside \`src/\` — ${fault}`),
    ];

    const readOnlyBySrc = modulesSrcReachesOutsideItself(root);
    const importersOutsideSrc = shippedCode.filter((file) => !file.startsWith('src/'));
    const probes = [
      ...floorProbes(
        [
          [shippedCode.length, 2, `${shippedCode.length} shipped file(s) are modules this resolver reads`],
          [edges, 1, `${edges} relative import edge(s) were resolved`],
          [crossing, 1, `${crossing} of those edges cross a directory, which is the rule's own subject`],
        ],
        'and a reader that resolves no import at all pronounces the allowlist closed off nothing',
      ),
      ...closureFaults,
      ...controlFaults,
    ];
    const held = probes.length === 0;
    say(
      'CUR16_EVERY_RELATIVE_IMPORT_A_SHIPPED_MODULE_MAKES_LANDS_ON_A_SHIPPED_MODULE',
      held,
      probeDetail(
        held,
        probes,
        `\`files\` ships ${shippedCode.length} module(s) with ${edges} relative import edge(s) between them ` +
          `(${crossing} of them crossing a directory), and every one lands on a file \`files\` also ships — ` +
          `including the ${importersOutsideSrc.length} importer(s) outside \`src/\`, whose edges are not in the ` +
          `${readOnlyBySrc.length} module(s) \`CUR15\` derives`,
      ),
      'the installed package is an allowlist and a checkout is not, so the two can disagree, and until #527 the ' +
        'only thing holding them together was `CUR15`\'s last clause over the modules `src/` reaches — a corner of ' +
        'the graph, and the detail above prints how small a corner. The rest were held by nobody: `cli.ts` or ' +
        '`tools/plate.ts` reaching a new helper left out of `files` is the same defect with the same consequence, ' +
        'and the tree stayed green on it. ' +
        '⚠️ It is a gate on the FACT rather than on the prose, and that was measured rather than preferred — ' +
        '`ROADMAP.md` stated the hole in words `CUR15`\'s finder does not see, and a finder written from those ' +
        'words would have one site today and none after the repair, which is a scan with no floor it can state. ' +
        '🔒 The resolver reports a target it cannot land on as its own fault rather than as a missing ship, ' +
        'because those are different repairs and a reader who cannot tell them apart fixes the wrong one',
    );
  }

  // --- CUR17: the key sets against the interfaces that declare them ---------
  //
  // `RIG_KEYS` and `MOTION_KEYS` are what `parseRigSpec` and `parseMotionSpec`
  // refuse an unknown key against, and they are hand-written, because TypeScript
  // erases the interfaces they shadow. A hand-written list beside a declaration
  // is this repository's own named antipattern, so it is derived from the
  // declaration here instead of trusted: every entry's field list is read out of
  // the source of the interface it is named for and compared set to set.
  //
  // 🔒 Both directions are faults and they are different ones. A key in the
  // interface and not the table is a field an author cannot write — loud, the
  // first time anyone tries. A key in the table and not the interface is the
  // silent half: it is accepted by the parser and read by nothing, which is
  // exactly what `scaleYMode` was (CUR18 is the other half of that one).
  {
    const sources = ['src/rig.ts', 'src/types.ts', 'src/trackgen.ts', 'src/deformgen.ts'].map((rel) => ({
      rel,
      text: readFileSync(join(root, rel), 'utf8'),
    }));
    const faults: string[] = [];
    let compared = 0;
    const sets: Array<[string, readonly string[]]> = [...Object.entries(RIG_KEYS), ...Object.entries(MOTION_KEYS)];
    for (const [shape, declared] of sets) {
      const found = sources.map((s) => ({ rel: s.rel, fields: interfaceFieldsIn(s.text, shape) })).filter((s) => s.fields !== null);
      if (found.length !== 1) {
        faults.push(
          `${shape} is declared as an interface in ${found.length === 0 ? 'none' : found.map((f) => f.rel).join(' and ')} of the ${sources.length} module(s) this reads`,
        );
        continue;
      }
      compared += 1;
      const fields = found[0].fields as string[];
      for (const key of fields) if (!declared.includes(key)) faults.push(`${shape}.${key} is declared and the key set omits it`);
      for (const key of declared) if (!fields.includes(key)) faults.push(`the key set for ${shape} carries "${key}" and the interface has no such field`);
    }
    // The plants. Two synthetic sources standing where a real one would, so the
    // comparison is driven both ways over a shape whose answer is known — a
    // check that only ever ran on a tree that agrees has not been seen to fail.
    const agreeing = 'export interface P {\n  a: number;\n  /** b?: number; */\n  b?: string;\n}\n';
    const planted = [
      ...(JSON.stringify(interfaceFieldsIn(agreeing, 'P')) === '["a","b"]'
        ? []
        : [`the field reader does not read a two-field interface: ${JSON.stringify(interfaceFieldsIn(agreeing, 'P'))}`]),
      ...(interfaceFieldsIn(agreeing, 'Q') === null ? [] : ['an interface that is not there was read as one']),
      ...(JSON.stringify(interfaceFieldsIn('export interface P {\n  a: number;\n}\n', 'P')) === '["a"]'
        ? []
        : ['dropping a field from the source did not move what the reader returns']),
    ];
    const held = faults.length === 0 && planted.length === 0 && compared === Object.keys(RIG_KEYS).length + Object.keys(MOTION_KEYS).length;
    say(
      'CUR17_EVERY_DECLARED_SPEC_KEY_SET_IS_ITS_INTERFACE_S_OWN_FIELD_LIST',
      held,
      probeDetail(
        held,
        [...faults, ...planted],
        `${compared} key set(s) — ${Object.keys(RIG_KEYS).length} rig, ${Object.keys(MOTION_KEYS).length} motion — ` +
          `each paired with exactly one interface across ${sources.length} module(s) and equal to its fields set for ` +
          'set, with the reader driven over a planted interface it must read, one it must not find, and one field removed',
      ),
      'the refusal is only as good as the set it refuses against, and the set is the one thing here TypeScript ' +
        'cannot hold: the interfaces are erased at runtime. Issue #545 is what a table nothing derives turns into ' +
        '— `scaleYMode` sat in the interface from the rig spec\'s first commit (c0e9944, 2026-08-22) while the ' +
        'emitter read `scaleY`, and the type system pointed authors at the key that did nothing',
    );
  }

  // --- CUR18: a declared key that occurs nowhere else -----------------------
  //
  // ⭐ The check issue #545 could not have been filed against, because the
  // defect's own signature is the absence of anything: `scaleYMode` occurred
  // **exactly once in the entire tree**, in the declaration, and there was no
  // artifact, no error and no test naming it anywhere. So the measurement is the
  // count itself. A key that no module reads and no shipped document mentions is
  // a key nothing does anything with.
  //
  // ⚠️ It does not claim the emitter reads the key, and must not be read as
  // claiming it: `note` is prose for a reader and `lengths` exists so a refusal
  // can name it, and both are legitimate. What it claims is narrower and is the
  // whole of what was missing — that something outside the declaration knows the
  // name at all.
  {
    /** The modules the interfaces and the key tables live in — where the declaration itself does not count. */
    const DECLARING = new Set(['src/rig.ts', 'src/motion.ts', 'src/types.ts', 'src/trackgen.ts', 'src/deformgen.ts']);
    const modules = ['cli.ts']
      .concat(trackedIn(root, 'src', (f) => f.endsWith('.ts')))
      .concat(trackedIn(root, 'tools', (f) => f.endsWith('.ts') || f.endsWith('.mjs')));
    // ⭐ The declaring modules keep their CODE and lose only their declarations,
    // rather than being excluded whole. Excluding them entirely was the first
    // shape of this and it was measurably weaker in both directions:
    // `DeformWave.wavelength` is read by `deformgen.ts`'s own evaluator and came
    // back an orphan, and a key defended only by a line of prose — a doc
    // example, or this very file's account of why `scaleYMode` was renamed —
    // came back read. Comments go everywhere, because a comment does not read a
    // key.
    const code = modules.map((rel) => {
      const raw = readFileSync(join(root, rel), 'utf8');
      const body = DECLARING.has(rel)
        ? cutBracedBlocks(cutBracedBlocks(raw, /export interface \w+(?: extends \w+)? \{/), /export const (?:RIG|MOTION)_(?:KEYS|TYPES) = \{/)
        : raw;
      return body.replace(/\/\*[\s\S]*?\*\//g, ' ').replace(/\/\/[^\n]*/g, ' ');
    });
    const readsIn = (texts: readonly string[], key: string): boolean => {
      const token = new RegExp(`\\b${key}\\b`);
      return texts.some((text) => token.test(text));
    };
    const reads = (key: string): boolean => readsIn(code, key);
    // The compiler's own modules — `cli.ts` and `src/` — which is where issue
    // #545's key lived and was read by nothing. `tools/` is left out of THIS set
    // only: `tools/pose_oracle.ts` dumps the runtime's
    // `PhysicsConstraintData.scaleYMode`, a real spine-core property of that
    // name, which is not the rig-spec key #545 was about. The orphan scan above
    // keeps its full scope, tools included, and `zzNoSuchSpecKey` below already
    // holds that scope to not matching everything.
    const compilerCode = code.filter((_, i) => !modules[i].startsWith('tools/'));
    const every = [...new Set([...Object.values(RIG_KEYS), ...Object.values(MOTION_KEYS)].flat())].sort();
    const orphans = every.filter((key) => !reads(key));
    // The plants, and the first of them is the defect itself: with the
    // declarations and the prose gone, `scaleYMode` is a name no line of the
    // compiler's code carries — so a run that reported it read there would be a
    // search matching anything, and the clean verdict above would mean nothing.
    const planted = [
      ...(readsIn(compilerCode, 'scaleYMode')
        ? ['`scaleYMode` was reported as read by code, so this search matches prose and the clean run is vacuous']
        : []),
      ...(reads('zzNoSuchSpecKey') ? ['a name no file carries was reported as read'] : []),
      ...(reads('triangles') ? [] : ['a key every emitted mesh carries was reported as unread, so the search matches nothing']),
    ];
    const held = orphans.length === 0 && planted.length === 0;
    say(
      'CUR18_EVERY_DECLARED_SPEC_KEY_IS_NAMED_BY_CODE_THAT_IS_NOT_ITS_DECLARATION',
      held,
      probeDetail(
        held,
        [...orphans.map((key) => `"${key}" is named by no line of code in the ${modules.length} module(s) this reads, only by its own declaration`), ...planted],
        `all ${every.length} distinct key(s) of the two formats are named by code in the ${modules.length} ` +
          `module(s) this reads, with the ${DECLARING.size} declaring ones stripped of their interfaces and their key and type ` +
          'tables and every module stripped of its comments — under which `scaleYMode` reads as unnamed by the ' +
          'compiler\'s modules, an ' +
          'invented key as unnamed, and an emitted one as named',
      ),
      'run over the whole tree before it was written, this named exactly one key — ' +
        '`RigPhysicsConstraint.scaleYMode`, the whole of issue #545 — and nothing else across the 22 rig shapes ' +
        'and 15 motion ones that existed then. A defect whose signature is an absence needs a check that counts',
    );
  }

  // --- CUR29/30/31: the post-publish confirmation (issue #563) ---------------
  //
  // 🚨 **The defect printed a good cut as a broken one.** `release.yml`'s
  // confirmation step waited sixty seconds for a registry whose own notice on
  // publish says *"Your package is being processed and may take a few minutes
  // to become available"*, and then ended in a trailing `npm view`'s raw
  // `E404`. So two different facts left the same red — *the registry has not
  // served this version yet*, which says nothing at all about the package, and
  // *the artifact is there and does not build*, which is the only thing the
  // step exists to find. All three cuts that ran that step went red and all
  // three packages were fine; RELEASING.md carries the figures and their
  // sources.
  //
  // ⭐ **Why these three can exist at all.** The card that designed the step
  // (#556) said its own firing could not be observed without a real publish,
  // and for a `run:` body that is simply true. The repair moves the wait into
  // `scripts/install_smoke.ts`, and a script is a subprocess with a PATH in
  // front of it: an `npm` that answers E404 drives the first outcome and one
  // that serves the version and cannot hand over its tarball drives the second,
  // offline, in seconds. `CUR31` then holds the workflow and the document to
  // what those two runs printed. ⚠️ What none of them reaches is a real
  // publish — that is still the confirmation's own ground, and it is why the
  // GATE is `ci.yml`'s `installs` job and this is a confirmation beside it.
  {
    interface WfStep {
      name?: string;
      uses?: string;
      run?: string;
      if?: string;
    }
    interface WfJob {
      if?: string;
      'timeout-minutes'?: number;
      steps?: WfStep[];
    }
    interface Workflow {
      on?: { workflow_dispatch?: { inputs?: Record<string, { required?: boolean }> } };
      jobs?: Record<string, WfJob>;
    }

    /** A directory holding an `npm` that answers instead of the registry, to go first on PATH. */
    const fakeRegistry = (body: string): string => {
      const dir = mkdtempSync(join(harnessTemp(), 'rigc-fake-npm-'));
      writeFileSync(join(dir, 'npm'), body);
      chmodSync(join(dir, 'npm'), 0o755);
      return dir;
    };
    /** The smoke, run the way a caller runs it, with that fake registry in front of the real one. */
    const smokeWith = (dir: string | null, argv: readonly string[]): { status: number; out: string } => {
      const ran = spawnSync(process.execPath, ['scripts/install_smoke.ts', ...argv], {
        cwd: root,
        encoding: 'utf8',
        env: dir === null ? process.env : { ...process.env, PATH: `${dir}${delimiter}${process.env.PATH ?? ''}` },
      });
      return { status: ran.status ?? -1, out: `${ran.stdout ?? ''}${ran.stderr ?? ''}` };
    };
    const FAKE = '0.0.0-fake-registry';
    const SPEC = `${packageName}@${FAKE}`;

    // --- CUR29: a version nobody is serving is a confirmation not taken ------
    const nothingServed = fakeRegistry(
      '#!/bin/sh\n' +
        '# A registry that has finished processing nothing: every version is a 404.\n' +
        'if [ "$1" = "view" ]; then\n' +
        '  echo "npm error code E404" >&2\n' +
        `  echo "npm error 404 No match found for version \${2#${packageName}@}" >&2\n` +
        '  exit 1\n' +
        'fi\n' +
        'echo "npm error this fake registry answers nothing but view" >&2\n' +
        'exit 1\n',
    );
    // 0.05 min = 3 s, which is one step of the backoff: the first ask, a sleep
    // capped by what is left of the wait, and a second ask that runs out of it.
    // Short enough to sit in a suite, long enough that the elapsed line below
    // is printed rather than skipped.
    const late = smokeWith(nothingServed, ['--source', 'registry', '--version', FAKE, '--case', 'clean', '--wait', '0.05']);
    rmSync(nothingServed, { recursive: true, force: true });
    const byHandPrinted = /take it by hand once the registry answers: ([^\n]*?)(?:\. |$)/m.exec(late.out)?.[1]?.trim() ?? '';
    const lateAttempts = Number(/\((\d+) attempt\(s\)/.exec(late.out)?.[1] ?? '0');
    const lateProbes = [
      ...(late.status === 3
        ? []
        : [`a registry serving nothing ended the smoke at exit ${late.status}, and 3 — the code that means the confirmation was not taken — was required`]),
      ...(late.out.includes('SMOKE_REGISTRY_SERVED_THE_VERSION') ? [] : ['the run named no SMOKE_REGISTRY_SERVED_THE_VERSION, so the wait ended with nothing anybody can grep for']),
      ...(late.out.includes('the confirmation was NOT taken') ? [] : ['the run does not say the confirmation was NOT taken, which is the whole of what a wait that ran out knows']),
      ...(byHandPrinted === `bun run smoke -- --source registry --version ${FAKE} --case clean`
        ? []
        : [`the run offers ${byHandPrinted === '' ? 'no by-hand command' : `\`${byHandPrinted}\``}, and a cut whose wait ran out has nothing else to act on`]),
      ...(late.out.includes('npm error code E404')
        ? []
        : ['the message does not name what npm actually said, so a network that is down and a version that is late would read the same']),
      ...(lateAttempts >= 2 ? [] : [`the wait made ${lateAttempts} attempt(s) inside 3 s, so nothing here measured a second ask`]),
      ...(/attempt 1, \dm \d\ds into a 0\.05 min wait/.test(late.out) ? [] : ['no attempt announced its own elapsed time, which is what the sixty-second step could not be read for']),
      ...(late.out.includes('does not build') ? ['the run ALSO printed the served-and-broken message, so the two outcomes are still one message'] : []),
      ...late.out
        .split('\n')
        .filter((line) => /attempt \d+, \dm \d\ds into a 0\.05 min wait/.test(line) && !/packument/.test(line))
        .map((line) => `an attempt line does not say it is the packument that is missing: ${line.trim()}`),
      ...(/PASS {2}SMOKE_CASE/.test(late.out) ? ['a case ran and passed against a registry that is serving nothing'] : []),
    ];
    const lateHeld = lateProbes.length === 0;
    say(
      'CUR29_A_VERSION_THE_REGISTRY_HAS_NOT_SERVED_IS_A_CONFIRMATION_NOT_TAKEN_AND_SAYS_SO',
      lateHeld,
      probeDetail(
        lateHeld,
        lateProbes,
        'an `npm` on PATH that answers every version with E404 ends `--source registry --wait 0.05` at exit ' +
          `${late.status} after ${lateAttempts} attempt(s), naming SMOKE_REGISTRY_SERVED_THE_VERSION, the ` +
          "confirmation NOT taken, npm's own E404 and the by-hand command — and printing nothing about an " +
          'artifact that does not build, because none was fetched',
      ),
      'the first real run of the confirmation step, on v0.22.0, went red 63 s after a publish the registry served ' +
        '4 min 11 s later — and the package was fine. What was wrong was the clock and the message, so the wait is ' +
        "now the script's and the two outcomes carry different exit codes",
    );

    // --- CUR111: the packument without the tarball is a version NOT served (#833)
    //
    // 🚨 **The defect printed a good cut as a broken one a second time, one
    // layer further in.** v1.1.0's confirmation waited out the packument
    // (`npm view` answered on attempt 8), then `npm pack` 404'd on a tarball
    // the registry had not finished serving, and the run said *"the published
    // artifact does not build … This is a fault in what was published"* — exit
    // 1 on a package a dispatch confirmed green six minutes later. So the wait
    // now ends on the bytes, and these two runs hold it to that: metadata that
    // answers over a tarball that 404s, and over a pack that exits 0 having
    // written nothing, are both a confirmation not taken, and both say it was
    // the tarball that never came.
    const tarballUrl = `https://registry.invalid/${packageName}/-/${packageName}-${FAKE}.tgz`;
    const metadataOnly = (pack: string): string =>
      fakeRegistry(
        '#!/bin/sh\n' +
          '# The packument answers; the tarball behind it does not.\n' +
          'if [ "$1" = "view" ]; then\n' +
          `  echo "${tarballUrl}"\n` +
          '  exit 0\n' +
          'fi\n' +
          'if [ "$1" = "pack" ]; then\n' +
          pack +
          'fi\n' +
          'echo "npm error this fake registry answers nothing but view and pack" >&2\n' +
          'exit 1\n',
      );
    const tarballRuns: Array<{ what: string; pack: string; said: string }> = [
      {
        what: 'a tarball that 404s',
        pack: '  echo "npm error code E404" >&2\n' + `  echo "npm error 404 Not Found - GET ${tarballUrl}" >&2\n` + '  exit 1\n',
        said: 'npm error code E404',
      },
      { what: 'a pack that exits 0 and writes no bytes', pack: '  exit 0\n', said: 'no bytes' },
    ];
    const tarballProbes: string[] = [];
    const tarballCases: string[] = [];
    for (const one of tarballRuns) {
      const dir = metadataOnly(one.pack);
      const ran = smokeWith(dir, ['--source', 'registry', '--version', FAKE, '--case', 'clean', '--wait', '0.05']);
      rmSync(dir, { recursive: true, force: true });
      const failLine = ran.out.split('\n').find((line) => line.includes('SMOKE_REGISTRY_SERVED_THE_VERSION')) ?? '';
      const progress = ran.out.split('\n').filter((line) => /attempt \d+, \dm \d\ds into a 0\.05 min wait/.test(line));
      const attempts = Number(/\((\d+) attempt\(s\)/.exec(ran.out)?.[1] ?? '0');
      const faults = [
        ...(ran.status === 3 ? [] : [`exit ${ran.status}, and 3 — the confirmation was not taken — was required`]),
        ...(failLine === '' ? ['no SMOKE_REGISTRY_SERVED_THE_VERSION line, so the wait ended with nothing anybody can grep for'] : []),
        ...(failLine !== '' && !/tarball/.test(failLine) ? ['the not-served line does not name the tarball, which is the piece that never came'] : []),
        ...(failLine !== '' && !/packument answered/.test(failLine) ? ['the not-served line does not say the packument answered, so it reads the same as a version nobody published'] : []),
        ...(failLine.includes(one.said) ? [] : [`the not-served line does not carry "${one.said}", what the registry actually handed back`]),
        ...(ran.out.includes('the confirmation was NOT taken') ? [] : ['the run does not say the confirmation was NOT taken']),
        ...(attempts >= 2 ? [] : [`${attempts} attempt(s) inside 3 s, so nothing here measured a second ask for the bytes`]),
        ...(progress.length > 0 ? [] : ['no attempt announced its elapsed time']),
        ...progress.filter((line) => !/tarball/.test(line)).map((line) => `an attempt line does not say it is the tarball that is missing: ${line.trim()}`),
        ...(ran.out.includes('does not build') ? ['the run printed the served-and-broken message on bytes that never arrived — the #833 defect'] : []),
        ...(ran.out.includes('SMOKE_PACK_WROTE_A_TARBALL') ? ['a case reached its own pack, so the wait let through a version whose tarball it never had'] : []),
        ...(/PASS {2}SMOKE_CASE/.test(ran.out) ? ['a case passed with no tarball behind it'] : []),
      ];
      for (const f of faults) tarballProbes.push(`${one.what}: ${f}`);
      tarballCases.push(`${one.what} -> exit ${ran.status} after ${attempts} attempt(s)`);
    }
    const tarballHeld = tarballProbes.length === 0;
    say(
      'CUR111_A_PACKUMENT_WITHOUT_ITS_TARBALL_IS_A_VERSION_NOT_SERVED_AND_NAMES_THE_TARBALL',
      tarballHeld,
      probeDetail(
        tarballHeld,
        tarballProbes,
        `an \`npm\` whose \`view\` answers ${SPEC} and whose \`pack\` cannot hand over the bytes ends ` +
          `\`--source registry --wait 0.05\` at exit 3 both ways — ${tarballCases.join('; ')} — with every attempt ` +
          "line and the not-served line naming the tarball, npm's own answer carried, and no case reached",
      ),
      "v1.1.0's confirmation went red at exit 1 on a package that was fine: the packument answered at 09:08:37 UTC " +
        'and its tarball was still a 404, so a wait that ended on metadata printed "the published artifact does not ' +
        'build". Red on the script before #833 — exit 1, the served-and-broken message',
    );

    // --- CUR30: a version that IS served is the artifact, and its red says so -
    //
    // ⚠️ Since #833 "served" means the bytes arrived, so this registry hands
    // over a REAL tarball — a package.json and nothing else, no `bin` — and
    // installs it by extracting it. What goes red is the artifact itself: an
    // install that leaves no `rigc` shim. The fake this replaced answered the
    // pack with E500, which is now a tarball that never came, and CUR111 says so.
    const servesThenBreaks = fakeRegistry(
      '#!/bin/sh\n' +
        '# The version is served, bytes and all; what it serves carries no bin.\n' +
        'if [ "$1" = "view" ]; then\n' +
        `  echo "${tarballUrl}"\n` +
        '  exit 0\n' +
        'fi\n' +
        'if [ "$1" = "pack" ]; then\n' +
        '  dest=""; prev=""\n' +
        '  for arg in "$@"; do if [ "$prev" = "--pack-destination" ]; then dest="$arg"; fi; prev="$arg"; done\n' +
        '  stage=$(mktemp -d)\n' +
        '  mkdir -p "$stage/package"\n' +
        `  printf '{"name":"${packageName}","version":"${FAKE}"}\\n' > "$stage/package/package.json"\n` +
        `  tar -czf "$dest/${packageName}-${FAKE}.tgz" -C "$stage" package\n` +
        '  rm -rf "$stage"\n' +
        '  exit 0\n' +
        'fi\n' +
        'if [ "$1" = "install" ]; then\n' +
        `  mkdir -p node_modules/${packageName}\n` +
        `  tar -xzf "$2" -C node_modules/${packageName} --strip-components=1\n` +
        '  exit $?\n' +
        'fi\n' +
        'exit 1\n',
    );
    const broken = smokeWith(servesThenBreaks, ['--source', 'registry', '--version', FAKE, '--case', 'clean', '--wait', '0.05']);
    rmSync(servesThenBreaks, { recursive: true, force: true });
    const brokenProbes = [
      ...(broken.status === 1 ? [] : [`a served version whose artifact fails ended the smoke at exit ${broken.status}, and 1 was required`]),
      ...(broken.status === late.status ? [`both outcomes exited ${broken.status}, which is the defect this pair is written against`] : []),
      ...(broken.out.includes('the published artifact does not build') ? [] : ['the run never says the published artifact does not build, so a red cut still reads as a slow registry']),
      ...(broken.out.includes(`the registry served ${SPEC}`) ? [] : ["the run does not record that the registry answered, which is what makes this red the artifact's rather than the wait's"]),
      ...(broken.out.includes('SMOKE_REGISTRY_SERVED_THE_VERSION') ? ['the run ALSO printed the not-served message on a version the registry served'] : []),
      ...(broken.out.includes('confirmation was NOT taken') ? ['the run says the confirmation was not taken, and it was: the artifact was asked for and went red'] : []),
      ...(broken.out.includes('SMOKE_INSTALL_EMPTY_DIR') ? [] : ['no fault named the install step, where a package with no `bin` goes red, so this case cannot say what it measured']),
      ...(broken.out.includes('SMOKE_PACK_WROTE_A_TARBALL') ? ['the pack went red on a registry that handed over its bytes'] : []),
    ];
    const brokenHeld = brokenProbes.length === 0;
    say(
      'CUR30_A_VERSION_THE_REGISTRY_DOES_SERVE_IS_THE_ARTIFACT_AND_A_RED_ON_IT_SAYS_SO',
      brokenHeld,
      probeDetail(
        brokenHeld,
        brokenProbes,
        `an \`npm\` that serves ${SPEC} with a tarball carrying no \`bin\` ends the same command at exit ` +
          `${broken.status} — the published artifact does not build, named at the install — where the registry ` +
          `serving nothing ends it at exit ${late.status}. Two fake registries, two codes, and neither message ` +
          'reaches the other run',
      ),
      'these two are one control in two halves. One red for both facts was the whole of issue #563, so the half ' +
        'that proves the repair is not "the wait is named" but "the wait is named and a broken artifact is still ' +
        'named something else"',
    );

    // --- CUR121: each alias is held to the package by its files (issues #1258, #1347)
    //
    // 🪞 The package is published under its `package.json` name and under every
    // name in `ALIASES` — `spine-rigc`, the name every version up to 2.20.4
    // shipped under, and `@rig-c/core`, the package under the toolchain's scope
    // — and the promise is that each alias carries the package's files at every
    // version. The confirmation reads that off the registry: one `--alias` per
    // name fetches the same version under it and compares the unpacked
    // tarballs, each alias on its own line. A registry on PATH that serves
    // every name drives it offline — the tarball file named the way `npm pack`
    // names a scoped package, `@scope/name` as `scope-name` — once with every
    // alias identical but for its name line, once per way an alias can
    // differ, and once with the difference in the first alias rather than the
    // last, so a reading that stopped at the first verdict or read only one
    // alias goes red. The tool that makes each alias for the publish is driven
    // over the same tarballs, under every name. ⚠️ What none of these reaches is
    // a green case: the fake installs nothing, so every run here is red at the
    // install, and the exit code of a late alias over a green case (3) is read
    // in the script rather than seen here. The lines are what is held.
    {
      const stage = mkdtempSync(join(harnessTemp(), 'rigc-fake-alias-stage-'));
      const manifestOf = (name: string, version = FAKE): string => `{\n  "name": ${JSON.stringify(name)},\n  "version": ${JSON.stringify(version)}\n}\n`;
      /** The file `npm pack` names a package's tarball after: a scoped `@scope/name` is `scope-name`. */
      const fileOf = (name: string): string => name.replace(/^@/, '').replace(/\//g, '-');
      /** A tarball of `package/<path>` files, written to `into`. */
      const tarball = (label: string, files: Record<string, string>, into: string): string => {
        const src = join(stage, fileOf(label));
        // Cleared first: a label is reused across runs, and a file an earlier run wrote must not ride into a later one.
        rmSync(src, { recursive: true, force: true });
        for (const [path, text] of Object.entries(files)) {
          mkdirSync(dirname(join(src, 'package', path)), { recursive: true });
          writeFileSync(join(src, 'package', path), text);
        }
        const tgz = join(into, `${fileOf(label)}.tgz`);
        const made = spawnSync('tar', ['-czf', tgz, '-C', src, 'package'], { encoding: 'utf8' });
        if (made.status !== 0) throw new Error(`CUR121: tar of ${label} exited ${String(made.status)}: ${made.stderr}`);
        return tgz;
      };
      const primaryFiles = { 'package.json': manifestOf(packageName), 'src/probe.ts': 'export const probe = 1;\n' };
      const sameAs = (alias: string): Record<string, string> => ({ ...primaryFiles, 'package.json': manifestOf(alias) });
      /** A registry serving `<file>.tgz` from its own directory for every name it holds, and installing nothing. */
      const servesNames = (aliasFiles: ReadonlyMap<string, Record<string, string> | null>): string => {
        const dir = fakeRegistry(
          '#!/bin/sh\n' +
            '# Serves each name whose tarball sits beside this script; installs nothing.\n' +
            'here=$(dirname "$0")\n' +
            'name="${2%@*}"\n' +
            "file=$(printf '%s' \"$name\" | sed -e 's#^@##' -e 's#/#-#g')\n" +
            'if [ "$1" = "view" ]; then\n' +
            '  if [ -f "$here/$file.tgz" ]; then echo "https://registry.invalid/$file.tgz"; exit 0; fi\n' +
            '  echo "npm error code E404" >&2\n' +
            '  exit 1\n' +
            'fi\n' +
            'if [ "$1" = "pack" ]; then\n' +
            '  dest=""; prev=""\n' +
            '  for arg in "$@"; do if [ "$prev" = "--pack-destination" ]; then dest="$arg"; fi; prev="$arg"; done\n' +
            `  cp "$here/$file.tgz" "$dest/$file-${FAKE}.tgz"\n` +
            '  exit $?\n' +
            'fi\n' +
            'echo "npm error this fake registry installs nothing" >&2\n' +
            'exit 1\n',
        );
        tarball(packageName, primaryFiles, dir);
        for (const [alias, files] of aliasFiles) if (files !== null) tarball(alias, files, dir);
        return dir;
      };
      const ALIAS_CASE = 'SMOKE_ALIAS_CARRIES_THE_SAME_FILES';
      const aliasFlags = ALIASES.flatMap((alias) => ['--alias', alias]);
      /** The output from the alias's own verdict line on, or '' when no line names it. */
      const aliasTail = (out: string, alias: string): string => {
        const lines = out.split('\n');
        const at = lines.findIndex((line) => line.includes(ALIAS_CASE) && line.includes(`${alias}@${FAKE}`));
        return at === -1 ? '' : lines.slice(at).join('\n');
      };
      const first = ALIASES[0];
      const last = ALIASES[ALIASES.length - 1];
      interface AliasRun {
        what: string;
        /** The alias the case changes, and how; every other alias is served identical but for its name line. */
        target: string;
        files: (alias: string) => Record<string, string> | null;
        said: string[];
      }
      const runs: AliasRun[] = [
        { what: 'every alias identical but for its name line', target: '', files: sameAs, said: ['2 file(s)', `${packageName}@${FAKE}`] },
        { what: `one byte appended to a file of ${last}`, target: last, files: (alias) => ({ ...sameAs(alias), 'src/probe.ts': 'export const probe = 1;\n!' }), said: ['package/src/probe.ts differs', 'first parting at byte'] },
        { what: `a file the package does not carry, in ${last}`, target: last, files: (alias) => ({ ...sameAs(alias), 'src/extra.ts': 'x\n' }), said: ['package/src/extra.ts is in'] },
        { what: `${last}'s manifest changed beyond its name`, target: last, files: (alias) => ({ ...primaryFiles, 'package.json': manifestOf(alias, '0.0.1-other') }), said: ['package/package.json differs beyond its name line'] },
        { what: `${last} not served by the registry`, target: last, files: () => null, said: [`${last}@${FAKE}`, 'NOT taken', aliasFlags.join(' ')] },
        { what: `one byte appended to a file of ${first}, the first alias read`, target: first, files: (alias) => ({ ...sameAs(alias), 'src/probe.ts': 'export const probe = 1;\n!' }), said: ['package/src/probe.ts differs'] },
      ];
      const aliasProbes: string[] = [];
      const aliasCases: string[] = [];
      if (ALIASES.length < 2 || new Set(ALIASES).size !== ALIASES.length) aliasProbes.push(`ALIASES is ${JSON.stringify(ALIASES)}, and these runs are written over two or more distinct names`);
      for (const one of runs) {
        const dir = servesNames(new Map(ALIASES.map((alias) => [alias, alias === one.target ? one.files(alias) : sameAs(alias)])));
        const ran = smokeWith(dir, ['--source', 'registry', '--version', FAKE, '--case', 'clean', '--wait', '0.05', ...aliasFlags]);
        rmSync(dir, { recursive: true, force: true });
        const verdicts: string[] = [];
        for (const alias of ALIASES) {
          const tail = aliasTail(ran.out, alias);
          const line = tail.split('\n')[0] ?? '';
          const pass = alias !== one.target;
          const faults = [
            ...(line === '' ? [`no ${ALIAS_CASE} line names ${alias}@${FAKE}, so that alias was never read`] : []),
            ...(line !== '' && pass && !line.includes(`PASS  ${ALIAS_CASE}`) ? [`${alias} was not passed: ${line.trim().slice(0, 200)}`] : []),
            ...(line !== '' && !pass && !line.includes(`FAIL  ${ALIAS_CASE}`) ? [`${alias} was not failed: ${line.trim().slice(0, 200)}`] : []),
            ...(pass ? (one.target === '' ? one.said : []) : one.said).filter((text) => !tail.includes(text)).map((text) => `${alias}'s reading does not say "${text}"`),
          ];
          for (const f of faults) aliasProbes.push(`${one.what}: ${f}`);
          verdicts.push(`${alias} ${line.includes(`PASS  ${ALIAS_CASE}`) ? 'PASS' : line.includes(`FAIL  ${ALIAS_CASE}`) ? 'FAIL' : 'unread'}`);
        }
        if (!ran.out.includes('SMOKE_INSTALL_EMPTY_DIR')) aliasProbes.push(`${one.what}: the case did not reach the install, so the aliases were read on a run that did not get as far as a real one`);
        if (ran.status !== 1) aliasProbes.push(`${one.what}: exit ${ran.status}, where a red case — the fake installs nothing — is 1 whatever the aliases read`);
        aliasCases.push(`${one.what} -> ${verdicts.join(', ')}`);
      }
      // The flag where it cannot mean anything is refused, not ignored.
      const refusals: Array<{ what: string; argv: string[]; said: string }> = [
        { what: '--alias on a tarball this tree packs', argv: ['--case', 'clean', ...aliasFlags], said: '--source registry' },
        { what: "--alias naming the package's own name", argv: ['--source', 'registry', '--version', FAKE, '--case', 'clean', ...aliasFlags, '--alias', packageName], said: 'not a second one' },
        { what: '--alias naming one alias twice', argv: ['--source', 'registry', '--version', FAKE, '--case', 'clean', '--alias', first, '--alias', first], said: 'given twice' },
        { what: '--alias with no name after it', argv: ['--source', 'registry', '--version', FAKE, '--case', 'clean', '--alias', first, '--alias'], said: 'needs another name' },
      ];
      for (const one of refusals) {
        const ran = smokeWith(null, one.argv);
        const line = ran.out.split('\n').find((text) => text.includes(ALIAS_CASE)) ?? '';
        if (ran.status !== 1 || !line.includes(`FAIL  ${ALIAS_CASE}`) || !line.includes(one.said) || ran.out.includes('SMOKE_CASE')) {
          aliasProbes.push(`${one.what}: exit ${ran.status}, line ${JSON.stringify(line.trim().slice(0, 200))} — a refusal naming "${one.said}", before any case, was required`);
        }
        aliasCases.push(`${one.what} -> refused`);
      }
      // The tool the publish runs, over the same tarballs and under every
      // name: it makes each alias, holds it to the package, and refuses a
      // manifest whose name it cannot change in exactly one line.
      const tool = (argv: string[]): { status: number; out: string; stdout: string } => {
        const ran = spawnSync(process.execPath, ['scripts/alias_tarball.ts', ...argv], { cwd: root, encoding: 'utf8' });
        return { status: ran.status ?? -1, out: `${ran.stdout ?? ''}${ran.stderr ?? ''}`, stdout: ran.stdout ?? '' };
      };
      const toolDir = mkdtempSync(join(harnessTemp(), 'rigc-alias-tool-'));
      const primaryTgz = tarball('tool-primary', primaryFiles, toolDir);
      for (const alias of ALIASES) {
        const made = tool(['pack', '--name', alias, '--out', join(toolDir, `out-${fileOf(alias)}`), '--tarball', primaryTgz]);
        const madeTgz = made.stdout.trim().split('\n').pop() ?? '';
        if (made.status !== 0 || !madeTgz.endsWith('.tgz') || !existsSync(madeTgz)) aliasProbes.push(`alias_tarball pack --name ${alias} exited ${made.status} printing ${JSON.stringify(madeTgz)}: ${made.out.trim().slice(0, 300)}`);
        else {
          const same = tool(['compare', primaryTgz, madeTgz]);
          if (same.status !== 0 || !same.out.includes(`PASS  ALIAS_SAME_CONTENT: ${alias} carries`)) aliasProbes.push(`alias_tarball compare of the package and the alias ${alias} it made exited ${same.status}: ${same.out.trim().slice(0, 300)}`);
        }
        const differs = tool(['compare', primaryTgz, tarball(`tool-differs-${fileOf(alias)}`, { ...sameAs(alias), 'src/probe.ts': 'export const probe = 2;\n' }, toolDir)]);
        if (differs.status !== 1 || !differs.out.includes('package/src/probe.ts differs')) aliasProbes.push(`alias_tarball compare of ${alias} with a changed file exited ${differs.status}, and 1 naming the file was required: ${differs.out.trim().slice(0, 300)}`);
      }
      const minified = tool(['pack', '--name', first, '--out', join(toolDir, 'out-minified'), '--tarball', tarball('tool-minified', { ...primaryFiles, 'package.json': `{"name":${JSON.stringify(packageName)},"version":"${FAKE}"}\n` }, toolDir)]);
      if (minified.status !== 2 || !minified.out.includes('exactly one')) aliasProbes.push(`alias_tarball pack of a one-line manifest exited ${minified.status}, and 2 refusing a name it cannot change in exactly one line was required: ${minified.out.trim().slice(0, 300)}`);
      aliasCases.push(`alias_tarball pack and compare both ways under ${ALIASES.join(' and ')}, and a one-line manifest -> read`);
      rmSync(toolDir, { recursive: true, force: true });
      rmSync(stage, { recursive: true, force: true });
      const aliasHeld = aliasProbes.length === 0;
      say(
        'CUR121_THE_ALIAS_THE_REGISTRY_SERVES_IS_HELD_TO_THE_PACKAGE_FILE_BY_FILE_AND_A_DIFFERENCE_OR_A_LATE_ALIAS_IS_NAMED',
        aliasHeld,
        probeDetail(
          aliasHeld,
          aliasProbes,
          `an \`npm\` serving ${packageName}@${FAKE} and ${ALIASES.map((alias) => `${alias}@${FAKE}`).join(' and ')} ends \`${aliasFlags.join(' ')}\` with ` +
            `one ${ALIAS_CASE} line per alias, passed on an alias identical but for its name line and failed, naming the path, on each way ` +
            `one can differ, the others still read — ${aliasCases.join('; ')}`,
        ),
        'issue #1258: the package is published under more than one name, and the promise that each alias carries the ' +
          'package\'s files is only as good as the reading that would see it broken — the tarballs cannot share a hash, so ' +
          'the unpacked files are what is compared; issue #1347 made it a list, so a reading of one alias is a reading of too few',
      );
    }

    // --- CUR122: release.yml publishes the aliases it confirms (issues #1258, #1347)
    //
    // Each alias's name is written in two places a person edits — its own pack
    // step and every confirmation call — and in one a program reads,
    // `ALIASES`. They have to agree name for name, every alias publish has to
    // follow the gated one in the same job (the gate's verdict is about this
    // commit, and each alias is this commit's files), and RELEASING.md has to
    // say how to confirm every name. Dropping any one alias from the publish
    // or from either confirmation is planted, once per alias.
    if (BUN_YAML === null) {
      reportYamlHole('CUR122_RELEASE_YML_PUBLISHES_THE_ALIAS_AFTER_THE_GATED_PUBLISH_FROM_THE_TARBALL_IT_COMPARED_AND_CONFIRMS_THE_SAME_ALIAS');
    } else {
      interface AliasStep {
        name?: string;
        run?: string;
      }
      interface AliasWorkflow {
        jobs?: Record<string, { steps?: AliasStep[] }>;
      }
      const PACK = 'scripts/alias_tarball.ts pack';
      const aliasFaults = (yml: string, doc: string): string[] => {
        const faults: string[] = [];
        let wf: AliasWorkflow;
        try {
          wf = readYaml(yml) as AliasWorkflow;
        } catch (error) {
          return [`release.yml does not parse as YAML: ${error instanceof Error ? error.message : String(error)}`];
        }
        const lines = (step: AliasStep): string[] => (step.run ?? '').split('\n').map((line) => line.trim());
        const packers: Array<{ job: string; at: number; step: AliasStep }> = [];
        const publishers: Array<{ job: string; at: number }> = [];
        for (const [job, body] of Object.entries(wf.jobs ?? {})) {
          (body.steps ?? []).forEach((step, at) => {
            if (lines(step).some((line) => line.includes(PACK))) packers.push({ job, at, step });
            if (lines(step).some((line) => /^npm publish(\s|$)/.test(line))) publishers.push({ job, at });
          });
        }
        const packed: string[] = [];
        for (const packer of packers) {
          const packLines = lines(packer.step).filter((line) => line.includes(PACK));
          if (packLines.length !== 1) {
            faults.push(`release.yml: step "${packer.step.name ?? '(unnamed)'}" packs ${packLines.length} alias(es) with ${PACK}, where each step packs one`);
            continue;
          }
          const [packLine] = packLines;
          const named = /--name\s+"?([^"\s]+)"?/.exec(packLine)?.[1] ?? null;
          packed.push(named ?? '(no --name)');
          if (named === null || !ALIASES.includes(named)) faults.push(`release.yml: an alias is packed as ${JSON.stringify(named)}, which is not among the names scripts/alias_tarball.ts holds (${ALIASES.join(', ')})`);
          const variable = /^([A-Za-z_][A-Za-z_\d]*)="\$\(bun scripts\/alias_tarball\.ts pack\b/.exec(packLine)?.[1] ?? null;
          const publishesIt = variable !== null && lines(packer.step).some((line) => line.startsWith(`npm publish "$${variable}"`));
          if (!publishesIt) faults.push(`release.yml: the step that packs ${JSON.stringify(named)} does not \`npm publish\` the path it printed, so what is published is not what was compared`);
          const gated = publishers.filter((p) => p.job === packer.job && p.at < packer.at && !packers.some((other) => other.job === p.job && other.at === p.at));
          if (gated.length === 0) faults.push(`release.yml: no \`npm publish\` from the checkout runs before the alias ${JSON.stringify(named)} in job "${packer.job}", so it goes out ahead of — or without — the gated publish`);
        }
        for (const alias of ALIASES) {
          const times = packed.filter((name) => name === alias).length;
          if (times !== 1) faults.push(`release.yml: ${times} step(s) pack and publish the alias ${alias}, where one does — scripts/alias_tarball.ts names ${ALIASES.length} alias(es) and each is published at every version`);
        }
        const calls: string[] = [];
        for (const body of Object.values(wf.jobs ?? {})) for (const step of body.steps ?? []) calls.push(...lines(step).filter((line) => line.startsWith('bun run smoke')));
        if (calls.length === 0) faults.push('release.yml calls no `bun run smoke`, so nothing confirms any name');
        for (const call of calls) {
          const argv = call.split(/\s+/);
          const given = argv.flatMap((arg, at) => (arg === '--alias' ? [argv[at + 1] ?? '(nothing)'] : []));
          for (const alias of ALIASES) if (!given.includes(alias)) faults.push(`release.yml: \`${call}\` does not confirm the alias ${alias}, which is published`);
          for (const name of given) if (!ALIASES.includes(name)) faults.push(`release.yml: \`${call}\` confirms ${JSON.stringify(name)}, which no step publishes as an alias`);
        }
        for (const name of [packageName, ...ALIASES]) {
          if (!doc.includes(`npm view ${name} version`)) faults.push(`RELEASING.md carries no \`npm view ${name} version\`, so the cut's own confirmation of that name is stated nowhere`);
        }
        return faults;
      };
      const yml = readFileSync(join(root, '.github', 'workflows', 'release.yml'), 'utf8');
      const doc = readFileSync(join(root, 'RELEASING.md'), 'utf8');
      const standing = aliasFaults(yml, doc);
      const edit = (text: string, from: string, to: string): string | null => (text.includes(from) ? text.split(from).join(to) : null);
      /** `from` → `to` on the one line holding `marker`, or null when no line holds both. */
      const editLine = (text: string, marker: string, from: string, to: string): string | null => {
        const lines = text.split('\n');
        const at = lines.findIndex((line) => line.includes(marker) && line.includes(from));
        if (at === -1) return null;
        lines[at] = lines[at].split(from).join(to);
        return lines.join('\n');
      };
      const stepOf = (alias: string): string => {
        const at = yml.indexOf(`      - name: Publish the alias ${alias}\n`);
        return at === -1 ? '' : yml.slice(at, yml.indexOf('\n\n', at) + 2);
      };
      const gatedStep = '      - name: Publish to npm\n';
      const plants: Array<{ what: string; yml: string | null; doc?: string | null; quiet?: boolean }> = [
        ...ALIASES.flatMap((alias) => {
          const step = stepOf(alias);
          return [
            { what: `the cut's confirmation stops confirming ${alias}`, yml: editLine(yml, '"$version" --wait', ` --alias ${alias}`, '') },
            { what: `the re-run stops confirming ${alias}`, yml: editLine(yml, '"$VERSION" --wait', ` --alias ${alias}`, '') },
            { what: `${alias} is packed under another name`, yml: edit(yml, `pack --name ${alias} `, `pack --name ${alias}-other `) },
            { what: `${alias}'s step is dropped`, yml: step === '' ? null : edit(yml, step, '') },
            { what: `${alias} is published ahead of the gated publish`, yml: step === '' ? null : edit(yml.replace(step, ''), gatedStep, `${step}${gatedStep}`) },
            { what: `RELEASING.md stops confirming ${alias}`, yml, doc: edit(doc, `npm view ${alias} version`, `npm view ${alias} dist-tags`) },
            { what: `${alias}'s step is renamed`, yml: edit(yml, `name: Publish the alias ${alias}\n`, `name: Another name for ${alias}\n`), quiet: true },
          ];
        }),
        { what: 'the alias steps publish the checkout instead of the tarball', yml: edit(yml, 'npm publish "$alias_tgz" --provenance', 'npm publish --provenance') },
      ];
      const plantProbes: string[] = [];
      const plantCases: string[] = [];
      for (const plant of plants) {
        const planted = plant.doc === undefined ? doc : plant.doc;
        if (plant.yml === null || planted === null) {
          plantProbes.push(`"${plant.what}": the edit found nothing to change, so this plant was never made`);
          continue;
        }
        const raised = raisedBy(aliasFaults(plant.yml, planted), { was: standing });
        if (plant.quiet === true) {
          if (raised.length > 0) plantProbes.push(`"${plant.what}" changes nothing this gate is about and ${raised.length} fault(s) fired: ${raised[0].slice(0, 160)}`);
          plantCases.push(`${plant.what} -> quiet`);
          continue;
        }
        if (raised.length === 0) plantProbes.push(`"${plant.what}" was planted and this gate did not fire`);
        plantCases.push(`${plant.what} -> ${raised.length}`);
      }
      const held = standing.length === 0 && plantProbes.length === 0;
      say(
        'CUR122_RELEASE_YML_PUBLISHES_THE_ALIAS_AFTER_THE_GATED_PUBLISH_FROM_THE_TARBALL_IT_COMPARED_AND_CONFIRMS_THE_SAME_ALIAS',
        held,
        probeDetail(
          held,
          [...standing, ...plantProbes],
          `release.yml packs each of ${ALIASES.join(' and ')} — the names scripts/alias_tarball.ts holds — once, in its own step after the gated ` +
            '`npm publish` in the same job, and publishes the tarball it printed; every `bun run smoke` call confirms every alias, and RELEASING.md ' +
            `carries \`npm view\` for ${[packageName, ...ALIASES].join(', ')} — over ${plants.length} plant(s): ${plantCases.join('; ')}`,
        ),
        'issue #1258: an alias named in three places drifts in the one nobody reads, and an alias published ahead of the gate ' +
          'or from another tree than the one compared is the same files only by luck; issue #1347 made the alias a list, so ' +
          'dropping any one name from the publish or from either confirmation has to be its own red',
      );
    }

    // --- CUR31: the workflow and the document, against those two runs --------
    if (BUN_YAML === null) {
      reportYamlHole('CUR31_THE_RELEASE_WORKFLOW_CALLS_THE_CONFIRMATION_AS_ITS_DOCUMENT_STATES_AND_A_DISPATCH_CUTS_NOTHING');
    } else {
      const help = smokeWith(null, ['--help']);
      const confirmationFaults = (yml: string, doc: string, helpText: string): string[] => {
        const faults: string[] = [];
        let parsed: Workflow;
        try {
          parsed = readYaml(yml) as Workflow;
        } catch (error) {
          return [`release.yml does not parse as YAML: ${error instanceof Error ? error.message : String(error)}`];
        }
        const jobs = Object.entries(parsed.jobs ?? {});
        if (jobs.length === 0) return ['release.yml declares no jobs at all, so every clause below would be reading nothing'];
        const bodyOf = (job: WfJob): string => (job.steps ?? []).map((step) => step.run ?? '').join('\n');

        // 1. A dispatch exists, and it takes the version it is asked to confirm.
        const dispatch = parsed.on?.workflow_dispatch;
        const input = dispatch?.inputs?.version;
        if (dispatch === undefined) {
          faults.push('release.yml declares no `workflow_dispatch`, so a confirmation whose wait ran out can only be re-taken by publishing again');
        } else if (input === undefined) {
          faults.push('`workflow_dispatch` declares no `version` input, so a re-run has nothing to say which cut it is confirming');
        } else if (input.required !== true && !jobs.some(([, job]) => /\binputs\.version\s*!=\s*''/.test(job.if ?? '') && /bun run smoke/.test(bodyOf(job)))) {
          // Optional since issue #1504 (a dispatch gives `tag` or `version`, and GitHub refuses one that omits a required
          // input), so the job that confirms is what has to refuse an empty version instead.
          faults.push('the `version` input is not required and no confirming job runs under `inputs.version != \'\'`, so a dispatch with that field left empty would confirm whatever the checked-out package.json last said');
        }

        // 2. What a dispatch can reach. The guard is structural — release-please
        //    has to be held to the push event, and the job that publishes to
        //    the push or to the tag `plan` resolved (issue #1504: a `tag`
        //    dispatch publishes through the same job, CUR131) — rather than a
        //    list of step names, because a step added tomorrow is exactly what
        //    a name list cannot see. "Held" is a top-level `&&` term: a push
        //    term joined by `||` holds nothing.
        const heldBy = (condition: string | undefined, term: RegExp): boolean => {
          const bare = (condition ?? '').replace(/^\s*\$\{\{\s*|\s*\}\}\s*$/g, '');
          return !bare.includes('||') && bare.split('&&').some((one) => term.test(one.trim()));
        };
        const push = /^github\.event_name\s*==\s*'push'$/;
        const resolvedTag = /^needs\.[A-Za-z_][\w-]*\.outputs\.publish\s*==\s*'true'$/;
        const publishers = jobs.filter(([, job]) => /npm publish/.test(bodyOf(job)));
        if (publishers.length !== 1) {
          faults.push(`${publishers.length} job(s) run \`npm publish\` where exactly one does today — this clause is reading something other than the publish`);
        }
        for (const [name, job] of jobs) {
          if (/npm publish/.test(bodyOf(job)) && !heldBy(job.if, push) && !heldBy(job.if, resolvedTag)) {
            faults.push(
              `job "${name}" publishes and its \`if\` is ${JSON.stringify(job.if ?? null)}, which holds it neither to a push nor to the tag a plan job resolved — a workflow_dispatch would reach it`,
            );
          }
          for (const step of job.steps ?? []) {
            if (/release-please/.test(step.uses ?? '') && !heldBy(step.if, push) && !heldBy(job.if, push)) {
              faults.push(
                `job "${name}" cuts a release under the step's \`if\` ${JSON.stringify(step.if ?? null)} and the job's ${JSON.stringify(job.if ?? null)}, neither of which holds it to a push — a workflow_dispatch would reach it`,
              );
            }
          }
        }

        // 3. Every call of the confirmation, and the flags the document states.
        const calls: Array<{ job: string; argv: string[]; timeout: number | undefined }> = [];
        for (const [name, job] of jobs) {
          for (const step of job.steps ?? []) {
            const line = (step.run ?? '').split('\n').map((one) => one.trim()).find((one) => one.startsWith('bun run smoke'));
            if (line === undefined) continue;
            calls.push({ job: name, argv: line.split(/\s+/).slice(4), timeout: job['timeout-minutes'] });
          }
        }
        if (calls.length < 2) {
          faults.push(`${calls.length} step(s) call \`bun run smoke\`, and the cut's own path and the re-run path are two — a confirmation on one path only is the one that cannot be re-taken`);
        }
        const after = (argv: readonly string[], name: string): string | null => {
          const at = argv.indexOf(name);
          return at === -1 || at === argv.length - 1 ? null : argv[at + 1];
        };
        const waits = new Set<string>();
        for (const call of calls) {
          if (after(call.argv, '--source') !== 'registry') faults.push(`the smoke call in job "${call.job}" does not pass \`--source registry\`, so it confirms a tarball this tree packed rather than the published one`);
          if (after(call.argv, '--version') === null) faults.push(`the smoke call in job "${call.job}" passes no \`--version\``);
          if (after(call.argv, '--case') !== 'clean') faults.push(`the smoke call in job "${call.job}" does not pass \`--case clean\`, so a cut would run the plants against the published package`);
          const wait = after(call.argv, '--wait');
          if (wait === null) {
            faults.push(`the smoke call in job "${call.job}" passes no \`--wait\`, so how long a cut waits for the registry is not readable in the file whose own timeout has to cover it`);
            continue;
          }
          waits.add(wait);
          const minutes = Number(wait);
          if (!Number.isFinite(minutes) || minutes <= 0) {
            faults.push(`the smoke call in job "${call.job}" waits ${JSON.stringify(wait)}, which is not a number of minutes`);
          } else if (call.timeout === undefined || call.timeout <= minutes) {
            faults.push(
              `job "${call.job}" waits ${wait} min for the registry under a timeout-minutes of ${String(call.timeout)}, so the job is cancelled before its own wait can end — and a cancelled job is neither of the two outcomes`,
            );
          }
        }
        if (waits.size > 1) faults.push(`the confirmation is called with ${[...waits].join(' and ')} minute(s) of wait on different paths, so a re-run does not wait the way the cut did`);

        // 4. The document, against the workflow and against the script's own
        //    `--help`, and never against a figure written here.
        for (const wait of waits) {
          if (!doc.includes(`--wait ${wait}`)) faults.push(`the workflow waits ${wait} min for the registry and RELEASING.md states no \`--wait ${wait}\``);
        }
        const codes = [...helpText.matchAll(/^ {2}(\d)\s{2}\S/gm)].map((found) => found[1]);
        if (codes.length < 4) {
          faults.push(`\`--help\` lists ${codes.length} exit code(s) where the script distinguishes four — this clause is reading the wrong block`);
        }
        for (const code of codes) {
          if (!new RegExp(`^\\|\\s*\`${code}\`\\s*\\|`, 'm').test(doc)) faults.push(`the script's \`--help\` lists exit code ${code} and RELEASING.md has no row for it`);
        }
        for (const found of doc.matchAll(/^\|\s*`(\d)`\s*\|/gm)) {
          if (!codes.includes(found[1])) faults.push(`RELEASING.md states an exit code ${found[1]} that the script's \`--help\` does not list`);
        }
        // 5. The by-hand command, taken from what the run above PRINTED rather
        //    than written out here a second time: somebody whose cut timed out is
        //    sent to this document, and the document has to carry the command the
        //    tool is offering them.
        if (byHandPrinted !== '' && !doc.includes(byHandPrinted.split(FAKE).join('<version>'))) {
          faults.push(`the run whose wait ended offers \`${byHandPrinted}\` and RELEASING.md carries no such line with \`<version>\` in it`);
        }
        return faults;
      };

      const ymlText = readFileSync(join(root, '.github', 'workflows', 'release.yml'), 'utf8');
      const docText = readFileSync(join(root, 'RELEASING.md'), 'utf8');
      const standing = confirmationFaults(ymlText, docText, help.out);
      const jobCount = Object.keys((readYaml(ymlText) as Workflow).jobs ?? {}).length;
      /** An edit that has to change the text it is given — a plant that planted nothing is a fault of its own. */
      const plantInto = (text: string, from: string, to: string): string | null => (text.includes(from) ? text.split(from).join(to) : null);
      const plants: Array<{ what: string; yml: [string, string] | null; doc: [string, string] | null; quiet?: boolean }> = [
        { what: 'release-please stops being held to a push', yml: ["        id: release\n        if: ${{ github.event_name == 'push' }}\n", '        id: release\n'], doc: null },
        { what: 'the publishing job stops being held to the resolved tag', yml: ["    needs: [plan, gate]\n    if: ${{ needs.plan.outputs.publish == 'true' }}\n", '    needs: [plan, gate]\n'], doc: null },
        { what: 'the confirmation stops refusing an empty version', yml: [" && inputs.version != '' && inputs.tag == '' }}", " && inputs.tag == '' }}"], doc: null },
        { what: 'the workflow stops taking a dispatch', yml: ['  workflow_dispatch:\n', '  workflow_call:\n'], doc: null },
        { what: 'the re-run path waits three times as long as the cut did', yml: ['--version "$VERSION" --wait 15', '--version "$VERSION" --wait 45'], doc: null },
        { what: 'the cut stops passing a wait at all', yml: ['--version "$version" --wait 15 --case clean', '--version "$version" --case clean'], doc: null },
        { what: 'the re-run stops naming the case', yml: ['--version "$VERSION" --wait 15 --case clean', '--version "$VERSION" --wait 15'], doc: null },
        { what: 'the publishing job is given a timeout under its own wait', yml: ['    timeout-minutes: 40\n', '    timeout-minutes: 10\n'], doc: null },
        { what: 'the document states a wait the workflow does not pass', yml: null, doc: ['--wait 15', '--wait 5'] },
        { what: 'the document drops the row for the not-served exit code', yml: null, doc: ['| `3` |', '| `9` |'] },
        { what: 'the confirmation job is renamed', yml: ['\n  confirm:\n', '\n  reconfirm:\n'], doc: null, quiet: true },
      ];
      const plantProbes: string[] = [];
      const plantCases: string[] = [];
      for (const plant of plants) {
        const yml = plant.yml === null ? ymlText : plantInto(ymlText, plant.yml[0], plant.yml[1]);
        const doc = plant.doc === null ? docText : plantInto(docText, plant.doc[0], plant.doc[1]);
        if (yml === null || doc === null) {
          plantProbes.push(`"${plant.what}": the edit found nothing to change, so this plant was never made`);
          continue;
        }
        const raised = raisedBy(confirmationFaults(yml, doc, help.out), { was: standing });
        if (plant.quiet === true) {
          if (raised.length > 0) plantProbes.push(`"${plant.what}" changes nothing this gate is about and ${raised.length} fault(s) fired: ${raised[0].slice(0, 160)}`);
          plantCases.push(`${plant.what} -> quiet`);
          continue;
        }
        if (raised.length === 0) plantProbes.push(`"${plant.what}" was planted and this gate did not fire`);
        plantCases.push(`${plant.what} -> ${raised.length}`);
      }
      const confirmationHeld = standing.length === 0 && plantProbes.length === 0;
      say(
        'CUR31_THE_RELEASE_WORKFLOW_CALLS_THE_CONFIRMATION_AS_ITS_DOCUMENT_STATES_AND_A_DISPATCH_CUTS_NOTHING',
        confirmationHeld,
        probeDetail(
          confirmationHeld,
          [...standing, ...plantProbes],
          `release.yml's ${jobCount} job(s) read as a workflow whose release-please is held to a push, whose publish is held to the tag ` +
            'a plan job resolved, and whose confirming job refuses an empty `version`, with every `bun run smoke` call passing the same wait under a timeout that ' +
            'covers it, and RELEASING.md carrying that wait, a row for each exit code `--help` lists, and the ' +
            `by-hand command the run above printed — over ${plants.length} plant(s): ${plantCases.join('; ')}`,
        ),
        'a `run:` body cannot be red-firsted anywhere, so the wait moved into a script and what stayed in the ' +
          'workflow is a call. This is what keeps the call honest — and the quiet plant is what says the scan is ' +
          'structural rather than a search for the job that happens to be named `confirm`',
      );
    }
  }

  // --- CUR112: the publish gate runs over the corpus CI's gate runs over (#1003)
  //
  // 🚨 **v1.6.0 was tagged, released on GitHub and never served.** The release
  // job's `prepublishOnly` ran the same three commands as `ci.yml`'s `test`
  // job, but not over the same tree: `test` fetches the Spine examples before
  // its selftest and the release job did not, on the premise — written in both
  // the workflow and RELEASING.md — that the selftest needs no corpus. The core
  // suite retired that premise: with no examples/ its corpus controls are red,
  // correctly, and four of them failed the publish ten minutes in.
  //
  // ⭐ Read structurally, like CUR31: the job that runs `npm publish` and the
  // job that runs `bun run selftest` are found by what their steps run, not by
  // their names, and the fetch has to sit before the gated step in each, with
  // the same body and environment, and — in the release job — under the same
  // `if:` as the publish. A fetch that runs when nothing is being released is
  // a different fault from a missing one, but it is still one: the two steps
  // stop being a pair.
  if (BUN_YAML === null) {
    reportYamlHole('CUR112_THE_PUBLISH_GATE_FETCHES_THE_CORPUS_BEFORE_NPM_PUBLISH_AS_CI_DOES_BEFORE_THE_SELFTEST');
  } else {
    interface CorpusStep {
      name?: string;
      run?: string;
      if?: string;
      env?: Record<string, string>;
    }
    interface CorpusWorkflow {
      jobs?: Record<string, { steps?: CorpusStep[] }>;
    }
    const FETCH = 'bun run fetch-examples';
    const runsExactly = (step: CorpusStep, command: string): boolean =>
      (step.run ?? '')
        .split('\n')
        .map((line) => line.trim())
        .includes(command);
    const corpusFaults = (releaseYml: string, ciYml: string, doc: string): string[] => {
      const faults: string[] = [];
      const parse = (file: string, text: string): CorpusWorkflow | null => {
        try {
          return readYaml(text) as CorpusWorkflow;
        } catch (error) {
          faults.push(`${file} does not parse as YAML: ${error instanceof Error ? error.message : String(error)}`);
          return null;
        }
      };
      const release = parse('release.yml', releaseYml);
      // Since issue #1249 the selftest job is selftest-shards.yml's, which ci.yml and release.yml both call.
      const ci = parse('selftest-shards.yml', ciYml);
      if (release === null || ci === null) return faults;

      /** The one job whose steps run `gated`, the index of that step, and the index of the fetch in it. */
      const pairIn = (
        file: string,
        wf: CorpusWorkflow,
        gated: string,
        matches: (step: CorpusStep) => boolean,
      ): { job: string; steps: CorpusStep[]; gate: number; fetch: number } | null => {
        const holders = Object.entries(wf.jobs ?? {}).filter(([, job]) => (job.steps ?? []).some(matches));
        if (holders.length !== 1) {
          faults.push(`${file}: ${holders.length} job(s) run \`${gated}\` where exactly one does today — this control is reading something other than the gate`);
          return null;
        }
        const [job, body] = holders[0];
        const steps = body.steps ?? [];
        const gate = steps.findIndex(matches);
        const fetches = steps.map((step, at) => (runsExactly(step, FETCH) ? at : -1)).filter((at) => at !== -1);
        if (fetches.length !== 1) {
          faults.push(
            `${file}: job "${job}" runs \`${FETCH}\` in ${fetches.length} step(s) where exactly one is required, so its \`${gated}\` ` +
              (fetches.length === 0 ? 'reads a tree with no example corpus — the #1003 fault' : 'has no single fetch to be ordered against'),
          );
          return null;
        }
        const fetch = fetches[0];
        if (fetch > gate) {
          faults.push(
            `${file}: job "${job}" runs \`${FETCH}\` at step ${fetch + 1}, after \`${gated}\` at step ${gate + 1}, so the gate has already read a tree with no corpus when it arrives`,
          );
        }
        return { job, steps, gate, fetch };
      };
      const publish = pairIn('release.yml', release, 'npm publish', (step) => /\bnpm publish\b/.test(step.run ?? ''));
      const test = pairIn('selftest-shards.yml', ci, 'bun run selftest', (step) => runsExactly(step, 'bun run selftest'));
      // The pairing is read only when both halves were found; the document
      // below is read either way, so a tree carrying both faults names both.
      if (publish !== null && test !== null) {
        const releaseFetch = publish.steps[publish.fetch];
        const ciFetch = test.steps[test.fetch];
        const publishIf = publish.steps[publish.gate].if;
        if (releaseFetch.if !== publishIf) {
          faults.push(
            `release.yml: the fetch in job "${publish.job}" runs under \`if: ${releaseFetch.if ?? '(none)'}\` and the publish under ` +
              `\`if: ${publishIf ?? '(none)'}\`, so the corpus is fetched on runs that publish nothing, or missing on one that does`,
          );
        }
        const envOf = (step: CorpusStep): string => JSON.stringify(Object.entries(step.env ?? {}).sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)));
        if (envOf(releaseFetch) !== envOf(ciFetch)) {
          faults.push(
            `release.yml: the fetch in job "${publish.job}" runs with env ${envOf(releaseFetch)} and selftest-shards.yml's in job "${test.job}" with ` +
              `${envOf(ciFetch)}, so the two gates fetch under different rate limits and can read different corpora`,
          );
        }
      }

      // The document: the paragraph that states what `prepublishOnly` runs.
      const paragraph = doc
        .split(/\n\s*\n/)
        .find((one) => one.startsWith('`prepublishOnly` runs'))
        ?.replace(/\s+/g, ' ');
      if (paragraph === undefined) {
        faults.push('RELEASING.md has no paragraph beginning "`prepublishOnly` runs", so what the publish gate reads is stated nowhere this control can find');
        return faults;
      }
      for (const sentence of paragraph.split(/(?<=[.;])\s+/)) {
        if (/needs no corpus|does not fetch the Spine examples/.test(sentence)) {
          faults.push(`RELEASING.md's \`prepublishOnly\` paragraph still states the retired premise: "${sentence.trim()}"`);
        }
      }
      if (!paragraph.includes(`\`${FETCH}\``)) {
        faults.push(`RELEASING.md's \`prepublishOnly\` paragraph does not name \`${FETCH}\`, so it does not say the publish gate reads the corpus`);
      }
      return faults;
    };

    const releaseText = readFileSync(join(root, '.github', 'workflows', 'release.yml'), 'utf8');
    const ciText = readFileSync(join(root, '.github', 'workflows', 'selftest-shards.yml'), 'utf8');
    const releasingText = readFileSync(join(root, 'RELEASING.md'), 'utf8');
    const standing = corpusFaults(releaseText, ciText, releasingText);
    const edit = (text: string, from: string, to: string): string | null => (text.includes(from) ? text.split(from).join(to) : null);
    // Since issue #1249 the publishing job is held to the release by its own `if:`, so neither step carries one.
    const fetchStep =
      '      - name: Fetch the Spine example corpus\n' +
      '        run: bun run fetch-examples\n' +
      '        env:\n' +
      '          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}\n\n';
    const publishRun = '        run: npm publish --provenance --access public\n';
    const moved = ((): string | null => {
      const dropped = edit(releaseText, fetchStep, '');
      return dropped === null ? null : edit(dropped, publishRun, `${publishRun}\n${fetchStep.slice(0, -1)}`);
    })();
    const plants: Array<{ what: string; release: string | null; ci?: string | null; doc?: string | null; quiet?: boolean }> = [
      { what: 'the fetch step is dropped from release.yml', release: edit(releaseText, fetchStep, '') },
      { what: 'the fetch step is moved after the publish', release: moved },
      {
        what: 'the fetch step gains an `if:` the publish does not carry',
        release: edit(
          releaseText,
          '      - name: Fetch the Spine example corpus\n        run: bun run fetch-examples\n',
          "      - name: Fetch the Spine example corpus\n        if: ${{ github.event_name == 'workflow_dispatch' }}\n        run: bun run fetch-examples\n",
        ),
      },
      {
        what: 'the release fetch loses the token ci.yml passes',
        release: edit(releaseText, 'run: bun run fetch-examples\n        env:\n          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}\n', 'run: bun run fetch-examples\n'),
      },
      {
        what: "RELEASING.md's paragraph gets the retired sentence back",
        release: releaseText,
        doc: edit(
          releasingText,
          'every push, and they run over the same corpus:',
          'every push; the selftest needs no corpus and no arguments, and reports the\nexample suites as HOLEs rather than passes when `examples/` is absent, which is\nwhy the publish job does not fetch the Spine examples the way `ci.yml` does. And',
        ),
      },
      {
        what: "selftest-shards.yml's own fetch is moved after its selftest",
        release: releaseText,
        ci: ((): string | null => {
          const at = ciText.indexOf('      - name: Fetch the Spine example corpus\n');
          const selftest = '      - run: bun run selftest\n';
          if (at === -1 || !ciText.includes(selftest)) return null;
          const end = ciText.indexOf('\n\n', at);
          const step = ciText.slice(at, end + 2);
          return edit(ciText.replace(step, ''), selftest, `${selftest}\n${step.slice(0, -1)}`);
        })(),
      },
      { what: 'the release fetch step is renamed', release: edit(releaseText, 'name: Fetch the Spine example corpus\n        run:', 'name: Examples\n        run:'), quiet: true },
    ];
    const plantProbes: string[] = [];
    const plantCases: string[] = [];
    for (const plant of plants) {
      const ciYml = plant.ci === undefined ? ciText : plant.ci;
      const doc = plant.doc === undefined ? releasingText : plant.doc;
      if (plant.release === null || ciYml === null || doc === null) {
        plantProbes.push(`"${plant.what}": the edit found nothing to change, so this plant was never made`);
        continue;
      }
      const raised = raisedBy(corpusFaults(plant.release, ciYml, doc), { was: standing });
      if (plant.quiet === true) {
        if (raised.length > 0) plantProbes.push(`"${plant.what}" changes nothing this gate is about and ${raised.length} fault(s) fired: ${raised[0].slice(0, 160)}`);
        plantCases.push(`${plant.what} -> quiet`);
        continue;
      }
      if (raised.length === 0) plantProbes.push(`"${plant.what}" was planted and this gate did not fire`);
      plantCases.push(`${plant.what} -> ${raised.length}`);
    }
    const corpusHeld = standing.length === 0 && plantProbes.length === 0;
    say(
      'CUR112_THE_PUBLISH_GATE_FETCHES_THE_CORPUS_BEFORE_NPM_PUBLISH_AS_CI_DOES_BEFORE_THE_SELFTEST',
      corpusHeld,
      probeDetail(
        corpusHeld,
        [...standing, ...plantProbes],
        `release.yml's publishing job runs \`${FETCH}\` before \`npm publish\`, under the publish's own \`if:\` and with ` +
          "the environment selftest-shards.yml's shard job — ci.yml's gate and release.yml's — fetches with, as that job does before `bun run selftest`, and " +
          `RELEASING.md's \`prepublishOnly\` paragraph names the fetch and not the retired premise — over ${plants.length} ` +
          `plant(s): ${plantCases.join('; ')}`,
      ),
      "v1.6.0's publish ran the selftest with no examples/ and four core-suite corpus controls went red after the " +
        'tag and the GitHub release existed, because the workflow and RELEASING.md both said the selftest needs no ' +
        'corpus. Red on the tree before #1003 — no fetch step in the publishing job',
    );
  }

  // --- CUR119/CUR120: the release run's graph, and the one gate both workflows call (issue #1249)
  //
  // ⏱️ The publish ran the whole selftest in one process on one runner —
  // `Publish to npm` 18m37s of a ~21-minute run (v2.20.0) — where CI runs it as
  // six shards and a merge. So release.yml now calls the same shards and merge
  // over the tag (`gate`) and `prepublishOnly` reads the merged tally they wrote
  // instead of running them again. That trade is only sound in one order, and
  // CUR119 holds it: release-please first, the gate on the tag `plan` resolved
  // under the one condition `plan` resolved, the publish after the gate with
  // the corpus fetched and the tally downloaded first, `RIGC_PREPUBLISH_TALLY`
  // set on the publish step and nowhere else, the OIDC token on the publish job
  // alone, and a dispatch reaching the confirmation or — through `plan`'s
  // resolve step — the same gate and publish, never a job of its own (issue
  // #1504; CUR131 holds the dispatch's refusals). CUR120 holds the other half of the premise:
  // the gate release.yml reads is the gate ci.yml reads — one reusable workflow,
  // called by both, and no second definition of the shards anywhere in the tree.
  {
    interface GraphStep {
      name?: string;
      id?: string;
      run?: string;
      uses?: string;
      if?: string;
      env?: Record<string, string>;
      with?: Record<string, string>;
    }
    interface GraphJob {
      needs?: string | string[];
      if?: string;
      uses?: string;
      with?: Record<string, string>;
      env?: Record<string, string>;
      permissions?: Record<string, string> | string;
      outputs?: Record<string, string>;
      steps?: GraphStep[];
    }
    interface GraphWorkflow {
      on?: Record<string, unknown>;
      env?: Record<string, string>;
      permissions?: Record<string, string> | string;
      jobs?: Record<string, GraphJob>;
    }
    const SHARDS_FILE = 'selftest-shards.yml';
    const SHARDS_USES = `./.github/workflows/${SHARDS_FILE}`;
    const TALLY_ARTIFACT = 'selftest-merged-tally';
    const FETCH = 'bun run fetch-examples';
    const parseAll = (texts: Record<string, string>, faults: string[]): Record<string, GraphWorkflow> | null => {
      const parsed: Record<string, GraphWorkflow> = {};
      for (const [file, text] of Object.entries(texts)) {
        try {
          parsed[file] = readYaml(text) as GraphWorkflow;
        } catch (error) {
          faults.push(`${file} does not parse as YAML: ${error instanceof Error ? error.message : String(error)}`);
        }
      }
      return faults.length > 0 ? null : parsed;
    };
    const needsOf = (job: GraphJob): string[] => (job.needs === undefined ? [] : Array.isArray(job.needs) ? job.needs : [job.needs]);
    const runLines = (step: GraphStep): string[] => (step.run ?? '').split('\n').map((line) => line.trim());
    /** The terms of a condition joined by `op` at its top level, `${{ }}` and whitespace normalised; null when it also joins by the other operator. */
    const termsOf = (condition: string | undefined, op: '&&' | '||'): string[] | null => {
      const bare = (condition ?? '').trim().replace(/^\$\{\{\s*/, '').replace(/\s*\}\}$/, '').replace(/\s+/g, ' ');
      if (bare.includes(op === '&&' ? '||' : '&&')) return null;
      return bare.split(op).map((term) => term.trim());
    };
    // Since issue #1504 a push term joined by `||` holds nothing — `plan` runs under one — so "held" means a top-level `&&` term.
    const heldToPush = (job: { if?: string }): boolean => (termsOf(job.if, '&&') ?? []).includes("github.event_name == 'push'");

    // --- CUR119 ----------------------------------------------------------------
    const graphFaults = (releaseYml: string, otherYml: Record<string, string>): string[] => {
      const faults: string[] = [];
      const all = parseAll({ 'release.yml': releaseYml, ...otherYml }, faults);
      if (all === null) return faults;
      const wf = all['release.yml'];
      const jobs = Object.entries(wf.jobs ?? {});
      const one = (what: string, match: (job: GraphJob) => boolean): [string, GraphJob] | null => {
        const found = jobs.filter(([, job]) => match(job));
        if (found.length !== 1) {
          faults.push(`release.yml: ${found.length} job(s) ${what} where exactly one does`);
          return null;
        }
        return found[0];
      };
      const plan = one('run release-please', (job) => (job.steps ?? []).some((step) => /release-please/.test(step.uses ?? '')));
      const gate = one(`call ${SHARDS_FILE}`, (job) => job.uses === SHARDS_USES);
      const publish = one('run `npm publish`', (job) => (job.steps ?? []).some((step) => /\bnpm publish\b/.test(step.run ?? '')));
      if (plan === null || gate === null || publish === null) return faults;
      const [planName, planJob] = plan;
      const [gateName, gateJob] = gate;
      const [publishName, publishJob] = publish;
      const resolved = `\${{ needs.${planName}.outputs.publish == 'true' }}`;
      const resolvedTag = `\${{ needs.${planName}.outputs.sha || needs.${planName}.outputs.tag }}`;

      // The order: plan → gate → publish, the last two held to the one condition plan resolved (issue #1504).
      if (!needsOf(gateJob).includes(planName)) faults.push(`release.yml: job "${gateName}" does not need "${planName}", so the gate can start before a tag exists`);
      if (!needsOf(publishJob).includes(gateName)) faults.push(`release.yml: job "${publishName}" does not need "${gateName}", so it can publish over a gate that has not run or went red`);
      if (!needsOf(publishJob).includes(planName)) faults.push(`release.yml: job "${publishName}" does not need "${planName}", so it cannot read the tag it publishes`);
      for (const [name, job] of [gate, publish]) {
        if ((job.if ?? '').replace(/\s+/g, ' ').trim() !== resolved) {
          faults.push(`release.yml: job "${name}" runs under \`if: ${job.if ?? '(none)'}\`, where it runs under ${resolved} alone — the tag ${planName} resolved, on a push or a dispatch`);
        }
      }
      const planSteps = planJob.steps ?? [];
      const please = planSteps.findIndex((step) => /release-please/.test(step.uses ?? ''));
      if (!heldToPush(planSteps[please]) && !heldToPush(planJob)) {
        faults.push(`release.yml: the release-please step of job "${planName}" runs under \`if: ${planSteps[please].if ?? '(none)'}\` in a job under \`if: ${planJob.if ?? '(none)'}\`, which does not hold it to a push, so a dispatch could cut a tag or a release`);
      }
      const target = planSteps.findIndex((step) => step.id === 'target');
      if (target === -1) faults.push(`release.yml: job "${planName}" has no step with id \`target\`, so nothing resolves what ${gateName} and ${publishName} read`);
      else {
        if (target !== please + 1) faults.push(`release.yml: the resolve step is step ${target + 1} of job "${planName}", where it follows release-please (step ${please + 1}) directly`);
        if (planSteps[target].if !== undefined) faults.push(`release.yml: the resolve step runs under \`if: ${planSteps[target].if}\`, so a run can skip it and leave ${gateName} and ${publishName} nothing to read`);
      }
      for (const output of ['publish', 'tag']) {
        const want = `\${{ steps.target.outputs.${output} }}`;
        if (planJob.outputs?.[output] !== want) faults.push(`release.yml: job "${planName}" exports \`${output}\` as ${JSON.stringify(planJob.outputs?.[output] ?? null)}, not ${want}`);
      }
      if ((gateJob.with?.ref ?? '') !== resolvedTag) {
        faults.push(`release.yml: job "${gateName}" calls ${SHARDS_FILE} with ref ${JSON.stringify(gateJob.with?.ref ?? null)}, not the ref "${planName}" resolved (${resolvedTag}), so the gate reads another tree than the publish`);
      }

      // The publish job's steps: the fetch and the tally before the publish, the variable on the publish alone.
      const steps = publishJob.steps ?? [];
      const at = steps.findIndex((step) => /\bnpm publish\b/.test(step.run ?? ''));
      const fetch = steps.findIndex((step) => runLines(step).includes(FETCH));
      const download = steps.findIndex((step) => /actions\/download-artifact/.test(step.uses ?? '') && step.with?.name === TALLY_ARTIFACT);
      if (fetch === -1 || fetch > at) faults.push(`release.yml: job "${publishName}" runs \`${FETCH}\` at step ${fetch + 1}, not before the publish at step ${at + 1}, so a refused tally falls back to a selftest with no corpus`);
      if (download === -1 || download > at) faults.push(`release.yml: job "${publishName}" downloads "${TALLY_ARTIFACT}" at step ${download + 1}, not before the publish at step ${at + 1}`);
      const named = steps[at].env?.RIGC_PREPUBLISH_TALLY;
      const into = download === -1 ? null : steps[download].with?.path ?? null;
      if (named === undefined) faults.push(`release.yml: the publish step sets no RIGC_PREPUBLISH_TALLY, so the tally "${gateName}" wrote is never read and the publish runs the whole selftest again`);
      else if (into === null || !named.startsWith(`${into}/`)) faults.push(`release.yml: RIGC_PREPUBLISH_TALLY names ${JSON.stringify(named)}, which is not under the path the tally is downloaded into (${JSON.stringify(into)})`);
      const setters: string[] = [];
      for (const [file, flow] of Object.entries(all)) {
        if (flow.env?.RIGC_PREPUBLISH_TALLY !== undefined) setters.push(`${file}'s workflow env`);
        for (const [name, job] of Object.entries(flow.jobs ?? {})) {
          if (job.env?.RIGC_PREPUBLISH_TALLY !== undefined) setters.push(`${file} job "${name}"'s env`);
          if (Object.values(job.with ?? {}).some((value) => String(value).includes('RIGC_PREPUBLISH_TALLY'))) setters.push(`${file} job "${name}"'s with`);
          (job.steps ?? []).forEach((step, k) => {
            const self = file === 'release.yml' && name === publishName && k === at;
            if (!self && step.env?.RIGC_PREPUBLISH_TALLY !== undefined) setters.push(`${file} job "${name}" step ${k + 1}'s env`);
            if ((step.run ?? '').includes('RIGC_PREPUBLISH_TALLY')) setters.push(`${file} job "${name}" step ${k + 1}'s run`);
          });
        }
      }
      if (setters.length > 0) faults.push(`RIGC_PREPUBLISH_TALLY is set beyond the publish step, in ${setters.join(', ')}`);

      // Permissions: the OIDC token on the publish job and nowhere else.
      const writesToken = (perms: GraphJob['permissions']): boolean =>
        perms === 'write-all' || (typeof perms === 'object' && perms !== null && perms['id-token'] === 'write');
      if (writesToken(wf.permissions)) faults.push('release.yml: the workflow grants `id-token: write` to every job');
      for (const [name, job] of jobs) {
        if (name !== publishName && writesToken(job.permissions)) faults.push(`release.yml: job "${name}" holds \`id-token: write\`, which only the publish needs`);
      }
      if (!writesToken(publishJob.permissions)) faults.push(`release.yml: job "${publishName}" holds no \`id-token: write\`, so trusted publishing has no token to exchange`);

      // What a dispatch reaches (issue #1504): plan, gate and publish — keyed on
      // the tag plan resolved, held above — and the confirmation, on a
      // `version` alone. Any other job not held to a push is a path of its own.
      if (wf.on?.workflow_dispatch === undefined) faults.push('release.yml takes no `workflow_dispatch`, so this clause reads nothing');
      const versionOnly = ["github.event_name == 'workflow_dispatch'", "inputs.version != ''", "inputs.tag == ''"];
      const confirmations: string[] = [];
      for (const [name, job] of jobs) {
        if (heldToPush(job) || name === planName || name === gateName || name === publishName) continue;
        const terms = termsOf(job.if, '&&');
        const confirms =
          terms !== null && terms.length === versionOnly.length && versionOnly.every((term) => terms.includes(term)) &&
          job.uses === undefined &&
          (job.steps ?? []).every((step) => !/\bnpm publish\b/.test(step.run ?? '') && !/release-please/.test(step.uses ?? '')) &&
          (job.steps ?? []).some((step) => runLines(step).some((line) => line.startsWith('bun run smoke')));
        if (confirms) confirmations.push(name);
        else faults.push(`release.yml: job "${name}" runs under \`if: ${job.if ?? '(none)'}\`, is not held to a push and is neither ${planName}, ${gateName}, ${publishName} nor the confirmation on a \`version\` dispatch alone, so a workflow_dispatch reaches it`);
      }
      if (confirmations.length !== 1) faults.push(`release.yml: ${confirmations.length} job(s) confirm on a \`version\` dispatch, where one does`);
      return faults;
    };

    // --- CUR120 ----------------------------------------------------------------
    const oneGateFaults = (texts: Record<string, string>): string[] => {
      const faults: string[] = [];
      const all = parseAll(texts, faults);
      if (all === null) return faults;
      const shards = all[SHARDS_FILE];
      if (shards === undefined) return [`there is no .github/workflows/${SHARDS_FILE}`];
      if (shards.on?.workflow_call === undefined) faults.push(`${SHARDS_FILE} is not a reusable workflow (no \`on.workflow_call\`), so nothing can call it`);
      // Where the shards are defined: a step running the selftest under RIGC_SHARD, or a merge.
      for (const [file, flow] of Object.entries(all)) {
        for (const [name, job] of Object.entries(flow.jobs ?? {})) {
          for (const step of job.steps ?? []) {
            const shardRun = runLines(step).includes('bun run selftest') && step.env?.RIGC_SHARD !== undefined;
            const merge = runLines(step).some((line) => /selftest\.ts\s+--merge\b/.test(line));
            if ((shardRun || merge) && file !== SHARDS_FILE) faults.push(`${file} job "${name}" ${shardRun ? 'runs a shard' : 'merges shards'} of its own, a second definition of the gate beside ${SHARDS_FILE}`);
          }
        }
      }
      const shardJobs = Object.entries(shards.jobs ?? {}).filter(([, job]) => (job.steps ?? []).some((step) => runLines(step).includes('bun run selftest') && step.env?.RIGC_SHARD !== undefined));
      const mergeSteps = Object.values(shards.jobs ?? {}).flatMap((job) => (job.steps ?? []).filter((step) => runLines(step).some((line) => /selftest\.ts\s+--merge\b/.test(line))));
      if (shardJobs.length !== 1) faults.push(`${SHARDS_FILE}: ${shardJobs.length} job(s) run the shards, where one matrix does`);
      if (mergeSteps.length !== 1) faults.push(`${SHARDS_FILE}: ${mergeSteps.length} step(s) run \`--merge\`, where one does`);
      else {
        const tallyOut = /--tally-out\s+"?([^"\s]+)"?/.exec(mergeSteps[0].run ?? '')?.[1] ?? null;
        const upload = Object.values(shards.jobs ?? {}).flatMap((job) => job.steps ?? []).find((step) => /actions\/upload-artifact/.test(step.uses ?? '') && step.with?.name === TALLY_ARTIFACT);
        if (tallyOut === null) faults.push(`${SHARDS_FILE}: the merge writes no \`--tally-out\`, so there is no merged tally for a publish to read`);
        else if (upload === undefined) faults.push(`${SHARDS_FILE}: no step uploads "${TALLY_ARTIFACT}"`);
        else if (upload.with?.path?.replace('${{ runner.temp }}', '$RUNNER_TEMP') !== tallyOut) faults.push(`${SHARDS_FILE}: "${TALLY_ARTIFACT}" uploads ${JSON.stringify(upload.with?.path ?? null)} and the merge writes ${JSON.stringify(tallyOut)}`);
      }
      // Both callers call it.
      for (const caller of ['ci.yml', 'release.yml']) {
        const flow = all[caller];
        const calls = Object.entries(flow?.jobs ?? {}).filter(([, job]) => job.uses === SHARDS_USES);
        if (calls.length !== 1) faults.push(`${caller}: ${calls.length} job(s) call ${SHARDS_FILE}, where one does`);
      }
      // ci.yml's `test` is the required check, and it reads the merge's verdict.
      const ci = all['ci.yml'];
      const caller = Object.entries(ci?.jobs ?? {}).find(([, job]) => job.uses === SHARDS_USES)?.[0];
      const test = ci?.jobs?.test;
      if (test === undefined) faults.push('ci.yml has no job named `test`, which is the check pull requests are required to pass');
      else if (caller !== undefined) {
        const reads = (test.steps ?? []).some((step) => Object.values(step.env ?? {}).some((value) => value.includes(`needs.${caller}.outputs.verdict`)));
        if (!needsOf(test).includes(caller) || !reads) faults.push(`ci.yml's \`test\` does not need "${caller}" and read its \`verdict\` output, so the required check is not the merge's verdict`);
      }
      return faults;
    };

    const workflowsDir = join(root, '.github', 'workflows');
    const texts: Record<string, string> = Object.fromEntries(
      readdirSync(workflowsDir)
        .filter((file) => /\.ya?ml$/.test(file))
        .sort()
        .map((file) => [file, readFileSync(join(workflowsDir, file), 'utf8')] as const),
    );
    const releaseText = texts['release.yml'] ?? '';
    const others = Object.fromEntries(Object.entries(texts).filter(([file]) => file !== 'release.yml'));
    const once = (text: string, from: string, to: string): string | null => (text.includes(from) ? text.replace(from, to) : null);
    const runPlants = (
      standing: string[],
      plants: Array<{ what: string; edit: string | null | Record<string, string | null>; quiet?: boolean }>,
      check: (edited: Record<string, string>) => string[],
    ): { probes: string[]; cases: string[] } => {
      const probes: string[] = [];
      const cases: string[] = [];
      for (const plant of plants) {
        const edits = typeof plant.edit === 'string' || plant.edit === null ? { 'release.yml': plant.edit } : plant.edit;
        if (Object.values(edits).some((text) => text === null)) {
          probes.push(`"${plant.what}": the edit found nothing to change, so this plant was never made`);
          continue;
        }
        const raised = raisedBy(check({ ...texts, ...(edits as Record<string, string>) }), { was: standing });
        if (plant.quiet === true) {
          if (raised.length > 0) probes.push(`"${plant.what}" changes nothing this gate is about and ${raised.length} fault(s) fired: ${raised[0].slice(0, 160)}`);
          cases.push(`${plant.what} -> quiet`);
          continue;
        }
        if (raised.length === 0) probes.push(`"${plant.what}" was planted and this gate did not fire`);
        cases.push(`${plant.what} -> ${raised.length}`);
      }
      return { probes, cases };
    };

    if (BUN_YAML === null) {
      reportYamlHole('CUR119_RELEASE_YML_RUNS_PLAN_THEN_THE_SHARDED_GATE_ON_THE_RESOLVED_TAG_THEN_A_PUBLISH_THAT_READS_ITS_TALLY_AND_A_DISPATCH_REACHES_NO_PATH_OF_ITS_OWN');
    } else {
      const check = (edited: Record<string, string>): string[] =>
        graphFaults(edited['release.yml'] ?? '', Object.fromEntries(Object.entries(edited).filter(([file]) => file !== 'release.yml')));
      const standing = check(texts);
      const gateIf = "    if: ${{ needs.plan.outputs.publish == 'true' }}\n    permissions:\n      contents: read # check out the tag\n    uses:";
      const publishIf = "    needs: [plan, gate]\n    if: ${{ needs.plan.outputs.publish == 'true' }}\n";
      /** `from` → `to` where `from` occurs exactly once, or null — a plant whose anchor is ambiguous has planted nothing it can name. */
      const uniq = (text: string, from: string, to: string): string | null => (text.split(from).length === 2 ? text.replace(from, to) : null);
      const downloadStep = releaseText.slice(releaseText.indexOf('      - name: Download the merged tally the gate wrote\n'), releaseText.indexOf('      # `RIGC_PREPUBLISH_TALLY` is set on this step'));
      const moved = ((): string | null => {
        if (!downloadStep.startsWith('      - name: Download')) return null;
        const without = releaseText.replace(downloadStep, '');
        const confirm = '      # ROADMAP.md\'s fourth condition';
        return without.includes(confirm) ? without.replace(confirm, `${downloadStep}${confirm}`) : null;
      })();
      const { probes, cases } = runPlants(
        standing,
        [
          { what: 'the gate stops needing the plan', edit: once(releaseText, '    needs: plan\n', '') },
          { what: 'the publish stops needing the gate', edit: once(releaseText, '    needs: [plan, gate]\n', '    needs: [plan]\n') },
          { what: 'the gate loses the resolved condition', edit: once(releaseText, gateIf, gateIf.replace("needs.plan.outputs.publish == 'true'", "github.event_name == 'push'")) },
          { what: 'a dispatch reaches the gate past the resolve step', edit: once(releaseText, gateIf, gateIf.replace("needs.plan.outputs.publish == 'true'", "needs.plan.outputs.publish == 'true' || github.event_name == 'workflow_dispatch'")) },
          { what: 'the publish is keyed on release-please again', edit: uniq(releaseText, publishIf, publishIf.replace("needs.plan.outputs.publish == 'true'", "github.event_name == 'push' && needs.plan.outputs.release_created == 'true'")) },
          { what: 'the gate is called on the default branch rather than the tag', edit: uniq(releaseText, '\n      ref: ${{ needs.plan.outputs.sha || needs.plan.outputs.tag }}\n\n', "\n      ref: ''\n\n") },
          { what: 'release-please runs on a dispatch', edit: uniq(releaseText, "        id: release\n        if: ${{ github.event_name == 'push' }}\n", '        id: release\n') },
          { what: 'the resolve step is skipped on a dispatch', edit: uniq(releaseText, '        id: target\n', "        id: target\n        if: ${{ github.event_name == 'push' }}\n") },
          { what: 'plan exports the cut tag rather than the resolved one', edit: uniq(releaseText, '      tag: ${{ steps.target.outputs.tag }}\n', '      tag: ${{ steps.release.outputs.tag_name }}\n') },
          { what: 'the confirmation runs on a tag dispatch too', edit: uniq(releaseText, " && inputs.version != '' && inputs.tag == '' }}", ' }}') },
          { what: 'the tally is downloaded after the publish', edit: moved },
          { what: 'the publish step stops naming the tally', edit: once(releaseText, '        env:\n          RIGC_PREPUBLISH_TALLY:', '        env:\n          RIGC_UNREAD_TALLY:') },
          { what: 'the variable is set on the whole publish job', edit: once(releaseText, '    timeout-minutes: 40\n', '    timeout-minutes: 40\n    env:\n      RIGC_PREPUBLISH_TALLY: /dev/null\n') },
          { what: 'the plan job is handed the OIDC token', edit: once(releaseText, '      issues: write # release-please labels\n', '      issues: write # release-please labels\n      id-token: write\n') },
          { what: 'the download step is renamed', edit: once(releaseText, 'name: Download the merged tally the gate wrote', 'name: Tally'), quiet: true },
        ],
        check,
      );
      const held = standing.length === 0 && probes.length === 0;
      say(
        'CUR119_RELEASE_YML_RUNS_PLAN_THEN_THE_SHARDED_GATE_ON_THE_RESOLVED_TAG_THEN_A_PUBLISH_THAT_READS_ITS_TALLY_AND_A_DISPATCH_REACHES_NO_PATH_OF_ITS_OWN',
        held,
        probeDetail(
          held,
          [...standing, ...probes],
          `release.yml's ${Object.keys((readYaml(releaseText) as GraphWorkflow).jobs ?? {}).length} job(s) read as release-please held to a push and the resolve step right after it, then ${SHARDS_FILE} on the resolved tag under ` +
            'the resolved condition, then a publish under that same condition that needs the gate, fetches the corpus and downloads the merged tally before ' +
            '`npm publish`, with RIGC_PREPUBLISH_TALLY on that step alone and `id-token: write` on that job alone, and a dispatch ' +
            `that reaches those three jobs or the confirmation on a \`version\` alone, no job of its own — over ${cases.length} plant(s): ${cases.join('; ')}`,
        ),
        'issue #1249: the publish reads a tally instead of running the selftest, which is sound only if the tally is the gate over ' +
          'this tag, run before the publish and handed to it alone; issue #1504: a dispatched tag reaches the publish only through the ' +
          'same resolve step, the same condition and the same gate, so the dispatch path is not a second graph',
      );
    }

    if (BUN_YAML === null) {
      reportYamlHole('CUR120_CI_AND_RELEASE_CALL_ONE_REUSABLE_SHARDED_GATE_AND_NO_OTHER_WORKFLOW_DEFINES_THE_SHARDS');
    } else {
      const standing = oneGateFaults(texts);
      const ciText = texts['ci.yml'] ?? '';
      const shardsText = texts[SHARDS_FILE] ?? '';
      const secondMatrix =
        '\n  shard-again:\n    runs-on: ubuntu-latest\n    strategy:\n      matrix:\n        shard: [1, 2]\n    steps:\n' +
        '      - run: bun run selftest\n        env:\n          RIGC_SHARD: ${{ matrix.shard }}/2\n';
      const { probes, cases } = runPlants(
        standing,
        [
          { what: 'ci.yml grows a shard matrix of its own', edit: { 'ci.yml': `${ciText.trimEnd()}\n${secondMatrix}` } },
          { what: 'release.yml merges shards itself', edit: { 'release.yml': once(releaseText, '      - name: Publish to npm\n', '      - run: bun selftest.ts --merge shard-1.json\n      - name: Publish to npm\n') } },
          { what: 'release.yml calls another workflow', edit: { 'release.yml': once(releaseText, `uses: ${SHARDS_USES}`, 'uses: ./.github/workflows/selftest-release.yml') } },
          { what: "ci.yml's test stops reading the merge's verdict", edit: { 'ci.yml': once(ciText, 'needs.selftest.outputs.verdict', 'needs.selftest.result') } },
          { what: 'the merge stops writing the tally', edit: { [SHARDS_FILE]: once(shardsText, ' --tally-out "$RUNNER_TEMP/selftest_merged.json"', '') } },
          { what: 'the shard job is renamed', edit: { [SHARDS_FILE]: once(shardsText, '    name: shard ${{ matrix.shard }}\n', '    name: part ${{ matrix.shard }}\n') }, quiet: true },
        ],
        oneGateFaults,
      );
      const held = standing.length === 0 && probes.length === 0;
      say(
        'CUR120_CI_AND_RELEASE_CALL_ONE_REUSABLE_SHARDED_GATE_AND_NO_OTHER_WORKFLOW_DEFINES_THE_SHARDS',
        held,
        probeDetail(
          held,
          [...standing, ...probes],
          `${SHARDS_FILE} is a reusable workflow holding the one shard matrix and the one \`--merge\`, which writes the tally it ` +
            `uploads as "${TALLY_ARTIFACT}"; ci.yml and release.yml each call it once and no workflow among ${Object.keys(texts).length} ` +
            `runs a shard or a merge of its own, and ci.yml's \`test\` reads the merge's verdict — over ${cases.length} plant(s): ${cases.join('; ')}`,
        ),
        'issue #1249: release.yml reading a gate that is not the one CI reads would be #1003 again — two environments, one name',
      );
    }

    // --- CUR131: a cut tag is republished by dispatch through the same gate (issue #1504)
    //
    // 🚨 A cut whose publish failed after the tag could not be recovered by a
    // re-run: release-please no longer reports `release_created` for a tag it
    // has cut, so `gate` and `publish` were skipped and the registry kept the
    // previous version, while a publish by hand loses provenance and the
    // trusted publisher names release.yml. The repair is a `tag` dispatch whose
    // resolve step in `plan` feeds the same `gate` and the same `publish` —
    // CUR119 holds that it is the same graph; this holds the dispatch itself:
    // the two optional inputs, `plan`'s `if`, release-please under a push, the
    // resolve step right after it naming each refusal in order, the two
    // registry reads under package.json's name, the inputs reaching the script
    // through env alone, every reader of the tag reading the resolved one, the
    // confirmation on a `version` alone, and RELEASING.md saying all of it.
    // Ported from the sibling repository's control for the same repair, onto
    // this repository's three-job graph. Issue #1509 added the prerelease
    // refusal: the publish steps pass no `--tag`, so a prerelease dispatched
    // above the registry's latest would otherwise go out under latest.
    if (BUN_YAML === null) {
      reportYamlHole('CUR131_A_CUT_TAG_IS_REPUBLISHED_BY_DISPATCH_THROUGH_THE_SAME_GATE_AND_PUBLISH_AND_EACH_REFUSAL_IS_NAMED');
    } else {
      const REFUSALS = ['RELEASE_DISPATCH_INPUT', 'RELEASE_TAG_FORM', 'RELEASE_TAG_PRERELEASE', 'RELEASE_TAG_UNRELEASED', 'RELEASE_ALREADY_PUBLISHED', 'RELEASE_TAG_BELOW_LATEST'] as const;
      const UNPUBLISHED_CUT_LINE = 'a release-please failure after the tag leaves a version unpublished; the next cut carries it, or the tag is republished by dispatch';
      const DISPATCH = 'gh workflow run release.yml --ref vX.Y.Z -f tag=';
      const PLAN_TERMS = ["github.event_name == 'push'", "inputs.tag != ''", "inputs.version == ''"];
      const CONFIRM_TERMS = ["github.event_name == 'workflow_dispatch'", "inputs.version != ''", "inputs.tag == ''"];
      interface DispatchInput {
        required?: boolean;
        type?: string;
      }
      const sameTerms = (condition: string | undefined, op: '&&' | '||', want: readonly string[]): boolean => {
        const terms = termsOf(condition, op);
        return terms !== null && terms.length === want.length && want.every((term) => terms.includes(term));
      };
      const republishFaults = (yml: string, doc: string): string[] => {
        let wf: GraphWorkflow;
        try {
          wf = readYaml(yml) as GraphWorkflow;
        } catch (error) {
          return [`release.yml does not parse as YAML: ${error instanceof Error ? error.message : String(error)}`];
        }
        const faults: string[] = [];
        const dispatch = wf.on?.workflow_dispatch as { inputs?: Record<string, DispatchInput> } | null | undefined;
        const inputs = dispatch?.inputs ?? {};
        for (const name of ['tag', 'version']) {
          const input = inputs[name];
          if (input === undefined) faults.push(`release.yml: workflow_dispatch has no \`${name}\` input`);
          else if (input.required !== false || input.type !== 'string') {
            faults.push(`release.yml: the dispatch input \`${name}\` is ${JSON.stringify({ required: input.required ?? null, type: input.type ?? null })}, where an optional string is what lets a dispatch give the other input alone`);
          }
        }
        const jobs = Object.entries(wf.jobs ?? {});
        const planEntry = jobs.find(([, job]) => (job.steps ?? []).some((step) => /release-please/.test(step.uses ?? '')));
        const gateEntry = jobs.find(([, job]) => job.uses === SHARDS_USES);
        const publishEntry = jobs.find(([, job]) => (job.steps ?? []).some((step) => /\bnpm publish\b/.test(step.run ?? '')));
        if (planEntry === undefined || gateEntry === undefined || publishEntry === undefined) {
          faults.push(`release.yml: no ${planEntry === undefined ? 'release-please job' : gateEntry === undefined ? `job calling ${SHARDS_FILE}` : 'job running `npm publish`'}, so the republish path has nothing to read`);
          return faults;
        }
        const [planName, planJob] = planEntry;
        if (!sameTerms(planJob.if, '||', PLAN_TERMS)) {
          faults.push(`release.yml: the plan job "${planName}" runs under ${JSON.stringify(planJob.if ?? null)}, where ${PLAN_TERMS.join(' || ')} admits a push and every dispatch but a confirmation alone`);
        }
        const steps = planJob.steps ?? [];
        const please = steps.findIndex((step) => /release-please/.test(step.uses ?? ''));
        if (steps[please].if !== "${{ github.event_name == 'push' }}") faults.push(`release.yml: release-please runs under ${JSON.stringify(steps[please].if ?? null)}, so a dispatch could cut a tag or a release`);
        const target = steps.findIndex((step) => step.id === 'target');
        if (target === -1) faults.push(`release.yml: the plan job "${planName}" has no step with id \`target\` resolving the tag to publish`);
        else {
          const step = steps[target];
          if (target !== please + 1) faults.push(`release.yml: the resolve step is step ${target + 1} of "${planName}", where it follows release-please directly`);
          if (step.if !== undefined) faults.push(`release.yml: the resolve step runs under ${JSON.stringify(step.if)}, so a dispatch could skip its refusals`);
          const run = step.run ?? '';
          const at = REFUSALS.map((code) => run.indexOf(`::error::${code}:`));
          REFUSALS.forEach((code, k) => {
            if (at[k] === -1) faults.push(`release.yml: the resolve step never prints \`::error::${code}:\`, so that refusal is not made by name`);
          });
          const found = REFUSALS.filter((_, k) => at[k] !== -1);
          const order = [...found].sort((a, b) => at[REFUSALS.indexOf(a)] - at[REFUSALS.indexOf(b)]);
          if (order.join() !== found.join()) faults.push(`release.yml: the resolve step refuses in the order ${order.join(', ')}, out of order against ${REFUSALS.join(', ')} — prerelease after the form check, which admits the spelling so the tag can be named, and before the GitHub-release read; below-latest after already-published, so a version already served is not named as below latest`);
          if (!run.includes(`npm view "${packageName}" version`)) faults.push(`release.yml: the resolve step does not read \`npm view "${packageName}" version\`, so a tag below the registry's latest is not refused`);
          if (!run.includes(`npm view "${packageName}@$version" version`)) faults.push(`release.yml: the resolve step does not read \`npm view "${packageName}@$version" version\`, so a version the registry serves is not refused under the package's name`);
          for (const [variable, source] of [['INPUT_TAG', '${{ inputs.tag }}'], ['INPUT_VERSION', '${{ inputs.version }}']] as const) {
            if (step.env?.[variable] !== source) faults.push(`release.yml: the resolve step's env does not set ${variable} to ${source}`);
          }
        }
        for (const output of ['publish', 'tag']) {
          if (planJob.outputs?.[output] !== `\${{ steps.target.outputs.${output} }}`) faults.push(`release.yml: the plan job exports \`${output}\` as ${JSON.stringify(planJob.outputs?.[output] ?? null)}, not the resolve step's`);
        }
        const condition = `\${{ needs.${planName}.outputs.publish == 'true' }}`;
        const tag = `\${{ needs.${planName}.outputs.tag }}`;
        const ref = `\${{ needs.${planName}.outputs.sha || needs.${planName}.outputs.tag }}`;
        for (const [name, job] of [gateEntry, publishEntry]) {
          if (job.if !== condition) faults.push(`release.yml: job "${name}" runs under ${JSON.stringify(job.if ?? null)}, not ${condition}`);
        }
        if (gateEntry[1].with?.ref !== ref) faults.push(`release.yml: job "${gateEntry[0]}" calls ${SHARDS_FILE} with ref ${JSON.stringify(gateEntry[1].with?.ref ?? null)}, not ${ref}`);
        const publishSteps = publishEntry[1].steps ?? [];
        const checkout = publishSteps.find((step) => /^actions\/checkout@/.test(step.uses ?? ''));
        if (checkout?.with?.ref !== ref) faults.push(`release.yml: job "${publishEntry[0]}" checks out ${JSON.stringify(checkout?.with?.ref ?? null)}, not ${ref}`);
        const confirmation = publishSteps.find((step) => runLines(step).some((line) => line.startsWith('bun run smoke')));
        if (confirmation?.env?.TAG_NAME !== tag) faults.push(`release.yml: the confirmation in job "${publishEntry[0]}" reads TAG_NAME ${JSON.stringify(confirmation?.env?.TAG_NAME ?? null)}, not ${tag}`);
        for (const [name, job] of jobs) {
          if (name !== planName && /outputs\.(?:release_created|tag_name)\b/.test(JSON.stringify(job).replace(/steps\.release\.outputs/g, ''))) {
            faults.push(`release.yml: job "${name}" reads ${planName}'s release_created or tag_name, which a dispatch never sets; it reads the resolved \`publish\` and \`tag\``);
          }
        }
        const confirms = jobs.filter(([name, job]) => name !== publishEntry[0] && (job.steps ?? []).some((step) => runLines(step).some((line) => line.startsWith('bun run smoke'))));
        if (confirms.length !== 1) faults.push(`release.yml: ${confirms.length} job(s) besides "${publishEntry[0]}" confirm, where the confirm job alone does`);
        for (const [name, job] of confirms) {
          if (!sameTerms(job.if, '&&', CONFIRM_TERMS)) faults.push(`release.yml: the confirm job "${name}" runs under ${JSON.stringify(job.if ?? null)}, where ${CONFIRM_TERMS.join(' && ')} keeps it to a \`version\` dispatch alone`);
        }
        for (const [name, job] of jobs) {
          for (const step of job.steps ?? []) {
            if (/\$\{\{[^}]*\binputs\./.test(step.run ?? '')) faults.push(`release.yml: "${step.name ?? step.uses ?? '(unnamed)'}" in job "${name}" interpolates an input into its script; inputs reach a run block through env only`);
          }
        }
        if (!doc.includes(UNPUBLISHED_CUT_LINE)) faults.push(`RELEASING.md does not carry "${UNPUBLISHED_CUT_LINE}"`);
        if (!doc.includes(DISPATCH)) faults.push(`RELEASING.md does not give the dispatch \`${DISPATCH}\``);
        for (const code of REFUSALS) if (!doc.includes(code)) faults.push(`RELEASING.md does not name the refusal ${code}`);
        return faults;
      };

      const releasingText = readFileSync(join(root, 'RELEASING.md'), 'utf8');
      const standing = republishFaults(releaseText, releasingText);
      /** `from` → `to` where `from` occurs exactly once, or null: an ambiguous anchor plants nothing it can name. */
      const one = (text: string, from: string, to: string): string | null => (text.split(from).length === 2 ? text.replace(from, to) : null);
      /** The two refusal codes' `::error::` lines exchanged in place, or null when either is not there exactly once. */
      const swapped = (first: string, second: string): string | null => {
        const a = `::error::${first}:`;
        const b = `::error::${second}:`;
        const marked = one(releaseText, a, '\u0000');
        const moved = marked === null ? null : one(marked, b, a);
        return moved === null ? null : moved.replace('\u0000', b);
      };
      const condition = "    if: ${{ needs.plan.outputs.publish == 'true' }}\n";
      const plants: Array<{ what: string; yml: string | null; doc?: string | null; want: string; quiet?: boolean }> = [
        { what: 'the tag input dropped', yml: one(releaseText, '      tag:\n        description:', '      tagged:\n        description:'), want: 'no `tag` input' },
        { what: 'the version input required again', yml: one(releaseText, '(leave tag empty)\n        required: false', '(leave tag empty)\n        required: true'), want: 'the dispatch input `version`' },
        { what: 'the plan job runs on a push only', yml: one(releaseText, "    if: ${{ github.event_name == 'push' || inputs.tag != '' || inputs.version == '' }}\n", "    if: ${{ github.event_name == 'push' }}\n"), want: 'the plan job "plan" runs under' },
        { what: 'release-please runs on a dispatch', yml: one(releaseText, "        id: release\n        if: ${{ github.event_name == 'push' }}\n", '        id: release\n'), want: 'so a dispatch could cut' },
        { what: 'the resolve step skipped on a dispatch', yml: one(releaseText, '        id: target\n', "        id: target\n        if: ${{ github.event_name == 'push' }}\n"), want: 'could skip its refusals' },
        { what: 'the gate keyed on release-please again', yml: one(releaseText, `    needs: plan\n${condition}`, "    needs: plan\n    if: ${{ github.event_name == 'push' && needs.plan.outputs.release_created == 'true' }}\n"), want: 'job "gate" runs under' },
        { what: 'the publish admits any dispatch', yml: one(releaseText, `    needs: [plan, gate]\n${condition}`, "    needs: [plan, gate]\n    if: ${{ needs.plan.outputs.publish == 'true' || github.event_name == 'workflow_dispatch' }}\n"), want: 'job "publish" runs under' },
        { what: 'the gate reads the cut tag again', yml: one(releaseText, '\n      ref: ${{ needs.plan.outputs.sha || needs.plan.outputs.tag }}\n', '\n      ref: ${{ needs.plan.outputs.tag_name }}\n'), want: 'with ref' },
        { what: 'the publish checks out the cut tag again', yml: one(releaseText, '\n          ref: ${{ needs.plan.outputs.sha || needs.plan.outputs.tag }}\n', '\n          ref: ${{ needs.plan.outputs.tag_name }}\n'), want: 'checks out' },
        { what: 'the confirmation reads the cut tag again', yml: one(releaseText, 'TAG_NAME: ${{ needs.plan.outputs.tag }}', 'TAG_NAME: ${{ needs.plan.outputs.tag_name }}'), want: 'reads TAG_NAME' },
        { what: 'plan exports the cut tag', yml: one(releaseText, '      tag: ${{ steps.target.outputs.tag }}\n', '      tag: ${{ steps.release.outputs.tag_name }}\n'), want: 'exports `tag`' },
        { what: 'the dispatch-input refusal unnamed', yml: releaseText.includes('::error::RELEASE_DISPATCH_INPUT:') ? releaseText.split('::error::RELEASE_DISPATCH_INPUT:').join('::error::') : null, want: 'RELEASE_DISPATCH_INPUT' },
        { what: 'the form refusal unnamed', yml: one(releaseText, '::error::RELEASE_TAG_FORM:', '::error::'), want: 'RELEASE_TAG_FORM' },
        { what: 'the prerelease refusal unnamed', yml: one(releaseText, '::error::RELEASE_TAG_PRERELEASE:', '::error::'), want: 'RELEASE_TAG_PRERELEASE' },
        { what: 'the form and prerelease refusals swapped', yml: swapped('RELEASE_TAG_FORM', 'RELEASE_TAG_PRERELEASE'), want: 'out of order' },
        { what: 'the unreleased and already-published refusals swapped', yml: swapped('RELEASE_TAG_UNRELEASED', 'RELEASE_ALREADY_PUBLISHED'), want: 'out of order' },
        { what: 'the latest read dropped', yml: one(releaseText, `npm view "${packageName}" version`, `npm view "${packageName}" dist-tags`), want: "below the registry's latest is not refused" },
        { what: 'the served read under another name', yml: one(releaseText, `npm view "${packageName}@$version" version`, 'npm view "other@$version" version'), want: "under the package's name" },
        { what: 'the tag input fed from the version', yml: one(releaseText, 'INPUT_TAG: ${{ inputs.tag }}', 'INPUT_TAG: ${{ inputs.version }}'), want: 'does not set INPUT_TAG' },
        { what: 'an input interpolated into the script', yml: one(releaseText, 'version="${INPUT_TAG#v}"', 'version="${{ inputs.tag }}"'), want: 'interpolates an input' },
        { what: 'the confirm job runs on a tag dispatch', yml: one(releaseText, " && inputs.version != '' && inputs.tag == '' }}", ' }}'), want: 'the confirm job "confirm" runs under' },
        { what: "RELEASING.md drops the unpublished-cut line", yml: releaseText, doc: one(releasingText, UNPUBLISHED_CUT_LINE, "a failure after the tag is somebody else's"), want: 'RELEASING.md does not carry' },
        { what: 'RELEASING.md drops the dispatch command', yml: releaseText, doc: one(releasingText, `${DISPATCH}vX.Y.Z`, 'gh workflow run release.yml'), want: 'does not give the dispatch' },
        { what: 'RELEASING.md drops a refusal', yml: releaseText, doc: releasingText.includes('RELEASE_TAG_UNRELEASED') ? releasingText.split('RELEASE_TAG_UNRELEASED').join('RELEASE_TAG_UNKNOWN') : null, want: 'does not name the refusal RELEASE_TAG_UNRELEASED' },
        { what: 'the resolve step renamed', yml: one(releaseText, '      - name: Resolve the tag to publish\n', '      - name: Pick a tag\n'), want: '', quiet: true },
      ];
      const probes: string[] = [];
      const cases: string[] = [];
      for (const plant of plants) {
        const doc = plant.doc === undefined ? releasingText : plant.doc;
        if (plant.yml === null || doc === null) {
          probes.push(`"${plant.what}": the edit found nothing to change, so this plant was never made`);
          continue;
        }
        const raised = raisedBy(republishFaults(plant.yml, doc), { was: standing });
        if (plant.quiet === true) {
          if (raised.length > 0) probes.push(`"${plant.what}" changes nothing this gate is about and ${raised.length} fault(s) fired: ${raised[0].slice(0, 160)}`);
          cases.push(`${plant.what} -> quiet`);
          continue;
        }
        if (!raised.some((fault) => fault.includes(plant.want))) {
          probes.push(`"${plant.what}" was planted and this gate did not fire the fault naming "${plant.want}" (raised: ${raised.join(' | ').slice(0, 200) || 'none'})`);
          continue;
        }
        cases.push(`${plant.what} -> named`);
      }
      const held = standing.length === 0 && probes.length === 0;
      say(
        'CUR131_A_CUT_TAG_IS_REPUBLISHED_BY_DISPATCH_THROUGH_THE_SAME_GATE_AND_PUBLISH_AND_EACH_REFUSAL_IS_NAMED',
        held,
        probeDetail(
          held,
          [...standing, ...probes],
          'release.yml takes an optional `tag` beside an optional `version`, runs plan on a push or any dispatch but a confirmation alone, ' +
            `release-please on a push only, and the resolve step right after it naming ${REFUSALS.join(', ')} in that order with both ` +
            `\`npm view\` reads under ${packageName} and the inputs through env; gate and publish run under the resolved condition and every ` +
            'reader of the tag reads the resolved one, the confirm job runs on a `version` alone, no script interpolates an input, and ' +
            `RELEASING.md carries the line, the dispatch and every refusal — over ${plants.length} plant(s): ${cases.join('; ')}`,
        ),
        'issue #1504: a cut whose publish failed after the tag could not be recovered by a re-run, because release-please no longer ' +
          'reports a release for a tag it cut; the tag is published by a dispatch through the same resolve step, the same gate and the ' +
          'same publish in this file, so the trusted publisher and provenance hold and nothing reaches the publish past the gate',
      );
    }

    // --- CUR132: one concurrency group for the runs that may publish (issue #1510)
    //
    // 🚨 The group was keyed on the event name, so a push cut ran in one group
    // and every dispatch in another: a `tag` republish and a push cut never
    // queued behind each other — two runs could reach `publish` together —
    // while a `version` confirmation, which publishes nothing, queued behind a
    // republish. The opposite of what each needs, and nothing read the group.
    // This evaluates the group expression as GitHub would, over a push, a `tag`
    // dispatch from the default branch and from another ref, and a `version`
    // dispatch, rather than matching its text: a rewrite that still reads the
    // same passes, and one the evaluator cannot read is refused by name.
    if (BUN_YAML === null) {
      reportYamlHole('CUR132_A_TAG_REPUBLISH_AND_A_PUSH_CUT_SHARE_ONE_CONCURRENCY_GROUP_AND_A_CONFIRMATION_DOES_NOT');
    } else {
      type ExprValue = string | boolean | null;
      interface RunContext {
        label: string;
        values: Record<string, ExprValue>;
      }
      /** The paths the group may read; any other name is refused rather than read as null. */
      const KNOWN_PATHS = ['github.ref', 'github.event_name', 'inputs.tag', 'inputs.version'] as const;
      const runContext = (label: string, event: string, ref: string, tag: string | null, version: string | null): RunContext => ({
        label,
        values: { 'github.ref': ref, 'github.event_name': event, 'inputs.tag': tag, 'inputs.version': version },
      });
      // A push carries no inputs, so GitHub reads them as null there; a dispatch reads an omitted string input as ''.
      const PUSH = runContext('a push cut', 'push', 'refs/heads/main', null, null);
      const PUBLISHERS: readonly RunContext[] = [
        PUSH,
        runContext('a `tag` dispatch', 'workflow_dispatch', 'refs/heads/main', 'v1.2.3', ''),
        runContext('a `tag` dispatch from another ref', 'workflow_dispatch', 'refs/heads/other', 'v1.2.3', ''),
      ];
      const CONFIRMATION = runContext('a `version` dispatch', 'workflow_dispatch', 'refs/heads/main', '', '1.2.3');
      const truthy = (value: ExprValue): boolean => value !== null && value !== false && value !== '';
      /** GitHub's coercion when two operands differ in type: both to numbers. */
      const toNumber = (value: ExprValue): number =>
        value === null ? 0 : typeof value === 'boolean' ? (value ? 1 : 0) : value.trim() === '' ? 0 : Number(value);
      /** `==` as GitHub evaluates it: strings compare ignoring case, other mixed types compare as numbers. */
      const equal = (a: ExprValue, b: ExprValue): boolean => {
        if (typeof a === 'string' && typeof b === 'string') return a.toLowerCase() === b.toLowerCase();
        if (typeof a === typeof b) return a === b;
        return toNumber(a) === toNumber(b);
      };
      /** One `${{ }}` body, evaluated for one run: string literals, the four paths, `==`, `&&`, `||` and parentheses — nothing else. */
      const evaluate = (body: string, run: RunContext): ExprValue => {
        const tokens: string[] = [];
        const lexer = /\s*(?:('(?:[^']|'')*')|(==|&&|\|\||\(|\))|([A-Za-z_][A-Za-z0-9_.-]*)|(\S))/gy;
        // Every alternative consumes a character, and `(\S)` takes any the others do not, so only trailing space ends the scan early.
        for (let m = lexer.exec(body); m !== null; m = lexer.exec(body)) {
          const [, literal, operator, path, other] = m;
          if (other !== undefined) throw new Error(`\`${other}\`, a token this evaluator does not read`);
          if (path !== undefined && !(KNOWN_PATHS as readonly string[]).includes(path)) {
            throw new Error(`\`${path}\`, a name this evaluator does not read (it reads ${KNOWN_PATHS.join(', ')})`);
          }
          tokens.push(literal ?? operator ?? path);
        }
        let at = 0;
        const fail = (what: string): never => {
          throw new Error(`${what} at token ${at + 1} of \`${body.trim()}\``);
        };
        const primary = (): ExprValue => {
          const token = tokens[at++];
          if (token === undefined) return fail('an operand missing');
          if (token === '(') {
            const value = or();
            if (tokens[at++] !== ')') fail('an unclosed parenthesis');
            return value;
          }
          if (token.startsWith("'")) return token.slice(1, -1).replace(/''/g, "'");
          if ((KNOWN_PATHS as readonly string[]).includes(token)) return run.values[token] ?? null;
          return fail(`\`${token}\` where an operand belongs`);
        };
        const comparison = (): ExprValue => {
          let left = primary();
          while (tokens[at] === '==') {
            at++;
            left = equal(left, primary());
          }
          return left;
        };
        const and = (): ExprValue => {
          let left = comparison();
          while (tokens[at] === '&&') {
            at++;
            const right = comparison();
            left = truthy(left) ? right : left;
          }
          return left;
        };
        const or = (): ExprValue => {
          let left = and();
          while (tokens[at] === '||') {
            at++;
            const right = and();
            left = truthy(left) ? left : right;
          }
          return left;
        };
        const value = or();
        if (at !== tokens.length) fail(`\`${tokens[at]}\` left over`);
        return value;
      };
      /** The group string for one run: literal text, and each `${{ }}` piece evaluated and joined. */
      const groupFor = (template: string, run: RunContext): string =>
        template.replace(/\$\{\{([\s\S]*?)\}\}/g, (_, body: string) => {
          const value = evaluate(body, run);
          return value === null ? '' : String(value);
        });
      const concurrencyFaults = (yml: string): string[] => {
        let wf: { concurrency?: unknown };
        try {
          wf = readYaml(yml) as { concurrency?: unknown };
        } catch (error) {
          return [`release.yml does not parse as YAML: ${error instanceof Error ? error.message : String(error)}`];
        }
        const block = wf.concurrency;
        if (block === null || typeof block !== 'object') return [`release.yml: the workflow's \`concurrency\` is ${JSON.stringify(block ?? null)}, not a block with a group and cancel-in-progress`];
        const { group, 'cancel-in-progress': cancel } = block as { group?: unknown; 'cancel-in-progress'?: unknown };
        const faults: string[] = [];
        if (cancel !== false) faults.push(`release.yml: concurrency.cancel-in-progress is ${JSON.stringify(cancel ?? null)}, where false lets a run queued behind a publish wait instead of cancelling it`);
        if (typeof group !== 'string') return [...faults, `release.yml: concurrency.group is ${JSON.stringify(group ?? null)}, not a string`];
        let publishers: string[];
        let confirmation: string;
        try {
          publishers = PUBLISHERS.map((run) => groupFor(group, run));
          confirmation = groupFor(group, CONFIRMATION);
        } catch (error) {
          return [...faults, `release.yml: concurrency.group is refused by the evaluator: it holds ${error instanceof Error ? error.message : String(error)}`];
        }
        PUBLISHERS.forEach((run, k) => {
          if (publishers[k] !== publishers[0]) faults.push(`release.yml: ${run.label} runs in group "${publishers[k]}" and ${PUSH.label} in "${publishers[0]}", so the two can reach publish together`);
        });
        if (confirmation === publishers[0]) faults.push(`release.yml: ${CONFIRMATION.label} runs in "${confirmation}", the publishers' own group, so a confirmation queues behind a release`);
        return faults;
      };

      const standing = concurrencyFaults(releaseText);
      const groupLine = /^ {2}group: .*$/m.exec(releaseText)?.[0] ?? null;
      const one = (text: string, from: string | null, to: string): string | null => (from !== null && text.split(from).length === 2 ? text.replace(from, to) : null);
      const plants: Array<{ what: string; yml: string | null; want: string; quiet?: boolean }> = [
        { what: 'the group keyed on the event name again', yml: one(releaseText, groupLine, '  group: release-${{ github.ref }}-${{ github.event_name }}'), want: 'a `tag` dispatch runs in group' },
        { what: 'the group with no event term', yml: one(releaseText, groupLine, '  group: release-${{ github.ref }}'), want: 'the publishers\' own group' },
        { what: 'the ref back in the group', yml: one(releaseText, groupLine, `${groupLine ?? ''}-\${{ github.ref }}`), want: 'a `tag` dispatch from another ref runs in group' },
        { what: 'cancel-in-progress true', yml: one(releaseText, '  cancel-in-progress: false\n', '  cancel-in-progress: true\n'), want: 'cancel-in-progress is true' },
        {
          what: 'a function the evaluator does not read',
          yml: one(releaseText, groupLine, (groupLine ?? '').replace("github.event_name == 'workflow_dispatch'", "startsWith(github.event_name, 'workflow')")),
          want: '`startsWith`, a name this evaluator does not read',
        },
        { what: 'an operator the evaluator does not read', yml: one(releaseText, groupLine, (groupLine ?? '').replace("inputs.tag == ''", "inputs.tag != ''")), want: 'refused by the evaluator' },
        { what: 'the parentheses dropped', yml: one(releaseText, groupLine, (groupLine ?? '').replace('(', '').replace(')', '')), want: '', quiet: true },
      ];
      const probes: string[] = [];
      const cases: string[] = [];
      for (const plant of plants) {
        if (plant.yml === null || plant.yml === releaseText) {
          probes.push(`"${plant.what}": the edit found nothing to change, so this plant was never made`);
          continue;
        }
        const raised = raisedBy(concurrencyFaults(plant.yml), { was: standing });
        if (plant.quiet === true) {
          if (raised.length > 0) probes.push(`"${plant.what}" reads the same and ${raised.length} fault(s) fired: ${raised[0].slice(0, 160)}`);
          cases.push(`${plant.what} -> quiet`);
          continue;
        }
        if (!raised.some((fault) => fault.includes(plant.want))) {
          probes.push(`"${plant.what}" was planted and this gate did not fire the fault naming "${plant.want}" (raised: ${raised.join(' | ').slice(0, 200) || 'none'})`);
          continue;
        }
        cases.push(`${plant.what} -> named`);
      }
      const evaluated = ((): string => {
        try {
          const group = (readYaml(releaseText) as { concurrency?: { group?: string } }).concurrency?.group ?? '';
          return [...PUBLISHERS, CONFIRMATION].map((run) => `${run.label} = "${groupFor(group, run)}"`).join(', ');
        } catch {
          return 'not evaluated';
        }
      })();
      const held = standing.length === 0 && probes.length === 0;
      say(
        'CUR132_A_TAG_REPUBLISH_AND_A_PUSH_CUT_SHARE_ONE_CONCURRENCY_GROUP_AND_A_CONFIRMATION_DOES_NOT',
        held,
        probeDetail(
          held,
          [...standing, ...probes],
          `release.yml's concurrency group, evaluated: ${evaluated}; cancel-in-progress is false — over ${plants.length} plant(s): ${cases.join('; ')}`,
        ),
        'issue #1510: keyed on the event name, a republish and a push cut never queued behind each other while a confirmation queued ' +
          'behind a republish; every run that may publish shares one group and a confirmation keeps its own',
      );
    }

    // --- CUR133: dispatched provenance names the checked-out commit (#1542)
    // Execute the workflow's own guard and publish bodies with git, npm and
    // bun replaced by closed mocks. No registry, token or Git operation runs.
    {
      const id = 'CUR133_DISPATCH_PROVENANCE_REFUSES_A_DIFFERENT_SHA_BEFORE_EVERY_PUBLISH_AND_LEAVES_PUSH_UNCHANGED';
      if (BUN_YAML === null) {
        reportYamlHole(id);
      } else {
        interface ProvenanceStep {
          name?: string;
          uses?: string;
          run?: string;
          if?: string;
          'continue-on-error'?: boolean | string;
          id?: string;
          with?: Record<string, string>;
        }
        interface ProvenanceWorkflow {
          jobs?: Record<string, { steps?: ProvenanceStep[]; with?: Record<string, string>; outputs?: Record<string, string> }>;
        }
        const rule = 'PROVENANCE_SHA_MISMATCH';
        const mock = mkdtempSync(join(harnessTemp(), 'rigc-provenance-'));
        const bin = join(mock, 'bin');
        mkdirSync(bin);
        const trace = join(mock, 'calls.txt');
        const checkedOut = '1'.repeat(40);
        const different = '2'.repeat(40);
        const bodies: Record<string, string> = {
          git: 'printf "git %s\\n" "$*" >> "$MOCK_TRACE"\n[ "$*" = "rev-parse HEAD" ] || exit 91\nprintf "%s\\n" "$MOCK_HEAD"\n',
          gh: 'printf "gh %s\\n" "$*" >> "$MOCK_TRACE"\nif [ "$1" = api ]; then\n  case "$*" in "api repos/$REPO/commits/refs%2Ftags%2F$CUT_TAG --jq .sha") printf "%s\\n" "$MOCK_COMMIT";; "api repos/$REPO/commits/tags%2F$CUT_TAG --jq .sha") if [ "$MOCK_KIND" = tag ]; then printf "HTTP 422: No commit found for SHA: tags/%s\\n" "$CUT_TAG" >&2; exit 1; fi; printf "%s\\n" "$MOCK_COMMIT";; "api repos/$REPO/git/ref/tags/$CUT_TAG --jq .sha") if [ "$MOCK_KIND" = tag ]; then printf "%s\\n" "$MOCK_OBJECT"; else printf "%s\\n" "$MOCK_COMMIT"; fi;; *) exit 94;; esac\n  exit "$MOCK_API_EXIT"\nfi\n[ "$*" = "release view $INPUT_TAG --repo mock/core" ] || exit 95\nexit "$MOCK_RELEASE_EXIT"\n',
          npm: 'printf "npm %s\\n" "$*" >> "$MOCK_TRACE"\nif [ "$1" = publish ]; then exit 0; fi\n[ "$1" = view ] && [ "$3" = version ] || exit 92\ncase "$2" in rig-c@*) [ -n "$MOCK_SERVED" ] || exit 1; printf "%s\\n" "$MOCK_SERVED";; rig-c) printf "%s\\n" "$MOCK_LATEST";; *) exit 96;; esac\n',
          bun: 'printf "bun %s\\n" "$*" >> "$MOCK_TRACE"\n[ "$1" = scripts/alias_tarball.ts ] && [ "$2" = pack ] || exit 93\nprintf "mock-alias.tgz\\n"\n',
        };
        for (const [name, body] of Object.entries(bodies)) {
          const file = join(bin, name);
          writeFileSync(file, `#!/bin/bash\nset -euo pipefail\n${body}`);
          chmodSync(file, 0o755);
        }
        // grep and the JS runtime execute only the extracted dispatch spelling/semver
        // logic. All service commands are stubs and the child inherits no credentials.
        symlinkSync('/usr/bin/grep', join(bin, 'grep'));
        symlinkSync(process.execPath, join(bin, 'node'));
        const inspectPlan = (wf: ProvenanceWorkflow, steps: ProvenanceStep[]): { faults: string[]; rows: string[] } => {
          const faults: string[] = [];
          const rows: string[] = [];
          const plan = wf.jobs?.plan;
          const target = plan?.steps?.find((step) => step.id === 'target');
          if (target?.run === undefined) return { faults: ['plan has no executable target body'], rows };
          const pinned = '${{ needs.plan.outputs.sha || needs.plan.outputs.tag }}';
          if (plan?.outputs?.sha !== '${{ steps.target.outputs.sha }}') faults.push('plan must export the verified SHA');
          if (wf.jobs?.gate?.with?.ref !== pinned) faults.push('gate must consume the verified push SHA, with tag fallback only for dispatch');
          if (steps.find((step) => /^actions\/checkout@/.test(step.uses ?? ''))?.with?.ref !== pinned) faults.push('publish checkout must consume the same verified push SHA');
          const tag = 'v1.2.3';
          // Narrow public observations supplied by a read-only API capture:
          // git/git's annotated v2.45.0 short commit ref returned 422, while
          // refs/tags resolved its commit; core's lightweight full ref also resolved.
          // The stubs model those responses; this control is no live API oracle.
          const annotated = { repo: 'git/git', cutTag: 'v2.45.0', expectedCommit: '786a3e4b8d754d2b14b1208b98eeb0a554ef19a8', object: '8be58deda2ccce7d036072ec34439f9fad88204f', refKind: 'tag' };
          const lightweight = { repo: 'rig-c/core', cutTag: 'v2.67.1', expectedCommit: 'ebf243299d5edba458726fd359e84947ded01a7b', refKind: 'commit' };
          interface Scenario {
            name: string; event?: string; created?: string; cutTag?: string; inputTag?: string; inputVersion?: string;
            commit?: string; sha?: string; apiExit?: string; releaseExit?: string; served?: string; latest?: string;
            rule?: string; noRelease?: boolean; apiReads?: number; published?: number; refKind?: string;
            repo?: string; expectedCommit?: string; object?: string;
          }
          const scenarios: Scenario[] = [
            { name: 'matching lightweight push', ...lightweight },
            { name: 'matching annotated push', ...annotated },
            { name: 'mismatching rerun retains cut tag', sha: different, rule: rule },
            { name: 'annotated object SHA is not the commit', ...annotated, sha: annotated.object, rule: rule },
            { name: 'lookup fails with plausible SHA', apiExit: '1', rule: 'RELEASE_TAG_UNRESOLVED' },
            ...['', 'null', checkedOut.slice(0, 7), 'g'.repeat(40), `${checkedOut}\n${different}`, `{"sha":"${checkedOut}"}`].map((commit) => ({ name: `invalid commit ${JSON.stringify(commit)}`, commit, rule: 'RELEASE_TAG_UNRESOLVED' })),
            { name: 'invalid cut tag', cutTag: '../heads/main', rule: 'RELEASE_TAG_UNRESOLVED', apiReads: 0 },
            ...['false', ''].map((created) => ({ name: `no release ${JSON.stringify(created)}`, created, cutTag: '', noRelease: true, apiReads: 0 })),
            { name: 'matching dispatch', event: 'workflow_dispatch', apiReads: 0 },
            { name: 'mismatched dispatch', event: 'workflow_dispatch', sha: different, rule: rule, apiReads: 0, published: 0 },
            { name: 'both dispatch inputs precede form check', event: 'workflow_dispatch', inputTag: 'bad', inputVersion: '1.2.3', rule: 'RELEASE_DISPATCH_INPUT', apiReads: 0 },
            { name: 'neither dispatch input', event: 'workflow_dispatch', inputTag: '', rule: 'RELEASE_DISPATCH_INPUT', apiReads: 0 },
            { name: 'invalid dispatch form', event: 'workflow_dispatch', inputTag: 'main', rule: 'RELEASE_TAG_FORM', apiReads: 0 },
            { name: 'prerelease precedes release lookup', event: 'workflow_dispatch', inputTag: 'v1.2.3-rc.1', releaseExit: '1', rule: 'RELEASE_TAG_PRERELEASE', apiReads: 0 },
            { name: 'unreleased precedes registry reads', event: 'workflow_dispatch', releaseExit: '1', served: '1.2.3', rule: 'RELEASE_TAG_UNRELEASED', apiReads: 0 },
            { name: 'already published precedes below latest', event: 'workflow_dispatch', served: '1.2.3', latest: '1.2.4', rule: 'RELEASE_ALREADY_PUBLISHED', apiReads: 0 },
            { name: 'below latest', event: 'workflow_dispatch', latest: '1.2.4', rule: 'RELEASE_TAG_BELOW_LATEST', apiReads: 0 },
          ];
          for (const scenario of scenarios) {
            const event = scenario.event ?? 'push';
            const expectedCommit = scenario.expectedCommit ?? checkedOut;
            const scenarioTag = scenario.cutTag ?? tag;
            const repo = scenario.repo ?? 'mock/core';
            const tagObject = scenario.object ?? '3'.repeat(40);
            const recovery = `gh workflow run release.yml --ref ${scenarioTag} -f tag=${scenarioTag}`;
            const sha = scenario.sha ?? expectedCommit;
            const outputFile = join(mock, 'outputs.txt');
            writeFileSync(outputFile, '');
            writeFileSync(trace, '');
            // The cut is a fixture that predates plan. The mock never cuts or
            // removes it; refusal must preserve it, just as a failed job does.
            const cutFile = join(mock, 'already-cut-tag.txt');
            writeFileSync(cutFile, `${scenarioTag}\n${expectedCommit}\n`);
            const env = {
              PATH: bin, MOCK_TRACE: trace, MOCK_HEAD: expectedCommit,
              MOCK_COMMIT: scenario.commit ?? expectedCommit, MOCK_API_EXIT: scenario.apiExit ?? '0', MOCK_KIND: scenario.refKind ?? 'commit', MOCK_OBJECT: tagObject,
              MOCK_RELEASE_EXIT: scenario.releaseExit ?? '0', MOCK_SERVED: scenario.served ?? '', MOCK_LATEST: scenario.latest ?? '1.2.2',
              EVENT: event, CREATED: scenario.created ?? 'true', CUT_TAG: scenario.cutTag ?? tag,
              INPUT_TAG: scenario.inputTag ?? tag, INPUT_VERSION: scenario.inputVersion ?? '',
              REPO: repo, GITHUB_SHA: sha, GITHUB_EVENT_NAME: event, GITHUB_OUTPUT: outputFile, RUNNER_TEMP: 'mock-runner-temp',
            };
            const run = (body: string) => spawnSync('/bin/bash', ['--noprofile', '--norc', '-e', '-o', 'pipefail', '-c', body], { cwd: mock, encoding: 'utf8', timeout: 5000, env });
            const resolved = run(target.run);
            const outputs = Object.fromEntries(readFileSync(outputFile, 'utf8').trim().split('\n').filter(Boolean).map((line) => line.split('=')));
            let exit = resolved.status;
            let output = `${resolved.stdout ?? ''}${resolved.stderr ?? ''}`;
            if (resolved.error !== undefined) output += String(resolved.error);
            // Follow the real publish condition only after a successful plan,
            // then execute its existing guard and all three actual publish bodies.
            if (exit === 0 && outputs.publish === 'true') {
              for (const step of steps.filter((step) => (step.run ?? '').includes(rule) || /\bnpm publish\b/.test(step.run ?? ''))) {
                const ran = run(step.run ?? '');
                exit = ran.status;
                output += `${ran.stdout ?? ''}${ran.stderr ?? ''}`;
                if (ran.error !== undefined) output += String(ran.error);
                if (exit !== 0) break;
              }
            }
            const calls = readFileSync(trace, 'utf8').trim().split('\n').filter(Boolean);
            const published = calls.filter((line) => line.startsWith('npm publish '));
            const api = calls.filter((line) => line.startsWith('gh api '));
            const wantExit = scenario.rule === undefined ? 0 : 1;
            const wantPublished = scenario.published ?? (wantExit === 0 && !scenario.noRelease ? 3 : 0);
            if (exit !== wantExit || published.length !== wantPublished) faults.push(`${scenario.name}: exit ${exit}, publishes ${published.length}, required ${wantExit}/${wantPublished}; ${JSON.stringify(output)}`);
            if (api.length !== (scenario.apiReads ?? 1) || calls.some((line) => line.startsWith('gh api ') && line !== `gh api repos/${repo}/commits/refs%2Ftags%2F${scenarioTag} --jq .sha`)) faults.push(`${scenario.name}: unexpected commits API reads ${JSON.stringify(api)}`);
            if (scenario.rule !== undefined && !output.includes(`::error::${scenario.rule}:`)) faults.push(`${scenario.name}: missing named refusal ${scenario.rule}`);
            if (event === 'push' && scenario.rule !== undefined && Object.keys(outputs).length !== 0) faults.push(`${scenario.name}: plan emitted outputs before refusal ${JSON.stringify(outputs)}`);
            if (scenario.rule === rule && (!output.includes(sha) || !output.includes(expectedCommit))) faults.push(`${scenario.name}: refusal must name both full SHAs`);
            if (event === 'push' && scenario.rule === rule && (!output.includes(recovery) || !output.includes('the tag remains cut'))) faults.push(`${scenario.name}: refusal must retain the cut and give exact recovery ${recovery}`);
            if (event === 'push' && wantExit === 0 && !scenario.noRelease && JSON.stringify(outputs) !== JSON.stringify({ publish: 'true', tag: scenarioTag, sha: expectedCommit })) faults.push(`${scenario.name}: wrong verified outputs ${JSON.stringify(outputs)}`);
            if (event === 'workflow_dispatch' && outputs.sha !== undefined) faults.push(`${scenario.name}: dispatch resolution changed to emit a SHA`);
            if (scenario.noRelease && JSON.stringify(outputs) !== JSON.stringify({ publish: 'false' })) faults.push(`${scenario.name}: no-release output changed`);
            if (readFileSync(cutFile, 'utf8') !== `${scenarioTag}\n${expectedCommit}\n`) faults.push(`${scenario.name}: cut tag changed`);
            if (published.some((line) => !line.includes('--provenance'))) faults.push(`${scenario.name}: publish lost provenance`);
            rows.push(`${scenario.name}${scenario.refKind === 'tag' ? ` (annotated object ${tagObject}, commits API ${expectedCommit})` : ''}: exit ${exit}, publishes ${published.length}/3, outputs ${JSON.stringify(outputs)}, calls ${JSON.stringify(calls)}, output ${JSON.stringify(output.trim())}`);
          }
          return { faults, rows };
        };
        const publishes = (step: ProvenanceStep): boolean => /\bnpm publish\b/.test(step.run ?? '');
        const inspect = (text: string): { faults: string[]; rows: string[] } => {
          const faults: string[] = [];
          const rows: string[] = [];
          let wf: ProvenanceWorkflow;
          try {
            wf = readYaml(text) as ProvenanceWorkflow;
          } catch (error) {
            return { faults: [`release.yml does not parse: ${String(error)}`], rows };
          }
          const jobs = Object.entries(wf.jobs ?? {}).filter(([, job]) => (job.steps ?? []).some(publishes));
          if (jobs.length !== 1) return { faults: [`${jobs.length} jobs publish, required one guarded job`], rows };
          const steps = jobs[0][1].steps ?? [];
          const guards = steps.map((step, at) => (step.run ?? '').includes(rule) ? at : -1).filter((at) => at >= 0);
          if (guards.length !== 1) return { faults: [`${guards.length} guards name ${rule}, required one`], rows };
          const guard = guards[0];
          const checkout = steps.findIndex((step) => /^actions\/checkout@/.test(step.uses ?? ''));
          const publishSteps = steps.map((step, at) => publishes(step) ? at : -1).filter((at) => at >= 0);
          if (checkout < 0 || checkout >= guard) faults.push('the provenance guard must read HEAD after checkout');
          if (publishSteps.some((at) => at <= guard)) faults.push('the provenance guard must precede every publish, canonical and aliases');
          if (steps[guard].if !== undefined || steps[guard]['continue-on-error'] !== undefined) faults.push('the provenance guard can be skipped or its failure ignored');
          const planMeasured = inspectPlan(wf, steps);
          faults.push(...planMeasured.faults);
          rows.push(...planMeasured.rows);
          const selected = steps.filter((step, at) => at === guard || publishes(step));
          const scenarios = [
            { name: 'mismatched dispatch', event: 'workflow_dispatch', sha: different, exit: 1, publish: 0, git: 1 },
            { name: 'matching dispatch', event: 'workflow_dispatch', sha: checkedOut, exit: 0, publish: publishSteps.length, git: 1 },
            { name: 'mismatched push', event: 'push', sha: different, exit: 0, publish: publishSteps.length, git: 0 },
          ];
          for (const scenario of scenarios) {
            writeFileSync(trace, '');
            let exit: number | null = 0;
            let output = '';
            for (const step of selected) {
              const ran = spawnSync('/bin/bash', ['--noprofile', '--norc', '-e', '-o', 'pipefail', '-c', step.run ?? ''], {
                cwd: mock,
                encoding: 'utf8',
                timeout: 5000,
                // PATH contains only the mocks, and env contains no inherited
                // BASH_ENV, credentials or npm configuration.
                env: { PATH: bin, MOCK_TRACE: trace, MOCK_HEAD: checkedOut, GITHUB_EVENT_NAME: scenario.event, GITHUB_SHA: scenario.sha, RUNNER_TEMP: 'mock-runner-temp' },
              });
              exit = ran.status;
              output += ran.stdout ?? '';
              output += ran.stderr ?? '';
              if (ran.error !== undefined) output += String(ran.error);
              if (exit !== 0) break;
            }
            const calls = readFileSync(trace, 'utf8').trim().split('\n').filter(Boolean);
            const published = calls.filter((line) => line.startsWith('npm publish '));
            const reads = calls.filter((line) => line.startsWith('git '));
            const named = output.includes(`::error::${rule}:`) && output.includes(scenario.sha) && output.includes(checkedOut);
            if (exit !== scenario.exit || published.length !== scenario.publish || reads.length !== scenario.git || (scenario.exit === 1 ? !named : output.includes(rule))) {
              faults.push(`${scenario.name}: exit ${exit}, publishes ${published.length}, git reads ${reads.length}, output ${JSON.stringify(output)}; required exit ${scenario.exit}, publishes ${scenario.publish}, git reads ${scenario.git}${scenario.exit === 1 ? ', named refusal with both SHAs' : ', no refusal'}`);
            }
            if (published.some((line) => !line.includes('--provenance'))) faults.push(`${scenario.name}: a publish lost --provenance`);
            rows.push(`${scenario.name}: exit ${exit}, publishes ${published.length}/${publishSteps.length}, git reads ${reads.length}, calls ${JSON.stringify(calls)}, output ${JSON.stringify(output.trim())}`);
          }
          return { faults, rows };
        };
        try {
          const standing = inspect(releaseText);
          const parsed = readYaml(releaseText) as ProvenanceWorkflow;
          const steps = Object.values(parsed.jobs ?? {}).find((job) => (job.steps ?? []).some(publishes))?.steps ?? [];
          const guardBody = steps.find((step) => (step.run ?? '').includes(rule))?.run ?? '';
          const lateGuard = readYaml(releaseText) as ProvenanceWorkflow;
          const lateSteps = Object.values(lateGuard.jobs ?? {}).find((job) => (job.steps ?? []).some(publishes))?.steps ?? [];
          const guardAt = lateSteps.findIndex((step) => (step.run ?? '').includes(rule));
          if (guardAt >= 0) {
            const [moved] = lateSteps.splice(guardAt, 1);
            lateSteps.splice(lateSteps.findIndex(publishes) + 1, 0, moved);
          }
          const planBody = parsed.jobs?.plan?.steps?.find((step) => step.id === 'target')?.run ?? '';
          const changePlan = (from: string, to: string): string | null => {
            if (planBody.split(from).length !== 2) return null;
            const changed = readYaml(releaseText) as ProvenanceWorkflow;
            const step = changed.jobs?.plan?.steps?.find((item) => item.id === 'target');
            if (step === undefined) return null;
            step.run = planBody.replace(from, to);
            return JSON.stringify(changed);
          };
          const guardDeleted = guardBody === '' ? null : releaseText.replace(guardBody.trimEnd().split('\n').map((line) => `          ${line}`).join('\n'), '          :');
          const deletionFaults: string[] = [];
          if (guardDeleted === null || guardDeleted === releaseText) deletionFaults.push('dispatch guard deletion made no edit');
          else {
            const deleted = readYaml(guardDeleted) as ProvenanceWorkflow;
            const deletedSteps = Object.values(deleted.jobs ?? {}).find((job) => (job.steps ?? []).some(publishes))?.steps ?? [];
            const originalAt = steps.findIndex((step) => step.run === guardBody);
            if (originalAt < 0 || deletedSteps[originalAt]?.run?.trim() !== ':') deletionFaults.push('deletion did not replace the intended publish dispatch guard');
            if (deleted.jobs?.plan?.steps?.find((step) => step.id === 'target')?.run !== planBody) deletionFaults.push('dispatch guard deletion changed the plan resolver');
          }
          const plants = [
            { what: 'push comparison reversed', text: changePlan('"$GITHUB_SHA" != "$tag_sha"', '"$GITHUB_SHA" = "$tag_sha"') },
            { what: 'push lookup failure ignored', text: changePlan('if ! tag_sha=', 'if tag_sha=') },
            { what: 'push accepts a short SHA', text: changePlan('^[0-9a-f]{40}$', '^[0-9a-f]{7,40}$') },
            { what: 'push uses short commit ref that rejects the observed annotated tag', text: changePlan('commits/refs%2Ftags%2F$CUT_TAG', 'commits/tags%2F$CUT_TAG') },
            { what: 'push compares a tag object from refs API', text: changePlan('commits/refs%2Ftags%2F$CUT_TAG', 'git/ref/tags/$CUT_TAG') },
            { what: 'push publishes true before comparison', text: changePlan('if [ "$GITHUB_SHA" != "$tag_sha" ]; then', 'echo "publish=true" >> "$GITHUB_OUTPUT"; if [ "$GITHUB_SHA" != "$tag_sha" ]; then') },
            { what: 'gate re-resolves mutable tag', text: releaseText.replace('      ref: ${{ needs.plan.outputs.sha || needs.plan.outputs.tag }}', '      ref: ${{ needs.plan.outputs.tag }}') },
            { what: 'checkout re-resolves mutable tag', text: releaseText.replace('          ref: ${{ needs.plan.outputs.sha || needs.plan.outputs.tag }}', '          ref: ${{ needs.plan.outputs.tag }}') },
            { what: 'recovery loses tag ref', text: changePlan('release.yml --ref $CUT_TAG -f tag=$CUT_TAG', 'release.yml -f tag=$CUT_TAG') },
            { what: 'guard deleted', text: guardDeleted },
            { what: 'guard after the canonical publish', text: guardAt < 0 ? null : JSON.stringify(lateGuard) },
            { what: 'SHA comparison reversed', text: releaseText.includes('"$GITHUB_SHA" != "$checked_out_sha"') ? releaseText.replace('"$GITHUB_SHA" != "$checked_out_sha"', '"$GITHUB_SHA" = "$checked_out_sha"') : null },
          ];
          const probes: string[] = [...deletionFaults];
          const rows = [...standing.rows];
          for (const plant of plants) {
            if (plant.text === null || plant.text === releaseText) probes.push(`${plant.what}: no edit was made`);
            else {
              const found = inspect(plant.text);
              if (found.faults.length === 0) probes.push(`${plant.what}: no fault fired`);
              rows.push(`${plant.what}: ${found.faults.length} fault(s) — ${found.faults.join('; ')}`);
            }
          }
          const held = standing.faults.length === 0 && probes.length === 0;
          say(id, held, probeDetail(held, [...standing.faults, ...probes], `${rows.length} measured row(s): ${rows.join('; ')}`),
            'issue #1542: checkout does not change the GITHUB_SHA npm records in provenance; a dispatch from another commit must stop before any name is published');
        } finally {
          rmSync(mock, { recursive: true, force: true });
        }
      }
    }

    // --- CUR124–CUR125: the squash text release-please reads (issue #1354) ----
    //
    // The squash of #1352 (1c04a03) shipped nothing: line 20 of its body opened
    // with a code span holding a call, release-please's commit parser threw
    // `unexpected token '(' at 20:23`, and the release run logged it at debug
    // level, counted zero commits and concluded success. `scripts/commit_parse.ts`
    // reads the squash text with that parser before the merge, and
    // `squash-text.yml` runs it on every pull request event that can change the
    // text. CUR124 holds the judgement on fixtures, through the same
    // `judgeSquash` the pull request job calls; CUR125 holds the job and the pin.
    {
      // The first 21 lines of 1c04a03 as they stood on the branch — the one
      // commit of #1352, its subject without the ` (#1352)` the squash appends.
      const incident = [
        'feat(validate): A51 holds the bones a rig declares to share an axis to the line through two named bones\' setup-pose origins — invariants.axes, refused by name at read, validity under the default profile, equal on both suppliers (AX01–AX06), and declared on gallery/look, nod and portrait at 0.0000° off with no emitted byte moved (#1351)',
        '',
        'An agent keys `scaleY` on an eye bone to blink. On a face painted tilted,',
        'bones written at rotation 0 squash along the page\'s vertical rather than',
        'across the eye line — the parser accepts it, the gate was green, the',
        'picture is wrong. Measured on HQ\'s trailer rig: the eye line 23.7° off the',
        'page, five face bones at 0; the first production consumer reports the same',
        'root behind four defects (eye scaleY, brow translateY, mouth scaleY, iris',
        'translateX). The build-side fix for generated rigs is rig-c/parts#239; this',
        'is the rule that holds any rig, hand-authored included.',
        '',
        'What is built: `invariants.axes: [{ name, through: [a, b], bones, tolerance }]`',
        'and `A51_BONES_LIE_ALONG_THEIR_DECLARED_AXIS`. The axis is the line through',
        'the two `through` bones\' setup-pose world origins; every bone in `bones`',
        'must have its world x axis within `tolerance` degrees of it, as a line (the',
        'gap folded mod 180° into 0–90°, so a bone turned 180° or mirrored lies on',
        'it). The pose is A50\'s, measured rather than chosen: constraints applied,',
        'no physics, no skin set — spine-core `setupPose()` +',
        '`updateWorldTransform(Physics.none)` read off `appliedPose`, the model side',
        '`poseSetup(underNoSkin(doc))` + `activeBones`. A bone\'s angle is',
        '`atan2(c, a)`, what `getWorldRotationX` reports. Held whether or not an',
      ];
      // What the release log of run 38147112861 printed for it, verbatim.
      const RELEASE_LOG = "unexpected token '(' at 20:23, valid tokens [)]";
      const badLine = incident.findIndex((line) => line.startsWith('`poseSetup('));
      // The positive control: the same words, the code span moved off the start of the line.
      const reflowed = incident.map((line, i) =>
        i === badLine - 1 ? `${line} ${incident[badLine].slice(0, incident[badLine].indexOf(' + '))}` : i === badLine ? incident[badLine].slice(incident[badLine].indexOf(' + ') + 1) : line,
      );
      const message = (lines: readonly string[]): string => `${lines.join('\n')}\n`;
      const notConventional = 'A sixth gallery example: nod';
      const conventional = 'feat(gallery): nod, a sixth example';
      const clean = 'test(selftest): a second commit on the branch\n\nNothing in this body opens a line the grammar reads as a footer.\n';
      const override = (text: string): string => `What the squash says is replaced.\n\nBEGIN_COMMIT_OVERRIDE\n${text}\nEND_COMMIT_OVERRIDE\n`;
      const probes: string[] = [];
      const rows: string[] = [];
      const expect = (
        what: string,
        input: { title: string; commits: string[]; body?: string },
        want: { exit: 0 | 1; line?: number; column?: number; error?: string },
      ): void => {
        const verdict = judgeSquash({ title: input.title, number: '1352', commits: input.commits, body: input.body ?? '' });
        const first = verdict.faults[0];
        const at = first === undefined ? 'parses' : `line ${first.line ?? '?'}:${first.partColumn ?? '?'}`;
        rows.push(`${what} -> ${verdict.exit === 0 ? 'parses' : at}`);
        if (verdict.exit !== want.exit) {
          probes.push(`${what}: wanted ${want.exit === 0 ? 'a parse' : 'a refusal'} and got ${verdict.exit === 0 ? 'a parse' : `a refusal at ${at} (${first?.error ?? 'no fault'})`}`);
          return;
        }
        if (want.line !== undefined && (first === undefined || first.line !== want.line)) probes.push(`${what}: refused at ${at}, where line ${want.line} is the line at fault`);
        if (want.column !== undefined && (first === undefined || first.partColumn !== want.column)) probes.push(`${what}: refused at ${at}, where column ${want.column} is the release log's`);
        if (want.error !== undefined && (first === undefined || first.error !== want.error)) probes.push(`${what}: the parser said ${JSON.stringify(first?.error ?? null)} where the release log printed ${JSON.stringify(want.error)}`);
        if (verdict.exit === 1 && !verdict.lines.some((line) => first !== undefined && first.lineText !== null && line === `  | ${first.lineText}`)) {
          probes.push(`${what}: the refusal does not print the offending line`);
        }
      };
      // The incident: one commit, so the squash is its subject and body, and the line and column are the release log's.
      expect('the body of 1c04a03', { title: notConventional, commits: [message(incident)] }, { exit: 1, line: badLine + 1, column: 23, error: RELEASE_LOG });
      expect('the same body with the code span moved off the start of its line', { title: notConventional, commits: [message(reflowed)] }, { exit: 0 });
      // The title is read only where the squash writes it: one commit's subject is its own, several take the pull request title.
      expect('one commit, the title not conventional', { title: notConventional, commits: [message(reflowed)] }, { exit: 0 });
      expect('two commits, the title not conventional', { title: notConventional, commits: [message(reflowed), clean] }, { exit: 1, line: 1 });
      expect('two commits, the title conventional', { title: conventional, commits: [message(reflowed), clean] }, { exit: 0 });
      // In a squash of several, the incident line sits below the title, a blank line and its `* `.
      const several = squashText({ title: conventional, number: '1352', commits: [clean, message(incident)] }).split('\n');
      expect('two commits, the second carrying the incident line', { title: conventional, commits: [clean, message(incident)] }, { exit: 1, line: several.indexOf(incident[badLine]) + 1, column: 23 });
      // The pull request body is read for the override release-please reads instead, and for nothing else.
      expect('the incident line in the pull request body alone', { title: conventional, commits: [message(reflowed), clean], body: incident[badLine] }, { exit: 0 });
      expect('the incident body as a commit override', { title: conventional, commits: [message(reflowed), clean], body: override(message(incident)) }, { exit: 1, line: badLine + 1, column: 23 });
      expect('a clean override over the incident commit', { title: conventional, commits: [message(incident)], body: override(clean) }, { exit: 0 });
      // The parser itself, outside the assembly: what release-please's own splitting hands it.
      const direct = parseFaults(message(incident));
      if (direct.length !== 1 || direct[0].error !== RELEASE_LOG) probes.push(`parseFaults on the raw 1c04a03 lines answered ${JSON.stringify(direct.map((fault) => fault.error))}, where the release log printed one fault, ${RELEASE_LOG}`);
      rows.push(`the raw 1c04a03 lines -> ${direct.length} fault(s)`);
      const held = probes.length === 0;
      say(
        'CUR124_A_SQUASH_RELEASE_PLEASE_CANNOT_PARSE_IS_REFUSED_BY_ITS_OWN_PARSER_AT_THE_LINE_AND_COLUMN_ITS_RELEASE_LOG_PRINTS',
        held,
        probeDetail(
          held,
          probes,
          `the squash text is judged by @conventional-commits/parser as release-please splits it, and the body of 1c04a03 is refused with the ` +
            `release log's own words (${RELEASE_LOG}) — over ${rows.length} case(s): ${rows.join('; ')}`,
        ),
        'issue #1354: the squash of #1352 shipped nothing and its release run concluded success, because release-please skips a commit its parser throws on',
      );
    }

    if (BUN_YAML === null) {
      reportYamlHole('CUR125_EVERY_PULL_REQUEST_EVENT_THAT_CAN_CHANGE_THE_SQUASH_TEXT_RUNS_THE_PINNED_PARSER_OVER_IT_THROUGH_THE_ENVIRONMENT');
    } else {
      const FILE = 'squash-text.yml';
      const PARSER = '@conventional-commits/parser';
      const STEP_RUN = 'bun scripts/commit_parse.ts pr';
      const ENV_WANT: Record<string, string> = {
        PR_TITLE: 'github.event.pull_request.title',
        PR_BODY: 'github.event.pull_request.body',
        PR_NUMBER: 'github.event.pull_request.number',
        BASE_SHA: 'github.event.pull_request.base.sha',
        HEAD_SHA: 'github.event.pull_request.head.sha',
      };
      const STRANGER = /\$\{\{\s*github\.(event\.pull_request\.(title|body|head\.ref|head\.label)|head_ref)\b/;
      const installedVersion = ((): string | null => {
        try {
          return (JSON.parse(readFileSync(join(root, 'node_modules', '@conventional-commits', 'parser', 'package.json'), 'utf8')) as { version?: string }).version ?? null;
        } catch {
          return null;
        }
      })();
      const squashFaults = (edited: Record<string, string>): string[] => {
        const faults: string[] = [];
        const { 'package.json': manifestText, ...workflows } = edited;
        const all = parseAll(workflows, faults);
        if (all === null) return faults;
        // No workflow hands a stranger's text to a shell by interpolation.
        for (const [file, flow] of Object.entries(all)) {
          for (const [name, job] of Object.entries(flow.jobs ?? {})) {
            for (const step of job.steps ?? []) {
              if (STRANGER.test(step.run ?? '')) faults.push(`${file} job "${name}" interpolates pull request text into \`run:\`, which executes it; pass it through \`env:\``);
            }
          }
        }
        const flow = all[FILE];
        if (flow === undefined) return [...faults, `there is no .github/workflows/${FILE}`];
        const pr = (flow.on ?? {}).pull_request as { types?: string[] } | null | undefined;
        const types = pr?.types ?? [];
        for (const type of ['opened', 'edited', 'synchronize', 'reopened']) {
          if (!types.includes(type)) faults.push(`${FILE}: \`pull_request\` does not list "${type}", so ${type === 'edited' ? 'fixing a title or body is not checked again' : `a ${type} pull request is not checked`}`);
        }
        const steps = Object.values(flow.jobs ?? {}).flatMap((job) => job.steps ?? []);
        const checking = steps.filter((step) => runLines(step).includes(STEP_RUN));
        if (checking.length !== 1) faults.push(`${FILE}: ${checking.length} step(s) run \`${STEP_RUN}\`, where one does`);
        else {
          for (const [variable, field] of Object.entries(ENV_WANT)) {
            const value = checking[0].env?.[variable] ?? '';
            if (!new RegExp(`^\\$\\{\\{\\s*${field.replace(/\./g, '\\.')}\\s*\\}\\}$`).test(value)) faults.push(`${FILE}: the checking step's env ${variable} is ${JSON.stringify(value)}, where it reads \${{ ${field} }}`);
          }
        }
        const checkout = steps.find((step) => /actions\/checkout/.test(step.uses ?? ''));
        if (String(checkout?.with?.['fetch-depth'] ?? '') !== '0') faults.push(`${FILE}: the checkout is not \`fetch-depth: 0\`, so the commits between the merge base and the head are not there to read`);
        if (!steps.some((step) => runLines(step).includes('bun install --frozen-lockfile'))) faults.push(`${FILE}: nothing runs \`bun install --frozen-lockfile\`, so the parser the lockfile pins is not the one that runs`);
        // The parser is pinned to one version, and that version is the one installed.
        const declared = (JSON.parse(manifestText ?? '{}') as { devDependencies?: Record<string, string> }).devDependencies?.[PARSER] ?? null;
        if (declared === null || !/^\d+\.\d+\.\d+$/.test(declared)) faults.push(`package.json: devDependencies["${PARSER}"] is ${JSON.stringify(declared)}, where an exact version pins the parser release-please runs`);
        else if (installedVersion !== declared) faults.push(`package.json pins ${PARSER} ${declared} and node_modules carries ${JSON.stringify(installedVersion)}`);
        return faults;
      };
      const manifestText = readFileSync(join(root, 'package.json'), 'utf8');
      const base = { ...texts, 'package.json': manifestText };
      const standing = squashFaults(base);
      const fileText = texts[FILE] ?? '';
      // Each plant names the fault it has to raise, so a plant that trips some other row is not counted as caught.
      const plants: Array<{ what: string; edit: Record<string, string | null>; at?: string; quiet?: boolean }> = [
        {
          what: 'the body interpolated into run:',
          edit: { [FILE]: once(fileText, `        run: ${STEP_RUN}\n`, `        run: |\n          echo "\${{ github.event.pull_request.body }}"\n          ${STEP_RUN}\n`) },
          at: `${FILE} job "`,
        },
        { what: 'edited dropped from the triggers', edit: { [FILE]: once(fileText, 'types: [opened, edited, synchronize, reopened]', 'types: [opened, synchronize, reopened]') }, at: `${FILE}: \`pull_request\` does not list "edited"` },
        { what: 'the title read from the branch name', edit: { [FILE]: once(fileText, 'PR_TITLE: ${{ github.event.pull_request.title }}', 'PR_TITLE: ${{ github.event.pull_request.head.ref }}') }, at: `${FILE}: the checking step's env PR_TITLE` },
        { what: 'the step stops running the check', edit: { [FILE]: once(fileText, `run: ${STEP_RUN}`, 'run: echo skipped') }, at: `${FILE}: 0 step(s) run` },
        { what: 'a shallow checkout', edit: { [FILE]: once(fileText, '          fetch-depth: 0\n', '          fetch-depth: 1\n') }, at: `${FILE}: the checkout is not` },
        { what: 'the parser as a range', edit: { 'package.json': once(manifestText, `"${PARSER}": "${installedVersion ?? ''}"`, `"${PARSER}": "^${installedVersion ?? ''}"`) }, at: 'package.json: devDependencies' },
        { what: 'the step renamed', edit: { [FILE]: once(fileText, '- name: release-please parses the text the squash will write', '- name: the squash text parses') }, quiet: true },
      ];
      const probes: string[] = [];
      const cases: string[] = [];
      for (const plant of plants) {
        if (Object.values(plant.edit).some((text) => text === null)) {
          probes.push(`"${plant.what}": the edit found nothing to change, so this plant was never made`);
          continue;
        }
        const raised = raisedBy(squashFaults({ ...base, ...(plant.edit as Record<string, string>) }), { at: plant.at, was: standing });
        if (plant.quiet === true) {
          if (raised.length > 0) probes.push(`"${plant.what}" changes nothing this gate is about and ${raised.length} fault(s) fired: ${raised[0].slice(0, 160)}`);
          cases.push(`${plant.what} -> quiet`);
          continue;
        }
        if (raised.length === 0) probes.push(`"${plant.what}" was planted and this gate did not fire`);
        cases.push(`${plant.what} -> ${raised.length}`);
      }
      const held = standing.length === 0 && probes.length === 0;
      say(
        'CUR125_EVERY_PULL_REQUEST_EVENT_THAT_CAN_CHANGE_THE_SQUASH_TEXT_RUNS_THE_PINNED_PARSER_OVER_IT_THROUGH_THE_ENVIRONMENT',
        held,
        probeDetail(
          held,
          [...standing, ...probes],
          `${FILE} runs \`${STEP_RUN}\` on opened, edited, synchronize and reopened, reads the pull request through \`env:\` with full history, ` +
            `no workflow among ${Object.keys(texts).length} interpolates pull request text into \`run:\`, and ${PARSER} is pinned at ${installedVersion} and installed at it — ` +
            `over ${cases.length} plant(s): ${cases.join('; ')}`,
        ),
        'issue #1354: a check that a title edit does not re-run, or that executes the title it reads, is not the check the card asked for',
      );
    }

    // --- CUR126: `ships` reads the subject the squash writes (issue #1359) ----
    //
    // `ships` read the pull request TITLE as the squash subject, and under
    // `COMMIT_OR_PR_TITLE` that is only true for a branch of several commits:
    // #1356's one commit was retyped `ci:` → `fix(release):` and `ships` stayed
    // red until the title was edited, and a `docs:` commit under a `fix:` title
    // would have passed it and landed hidden from the release. It now reads
    // `bun scripts/commit_parse.ts subject`, which is `squashSubject` over the
    // same `squashText` CUR124 holds. This holds the reader on fixtures — with a
    // title-reader beside it that must disagree, so the rows can tell the two
    // apart — and holds the job: one `ships` in the tree, in the workflow that
    // re-runs on `edited`, installing what the reader imports, handing it the
    // pull request through `env:`, and judging what it printed.
    if (BUN_YAML === null) {
      reportYamlHole('CUR126_SHIPS_JUDGES_THE_SUBJECT_THE_SQUASH_WRITES_READ_FROM_THE_ONE_ASSEMBLY_AND_RERUNS_ON_A_TITLE_EDIT');
    } else {
      const FILE = 'squash-text.yml';
      const READ = 'bun scripts/commit_parse.ts subject';
      const VERDICT = 'judge "$work/changed" "$subject" "$work/said" "  "';
      const ENV_WANT: Record<string, string> = {
        PR_TITLE: 'github.event.pull_request.title',
        PR_NUMBER: 'github.event.pull_request.number',
        BASE_SHA: 'github.event.pull_request.base.sha',
        HEAD_SHA: 'github.event.pull_request.head.sha',
      };
      const rowsFor = (reader: (input: { title: string; number: string; commits: string[] }) => string): { rows: string[]; wrong: string[] } => {
        const cases: Array<{ what: string; title: string; commits: string[]; want: string }> = [
          { what: 'one docs commit under a fix title', title: 'fix: the title', commits: ['docs: the one commit\n\nA body the subject does not carry.\n'], want: 'docs: the one commit' },
          { what: 'one fix commit under a ci title', title: 'ci: the title', commits: ['fix(release): the one commit\n'], want: 'fix(release): the one commit' },
          { what: 'two fix commits under a docs title', title: 'docs: the title', commits: ['fix: the first\n', 'fix: the second\n'], want: 'docs: the title' },
        ];
        const rows: string[] = [];
        const wrong: string[] = [];
        for (const c of cases) {
          const got = reader({ title: c.title, number: '1359', commits: c.commits });
          rows.push(`${c.what} -> ${JSON.stringify(got)}`);
          if (got !== c.want) wrong.push(`${c.what}: the reader answered ${JSON.stringify(got)} where the squash writes ${JSON.stringify(c.want)}`);
        }
        return { rows, wrong };
      };
      const reader = rowsFor(squashSubject);
      const titleReader = rowsFor((input) => input.title);
      const shipsFaults = (edited: Record<string, string>): string[] => {
        const faults: string[] = [];
        const all = parseAll(edited, faults);
        if (all === null) return faults;
        const homes = Object.entries(all)
          .filter(([, flow]) => (flow.jobs ?? {}).ships !== undefined)
          .map(([file]) => file);
        if (homes.length !== 1 || homes[0] !== FILE) {
          faults.push(`a job named \`ships\` is defined in ${homes.length === 0 ? 'no workflow' : homes.join(', ')}, where it is defined once, in ${FILE}, which re-runs on \`edited\``);
        }
        const job = (all[FILE]?.jobs ?? {}).ships;
        if (job === undefined) return faults;
        const steps = job.steps ?? [];
        const at = steps.findIndex((step) => runLines(step).some((line) => line.includes(READ)));
        if (at < 0) return [...faults, `${FILE}: no step of \`ships\` runs \`${READ}\`, so the subject it judges is not the one the squash writes`];
        const step = steps[at];
        for (const [variable, field] of Object.entries(ENV_WANT)) {
          const value = step.env?.[variable] ?? '';
          if (!new RegExp(`^\\$\\{\\{\\s*${field.replace(/\./g, '\\.')}\\s*\\}\\}$`).test(value)) faults.push(`${FILE}: the \`ships\` step's env ${variable} is ${JSON.stringify(value)}, where it reads \${{ ${field} }}`);
        }
        if (!steps.slice(0, at).some((step) => runLines(step).includes('bun install --frozen-lockfile'))) {
          faults.push(`${FILE}: \`ships\` runs no \`bun install --frozen-lockfile\` before \`${READ}\`, and the reader imports the pinned parser at load`);
        }
        if (!runLines(step).includes(VERDICT)) faults.push(`${FILE}: the \`ships\` verdict is not \`${VERDICT}\`, so what it judges is not the subject the reader printed`);
        return faults;
      };
      const standing = shipsFaults(texts);
      const fileText = texts[FILE] ?? '';
      const ciText = texts['ci.yml'] ?? '';
      const plants: Array<{ what: string; edit: Record<string, string | null>; at?: string; quiet?: boolean }> = [
        { what: 'the verdict judges the title again', edit: { [FILE]: once(fileText, VERDICT, 'judge "$work/changed" "$PR_TITLE" "$work/said" "  "') }, at: `${FILE}: the \`ships\` verdict` },
        { what: 'a second ships job back in ci.yml', edit: { 'ci.yml': `${ciText.trimEnd()}\n\n  ships:\n    runs-on: ubuntu-latest\n    steps:\n      - run: echo planted\n` }, at: 'a job named `ships`' },
        {
          what: 'ships stops installing what the reader imports',
          edit: { [FILE]: once(fileText, '      - uses: oven-sh/setup-bun@v2\n      - run: bun install --frozen-lockfile\n\n      - name: A landing', '      - uses: oven-sh/setup-bun@v2\n\n      - name: A landing') },
          at: `${FILE}: \`ships\` runs no`,
        },
        {
          what: 'the number left out of the env the reader reads',
          edit: { [FILE]: once(fileText, '          PR_NUMBER: ${{ github.event.pull_request.number }}\n        run: |\n          # `sort`', '        run: |\n          # `sort`') },
          at: `${FILE}: the \`ships\` step's env PR_NUMBER`,
        },
        { what: 'the ships step renamed', edit: { [FILE]: once(fileText, '- name: A landing that changes the package is visible to the release', '- name: ships') }, quiet: true },
      ];
      const probes: string[] = [...reader.wrong];
      if (titleReader.wrong.length === 0) probes.push('a reader that returns the title agreed with every fixture row, so the rows cannot tell the squash subject from the title');
      const cases: string[] = [];
      for (const plant of plants) {
        if (Object.values(plant.edit).some((text) => text === null)) {
          probes.push(`"${plant.what}": the edit found nothing to change, so this plant was never made`);
          continue;
        }
        const raised = raisedBy(shipsFaults({ ...texts, ...(plant.edit as Record<string, string>) }), { at: plant.at, was: standing });
        if (plant.quiet === true) {
          if (raised.length > 0) probes.push(`"${plant.what}" changes nothing this gate is about and ${raised.length} fault(s) fired: ${raised[0].slice(0, 160)}`);
          cases.push(`${plant.what} -> quiet`);
          continue;
        }
        if (raised.length === 0) probes.push(`"${plant.what}" was planted and this gate did not fire`);
        cases.push(`${plant.what} -> ${raised.length}`);
      }
      const held = standing.length === 0 && probes.length === 0;
      say(
        'CUR126_SHIPS_JUDGES_THE_SUBJECT_THE_SQUASH_WRITES_READ_FROM_THE_ONE_ASSEMBLY_AND_RERUNS_ON_A_TITLE_EDIT',
        held,
        probeDetail(
          held,
          [...standing, ...probes],
          `squashSubject answers the one commit's subject for one commit and the title for several — ${reader.rows.join('; ')} — where a title-reader ` +
            `gets ${titleReader.wrong.length} of ${reader.rows.length} row(s) wrong; \`ships\` is defined once, in ${FILE}, installs, runs \`${READ}\` with the pull request ` +
            `through \`env:\` and judges what it printed — over ${cases.length} plant(s): ${cases.join('; ')}`,
        ),
        'issue #1359: under COMMIT_OR_PR_TITLE a single commit squashes to its own subject, so a check that reads the title judges a line the squash does not write',
      );
    }

    // --- CUR127: `removals` re-runs on an edit of the text it reads (issue #1368) ----
    //
    // `removals` accepts a removed control's declaration from a commit message,
    // the pull request title or its body, and it lived in ci.yml, which does not
    // run on `edited`: writing the declaration the job asked for into the title
    // or body re-ran nothing, and the red stood until a new head was pushed. It
    // now lives in squash-text.yml, which runs on `edited` and starts no
    // selftest shard. This holds where it is — defined once, in that workflow,
    // with `edited` among its triggers — and that what an edit changes is still
    // what it reads: the title and body through `env:`, appended to what it
    // judges, over a full-history checkout.
    if (BUN_YAML === null) {
      reportYamlHole('CUR127_REMOVALS_RERUNS_ON_AN_EDIT_OF_THE_TITLE_AND_BODY_IT_READS');
    } else {
      const FILE = 'squash-text.yml';
      const SAID = `printf '%s\\n%s\\n' "$PR_TITLE" "$PR_BODY" >> "$work/said"`;
      const VERDICT = 'judge "$work/gone" "$work/said" "  "';
      const ENV_WANT: Record<string, string> = {
        PR_TITLE: 'github.event.pull_request.title',
        PR_BODY: 'github.event.pull_request.body',
        BASE_SHA: 'github.event.pull_request.base.sha',
        HEAD_SHA: 'github.event.pull_request.head.sha',
      };
      const removalsFaults = (edited: Record<string, string>): string[] => {
        const faults: string[] = [];
        const all = parseAll(edited, faults);
        if (all === null) return faults;
        const homes = Object.entries(all)
          .filter(([, flow]) => (flow.jobs ?? {}).removals !== undefined)
          .map(([file]) => file);
        if (homes.length !== 1 || homes[0] !== FILE) {
          faults.push(`a job named \`removals\` is defined in ${homes.length === 0 ? 'no workflow' : homes.join(', ')}, where it is defined once, in ${FILE}, which re-runs on \`edited\``);
        }
        const flow = all[FILE];
        const types = ((flow?.on ?? {}).pull_request as { types?: string[] } | null | undefined)?.types ?? [];
        if (!types.includes('edited')) faults.push(`${FILE}: \`pull_request\` does not list "edited", so declaring a removal in the title or body does not run \`removals\` again`);
        const job = (flow?.jobs ?? {}).removals;
        if (job === undefined) return faults;
        const steps = job.steps ?? [];
        const checkout = steps.find((step) => /actions\/checkout/.test(step.uses ?? ''));
        if (String(checkout?.with?.['fetch-depth'] ?? '') !== '0') faults.push(`${FILE}: \`removals\` checks out without \`fetch-depth: 0\`, so the merge base it compares against is not there`);
        const at = steps.findIndex((step) => runLines(step).includes(VERDICT));
        if (at < 0) return [...faults, `${FILE}: no step of \`removals\` runs \`${VERDICT}\`, so nothing judges what left the tree`];
        const step = steps[at];
        for (const [variable, field] of Object.entries(ENV_WANT)) {
          const value = step.env?.[variable] ?? '';
          if (!new RegExp(`^\\$\\{\\{\\s*${field.replace(/\./g, '\\.')}\\s*\\}\\}$`).test(value)) faults.push(`${FILE}: the \`removals\` step's env ${variable} is ${JSON.stringify(value)}, where it reads \${{ ${field} }}`);
        }
        if (!runLines(step).includes(SAID)) faults.push(`${FILE}: the \`removals\` step does not append the title and body to what it judges (\`${SAID}\`), so an edit of them changes nothing it reads`);
        return faults;
      };
      const standing = removalsFaults(texts);
      const fileText = texts[FILE] ?? '';
      const ciText = texts['ci.yml'] ?? '';
      const jobAt = fileText.indexOf('\n  removals:\n');
      /** One edit inside the `removals` job alone, so a string the other jobs share is planted where this gate reads it. */
      const inJob = (from: string, to: string): string | null => {
        if (jobAt < 0) return null;
        const job = once(fileText.slice(jobAt), from, to);
        return job === null ? null : fileText.slice(0, jobAt) + job;
      };
      const plants: Array<{ what: string; edit: Record<string, string | null>; at?: string; quiet?: boolean }> = [
        { what: 'a second removals job back in ci.yml', edit: { 'ci.yml': `${ciText.trimEnd()}\n\n  removals:\n    runs-on: ubuntu-latest\n    steps:\n      - run: echo planted\n` }, at: 'a job named `removals`' },
        { what: 'edited dropped from the triggers', edit: { [FILE]: once(fileText, 'types: [opened, edited, synchronize, reopened]', 'types: [opened, synchronize, reopened]') }, at: `${FILE}: \`pull_request\` does not list "edited", so declaring` },
        { what: 'the body left out of the env', edit: { [FILE]: inJob('          PR_BODY: ${{ github.event.pull_request.body }}\n', '') }, at: `${FILE}: the \`removals\` step's env PR_BODY` },
        { what: 'the title and body no longer judged', edit: { [FILE]: inJob(`          ${SAID}\n`, '') }, at: `${FILE}: the \`removals\` step does not append` },
        { what: 'a shallow checkout of removals', edit: { [FILE]: inJob('          fetch-depth: 0\n', '          fetch-depth: 1\n') }, at: `${FILE}: \`removals\` checks out without` },
        { what: 'the removals step renamed', edit: { [FILE]: inJob('- name: A control that leaves is named by the change that removes it', '- name: removals') }, quiet: true },
      ];
      const probes: string[] = [];
      const cases: string[] = [];
      for (const plant of plants) {
        if (Object.values(plant.edit).some((text) => text === null)) {
          probes.push(`"${plant.what}": the edit found nothing to change, so this plant was never made`);
          continue;
        }
        const raised = raisedBy(removalsFaults({ ...texts, ...(plant.edit as Record<string, string>) }), { at: plant.at, was: standing });
        if (plant.quiet === true) {
          if (raised.length > 0) probes.push(`"${plant.what}" changes nothing this gate is about and ${raised.length} fault(s) fired: ${raised[0].slice(0, 160)}`);
          cases.push(`${plant.what} -> quiet`);
          continue;
        }
        if (raised.length === 0) probes.push(`"${plant.what}" was planted and this gate did not fire`);
        cases.push(`${plant.what} -> ${raised.length}`);
      }
      const held = standing.length === 0 && probes.length === 0;
      say(
        'CUR127_REMOVALS_RERUNS_ON_AN_EDIT_OF_THE_TITLE_AND_BODY_IT_READS',
        held,
        probeDetail(
          held,
          [...standing, ...probes],
          `\`removals\` is defined once, in ${FILE}, which lists "edited"; it checks out full history, reads the title, body and both SHAs through \`env:\` ` +
            `and appends the title and body to what it judges — over ${cases.length} plant(s): ${cases.join('; ')}`,
        ),
        'issue #1368: a check whose remedy is a sentence in the pull request text, and which an edit of that text does not re-run, stays red after it is satisfied',
      );
    }
  }

  // --- CUR113–CUR115: the package as an install receives it — spine-core a devDependency (issue #1061) --
  //
  // `@esotericsoftware/spine-core` is a devDependency: a clone and CI install it,
  // an install of the package does not. So the package has to run without it, and
  // what makes that true is a property of the shipped import graph, held here over
  // `files` rather than over the tree: the entry the launcher picks when the runtime
  // is absent (`cli_core.ts`) reaches, through what ships, none of the modules that
  // import the runtime and none of the modules registering a command the command
  // table marks as needing it (CUR113); the entry it picks when the runtime resolves
  // (`cli.ts`) reaches every one of those linkers, so the round trip is still what a
  // clone runs (CUR114); and the manifest, the lockfile and the launcher state the
  // split the graph needs — the runtime declared only as a devDependency, at the
  // version the lockfile pins, and chosen by resolution alone (CUR115).
  {
    const RUNTIME_SPEC = /^@esotericsoftware\/spine-core(\/|$)/;
    const shippedModules = [...shipped].filter((file) => /\.(ts|mjs|cjs)$/.test(file)).sort();
    const population = new Map(shippedModules.map((file) => [file, readFileSync(join(root, file), 'utf8')] as const));
    const linkersOf = (pop: ReadonlyMap<string, string>): string[] =>
      [...pop].filter(([, text]) => specifiersOf(codeOnly(text)).some((s) => !s.typeOnly && RUNTIME_SPEC.test(s.spec))).map(([file]) => file).sort();
    // The modules that register a body the command table marks as needing the runtime — RC26's registrars, read off the marks.
    const registrars: Array<[string, Readonly<Record<string, unknown>>]> = [
      ['src/cli/core_commands.ts', CORE_COMMAND_RUNS],
      ['src/cli/spine_commands.ts', SPINE_COMMAND_RUNS],
    ];
    const runtimeRegistrars = registrars
      .filter(([, runs]) => COMMANDS.some((doc) => doc.runtime !== false && Object.prototype.hasOwnProperty.call(runs, doc.name)))
      .map(([module]) => module);
    const chainIn = (closure: CoreClosure, module: string): string => {
      const chain: string[] = [];
      for (let at: string | null = module; at !== null; at = closure.via.get(at) ?? null) chain.unshift(at);
      return chain.join(' > ');
    };
    const shippedClosureFaults = (pop: ReadonlyMap<string, string>, entry: string): { closure: CoreClosure; faults: string[] } => {
      const closure = coreClosureFrom(pop, [entry]);
      const faults: string[] = [];
      if (!pop.has(entry)) faults.push(`${entry} is not shipped — \`files\` does not carry the entry the launcher runs without the runtime`);
      for (const missing of closure.problems) faults.push(`🔒 ${missing.replace('is not in the population read', 'is not shipped')}`);
      const linkers = linkersOf(pop);
      for (const module of closure.modules) {
        if (linkers.includes(module)) faults.push(`🔒 ${module} imports spine-core and the install's entry reaches it: ${chainIn(closure, module)}`);
        if (runtimeRegistrars.includes(module)) faults.push(`🔒 ${module} registers commands marked as needing the runtime and the install's entry reaches it: ${chainIn(closure, module)}`);
      }
      return { closure, faults };
    };

    // CUR113
    const live = shippedClosureFaults(population, 'cli_core.ts');
    const probes113 = [...live.faults];
    // The plant: one closure member, the deepest the walk recorded, importing the round trip.
    const member = [...live.closure.modules].filter((m) => m !== 'cli_core.ts' && m.startsWith('src/')).sort((a, b) => chainIn(live.closure, b).split(' > ').length - chainIn(live.closure, a).split(' > ').length || a.localeCompare(b))[0];
    let plantedChain = '';
    if (member === undefined) probes113.push('cli_core.ts reaches no module of src/, so the plant has nowhere to go');
    else {
      const spec = relative(dirname(member), 'src/validate.ts').split('\\').join('/');
      const planted = shippedClosureFaults(plantedInto(population, member, `import { validate as planted } from '${spec.startsWith('.') ? spec : `./${spec}`}';`), 'cli_core.ts');
      const raised = planted.faults.filter((f) => !live.faults.includes(f));
      plantedChain = raised.find((f) => f.includes(`${member} > src/validate.ts`)) ?? '';
      if (plantedChain === '') probes113.push(`an import of validate.ts planted in ${member} raised [${raised.join('; ')}], none naming the chain through ${member}`);
    }
    const dropped = shippedClosureFaults(new Map([...population].filter(([file]) => file !== 'cli_core.ts')), 'cli_core.ts');
    if (!dropped.faults.some((f) => f.startsWith('cli_core.ts is not shipped'))) probes113.push('a package whose `files` leaves cli_core.ts out was not faulted');
    const held113 = probes113.length === 0 && live.closure.modules.length > 1;
    say(
      'CUR113_THE_ENTRY_AN_INSTALL_RUNS_REACHES_NO_RUNTIME_LINKER_AND_NO_RUNTIME_COMMAND_THROUGH_WHAT_SHIPS',
      held113,
      probeDetail(
        held113,
        probes113,
        `\`files\` ships ${shippedModules.length} module(s); cli_core.ts's static closure within them is ${live.closure.modules.length} module(s) (${closureByDirectory(live.closure.modules)}), every one shipped, and reaches none of the ` +
          `${linkersOf(population).length} shipped module(s) that import spine-core [${linkersOf(population).join(', ')}] nor the module(s) registering a command marked as needing it [${runtimeRegistrars.join(', ')}]; ` +
          `an import of validate.ts planted in ${member ?? '(none)'} is named — ${plantedChain.replace(/^🔒 /, '')} — and a \`files\` without cli_core.ts is named`,
      ),
      'issue #1061: spine-core is a devDependency, so an install has no runtime and the launcher hands it to cli_core.ts; RC24–RC26 hold that entry over the tree, and this holds it over what `files` ships — the allowlist an install actually has, where a module reached and not shipped is `Cannot find module` and a module reached that links the runtime is the same',
    );

    // CUR114
    const full = coreClosureFrom(population, ['cli.ts']);
    const linkers = linkersOf(population);
    const unreached = linkers.filter((module) => !full.modules.includes(module));
    const probes114 = unreached.map((module) => `${module} imports spine-core and cli.ts does not reach it, so the full entry does not run what it links`);
    if (linkers.length === 0) probes114.push('no shipped module imports spine-core, so there is no round trip for the full entry to reach');
    const extra = 'src/planted_linker.ts';
    const withExtra = new Map(population).set(extra, "import { Skeleton } from '@esotericsoftware/spine-core';\nexport const planted = Skeleton;\n");
    const extraUnreached = linkersOf(withExtra).filter((module) => !coreClosureFrom(withExtra, ['cli.ts']).modules.includes(module));
    if (!extraUnreached.includes(extra)) probes114.push('a shipped module linking the runtime that cli.ts does not reach was not named');
    const held114 = probes114.length === 0;
    say(
      'CUR114_THE_ENTRY_A_CLONE_RUNS_REACHES_EVERY_SHIPPED_MODULE_THAT_LINKS_SPINE_CORE',
      held114,
      probeDetail(
        held114,
        probes114,
        `cli.ts's static closure within \`files\` is ${full.modules.length} module(s) and reaches all ${linkers.length} shipped linker(s) [${linkers.join(', ')}] — the round trip a clone and CI run, and the launcher's choice when the runtime resolves; a planted linker it does not reach is named`,
      ),
      'issue #1061: the launcher runs cli.ts exactly when spine-core resolves, so the promise that a clone and CI still round-trip every build is the promise that cli.ts reaches every module linking the runtime — a linker nothing reaches is dead weight in the package and a gate nobody runs',
    );

    // CUR115
    const manifest = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8')) as { dependencies?: Record<string, string>; devDependencies?: Record<string, string>; bin?: Record<string, string> };
    const RUNTIME = '@esotericsoftware/spine-core';
    const lock = readFileSync(join(root, 'bun.lock'), 'utf8');
    const pinned = new RegExp(`"${RUNTIME.replace('/', '\\/')}": \\["${RUNTIME.replace('/', '\\/')}@([^"]+)"`).exec(lock)?.[1] ?? null;
    const probes115: string[] = [];
    if (manifest.dependencies !== undefined && RUNTIME in manifest.dependencies) probes115.push(`package.json declares ${RUNTIME} in dependencies, so every install fetches it`);
    const declared = manifest.devDependencies?.[RUNTIME];
    if (declared === undefined) probes115.push(`package.json declares no ${RUNTIME} devDependency, so a clone and CI would have no round trip`);
    else if (pinned === null || declared !== pinned) probes115.push(`package.json pins ${RUNTIME} at ${JSON.stringify(declared)} and bun.lock resolves ${JSON.stringify(pinned)}`);
    const launcher = manifest.bin?.rigc;
    let launcherLine = 'not run: no `node` on PATH (the launcher suite says so)';
    if (launcher === undefined) probes115.push('package.json names no `rigc` bin');
    else if (firstOnPath('node') !== null) {
      const nodeBin = join(firstOnPath('node') as string, 'node');
      const work = mkdtempSync(join(harnessTemp(), 'rigc-cur115-'));
      const tree = (name: string, runtime: boolean, drop?: string): string => {
        const at = absentTree(join(work, name));
        mkdirSync(join(at, 'bin'), { recursive: true });
        cpSync(join(root, launcher), join(at, launcher));
        if (runtime) {
          mkdirSync(join(at, 'node_modules', '@esotericsoftware'), { recursive: true });
          symlinkSync(join(root, 'node_modules', '@esotericsoftware', 'spine-core'), join(at, 'node_modules', '@esotericsoftware', 'spine-core'), 'dir');
        }
        if (drop !== undefined) rmSync(join(at, drop));
        return at;
      };
      const version = (JSON.parse(readFileSync(join(root, 'package.json'), 'utf8')) as { version: string }).version;
      const installed = (JSON.parse(readFileSync(join(root, 'node_modules', '@esotericsoftware', 'spine-core', 'package.json'), 'utf8')) as { version?: string }).version;
      const runIn = (at: string, env?: Record<string, string>): { status: number | null; stdout: string; stderr: string } => {
        const r = spawnSync(nodeBin, [join(at, launcher), '--version'], { cwd: work, encoding: 'utf8', env: { ...process.env, ...env } });
        return { status: r.status, stdout: r.stdout, stderr: r.stderr };
      };
      const absent = runIn(tree('absent', false));
      const present = runIn(tree('present', true));
      // Whatever an environment says, the choice is the resolution's: the absent tree under a variable naming the full entry still runs the core one.
      const urged = runIn(join(work, 'absent'), { RIGC_ENTRY: 'cli.ts', RIGC_FULL: '1' });
      const noCore = runIn(tree('nocore', false, 'cli_core.ts'));
      if (absent.status !== 0 || absent.stdout !== `${version}\n` || !absent.stderr.includes(`entry: cli_core.ts — ${RUNTIME} absent`)) probes115.push(`with ${RUNTIME} absent the launcher exited ${absent.status} printing ${JSON.stringify(absent.stdout)} / ${JSON.stringify(absent.stderr.trim())}`);
      if (present.status !== 0 || present.stdout !== `${version}\n` || present.stderr.trim() !== `entry: cli.ts — ${RUNTIME} ${installed} present`) probes115.push(`with ${RUNTIME} beside it the launcher exited ${present.status} printing ${JSON.stringify(present.stdout)} / ${JSON.stringify(present.stderr.trim())}`);
      if (urged.stderr !== absent.stderr || urged.stdout !== absent.stdout) probes115.push(`an environment naming the full entry changed what the launcher ran: ${JSON.stringify(urged.stderr.trim())}`);
      if (noCore.status === 0 || noCore.stdout.includes(version)) probes115.push(`with ${RUNTIME} absent and cli_core.ts removed the launcher exited ${noCore.status} printing ${JSON.stringify(noCore.stdout)} — it fell back to an entry rather than failing`);
      launcherLine = `${launcher} under node in a copy with an empty node_modules: stdout ${JSON.stringify(absent.stdout.trim())}, stderr ${JSON.stringify(absent.stderr.trim())}; with the runtime linked beside it: ${JSON.stringify(present.stderr.trim())}; an environment naming the full entry changes nothing; with cli_core.ts gone it exits ${noCore.status}`;
      rmSync(work, { recursive: true, force: true });
    }
    const held115 = probes115.length === 0;
    say(
      'CUR115_THE_RUNTIME_IS_A_DEVDEPENDENCY_AND_THE_LAUNCHER_CHOOSES_ITS_ENTRY_BY_RESOLUTION_ALONE',
      held115,
      probeDetail(
        held115,
        probes115,
        `package.json declares ${RUNTIME} only as a devDependency, at ${JSON.stringify(declared)}, the version bun.lock resolves; ${launcherLine}`,
      ),
      'issue #1061: the owner settled 2.0.0 as one package whose install carries no runtime — the round trip stays what a clone and CI run, so the dependency moves to devDependencies, and the launcher is the one place that decides which entry an install runs; a choice anything but resolution could flip would be a bypass of the 🔒 invariant spelled as a variable',
    );

    // The checked consumer gets one explicit entry, not the implementation's wider namespace (#1561).
    {
      const functions = ['loadCandidate', 'throughPoser', 'sampleAnimation', 'sampleSetupPose', 'pageFor', 'projector', 'rasterisePiece', 'renderFrame'] as const;
      const failures = ['CandidateAtlasError', 'CandidatePairError', 'PoserChoiceError', 'SlotSubsetError', 'SpineRuntimeError', 'CoreInputError'];
      const expected = [...functions, ...failures].sort();
      const exportsMap = (JSON.parse(readFileSync(join(root, 'package.json'), 'utf8')) as { exports: Record<string, string> }).exports;
      const target = exportsMap['./render-shared'];
      const entry = (target ?? '').replace(/^\.\//, '');
      const population = entryPopulation(root);
      const text = population.get(entry) ?? '';
      const namesFaults = (source: string): string[] => {
        const file = ts.createSourceFile('read-entry.ts', source, ts.ScriptTarget.Latest, true);
        const names: string[] = [];
        const faults: string[] = [];
        for (const node of file.statements) {
          if (ts.isExportDeclaration(node) && !node.isTypeOnly) {
            if (node.exportClause === undefined || !ts.isNamedExports(node.exportClause)) faults.push('wildcard value export');
            else for (const item of node.exportClause.elements) if (!item.isTypeOnly) names.push(item.name.text);
          }
        }
        if (JSON.stringify(names.sort()) !== JSON.stringify(expected)) faults.push('value exports differ from the agreed reads and failures');
        return faults;
      };
      const live = namesFaults(text);
      const faults = [...live];
      if (target !== './src/render_read.ts') faults.push(`./render-shared maps to ${JSON.stringify(target)}`);
      if (JSON.stringify(Object.keys(rendererReads).sort()) !== JSON.stringify(expected)) faults.push('actual namespace differs');
      for (const name of functions) if (rendererReads[name] !== rendererImplementation[name]) faults.push(`${name} is not the official implementation`);
      const closure = coreClosureFrom(population, [entry]);
      faults.push(...closure.problems, ...closure.linkers.map((l) => `runtime reached: ${l.chain.join(' > ')}`));
      if (namesFaults(text + "\nexport * from './render_shared.ts';").length === 0) faults.push('wildcard export plant escaped');
      if (namesFaults(text + "\nexport { fill } from './render_shared.ts';").length === 0) faults.push('extra export plant escaped');
      if (namesFaults(text + "\nexport type { Frame as ReadFrame } from './render_shared.ts';").length !== 0) faults.push('type-only edge refused');
      const valuePlant = coreClosureFrom(plantedInto(population, entry, "import { Skeleton } from '@esotericsoftware/spine-core';"), [entry]);
      const typePlant = coreClosureFrom(plantedInto(population, entry, "import type { Skeleton } from '@esotericsoftware/spine-core';"), [entry]);
      if (valuePlant.linkers.length === 0 || typePlant.linkers.length !== 0) faults.push('runtime value/type edge was not distinguished');
      say('CUR135_RENDER_SHARED_PROMISE_IS_EXPLICIT_AND_USES_THE_OFFICIAL_RUNTIME_FREE_READS', faults.length === 0,
        probeDetail(faults.length === 0, faults, `./render-shared names exactly eight reads and their failure classes; ${closure.modules.length} value modules reach no Spine import; wildcard/extra-export/runtime plants caught, type-only edge accepted; installed calls are held by stock smoke`),
        'issue #1561: transport courtesy does not promise an API; the checked consumer needs the official chooser, samplers and raster reads without eagerly importing the optional runtime');
    }

    // CUR123 — the entry a browser player links reaches only the core (issue #1275).
    //
    // `rig-c/core` is promised to bundle for a browser with no node polyfill, and
    // what makes that true is a property of the entry's static closure: every
    // module it reaches by value is under src/core/, no module in it names a
    // package or a node builtin by value, and the one place it leaves src/core/ is
    // a TYPE import of src/model.ts, which a bundler erases — model.ts itself
    // imports `node:crypto`, so a value import of it would carry node into the
    // browser. The same closure walk as CUR113, from a smaller root, over src/
    // read off the disk (a file not yet committed included). The install smoke
    // measures the bundle; this names the module that would break it, before a
    // pack. The entry is read from package.json's `exports`, not spelled here.
    {
      const exportsMap = (JSON.parse(readFileSync(join(root, 'package.json'), 'utf8')) as { exports?: Record<string, string> }).exports ?? {};
      const target = exportsMap['./core'];
      const entry = target === undefined ? '' : target.replace(/^\.\//, '');
      const TYPE_EXCEPTION = 'src/model.ts';
      const corePopulation = srcPopulation(root);
      const closureFaults = (pop: ReadonlyMap<string, string>): { modules: string[]; typeOnly: string[]; faults: string[] } => {
        const faults: string[] = [];
        if (entry === '' || !pop.has(entry)) {
          faults.push(`package.json's exports maps ./core to ${JSON.stringify(target)}, which is not a module under src/`);
          return { modules: [], typeOnly: [], faults };
        }
        const closure = coreClosureFrom(pop, [entry]);
        const chain = (module: string): string => {
          const out: string[] = [];
          for (let at: string | null = module; at !== null; at = closure.via.get(at) ?? null) out.unshift(at);
          return out.join(' > ');
        };
        faults.push(...closure.problems);
        const typeOnly = new Set<string>();
        for (const module of closure.modules) {
          if (!module.startsWith('src/core/')) faults.push(`🔒 ${module} is outside src/core/ and ./core reaches it by value: ${chain(module)}`);
          for (const { spec, typeOnly: isType } of specifiersOf(codeOnly(pop.get(module) ?? ''))) {
            if (!spec.startsWith('.')) {
              if (!isType) faults.push(`🔒 ${module} imports "${spec}" by value, and ./core reaches it: ${chain(module)}`);
              continue;
            }
            if (!isType) continue;
            const reached = join(dirname(module), spec).split('\\').join('/');
            if (reached.startsWith('src/core/')) continue;
            typeOnly.add(reached);
            if (reached !== TYPE_EXCEPTION) faults.push(`${module} type-imports ${reached}, and the one module outside src/core/ the entry's closure may name, as a type, is ${TYPE_EXCEPTION}`);
          }
        }
        return { modules: closure.modules, typeOnly: [...typeOnly].sort(), faults };
      };
      const live123 = closureFaults(corePopulation);
      const probes123 = [...live123.faults];
      // The plants, each on a copy of the population, each into the deepest closure member other than the entry.
      const member123 = live123.modules.filter((m) => m !== entry).sort((a, b) => b.split('/').length - a.split('/').length || a.localeCompare(b))[0];
      const plants123: Array<[string, string, string]> = [
        ['a value import of src/model.ts', "import { spineFileSha256 as planted } from '../model.ts';", `${TYPE_EXCEPTION} is outside src/core/`],
        ['a node builtin', "import { readFileSync as planted } from 'node:fs';", 'imports "node:fs" by value'],
        ['a package', "import { Skeleton as planted } from '@esotericsoftware/spine-core';", 'imports "@esotericsoftware/spine-core" by value'],
        ['a type import of a module other than src/model.ts', "import type { CompileError as Planted } from '../errors.ts';", 'type-imports src/errors.ts'],
      ];
      const caught123: string[] = [];
      if (member123 === undefined) probes123.push('./core reaches no module but itself, so the plants have nowhere to go');
      else {
        for (const [label, line, mustSay] of plants123) {
          const raised = closureFaults(plantedInto(corePopulation, member123, line)).faults.filter((f) => !live123.faults.includes(f));
          if (!raised.some((f) => f.includes(mustSay))) probes123.push(`${label} planted in ${member123} raised [${raised.join('; ')}], none saying "${mustSay}"`);
          else caught123.push(label);
        }
      }
      const held123 = probes123.length === 0 && live123.modules.length > 1;
      say(
        'CUR123_THE_CORE_ENTRY_REACHES_ONLY_THE_CORE_BY_VALUE_AND_MODEL_TS_ONLY_AS_A_TYPE',
        held123,
        probeDetail(
          held123,
          probes123,
          `./core is ${entry}; its static value closure over src/ read off the disk is ${live123.modules.length} module(s), every one under src/core/ [${live123.modules.join(', ')}], none importing a package or a node builtin by value; ` +
            `outside src/core/ it names only [${live123.typeOnly.join(', ')}], as a type; planted in ${member123 ?? '(none)'}, ${caught123.length} of ${plants123.length} are named — ${caught123.join('; ')}`,
        ),
        'issue #1275: rig-c/core is the entry a runtime-free web player bundles for a browser, so it may reach nothing a browser lacks — src/model.ts imports node:crypto and is admitted only as a type, which the bundler erases; the install smoke bundles it and this names the module that would break that before a pack',
      );
    }

    // CUR136 — the runtime poser's entry a browser player links reaches only the runtime and the core (issue #1591).
    //
    // `rig-c/runtime` (experimental) is play's in-place poser, so it carries the
    // promise `rig-c/core` carries: bundled for a browser, it may reach nothing a
    // browser lacks. The same walk as CUR123 over its closure, read off the
    // disk: every module it reaches by value is under src/runtime/ or src/core/,
    // none names a package or a node builtin by value, and outside those two it
    // names only src/model.ts, as a type. The entry is read from `exports`.
    {
      const exportsMap = (JSON.parse(readFileSync(join(root, 'package.json'), 'utf8')) as { exports?: Record<string, string> }).exports ?? {};
      const target = exportsMap['./runtime'];
      const entry = target === undefined ? '' : target.replace(/^\.\//, '');
      const TYPE_EXCEPTION = 'src/model.ts';
      const inside = (m: string): boolean => m.startsWith('src/runtime/') || m.startsWith('src/core/');
      const runtimePopulation = srcPopulation(root);
      const faultsOf = (pop: ReadonlyMap<string, string>): { modules: string[]; faults: string[] } => {
        const faults: string[] = [];
        if (entry === '' || !pop.has(entry)) return { modules: [], faults: [`package.json's exports maps ./runtime to ${JSON.stringify(target)}, which is not a module under src/`] };
        const closure = coreClosureFrom(pop, [entry]);
        faults.push(...closure.problems);
        for (const module of closure.modules) {
          if (!inside(module)) faults.push(`🔒 ${module} is outside src/runtime/ and src/core/, and ./runtime reaches it by value`);
          for (const { spec, typeOnly: isType } of specifiersOf(codeOnly(pop.get(module) ?? ''))) {
            if (!spec.startsWith('.')) {
              if (!isType) faults.push(`🔒 ${module} imports "${spec}" by value, and ./runtime reaches it`);
              continue;
            }
            const reached = join(dirname(module), spec).split('\\').join('/');
            if (isType && !inside(reached) && reached !== TYPE_EXCEPTION) faults.push(`${module} type-imports ${reached}, and the one module outside src/runtime/ and src/core/ the entry may name, as a type, is ${TYPE_EXCEPTION}`);
          }
        }
        return { modules: closure.modules, faults };
      };
      const live136 = faultsOf(runtimePopulation);
      const probes136 = [...live136.faults];
      if (!live136.modules.some((m) => m.startsWith('src/runtime/')) || !live136.modules.some((m) => m.startsWith('src/core/'))) probes136.push(`./runtime's closure is [${live136.modules.join(', ')}], which does not reach both the runtime and the core it reads`);
      const plants136: Array<[string, string, string]> = [
        ['a node builtin', "import { readFileSync as planted } from 'node:fs';", 'imports "node:fs" by value'],
        ['the Spine runtime package', "import { Skeleton as planted } from '@esotericsoftware/spine-core';", 'imports "@esotericsoftware/spine-core" by value'],
        ['a value import of src/model.ts', "import { spineFileSha256 as planted } from '../model.ts';", `${TYPE_EXCEPTION} is outside`],
      ];
      const caught136: string[] = [];
      for (const [label, line, mustSay] of plants136) {
        const raised = faultsOf(plantedInto(runtimePopulation, 'src/runtime/pose.ts', line)).faults.filter((f) => !live136.faults.includes(f));
        if (!raised.some((f) => f.includes(mustSay))) probes136.push(`${label} planted in src/runtime/pose.ts raised [${raised.join('; ')}], none saying "${mustSay}"`);
        else caught136.push(label);
      }
      const held136 = probes136.length === 0;
      say(
        'CUR136_THE_RUNTIME_ENTRY_REACHES_ONLY_THE_RUNTIME_AND_THE_CORE_BY_VALUE_AND_MODEL_TS_ONLY_AS_A_TYPE',
        held136,
        probeDetail(held136, probes136, `./runtime is ${entry}; its static value closure over src/ read off the disk is ${live136.modules.length} module(s), every one under src/runtime/ or src/core/, none importing a package or a node builtin by value; planted in src/runtime/pose.ts, ${caught136.length} of ${plants136.length} are named — ${caught136.join('; ')}`),
        'issue #1591: rig-c/runtime is the in-place poser a browser player (play#200) bundles, so it carries rig-c/core\'s promise — nothing a browser lacks; the entry is experimental, the browser rule is not',
      );
    }

    // CUR117 — RELEASING.md's row of the commands an install without the
    // runtime runs is the set the command table derives (issue #1178). At
    // v2.12.0 the row listed eight while `bun cli_core.ts --help` listed ten —
    // `build` (#1060) and `repack` (#1177) have bodies on that entry — because
    // nothing read it. The set is read off
    // `COMMANDS` by the rule `entryCommands` applies — a `runtime` of `false`, or
    // one carrying a `core` body — and the row's commands are its backticked
    // lowercase words after the entry's own name, so the parenthesis beside them
    // (`A00_ROUNDTRIP_PARSE`) is not one. Both directions, each difference named.
    {
      const ROW = '| no `@esotericsoftware/spine-core`';
      const derived = COMMANDS.filter((doc) => doc.runtime === false || doc.runtime.core !== undefined).map((doc) => doc.name);
      const rowFaults = (doc: string): { faults: string[]; listed: string[] } => {
        const rows = doc.split('\n').filter((line) => line.startsWith(ROW));
        if (rows.length !== 1) return { faults: [`RELEASING.md has ${rows.length} row(s) starting \`${ROW}\` where one was required, so there is no single statement to read`], listed: [] };
        const cell = rows[0].split('|')[2] ?? '';
        const tokens = [...cell.matchAll(/`([^`]+)`/g)].map((found) => found[1]);
        if (tokens[0] !== 'cli_core.ts') return { faults: [`the row's second cell names ${JSON.stringify(tokens[0] ?? '(nothing)')} first, and the entry an install runs, cli_core.ts, was required`], listed: [] };
        const listed = [...new Set(tokens.slice(1).filter((token) => /^[a-z][a-z0-9-]*$/.test(token)))];
        const faults: string[] = [];
        for (const name of derived.filter((n) => !listed.includes(n))) faults.push(`\`${name}\` runs on cli_core.ts by the command table and the row does not list it`);
        for (const name of listed.filter((n) => !derived.includes(n))) {
          faults.push(COMMANDS.some((doc) => doc.name === name) ? `the row lists \`${name}\`, which the command table marks as needing the runtime with no body on cli_core.ts, so an install refuses it` : `the row lists \`${name}\`, which is not a command`);
        }
        return { faults, listed };
      };
      const releasing = readFileSync(join(root, 'RELEASING.md'), 'utf8');
      const live117 = rowFaults(releasing);
      const probes117 = [...live117.faults];
      const viaEntry = entryCommands(false).map((doc) => doc.name);
      if (viaEntry.join(',') !== derived.join(',')) probes117.push(`the rule read here gives [${derived.join(', ')}] and entryCommands(false) gives [${viaEntry.join(', ')}], so this control reads a different set from the one the entry runs`);
      if (derived.length === 0) probes117.push('the command table derives no command for cli_core.ts, so the row has nothing to be held to');
      // The plants, derived from the live row and the table rather than typed:
      // the row's last command dropped, and the first command the table keeps
      // off the entry (validate, today) added after the entry's name.
      const row = releasing.split('\n').find((line) => line.startsWith(ROW)) ?? '';
      const last = live117.listed[live117.listed.length - 1];
      const outsider = COMMANDS.find((doc) => !derived.includes(doc.name))?.name;
      const plants117: Array<{ what: string; name: string | undefined; doc: string | null }> = [
        { what: 'a command dropped from the row', name: last, doc: last === undefined || !row.includes(`, \`${last}\``) ? null : releasing.replace(row, row.replace(`, \`${last}\``, '')) },
        { what: 'a command added to the row', name: outsider, doc: outsider === undefined ? null : releasing.replace(row, row.replace('`cli_core.ts` — ', `\`cli_core.ts\` — \`${outsider}\`, `)) },
      ];
      const plantCases117: string[] = [];
      for (const plant of plants117) {
        if (plant.doc === null || plant.name === undefined || plant.doc === releasing) {
          probes117.push(`"${plant.what}": the edit found nothing to change, so this plant was never made`);
          continue;
        }
        const raised = rowFaults(plant.doc).faults.filter((f) => !live117.faults.includes(f));
        const named = raised.find((f) => f.includes(`\`${plant.name}\``));
        if (named === undefined) probes117.push(`"${plant.what}" (\`${plant.name}\`) was planted and raised [${raised.join('; ')}], none naming it`);
        else plantCases117.push(`${plant.what} -> ${named}`);
      }
      const held117 = probes117.length === 0;
      say(
        'CUR117_RELEASINGS_ROW_OF_CORE_ENTRY_COMMANDS_IS_THE_SET_THE_COMMAND_TABLE_DERIVES',
        held117,
        probeDetail(
          held117,
          probes117,
          `RELEASING.md's row for an install without the runtime lists the ${live117.listed.length} command(s) [${live117.listed.join(', ')}] and the command table derives the same ${derived.length} for cli_core.ts, as entryCommands(false) does; ` +
            `over ${plantCases117.length} plant(s): ${plantCases117.join('; ')}`,
        ),
        'issue #1178: the row listed eight commands while `bun cli_core.ts --help` listed ten — `build` and `repack` had bodies on that entry and the document an installer reads said they were refused',
      );
    }

    // CUR118 — every code a build report prints, on either entry, has exactly one
    // row in docs/AUTHORING.md §5.2, and every row there is a code one of them
    // prints (issue #1183). At v2.12.0 the core entry's build printed
    // `A00_MODEL_READ` and `A00_MODEL_REGIONS_ON_PAGES` — the model side's own
    // parse rules, outside the registry — and the guide that maps each named
    // failure to the file to change had no row for either, because nothing held
    // the table to anything: not to the registry, and not to the model side.
    // What each entry prints is read, not listed: `cli.ts build`'s report is
    // `validate()`'s, whose rows partition the registry (`S09`, and CUR01's
    // `reached`); `cli_core.ts build`'s is the live core report `currencyTruth`
    // ran, held there to MODEL_SIDE_CODES and the round trip's own codes. The
    // profile column is held too, derived from the code's kind the way the
    // harness excludes it: validity runs under both, the other two are named.
    {
      const GUIDE118 = 'docs/AUTHORING.md';
      const guide118 = readFileSync(join(root, GUIDE118), 'utf8');
      const kindOf118: Readonly<Record<string, string>> = { ...ASSERTION_KIND, ...MODEL_PARSE_KIND };
      const columnOf118 = (kind: string | undefined): string | null => (kind === undefined ? null : kind === 'validity' ? 'both' : kind);
      const entries118: ReadonlyArray<readonly [string, readonly string[]]> = [
        ['cli.ts build', [...ASSERTION_NAMES]],
        ['cli_core.ts build', truth.core.codes],
      ];
      /** §5.2's table rows whose first cell is one code: the code, its profile cell, and the line. */
      const rowsOf118 = (text: string): Array<{ code: string; profile: string; line: number }> => {
        const lines = text.split('\n');
        const start = lines.findIndex((line) => line.startsWith('### 5.2 '));
        if (start < 0) return [];
        const after = lines.findIndex((line, k) => k > start && /^#{1,3} /.test(line));
        const out: Array<{ code: string; profile: string; line: number }> = [];
        for (let k = start + 1; k < (after < 0 ? lines.length : after); k++) {
          const row = /^\| (?:<a id="[^"]*"><\/a>)?`([A-Z]\d\d_[A-Z\d_]+)` \| ([^|]*?) \|/.exec(lines[k]);
          if (row !== null) out.push({ code: row[1], profile: row[2].replace('◑', '').trim(), line: k + 1 });
        }
        return out;
      };
      const faults118 = (text: string, printed: ReadonlyArray<readonly [string, readonly string[]]>): string[] => {
        const rows = rowsOf118(text);
        const codes = [...new Set(printed.flatMap(([, list]) => list))].sort();
        const faults: string[] = [];
        for (const code of codes) {
          const mine = rows.filter((row) => row.code === code);
          const by = printed.filter(([, list]) => list.includes(code)).map(([entry]) => entry).join(' and ');
          if (mine.length === 0) faults.push(`\`${code}\` is printed by ${by} and ${GUIDE118} §5.2 has no row for it`);
          else if (mine.length > 1) faults.push(`\`${code}\` is printed by ${by} and ${GUIDE118} §5.2 has ${mine.length} rows for it (lines ${mine.map((row) => row.line).join(', ')})`);
        }
        for (const row of rows) {
          if (!codes.includes(row.code)) {
            faults.push(`${GUIDE118}:${row.line} is a §5.2 row for \`${row.code}\`, which neither entry's build report prints`);
            continue;
          }
          const want = columnOf118(kindOf118[row.code]);
          if (want === null) faults.push(`${GUIDE118}:${row.line} \`${row.code}\` has no kind in ASSERTION_KIND or MODEL_PARSE_KIND, so its profile column cannot be derived`);
          else if (row.profile !== want) faults.push(`${GUIDE118}:${row.line} files \`${row.code}\` under "${row.profile}", and its kind (${kindOf118[row.code]}) runs it under "${want}"`);
        }
        return faults;
      };
      const live118 = faults118(guide118, entries118);
      const rows118 = rowsOf118(guide118);
      const printed118 = [...new Set(entries118.flatMap(([, list]) => list))];
      const probes118 = [
        ...live118,
        ...floorProbes(
          [
            [rows118.length, printed118.length, `${rows118.length} §5.2 row(s) read against ${printed118.length} printed code(s)`],
            [truth.core.codes.filter((code) => !ASSERTION_NAMES.includes(code)).length, 1, 'the core report printed no code outside the registry'],
          ],
          'so the table was not read the way this control reads it, or the core report was not the one it describes',
        ),
      ];
      // The plants, derived rather than typed: a code joining the model side's
      // list with no row, and a copy of the first row filed under a code neither
      // entry prints.
      const PLANTED_CODE = `${MODEL_SIDE_CODES[0]}_PLANTED_BY_CUR118`;
      const firstRow = guide118.split('\n').find((line, k) => rows118.length > 0 && k + 1 === rows118[0].line) ?? '';
      const PLANTED_ROW = `${rows118[0]?.code ?? 'A00'}_ROW_PLANTED_BY_CUR118`;
      const plants118: Array<{ what: string; name: string; faults: string[] | null }> = [
        { what: 'a code added to the model side with no row', name: PLANTED_CODE, faults: faults118(guide118, [entries118[0], ['cli_core.ts build', [...entries118[1][1], PLANTED_CODE]]]) },
        {
          what: 'a row for a code neither entry prints',
          name: PLANTED_ROW,
          faults: firstRow === '' ? null : faults118(guide118.replace(firstRow, () => `${firstRow}\n${firstRow.replace(`\`${rows118[0].code}\``, () => `\`${PLANTED_ROW}\``)}`), entries118),
        },
      ];
      const plantCases118: string[] = [];
      for (const plant of plants118) {
        if (plant.faults === null) {
          probes118.push(`"${plant.what}": the guide had no row to copy, so this plant was never made`);
          continue;
        }
        const raised = plant.faults.filter((f) => !live118.includes(f));
        const named = raised.find((f) => f.includes(`\`${plant.name}\``));
        if (raised.length !== 1 || named === undefined) probes118.push(`"${plant.what}" (\`${plant.name}\`) raised [${raised.join('; ')}], where one fault naming it was required`);
        else plantCases118.push(`${plant.what} -> ${named}`);
      }
      const held118 = probes118.length === 0;
      say(
        'CUR118_EVERY_CODE_EITHER_ENTRYS_BUILD_REPORT_PRINTS_HAS_EXACTLY_ONE_GUIDE_ROW_AND_EVERY_ROW_IS_ONE',
        held118,
        probeDetail(
          held118,
          probes118,
          `${GUIDE118} §5.2 has ${rows118.length} row(s), one for each of the ${printed118.length} code(s) a build report prints — the ${ASSERTION_NAMES.length} of cli.ts build's ` +
            `and the ${truth.core.codes.length} of cli_core.ts build's, ${truth.core.codes.filter((code) => !ASSERTION_NAMES.includes(code)).length} of them outside the registry ` +
            `[${truth.core.codes.filter((code) => !ASSERTION_NAMES.includes(code)).join(', ')}] — each filed under the profile its kind runs it in; ` +
            `over ${plantCases118.length} plant(s): ${plantCases118.join('; ')}`,
        ),
        'issue #1183: the core entry printed two rules no shipped document named, so an agent meeting either as a FAIL on an install had no row to read — and the guide is the only map from a named failure to the file that has to change',
      );
    }
  }

  // --- CUR32–CUR34: a filesystem path derived from `URL.pathname` (#558) ----
  //
  // `URL.pathname` is percent-encoded. A checkout at `/Users/x/My Rigs/rigc`
  // makes `new URL('.', import.meta.url).pathname` say `/Users/x/My%20Rigs/…`,
  // which is not a path on disk — so every `readFileSync` built from it throws
  // `ENOENT` on a directory that exists, and every `mkdirSync` creates a
  // freshly-invented `My%20Rigs` sibling and writes the art into it. 25 sites
  // across 23 files were written that way: all seven gallery `make_parts.ts`
  // scripts the gallery READMEs tell a reader to run, and every art, spec, gif
  // and vote script of all three films.
  //
  // 🔒 **The scan is syntactic on purpose, and that is the whole argument for
  // it being a scan at all.** The honest measurement is to run a generator from
  // a path with a space in it — which is what found this (`bun run smoke`'s
  // unusual-path case, RELEASING.md *The plants are in the tool*) and what was
  // re-run by hand on `gallery/squash` when the repair landed. But that costs a
  // full art regeneration per script per run, and the property does not need
  // running to be decided: a `.pathname` read off a URL built from
  // `import.meta.url` is wrong wherever it appears, because that URL is always
  // a `file:` URL and its path component is always percent-encoded.
  //
  // ⚠️ **Two-sided, and the measurement changed what that had to mean.** The
  // card asked for a scan that does not fire on `new URL(...)` used as a URL,
  // "there is at least one legitimate use to look for" — and there is not one
  // in this tree: every `new URL(` outside these sites is either the repair
  // itself or prose about it. So the live population cannot demonstrate the
  // negative half and `CUR34` plants it instead, alongside the two shapes that
  // DO occur live and would fault a naive scan: `new URL(...).pathname` written
  // inside a comment, and written inside a template literal that carries source
  // for another file (`scripts/install_smoke.ts` has both, and its comment is
  // there precisely to warn the next author off this defect).
  //
  // 🔑 **The exclusion is derived, not typed.** Two of the 25 sites are in
  // landed run records under `bench/runs/`, which `bench/runs/README.md` seals
  // — final against editing under #181, repairable only as a labelled amendment
  // commit whose repair is verified by reproducing the run's own figures. A
  // hand-typed `bench/runs/` here would be a second copy of that ruling, free
  // to drift from it; `sealedSubtrees` reads the marker line the README shows
  // its reader, so the gate and the ruling are one object. `CUR33` requires the
  // exclusion to exclude something, which is what stops a marker becoming a way
  // to switch this off.
  {
    const listed = spawnSync('git', ['ls-files', '-z'], { cwd: root, encoding: 'buffer', maxBuffer: 256 * 1024 * 1024 });
    const treeFault =
      listed.error !== undefined || listed.status !== 0
        ? `git could not list the tracked files (${listed.error?.message ?? `exit ${String(listed.status)}: ${listed.stderr.toString('utf8').trim()}`})`
        : null;
    const tracked = treeFault === null ? listed.stdout.toString('utf8').split('\u0000').filter((entry) => entry !== '') : [];

    // The sealing markers, read off the tree's own markdown — the same parser
    // `runDocsQuoteSuite` reads them with, so a change to the rule reaches here.
    const markdown = new Map<string, string>();
    for (const rel of tracked) if (rel.endsWith('.md') && existsSync(join(root, rel))) markdown.set(rel, readFileSync(join(root, rel), 'utf8'));
    const sealed = sealedSubtrees(markdown);
    const sealedBy = (rel: string): { where: string; prefix: string; reason: string } | undefined =>
      sealed.prefixes.find((seal) => seal.prefix !== '' && rel.startsWith(seal.prefix));

    const scanned: string[] = [];
    const heldOut = new Map<string, string[]>();
    const sites: string[] = [];
    const blankFaults: string[] = [];
    for (const rel of tracked) {
      if (!/\.(?:ts|mjs|js)$/.test(rel) || !existsSync(join(root, rel))) continue;
      const seal = sealedBy(rel);
      if (seal !== undefined) {
        heldOut.set(seal.where, [...(heldOut.get(seal.where) ?? []), rel]);
        continue;
      }
      const text = readFileSync(join(root, rel), 'utf8');
      // The blanker has to be length- and line-preserving or every coordinate
      // it reports is a lie. Checked on the live population rather than argued.
      const code = blankCommentsAndStrings(text);
      if (code.length !== text.length || code.split('\n').length !== text.split('\n').length) {
        blankFaults.push(`${rel}: blanking changed the file's shape (${text.length}b/${text.split('\n').length}L became ${code.length}b/${code.split('\n').length}L), so every line number below it is wrong`);
      }
      scanned.push(rel);
      sites.push(...fileUrlPathSites(rel, text));
    }

    // --- CUR32: the scan ----------------------------------------------------
    {
      const probes = [
        ...(treeFault === null ? [] : [treeFault]),
        ...sealed.faults,
        ...blankFaults,
        ...firstFew(
          sites.map((site) => `${site} — \`URL.pathname\` is percent-encoded, so this is not a path on any checkout whose directory holds a space or a non-ASCII character; write \`fileURLToPath(new URL(…, import.meta.url))\`, or bun's \`import.meta.dir\` where no trailing slash is wanted`),
          'site(s)',
        ),
      ];
      const held = probes.length === 0;
      say(
        'CUR32_NO_SCRIPT_OUTSIDE_A_SEALED_SUBTREE_DERIVES_A_FILESYSTEM_PATH_FROM_URL_PATHNAME',
        held && scanned.length > 0,
        probeDetail(
          held && scanned.length > 0,
          probes,
          `${scanned.length} tracked .ts/.mjs/.js file(s), comments and string literals blanked, read for two forms — ` +
            '`new URL(…, import.meta.url).pathname`, and a binding of that URL whose `.pathname` is read later — and ' +
            `not one of them carries either. ${[...heldOut.values()].flat().length} file(s) held out by ` +
            `${sealed.prefixes.length} sealing marker(s): ${sealed.prefixes.map((seal) => `${seal.prefix} (${seal.where})`).join(', ')}`,
        ),
        'the gallery and film scripts read their own directory out of `URL.pathname` for 25 sites across 23 files, ' +
          'and a checkout under a directory with a space in it could not regenerate any of it — `bun run smoke`\'s ' +
          'unusual-path case found the shape in a generated fixture (#556) before anything looked for it in the ' +
          'tree. Running every generator from a hostile path is the honest measurement and costs a full art ' +
          'regeneration each time; the property is syntactic, so this reads it instead',
      );
    }

    // --- CUR33: that the scan reached the files it was written for ----------
    //
    // 🔒 `CUR01`'s argument. Every step above can come back empty — git listing
    // nothing, an extension filter that stops matching, a seal that swallows the
    // tree — and each of those makes `CUR32` pass over nothing while saying so
    // in a sentence nobody reads. The subjects are derived from the directory
    // listing, never from a count typed here, because a literal would be a
    // second copy of the population free to drift from the first.
    {
      const galleryRoot = join(root, 'gallery');
      const makers = existsSync(galleryRoot)
        ? readdirSync(galleryRoot)
            .filter((name) => existsSync(join(galleryRoot, name, 'make_parts.ts')))
            .sort()
            .map((name) => `gallery/${name}/make_parts.ts`)
        : [];
      const filmScripts = tracked.filter((rel) => rel.startsWith('films/') && /\.(?:ts|mjs|js)$/.test(rel));
      const seen = new Set(scanned);
      const missed = [...makers, ...filmScripts].filter((rel) => !seen.has(rel));
      const emptySeals = sealed.prefixes.filter((seal) => (heldOut.get(seal.where) ?? []).length === 0);
      const probes = [
        ...firstFew(missed.map((rel) => `${rel} is in the tree and CUR32 did not read it`), 'file(s)'),
        ...emptySeals.map(
          (seal) =>
            `${seal.where} seals \`${seal.prefix}\` and CUR32 held no file out for it — a marker that excludes ` +
            'nothing is a marker that could be pointed anywhere, which is how an exclusion becomes a switch',
        ),
        ...floorProbes(
          [
            [tracked.length, 1, `git listed ${tracked.length} tracked path(s)`],
            [scanned.length, 1, `${scanned.length} of them are .ts/.mjs/.js outside a sealed subtree and were scanned`],
            [makers.length, 1, `${makers.length} gallery example(s) carry a make_parts.ts`],
            [filmScripts.length, 1, `${filmScripts.length} script(s) live under films/`],
            [sealed.prefixes.length, 1, `${sealed.prefixes.length} sealing marker(s) were read off the tree's markdown`],
          ],
          'a step that comes back empty makes CUR32 read a clean tree off nothing',
        ),
      ];
      const held = probes.length === 0;
      say(
        'CUR33_THE_PATHNAME_SCAN_READ_EVERY_GALLERY_MAKER_AND_EVERY_FILM_SCRIPT',
        held,
        probeDetail(
          held,
          probes,
          `CUR32 read all ${makers.length} gallery generator(s) — ${makers.join(', ')} — and all ` +
            `${filmScripts.length} script(s) under films/, out of ${scanned.length} file(s) scanned; and each of the ` +
            `${sealed.prefixes.length} sealing marker(s) held at least one file out ` +
            `(${sealed.prefixes.map((seal) => `${seal.prefix} ${(heldOut.get(seal.where) ?? []).length}`).join(', ')})`,
        ),
        'these are the files the defect was in, so a scan that stops reaching them is the one failure that looks ' +
          'exactly like the repair holding',
      );
    }

    // --- CUR34: both sides of it, planted --------------------------------
    //
    // ⭐ The live site is re-planted rather than imagined: the victim is the
    // first gallery generator CUR32 scanned, and the plant is its own repaired
    // line put back the way #558 found it. Nothing here is a literal path.
    {
      const victim = scanned.find((rel) => /^gallery\/[^/]+\/make_parts\.ts$/.test(rel));
      const faults: string[] = [];
      let note = '';
      if (victim === undefined) faults.push('no gallery generator was scanned, so the re-plant below had nothing to aim at');
      else {
        const clean = readFileSync(join(root, victim), 'utf8');
        const REPAIRED = /fileURLToPath\(new URL\((.*?), import\.meta\.url\)\)/;
        const found = REPAIRED.exec(clean);
        if (found === null) {
          faults.push(`${victim} no longer spells its own directory with \`fileURLToPath(new URL(…, import.meta.url))\`, so the re-plant cannot be derived from it`);
        } else {
          const replanted = clean.replace(REPAIRED, `new URL(${found[1]}, import.meta.url).pathname`);
          const one = (name: string, path: string, text: string, want: number): void => {
            const got = fileUrlPathSites(path, text);
            if (got.length !== want) {
              faults.push(
                `the ${name} probe was reported ${got.length} time(s) and this control requires ${want}` +
                  (got.length === 0 ? '' : ` — it said: ${got.join('; ')}`),
              );
            }
          };
          one('untouched live file', victim, clean, 0);
          one('re-planted live file', victim, replanted, 1);
          // The negative half, which the live tree cannot supply: after the
          // repair nothing in it reads `.pathname` at all, legitimately or not.
          one('direct defect', 'probe.ts', "const HERE = new URL('.', import.meta.url).pathname;", 1);
          one('bound defect', 'probe.ts', "const here = new URL('.', import.meta.url);\nconst HERE = here.pathname;", 1);
          one('the repair', 'probe.ts', "const HERE = fileURLToPath(new URL('.', import.meta.url));", 0);
          one('bun\'s own spelling', 'probe.ts', 'const HERE = import.meta.dir;', 0);
          one('a URL used as a URL', 'probe.ts', 'const route = new URL(request.url).pathname;', 0);
          one('a URL bound and used as a URL', 'probe.ts', 'const u = new URL(request.url);\nconst route = u.pathname;', 0);
          one('the defect in a line comment', 'probe.ts', "// never `new URL('.', import.meta.url).pathname`\nconst HERE = import.meta.dir;", 0);
          one('the defect in a block comment', 'probe.ts', "/* new URL('.', import.meta.url).pathname */\nconst HERE = import.meta.dir;", 0);
          one('the defect inside a template literal', 'probe.ts', 'const SRC = `const H = new URL(".", import.meta.url).pathname;`;', 0);
          // A regex holding a lone quote used to open a string that swallowed
          // the rest of the file, and a scan that has gone quiet looks green.
          one('a defect after a regex holding a quote', 'probe.ts', "const q = /'/;\nconst HERE = new URL('.', import.meta.url).pathname;", 1);
          const at = replanted.split('\n').findIndex((line) => /new URL\(.*import\.meta\.url\)\.pathname/.test(line)) + 1;
          note =
            `\`${victim}\` reads clean, and the same file with its one repaired line put back the way #558 found ` +
            `it is reported once, at line ${at}; a bound URL is reported too, while the repair, \`import.meta.dir\`, ` +
            'a URL genuinely used as a URL (bound or not), the defect written inside a line comment, a block ' +
            'comment or a template literal, are each reported in no way — and a defect following a regex that ' +
            'holds a lone quote is still reported, which is the blanker not swallowing the file';
        }
      }
      const held = faults.length === 0;
      say(
        'CUR34_THE_PATHNAME_SCAN_FIRES_ON_THE_DEFECT_AND_ON_NOTHING_THAT_MERELY_LOOKS_LIKE_IT',
        held,
        probeDetail(held, faults, `the controls: ${note}`),
        'a scan is a vocabulary of forms, and both directions fail silently: a form that stops matching the defect ' +
          'goes quiet rather than red (`CUR06`), and a form loose enough to fault a comment, a template of ' +
          'generated source, or a URL doing a URL\'s job is one every author learns to work around',
      );
    }

    // --- CUR116: the blanker's bounded look-behind is the whole-prefix one ----
    //
    // Issue #1121. The blanker used to copy and trim the whole prefix before
    // every `/` to ask what precedes it — on this file, 41 s and an 879 MB
    // high-water per call, the `currency` suite's peak. It now reads the last
    // `REGEX_LOOK_BEHIND` characters. That is equal by argument (the regex is
    // anchored at the end and its longest alternative is that long, `\b`
    // included), and this holds the argument by measurement: on every file
    // CUR32 scanned except this one, the bounded reading against the reading it
    // replaced, verbatim; on this one — where the old reading costs what the
    // card was opened over — against a window four times as wide, which can only
    // differ if the bound is too short. Plants: a window one character short on
    // a probe whose keyword is glued to a word, which must differ from the whole
    // prefix, and every keyword written both ways, which must not.
    {
      const self = relative(root, import.meta.path);
      const faults: string[] = [];
      let compared = 0;
      for (const rel of scanned) {
        if (rel === self) continue;
        const text = readFileSync(join(root, rel), 'utf8');
        if (blankCommentsAndStrings(text) !== blankCommentsAndStrings(text, Infinity)) faults.push(`${rel}: the bounded look-behind blanks it differently from the whole prefix`);
        compared++;
      }
      const selfScanned = scanned.includes(self);
      if (!selfScanned) faults.push(`${self} was not among the files CUR32 scanned, so the largest population was not read`);
      else {
        const text = readFileSync(join(root, self), 'utf8');
        if (blankCommentsAndStrings(text) !== blankCommentsAndStrings(text, 4 * REGEX_LOOK_BEHIND)) {
          faults.push(`${self}: a window of ${REGEX_LOOK_BEHIND} blanks it differently from one of ${4 * REGEX_LOOK_BEHIND}, so the bound is too short`);
        }
      }
      const longest = REGEX_OPENING_KEYWORDS.reduce((a, b) => (b.length > a.length ? b : a));
      const glued = `const a = x${longest} /'/;\nconst b = 'kept';\n`;
      const short = blankCommentsAndStrings(glued, REGEX_LOOK_BEHIND - 1) !== blankCommentsAndStrings(glued, Infinity);
      if (!short) faults.push(`a window of ${REGEX_LOOK_BEHIND - 1} on "x${longest} /'/" blanks it as the whole prefix does, so the probe cannot see a bound that is too short`);
      for (const word of REGEX_OPENING_KEYWORDS) {
        for (const probe of [`v = ${word} /'/;\nw = 'q';\n`, `v = z${word} /'/;\nw = 'q';\n`, `v = ${word}\t /x/;\n`]) {
          if (blankCommentsAndStrings(probe) !== blankCommentsAndStrings(probe, Infinity)) faults.push(`the probe ${JSON.stringify(probe)} blanks differently under the bound`);
        }
      }
      if (compared === 0) faults.push('no file was compared against the whole-prefix reading');
      const held = faults.length === 0;
      say(
        'CUR116_THE_BLANKERS_BOUNDED_LOOK_BEHIND_BLANKS_EXACTLY_AS_THE_WHOLE_PREFIX_DID',
        held,
        probeDetail(
          held,
          faults,
          `${compared} scanned file(s) blank identically under the ${REGEX_LOOK_BEHIND}-character look-behind and the whole prefix; ` +
            `${self} identically under ${REGEX_LOOK_BEHIND} and ${4 * REGEX_LOOK_BEHIND}; a window of ${REGEX_LOOK_BEHIND - 1} on ` +
            `"x${longest} /'/" differs from the whole prefix, and all ${REGEX_OPENING_KEYWORDS.length} keyword(s), spaced, glued and ` +
            'tab-separated, do not',
        ),
        'issue #1121: the whole-prefix reading made one call on this file cost 41 s and an 879 MB high-water, and the ' +
          'currency suite\'s peak was that call; a bound is only a fix if it decides every `/` the way the whole prefix did',
      );
    }
  }

  // --- CUR35-38: the authoring guide against the keys the parsers accept ----
  //
  // ⭐ `CUR17` derives the key TABLES from the interfaces and `CUR18` requires
  // something outside the declaration to name each key. Neither asks the
  // question `CLAUDE.md` asks — the guide and the validator's messages "are the
  // only interface an agent that cannot see the rig actually has" — which is
  // whether the guide names the key at all. Issue #676 measured it and found
  // eleven that it did not: a `ring` generator's `center`, `inner` and
  // `controls`, its `bias`'s `axis_deg`, a detached rule's `notUnder`, and six
  // of a physics constraint's seven `*Global` flags. Every one of them parses,
  // emits, and could only be learnt by reading `src/rig.ts`.
  //
  // 🔒 **Both directions, because they fail differently.** A key the guide never
  // names is an affordance nobody can reach. A field the guide lists that no
  // shape declares is the opposite and worse: an author who writes it gets the
  // unknown-key refusal from the file the guide told them to write it in.
  //
  // ⚠️ **What this cannot see, stated rather than implied.** The question is
  // "does the word occur", so:
  //
  //  - a key named ANYWHERE counts — in prose, in a fenced example, in a quoted
  //    error message, in a sentence about something else entirely. `bias` and
  //    `ramp` were named on the day #676 was filed only by the depth map's own
  //    `bias` row and by prose about falloff ramps, neither of which is about a
  //    ring's `bias` at all, and both read as named here.
  //  - a key named in the WRONG section is invisible for the same reason.
  //  - the second direction resolves a field against the union of every shape's
  //    keys rather than against the shape its own `####` section documents, so a
  //    field listed under the wrong generator passes. Resolving per section would
  //    need a heading-to-shape map, which is a second copy of `GENERATOR_SHAPE`
  //    kept by hand — the antipattern this file exists to refuse.
  //  - the one-letter keys (`x`, `y`, `t`, `v`) are named by almost any English
  //    sentence, so the first direction is weakest exactly where the key is
  //    shortest. It is a floor under the guide, not a proof of it.
  {
    /** The guide `CLAUDE.md` calls the interface an authoring agent has. */
    const GUIDE = 'docs/AUTHORING.md';
    const guideDoc = docs.find((doc) => doc.path === GUIDE);
    const guideText = guideDoc === undefined ? '' : guideDoc.raw.join('\n');
    const sets: Array<[string, readonly string[]]> = [...Object.entries(RIG_KEYS), ...Object.entries(MOTION_KEYS)];
    const shapesOf = (key: string): string[] => sets.filter(([, keys]) => keys.includes(key)).map(([shape]) => shape);

    /** Does this text name this key at all — any section, prose or example? */
    const names = (text: string, key: string): boolean => new RegExp(`\\b${literalPattern(key)}\\b`).test(text);

    /** The distinct keys of a key table that a text never names, sorted. */
    const unnamedIn = (text: string, table: ReadonlyArray<readonly [string, readonly string[]]>): string[] =>
      [...new Set(table.flatMap(([, keys]) => keys))].sort().filter((key) => !names(text, key));

    /**
     * Every field a `| Field | …` table under a `####` heading names, with the
     * heading it sits under and the line it is on.
     *
     * Only the FIRST column is read — the second is prose and routinely spells
     * another key — and a cell may name several (`us` / `vs`), so the row is the
     * backticked identifier rather than the line. Fenced lines are dropped
     * through `linesOutsideFences`, so a `####` inside a transcript is not a
     * heading and a table inside one is not a field list.
     */
    const fieldRows = (text: string): Array<{ heading: string; line: number; field: string }> => {
      const out: Array<{ heading: string; line: number; field: string }> = [];
      let heading: string | null = null;
      let inTable = false;
      for (const [i, line] of linesOutsideFences(text.split('\n')).entries()) {
        if (line === null) continue;
        const head = /^(#{1,6}) (.*)$/.exec(line);
        if (head !== null) {
          // `####` or below: a field table may sit under a deeper heading too (`soft`, a ##### under §3.4.6), and a
          // reader that stops at #### would drop it silently.
          heading = head[1].length >= 4 ? head[2] : null;
          inTable = false;
          continue;
        }
        if (heading === null) continue;
        if (/^\| *Field *\|/.test(line)) {
          inTable = true;
          continue;
        }
        if (!inTable) continue;
        if (!line.startsWith('|')) {
          inTable = false;
          continue;
        }
        if (/^\| *-+/.test(line)) continue;
        for (const found of (line.split('|')[1] ?? '').matchAll(/`([^`]+)`/g)) {
          if (/^[A-Za-z_][A-Za-z\d_]*$/.test(found[1])) out.push({ heading, line: i + 1, field: found[1] });
        }
      }
      return out;
    };

    const unnamed = unnamedIn(guideText, sets);
    const everyKey = [...new Set(sets.flatMap(([, keys]) => keys))];
    const rows = fieldRows(guideText);
    const headings = [...new Set(rows.map((row) => row.heading))];
    const known = new Set(everyKey);
    const strayRows = rows.filter((row) => !known.has(row.field));
    const missing =
      guideDoc === undefined
        ? [`${GUIDE} is not one of the ${docs.length} document(s) this scan reads, so nothing below compared anything`]
        : [];

    // --- CUR35: every key the parser accepts is named in the guide ----------
    {
      const probes = [
        ...missing,
        ...floorProbes(
          [
            [sets.length, 1, `${sets.length} key set(s) were read off the two parsers' own tables`],
            [everyKey.length, 1, `${everyKey.length} distinct key(s) across them`],
            [guideDoc?.raw.length ?? 0, 1, `${guideDoc?.raw.length ?? 0} line(s) of ${GUIDE} were read`],
          ],
          'a step that comes back empty makes this read a complete guide off nothing',
        ),
        ...firstFew(
          unnamed.map(
            (key) =>
              `\`${key}\` (${shapesOf(key).join(', ')}) is a key the parser accepts and ${GUIDE} never names it — ` +
              'an author reading the guide has no way to learn the field exists, and writing anything else in its ' +
              'place is refused as an unknown key',
          ),
          'key(s)',
        ),
      ];
      const held = probes.length === 0;
      say(
        'CUR35_EVERY_SPEC_KEY_THE_PARSER_ACCEPTS_IS_NAMED_BY_THE_AUTHORING_GUIDE',
        held,
        probeDetail(
          held,
          probes,
          `all ${everyKey.length} distinct key(s) of the ${sets.length} shape(s) the two formats declare — ` +
            `${Object.keys(RIG_KEYS).length} rig, ${Object.keys(MOTION_KEYS).length} motion — are named somewhere ` +
            `in the ${guideDoc?.raw.length ?? 0} line(s) of ${GUIDE}`,
        ),
        'the guide and the refusals are the whole interface an agent that cannot see the rig has, so a field only ' +
          '`src/rig.ts` names is a field only a reader of the source can use. #676 found eleven, and the one that ' +
          'shows what the silence costs is `RigDetachedRule.notUnder`: the field that says what the parentage may ' +
          'not be, in the block whose whole purpose is to say it',
      );
    }

    // --- CUR36: the first direction, planted both ways ----------------------
    //
    // 🌱 The plant goes into a COPY of the key table rather than into
    // `src/rig.ts`, so nothing on disk moves and the run stays deterministic;
    // what it breaks is the data the verdict reads, which is the same edit an
    // author makes when a field is added.
    {
      const planted: Array<[string, readonly string[]]> = [...sets, ['ProbeShape', ['zzPlantedSpecKey']]];
      const raised = raisedBy(unnamedIn(guideText, planted), { was: unnamed });
      const anchor = rows.length > 0 ? rows[0].field : null;
      const faults = [
        ...missing,
        ...(raised.length === 0
          ? [
              'a key planted into a copy of the parser key table was not faulted as unnamed, so a shape could grow ' +
                'a field the guide never mentions and this stays green',
            ]
          : []),
        ...(names(guideText, 'zzNoSuchSpecKey')
          ? ['a name no line of the guide carries was reported as named, so this search matches anything']
          : []),
        ...(anchor === null
          ? ['the guide gave up no field row, so there was no key known to be named to drive the other direction']
          : names(guideText, anchor)
            ? []
            : [`\`${anchor}\` is a field the guide's own table names and the search reported it unnamed`]),
        ...(names('the tolerances are generous', 'tolerance')
          ? ['a key was reported named by a longer word that merely starts with it, so the match is not on words']
          : []),
        ...(names('```json\n"zzFencedOnly": 1\n```', 'zzFencedOnly')
          ? []
          : [
              'a key named only inside a fenced example was reported unnamed, so this control no longer measures ' +
                'the scope the clean verdict is stated at',
            ]),
      ];
      const held = faults.length === 0;
      say(
        'CUR36_THE_KEY_SCAN_FAULTS_A_KEY_THE_GUIDE_LACKS_AND_PASSES_ONE_IT_CARRIES',
        held,
        probeDetail(
          held,
          faults,
          `a key added to a copy of the ${sets.length}-shape table is reported unnamed and nothing else is; a name ` +
            `no line of the guide carries reads unnamed; \`${anchor ?? '—'}\`, which the guide's own field table ` +
            'names, reads named; a longer word that merely starts with a key does not name it; and a key written ' +
            'only inside a fenced example does — which is the scope the clean run above claims and no more',
      ),
        'a scan whose matcher is too loose reports every key named and goes quiet for good, and one too tight ' +
          'reports a guide that is complete as full of holes; the two are told apart only by driving it over an ' +
          'answer that is known',
      );
    }

    // --- CUR37: every field the guide lists is a key the parser accepts -----
    {
      const probes = [
        ...missing,
        ...floorProbes(
          [
            [headings.length, 1, `${headings.length} \`####\` section(s) of ${GUIDE} carry a field table`],
            [rows.length, 1, `${rows.length} field row(s) were read out of them`],
          ],
          'a reader that stops matching the guide\'s own tables checks nothing and says so nowhere',
        ),
        ...firstFew(
          strayRows.map(
            (row) =>
              `${GUIDE} line ${row.line} lists \`${row.field}\` as a field under "${row.heading}" and no shape of ` +
              'either format declares it — an author who writes it gets `has N keys this compiler does not read`, ' +
              'from the guide that told them to',
          ),
          'row(s)',
        ),
      ];
      const held = probes.length === 0;
      say(
        'CUR37_EVERY_FIELD_THE_GUIDE_LISTS_IS_A_KEY_ONE_OF_THE_TWO_FORMATS_DECLARES',
        held,
        probeDetail(
          held,
          probes,
          `all ${rows.length} field row(s) under the ${headings.length} \`####\` section(s) of ${GUIDE} that carry ` +
            `a field table name keys the parsers accept (${headings.join('; ')})`,
        ),
        'the direction that costs an author a loop rather than an affordance: a field list is what a spec gets ' +
          'written from, so a row nothing declares is a refusal the guide walked the author into. It resolves ' +
          'against the union of every shape\'s keys and not against the section\'s own shape, so a field in the ' +
          'wrong `####` section passes — that blind spot is the price of not keeping a heading-to-shape map by hand',
      );
    }

    // --- CUR38: the field reader, planted on text this case writes ----------
    {
      const table = (heading: string, cell: string): string =>
        `${heading}\n\n| Field | Meaning |\n| --- | --- |\n| ${cell} | planted by this control |\n`;
      const fieldsOf = (text: string): string[] => fieldRows(text).map((row) => row.field);
      const plantedGuide = `${guideText}\n${table('#### `probe`', '`zzPlantedGuideField`')}`;
      const raised = raisedBy(
        fieldRows(plantedGuide)
          .filter((row) => !known.has(row.field))
          .map((row) => `${row.field}@${row.heading}`),
        { was: strayRows.map((row) => `${row.field}@${row.heading}`) },
      );
      const fenced = `\`\`\`\n${table('#### `probe`', '`zzFencedField`')}\`\`\`\n`;
      const faults = [
        ...missing,
        ...(raised.length === 0
          ? [
              'a field row planted into a copy of the guide was not faulted as a key no shape declares, so the ' +
                'guide could grow a row for a field that does not exist and this stays green',
            ]
          : []),
        ...(fieldsOf(table('### `probe`', '`zzThirdLevel`')).includes('zzThirdLevel')
          ? ['a field table under a `###` heading was read, and the population this case states is `####` sections']
          : []),
        ...(fieldsOf(fenced).includes('zzFencedField')
          ? ['a field table inside a fence was read, so a transcript of a guide would be scanned as the guide']
          : []),
        ...(fieldsOf(table('#### `probe`', '`alpha` | `zzMeaningColumn`')).includes('zzMeaningColumn')
          ? ['the Meaning column was read as a field list, and it is prose that routinely spells another key']
          : []),
        ...(fieldsOf(table('#### `probe`', '`us` / `vs`')).join(',') === 'us,vs'
          ? []
          : [
              `a cell naming two fields was read as ${JSON.stringify(fieldsOf(table('#### \`probe\`', '`us` / `vs`')))}` +
                ' — the guide writes `us` / `vs` and `cols` / `rows` in one cell each, so a reader that takes one ' +
                'per row misses half of them',
            ]),
        ...(fieldsOf(table('#### `probe`', '`alpha`')).includes('alpha')
          ? []
          : ['a one-field table this control wrote was not read at all, so every negative result above is vacuous']),
      ];
      const held = faults.length === 0;
      say(
        'CUR38_THE_FIELD_READER_TAKES_THE_GUIDES_OWN_TABLES_AND_NOTHING_THAT_LOOKS_LIKE_ONE',
        held,
        probeDetail(
          held,
          faults,
          'a row planted into a copy of the guide is reported and nothing else is; a one-field table is read; and ' +
            'a table under a `###` heading, a table inside a fence and a key spelled in the Meaning column are ' +
            'each read in no way, while a cell naming two fields is read as two',
        ),
        'the reader is the whole of what `CUR37` measures, and every way it can go wrong is silent: a heading rule ' +
          'that widens swallows report-field tables that were never spec keys, one that narrows leaves the ' +
          'generator sections unread, and either way the verdict above still prints green',
      );
    }
  }

  // --- CUR39–CUR41: the doctrine, and a symbol stated as a number (#677) -----
  //
  // ⭐ **Both plants are a live document's own sentence, put back the way this
  // landing found it**, which is `CUR34`'s bar: a control whose victim is
  // invented proves the form matches the control's imagination. The line is
  // located by asking the SCANNER where it reads a site, never by a second copy
  // of its forms or by a path written here — so a form that stops matching takes
  // the plant's own line away and these go red rather than quiet.
  //
  // 🔑 The two cases are separate because they answer different questions. The
  // doctrine's is *is this document in the scanned set at all* — it is in neither
  // derived tier, and for the whole life of this gate it was outside. The
  // symbol's is *does the vocabulary reach this shape* — `docs/BENCHMARK.md`
  // stated `ASSERTION_NAMES.length` as 40 and `assertionCountForProfile('spine')`
  // as 25 while the scan read eighteen tallies on the same page and stayed green.
  {
    const scanOf = (doc: CurrencyDoc): CurrencyScan => scanAssertionTallies(doc, truth);
    /** The first line of a document at which a named limb reads a site, asked of the scanner itself. */
    const firstSiteAt = (doc: CurrencyDoc, limb: string): number =>
      doc.raw.findIndex((line) => (scanOf(readCurrencyDoc(doc.path, doc.tier, line)).sites.get(limb) ?? 0) > 0);
    /** The same document with one line rewritten, read back through the same reader the scan uses. */
    const rewritten = (doc: CurrencyDoc, at: number, line: string): CurrencyDoc =>
      readCurrencyDoc(doc.path, doc.tier, doc.raw.map((was, i) => (i === at ? line : was)).join('\n'));

    // --- CUR39: the doctrine is one of the documents this scan reads ---------
    {
      const faults: string[] = [];
      let note = '';
      const doctrine = docs.find((doc) => doc.path === CURRENCY_DOCTRINE);
      if (doctrine === undefined) {
        faults.push(`${CURRENCY_DOCTRINE} is not in the scanned set, so there was nothing here to plant on`);
      } else {
        const at = firstSiteAt(doctrine, 'tally:the assertion registry');
        if (at < 0) {
          faults.push(
            `${CURRENCY_DOCTRINE} states the registry's size on no single line, so this plant has nothing to aim ` +
              'at — the sentence used to wrap between the number and its noun, and a limb that reads one line at a ' +
              'time saw nothing there',
          );
        } else {
          const standing = scanOf(doctrine).faults;
          if (standing.length > 0) {
            faults.push(`${CURRENCY_DOCTRINE} as it stands is faulted by this scan: ${standing.join('; ')}`);
          }
          const planted = rewritten(
            doctrine,
            at,
            doctrine.raw[at].replace(String(truth.total), String(truth.total + 1)),
          );
          const raised = raisedBy(scanOf(planted).faults, {
            was: standing,
            at: `${CURRENCY_DOCTRINE}:${at + 1}`,
          });
          if (raised.length !== 1) {
            faults.push(
              `the stale registry figure planted at ${CURRENCY_DOCTRINE}:${at + 1} was not faulted — this scan ` +
                `raised ${raised.length} fault(s) there` +
                (raised.length === 0 ? '' : `: ${raised.join('; ')}`),
            );
          }
          note =
            `${CURRENCY_DOCTRINE} is read as \`${doctrine.tier}\` and reads clean; its own registry sentence, at ` +
            `line ${at + 1}, with ${truth.total} put back as ${truth.total + 1}, is reported once — ` +
            `"${raised.join('; ')}"`;
        }
      }
      const held = faults.length === 0;
      say(
        'CUR39_THE_DOCTRINE_IS_ONE_OF_THE_DOCUMENTS_THIS_SCAN_READS',
        held,
        probeDetail(held, faults, note),
        'the document that most insists a claim be derived was the one document whose own figures were kept by ' +
          'hand: `CLAUDE.md` is not in `files` and the README linked it nowhere, so neither derived tier reached ' +
          'it, and its halves clause stated figures the run had not printed for weeks. Membership is the whole of ' +
          'what this asks, and it asks it by planting rather than by naming the set, because a tier that lists a ' +
          'path and reads nothing under it looks exactly like this passing',
      );
    }

    // --- CUR40: an exported symbol stated as a number ------------------------
    {
      const faults: string[] = [];
      const notes: string[] = [];
      const host = docs.find((doc) => firstSiteAt(doc, 'exported symbol') >= 0);
      if (host === undefined) {
        faults.push('no document in the scanned set states an exported symbol as a number, so nothing was planted');
      } else {
        const standing = scanOf(host).faults;
        if (standing.length > 0) {
          faults.push(`${host.path} as it stands is faulted by this scan: ${standing.join('; ')}`);
        }
        for (const symbol of CURRENCY_EXPORTED_SYMBOLS) {
          const said = `\`${symbol.spelling}\` is ${symbol.of(truth)}`;
          const at = host.raw.findIndex((line) => line.includes(said));
          if (at < 0) {
            faults.push(
              `${host.path} does not state \`${symbol.spelling}\` as ${symbol.of(truth)} on any line, so the ` +
                'plant for it could not be derived from the page',
            );
            continue;
          }
          const planted = rewritten(
            host,
            at,
            host.raw[at].replace(said, `\`${symbol.spelling}\` is ${symbol.of(truth) + 1}`),
          );
          const raised = raisedBy(scanOf(planted).faults, { was: standing, at: `${host.path}:${at + 1}` });
          if (raised.length !== 1) {
            faults.push(
              `\`${symbol.spelling}\` stated one too high at ${host.path}:${at + 1} was not faulted — this scan ` +
                `raised ${raised.length} fault(s) there` +
                (raised.length === 0 ? '' : `: ${raised.join('; ')}`),
            );
            continue;
          }
          if (!raised[0].includes(symbol.quantity)) {
            faults.push(
              `the fault raised at ${host.path}:${at + 1} does not name ${symbol.quantity}, so the message sends a ` +
                `reader to the wrong quantity: ${raised[0]}`,
            );
          }
          notes.push(`"${raised[0]}"`);
        }
      }
      const held = faults.length === 0;
      say(
        'CUR40_AN_EXPORTED_SYMBOL_A_DOC_STATES_A_VALUE_FOR_IS_THE_VALUE_THE_MODULE_ANSWERS_WITH',
        held,
        probeDetail(
          held,
          faults,
          `${host === undefined ? 'no page' : host.path} states ${CURRENCY_EXPORTED_SYMBOLS.length} exported ` +
            `symbol(s) as numbers and reads clean; each one put back one too high is reported on its own line and ` +
            `against its own quantity — ${notes.join(', ')}`,
        ),
        'the page that went stale is the one explaining why these two numbers are exported rather than written in ' +
          'prose, four lines under a table that has them right. Every other form in this suite reads a number ' +
          'beside a NOUN, and a sentence naming the code it could have run matched none of them',
      );
    }

    // --- CUR41: the symbol form against the shapes it must not read ----------
    //
    // 🔒 `CUR34`'s other half, on this form. A form loose enough to read any
    // sentence with a number in it would fault on prose nobody can rewrite, and
    // one narrow enough to read only the live spelling would go quiet the day
    // somebody bolds the figure — which is how the tree writes half its tallies.
    {
      const faults: string[] = [];
      const registry = CURRENCY_EXPORTED_SYMBOLS[0];
      const profile = CURRENCY_EXPORTED_SYMBOLS[1];
      const one = (name: string, text: string, wantSites: number, wantFaults: number): void => {
        const found = scanOf(readCurrencyDoc('probe.md', 'landing', text));
        const sites = found.sites.get('exported symbol') ?? 0;
        if (sites !== wantSites || found.faults.length !== wantFaults) {
          faults.push(
            `the ${name} probe was read at ${sites} site(s) and faulted ${found.faults.length} time(s), and this ` +
              `control requires ${wantSites} and ${wantFaults}` +
              (found.faults.length === 0 ? '' : ` — it said: ${found.faults.join('; ')}`),
          );
        }
      };
      one('value the module answers with', `\`${registry.spelling}\` is ${truth.total}.`, 1, 0);
      one('stale value', `\`${registry.spelling}\` is ${truth.total + 1}.`, 1, 1);
      one('same sentence in bold', `\`${registry.spelling}\` is **${truth.total + 1}**.`, 1, 1);
      // Each symbol against its OWN quantity: the registry's number under the
      // profile's symbol is a number the page holds somewhere, and a form with
      // one truth behind it would pass it.
      one("profile symbol carrying the registry's number", `\`${profile.spelling}\` is ${truth.total}.`, 1, 1);
      one('profile symbol carrying its own', `\`${profile.spelling}\` is ${truth.spine}.`, 1, 0);
      one('symbol this table does not know', `\`${registry.identifier}.size\` is ${truth.total + 1}.`, 0, 0);
      one('number with no symbol in front of it', `the registry is ${truth.total + 1}.`, 0, 0);
      one('symbol stated without a value', `\`${registry.spelling}\` is the registry's own count.`, 0, 0);
      one('symbol and a number further along the line', `\`${registry.spelling}\` — the table says ${truth.total + 1}.`, 0, 0);
      // The escape hatch reaches this limb exactly as it reaches limbs 1–3: a
      // page that declares itself a dated record states figures as of its date.
      one(
        'stale value on a page that declared a dated record',
        `# Probe\n\n${DATED_RECORD_MARKER}\n\nMeasured 2026-08-22.\n\n\`${registry.spelling}\` is ${truth.total + 1}.`,
        0,
        0,
      );
      const held = faults.length === 0;
      say(
        'CUR41_THE_SYMBOL_FORM_FIRES_ON_THE_DEFECT_AND_ON_NOTHING_THAT_MERELY_LOOKS_LIKE_IT',
        held,
        probeDetail(
          held,
          faults,
          `the true value and the bare symbol are read and pass, one too high is reported bold or plain, and each ` +
            `symbol is compared against its own quantity — \`${profile.spelling}\` stating ${truth.total} is a ` +
            `fault. A symbol this table does not carry, a number with no symbol in front of it, the symbol with no ` +
            `number after it, a number further along the line, and the stale sentence on a page that declared a ` +
            `dated record are each read at no site at all`,
        ),
        'a form that reads a raw line is reading markup, and both directions fail silently there: narrowed to one ' +
          'spelling it goes quiet on the next author who bolds the figure, and loosened to "a number near a code ' +
          'span" it faults on prose and earns itself an exception table, which is the defect this suite gates for',
      );
    }
  }

  // --- CUR42–CUR44: the guide's typed attachment tables, and the uv corner ---
  //
  // ⭐ **Why `CUR37` is not already doing this.** It reads a field table only
  // under a `####` heading, and §3.4's attachment tables sit under a `###` one —
  // measured on the branch point at 53 rows under 8 sections, not one of them
  // §3.4's. So the guide's oldest field tables have never been held by anything,
  // and an agent authoring from them was reading a list nothing checked. The
  // exam sitting that filed this reconstructed a clipping attachment out of two
  // refusal rows and a round-trip note because §3.4 named the type nowhere.
  //
  // 🔒 **And the hold here is tighter than `CUR37`'s, in the one way that
  // matters.** `CUR37` resolves a field against the union of every shape's keys,
  // so a field listed under the wrong type passes; the price of that is stated in
  // its own case, and it is the price of not keeping a heading-to-shape map by
  // hand. This keeps no map either — it asks the PARSER what it accepts for that
  // `type`, by handing it an attachment carrying a key no shape declares and
  // reading the `Known here:` list out of the refusal — so both directions are
  // exact: a key the parser grows without a row is a fault, and a row naming a
  // key the parser refuses is a fault.
  {
    const GUIDE = 'docs/AUTHORING.md';
    const guideDoc = docs.find((doc) => doc.path === GUIDE);
    const guideRaw: readonly string[] = guideDoc?.raw ?? [];
    /** A key no shape of either format declares, planted to make the parser list what it does declare. */
    const UNDECLARED = 'zzKeyNoShapeDeclares';

    /** Every backticked identifier in one table cell. */
    const identifiersIn = (cell: string): string[] =>
      [...cell.matchAll(/`([^`]+)`/g)].map((found) => found[1]).filter((word) => /^[A-Za-z_][A-Za-z\d_]*$/.test(word));

    /**
     * Every `| Field | Meaning |` table the guide attaches to an attachment
     * `"type"`, with the fields its FIRST column names.
     *
     * The anchor is the type spelled the way a spec spells it — `"type": "x"` in
     * a code span — and it is dropped again at the next heading, so a table under
     * a later section cannot inherit an anchor from an earlier one. Only the first
     * column is read: the second is prose and routinely spells another key.
     */
    const typedTables = (raw: readonly string[]): Array<{ type: string; at: number; fields: string[] }> => {
      const lines = linesOutsideFences(raw);
      const out: Array<{ type: string; at: number; fields: string[] }> = [];
      let anchor: { type: string; at: number } | null = null;
      for (const [i, line] of lines.entries()) {
        if (line === null) continue;
        if (/^#{1,6} /.test(line)) {
          anchor = null;
          continue;
        }
        // An anchor is a section's own intro line. The same spelling inside a
        // TABLE ROW is prose about a type — §5.1's refusal table carries one,
        // `give that slot a "type": "path" attachment` — and anchoring on it
        // would hand the next field table to whatever type that row named.
        const named = line.startsWith('|') ? null : /`"type": "([a-z]+)"`/.exec(line);
        if (named !== null) anchor = { type: named[1], at: i + 1 };
        if (!/^\| *Field *\|/.test(line) || anchor === null) continue;
        const fields: string[] = [];
        for (let at = i + 1; at < lines.length; at++) {
          const row = lines[at];
          if (row === null || !row.startsWith('|')) break;
          if (/^\| *-+/.test(row)) continue;
          fields.push(...identifiersIn(row.split('|')[1] ?? ''));
        }
        out.push({ type: anchor.type, at: anchor.at, fields });
        anchor = null;
      }
      return out;
    };

    /**
     * What the parser itself says it accepts on an attachment of this `type`,
     * read out of the refusal it raises over a key no shape declares.
     *
     * Asking the compiler rather than indexing a table is what makes this need no
     * type-to-shape map: the map is `src/rig.ts`'s own, and a `type` it stopped
     * recognising comes back `null` here rather than silently resolving elsewhere.
     */
    const acceptedFor = (type: string): string[] | null => {
      const probe = { spec: RIG_SPEC_VERSION, skins: { default: { s: { p: { type, [UNDECLARED]: 1 } } } } };
      try {
        parseRigSpec(probe, 'probe');
      } catch (error) {
        const said = error instanceof Error ? error.message : String(error);
        const found = /Known here: ([^.]+)\./.exec(said);
        if (found !== null) return found[1].split(', ');
      }
      return null;
    };

    /** The shapes that carry a polygon — the ones a `####` section has never documented. */
    const rigSets: Array<[string, readonly string[]]> = Object.entries(RIG_KEYS);
    const polygonShapes = rigSets.filter(([, keys]) => keys.includes('vertexCount'));
    const sameSet = (left: readonly string[], right: readonly string[]): boolean =>
      [...left].sort().join(',') === [...right].sort().join(',');

    /**
     * What one table and the parser disagree about, in both directions.
     * `accepted` is passed in so a plant can hand it a key set the parser does
     * not actually have, which is the second half of `CUR43`.
     */
    const disagreements = (
      table: { type: string; at: number; fields: string[] },
      accepted: readonly string[] | null,
    ): string[] => {
      if (accepted === null) {
        return [
          `${GUIDE} line ${table.at} gives a field table to \`"type": "${table.type}"\` and the parser named no ` +
            'key set for it at all — the type resolves to no shape, so every row of that table is unchecked',
        ];
      }
      const rows = new Set(table.fields);
      return [
        ...accepted
          .filter((key) => !rows.has(key))
          .map(
            (key) =>
              `\`${key}\` is a key the parser accepts on a "${table.type}" attachment and the table at ${GUIDE} ` +
              `line ${table.at} gives it no row — an affordance an author can only find by reading src/rig.ts`,
          ),
        ...table.fields
          .filter((field) => !accepted.includes(field))
          .map(
            (field) =>
              `the table at ${GUIDE} line ${table.at} lists \`${field}\` on a "${table.type}" attachment and the ` +
              'parser refuses it — an author who writes it gets `has a key this compiler does not read`, from the ' +
              'guide that told them to',
          ),
      ];
    };

    const tables = typedTables(guideRaw);
    const live = tables.map((table) => ({ table, accepted: acceptedFor(table.type) }));
    const unmatchedShapes = polygonShapes
      .filter(([, keys]) => !live.some(({ accepted }) => accepted !== null && sameSet(accepted, keys)))
      .map(([shape]) => shape);

    // --- CUR42: the typed tables against the keys the parser accepts ---------
    {
      const probes = [
        ...(guideDoc === undefined ? [`${GUIDE} is not one of the ${docs.length} document(s) this scan reads`] : []),
        ...floorProbes(
          [
            [tables.length, 1, `${tables.length} \`"type"\` field table(s) were read out of ${GUIDE}`],
            [tables.reduce((sum, table) => sum + table.fields.length, 0), 1, 'field row(s) across them'],
            [polygonShapes.length, 1, `${polygonShapes.length} shape(s) of RIG_KEYS carry a \`vertexCount\``],
          ],
          'a step that comes back empty makes this compare a complete set of tables against nothing',
        ),
        ...firstFew(
          live.flatMap(({ table, accepted }) => disagreements(table, accepted)),
          'disagreement(s)',
        ),
        ...unmatchedShapes.map(
          (shape) =>
            `${shape} carries a \`vertexCount\` and no \`"type"\` table in ${GUIDE} names the key set it declares — ` +
            'a polygon type the guide documents nowhere is exactly the hole this case was opened over',
        ),
      ];
      const held = probes.length === 0;
      say(
        'CUR42_EVERY_TYPED_ATTACHMENT_TABLE_NAMES_THE_KEYS_THAT_TYPE_ACCEPTS',
        held,
        probeDetail(
          held,
          probes,
          `${tables.length} table(s) — ${live
            .map(({ table, accepted }) => `${table.type} (${table.fields.length} row field(s), parser ${accepted?.length ?? 0})`)
            .join(', ')} — name exactly the keys the parser accepts for their own type, and each of the ` +
            `${polygonShapes.length} shape(s) carrying a \`vertexCount\` is the key set one of them states`,
        ),
        'the guide and the refusals are the whole interface an agent that cannot see the rig has, and a type the ' +
          'guide never names costs more than a missing field: the sitting that filed this reconstructed a clipping ' +
          "attachment out of two refusal rows and could not learn from anything shipped whether `convex` was read " +
          'on the way in, which space the vertices were in, or that `inverse` existed at all',
      );
    }

    // --- CUR43: the table reader and the comparison, planted both ways -------
    {
      const clean = live.flatMap(({ table, accepted }) => disagreements(table, accepted));
      // 🌱 The table both plants are aimed at, and what the parser says about its
      // own type. The empty stand-in is what a guide with no typed table at all
      // leaves, and the row below reports THAT rather than letting the two plants
      // pass over nothing. ⚠️ Both `raisedBy` calls are spelled at the binding
      // and not behind a `?:`, because `RB04` resolves the NAME to its
      // initializer — a ternary there reads as a fault list against a constant,
      // which is what this landing's first full run was red on.
      const aim = tables[0] ?? { type: '', at: 0, fields: [] };
      const aimAccepted = tables.length === 0 ? [] : acceptedFor(aim.type);
      const rowPlant = raisedBy(
        disagreements({ ...aim, fields: [...aim.fields, 'zzPlantedGuideField'] }, aimAccepted),
        { was: clean },
      );
      const keyPlant = raisedBy(disagreements(aim, [...(aimAccepted ?? []), 'zzPlantedParserKey']), { was: clean });
      const table = (anchor: string, cell: string): string =>
        `${anchor}\n\n| Field | Meaning |\n| --- | --- |\n| ${cell} | planted by this control |\n`;
      const readOf = (text: string): Array<{ type: string; at: number; fields: string[] }> =>
        typedTables(text.split('\n'));
      const fenced = '```\n' + table('`"type": "probe"`', '`zzFencedField`') + '```\n';
      const faults = [
        ...(tables.length === 0
          ? ['the guide gave up no `"type"` table at all, so both plants below had nothing to aim at']
          : []),
        ...(rowPlant.length === 0
          ? [
              'a field row planted into a copy of a table was not faulted as a key the parser refuses, so the ' +
                'guide could grow a row for a field that does not exist and this stays green',
            ]
          : []),
        ...(keyPlant.length === 0
          ? [
              'a key planted into a copy of the accepted set was not faulted as a row the guide lacks, so a shape ' +
                'could grow a field the tables never mention and this stays green',
            ]
          : []),
        ...(acceptedFor('zzNoSuchAttachmentType') === null
          ? []
          : ['a type no shape declares came back with a key set, so the parser is not what this reads the set from']),
        ...(readOf(fenced).length === 0
          ? []
          : ['a typed table inside a fence was read, so a transcript of the guide would be scanned as the guide']),
        ...(readOf(table('`"type": "probe"`', '`alpha` | `zzMeaningColumn`'))[0]?.fields.includes('zzMeaningColumn')
          ? ['the Meaning column was read as a field list, and it is prose that routinely spells another key']
          : []),
        ...(readOf(table('`"type": "probe"`', '`us` / `vs`'))[0]?.fields.join(',') === 'us,vs'
          ? []
          : ['a cell naming two fields was not read as two, and the guide writes several keys in one cell']),
        ...(readOf(`\`"type": "probe"\`\n\n#### a heading\n\n| Field | Meaning |\n| --- | --- |\n| \`alpha\` | x |\n`).length === 0
          ? []
          : ['a table separated from its anchor by a heading was still attributed to it, so an anchor leaks forward']),
        ...(readOf(`| a | \`"type": "probe"\` |\n\n| Field | Meaning |\n| --- | --- |\n| \`alpha\` | x |\n`).length === 0
          ? []
          : [
              'a type named inside a table ROW anchored the field table below it — §5.1 spells one in a refusal row, ' +
                'and reading that as a section intro hands the next field table to a type nobody documented there',
            ]),
        ...(readOf(table('`"type": "probe"`', '`alpha`'))[0]?.fields.includes('alpha')
          ? []
          : ['a one-field table this control wrote was not read at all, so every negative result above is vacuous']),
      ];
      const held = faults.length === 0;
      say(
        'CUR43_THE_TYPED_TABLE_READER_AND_THE_COMPARISON_FIRE_ON_EITHER_SIDE_GOING_WRONG',
        held,
        probeDetail(
          held,
          faults,
          'a row planted into a copy of a table is reported as a key the parser refuses and a key planted into a ' +
            'copy of the accepted set as a row the guide lacks; a type no shape declares yields no key set; and a ' +
            'one-field table is read while a table inside a fence, a key spelled in the Meaning column, a table a ' +
            'heading separates from its anchor and a type named inside a table row are each read in no way, a cell ' +
            'naming two fields as two',
        ),
        'both halves of `CUR42` fail silently on their own: a reader that stops matching the guide\'s tables ' +
          'compares an empty list against a full one and the floor is the only thing left, while a key set read ' +
          'from anywhere but the parser turns the case into two documents agreeing with each other',
      );
    }

    // --- CUR44: which corner of the region a mesh's `uvs` (0, 0) is ----------
    //
    // 🌱 The measurement is the runtime's own `MeshAttachment.computeUVs`, handed
    // the region rigc's own atlas writer produced, and the corner NAME is derived
    // from where it landed rather than chosen here: row 0 of a page is its top
    // row and column 0 its left one, which is what `tools/plate.ts` and
    // `src/render.ts` both read a PNG as. The guide's row then has to name that
    // corner and must not name either of the other two.
    {
      const width = 64;
      const height = 48;
      const atlasText = buildAtlasText([
        { region: 'probe', page: 'probe.png', absPath: '/probe.png', width, height, hasAlpha: true, isBase: true },
      ]);
      const region = new TextureAtlas(atlasText).findRegion('probe');
      const cornerAt = (u: number, v: number): string | null => {
        if (region === null) return null;
        const out = [0, 0];
        MeshAttachment.computeUVs(region, [u, v], out);
        const x = Math.min(Math.floor(out[0] * region.page.width), width - 1);
        const y = Math.min(Math.floor(out[1] * region.page.height), height - 1);
        return `${y === 0 ? 'top' : 'bottom'}-${x === 0 ? 'left' : 'right'}`;
      };
      const origin = cornerAt(0, 0);
      const opposite = cornerAt(1, 1);
      const acrossU = cornerAt(1, 0);
      const acrossV = cornerAt(0, 1);
      const corners = ['top', 'bottom'].flatMap((down) => ['left', 'right'].map((across) => `${down}-${across}`));
      const uvRows = guideRaw
        .map((line, i) => ({ line, at: i + 1 }))
        .filter(({ line }) => line.startsWith('|') && identifiersIn(line.split('|')[1] ?? '').join(',') === 'uvs');
      const named = uvRows.length === 1 ? corners.filter((corner) => uvRows[0].line.includes(corner)) : [];
      const wanted = origin === null || opposite === null ? [] : [origin, opposite];
      // 🌱 The same row with `top` and `bottom` exchanged, read back through the
      // same selector — the mistake this case is about, since y-up is what an
      // author brings to a uv from everywhere else in Spine.
      //
      // ⚠️ The DIAGONAL swap is deliberately not the plant: exchanging both words
      // of both corners maps {top-left, bottom-right} onto itself, so a control
      // that looked convinced by it would be reading nothing at all.
      const plantedRow =
        uvRows.length === 1
          ? uvRows[0].line.replace(/\b(top|bottom)-/g, (_whole: string, down: string) => `${down === 'top' ? 'bottom' : 'top'}-`)
          : '';
      const planted = corners.filter((corner) => plantedRow.includes(corner));
      const probes = [
        ...(region === null ? ['rigc\'s own atlas writer produced no region called "probe" to measure against'] : []),
        ...(uvRows.length === 1
          ? []
          : [
              `${GUIDE} carries ${uvRows.length} table row(s) whose field is \`uvs\`, and this reads the one that ` +
                'states the corner — with none there is no sentence to hold, and with several there is no telling ' +
                'which one an author would read',
            ]),
        ...(origin === acrossU || origin === acrossV
          ? [
              `\`u\` and \`v\` do not separate: (0, 0) landed ${String(origin)}, (1, 0) ${String(acrossU)} and ` +
                `(0, 1) ${String(acrossV)}, so one axis of this measurement is not being read at all`,
            ]
          : []),
        ...(uvRows.length === 1 && !sameSet(named, wanted)
          ? [
              `${GUIDE} line ${uvRows[0].at} is the \`uvs\` row and it names ${named.length === 0 ? 'no corner' : named.join(' and ')}; ` +
                `the runtime puts uv (0, 0) at the region's ${String(origin)} pixel and (1, 1) at its ` +
                `${String(opposite)} — a row that names another corner sends an author to the wrong end of the art, ` +
                'and one that names none leaves them to find it with an instrument',
            ]
          : []),
        ...(uvRows.length === 1 && plantedRow === uvRows[0].line
          ? ['exchanging `top` and `bottom` rewrote nothing in the `uvs` row, so the clause below measures nothing']
          : []),
        ...(uvRows.length === 1 && plantedRow !== uvRows[0].line && sameSet(planted, wanted)
          ? [
              `the \`uvs\` row with \`top\` and \`bottom\` exchanged names ${planted.join(' and ') || 'no corner'} and ` +
                'still satisfied this case, so the one word it exists to hold could be written either way and stay green',
            ]
          : []),
      ];
      const held = probes.length === 0;
      say(
        'CUR44_THE_GUIDE_NAMES_THE_CORNER_A_MESHS_UVS_START_FROM',
        held,
        probeDetail(
          held,
          probes,
          `\`MeshAttachment.computeUVs\`, over the region rigc's own atlas writer states for a ${width}x${height} ` +
            `page, puts uv (0, 0) at that region's ${String(origin)} pixel, (1, 0) at its ${String(acrossU)}, ` +
            `(0, 1) at its ${String(acrossV)} and (1, 1) at its ${String(opposite)}; ${GUIDE} line ` +
            `${uvRows[0]?.at ?? 0} names ${named.join(' and ')} and neither other corner, while the same row with ` +
            `\`top\` and \`bottom\` exchanged names ${planted.join(' and ')} and is refused`,
        ),
        'Spine\'s world is y up and a region\'s uvs are y down, so the guess an author makes here is a coin flip ' +
          'that a green build cannot settle: every assertion passes on a mesh whose art is upside down. The ' +
          'sitting that filed this assumed the top-left and confirmed it only through a coverage percentage on a ' +
          'part that happened not to be symmetric — an instrument standing in for a sentence',
      );
    }
  }

  // --- CUR45-CUR46: the turned-region paragraph, against the two routines it is
  // a reading of (issue #718) --------------------------------------------------
  //
  // ⭐ `docs/AUTHORING.md` §0.2 now tells an author holding only a pack what a
  // `rotate:` line means for the numbers beside it — which rectangle of the page
  // the region covers, and which way to turn that rectangle to get the drawing
  // back. Both halves are facts about somebody else's code, and prose about
  // somebody else's code is exactly the shape that goes stale without going red:
  // the paragraph it replaced said rigc "reads all of them", which is true of
  // rigc's instruments and answers neither question.
  //
  // 🔒 So neither word is read off the page and compared with a word written
  // here. The footprint half is derived from `pageFootprint`, which is what the
  // compiler, `A06`, `A19` and the renderer all call; the direction half from
  // `MeshAttachment.computeUVs` in the linked runtime, which is the one routine
  // there that states where a region's texels are for all four `degrees` —
  // `TextureAtlas`'s `u2`/`v2` transpose at one quarter turn and not the other
  // and would answer this wrongly at 270 (issue #579).
  //
  // ⚠️ The reader is the part that can go quiet, so it is the part that is
  // planted: a `rotate:` value is bound to the marker nearest before it IN ITS
  // OWN unit — a bullet or a paragraph — rather than anywhere on the page, which
  // is what keeps a mention in the prose above from binding a value it is not
  // about. Both plants are the section's own sentences with their two words
  // exchanged, which is `CUR34`'s bar: a control whose victim is invented proves
  // the form matches the control's imagination.
  {
    const GUIDE = 'docs/AUTHORING.md';
    const HEADING = '### 0.2 ';
    const guide = readFileSync(join(root, GUIDE), 'utf8');
    /**
     * One `###` section of a page, from its own heading to the next heading.
     *
     * ⚠️ Fenced blocks are held out of the search for that next heading, and
     * this file measured what leaving them in costs before it was written: every
     * transcript this guide quotes is commented with `#   ..`, which is a hash
     * and a space, so a reader of the raw lines ended §0.2 six lines in — at the
     * first quoted report line — and both cases below faulted on a section that
     * contained none of the sentences they exist to read.
     */
    const sectionOf = (text: string): string => {
      const lines = text.split('\n');
      const at = lines.findIndex((line) => line.startsWith(HEADING));
      if (at < 0) return '';
      let fenced = false;
      for (let i = at + 1; i < lines.length; i++) {
        if (lines[i].startsWith('```')) fenced = !fenced;
        else if (!fenced && /^#{1,3} /.test(lines[i])) return lines.slice(at, i).join('\n');
      }
      return lines.slice(at).join('\n');
    };
    /**
     * A section as the units a claim can live in: every bullet with the lines it
     * wraps onto, and every paragraph, whitespace collapsed to one space each.
     */
    const unitsOf = (section: string): string[] => {
      const units: string[] = [];
      let current = '';
      const flush = (): void => {
        if (current.trim() !== '') units.push(current.replace(/\s+/g, ' ').trim());
        current = '';
      };
      for (const line of section.split('\n')) {
        if (line.trim() === '') flush();
        else if (/^- /.test(line)) {
          flush();
          current = line;
        } else current = current === '' ? line : `${current} ${line}`;
      }
      flush();
      return units;
    };
    /**
     * What each `rotate: N` in the section is said about: the marker nearest
     * before it in its own unit, or nothing when its unit has none before it.
     * A value bound two ways is reported as both rather than as the last one.
     */
    const boundTo = (section: string, marker: RegExp): Map<number, string> => {
      const bound = new Map<number, string>();
      for (const unit of unitsOf(section)) {
        const markers = [...unit.matchAll(marker)].map((m) => ({ at: m.index ?? 0, word: m[0] }));
        if (markers.length === 0) continue;
        for (const token of unit.matchAll(/`rotate: (\d+)`/g)) {
          const before = markers.filter((m) => m.at < (token.index ?? 0));
          if (before.length === 0) continue;
          const word = before[before.length - 1].word;
          const turn = Number(token[1]);
          const already = bound.get(turn);
          bound.set(turn, already === undefined || already === word ? word : `${already} and ${word}`);
        }
      }
      return bound;
    };
    const DIRECTION = /\b(counter-)?clockwise\b/g;
    const SYMBOL = /`(?:w x h|h x w)`/g;
    const printed = (map: Map<number, string>): string =>
      [...map]
        .sort((a, b) => a[0] - b[0])
        .map(([turn, word]) => `rotate: ${turn} -> ${word}`)
        .join(', ') || '(nothing)';
    const apart = (said: Map<number, string>, measured: Map<number, string>, what: string): string[] => {
      const rows: string[] = [];
      for (const [turn, word] of measured) {
        const got = said.get(turn);
        if (got !== word) rows.push(`${GUIDE} §0.2 says ${what} at rotate: ${turn} is ${got ?? '(unsaid)'}, and it is ${word}`);
      }
      for (const [turn, word] of said) {
        if (!measured.has(turn)) rows.push(`${GUIDE} §0.2 states ${what} — ${word} — for rotate: ${turn}, which has none`);
      }
      return rows;
    };
    const section = sectionOf(guide);

    // The fixture: the probe rig's own parts, laid out by somebody else's packer
    // at each turn the runtime distinguishes. Nothing is fetched, so neither of
    // these two can HOLE.
    const dirs = writeProbeRig();
    const parts = ['block', 'marker'].map((region) => ({ region, absPath: join(dirs.dir, `${region}.png`) }));
    const CORNERS: Record<string, string> = {
      'top-left': 'no turn',
      'bottom-left': 'clockwise',
      'top-right': 'counter-clockwise',
      'bottom-right': 'half turn',
    };
    /**
     * Which way the rectangle ON THE PAGE has to be turned to become the
     * drawing, asked of the runtime: the corner of the footprint the drawing's
     * own top-left texel lands on names the turn, and nothing here says what it
     * should be.
     */
    const recoverBy = (degrees: number): string => {
      const pack = turnedPack(parts, degrees);
      const region = new TextureAtlas(readFileSync(pack.atlasPath, 'utf8')).regions.find(
        (r) => r.name.trim() === 'block',
      );
      if (region === undefined) return 'no such region';
      const foot = pageFootprint(region);
      const out = [0, 0];
      MeshAttachment.computeUVs(region, [0.5 / region.originalWidth, 0.5 / region.originalHeight], out);
      const px = Math.floor(out[0] * region.page.width);
      const py = Math.floor(out[1] * region.page.height);
      const side = px === region.x ? 'left' : px === region.x + foot.width - 1 ? 'right' : `x=${px}`;
      const row = py === region.y ? 'top' : py === region.y + foot.height - 1 ? 'bottom' : `y=${py}`;
      return CORNERS[`${row}-${side}`] ?? `${row}-${side}`;
    };
    const TURNS_STATED = [0, 90, 180, 270];
    const recovered = new Map(TURNS_STATED.map((degrees) => [degrees, recoverBy(degrees)]));
    const directionTruth = new Map(
      [...recovered].filter(([, word]) => word === 'clockwise' || word === 'counter-clockwise'),
    );

    // --- CUR45: the direction, against the runtime that owns the mapping -----
    {
      const faults: string[] = [];
      if (section === '') faults.push(`${GUIDE} has no section opening "${HEADING.trim()}", so nothing was read`);
      const said = boundTo(section, DIRECTION);
      faults.push(...apart(said, directionTruth, 'the turn that recovers the drawing'));
      // The plant: the section's own two words exchanged. A reader that bound a
      // value to whichever word is nearest ANYWHERE would still be green here,
      // because the exchange leaves the page carrying both words.
      const swapped = section.replace(DIRECTION, (_m, counter: string | undefined) =>
        counter === undefined ? 'counter-clockwise' : 'clockwise',
      );
      const swappedSaid = boundTo(swapped, DIRECTION);
      const swappedApart = apart(swappedSaid, directionTruth, 'the turn that recovers the drawing');
      if (swappedApart.length !== directionTruth.size) {
        faults.push(
          `§0.2 with its two direction words exchanged is faulted ${swappedApart.length} time(s) and this control ` +
            `requires ${directionTruth.size}, one per turn that has a direction — it read ${printed(swappedSaid)}`,
        );
      }
      // ...and the other side of the reader: a section naming no direction at
      // all must bind nothing, rather than reaching for the nearest word it can
      // find. Without this a reader that answered from the page's vocabulary
      // would pass both legs above.
      const silent = boundTo(section.replace(DIRECTION, 'a quarter turn'), DIRECTION);
      if (silent.size !== 0) faults.push(`§0.2 with no direction word left in it still bound ${printed(silent)}`);
      faults.push(
        ...floorProbes(
          [[directionTruth.size, 2, `${directionTruth.size} turn(s) were measured to have a direction`]],
          'a derivation that produced one direction or none would make the comparison above vacuous',
        ),
      );
      const held = faults.length === 0;
      say(
        'CUR45_THE_TURN_THE_GUIDE_NAMES_IS_THE_TURN_THE_RUNTIME_MAKES',
        held,
        probeDetail(
          held,
          faults,
          `the four turns recover the drawing by ${printed(recovered)}, measured on a packed fixture through ` +
            `\`MeshAttachment.computeUVs\`, and §0.2 names ${printed(boundTo(section, DIRECTION))}; the same ` +
            `section with its two words exchanged is faulted ${directionTruth.size} time(s), and with no ` +
            'direction word left in it binds nothing',
        ),
        'the direction is a fact about somebody else\'s code and the guide is the only place an author can read ' +
          'it. The 1.0 exam\'s first sitting derived it by cutting a page both ways and looking, after a ' +
          'composite drew the wrong glyphs in three of eleven places — each turned region\'s footprint happened ' +
          "to contain a neighbour's upright picture, so the wrong reading looked right. A sentence nothing " +
          'derives would put the next author in the same position while reading as though it were checked',
      );
    }

    // --- CUR46: the footprint, against the function every reader of it calls --
    {
      const PROBE = { width: 12, height: 8 };
      const symbolTruth = new Map(
        TURNS_STATED.map((degrees) => {
          const foot = pageFootprint({ ...PROBE, degrees });
          const same = foot.width === PROBE.width && foot.height === PROBE.height;
          return [degrees, same ? '`w x h`' : '`h x w`'] as const;
        }),
      );
      const faults: string[] = [];
      if (section === '') faults.push(`${GUIDE} has no section opening "${HEADING.trim()}", so nothing was read`);
      const said = boundTo(section, SYMBOL);
      faults.push(...apart(said, symbolTruth, 'the rectangle on the page'));
      const swapped = section.replace(SYMBOL, (m) => (m === '`w x h`' ? '`h x w`' : '`w x h`'));
      const swappedApart = apart(boundTo(swapped, SYMBOL), symbolTruth, 'the rectangle on the page');
      if (swappedApart.length !== symbolTruth.size) {
        faults.push(
          `§0.2 with its two footprint spellings exchanged is faulted ${swappedApart.length} time(s) and this ` +
            `control requires ${symbolTruth.size}, one per turn the section states`,
        );
      }
      // The quoted report line is the same claim in numbers, so it is read the
      // same way: `occupies` must be `pageFootprint`'s answer for the size and
      // the turn on its own line. (The size on the left is the untrimmed
      // drawing's, which is the region's own `bounds:` for the untrimmed region
      // this line quotes — a trimmed one would state a third pair and is not
      // what any line in this guide shows.)
      const quoted = [...section.matchAll(/(\d+)x(\d+) +<- .*?rotate (\d+), occupies (\d+)x(\d+)/g)];
      for (const line of quoted) {
        const [, w, h, degrees, fw, fh] = line;
        const foot = pageFootprint({ width: Number(w), height: Number(h), degrees: Number(degrees) });
        if (foot.width !== Number(fw) || foot.height !== Number(fh)) {
          faults.push(
            `${GUIDE} §0.2 quotes a ${w}x${h} region at rotate ${degrees} occupying ${fw}x${fh}, and ` +
              `\`pageFootprint\` makes it ${foot.width}x${foot.height}`,
          );
        }
      }
      faults.push(
        ...floorProbes(
          [
            [symbolTruth.size, 4, `${symbolTruth.size} turn(s) were derived`],
            [new Set(symbolTruth.values()).size, 2, `${new Set(symbolTruth.values()).size} distinct spelling(s) were derived`],
            [quoted.length, 1, `${quoted.length} report line(s) quoting a footprint were read`],
          ],
          'a derivation with one spelling in it, or a section quoting no line, would make this pass over nothing',
        ),
      );
      const held = faults.length === 0;
      say(
        'CUR46_THE_PAGE_RECTANGLE_THE_GUIDE_STATES_IS_PAGEFOOTPRINTS',
        held,
        probeDetail(
          held,
          faults,
          `\`pageFootprint\` makes a ${PROBE.width}x${PROBE.height} region ${printed(symbolTruth)} and §0.2 ` +
            `states ${printed(said)}; the same section with its two spellings exchanged is faulted ` +
            `${symbolTruth.size} time(s), and the ${quoted.length} quoted report line(s) carry the rectangle ` +
            'that function answers with',
        ),
        'this is the number the whole paragraph exists for, and it was derivable from `pageFootprint` for a month ' +
          'while no surface an author reads stated it. Deriving the PARTITION rather than the pair is what makes ' +
          'the case two-sided for free: the turns that transpose and the turns that do not are both read off the ' +
          'same function, so a guide that spelled either group the other way is faulted by name',
      );
    }
  }

  // --- CUR47/CUR48: the guide against the two sentences `pose` prints (#719) -
  //
  // ⭐ The same currency question as every case above, on a surface none of them
  // reaches: a message. `docs/AUTHORING.md` is the only interface an agent that
  // cannot see the rig has besides the messages themselves, so a page teaching a
  // sentence the tool no longer prints is worse than a page that never taught it
  // — the reader has been given a string to look for.
  //
  // 🔑 Neither figure below is typed here. The step comes off `rotationLadder`
  // run over the window the PAGE quotes, the ceiling off `COARSE_ROTATION_STEP`,
  // and the wall sentence out of `windowEdgeNote` over the two default scale
  // bounds — so the page is compared against what the module would produce
  // rather than against a copy of it made on the day it was written.
  {
    const guidePath = 'docs/AUTHORING.md';
    const guideRaw = readFileSync(join(root, guidePath), 'utf8').split('\n');
    /** The page with its wrapping taken out, so a sentence that spans two lines is one string. */
    const flatten = (lines: readonly string[]): string => lines.join('\n').replace(/\s+/g, ' ');
    /** The page with one line rewritten — the plant shape every case in this suite uses. */
    const rewritten = (at: number, line: string): string[] => guideRaw.map((was, i) => (i === at ? line : was));
    const lineWith = (needle: string): number => guideRaw.findIndex((line) => line.includes(needle));

    // --- CUR47: the step the page quotes is the step the ladder produces -----
    {
      const CEILING = /The coarse step `(-?[\d.]+)°` is a \*\*ceiling\*\*/;
      const QUOTED = /`--rotation (-?[\d.]+),(-?[\d.]+)` prints `([^`]+)`/;
      const scanGuide = (lines: readonly string[]): string[] => {
        const faults: string[] = [];
        const text = flatten(lines);
        const ceiling = CEILING.exec(text);
        if (ceiling === null) {
          faults.push(`${guidePath} no longer calls the coarse rotation step a ceiling, so nothing here reads it`);
        } else if (Number(ceiling[1]) !== COARSE_ROTATION_STEP) {
          faults.push(
            `${guidePath} calls ${ceiling[1]}° the ceiling on the coarse rotation step and the module answers ` +
              `${COARSE_ROTATION_STEP}`,
          );
        }
        const quoted = QUOTED.exec(text);
        if (quoted === null) {
          faults.push(`${guidePath} quotes no \`search\` line for a named --rotation window, so the step it teaches is unchecked`);
        } else {
          const minDeg = Number(quoted[1]);
          const maxDeg = Number(quoted[2]);
          const degrees = rotationLadder(minDeg, maxDeg);
          const built = searchRotationClause({
            minDeg,
            maxDeg,
            stepDeg: degrees.length > 1 ? degrees[1] - degrees[0] : 0,
            steps: degrees.length,
            degrees,
          });
          if (quoted[3] !== built) {
            faults.push(
              `${guidePath} teaches ${JSON.stringify(quoted[3])} for --rotation ${minDeg},${maxDeg} and this build ` +
                `prints ${JSON.stringify(built)}`,
            );
          }
        }
        return faults;
      };
      const standing = scanGuide(guideRaw);
      const probes = [...standing];
      let note = '';
      const ceilingAt = lineWith('is a **ceiling**');
      const quotedAt = lineWith('` prints `rotation ');
      if (ceilingAt < 0 || quotedAt < 0) {
        probes.push(
          `${guidePath} carries the ceiling sentence on line ${ceilingAt + 1} and the quoted line on line ` +
            `${quotedAt + 1}, and a plant needs both`,
        );
      } else if (standing.length === 0) {
        const one = (what: string, at: number, line: string): void => {
          const raised = raisedBy(scanGuide(rewritten(at, line)), { was: standing });
          if (raised.length !== 1) {
            probes.push(
              `${what} was faulted ${raised.length} time(s) and this control requires one` +
                (raised.length === 0 ? '' : `: ${raised.join('; ')}`),
            );
          } else note = `${note}${note === '' ? '' : ' · '}${what}: "${raised[0]}"`;
        };
        one(
          'the ceiling raised by a degree',
          ceilingAt,
          guideRaw[ceilingAt].replace(`\`${COARSE_ROTATION_STEP}°\``, `\`${COARSE_ROTATION_STEP + 1}°\``),
        );
        one(
          'the quoted step replaced by the constant it is a ceiling on',
          quotedAt,
          guideRaw[quotedAt].replace(/of ([\d.]+)°`/, `of ${COARSE_ROTATION_STEP}°\``),
        );
      }
      const held = probes.length === 0;
      say(
        'CUR47_THE_ROTATION_STEP_THE_GUIDE_TEACHES_IS_THE_ONE_THE_LADDER_PRODUCES',
        held,
        probeDetail(
          held,
          probes,
          `${guidePath} calls ${COARSE_ROTATION_STEP}° a ceiling on the coarse step and quotes one window's ` +
            `\`search\` line, which this build reproduces angle for angle — and ${note}`,
        ),
        'the page taught `step 15°` for four weeks because the report printed it, over windows the ladder walked ' +
          'at ten and at thirteen and a third. A guide that quotes a message is a second copy of it, and the only ' +
          'copy that cannot drift is one built from the same function the message is',
      );
    }

    // --- CUR48: the wall sentence the guide teaches is the one emitted ------
    {
      const scanGuide = (lines: readonly string[]): string[] => {
        const wanted = windowEdgeNote(
          'scale',
          'floor',
          DEFAULT_SCALE_MIN.toFixed(3),
          `${DEFAULT_SCALE_MIN},${DEFAULT_SCALE_MAX}`,
        );
        return flatten(lines).includes(wanted)
          ? []
          : [`${guidePath} does not carry the sentence a refusal at the default floor prints: ${JSON.stringify(wanted)}`];
      };
      const standing = scanGuide(guideRaw);
      const probes = [...standing];
      let note = '';
      const at = lineWith(`the floor of --scale ${DEFAULT_SCALE_MIN},${DEFAULT_SCALE_MAX}`);
      if (at < 0) {
        probes.push(`${guidePath} states the sentence on no single line, so a plant has nothing to aim at`);
      } else if (standing.length === 0) {
        const one = (what: string, line: string): void => {
          const raised = raisedBy(scanGuide(rewritten(at, line)), { was: standing });
          if (raised.length !== 1) {
            probes.push(
              `${what} was faulted ${raised.length} time(s) and this control requires one` +
                (raised.length === 0 ? '' : `: ${raised.join('; ')}`),
            );
          } else note = `${note}${note === '' ? '' : ' · '}${what} is reported once`;
        };
        one('the wall named as the ceiling instead of the floor', guideRaw[at].replace('the floor of', 'the ceiling of'));
        one(
          'the scale a decimal place out',
          guideRaw[at].replace(`scale ${DEFAULT_SCALE_MIN.toFixed(3)}`, `scale ${(DEFAULT_SCALE_MIN + 0.001).toFixed(3)}`),
        );
        one('the claim made flat rather than conditional', guideRaw[at].replace('may lie below', 'lies below'));
      }
      const held = probes.length === 0;
      say(
        'CUR48_THE_WALL_SENTENCE_THE_GUIDE_TEACHES_IS_THE_ONE_A_REFUSAL_PRINTS',
        held,
        probeDetail(
          held,
          probes,
          `${guidePath} §11.4 carries the sentence \`windowEdgeNote\` builds for a refusal at the default scale ` +
            `floor, word for word, over the two bounds the module exports — and ${note}`,
        ),
        'the sentence is the remedy: an author who reads the refusal and the page has to find the same string in ' +
          'both, because what the page is teaching is which words to look for. A paraphrase here is the failure ' +
          'mode — it reads correct and sends nobody to the right line',
      );
    }
  }

  // --- CUR49-CUR50: the two pages that document `diff`, against the code -----
  //
  // ⭐ `docs/AUTHORING.md` §9 is `check` and not `diff`; the two documents below
  // are where `diff` is written down, which is measured rather than assumed —
  // the page's own heading says *"Checking against the frames — `rigc check`"*.
  //
  // 🔒 Everything compared here is READ OFF THE TOOL: the measure names come
  // from a report this file builds, and the flag's value spelling comes from
  // `diff --help`, which is the page an agent actually meets. Nothing on either
  // side of the comparison is typed here, so a rename in `src/diff.ts` that no
  // document followed is what goes red — and the plant is a measure name the
  // tool does not emit, which must be faulted on both pages.
  {
    const oneShot = (name: string): Record<string, unknown> => ({ animations: { [name]: {} } });
    const paired = diffSkeletons(oneShot('candidate shot'), oneShot('reference shot'));
    const block = paired.sections.find((s) => s.name === 'animations')?.nameAgnostic;
    const prefix = 'animations.agnostic.';
    const tails = (block?.measures ?? []).map((m) => m.id.slice(prefix.length));
    const helpRow = /^ {2}(--as)((?: \S+)?) {2,}\S/.exec(
      runCli(['diff', '--help']).stdout.split('\n').find((line) => line.startsWith('  --as ')) ?? '',
    );
    const flagValue = helpRow?.[2].trim() ?? '';
    const heading = 'animations (name-agnostic)';

    /** What a page has to carry, faulted term by term. */
    const audit = (page: string, text: string, names: readonly string[]): string[] => [
      ...names.filter((tail) => !text.includes(`\`${tail}\``)).map((tail) => `${page} spells no \`${tail}\``),
      ...(text.includes('--as') ? [] : [`${page} never names the \`--as\` flag`]),
      ...(flagValue !== '' && text.includes(flagValue) ? [] : [`${page} does not spell --as's value as \`${flagValue}\``]),
      ...(text.includes(heading) ? [] : [`${page} never shows the block's own heading, "${heading}"`]),
    ];
    const ready = tails.length > 0 && flagValue !== '';
    const planted = [...tails.slice(0, -1), `${tails[tails.length - 1] ?? ''}_under_another_name`];

    for (const [name, page] of [
      ['CUR49_THE_BENCHMARK_PAGE_NAMES_THE_PAIRED_BLOCK_AND_ITS_FLAG_AS_THE_CODE_SPELLS_THEM', 'docs/BENCHMARK.md'],
      ['CUR50_THE_INGEST_PAGE_NAMES_THE_PAIRED_BLOCK_AND_ITS_FLAG_AS_THE_CODE_SPELLS_THEM', 'docs/INGEST.md'],
    ] as const) {
      const text = readFileSync(join(root, page), 'utf8');
      const standing = audit(page, text, tails);
      const raised = audit(page, text, planted).filter((fault) => !standing.includes(fault));
      const probes = [
        ...(ready ? [] : [`the report carried ${tails.length} measure name(s) and --help gave the value "${flagValue}" — nothing to compare`]),
        ...standing,
        ...(raised.length === 1
          ? []
          : [`a measure name the tool does not emit was faulted ${raised.length} time(s) on this page, and this control requires exactly one`]),
      ];
      const held = probes.length === 0;
      bad += reportCase(
        name,
        held,
        probeDetail(
          held,
          probes,
          `${page} spells all ${tails.length} of \`${prefix}*\` (${tails.join(', ')}), the flag \`--as ` +
            `${flagValue}\` as \`diff --help\` prints it, and the block's heading "${heading}"; a name the tool ` +
            'does not emit is faulted once',
          (count) => `${count} term(s) of this page did not hold:`,
        ),
        'the two pages here are where `diff` is documented — AUTHORING §9 is `check` — and a measure an agent ' +
          'cannot find under the name the report prints is a measure it cannot act on, which for a tool whose ' +
          'messages are its UI is the same as not having it',
      );
    }
  }

  // --- CUR51-CUR52: the guide's rule for the emitted name order (issue #728) --
  //
  // 🔒 Both sides are read rather than typed. The KINDS come off the compiler's
  // own union, and the ORDERS the page teaches come off the stored round trips:
  // R10 states the rule as "`x` before `y`", and every one of those pairs has to
  // be a pair some probe returned in that order. A page that teaches a rule the
  // oracle contradicts is the failure this pair exists for, and it is the one
  // shape a reader of either file alone cannot see.
  {
    const guide = 'docs/AUTHORING.md';
    const guideText = readFileSync(join(root, guide), 'utf8');
    const ruleBlock = (text: string): string => {
      const from = text.indexOf('**R10 — ');
      const to = text.indexOf('**R12 — ', from);
      return from < 0 || to < 0 ? '' : text.slice(from, to);
    };

    const kindsDeclared = (
      readFileSync(join(root, 'src/compile.ts'), 'utf8').match(/kind:\s*((?:'[a-z]+'\s*\|\s*)*'[a-z]+')/) ?? ['', '']
    )[1]
      .split('|')
      .map((kind) => kind.trim().replace(/'/g, ''))
      .filter(Boolean)
      .sort();
    /** Which of a kind list the failure map and R10 between them spell as code. */
    const kindsTaught = (kinds: readonly string[], text: string): string[] =>
      kinds.filter((kind) => text.includes(`\`${kind}\``));
    const mapRows = guideText
      .split('\n')
      .filter((line) => line.includes('have no one order'))
      .join('\n');
    const taughtIn = `${ruleBlock(guideText)}\n${mapRows}`;
    const missingKinds = kindsDeclared.filter((kind) => !kindsTaught(kindsDeclared, taughtIn).includes(kind));
    const plantedKind = 'sibling';
    const kindProbes = [
      ...(kindsDeclared.length > 0 ? [] : ['`src/compile.ts` declares no refusal kinds this reader can find']),
      ...(mapRows === '' ? [`${guide} carries no §5.1 row for the order refusal, so the map sends nobody anywhere`] : []),
      ...missingKinds.map((kind) => `${guide} never spells \`${kind}\`, which the compiler declares and a refusal prints`),
      ...(kindsTaught([plantedKind], taughtIn).length === 0
        ? []
        : [`${guide} spells \`${plantedKind}\`, which the compiler does not declare — this control cannot tell a real kind from a planted one`]),
      ...(kindsTaught([...kindsDeclared, plantedKind], taughtIn).length === kindsDeclared.length
        ? []
        : ['the reader found a kind the compiler does not declare, so it is not reading the union']),
    ];
    const kindsHeld = kindProbes.length === 0;
    say(
      'CUR51_THE_REFUSAL_KINDS_THE_GUIDE_TEACHES_ARE_THE_ONES_THE_COMPILER_DECLARES',
      kindsHeld,
      probeDetail(
        kindsHeld,
        kindProbes,
        `the compiler declares ${kindsDeclared.length} kind(s) (${kindsDeclared.join(', ')}) and ${guide} spells ` +
          `every one of them across R10 and its §5.1 row(s); a kind it does not declare (\`${plantedKind}\`) is ` +
          'not on the page',
        (count) => `${count} clause(s) of the kind vocabulary did not hold:`,
      ),
      'the kind in brackets is the only part of that refusal an author navigates by — it is what tells them which ' +
        'of the three repairs to take — so a page that teaches a kind the compiler stopped printing, or omits one ' +
        'it prints, sends the reader to a row that does not exist. Both sides are read: the union off the source, ' +
        'the spellings off the page',
    );

    interface TaughtPair {
      a: string;
      b: string;
    }
    const pairsTaught = (text: string): TaughtPair[] =>
      [...ruleBlock(text).matchAll(/`([^`]+)` before `([^`]+)`/g)].map((hit) => ({ a: hit[1], b: hit[2] }));
    interface OracleList {
      at: string;
      names: string[];
    }
    const oracle: OracleList[] = [];
    const oracleFaults: string[] = [];
    for (const which of [1, 2, 3, 4, 5]) {
      const at = `fixtures/editor-order/probe${which}.out.json`;
      try {
        const text = readFileSync(join(root, at), 'utf8');
        const parsed = JSON.parse(text) as { skins: Array<{ name: string }> };
        const from = text.indexOf('"animations"');
        const body = from < 0 ? '' : text.slice(text.indexOf('{', from) + 1);
        oracle.push({ at: `${at} skins`, names: parsed.skins.map((skin) => skin.name) });
        oracle.push({
          at: `${at} animations`,
          names: [...body.matchAll(/"((?:[^"\\]|\\.)*)"\s*:\s*\{\s*\}/g)].map((hit) => JSON.parse(`"${hit[1]}"`) as string),
        });
      } catch (err) {
        oracleFaults.push(`${at}: ${(err as Error).message}`);
      }
    }
    /** Every pair the page teaches that no stored output returned in that order. */
    const unsupported = (pairs: TaughtPair[]): string[] =>
      pairs
        .filter(
          (pair) =>
            !oracle.some(
              (list) =>
                list.names.includes(pair.a) &&
                list.names.includes(pair.b) &&
                list.names.indexOf(pair.a) < list.names.indexOf(pair.b),
            ),
        )
        .map((pair) => `${guide} teaches "${pair.a}" before "${pair.b}", which no stored round trip returned`);
    const taught = pairsTaught(guideText);
    const standingPairs = unsupported(taught);
    const swapped = taught.length === 0 ? [] : unsupported([{ a: taught[0].b, b: taught[0].a }]);
    const pairProbes = [
      ...oracleFaults,
      ...standingPairs,
      ...(taught.length > 0 ? [] : [`${guide} states R10's rule with no "\`x\` before \`y\`" pair in it, so nothing here is checkable`]),
      ...(oracle.length > 0 ? [] : ['no stored output was read, so every pair on the page would pass unmeasured']),
      ...(swapped.length === 1
        ? []
        : [`the first taught pair read backwards was faulted ${swapped.length} time(s) and this control requires one`]),
    ];
    const pairsHeld = pairProbes.length === 0;
    say(
      'CUR52_EVERY_ORDER_THE_GUIDES_RULE_TEACHES_IS_ONE_A_STORED_ROUND_TRIP_RETURNED',
      pairsHeld,
      probeDetail(
        pairsHeld,
        pairProbes,
        `R10 states its rule with ${taught.length} pair(s) of names and every one of them is a pair one of the ` +
          `${oracle.length} stored list(s) returned in that order; the first of them read backwards is faulted once`,
        (count) => `${count} order(s) the guide teaches that the oracle does not:`,
      ),
      '⭐ this is the clause that makes R10 a reading of the files rather than a paraphrase of them. The page is ' +
        'where an author meets the rule, and every example it gives is now derived: renaming a probe, reordering ' +
        'one, or mistyping an example on the page are all one fault here. The plant is the page\'s own first ' +
        'example reversed, so a reader that matched nothing would go red rather than agree',
    );
  }

  // --- CUR57/CUR58: the page-grid refusal, against the page that teaches it ---
  //
  // ⭐ The same currency question `CUR47`/`CUR48` ask of `pose`'s two sentences,
  // on the one `A06` prints for a page whose image is not the size the atlas
  // declares for it (issue #715). That message is unusual among this tool's
  // refusals in that it hands over a REPAIR — a `size:`/`scale:` pair the author
  // is meant to write — so a guide that taught a different one would be sending
  // a reader to rewrite a pack into a second broken state.
  //
  // 🔑 Neither case types a phrase or a number. `CUR57` blanks every digit and
  // every quoted name out of both the live refusal and the block the guide
  // quotes, and asks whether what is left of the guide is what the rule says;
  // `CUR58` reads the profile column off the §5.2 row and compares it against
  // which profiles actually refuse the plant.
  {
    const guidePath = 'docs/AUTHORING.md';
    const guide = readFileSync(join(root, guidePath), 'utf8');
    const A06 = 'A06_ATLAS_PAGE_SIZE_MATCHES_PNG';
    const dirs = writeProbeRig();
    const refusalUnder = (profile: ValidateProfile, mutate: (text: string) => string): string | null =>
      gateProbeAtlas(dirs, STATIC_MOTION, mutate, profile, ATLAS_EDIT_TWIN).failures.find((f) => f.assertion === A06)?.detail ?? null;
    const uniformSaid = refusalUnder('spine', doubleFirstAtlasPageSize);
    const stretchedSaid = refusalUnder('spine', stretchFirstAtlasPageSize);

    // --- CUR57: the sentences the guide quotes are the sentences it prints ----
    {
      /** A sentence with every digit and every quoted name blanked, and its wrapping taken out. */
      const shape = (text: string): string =>
        text
          .replace(/"[^"]*"/g, '""')
          .replace(/\d+/g, '#')
          .replace(/^[ \t]*#+ ?/gm, ' ')
          .replace(/\s+/g, ' ')
          .trim();
      /** The fenced block in §0.2 that quotes this refusal, cut at the ellipsis the page uses. */
      const quoted = (text: string): string[] => {
        const block = /```bash\n((?:#.*\n)*?#[^\n]*A06_ATLAS_PAGE_SIZE_MATCHES_PNG[\s\S]*?)```/.exec(text);
        if (block === null) return [];
        return block[1]
          .split('…')
          .map((piece) => shape(piece))
          .filter((piece) => piece.length > 0);
      };
      const taught = quoted(guide);
      const live = uniformSaid === null ? '' : shape(uniformSaid);
      const missing = taught.filter((piece) => !live.includes(piece.replace(/^FAIL [A-Z#_]+: /, '')));
      const plantedGuide = guide.replace('multiply every `bounds`/`offsets` on this page by', 'divide every `bounds`/`offsets` on this page by');
      const plantedPieces = quoted(plantedGuide);
      const plantedMissing = plantedPieces.filter((piece) => !live.includes(piece.replace(/^FAIL [A-Z#_]+: /, '')));
      const quoteProbes = [
        ...(uniformSaid === null ? [`the rule printed no ${A06} failure on a page declaring twice its own file, so nothing was compared`] : []),
        ...firstFew(
          missing.map((piece) => `${guidePath} §0.2 quotes a clause the rule does not print: ${JSON.stringify(piece.slice(0, 110))}`),
          'clause(s)',
        ),
        ...(plantedMissing.length > missing.length
          ? []
          : ['the same block with its repair verb exchanged is faulted no more often than the real one, so this reader is not reading the verb']),
        ...floorProbes(
          [[taught.length, 2, `${taught.length} piece(s) of the quoted block were read`]],
          'a block that quoted nothing, or only the assertion name, would make this pass over the page rather than over the sentence',
        ),
      ];
      const quoteHeld = quoteProbes.length === 0;
      say(
        'CUR57_THE_PAGE_GRID_REFUSAL_THE_GUIDE_QUOTES_IS_THE_ONE_THE_RULE_PRINTS',
        quoteHeld,
        probeDetail(
          quoteHeld,
          quoteProbes,
          `${taught.length} piece(s) of §0.2's quoted refusal, every digit and quoted name blanked, are clauses of ` +
            `the ${String(uniformSaid?.length ?? 0)}-character sentence this build prints for a page declaring ` +
            'twice its own file; the same block with its repair verb exchanged is faulted',
          (count) => `${count} clause(s) the page teaches that the rule does not print:`,
        ),
        'this refusal is the only one in the tool that hands the author a header to WRITE, so the page quoting a ' +
          'different one is worse than the page quoting none — the reader has been given a repair to carry out. ' +
          'Blanking the digits is what lets the page keep its own 4096/2048 example while the sentence around it ' +
          'is compared against the live one',
      );
    }

    // --- CUR58: the profile column, against the profiles that refuse it -------
    {
      const row = /\| (?:<a id="[^"]*"><\/a>)?`A06_ATLAS_PAGE_SIZE_MATCHES_PNG` \| ([^|]+?) \|/.exec(guide);
      const refusing = VALIDATE_PROFILES.filter((profile) => refusalUnder(profile, doubleFirstAtlasPageSize) !== null);
      const oracle = refusing.length === VALIDATE_PROFILES.length ? 'both' : refusing.join(' and ');
      const said = row === null ? null : row[1].trim();
      const profileProbes = [
        ...(said === null ? [`${guidePath} §5.2 has no row for ${A06}, so the profile it teaches was not read`] : []),
        ...(said !== null && said.split(' ')[0] === oracle
          ? []
          : [`${guidePath} §5.2 files ${A06} under ${JSON.stringify(said ?? '')} and the plant is refused under ${oracle}`]),
        ...floorProbes(
          [[refusing.length, 1, `${refusing.length} profile(s) refused the plant`]],
          'a plant no profile refuses would let any word at all stand in that column',
        ),
      ];
      const profileHeld = profileProbes.length === 0;
      say(
        'CUR58_THE_PROFILE_THE_GUIDE_FILES_THE_PAGE_GRID_CLAUSE_UNDER_IS_THE_ONE_THAT_REFUSES_IT',
        profileHeld,
        probeDetail(
          profileHeld,
          profileProbes,
          `a page declaring twice its own file is refused under ${oracle} of the ${VALIDATE_PROFILES.length} ` +
            `profile(s) (${VALIDATE_PROFILES.join(', ')}), and §5.2 files ${A06} under ${JSON.stringify(said ?? '')}`,
        ),
        'the column is how an author decides whether a refusal is about their file or about somebody\'s renderer, ' +
          'and this clause is the one a card argued should move across that line. It did not, and the page has to ' +
          'say which side it is on for the same reason the message does — read off the reports rather than off ' +
          'the sentence that argued it',
      );
    }
  }

  // --- CUR61/CUR62: the page that is not a PNG, against the page that teaches it
  //
  // `CUR57`'s question asked of the refusal issue #732 added: the sentence §0.2
  // quotes is compared, digits, quoted names and absolute paths blanked, against
  // the one `A06` prints for a forged WebP page; and the formats the guide says
  // the reader names are read off the reader's own sentence for a file in none
  // of them, which lists what it would have named. Neither case types a format.
  {
    const guidePath = 'docs/AUTHORING.md';
    const guide = readFileSync(join(root, guidePath), 'utf8');
    const A06 = 'A06_ATLAS_PAGE_SIZE_MATCHES_PNG';
    const gateOn = (pack: ReturnType<typeof packWithFirstPageReplaced>): string | null =>
      validate({
        skeletonText: pack.result.skeletonText,
        atlasText: pack.atlasText,
        atlasDir: pack.dir,
        declaredDurations: pack.result.declaredDurations,
        modelText: threadedModel(pack.result, pack.atlasText),
        rig: pack.result.rig,
        profile: 'spine',
      }).failures.find((f) => f.assertion === A06)?.detail ?? null;
    const webpPack = packWithFirstPageReplaced((_png, page) => minimalWebp(page.width, page.height));
    // Bytes that open no format at all, so the sentence falls through to the list it would have named.
    const unknownPack = packWithFirstPageReplaced(() => new Uint8Array(Buffer.from('not-a-page')));
    const webpSaid = gateOn(webpPack);
    const unknownSaid = gateOn(unknownPack);

    // --- CUR61: the refusal the guide quotes is the refusal the rule prints ---
    {
      const shape = (text: string): string =>
        text
          .replace(/^[ \t]*#+ ?/gm, ' ')
          .replace(/(^|\s)\/\S+/g, '$1/')
          .replace(/"[^"]*"/g, '""')
          .replace(/\d+/g, '#')
          .replace(/\s+/g, ' ')
          .trim();
      const quoted = (text: string): string[] => {
        const block = /```bash\n((?:#.*\n)*?#[^\n]*A06_ATLAS_PAGE_SIZE_MATCHES_PNG[^\n]*cannot be read as PNG[\s\S]*?)```/.exec(text);
        if (block === null) return [];
        return block[1]
          .split('…')
          .map((piece) => shape(piece))
          .filter((piece) => piece.length > 0);
      };
      const live = webpSaid === null ? '' : shape(webpSaid);
      const taught = quoted(guide);
      const missing = taught.filter((piece) => !live.includes(piece.replace(/^FAIL [A-Z#_]+: /, '')));
      const planted = quoted(guide.replace('is a WebP image (a RIFF/WEBP container', 'is a JPEG image (a RIFF/WEBP container'));
      const plantedMissing = planted.filter((piece) => !live.includes(piece.replace(/^FAIL [A-Z#_]+: /, '')));
      const quoteProbes = [
        ...(webpSaid === null ? [`the rule printed no ${A06} failure on a WebP page, so nothing was compared`] : []),
        ...firstFew(
          missing.map((piece) => `${guidePath} §0.2 quotes a clause the rule does not print: ${JSON.stringify(piece.slice(0, 110))}`),
          'clause(s)',
        ),
        ...(plantedMissing.length > missing.length
          ? []
          : ['the same block with its format exchanged is faulted no more often than the real one, so this reader is not reading the format']),
        ...floorProbes(
          [[taught.length, 2, `${taught.length} piece(s) of the quoted block were read`]],
          'a block that quoted nothing, or only the assertion name, would make this pass over the page rather than over the sentence',
        ),
      ];
      const quoteHeld = quoteProbes.length === 0;
      say(
        'CUR61_THE_NOT_A_PNG_REFUSAL_THE_GUIDE_QUOTES_IS_THE_ONE_THE_RULE_PRINTS',
        quoteHeld,
        probeDetail(
          quoteHeld,
          quoteProbes,
          `${taught.length} piece(s) of §0.2's quoted refusal, digits, quoted names and paths blanked, are clauses ` +
            `of the ${String(webpSaid?.length ?? 0)}-character sentence this build prints for a WebP page; the same ` +
            'block with its format exchanged is faulted',
          (count) => `${count} clause(s) the page teaches that the rule does not print:`,
        ),
        'the page is where an author who was handed a foreign pack learns what the refusal will look like, and a ' +
          'quoted sentence the rule no longer prints teaches them to look for the wrong line',
      );
    }

    // --- CUR62: the formats the guide says are named are the ones the reader names
    {
      const liveList = unknownSaid === null ? null : /it names ([^)]*?) when it meets them/.exec(unknownSaid);
      const named = liveList === null ? [] : liveList[1].split(/,\s*/).map((name) => name.trim()).filter(Boolean);
      const row = /\| (?:<a id="[^"]*"><\/a>)?`A06_ATLAS_PAGE_SIZE_MATCHES_PNG` \|[^\n]*?one of ([^\n]*?) by its signature/.exec(guide);
      const listOf = (text: string): string[] => text.split(/,\s*/).map((name) => name.trim()).filter(Boolean);
      const taught = row === null ? [] : listOf(row[1]);
      const plantedRow = row === null ? [] : listOf(row[1].replace(/,\s*[^,]+$/, ''));
      const differ = (a: readonly string[], b: readonly string[]): boolean => [...a].sort().join('|') !== [...b].sort().join('|');
      const formatProbes = [
        ...(unknownSaid === null ? [`the rule printed no ${A06} failure on a file in no format, so the reader's list was not read`] : []),
        ...(liveList === null && unknownSaid !== null ? [`the refusal for a file in no format lists nothing it would have named: ${unknownSaid.slice(0, 160)}`] : []),
        ...(row === null ? [`${guidePath} §5.2's ${A06} row lists no format it names by signature`] : []),
        ...(differ(taught, named) ? [`${guidePath} §5.2 teaches [${taught.join(', ')}] and the reader names [${named.join(', ')}]`] : []),
        ...(differ(plantedRow, named) ? [] : ['the row with its last format dropped still agrees with the reader, so this is not reading the list']),
        ...floorProbes([[named.length, 2, `${named.length} format(s) read off the reader's sentence`]], 'one format is the card\'s example, not a table'),
      ];
      const formatHeld = formatProbes.length === 0;
      say(
        'CUR62_THE_FORMATS_THE_GUIDE_SAYS_ARE_NAMED_ARE_THE_ONES_THE_READER_NAMES',
        formatHeld,
        probeDetail(
          formatHeld,
          formatProbes,
          `§5.2's ${A06} row and the reader's own sentence for a file in no format both name ` +
            `[${named.join(', ')}]; the row with its last format dropped is faulted`,
        ),
        'a format added to the reader and not to the page is one an author is told rigc does not recognise; the ' +
          'list is read off the sentence the reader prints for a file in none of them, so the page is compared ' +
          'against what the code does rather than against a copy of it',
      );
    }
    for (const pack of [webpPack, unknownPack]) rmSync(pack.dir, { recursive: true, force: true });
  }

  // --- CUR65/CUR66: the five inheritance modes, in the two places the guide lists them (issue #733)
  //
  // The guide states the modes twice — the setup field (§3.2) and the track
  // (§4.4) — and the compiler states them once, in the sentence both refusals
  // print. Each copy is held to that sentence rather than to the table in
  // `src/rig.ts`, so what is compared is what an author is told.
  {
    const guidePath = 'docs/AUTHORING.md';
    const guide = readFileSync(join(root, guidePath), 'utf8');
    const probe = writeProbeRig();
    const probeMotion = join(probe.dir, 'probe.motion.json');
    writeFileSync(
      probeMotion,
      `${JSON.stringify({ spec: 'rigc-motion/1', archetype: 'static_probe', cut: 'static_probe', easings: {}, animations: { move: { duration: 1, loop: false, tracks: [{ bone: 'block', property: 'inherit', keys: [{ t: 0, v: 'wobble' }] }] } } }, null, 2)}\n`,
    );
    let said = '';
    try {
      compile({ rigPath: probe.rigPath, motionPath: probeMotion, outDir: probe.outDir, imagesDir: probe.dir });
    } catch (err) {
      said = (err as Error).message;
    }
    const live = (/known: ([^—]*?) —/.exec(said)?.[1] ?? '').split(/,\s*/).map((mode) => mode.trim()).filter(Boolean);
    const ticked = (text: string): string[] => [...text.matchAll(/`([^`]+)`/g)].map((m) => m[1]);
    const differ = (a: readonly string[], b: readonly string[]): boolean => [...a].sort().join('|') !== [...b].sort().join('|');
    const rows: Array<[string, string, string, RegExp]> = [
      [
        'CUR65_THE_MODES_THE_GUIDES_INHERIT_TRACK_ROW_TEACHES_ARE_THE_ONES_THE_REFUSAL_PRINTS',
        '§4.4',
        'the `bone` / `inherit` track row',
        /^\| `bone` \| `inherit` \| a mode name, not an array: ([^\n]*?) —/m,
      ],
      [
        'CUR66_THE_MODES_THE_GUIDES_SETUP_INHERIT_ROW_TEACHES_ARE_THE_ONES_THE_REFUSAL_PRINTS',
        '§3.2',
        "the bone field table's `inherit` row",
        /^\| `inherit` \| ((?:`[^`]+`(?: · )?)+)\./m,
      ],
    ];
    for (const [name, section, what, pattern] of rows) {
      const row = pattern.exec(guide);
      const taught = row === null ? [] : ticked(row[1]);
      const planted = row === null ? [] : ticked(row[1]).slice(0, -1);
      const probes = [
        ...(live.length === 0 ? [`the refusal for an unknown mode lists no modes: ${said || 'the probe compiled'}`] : []),
        ...(row === null ? [`${guidePath} ${section} has no ${what} listing the modes`] : []),
        ...(differ(taught, live) ? [`${guidePath} ${section} teaches [${taught.join(', ')}] and the refusal prints [${live.join(', ')}]`] : []),
        ...(differ(planted, live) ? [] : ['the row with its last mode dropped still agrees with the refusal, so this is not reading the list']),
        ...floorProbes([[live.length, 2, `${live.length} mode(s) read off the refusal`]], 'one mode is an example, not a table'),
      ];
      const held = probes.length === 0;
      say(
        name,
        held,
        probeDetail(
          held,
          probes,
          `${section}'s ${what} and the compiler's own refusal of an unknown mode both name [${live.join(', ')}]; the row ` +
            'with its last mode dropped is faulted',
        ),
        'one resolver reads the setup field and the key, and prints one list when it refuses — so the page has two ' +
          'copies of it and each is a place an author learns the vocabulary. A copy that dropped one is an author ' +
          'told a mode does not exist; read off the sentence, the page is compared against the code rather than a copy',
      );
    }
  }

  // --- CUR67: the withheld lines the guide quotes are the ones `explain` prints (#750)
  //
  // `CUR61`'s question asked of the report rather than of the gate: §0.2 quotes
  // what `explain` prints on a pack whose page is not its declared size, and the
  // quote is compared — digits and quoted names blanked — against what this
  // build prints for the half-resolution fixture. The plant exchanges the one
  // word the section turns on.
  {
    const guidePath = 'docs/AUTHORING.md';
    const guide = readFileSync(join(root, guidePath), 'utf8');
    const packs = halvedMeshPacks();
    const live = typeof packs === 'string' ? null : explainHalvedMesh(packs, packs.rigs.measured, packs.half);
    const shape = (text: string): string =>
      text
        .replace(/^[ \t]*#+ ?/gm, ' ')
        .replace(/"[^"]*"/g, '""')
        .replace(/\d+/g, '#')
        .replace(/\s+/g, ' ')
        .trim();
    const quoted = (text: string): string[] => {
      const block = /```bash\n((?:#.*\n)*?#[^\n]*taken off this page's texels is withheld[\s\S]*?)```/.exec(text);
      if (block === null) return [];
      return block[1]
        .split('…')
        .map((piece) => shape(piece))
        .filter((piece) => piece.length > 0);
    };
    // Shaped a line at a time: a quote left open on one line of a report would otherwise pair with the next
    // line's and blank everything between them.
    const printed = live === null ? '' : live.stdout.split('\n').map(shape).join('\n');
    const taught = quoted(guide);
    const missing = taught.filter((piece) => !printed.includes(piece));
    const planted = quoted(guide.replace('fit not measured: page', 'fit not refused: page'));
    const plantedMissing = planted.filter((piece) => !printed.includes(piece));
    const probes = [
      ...(typeof packs === 'string' ? [`the fixture was not built: ${packs}`] : []),
      ...(live !== null && live.status !== 0 ? [`explain exited ${String(live.status)} on the half-resolution pack`] : []),
      ...firstFew(
        missing.map((piece) => `${guidePath} §0.2 quotes a clause explain does not print: ${JSON.stringify(piece.slice(0, 110))}`),
        'clause(s)',
      ),
      ...(plantedMissing.length > missing.length
        ? []
        : ['the same block with its verb exchanged is faulted no more often than the real one, so this reader is not reading the words']),
      ...floorProbes(
        [[taught.length, 3, `${taught.length} piece(s) of the quoted block were read`]],
        'the block quotes the page line, a withheld fit and a withheld count, and a reader that found fewer is ' +
          'comparing part of the quote',
      ),
    ];
    const held = probes.length === 0;
    say(
      'CUR67_THE_WITHHELD_FIGURES_THE_GUIDE_QUOTES_ARE_THE_LINES_EXPLAIN_PRINTS',
      held,
      probeDetail(
        held,
        probes,
        `${taught.length} piece(s) of §0.2's quoted explain lines, digits and quoted names blanked, are clauses of ` +
          'what this build prints for the half-resolution fixture; the same block with its verb exchanged is faulted',
        (count) => `${count} clause(s) the page teaches that explain does not print:`,
      ),
      'the page is where an author learns what a withheld figure looks like, and a quote the report no longer ' +
        'prints teaches them to look for a number that is not coming',
    );
    if (typeof packs !== 'string') rmSync(packs.dir, { recursive: true, force: true });
  }

  // --- CUR70–CUR71: the seven sequence modes are one list (issue #729) -------
  //
  // The motion parser, `A46` and `ingest` all read a mode against
  // `SEQUENCE_MODES`, and the compiler links no runtime, so nothing but these
  // two can say the list is the runtime's and the only one.
  {
    const runtime = SequenceModeValues.map((value) => SequenceMode[value]);
    const planted = [...SEQUENCE_MODES].reverse();
    const sameList = (a: readonly string[]): boolean => JSON.stringify(a) === JSON.stringify(runtime);
    say(
      'CUR70_THE_SEQUENCE_MODES_RIGC_READS_ARE_THE_RUNTIMES_ENUM_IN_ITS_ORDER',
      sameList(SEQUENCE_MODES) && !sameList(planted) && runtime.length > 1,
      `SEQUENCE_MODES = [${SEQUENCE_MODES.join(', ')}]; spine-core's SequenceModeValues read through SequenceMode = ` +
        `[${runtime.join(', ')}]; the list reversed ${sameList(planted) ? 'ALSO matches' : 'does not'}`,
      'a mode the list lacks is one the parser refuses and every runtime plays; a mode it has that the runtime ' +
        'lacks is one rigc emits and every runtime reads as "hold" — the silence the list exists to refuse. The ' +
        'order is the enum\'s because the mode bits are its ordinal (`mode | (index << 4)`), and the reversed ' +
        'plant is what says the comparison reads order and not only membership',
    );

    // Every other spelling of the seven in `src/`: the one mode no other word
    // shares, so a second table would have to spell it.
    const spelledIn = trackedIn(root, 'src', (file) => file.endsWith('.ts'))
      .map((path) => basename(path))
      .filter((file) => readFileSync(join(root, 'src', file), 'utf8').includes("'pingpongReverse'"));
    const plantedTree = [...spelledIn, 'compile.ts'];
    const oneList = (files: readonly string[]): boolean => files.length === 1 && files[0] === 'timelines.ts';
    say(
      'CUR71_THE_SEQUENCE_MODES_ARE_SPELT_IN_ONE_MODULE_OF_SRC',
      oneList(spelledIn) && !oneList(plantedTree),
      `the quoted name 'pingpongReverse' occurs in ${spelledIn.length} module(s) of src/: ${spelledIn.join(', ') || 'none'}; ` +
        `a tree with a second table in compile.ts ${oneList(plantedTree) ? 'ALSO passes' : 'is faulted'}`,
      'four readers of one list, and the failure a second copy invites is the one CUR70 cannot see: CUR70 holds ' +
        'the SHARED list to the runtime, so a reader that kept its own would drift in silence. `pingpongReverse` ' +
        'is the name to scan for because no other word in the format contains it, and zero occurrences — the ' +
        'list moved or renamed — is as red as two',
    );
  }

  // --- CUR72–CUR73: what the guide teaches about a `scale:` page's units is what rigc prints (#762)
  //
  // `CUR67`'s question asked of the two sentences #762 changed: §0.2 quotes the
  // fit line a `scale:` page prints, and §4's depth table quotes the refusal a
  // texel-sized sheet gets there. Each quote is compared — digits and quoted
  // names blanked, cut at every `…` — against what this build prints for the
  // same fixture, and a plant exchanges the word each one turns on.
  {
    const guidePath = 'docs/AUTHORING.md';
    const guide = readFileSync(join(root, guidePath), 'utf8');
    const packs = halvedMeshPacks();
    const shape = (text: string): string =>
      text
        .replace(/^[ \t]*#+ ?/gm, ' ')
        .replace(/"[^"]*"/g, '""')
        .replace(/\d+(\.\d+)?/g, '#')
        .replace(/\s+/g, ' ')
        .trim();
    const pieces = (quote: string | null): string[] =>
      quote === null
        ? []
        : quote
            .split('…')
            .map((piece) => shape(piece))
            .filter((piece) => piece.length > 0);
    const compare = (
      name: string,
      printed: string | null,
      quoteOf: (text: string) => string | null,
      plant: readonly [string, string],
      floor: number,
      where: string,
      why: string,
    ): void => {
      const taught = pieces(quoteOf(guide));
      const shaped = printed === null ? '' : printed.split('\n').map(shape).join('\n');
      const missing = taught.filter((piece) => !shaped.includes(piece));
      // Planted inside the quote itself, so the exchange cannot land on the same words elsewhere on the page.
      const quote = quoteOf(guide);
      const planted = pieces(quote === null ? null : quote.replace(plant[0], plant[1]));
      const plantedMissing = planted.filter((piece) => !shaped.includes(piece));
      const probes = [
        ...(typeof packs === 'string' ? [`the fixture was not built: ${packs}`] : []),
        ...(printed === null ? ['the build printed nothing to compare against'] : []),
        ...firstFew(
          missing.map((piece) => `${guidePath} ${where} quotes a clause rigc does not print: ${JSON.stringify(piece.slice(0, 110))}`),
          'clause(s)',
        ),
        ...(plantedMissing.length > missing.length
          ? []
          : [`the quote with ${JSON.stringify(plant[0])} exchanged is faulted no more often than the real one, so this reader is not reading the words`]),
        ...floorProbes([[taught.length, floor, `${taught.length} piece(s) of the quote were read`]], 'a reader that found fewer is comparing part of the quote'),
      ];
      const held = probes.length === 0;
      say(
        name,
        held,
        probeDetail(
          held,
          probes,
          `${taught.length} piece(s) of ${where}'s quote, digits and quoted names blanked, are clauses of what this build ` +
            `prints; the quote with ${JSON.stringify(plant[0])} exchanged is faulted`,
          (count) => `${count} clause(s) the page teaches that rigc does not print:`,
        ),
        why,
      );
    };

    // CUR72 — §0.2's `scale:` fit line.
    const fitPrinted =
      typeof packs === 'string'
        ? null
        : runCli([
            'explain', '--rig', packs.rigs.fan, '--motion', packs.motionPath, '--images', packs.parts,
            '--atlas-in', packs.honest, '--out', join(packs.dir, 'explain-doc'),
          ]).stdout;
    compare(
      'CUR72_THE_SCALE_PAGE_FIT_LINE_THE_GUIDE_QUOTES_IS_THE_LINE_EXPLAIN_PRINTS',
      fitPrinted,
      (text) => /```bash\n((?:#.*\n)*?#[^\n]*measured on the page's texels at scale:[^\n]*\n(?:#.*\n)*?)```/.exec(text)?.[1] ?? null,
      ["the drawing's pixels, measured", "the page's texels, measured"],
      1,
      '§0.2',
      'the section is where an author learns which unit the figure is in, and a quote that names the wrong grid ' +
        'is the defect #762 removed, restated in prose',
    );

    // CUR73 — §4's depth-table row for a texel-sized sheet on a `scale:` page.
    let refusal: string | null = null;
    if (typeof packs !== 'string') {
      try {
        compile({
          rigPath: packs.rigs.texelSheet,
          motionPath: packs.motionPath,
          outDir: join(packs.dir, 'refusal-doc'),
          imagesDir: packs.parts,
          atlasInPath: packs.honest,
        });
      } catch (err) {
        refusal = err instanceof Error ? err.message : String(err);
      }
    }
    compare(
      'CUR73_THE_SCALE_PAGE_SHEET_REFUSAL_THE_GUIDE_QUOTES_IS_THE_ONE_THE_COMPILER_RAISES',
      refusal,
      (text) => /^\| a sheet at the page's texel size, on a page that declares a `scale:` \| `([^`]*)`/m.exec(text)?.[1] ?? null,
      ['the part is a', 'the part is the'],
      2,
      '§4 (depth table)',
      'the table is the guide\'s index of refusals, and the row for this one is where an author finds out that ' +
        'the sheet is the art\'s size on a `scale:` page — a row quoting the texel-sized answer would send them to ' +
        'resample the file the compiler asks them to keep',
    );
    if (typeof packs !== 'string') rmSync(packs.dir, { recursive: true, force: true });
  }

  // --- CUR74–CUR75: the base-plate sentence the pages quote is the one A19 prints (issue #770)
  //
  // Every `*"…"*` quote in an `A19` table row is held to the refusal a
  // stageless rig-spec build prints for its opaque backdrop — the sentence that
  // says what would decide which image is the base plate. A quote reworded
  // on the page, or a sentence reworded in the rule, is red here.
  {
    const backdrop = gateStagelessSpecBackdrop();
    const live = backdrop.packed.failures.find((f) => f.assertion === 'A19_OVERLAY_PNGS_HAVE_ALPHA')?.detail ?? '';
    const quotesIn = (text: string): string[] =>
      text
        .split('\n')
        .filter((line) => ruleRowOf(line, 'A19_OVERLAY_PNGS_HAVE_ALPHA'))
        .flatMap((line) => [...line.matchAll(/\*"([^"]+)"\*/g)].map((m) => m[1]));
    const cases: Array<[string, string]> = [
      ['CUR74_THE_BASE_PLATE_SENTENCE_THE_GUIDE_QUOTES_IS_THE_ONE_A19_PRINTS', 'docs/AUTHORING.md'],
      ['CUR75_THE_BASE_PLATE_SENTENCE_THE_BENCHMARK_PAGE_QUOTES_IS_THE_ONE_A19_PRINTS', 'docs/BENCHMARK.md'],
    ];
    for (const [name, path] of cases) {
      const text = readFileSync(join(root, path), 'utf8');
      const quotes = quotesIn(text);
      const missing = quotes.filter((quote) => !live.includes(quote));
      const planted = quotesIn(text.replace(/(\| (?:<a id="[^"]*"><\/a>)?`A19_OVERLAY_PNGS_HAVE_ALPHA` \|[^\n]*?\*")(\S+)/, '$1RENAMED'));
      const plantedMissing = planted.filter((quote) => !live.includes(quote));
      const probes = [
        ...(live === '' ? ['the stageless rig-spec backdrop printed no A19 refusal, so nothing was compared'] : []),
        ...(quotes.length > 0 ? [] : [`no \`*"…"*\` quote stands in an A19 row of ${path}`]),
        ...missing.map((quote) => `${path} quotes a clause A19 does not print: ${JSON.stringify(quote.slice(0, 110))}`),
        ...(plantedMissing.length > missing.length ? [] : ['the same rows with a quote reworded are faulted no more often, so this reader is not reading the quote']),
      ];
      const held = probes.length === 0;
      say(
        name,
        held,
        probeDetail(
          held,
          probes,
          `${quotes.length} quote(s) in ${path}'s A19 rows are clauses of the sentence A19 prints for a stageless ` +
            'rig-spec backdrop; the same rows with a quote reworded are faulted',
          (count) => `${count} thing(s) the page's A19 quotes did not hold:`,
        ),
        'the page is where an author learns what would decide the base plate, and a quote the rule no longer ' +
          'prints sends them after a remedy the refusal does not name',
      );
    }
  }

  // --- CUR80–CUR81: the accepted-on-a-wall mark the guide teaches is the one `pose` prints (issue #737)
  //
  // Both read off the module: the console fragment comes out of `poseLines` over
  // a one-part report whose `walls` came out of `placementWalls`, at the default
  // ceiling, and the field row's keys are the keys that function returns. The
  // page is where an author learns which words mark a held value; a paraphrase
  // reads correct and sends nobody to the right line.
  {
    const guideFile = 'docs/AUTHORING.md';
    const guideText = readFileSync(join(root, guideFile), 'utf8');
    const guideLines = guideText.split('\n');
    const window = { min: DEFAULT_SCALE_MIN, max: DEFAULT_SCALE_MAX };
    const fullTurn = { min: -180, max: 180, wraps: true };
    const walls = placementWalls(DEFAULT_SCALE_MAX, 0, window, fullTurn, false);
    const onCeiling: PosePlacement = {
      x: 0,
      y: 0,
      rotationDeg: 0,
      scale: DEFAULT_SCALE_MAX,
      residual: 0,
      unexplained: 0,
      offCanvas: 0,
      footprint: 0,
      bbox: { x: 0, y: 0, width: 0, height: 0 },
    };
    const oneHeld: PoseReport = {
      spec: POSE_SPEC,
      space: '',
      images: '',
      frame: { path: '', width: 0, height: 0, background: { kind: 'unknown', colour: null, borderShare: 0, materialShare: 0 } },
      search: {
        scale: { min: window.min, max: window.max, steps: 0 },
        rotation: { minDeg: -180, maxDeg: 180, stepDeg: 0, steps: 0, degrees: [] },
        coarse: { frameLongSide: 0, partSpan: 0, strideFraction: 0, framePyramid: 0 },
        maxResidual: DEFAULT_MAX_RESIDUAL,
        ambiguity: { absolute: 0, relative: 0 },
      },
      caveats: [],
      parts: [
        {
          part: 'held.png',
          path: '',
          width: 0,
          height: 0,
          refusal: null,
          placement: onCeiling,
          walls,
          alternates: [],
          ambiguous: false,
          rotationFree: false,
          rotationSelfSimilarity: 1,
          coarse: null,
          legibility: null,
          notes: [],
        },
      ],
    };
    const printed = poseLines(oneHeld).find((row) => row.includes('held.png')) ?? '';
    const from = printed.indexOf('scale=');
    const to = printed.indexOf('  residual=');
    const fragment = from >= 0 && to > from ? printed.slice(from, to) : '';

    // CUR80: the console fragment.
    {
      const scan = (lines: readonly string[]): string[] =>
        fragment === '' || lines.some((line) => line.includes(fragment))
          ? []
          : [`${guideFile} does not quote the fragment an accepted placement on the default ceiling prints: ${JSON.stringify(fragment)}`];
      const standing = scan(guideLines);
      const probes = [...standing];
      if (fragment === '') probes.push(`\`poseLines\` printed no scale field for a placement on the ceiling: ${JSON.stringify(printed)}`);
      if (walls.length !== 1) probes.push(`\`placementWalls\` found ${walls.length} wall(s) for a scale on the default ceiling`);
      const at = guideLines.findIndex((line) => fragment !== '' && line.includes(fragment));
      let note = '';
      if (at >= 0) {
        const plant = (what: string, line: string): void => {
          const planted = [...guideLines];
          planted[at] = line;
          if (raisedBy(scan(planted), { was: standing }).length === 0) probes.push(`${what} was not caught`);
          else note = `${note}${note === '' ? '' : ' · '}${what} is faulted`;
        };
        plant('the wall named as the floor instead of the ceiling', guideLines[at].replace('(the ceiling of', '(the floor of'));
        plant('the clause dropped from the quoted line', guideLines[at].replace(/ \(the ceiling of --scale [^)]*\)/, ''));
      }
      const held = probes.length === 0;
      say(
        'CUR80_THE_ACCEPTED_WALL_CLAUSE_THE_GUIDE_QUOTES_IS_THE_ONE_POSE_PRINTS',
        held,
        probeDetail(
          held,
          probes,
          `${guideFile} §11.4 quotes ${JSON.stringify(fragment)}, which \`poseLines\` prints for a placement ` +
            `\`placementWalls\` puts on the default ceiling — and ${note}`,
        ),
        'the clause is how an author tells a value the window held from one the picture gave, so the page has to ' +
          'teach the words the report actually prints',
      );
    }

    // CUR81: the field row names every key of a wall.
    {
      const keys = walls.length > 0 ? Object.keys(walls[0]) : [];
      const rowOf = (lines: readonly string[]): string => lines.find((line) => line.startsWith('| `walls` |')) ?? '';
      const scan = (lines: readonly string[]): string[] => {
        const row = rowOf(lines);
        if (row === '') return [`${guideFile} §11.3 has no \`walls\` row`];
        return keys.filter((key) => !row.includes(`\`${key}\``)).map((key) => `${guideFile}'s \`walls\` row does not name the key \`${key}\``);
      };
      const standing = scan(guideLines);
      const probes = [...standing];
      if (keys.length === 0) probes.push('`placementWalls` returned no wall to read keys off');
      const at = guideLines.findIndex((line) => line.startsWith('| `walls` |'));
      if (at >= 0) {
        const planted = [...guideLines];
        planted[at] = planted[at].split(`\`${keys[1] ?? keys[0] ?? 'edge'}\``).join('`side`');
        if (raisedBy(scan(planted), { was: standing }).length === 0) probes.push('a row with one key renamed was not caught');
      }
      const held = probes.length === 0;
      say(
        'CUR81_THE_WALLS_ROW_THE_GUIDE_CARRIES_NAMES_EVERY_KEY_A_WALL_HAS',
        held,
        probeDetail(
          held,
          probes,
          `${guideFile} §11.3's \`walls\` row names ${keys.map((k) => `\`${k}\``).join(', ')}, the keys \`placementWalls\` ` +
            'returns — and the same row with one key renamed is faulted',
        ),
        'the JSON is what an agent reads, so a field row that names a key the report does not carry is a field ' +
          'nobody can find',
      );
    }
  }

  // --- CUR82: the hinge step the guide teaches is the one the ladder produces (issue #738)
  //
  // `CUR47`'s question asked of §12.4. The page calls `HINGE_STEP` a ceiling and
  // quotes one window's `search` clause and the note beside it; the clause is
  // rebuilt here by `searchHingeClause` over `hingeLadder` of the window the
  // PAGE names, and the note by `hingeWalkPhrase` of that ladder's step — so the
  // page is compared against what the module would print rather than against a
  // copy of it made on the day it was written.
  {
    const guidePath = 'docs/AUTHORING.md';
    const guideRaw = readFileSync(join(root, guidePath), 'utf8').split('\n');
    const CEILING = /The hinge step `(-?[\d.]+)°` is a \*\*ceiling\*\*/;
    const QUOTED = /`--hinge (-?[\d.]+),(-?[\d.]+)` prints `([^`]+)`/;
    const NOTED = /note says it was searched `([^`]+)`/;
    const scanGuide = (lines: readonly string[]): string[] => {
      const faults: string[] = [];
      const text = lines.join('\n').replace(/\s+/g, ' ');
      const ceiling = CEILING.exec(text);
      if (ceiling === null) {
        faults.push(`${guidePath} no longer calls the hinge step a ceiling, so nothing here reads it`);
      } else if (Number(ceiling[1]) !== HINGE_STEP) {
        faults.push(`${guidePath} calls ${ceiling[1]}° the ceiling on the hinge step and the module answers ${HINGE_STEP}`);
      }
      const quoted = QUOTED.exec(text);
      if (quoted === null) {
        faults.push(`${guidePath} quotes no \`search\` clause for a named --hinge window, so the step it teaches is unchecked`);
        return faults;
      }
      const minDeg = Number(quoted[1]);
      const maxDeg = Number(quoted[2]);
      const rungs = hingeLadder(minDeg, maxDeg);
      const stepDeg = hingeLadderStep(rungs);
      const built = searchHingeClause({ minDeg, maxDeg, stepDeg, steps: rungs.length });
      if (quoted[3] !== built) {
        faults.push(`${guidePath} teaches ${JSON.stringify(quoted[3])} for --hinge ${minDeg},${maxDeg} and this build prints ${JSON.stringify(built)}`);
      }
      const noted = NOTED.exec(text);
      const phrase = hingeWalkPhrase(stepDeg);
      if (noted === null) faults.push(`${guidePath} no longer quotes the note a chain part carries, so its step is unchecked`);
      else if (noted[1] !== phrase) {
        faults.push(`${guidePath} says a chain part's note reads ${JSON.stringify(noted[1])} and this build writes ${JSON.stringify(phrase)}`);
      }
      return faults;
    };
    const standing = scanGuide(guideRaw);
    const probes = [...standing];
    const at = guideRaw.findIndex((line) => CEILING.test(line));
    let note = '';
    if (at < 0) probes.push(`${guidePath} carries no line calling the hinge step a ceiling, and the plants need one`);
    else if (standing.length === 0) {
      const one = (what: string, line: string): void => {
        const raised = raisedBy(scanGuide(guideRaw.map((was, i) => (i === at ? line : was))), { was: standing });
        if (raised.length !== 1) {
          probes.push(
            `${what} was faulted ${raised.length} time(s) and this control requires one` +
              (raised.length === 0 ? '' : `: ${raised.join('; ')}`),
          );
        } else note = `${note}${note === '' ? '' : ' · '}${what}: "${raised[0]}"`;
      };
      one('the ceiling raised by a degree', guideRaw[at].replace(`\`${HINGE_STEP}°\` is a`, `\`${HINGE_STEP + 1}°\` is a`));
      one('the quoted step replaced by the constant it is a ceiling on', guideRaw[at].replace(/step ([\d.]+)° \(/, `step ${HINGE_STEP}° (`));
      one('the quoted note replaced by the constant', guideRaw[at].replace(/searched `in [\d.]+° steps`/, `searched \`in ${HINGE_STEP}° steps\``));
    }
    const held = probes.length === 0;
    say(
      'CUR82_THE_HINGE_STEP_THE_GUIDE_TEACHES_IS_THE_ONE_THE_LADDER_PRODUCES',
      held,
      probeDetail(
        held,
        probes,
        `${guidePath} calls ${HINGE_STEP}° a ceiling on the hinge step and quotes one window's \`search\` clause and ` +
          `note, which this build reproduces — and ${note}`,
      ),
      'the page is where an author learns what the `search` line promises; quoting the constant as the step ' +
        'teaches the string the report used to print over a ladder it did not walk',
    );
  }

  // --- CUR83-CUR84: the editor's key order, as the tree states it (#716) ----
  //
  // `src/keyorder.ts`'s `EDITOR_KEY_ORDER` is the one table; the guide prints
  // it and `src/types.ts`'s interfaces declare their fields in it. Both are
  // read here against the table, never against a copy of it.
  {
    const guidePath = 'docs/AUTHORING.md';
    const guideRaw = readFileSync(join(root, guidePath), 'utf8').split('\n');
    const HEAD = '| Kind | Keys, in the order the editor writes them |';
    const scanGuide = (lines: readonly string[]): string[] => {
      const at = lines.indexOf(HEAD);
      if (at < 0) return [`${guidePath} carries no table headed ${JSON.stringify(HEAD)}, so the order it teaches is unchecked`];
      const printed: Array<[string, string[]]> = [];
      for (let i = at + 2; i < lines.length && lines[i].startsWith('|'); i++) {
        const cells = lines[i].split('|').slice(1, -1).map((cell) => cell.trim());
        const kind = /^`([^`]+)`$/.exec(cells[0] ?? '')?.[1] ?? `(unreadable row ${i + 1})`;
        printed.push([kind, [...(cells[1] ?? '').matchAll(/`([^`]+)`/g)].map((m) => m[1])]);
      }
      const faults: string[] = [];
      const table = Object.entries(EDITOR_KEY_ORDER);
      for (const [kind, keys] of printed) {
        const row = EDITOR_KEY_ORDER[kind];
        if (row === undefined) faults.push(`${guidePath} prints a row for "${kind}", which the table does not have`);
        else if (row.join(',') !== keys.join(',')) faults.push(`${guidePath} prints "${kind}" as ${keys.join(', ')} and the table says ${row.join(', ')}`);
      }
      for (const [kind] of table) if (!printed.some(([k]) => k === kind)) faults.push(`${guidePath} prints no row for "${kind}"`);
      const inOrder = printed.map(([k]) => k).filter((k) => EDITOR_KEY_ORDER[k] !== undefined);
      const want = table.map(([k]) => k).filter((k) => inOrder.includes(k));
      if (inOrder.join(',') !== want.join(',')) faults.push(`${guidePath} prints the rows in another order than the table holds them`);
      return faults;
    };
    const standing = scanGuide(guideRaw);
    const probes = [...standing];
    const head = guideRaw.indexOf(HEAD);
    let note = '';
    // The plant needs a table it can read; where there is none, the standing
    // faults already say why.
    if (head >= 0 && standing.length === 0) {
      const first = head + 2;
      const cells = guideRaw[first].split('|');
      const keys = [...cells[2].matchAll(/`([^`]+)`/g)].map((m) => m[1]);
      const swapped = [keys[1], keys[0], ...keys.slice(2)].map((k) => `\`${k}\``).join(', ');
      const planted = guideRaw.map((line, i) => (i === first ? [...cells.slice(0, 2), ` ${swapped} `, ...cells.slice(3)].join('|') : line));
      const raised = raisedBy(scanGuide(planted), { was: standing });
      if (keys.length < 2) probes.push(`${guidePath}'s first row prints fewer than two keys, so swapping two measures nothing`);
      else if (raised.length !== 1) probes.push(`the first row's first two keys swapped raised ${raised.length} fault(s) and this control requires one`);
      else note = `the first row's first two keys swapped: "${raised[0]}"`;
    }
    const held = probes.length === 0;
    say(
      'CUR83_THE_KEY_ORDER_THE_GUIDE_PRINTS_IS_THE_TABLE_THE_EMITTER_APPLIES',
      held,
      probeDetail(
        held,
        probes,
        `${guidePath} prints ${Object.keys(EDITOR_KEY_ORDER).length} row(s), each the table's own in the table's ` +
          `order — and ${note}`,
      ),
      'the guide is what an agent reads to know what a rebuild will look like beside an export, and a row copied ' +
        'by hand is the one that is stale the day a row changes',
    );
  }
  {
    const typesPath = 'src/types.ts';
    const typesText = readFileSync(join(root, typesPath), 'utf8');
    /** Each interface that declares a kind's fields, and the kind. */
    const DECLARED: ReadonlyArray<readonly [string, string]> = [
      ['SpineSkeletonJson', 'top level'],
      ['SpineBone', 'bone'],
      ['SpineSlot', 'slot'],
      ['SpineRegionAttachment', 'region attachment'],
      ['SpineMeshAttachment', 'mesh attachment'],
      ['SpineBoundingBoxAttachment', 'boundingbox attachment'],
      ['SpineClippingAttachment', 'clipping attachment'],
    ];
    const scanTypes = (text: string): string[] => {
      const faults: string[] = [];
      for (const [name, kind] of DECLARED) {
        const fields = interfaceFieldsIn(text, name);
        const row = EDITOR_KEY_ORDER[kind];
        if (fields === null) faults.push(`${typesPath} declares no interface ${name}`);
        else if (row === undefined) faults.push(`the table has no row "${kind}" for ${name}`);
        else {
          const listed = fields.filter((f) => row.includes(f));
          const want = row.filter((k) => listed.includes(k));
          if (listed.length < 2) faults.push(`${name} declares ${listed.length} field(s) its row orders, so its order says nothing`);
          else if (listed.join(',') !== want.join(',')) faults.push(`${name} declares ${listed.join(', ')} and the "${kind}" row orders them ${want.join(', ')}`);
        }
      }
      const alias = /export type SpineConstraint = \{([^}]*)\}/.exec(text);
      const aliasFields = alias === null ? [] : [...alias[1].matchAll(/(\w+)\??\s*:/g)].map((m) => m[1]);
      const constraintRows = Object.keys(EDITOR_KEY_ORDER).filter((kind) => kind.endsWith(' constraint'));
      if (alias === null) faults.push(`${typesPath} declares no SpineConstraint type`);
      for (const kind of constraintRows) {
        const row = EDITOR_KEY_ORDER[kind];
        const want = row.filter((k) => aliasFields.includes(k));
        const listed = aliasFields.filter((f) => row.includes(f));
        if (listed.join(',') !== want.join(',')) faults.push(`SpineConstraint declares ${listed.join(', ')} and the "${kind}" row orders them ${want.join(', ')}`);
      }
      return faults;
    };
    const standing = scanTypes(typesText);
    const probes = [...standing];
    let note = '';
    if (standing.length === 0) {
      // The plant is the text this file carried until #716: a bone's rotation
      // after its y, which is what the constructor wrote and the editor does not.
      const bone = /export interface SpineBone \{[\s\S]*?\n\}/.exec(typesText)?.[0] ?? '';
      const rotation = /\n {2}\/\*\*[^\n]*\*\/\n {2}rotation\?: number;|\n {2}rotation\?: number;/.exec(bone)?.[0] ?? '';
      const moved = rotation === '' ? '' : bone.replace(rotation, '').replace('\n  y?: number;', `\n  y?: number;${rotation}`);
      const raised = moved === '' || moved === bone ? [] : raisedBy(scanTypes(typesText.replace(bone, moved)), { was: standing });
      if (raised.length !== 1) probes.push(`SpineBone's rotation moved after y raised ${raised.length} fault(s) and this control requires one`);
      else note = `SpineBone's rotation moved after y: "${raised[0]}"`;
    }
    const held = probes.length === 0;
    say(
      'CUR84_THE_SPINE_INTERFACES_DECLARE_THEIR_FIELDS_IN_THE_ORDER_THE_TABLE_EMITS_THEM',
      held,
      probeDetail(
        held,
        probes,
        `${DECLARED.length} interface(s) and SpineConstraint, each declaring the fields its row orders in that ` +
          `row's order — and ${note}`,
      ),
      'this file said for two releases that its field order was rigc\'s and not the editor\'s, and that changing ' +
        'it would say nothing; #716 changed the emitted order, and a declaration left behind would teach the old ' +
        'one to the next constructor written against it',
    );
  }

  // --- CUR85-CUR86: the consumer-driven sentences the guide quotes (issue #784)
  //
  // The two texts an agent meets when a muted constraint is the question — the
  // SKIP a declared one earns and the third door a refusal offers — are read
  // off the validator's own report on a generated rig, never typed here, and
  // the guide is held to carry them: `CUR85` the §5.2 rows' SKIP, `CUR86` the
  // door in the rows and the §4.12 quote whole. Each is planted on a copy of
  // the page and has to be faulted.
  {
    const guidePath = 'docs/AUTHORING.md';
    const guideText = readFileSync(join(root, guidePath), 'utf8');
    const flat = (text: string): string => text.replace(/\s+/g, ' ');
    const bones = [
      { name: 'root' },
      { name: 'block', parent: 'root', x: 0, y: 0, length: 12 },
      { name: 'upper', parent: 'root', x: 0, y: 0, length: 20 },
      { name: 'goal', parent: 'root', x: 10, y: 30 },
      { name: 'follower', parent: 'root', x: 40, y: 0, length: 20 },
      { name: 'source', parent: 'root', x: 60, y: 0, rotation: 45, length: 20 },
    ];
    const constraintsOf = {
      ik: { name: 'reach', type: 'ik', bones: ['upper'], target: 'goal', mix: 0 },
      transform: { name: 'follow', type: 'transform', bones: ['follower'], source: 'source', properties: { rotate: { to: { rotate: {} } } }, mixRotate: 0 },
    } as const;
    const motion = {
      spec: 'rigc-motion/1',
      archetype: 'static_probe',
      cut: 'static_probe',
      easings: {},
      animations: { move: { duration: 1, loop: false, tracks: [{ bone: 'goal', property: 'translate', keys: [{ t: 0, v: [10, 30] }, { t: 1, v: [30, 10] }] }] } },
    };
    const gateOf = (kind: 'ik' | 'transform', declared: boolean): ReturnType<typeof validate> => {
      const constraint = constraintsOf[kind];
      const dirs = writeProbeRig({
        bones,
        constraints: [constraint],
        ...(declared ? { invariants: { consumerDrivenMix: [{ constraint: constraint.name, type: kind, why: 'read off the gate' }] } } : {}),
      });
      try {
        return gateProbe(dirs, motion);
      } catch {
        // A rig the compiler refuses has nothing to quote, and the row says so rather than ending the suite.
        return { failures: [], passed: [], skipped: [], profileSkipped: [], profile: 'spine', stats: {} };
      }
    };
    const assertionOf = { ik: 'A47_IK_CONSTRAINT_NOT_MUTED_THROUGHOUT', transform: 'A48_TRANSFORM_CONSTRAINT_NOT_MUTED_THROUGHOUT' } as const;
    const said = (['ik', 'transform'] as const).map((kind) => {
      const assertion = assertionOf[kind];
      const name = constraintsOf[kind].name;
      const refusal = gateOf(kind, false).failures.find((f) => f.assertion === assertion)?.detail ?? '';
      const reason = gateOf(kind, true).skipped.find((s) => s.assertion === assertion)?.reason ?? '';
      const at = refusal.indexOf(', or declare');
      return {
        kind,
        assertion,
        refusal,
        // The row speaks of a constraint "C", so the name is the one thing substituted.
        door: at < 0 ? '' : refusal.slice(at + 2).split(`"${name}"`).join('"C"'),
        skip: reason.includes(' — ') ? reason.slice(0, reason.indexOf(' — ')) : '',
      };
    });
    const rowOf = (text: string, assertion: string): string => text.split('\n').find((line) => ruleRowOf(line, assertion)) ?? '';

    // CUR85: the SKIP a declared constraint earns, in its §5.2 row.
    {
      const scan = (text: string): string[] =>
        said.flatMap(({ assertion, skip }) =>
          skip !== '' && rowOf(text, assertion).includes(skip) ? [] : [`${guidePath}'s ${assertion} row does not quote the SKIP it prints: ${JSON.stringify(skip)}`],
        );
      const standing = scan(guideText);
      const probes = [...standing, ...said.filter((s) => s.skip === '').map((s) => `${s.assertion} printed no consumer-driven SKIP to read`)];
      let note = '';
      for (const { assertion, skip } of said) {
        const row = rowOf(guideText, assertion);
        const planted = guideText.replace(row, row.replace(skip, skip.replace('is declared', 'is marked')));
        const raised = raisedBy(scan(planted), { was: standing });
        if (raised.length !== 1) probes.push(`${assertion}'s row with its SKIP reworded was faulted ${raised.length} time(s), not once`);
        else note = `${note}${note === '' ? '' : ' · '}${raised[0]}`;
      }
      const held = probes.length === 0;
      say(
        'CUR85_THE_GUIDE_ROWS_QUOTE_THE_SKIP_A_CONSUMER_DRIVEN_CONSTRAINT_EARNS',
        held,
        probeDetail(held, probes, `${said.map((s) => `${s.assertion}: "${s.skip}"`).join(' · ')} — and, planted: ${note}`),
        'the SKIP is what a build prints over a declared constraint, so the row that explains the rule has to teach ' +
          'the words the run prints — or an agent reading a SKIP cannot find which declaration produced it',
      );
    }

    // CUR86: the third door, in both rows and in the §4.12 quote.
    {
      const scan = (text: string): string[] => {
        const faults = said.flatMap(({ assertion, door }) =>
          door !== '' && rowOf(text, assertion).includes(door) ? [] : [`${guidePath}'s ${assertion} row does not offer the third door as the refusal does: ${JSON.stringify(door)}`],
        );
        const ik = said[0].refusal;
        if (ik === '' || !flat(text).includes(flat(ik))) faults.push(`${guidePath} §4.12 does not quote the ik refusal as this build prints it: ${JSON.stringify(ik)}`);
        return faults;
      };
      const standing = scan(guideText);
      const probes = [...standing, ...said.filter((s) => s.door === '').map((s) => `${s.assertion} printed no third door to read`)];
      let note = '';
      const plant = (what: string, text: string): void => {
        const raised = raisedBy(scan(text), { was: standing });
        if (raised.length === 0) probes.push(`${what} was not faulted`);
        else note = `${note}${note === '' ? '' : ' · '}${what}: ${raised.length} fault(s)`;
      };
      const ikRow = rowOf(guideText, said[0].assertion);
      plant('the ik row with its third door dropped', guideText.replace(ikRow, ikRow.replace(`, ${said[0].door}`, '')));
      plant('the §4.12 quote with its third door dropped', guideText.replace('or key its mix above 0 in an animation, or declare that the consumer drives\nits mix', 'or key its mix above 0 in an animation'));
      const held = probes.length === 0;
      say(
        'CUR86_THE_GUIDE_OFFERS_THE_THIRD_DOOR_AS_THE_REFUSAL_PRINTS_IT',
        held,
        probeDetail(held, probes, `both rows and the §4.12 quote carry the refusal's third door as printed — and, planted: ${note}`),
        'the third door is a spelling an agent has to type, so the page that teaches it has to carry it the way the ' +
          'refusal prints it; a door the guide words differently is one nobody can copy',
      );
    }
  }

  // --- CUR89–CUR90: the loose route's texel sentence the pages quote is the one A19 prints (issue #777)
  //
  // The clauses are read off a live refusal — the articulated rig, stageless,
  // its first plain overlay rewritten as RGBA at full alpha in every texel —
  // and each page's A19 row has to carry both, verbatim, as code spans.
  // CUR74–CUR75 hold the row's `*"…"*` quotes to the base-plate sentence; these
  // are a second sentence and are quoted the way #705's already is.
  {
    const fromManifest = manifestBaseAndOverlay(ARTICULATED);
    const overlayName = basename(fromManifest.overlay.image, '.png');
    const copy = privateFixtureCopy(ARTICULATED, 'rigc-loosequote-');
    writeSolidRgbaPng(join(copy.dir, fromManifest.overlay.image), fromManifest.overlay.w, fromManifest.overlay.h, null);
    const gated = gateLooseAndPacked(
      stagelessOptionsFor(copy, buildRootIn(copy.dir, 'rigc-loosequote-out-'), 'loose'),
      'rig-play',
    );
    const live =
      gated.loose.failures.find(
        (f) => f.assertion === 'A19_OVERLAY_PNGS_HAVE_ALPHA' && new RegExp(`^part image "(?:[^"]*/)?${overlayName}\\.png" `).test(f.detail),
      )?.detail ?? '';
    const clauses = [
      /is opaque in every one of its \d+x\d+ texels/.exec(live)?.[0],
      /its file can hold transparency — .*? — and no texel uses it/.exec(live)?.[0],
    ].filter((clause): clause is string => clause !== undefined);
    /** Every A19 table row on the page, joined — the guide carries two, the base-plate table's and §5.2's. */
    const rowOf = (text: string): string =>
      text
        .split('\n')
        .filter((line) => ruleRowOf(line, 'A19_OVERLAY_PNGS_HAVE_ALPHA'))
        .join('\n');
    const absent = (row: string): string[] => clauses.filter((clause) => !row.includes(`\`${clause}\``));
    const cases: Array<[string, string]> = [
      ['CUR89_THE_LOOSE_TEXEL_SENTENCE_THE_GUIDE_QUOTES_IS_THE_ONE_A19_PRINTS', 'docs/AUTHORING.md'],
      ['CUR90_THE_LOOSE_TEXEL_SENTENCE_THE_BENCHMARK_PAGE_QUOTES_IS_THE_ONE_A19_PRINTS', 'docs/BENCHMARK.md'],
    ];
    for (const [name, path] of cases) {
      const row = rowOf(readFileSync(join(root, path), 'utf8'));
      const missing = absent(row);
      const planted = absent(row.replaceAll('and no texel uses it`', 'and no texel uses them`'));
      const probes = [
        ...(live === '' ? [`the loose build did not refuse "${overlayName}", so nothing was compared`] : []),
        ...(row === '' ? [`${path} has no A19 table row`] : []),
        ...missing.map((clause) => `${path}'s A19 row does not quote a clause A19 prints: ${JSON.stringify(clause)}`),
        ...(planted.length > missing.length ? [] : ['the same row with its last clause reworded is faulted no more often, so this reader is not reading the quote']),
        ...floorProbes([[clauses.length, 2, `${clauses.length} clause(s) were read off the live refusal`]], 'a reader that found fewer is comparing part of the sentence'),
      ];
      const held = probes.length === 0;
      say(
        name,
        held,
        probeDetail(
          held,
          probes,
          `${path}'s A19 row quotes ${clauses.map((clause) => JSON.stringify(clause)).join(' and ')}, which the loose ` +
            `route prints for "${overlayName}" at full alpha; the row with a clause reworded is faulted`,
          (count) => `${count} thing(s) the page's loose-route quote did not hold:`,
        ),
        'the page is where an author learns that saving as RGBA is not the repair, and a quote the rule does not ' +
          'print teaches a sentence nobody will meet',
      );
    }
  }

  // --- CUR91–CUR92: the contour refusal the guide quotes for a `scale:` page is the one the compiler raises (#779)
  //
  // §0.2 quotes the whole refusal a `scale: 0.5` page raises for the suite's
  // contour spec, and §3.4's refusal table quotes the clause of it that says
  // which unit the figure is in. Each quote — digits and quoted names blanked,
  // cut at every `…` — is compared against what this build raises on the same
  // fixture, and a plant exchanges the word the unit clause turns on.
  {
    const guidePath = 'docs/AUTHORING.md';
    const guide = readFileSync(join(root, guidePath), 'utf8');
    const packs = halvedMeshPacks();
    const refused = typeof packs === 'string' ? null : compileHalvedMesh(packs, packs.rigs.traced, packs.parts, packs.honest);
    const raised = typeof refused === 'string' ? `rigc compile error: ${refused}` : null;
    const shape = (text: string): string =>
      text
        .replace(/^[ \t]*#+ ?/gm, ' ')
        .replace(/"[^"]*"/g, '""')
        .replace(/\d+(\.\d+)?/g, '#')
        .replace(/\s+/g, ' ')
        .trim();
    const pieces = (quote: string | null): string[] =>
      quote === null
        ? []
        : quote
            .split('…')
            .map((piece) => shape(piece))
            .filter((piece) => piece.length > 0);
    const cases: Array<[string, string, (text: string) => string | null, number, string]> = [
      [
        'CUR91_THE_SCALE_PAGE_CONTOUR_REFUSAL_THE_GUIDE_QUOTES_IN_SECTION_0_2_IS_THE_ONE_THE_COMPILER_RAISES',
        '§0.2',
        (text) => /```bash\n(# rigc compile error:[^\n]*the outline crosses itself[^\n]*\n(?:#.*\n)*?)```/.exec(text)?.[1] ?? null,
        1,
        'the section is where an author learns that a contour\'s distances are the drawing\'s pixels on a `scale:` ' +
          'page, and the quote is the sentence they will meet there — a quote naming the texels as the unit is the ' +
          'reading #779 removed, restated in prose',
      ],
      [
        'CUR92_THE_SCALE_PAGE_ROW_OF_THE_CONTOUR_REFUSAL_TABLE_IS_A_CLAUSE_OF_THE_COMPILERS_REFUSAL',
        '§3.4 (contour refusal table)',
        (text) => /^\| any of the three above, on a packed page that declares a `scale:` \| `([^`]*)`/m.exec(text)?.[1] ?? null,
        1,
        'the table is the guide\'s index of contour refusals, and this row is where an author finds which unit the ' +
          'figure on a `scale:` page is in',
      ],
    ];
    for (const [name, where, quoteOf, floor, why] of cases) {
      const quote = quoteOf(guide);
      const taught = pieces(quote);
      const shaped = raised === null ? '' : shape(raised);
      const missing = taught.filter((piece) => !shaped.includes(piece));
      const planted = pieces(quote === null ? null : quote.replace('applied as', 'measured as'));
      const plantedMissing = planted.filter((piece) => !shaped.includes(piece));
      const probes = [
        ...(typeof packs === 'string' ? [`the fixture was not built: ${packs}`] : []),
        ...(raised === null ? ['the `scale:` page built the contour, so there is no refusal to compare against'] : []),
        ...(quote === null ? [`${guidePath} ${where} carries no quote of the refusal`] : []),
        ...firstFew(
          missing.map((piece) => `${guidePath} ${where} quotes a clause rigc does not raise: ${JSON.stringify(piece.slice(0, 110))}`),
          'clause(s)',
        ),
        ...(plantedMissing.length > missing.length
          ? []
          : ['the quote with "applied as" exchanged is faulted no more often than the real one, so this reader is not reading the words']),
        ...floorProbes([[taught.length, floor, `${taught.length} piece(s) of the quote were read`]], 'a reader that found none compared nothing'),
      ];
      const held = probes.length === 0;
      say(
        name,
        held,
        probeDetail(
          held,
          probes,
          `${taught.length} piece(s) of ${where}'s quote, digits and quoted names blanked, are clauses of the refusal the ` +
            '`scale:` page raises; the quote with "applied as" exchanged is faulted',
          (count) => `${count} clause(s) the page teaches that rigc does not raise:`,
        ),
        why,
      );
    }
    if (typeof packs !== 'string') rmSync(packs.dir, { recursive: true, force: true });
  }

  // --- CUR87-CUR88: the defaults left out, as the docs state them (#716) ----
  //
  // `PARSER_DEFAULTS` is the one table and the guide prints it; the guide's
  // advice and INGEST.md's pass line are sentences about what `build` and
  // `ingest` do, so both are read against a build and an ingest, not a copy.
  {
    const guidePath = 'docs/AUTHORING.md';
    const guideRaw = readFileSync(join(root, guidePath), 'utf8').split('\n');
    const HEAD = '| Kind | Left out when it is |';
    const spell = (rule: ParserDefault): string => {
      if (rule === null || typeof rule !== 'object') return JSON.stringify(rule);
      if ('field' in rule) return `\`${rule.field}\`'s${rule.only === undefined ? '' : `, only at ${JSON.stringify(rule.only)}`}`;
      return `the key before's, ${JSON.stringify(rule.first)} on key 0`;
    };
    const scanGuide = (lines: readonly string[]): string[] => {
      const at = lines.indexOf(HEAD);
      if (at < 0) return [`${guidePath} carries no table headed ${JSON.stringify(HEAD)}, so the defaults it teaches are unchecked`];
      const printed: Array<[string, string]> = [];
      for (let i = at + 2; i < lines.length && lines[i].startsWith('|'); i++) {
        const cells = lines[i].split('|').slice(1, -1).map((cell) => cell.trim());
        printed.push([/^`([^`]+)`$/.exec(cells[0] ?? '')?.[1] ?? `(unreadable row ${i + 1})`, cells[1] ?? '']);
      }
      const faults: string[] = [];
      for (const [kind, cell] of printed) {
        const row = PARSER_DEFAULTS[kind];
        const want = row === undefined ? '' : Object.entries(row).map(([field, rule]) => `\`${field}\` ${spell(rule)}`).join(' · ');
        if (row === undefined) faults.push(`${guidePath} prints a row for "${kind}", which the table does not have`);
        else if (cell !== want) faults.push(`${guidePath} prints "${kind}" as ${cell} and the table says ${want}`);
      }
      for (const kind of Object.keys(PARSER_DEFAULTS)) if (!printed.some(([k]) => k === kind)) faults.push(`${guidePath} prints no row for "${kind}"`);
      const inOrder = printed.map(([k]) => k).filter((k) => PARSER_DEFAULTS[k] !== undefined);
      const wantOrder = Object.keys(PARSER_DEFAULTS).filter((k) => inOrder.includes(k));
      if (inOrder.join(',') !== wantOrder.join(',')) faults.push(`${guidePath} prints the rows in another order than the table holds them`);
      return faults;
    };
    const standing = scanGuide(guideRaw);
    // The guide's advice, measured: the base probe rig states a bone at `x: 0,
    // y: 0`; the spec keeps both and the build leaves both out.
    const probe = writeProbeRig();
    const probeMotion = join(probe.dir, 'probe.motion.json');
    writeFileSync(probeMotion, `${JSON.stringify(STATIC_MOTION, null, 2)}\n`);
    const specBone = (JSON.parse(readFileSync(probe.rigPath, 'utf8')) as { bones: Array<Record<string, unknown>> }).bones.find((b) => b.name === 'block');
    const builtBone = (JSON.parse(compile({ rigPath: probe.rigPath, motionPath: probeMotion, outDir: probe.outDir, imagesDir: probe.dir }).skeletonText) as {
      bones: Array<Record<string, unknown>>;
    }).bones.find((b) => b.name === 'block');
    const advice = [
      ...(specBone?.x === 0 && specBone?.y === 0 ? [] : ['the probe rig states no bone at x: 0, y: 0, so the advice was not measured']),
      ...(builtBone !== undefined && !('x' in builtBone) && !('y' in builtBone)
        ? []
        : [`the probe's bone stated at x: 0, y: 0 is emitted ${JSON.stringify(builtBone)} — §10.5 says the file leaves both out`]),
      ...(guideRaw.some((line) => line.includes('in a rig spec is legitimate and stays in the spec — and the file leaves it out'))
        ? []
        : [`${guidePath} §10.5 no longer says a stated default stays in the spec and leaves the file, so this measures a sentence that is gone`]),
    ];
    const probes = [...standing, ...advice];
    const head = guideRaw.indexOf(HEAD);
    let note = '';
    if (head >= 0 && standing.length === 0) {
      const first = head + 2;
      const cells = guideRaw[first].split('|');
      const planted = guideRaw.map((line, i) => (i === first ? [...cells.slice(0, 2), ` ${cells[2].trim()} · \`planted\` 0 `, ...cells.slice(3)].join('|') : line));
      const raised = raisedBy(scanGuide(planted), { was: standing });
      if (raised.length !== 1) probes.push(`a key added to the first printed row raised ${raised.length} fault(s) and this control requires one`);
      else note = `a key added to the first printed row: "${raised[0]}"`;
    }
    const held = probes.length === 0;
    say(
      'CUR87_THE_DEFAULTS_THE_GUIDE_SAYS_THE_FILE_LEAVES_OUT_ARE_THE_ONES_A_BUILD_LEAVES_OUT',
      held,
      probeDetail(
        held,
        probes,
        `${guidePath} prints ${Object.keys(PARSER_DEFAULTS).length} row(s), each the table's own in the table's ` +
          `order; §10.5's advice measured — a bone the spec states at x: 0, y: 0 is emitted with neither — and ${note}`,
      ),
      'the guide is what an agent reads to know which keys a rebuild will not carry, and §10.5 told it until #716 ' +
        'that rigc does the opposite of the exporter; a row or a sentence copied by hand is the one that is stale ' +
        'the day the table changes',
    );
  }
  {
    const ingestPath = 'docs/INGEST.md';
    const ingestText = readFileSync(join(root, ingestPath), 'utf8');
    const declared = EDITOR_KEY_ORDER.header.filter((k) => !(RIG_KEYS.RigSkeletonHeader as readonly string[]).includes(k));
    // What `ingest` says about each header key, off a header carrying every key
    // the editor writes — and what the rebuild then writes.
    const headerProbe = {
      skeleton: { hash: 'probe-hash', spine: SPINE_VERSION, x: -10, y: -10, width: 20, height: 20, images: './images/', audio: null },
      bones: [{ name: 'root' }],
      slots: [],
      skins: [{ name: 'default', attachments: {} }],
      animations: {},
    };
    const read = ingest(headerProbe, { name: 'header_probe', art: 'none', source: 'skeleton.json', version: '0' });
    const codeFor = new Map<string, string>();
    for (const f of read.findings) {
      const key = /^skeleton\.(\w+)$/.exec(f.where)?.[1];
      if (key !== undefined && (f.code === 'HEADER_BOOKKEEPING' || f.code === 'HEADER_REDERIVED')) codeFor.set(key, f.code);
    }
    const scanIngest = (text: string): string[] => {
      const faults: string[] = [];
      const pass = /\*\*The pass line of the byte round trip, stated once:\*\*([\s\S]*?)\n\n/.exec(text)?.[1] ?? null;
      if (pass === null) return [`${ingestPath} states no pass line of the byte round trip, so what it promises is unchecked`];
      const apart = /apart from ((?:`[^`]+`(?:,\s*|\s+and\s+)?)+)/.exec(pass.replace(/\s+/g, ' '))?.[1] ?? '';
      const named = [...apart.matchAll(/`([^`]+)`/g)].map((m) => m[1]);
      if (named.join(',') !== declared.join(',')) {
        faults.push(`${ingestPath}'s pass line is stated apart from ${named.join(', ') || 'nothing'}, and the declared exceptions are ${declared.join(', ')}`);
      }
      const lines = text.split('\n');
      const at = lines.indexOf('| Header key | Example, rebuild vs export | Why it is an exception |');
      const rows: Array<[string, string]> = [];
      for (let i = at + 2; at >= 0 && i < lines.length && lines[i].startsWith('|'); i++) {
        const cells = lines[i].split('|').slice(1, -1).map((cell) => cell.trim());
        rows.push([/^`([^`]+)`$/.exec(cells[0] ?? '')?.[1] ?? '', [...(cells[2] ?? '').matchAll(/`(HEADER_[A-Z_]+)`/g)].map((m) => m[1]).join(',')]);
      }
      if (at < 0) faults.push(`${ingestPath} carries no table of the declared exceptions`);
      else if (rows.map(([k]) => k).join(',') !== declared.join(',')) {
        faults.push(`${ingestPath}'s exceptions table lists ${rows.map(([k]) => k).join(', ')}, and the declared exceptions are ${declared.join(', ')}`);
      }
      for (const [key, code] of rows) {
        if (code !== (codeFor.get(key) ?? '')) faults.push(`${ingestPath} names ${code || 'no finding'} for \`${key}\`, and ingest reports ${codeFor.get(key) ?? 'none'}`);
      }
      return faults;
    };
    const standing = scanIngest(ingestText);
    // The rebuild side of the same sentence: every header key but the
    // declared ones comes back, `audio: null` included.
    const probeDir = mkdtempSync(join(harnessTemp(), 'rigc-header-probe-'));
    writeFileSync(join(probeDir, 'rig.json'), `${JSON.stringify(read.rig, null, 2)}\n`);
    writeFileSync(join(probeDir, 'motion.json'), `${JSON.stringify(read.motion, null, 2)}\n`);
    let rebuilt: Record<string, unknown> | null = null;
    const refused = refusalOf(() => {
      rebuilt = (JSON.parse(compile({ rigPath: join(probeDir, 'rig.json'), motionPath: join(probeDir, 'motion.json'), outDir: join(probeDir, 'B') }).skeletonText) as {
        skeleton: Record<string, unknown>;
      }).skeleton;
    });
    const header = headerProbe.skeleton as Record<string, unknown>;
    const back = rebuilt as Record<string, unknown> | null;
    // The box is not carried since issue #907: the rebuild computes the setup-pose bounding box (`headerBoundsOf`),
    // and `IG97` holds it to `getBounds` of the source — so the four box keys are left out of "comes back as stated".
    const computed = ['x', 'y', 'width', 'height'];
    const lost = back === null ? [] : Object.keys(header).filter((k) => !declared.includes(k) && !computed.includes(k) && JSON.stringify(back[k]) !== JSON.stringify(header[k]));
    const probes = [
      ...standing,
      ...(refused === null ? [] : [`the header probe's rebuild was refused: ${refused}`]),
      ...(codeFor.has('audio') ? [`ingest reports ${codeFor.get('audio')} for \`audio\`, which the rig spec carries`] : []),
      ...lost.map((k) => `the rebuild writes \`${k}\` as ${JSON.stringify(back?.[k])} where the source states ${JSON.stringify(header[k])}`),
    ];
    let note = '';
    if (standing.length === 0) {
      const passAt = ingestText.indexOf('**The pass line of the byte round trip, stated once:**');
      const planted =
        passAt < 0 ? ingestText : ingestText.slice(0, passAt) + ingestText.slice(passAt).replace(/apart from `hash` and\s+`spine`/, 'apart from `hash`, `audio` and `spine`');
      const raised = planted === ingestText ? [] : raisedBy(scanIngest(planted), { was: standing });
      if (raised.length !== 1) probes.push(`\`audio\` added back to the pass line raised ${raised.length} fault(s) and this control requires one`);
      else note = `\`audio\` added back to the pass line: "${raised[0]}"`;
    }
    const held = probes.length === 0;
    say(
      'CUR88_INGESTS_PASS_LINE_NAMES_THE_DECLARED_EXCEPTIONS_AND_THE_FINDINGS_INGEST_PRINTS_FOR_THEM',
      held,
      probeDetail(
        held,
        probes,
        `${ingestPath}'s pass line is stated apart from ${declared.map((k) => `\`${k}\``).join(' and ')} — the ` +
          `header keys the editor writes and the rig spec has no field for — and its table names the finding ` +
          `ingest prints for each (${declared.map((k) => `${k} ${codeFor.get(k) ?? 'none'}`).join(', ')}); a header ` +
          `carrying every key the editor writes rebuilds with every other one as stated — and ${note}`,
      ),
      'the pass line is the promise #716 was opened to keep, and the reader who needs it is one comparing a ' +
        'rebuild with an export by hand: an exception the page names and the tools do not, or the reverse, is a ' +
        'difference that reader is told to ignore or told to chase for nothing',
    );
  }

  // --- CUR93-CUR94: §10.6b's two production-set sentences, held to the code (#791)
  //
  // The guide says where a mesh's `path`/`color` go and which characters the
  // comparator folds, and that both come from a production set rather than
  // from `examples/`. Neither is a table a control can re-derive from the
  // public tree, so each sentence is held to the code that implements it.
  {
    const guidePath = 'docs/AUTHORING.md';
    const compilePath = 'src/compile.ts';
    const guideText = readFileSync(join(root, guidePath), 'utf8');
    const compileText = readFileSync(join(root, compilePath), 'utf8');
    const flat = (text: string): string => text.replace(/\s+/g, ' ');
    const sectionOf = (text: string): string | null => {
      // A ##### under §10.6 since issue #1397, which counts §<n>.<m> and §<n>.<m>.<k> and holds the written numbers to
      // the count: a lettered 10.6b is no count, so it sits below the levels that are addressed.
      const at = text.indexOf('\n##### 10.6b ');
      const ends = at < 0 ? [] : ['\n### ', '\n#### ', '\n##### '].map((mark) => text.indexOf(mark, at + 1)).filter((k) => k >= 0);
      const end = ends.length === 0 ? -1 : Math.min(...ends);
      return at < 0 ? null : text.slice(at, end < 0 ? undefined : end);
    };
    /** A doc comment's text with its ` * ` gutters taken off, flattened. */
    const commentAbove = (text: string, declaration: string): string | null => {
      const at = text.indexOf(declaration);
      if (at < 0) return null;
      const close = text.lastIndexOf('*/', at);
      const open = text.lastIndexOf('/**', close);
      if (close < 0 || open < 0 || text.slice(close + 2, at).trim() !== '') return null;
      return flat(text.slice(open + 3, close).replace(/^\s*\* ?/gm, ''));
    };

    // CUR93 — the mesh sentence, in the guide and above `meshTextureKeys`, and
    // the one mesh constructor writing the two keys right after `type`.
    //
    // ⚠️ Since issue #917 that constructor is `emitMesh` in `src/emit_spine.ts`:
    // `compile.ts` builds mesh RECORDS, whose key order is no byte, and the
    // emitter restates the order the six mesh literals here used to open with.
    // The scan read `: SpineMeshAttachment = {` literals in `compile.ts` until
    // then, and found none once the records moved — the plant is the scan's to
    // change, and it now reads the literal that owns the bytes.
    const MESH_SENTENCE = 'right after `type`, `path` before `color` — measured on a production set (#791), not on `examples/`';
    const emitPath = 'src/emit_spine.ts';
    const emitText = readFileSync(join(root, emitPath), 'utf8');
    const scanMesh = (guide: string, code: string, emitter: string): { faults: string[]; literals: number } => {
      const faults: string[] = [];
      const section = sectionOf(guide);
      if (section === null) faults.push(`${guidePath} has no §10.6b`);
      else if (!flat(section).includes(MESH_SENTENCE)) faults.push(`${guidePath} §10.6b does not say ${JSON.stringify(MESH_SENTENCE)}`);
      const comment = commentAbove(code, 'function meshTextureKeys(');
      if (comment === null) faults.push(`${compilePath} has no doc comment directly above \`function meshTextureKeys(\``);
      else if (!comment.includes(MESH_SENTENCE)) faults.push(`${compilePath}'s comment above \`meshTextureKeys\` does not say ${JSON.stringify(MESH_SENTENCE)}`);
      const lines = emitter.split('\n');
      let literals = 0;
      lines.forEach((line, i) => {
        if (line.trim() !== "type: 'mesh',") return;
        literals++;
        const next = lines.slice(i + 1, i + 3).map((l) => l.trim());
        if (!next[0].startsWith('...(mesh.path !== undefined') || !next[1].startsWith('...(mesh.color !== undefined')) {
          faults.push(`${emitPath}:${i + 1}: the mesh literal follows \`type\` with ${JSON.stringify(next.join(' '))} — \`path\` then \`color\` is the order §10.6b states`);
        }
      });
      return { faults, literals };
    };
    const meshScan = scanMesh(guideText, compileText, emitText);
    const meshProbes = [
      ...meshScan.faults,
      ...floorProbes([[meshScan.literals, 1, `${meshScan.literals} mesh literal(s) found`]], 'so no constructor was read'),
    ];
    let meshNote = '';
    if (meshProbes.length === 0) {
      // Plant 1: the literal's `path` moved to its end. Plant 2: the guide's
      // sentence with the set it names exchanged.
      const lines = emitText.split('\n');
      const open = lines.findIndex((line) => line.trim() === "type: 'mesh',");
      const spread = lines[open + 1];
      const moved = [...lines.slice(0, open + 1), ...lines.slice(open + 2)];
      const close = moved.findIndex((line, i) => i > open && line.trim() === '};');
      moved.splice(close, 0, spread);
      const codeRaised = raisedBy(scanMesh(guideText, compileText, moved.join('\n')).faults, { was: meshScan.faults });
      const guideRaised = raisedBy(scanMesh(guideText.replace('measured on a production set (#791), not on', 'measured on a public set (#791), not on'), compileText, emitText).faults, {
        was: meshScan.faults,
      });
      if (codeRaised.length !== 1) meshProbes.push(`the mesh literal's \`path\` moved to its end raised ${codeRaised.length} fault(s) and this control requires one`);
      if (guideRaised.length !== 1) meshProbes.push(`the guide's set exchanged raised ${guideRaised.length} fault(s) and this control requires one`);
      if (codeRaised.length === 1 && guideRaised.length === 1) meshNote = `the literal's \`path\` moved last: "${codeRaised[0]}"; the guide's set exchanged: "${guideRaised[0]}"`;
    }
    const meshHeld = meshProbes.length === 0;
    say(
      'CUR93_THE_GUIDES_MESH_PATH_AND_COLOR_SENTENCE_IS_THE_CONSTRUCTORS_AND_EVERY_MESH_LITERAL_KEEPS_IT',
      meshHeld,
      probeDetail(
        meshHeld,
        meshProbes,
        `${guidePath} §10.6b and the comment above \`meshTextureKeys\` both say ${JSON.stringify(MESH_SENTENCE)}, and ` +
          `the ${meshScan.literals} mesh literal(s) in ${emitPath} follow \`type\` with \`path\` then \`color\` — and ${meshNote}`,
      ),
      'the position is a production measurement no row carries, so the constructor is the only place it lives — ' +
        '`emitMesh` since issue #917 moved the bytes to the Spine emitter: a mesh literal that writes the two keys ' +
        'anywhere else, or a guide that says they come from `examples/`, is the claim drifting from the one place it is kept',
    );

    // CUR94 — the fold's sentence: its name, and the code points it states.
    const foldTokens = (table: ReadonlyArray<readonly [number, number, number]>): string[] =>
      table.flatMap(([first, last, to]) =>
        (last === first ? [first, to] : [first, last, to, to + last - first]).map((code) => `U+${code.toString(16).toUpperCase().padStart(4, '0')}`),
      );
    const scanFold = (guide: string, code: string, table: ReadonlyArray<readonly [number, number, number]>): string[] => {
      const faults: string[] = [];
      const section = sectionOf(guide);
      const sentence = section === null ? null : (section.split('\n').find((line) => line.includes('`foldBeforeComparing`')) ?? null);
      if (sentence === null) faults.push(`${guidePath} §10.6b names no \`foldBeforeComparing\``);
      else {
        const stated = [...sentence.matchAll(/U\+[0-9A-F]{4}/g)].map((m) => m[0]);
        const want = foldTokens(table);
        if (stated.join(',') !== want.join(',')) faults.push(`${guidePath} §10.6b states the fold as ${stated.join(', ')} and \`EDITOR_NAME_FOLD\` holds ${want.join(', ')}`);
      }
      if (!/\nfunction foldBeforeComparing\(/.test(code)) faults.push(`${compilePath} declares no \`foldBeforeComparing\``);
      const readName = /\nfunction readName\([\s\S]*?\n\}/.exec(code)?.[0] ?? '';
      if (!readName.includes('foldBeforeComparing(')) faults.push(`${compilePath}'s \`readName\` does not call \`foldBeforeComparing\`, so the comparator compares unfolded`);
      return faults;
    };
    const foldStanding = scanFold(guideText, compileText, EDITOR_NAME_FOLD);
    const foldProbes = [...foldStanding, ...floorProbes([[EDITOR_NAME_FOLD.length, 1, `${EDITOR_NAME_FOLD.length} fold range(s)`]], 'so there is nothing to state')];
    let foldNote = '';
    if (foldProbes.length === 0) {
      const narrowed = EDITOR_NAME_FOLD.map(([first, last, to], i) => (i === EDITOR_NAME_FOLD.length - 1 ? ([first, last - 1, to] as const) : ([first, last, to] as const)));
      const tableRaised = raisedBy(scanFold(guideText, compileText, narrowed), { was: foldStanding });
      const unwired = raisedBy(scanFold(guideText, compileText.replace('foldUp(foldBeforeComparing(name))', 'foldUp(name)'), EDITOR_NAME_FOLD), { was: foldStanding });
      if (tableRaised.length !== 1) foldProbes.push(`the table's last range narrowed by one raised ${tableRaised.length} fault(s) and this control requires one`);
      if (unwired.length !== 1) foldProbes.push(`\`readName\` without the fold raised ${unwired.length} fault(s) and this control requires one`);
      if (tableRaised.length === 1 && unwired.length === 1) foldNote = `the last range narrowed: "${tableRaised[0]}"; the fold unwired: "${unwired[0]}"`;
    }
    const foldHeld = foldProbes.length === 0;
    say(
      'CUR94_THE_FOLD_THE_GUIDE_NAMES_IS_THE_ONE_THE_COMPARATOR_APPLIES',
      foldHeld,
      probeDetail(
        foldHeld,
        foldProbes,
        `${guidePath} §10.6b names \`foldBeforeComparing\` and states ${foldTokens(EDITOR_NAME_FOLD).join(', ')}, ` +
          `\`EDITOR_NAME_FOLD\`'s own ranges, and \`readName\` calls it — and ${foldNote}`,
      ),
      'the fold is measured on one production map and no public file can re-take it, so the guide\'s statement of ' +
        'which characters it covers is only as good as its agreement with the table the comparator reads',
    );
  }

  // --- CUR95: the interval the docs state for `damping` is the row's (#794) --
  //
  // The guide quotes `damping`'s bound in more than one section, and the row it
  // quotes moved from `(0, 1)` to `[0, 1]` with #794 and to `[0, 1)` with #1422.
  // A quote left behind states a bound the tool does not hold: the closed one
  // tells an author that 1 is accepted, which #1422 measured resonating.
  {
    const docPaths = ['README.md', ...trackedIn(root, 'docs', (name) => name.endsWith('.md'))];
    const dampingDocs = docPaths.map((path) => [path, readFileSync(join(root, path), 'utf8')] as const);
    const QUOTED = /`damping`[^.|;]{0,40}?`?([[(]0, ?1[\])])/g;
    const scanDampingBound = (texts: ReadonlyArray<readonly [string, string]>, states: string): { faults: string[]; quotes: number } => {
      const want = /[[(]0, ?1[\])]/.exec(states)?.[0] ?? null;
      const faults: string[] = want === null ? [`the \`damping\` row states ${JSON.stringify(states)}, which carries no interval to quote`] : [];
      let quotes = 0;
      for (const [path, text] of texts) {
        text.split('\n').forEach((line, i) => {
          for (const m of line.matchAll(QUOTED)) {
            quotes++;
            if (m[1] !== want) faults.push(`${path}:${i + 1} states \`damping\` inside ${m[1]} and the row states ${want}`);
          }
        });
      }
      return { faults, quotes };
    };
    const row = physicsRuleFor('damping');
    const states = row?.states ?? '(no damping row)';
    const standing = scanDampingBound(dampingDocs, states);
    const probes = [...standing.faults, ...floorProbes([[standing.quotes, 1, `${standing.quotes} quote(s) of damping's interval found`]], 'so no doc was read')];
    let note = '';
    if (probes.length === 0) {
      const rowRaised = raisedBy(scanDampingBound(dampingDocs, states.includes('[') ? 'inside (0, 1)' : 'inside [0, 1]').faults, { was: standing.faults });
      // The guide's first quote put back to an interval the row does not state — the closed one #1422 left, or the
      // half-open one where the row states another.
      const stale = states.includes('[0, 1)') ? '[0, 1]' : '[0, 1)';
      const reverted = dampingDocs.map(([path, text]) =>
        [path, path === 'docs/AUTHORING.md' ? text.replace(/(`damping`[^.|;]{0,40}?`?)[[(]0, ?1[\])]/, `$1${stale}`) : text] as const,
      );
      const quoteRaised = raisedBy(scanDampingBound(reverted, states).faults, { was: standing.faults });
      if (rowRaised.length !== standing.quotes) probes.push(`the row's interval exchanged raised ${rowRaised.length} fault(s) and this control requires one per quote, ${standing.quotes}`);
      if (quoteRaised.length !== 1) probes.push(`the guide's first quote reverted raised ${quoteRaised.length} fault(s) and this control requires one`);
      if (rowRaised.length === standing.quotes && quoteRaised.length === 1) note = `the row exchanged: "${rowRaised[0]}"; a quote reverted: "${quoteRaised[0]}"`;
    }
    const held = probes.length === 0;
    say(
      'CUR95_EVERY_INTERVAL_THE_DOCS_STATE_FOR_DAMPING_IS_THE_ONE_ITS_BOUND_ROW_STATES',
      held,
      probeDetail(
        held,
        probes,
        `${standing.quotes} quote(s) of \`damping\`'s interval across README.md and docs/, each ${JSON.stringify(states)}'s — and ${note}`,
      ),
      'the bound is one row read by the compiler and by A23, and the guide is the only other place an author learns it: ' +
        'a quote that kept an interval after the row moved is a guide stating a bound the tool does not hold, either way',
    );
  }

  // --- CUR97: the retired sequence-size refusal is quoted nowhere (#795) ---
  //
  // The compiler no longer compares a series' stated size with its frames, so
  // the refusal's sentence and the guide's "refused, as it is for one region"
  // would each tell an author to change a correct spec. Held both ways: the
  // tree carries neither, and either one planted back into the guide is named.
  {
    const RETIRED = [
      "a packed frame's rectangle is fixed",
      'a stated size that disagrees with a packed frame is refused',
    ];
    const scanned = ['docs/AUTHORING.md', 'README.md', 'src/compile.ts', 'src/rig.ts'];
    const texts = scanned.map((path) => [path, readFileSync(join(root, path), 'utf8').replace(/\s+/g, ' ')] as const);
    const scanRetired = (population: ReadonlyArray<readonly [string, string]>): string[] =>
      population.flatMap(([path, text]) => RETIRED.filter((sentence) => text.includes(sentence)).map((sentence) => `${path} still says "${sentence}"`));
    const standing = scanRetired(texts);
    const plantProbes = RETIRED.flatMap((sentence) => {
      const planted = scanRetired(texts.map(([path, text]) => [path, path === 'docs/AUTHORING.md' ? `${text} ${sentence}` : text] as const));
      return planted.length === standing.length + 1 ? [] : [`"${sentence}" planted into the guide raised ${planted.length - standing.length} fault(s), and one is required`];
    });
    const retiredProbes = [...standing, ...plantProbes];
    say(
      'CUR97_THE_RETIRED_SEQUENCE_SIZE_REFUSAL_IS_QUOTED_NOWHERE',
      retiredProbes.length === 0,
      probeDetail(
        retiredProbes.length === 0,
        retiredProbes,
        `${RETIRED.length} retired sentence(s) absent from ${scanned.join(', ')}, and each planted into the guide is named`,
      ),
      'a sentence the compiler no longer raises, left in the guide, is an instruction to break a correct spec — the ' +
        'series the editor exports with its setup frame\'s size — and nothing else in the run reads the guide for it',
    );
  }

  // --- CUR100: the guide's physics basis table is the rows' own (#798) -----
  //
  // §4.4 states, per bounded field, the two intervals and the basis of every
  // way out. All of it is read off `PHYSICS_POSE_RULES` here — the table's
  // fields, intervals, kinds and sentences — so no literal in this control can
  // agree with a stale guide on its own. The plants break the DATA: each arm's
  // kind flipped in a copy of the rows, and one kind in the guide reverted.
  {
    type BoundRow = (typeof PHYSICS_POSE_RULES)[number];
    type BoundArm = BoundRow['basis'][number];
    const guideText = readFileSync(join(root, 'docs/AUTHORING.md'), 'utf8');
    const HEADER = '| field | at rest | on a key | basis |';
    const cellOf = (arm: BoundArm): string => `${arm.kind}: ${arm.kind === 'arithmetic' ? physicsBasisSays(arm) : arm.does}`;
    const scanBasisTable = (text: string, rows: readonly BoundRow[]): { faults: string[]; rows: number } => {
      const lines = text.split('\n');
      const start = lines.findIndex((line) => line.trim() === HEADER);
      if (start < 0) return { faults: [`docs/AUTHORING.md has no table headed "${HEADER}"`], rows: 0 };
      const body: Array<{ at: number; cells: string[] }> = [];
      for (let i = start + 2; i < lines.length && lines[i].trim().startsWith('|'); i++) {
        body.push({ at: i + 1, cells: lines[i].trim().slice(1, -1).split(' | ').map((cell) => cell.trim()) });
      }
      const faults: string[] = [];
      for (const rule of rows) {
        const mine = body.filter((row) => row.cells[0] === `\`${rule.timeline}\``);
        if (mine.length !== 1) {
          faults.push(`the table has ${mine.length} line(s) for \`${rule.timeline}\`, and one is required`);
          continue;
        }
        const [, rest, key, basis] = mine[0].cells;
        const where = `docs/AUTHORING.md:${mine[0].at}`;
        if (rest !== `\`${rule.states}\``) faults.push(`${where} states ${rule.timeline} at rest as ${rest} and the row states \`${rule.states}\``);
        if (key !== `\`${rule.statesKeyed}\``) faults.push(`${where} states ${rule.timeline} on a key as ${key} and the row states \`${rule.statesKeyed}\``);
        for (const arm of rule.basis) {
          if (!(basis ?? '').includes(cellOf(arm))) faults.push(`${where} does not state ${rule.timeline}'s ${arm.kind} way out at ${arm.witness.value} as the row does`);
        }
        const labels = (basis ?? '').match(/\b(arithmetic|behavioural): /g)?.length ?? 0;
        if (labels !== rule.basis.length) faults.push(`${where} states ${labels} basis(es) for ${rule.timeline} and the row has ${rule.basis.length}`);
      }
      for (const row of body) {
        if (!rows.some((rule) => row.cells[0] === `\`${rule.timeline}\``)) faults.push(`docs/AUTHORING.md:${row.at} states a bound for ${row.cells[0]}, which no row bounds`);
      }
      return { faults, rows: body.length };
    };
    const standing = scanBasisTable(guideText, PHYSICS_POSE_RULES);
    const armCount = PHYSICS_POSE_RULES.reduce((sum, rule) => sum + rule.basis.length, 0);
    const probes = [...standing.faults, ...floorProbes([[standing.rows, PHYSICS_POSE_RULES.length, `${standing.rows} table line(s) read`]], 'one per bounded field')];
    let note = '';
    if (probes.length === 0) {
      const flips = PHYSICS_POSE_RULES.flatMap((rule, r) =>
        rule.basis.map((arm) => {
          const other: BoundArm =
            arm.kind === 'arithmetic'
              ? { kind: 'behavioural', when: arm.when, witness: arm.witness, does: arm.expression }
              : { kind: 'arithmetic', when: arm.when, witness: arm.witness, expression: arm.does, lines: '' };
          const rows = PHYSICS_POSE_RULES.map((one, i) => (i === r ? { ...one, basis: one.basis.map((a) => (a === arm ? other : a)) } : one));
          return raisedBy(scanBasisTable(guideText, rows).faults, { was: standing.faults }).length;
        }),
      );
      const reverted = guideText.replace(/(\| `[a-z]+` \| `[^`]+` \| `[^`]+` \| )behavioural: /, '$1arithmetic: ');
      const quoteRaised = raisedBy(scanBasisTable(reverted, PHYSICS_POSE_RULES).faults, { was: standing.faults });
      if (!flips.every((n) => n === 1) || flips.length !== armCount) probes.push(`flipping each of the ${armCount} arm(s)' kind raised ${flips.join(', ')} fault(s), and one each is required`);
      if (quoteRaised.length !== 1) probes.push(`the guide's first behavioural basis reverted to arithmetic raised ${quoteRaised.length} fault(s) and this control requires one`);
      if (probes.length === 0) note = `each of the ${armCount} arm(s) flipped in the rows raises one fault; a kind reverted in the guide: "${quoteRaised[0]}"`;
    }
    const held = probes.length === 0;
    say(
      'CUR100_EVERY_BOUND_AND_BASIS_THE_GUIDE_STATES_FOR_THE_FOUR_PHYSICS_FIELDS_IS_ITS_ROWS',
      held,
      probeDetail(
        held,
        probes,
        `${standing.rows} line(s) of §4.4's basis table, ${armCount} way(s) out, each field's intervals and every basis sentence the rows' own — and ${note}`,
      ),
      'the basis table is where an author learns whether a refusal is the runtime or rigc, and it is the rows\' text ' +
        'verbatim: a kind changed in the rows and not in the guide is a guide telling the author the runtime cannot ' +
        'take a value it plays, which is the sentence #798 removed from `src/types.ts`',
    );
  }

  // --- CUR101: the retired physics-bound sentences are said nowhere (#798) --
  //
  // Each of these told an author that a value the runtime runs finitely is one
  // it cannot use, or that a mirrored constraint is muted. Held both ways: the
  // tree carries none, and each planted back into the guide is named.
  {
    const RETIRED = [
      "they are the runtime's, not a policy",
      'a keyed physics value the runtime cannot use',
      'an infinite inverse mass — the constraint stops moving',
      'keys its mix above 0; it is muted —',
    ];
    const scanned = ['README.md', 'src/types.ts', 'src/timelines.ts', 'src/validate.ts', ...trackedIn(root, 'docs', (name) => name.endsWith('.md'))];
    const texts = scanned.map((path) => [path, readFileSync(join(root, path), 'utf8').replace(/\s+\*?\s*/g, ' ')] as const);
    const scanRetired = (population: ReadonlyArray<readonly [string, string]>): string[] =>
      population.flatMap(([path, text]) => RETIRED.filter((sentence) => text.includes(sentence)).map((sentence) => `${path} still says "${sentence}"`));
    const standing = scanRetired(texts);
    const plantProbes = RETIRED.flatMap((sentence) => {
      const planted = scanRetired(texts.map(([path, text]) => [path, path === 'docs/AUTHORING.md' ? `${text} ${sentence}` : text] as const));
      return planted.length === standing.length + 1 ? [] : [`"${sentence}" planted into the guide raised ${planted.length - standing.length} fault(s), and one is required`];
    });
    const retiredProbes = [...standing, ...plantProbes];
    say(
      'CUR101_THE_RETIRED_PHYSICS_BOUND_SENTENCES_ARE_SAID_NOWHERE',
      retiredProbes.length === 0,
      probeDetail(
        retiredProbes.length === 0,
        retiredProbes,
        `${RETIRED.length} retired sentence(s) absent from ${scanned.length} file(s), and each planted into the guide is named`,
      ),
      'three of them called a value the runtime plays one it cannot use, and the fourth told a constraint moving its ' +
        'bone against the jiggle that it is muted; each is the reason an author would take a correct refusal for a ' +
        'wrong one, or a wrong one for correct',
    );
  }

  // --- CUR102: the retired `lengths` sentences are quoted nowhere (#804) ------
  //
  // A path's `lengths` was refused when authored, dropped by `ingest` as a loss
  // and re-measured, and a comment claimed the re-measure matched the editor to
  // the digit. All three are gone from the code; a sentence left in the guide
  // would tell an author to delete an export's own array. Held both ways, as
  // `CUR97` is: the tree carries none, and each planted into the guide is named.
  {
    const RETIRED = [
      '"lengths" is not authored',
      'rigc RE-MEASURES it',
      'which rigc re-measures',
      'reproduces every digit the editor printed',
    ];
    const scanned = ['docs/AUTHORING.md', 'docs/INGEST.md', 'docs/SPEC_COVERAGE.md', 'README.md', 'src/compile.ts', 'src/rig.ts', 'src/ingest.ts', 'src/types.ts'];
    const texts = scanned.map((path) => [path, readFileSync(join(root, path), 'utf8').replace(/\s*\*\s+/g, ' ').replace(/\s+/g, ' ')] as const);
    const scanRetired = (population: ReadonlyArray<readonly [string, string]>): string[] =>
      population.flatMap(([path, text]) => RETIRED.filter((sentence) => text.includes(sentence)).map((sentence) => `${path} still says "${sentence}"`));
    const standing = scanRetired(texts);
    const plantProbes = RETIRED.flatMap((sentence) => {
      const planted = scanRetired(texts.map(([path, text]) => [path, path === 'docs/AUTHORING.md' ? `${text} ${sentence}` : text] as const));
      return planted.length === standing.length + 1 ? [] : [`"${sentence}" planted into the guide raised ${planted.length - standing.length} fault(s), and one is required`];
    });
    const retiredProbes = [...standing, ...plantProbes];
    say(
      'CUR102_THE_RETIRED_PATH_LENGTHS_SENTENCES_ARE_QUOTED_NOWHERE',
      retiredProbes.length === 0,
      probeDetail(
        retiredProbes.length === 0,
        retiredProbes,
        `${RETIRED.length} retired sentence(s) absent from ${scanned.join(', ')}, and each planted into the guide is named`,
      ),
      'each is an instruction the tool no longer follows — delete a stated array, expect it dropped, trust a ' +
        're-measure to match the editor — and the guide is the only interface an author has to the difference',
    );
  }

  // --- CUR103: the count refusal the guide quotes is the one the compiler raises (#804)
  //
  // The guide quotes the wrong-count refusal twice — in the path table's
  // `lengths` row and in the refusal index — with its counts written as `N` and
  // `M`. Each quote, counts and digits blanked and cut at every `…`, is compared
  // with what this build raises for two entries on a nine-vertex open path, and
  // a plant exchanges the verb the sentence turns on.
  {
    const guide = readFileSync(join(root, 'docs/AUTHORING.md'), 'utf8');
    const track = PATH_RIG.skins.default.attachments.track.track;
    const raised = refusal(
      writeProbeRig({
        ...PATH_RIG,
        skins: {
          ...PATH_RIG.skins,
          default: { attachments: { ...PATH_RIG.skins.default.attachments, track: { track: { ...track, lengths: [90, 180] } } } },
        },
      }),
      pathMotion(PATH_MOVE),
    );
    const shape = (text: string): string => text.replace(/\b[NM]\b/g, '#').replace(/\d+/g, '#').replace(/\s+/g, ' ').trim();
    const pieces = (quote: string): string[] => quote.split('…').map(shape).filter((piece) => piece.length > 0);
    const quotes = [...guide.matchAll(/`("lengths" has N entry\(ies\) where the parser sizes M[^`]*)`/g)].map((m) => m[1]);
    const shaped = raised === null ? '' : shape(raised);
    const missingOf = (quote: string): string[] => pieces(quote).filter((piece) => !shaped.includes(piece));
    const probes = [
      ...(raised === null ? ['two entries on a nine-vertex open path compiled'] : []),
      ...quotes.flatMap((quote) => missingOf(quote).map((piece) => `the guide quotes "${piece}" and the compiler raises "${raised}"`)),
      ...floorProbes([[quotes.length, 2, `${quotes.length} quote(s) of the count refusal in the guide`]], 'so the guide was not read'),
      ...quotes.flatMap((quote) =>
        missingOf(quote.replace('the parser sizes', 'the parser allocates')).length === 1
          ? []
          : [`the verb exchanged in "${quote}" raised ${missingOf(quote.replace('the parser sizes', 'the parser allocates')).length} missing piece(s), and one is required`],
      ),
    ];
    const held = probes.length === 0;
    say(
      'CUR103_THE_COUNT_REFUSAL_THE_GUIDE_QUOTES_FOR_A_STATED_LENGTHS_IS_THE_ONE_THE_COMPILER_RAISES',
      held,
      probeDetail(held, probes, `${quotes.length} quote(s), each a clause of: ${raised}`),
      'the message is the UI: the guide\'s quote is what an author searches for when the build stops, and the ' +
        'row beside it is the remedy. A quote the compiler does not raise is a remedy nobody reaches',
    );
  }

  // --- CUR104: the guide's A07 row quotes the three blank-line sentences A07 prints (#803, #810) ---
  //
  // The sentences are read off the validator, not typed here: a pack gated once
  // with a leading blank line, once with a trailing one, and once with a doubled
  // one between two page blocks, and each detail's `line N: ` stripped. The row
  // is the one an agent holding any of those refusals is sent to, so it must
  // tell the three apart in the words the gate uses. Held both ways: each
  // sentence cut from the row is named.
  {
    const A07 = 'A07_ATLAS_TEXT_SHAPE';
    const pack = packWithFirstPageReplaced((png) => png);
    const saidOf = (atlasText: string): string[] =>
      validate({
        skeletonText: pack.result.skeletonText,
        atlasText,
        atlasDir: pack.dir,
        declaredDurations: pack.result.declaredDurations,
        modelText: threadedModel(pack.result, pack.atlasText),
        rig: pack.result.rig,
        profile: 'spine',
      })
        .failures.filter((f) => f.assertion === A07)
        .map((f) => f.detail.replace(/^line \d+: /, ''));
    const lines = pack.atlasText.replace(/\n$/, '').split('\n');
    const sentences = [
      ...saidOf(`\n${pack.atlasText}`),
      ...saidOf(`${pack.atlasText}\n`),
      // the pack's one page block twice, with two blank lines between them
      ...saidOf([...lines, '', '', ...lines].join('\n') + '\n').filter((said) => said === 'consecutive blank lines'),
    ];
    const guide = readFileSync(join(root, 'docs/AUTHORING.md'), 'utf8');
    const rowOf = (text: string): string => text.split('\n').find((line) => ruleRowOf(line, A07)) ?? '';
    const missingFrom = (row: string): string[] => sentences.filter((said) => !row.includes(said)).map((said) => `the A07 row does not quote "${said}"`);
    const standing = missingFrom(rowOf(guide));
    const plantProbes = sentences.flatMap((said) => {
      const planted = missingFrom(rowOf(guide).split(said).join(''));
      return planted.length === standing.length + 1 ? [] : [`"${said}" cut from the row raised ${planted.length - standing.length} fault(s), and one is required`];
    });
    const probes = [
      ...(sentences.length === 3 ? [] : [`the validator printed ${sentences.length} blank-line sentence(s) over the three forgeries, and three are expected: [${sentences.join('; ')}]`]),
      ...(rowOf(guide) === '' ? ['docs/AUTHORING.md has no A07 row'] : []),
      ...standing,
      ...plantProbes,
    ];
    rmSync(pack.dir, { recursive: true, force: true });
    say(
      'CUR104_THE_GUIDES_A07_ROW_QUOTES_EVERY_BLANK_LINE_SENTENCE_THE_GATE_PRINTS',
      probes.length === 0,
      probeDetail(probes.length === 0, probes, `the A07 row quotes ${sentences.map((said) => `"${said}"`).join(' and ')}, and each cut from it is named`),
      'the three sentences name three different repairs — delete a leading blank, a trailing one, or one of a doubled ' +
        'pair mid-file — and the row ' +
        'is where an agent holding one of them looks up which it has',
    );
  }

  // --- CUR105: every name and verdict GENERATIONS.md quotes is the tree's (#706) ---
  //
  // The page quotes four kinds of thing from the code, and each is read off the
  // page and compared with the code rather than typed here: its export table
  // against what `src/generation.ts` exports (one set, compared whole), its
  // version table against what `spineGeneration` answers for each string, every
  // `GENERATION_*` code against the codes `src/ingest.ts` raises, and every
  // assertion name against the registry. Held both ways: one misspelling planted
  // into a copy of the page per kind, and each raises exactly one fault.
  {
    const page = readFileSync(join(root, 'docs/GENERATIONS.md'), 'utf8');
    const moduleSource = readFileSync(join(root, 'src/generation.ts'), 'utf8');
    const ingestSource = readFileSync(join(root, 'src/ingest.ts'), 'utf8');
    const exported = [...moduleSource.matchAll(/^export (?:type|const|function) (\w+)/gm)].map((m) => m[1]).sort();
    const raisedCodes = new Set([...ingestSource.matchAll(/'(GENERATION_[A-Z_]+)'/g)].map((m) => m[1]));
    const tableAfter = (text: string, header: string): string[] => {
      const lines = text.split('\n');
      const at = lines.indexOf(header);
      if (at < 0) return [];
      const rows: string[] = [];
      for (let k = at + 2; k < lines.length && lines[k].startsWith('|'); k++) rows.push(lines[k]);
      return rows;
    };
    const EXPORT_HEADER = '| export | what it is |';
    const VERSION_HEADER = '| `skeleton.spine` | generation |';
    const faultsOf = (text: string): string[] => {
      const listed = tableAfter(text, EXPORT_HEADER).flatMap((row) => /^\| `(\w+)` \|/.exec(row)?.[1] ?? []).sort();
      const vectors = tableAfter(text, VERSION_HEADER).flatMap((row) => {
        const m = /^\| `([^`]+)` \| `([^`]+)` \|$/.exec(row);
        return m === null ? [] : [[m[1], m[2]] as const];
      });
      const codes = [...new Set([...text.matchAll(/\bGENERATION_[A-Z_]+\b/g)].map((m) => m[0]))];
      const assertions = [...new Set([...text.matchAll(/\bA\d\d_[A-Z0-9_]+\b/g)].map((m) => m[0]))];
      return [
        ...(listed.join(',') === exported.join(',') ? [] : [`the export table lists [${listed.join(', ')}] and src/generation.ts exports [${exported.join(', ')}]`]),
        ...vectors.flatMap(([version, stated]) => {
          const read = String(spineGeneration(version));
          return read === stated ? [] : [`the page reads ${JSON.stringify(version)} as ${stated} and spineGeneration reads it as ${read}`];
        }),
        ...codes.filter((code) => !raisedCodes.has(code)).map((code) => `the page quotes ${code} and src/ingest.ts raises no such code`),
        ...assertions.filter((name) => !ASSERTION_NAMES.includes(name)).map((name) => `the page quotes ${name} and the registry has no such assertion`),
        ...floorProbes(
          [
            [listed.length, 1, `${listed.length} export row(s) read`],
            [vectors.length, 9, `${vectors.length} version row(s) read`],
            [codes.length, 2, `${codes.length} GENERATION_* code(s) quoted`],
            [assertions.length, 1, `${assertions.length} assertion name(s) quoted`],
          ],
          'so the page was not read the way this control reads it',
        ),
      ];
    };
    const standing = faultsOf(page);
    const firstOf = (pattern: RegExp): string => pattern.exec(page)?.[0] ?? '';
    const PLANTS: ReadonlyArray<readonly [string, string, string]> = [
      ['an export name misspelled in the export table', firstOf(/^\| `\w+` \| /m), firstOf(/^\| `\w+` \| /m).replace(/` \| $/, 'S` | ')],
      ['a version read as another generation', firstOf(/^\| `[^`]+` \| `4\.3` \|$/m), firstOf(/^\| `[^`]+` \| `4\.3` \|$/m).replace('`4.3`', '`4.2`')],
      ['a GENERATION_* code misspelled', firstOf(/\bGENERATION_[A-Z_]+\b/), `${firstOf(/\bGENERATION_[A-Z_]+\b/)}S`],
      ['an assertion name misspelled', firstOf(/\bA\d\d_[A-Z0-9_]+\b/), `${firstOf(/\bA\d\d_[A-Z0-9_]+\b/)}S`],
    ];
    const plantProbes = PLANTS.flatMap(([what, from, to]) => {
      if (from === '') return [`${what}: nothing on the page to plant into`];
      const raised = faultsOf(page.replace(from, to)).length - standing.length;
      return raised === 1 ? [] : [`${what} raised ${raised} fault(s), and one is required`];
    });
    const probes = [...standing, ...plantProbes];
    say(
      'CUR105_EVERY_NAME_AND_VERDICT_THE_GENERATIONS_PAGE_QUOTES_IS_THE_TREES',
      probes.length === 0,
      probeDetail(
        probes.length === 0,
        probes,
        `docs/GENERATIONS.md quotes ${exported.length} export(s), ${tableAfter(page, VERSION_HEADER).length} version verdict(s), ` +
          `${[...raisedCodes].length} ingest code(s) and its assertion names as the tree has them, and each of ${PLANTS.length} plants is named`,
      ),
      'the page is the policy an agent reads before it hands rigc a file from another generation; a name it quotes ' +
        'that the code does not carry is a search that finds nothing, and a verdict it states that the reader does ' +
        'not give is a generation handed to the wrong runtime',
    );
  }

  // --- CUR106: the guide's A02 row quotes the sentence A02 prints (#814) ---
  //
  // The sentence is read off the validator, not typed here: the pack's own
  // emit with its last bone given the legacy key, gated, and the bone's name in
  // the detail put back to the row's `…`. The row is the one an agent holding
  // the refusal is sent to, and the sentence is where the generations that
  // spelled the key are stated, so the row must say what the gate says. Held
  // both ways: the sentence cut from the row is named.
  {
    const A02 = 'A02_NO_BONE_TRANSFORM_KEY';
    const pack = packWithFirstPageReplaced((png) => png);
    const skeletonText = editJson(pack.result.skeletonText, (j) => {
      const bones = j.bones as Array<Record<string, unknown>>;
      bones[bones.length - 1][LEGACY_BONE_INHERIT_KEY] = 'noScale';
    });
    const sentences = validate({
      skeletonText,
      atlasText: pack.atlasText,
      atlasDir: pack.dir,
      declaredDurations: pack.result.declaredDurations,
      modelText: threadedModel(pack.result, pack.atlasText),
      rig: pack.result.rig,
      profile: 'spine',
    })
      .failures.filter((f) => f.assertion === A02)
      .map((f) => f.detail.replace(/^bone "[^"]*"/, 'bone "…"'));
    const guide = readFileSync(join(root, 'docs/AUTHORING.md'), 'utf8');
    const rowOf = (text: string): string => text.split('\n').find((line) => ruleRowOf(line, A02)) ?? '';
    const missingFrom = (row: string): string[] => sentences.filter((said) => !row.includes(said)).map((said) => `the A02 row does not quote "${said}"`);
    const standing = missingFrom(rowOf(guide));
    const plantProbes = sentences.flatMap((said) => {
      const planted = missingFrom(rowOf(guide).split(said).join(''));
      return planted.length === standing.length + 1 ? [] : [`"${said}" cut from the row raised ${planted.length - standing.length} fault(s), and one is required`];
    });
    const probes = [
      ...(sentences.length === 1 ? [] : [`the validator printed ${sentences.length} A02 sentence(s) over one forged bone, and one is expected: [${sentences.join('; ')}]`]),
      ...(rowOf(guide) === '' ? ['docs/AUTHORING.md has no A02 row'] : []),
      ...standing,
      ...plantProbes,
    ];
    rmSync(pack.dir, { recursive: true, force: true });
    say(
      'CUR106_THE_GUIDES_A02_ROW_QUOTES_THE_SENTENCE_THE_GATE_PRINTS',
      probes.length === 0,
      probeDetail(probes.length === 0, probes, `the A02 row quotes ${sentences.map((said) => `"${said}"`).join(' and ')}, and the sentence cut from it is named`),
      'the sentence is where the generations that spelled the key are stated; a row that says something else sends ' +
        'the agent holding the refusal to a different claim about which file it has',
    );
  }

  // --- CUR107: the guide's quotes of the deferred-point refusal are the one the compiler raises (#823)
  //
  // The guide quotes the `point` refusal in the refusal index and in §6's table,
  // each cut at `…`. The sentence is read off the compiler — a probe rig whose
  // one marker attachment is a point — and every piece of every quote has to be
  // a clause of it. Held both ways: each quote with one word exchanged is named.
  {
    const guide = readFileSync(join(root, 'docs/AUTHORING.md'), 'utf8');
    const probe = writeProbeRig({
      skins: { default: { block: { block: { image: 'block.png' } }, marker: { marker: { type: 'point' } } } },
    });
    const raised = refusal(probe, STATIC_MOTION);
    rmSync(probe.dir, { recursive: true, force: true });
    const shape = (text: string): string => text.replace(/\s+/g, ' ').trim();
    const shaped = raised === null ? '' : shape(raised);
    const pieces = (quote: string): string[] => quote.split('…').map(shape).filter((piece) => piece.length > 0);
    const missingOf = (quote: string): string[] => pieces(quote).filter((piece) => !shaped.includes(piece));
    const quotes = [...guide.matchAll(/`(this attachment is a "point"[^`]*)`/g)].map((m) => m[1]);
    const exchanged = (quote: string): string => quote.replace('this attachment', 'that attachment');
    const probes = [
      ...(raised === null ? ['a rig spec with a point attachment compiled'] : []),
      ...quotes.flatMap((quote) => missingOf(quote).map((piece) => `the guide quotes "${piece}" and the compiler raises "${raised}"`)),
      ...floorProbes([[quotes.length, 1, `${quotes.length} quote(s) of the point refusal in the guide`]], 'so the guide was not read'),
      ...quotes.flatMap((quote) =>
        missingOf(exchanged(quote)).length === missingOf(quote).length + 1
          ? []
          : [`one word exchanged in "${quote}" raised ${missingOf(exchanged(quote)).length - missingOf(quote).length} missing piece(s), and one is required`],
      ),
    ];
    const held = probes.length === 0;
    say(
      'CUR107_THE_GUIDES_QUOTES_OF_THE_DEFERRED_POINT_REFUSAL_ARE_THE_ONE_THE_COMPILER_RAISES',
      held,
      probeDetail(held, probes, `${quotes.length} quote(s), each a clause of: ${raised}`),
      'the quote is what an author holding the refusal searches the guide for, and the row beside it is where the ' +
        'deferral is explained; a quote the compiler does not raise is an explanation nobody reaches',
    );
  }

  // --- CUR110: every part pointer into the format reference or the survey resolves (#823)
  //
  // The format reference and the dated survey were one page, and a pointer
  // written against the one page names a part by number. After the split a
  // pointer at the reference's name for a part the survey holds is a reader sent
  // to a heading that is not there — the refusal for a deferred point attachment
  // did exactly that. Every `.ts` and `.md` git tracks at the root and directly
  // under `src/`, `docs/`, `bench/` and `tools/` is read, each pointer is resolved
  // against the headings of the page it names (`## Part N`, `### N.M`), and a
  // miss is one fault per part, naming every file that cites it. Held both ways:
  // a cited heading deleted from a copy of the reference, and a pointer at the
  // reference's name for a part only the survey has, each raise exactly one —
  // and that pointer raises one from a staged file and none from an untracked
  // one beside it (#827).
  {
    const PAGES = { SPEC_COVERAGE: 'docs/SPEC_COVERAGE.md', 'SURVEY_2026-08-22': 'docs/SURVEY_2026-08-22.md' } as const;
    type PageName = keyof typeof PAGES;
    const headingsOf = (text: string): Set<string> =>
      new Set(
        text.split('\n').flatMap((line) => {
          const part = /^## Part (\d+)\b/.exec(line);
          if (part) return [part[1]];
          const sub = /^### (\d+)\.(\d+) /.exec(line);
          return sub ? [`${sub[1]}.${sub[2]}`] : [];
        }),
      );
    // The population is what git tracks, not what sits in the directory (#827):
    // a squad's untracked `PR_BODY.md` describing the part it moved is not a
    // pointer a reader of the tree can follow.
    const populationOf = (at: string): string[] =>
      ['.', 'src', 'docs', 'bench', 'tools'].flatMap((dir) => trackedIn(at, dir, (name) => /\.(ts|md)$/.test(name)));
    const population = populationOf(root);
    const normal = (text: string): string =>
      text
        .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
        .replace(/`/g, '')
        .replace(/\s*\*\s+/g, ' ')
        .replace(/\s+/g, ' ');
    const POINTER = /\b(SPEC_COVERAGE|SURVEY_2026-08-22)(?:\.md)? (?:[Pp]arts?|§) ?(\d+)(?:[-.](\d+))?((?: and \d+[-.]\d+)*)/g;
    const citedIn = (texts: ReadonlyArray<readonly [string, string]>): Map<string, Set<string>> => {
      const cited = new Map<string, Set<string>>();
      for (const [path, text] of texts) {
        for (const m of normal(text).matchAll(POINTER)) {
          const keys = [m[3] === undefined ? m[2] : `${m[2]}.${m[3]}`, ...[...m[4].matchAll(/(\d+)[-.](\d+)/g)].map((k) => `${k[1]}.${k[2]}`)];
          for (const key of keys) {
            const id = `${m[1]} ${key}`;
            if (!cited.has(id)) cited.set(id, new Set());
            cited.get(id)?.add(path);
          }
        }
      }
      return cited;
    };
    const faultsOf = (texts: ReadonlyArray<readonly [string, string]>, pages: Record<PageName, string>): string[] => {
      const headings = { SPEC_COVERAGE: headingsOf(pages.SPEC_COVERAGE), 'SURVEY_2026-08-22': headingsOf(pages['SURVEY_2026-08-22']) };
      return [...citedIn(texts)].flatMap(([id, paths]) => {
        const [page, key] = id.split(' ') as [PageName, string];
        return headings[page].has(key)
          ? []
          : [`${page} part ${key.replace('.', '-')} is cited in ${[...paths].sort().join(', ')}, and ${PAGES[page]} has no heading for it`];
      });
    };
    const texts = population.map((path) => [path, readFileSync(join(root, path), 'utf8')] as const);
    const pages = {
      SPEC_COVERAGE: readFileSync(join(root, PAGES.SPEC_COVERAGE), 'utf8'),
      'SURVEY_2026-08-22': existsSync(join(root, PAGES['SURVEY_2026-08-22'])) ? readFileSync(join(root, PAGES['SURVEY_2026-08-22']), 'utf8') : '',
    };
    const cited = citedIn(texts);
    const standing = faultsOf(texts, pages);
    const citedOn = (page: PageName): string[] => [...cited.keys()].filter((id) => id.startsWith(`${page} `)).map((id) => id.split(' ')[1]);
    // Plant one: the first heading the reference is cited for, deleted from a copy of it.
    const firstCited = citedOn('SPEC_COVERAGE').find((key) => headingsOf(pages.SPEC_COVERAGE).has(key));
    const headingLine = (key: string): RegExp => (key.includes('.') ? new RegExp(`^### ${literalPattern(key)} .*$`, 'm') : new RegExp(`^## Part ${key}\\b.*$`, 'm'));
    const cutRaised =
      firstCited === undefined ? null : faultsOf(texts, { ...pages, SPEC_COVERAGE: pages.SPEC_COVERAGE.replace(headingLine(firstCited), '') }).length - standing.length;
    // Plant two: the reference's name on a part only the survey has, appended to the first scanned file.
    const movedOnly = [...headingsOf(pages['SURVEY_2026-08-22'])].find((key) => key.includes('.') && !headingsOf(pages.SPEC_COVERAGE).has(key));
    const misnamedRaised =
      movedOnly === undefined
        ? null
        : faultsOf(
            texts.map(([path, text], k) => [path, k === 0 ? `${text}\nSPEC_COVERAGE part ${movedOnly.replace('.', '-')}\n` : text] as const),
            pages,
          ).length - standing.length;
    // Plants three and four: that pointer written into two files of a throwaway
    // repository, one of them staged and the other not. The staged one raises
    // exactly one fault and the untracked one none — and the untracked file is
    // on disk, where a directory walk would have read it, so the plant that
    // must stay silent is not silent for want of a file.
    const repo = mkdtempSync(join(harnessTemp(), 'rigc-part-pointer-population-'));
    let trackedRaised: number | null = null;
    let untrackedRaised: number | null = null;
    if (movedOnly !== undefined) {
      const pointer = `SPEC_COVERAGE part ${movedOnly.replace('.', '-')}\n`;
      const isolated = ['-c', `core.excludesFile=${join(repo, 'no-such-global-excludes')}`];
      writeFileSync(join(repo, 'tracked.md'), pointer);
      writeFileSync(join(repo, 'untracked.md'), pointer);
      const staged =
        spawnSync('git', [...isolated, 'init', '-q'], { cwd: repo }).status === 0 &&
        spawnSync('git', [...isolated, 'add', '-f', 'tracked.md'], { cwd: repo }).status === 0;
      if (staged && readdirSync(repo).includes('untracked.md')) {
        const planted = populationOf(repo).map((path) => [path, readFileSync(join(repo, path), 'utf8')] as const);
        // A fault lists every citing file, so a file is named by membership of that list, not by a substring of it.
        const citers = (fault: string): string[] => (/ is cited in (.*), and \S+ has no heading for it$/.exec(fault)?.[1] ?? '').split(', ');
        const naming = (path: string): number => faultsOf(planted, pages).filter((fault) => citers(fault).includes(path)).length;
        trackedRaised = naming('tracked.md');
        untrackedRaised = naming('untracked.md');
      }
    }
    rmSync(repo, { recursive: true, force: true });
    const plants: ReadonlyArray<readonly [string, number | null, number]> = [
      [`deleting the heading of cited part ${String(firstCited)} from a copy of ${PAGES.SPEC_COVERAGE}`, cutRaised, 1],
      [`a pointer at ${PAGES.SPEC_COVERAGE} for the survey's part ${String(movedOnly)}`, misnamedRaised, 1],
      ['that pointer in a file git tracks', trackedRaised, 1],
      ['that pointer in a file git does not track, on disk beside it', untrackedRaised, 0],
    ];
    const probes = [
      ...standing,
      ...floorProbes(
        [
          [population.length, 1, `${population.length} file(s) read`],
          [citedOn('SPEC_COVERAGE').length, 1, `${citedOn('SPEC_COVERAGE').length} part(s) of ${PAGES.SPEC_COVERAGE} cited`],
          [citedOn('SURVEY_2026-08-22').length, 1, `${citedOn('SURVEY_2026-08-22').length} part(s) of ${PAGES['SURVEY_2026-08-22']} cited`],
          [headingsOf(pages['SURVEY_2026-08-22']).size, 1, `${headingsOf(pages['SURVEY_2026-08-22']).size} heading(s) read off ${PAGES['SURVEY_2026-08-22']}`],
        ],
        'so the pointers were not read the way this control reads them',
      ),
      ...plants.flatMap(([what, raised, required]) =>
        raised === required ? [] : [`${what} raised ${String(raised)} fault(s), and ${required === 1 ? 'one is' : 'none is'} required`],
      ),
    ];
    const held = probes.length === 0;
    say(
      'CUR110_EVERY_PART_POINTER_INTO_THE_FORMAT_REFERENCE_OR_THE_SURVEY_NAMES_A_HEADING_IT_HAS',
      held,
      probeDetail(
        held,
        probes,
        `${cited.size} cited part(s) across ${population.length} file(s) resolve — ` +
          `${citedOn('SPEC_COVERAGE').sort().join(', ')} on ${PAGES.SPEC_COVERAGE}, ` +
          `${citedOn('SURVEY_2026-08-22').sort().join(', ')} on ${PAGES['SURVEY_2026-08-22']} — and each of ${plants.length} plants is named`,
      ),
      'a refusal and a comment send their reader to a part by number; a number the page it names does not have is ' +
        'a pointer that resolves to nothing, and the reader cannot tell a moved part from a mistyped one',
    );
  }

  // CUR129 — the actual release-example block refuses missing sample assets before the comparison can pack/install.
  {
    const text = readFileSync(join(root, 'RELEASING.md'), 'utf8');
    const blocks = [...text.matchAll(/<!-- release-dependant-example:[^\n]*-->\n *```sh\n([\s\S]*?)\n *```/g)];
    const probes: string[] = blocks.length === 1 ? [] : [`RELEASING.md carries ${blocks.length} release-dependant-example blocks, required one`];
    const cases: string[] = [];
    if (blocks.length === 1) {
      const work = mkdtempSync(join(harnessTemp(), 'rigc-release-example-'));
      const candidate = join(work, 'candidate');
      const dependant = join(work, 'rig-parts');
      const marker = join(candidate, 'comparison.args');
      const inputs = ['examples/scarf/config.json', 'examples/scarf/animations.json', 'examples/scarf/inputs/painting.png', 'examples/scarf/inputs/layers/full', 'examples/scarf/inputs/layers/head', 'examples/scarf/inputs/layers/full/layers.json', 'examples/scarf/inputs/layers/head/layers.json'];
      const expected = ['scripts/dependant_check.ts', '--dependant', '../rig-parts', '--', 'bun', 'cli.ts', 'build', '--config', inputs[0], '--source', inputs[2], '--full', inputs[3], '--head', inputs[4], '--out', '{out}'];
      const source = blocks[0][1].replace(/^ {3}/gm, '');
      // Execute the documented command unchanged; only the executable is a shell function recording its arguments.
      const script = `bun() { printf '%s\\n' "$@" > comparison.args; }\n${source}`;
      const supply = (input: string): void => {
        const path = join(dependant, input);
        if (input.endsWith('/full') || input.endsWith('/head')) {
          mkdirSync(path, { recursive: true });
          writeFileSync(join(path, 'layers.json'), '{}\n');
        }
        else { mkdirSync(dirname(path), { recursive: true }); writeFileSync(path, '{}\n'); }
      };
      try {
        mkdirSync(candidate, { recursive: true });
        for (const input of inputs) supply(input);
        const complete = spawnSync('sh', ['-c', script], { cwd: candidate, encoding: 'utf8' });
        const args = existsSync(marker) ? readFileSync(marker, 'utf8').trimEnd().split('\n') : [];
        if (complete.error !== undefined || complete.status !== 0 || args.join('\n') !== expected.join('\n')) {
          probes.push(`complete scarf example: exit ${String(complete.status)}, comparison arguments ${JSON.stringify(args)}, required ${JSON.stringify(expected)}; ${complete.error?.message ?? complete.stderr}`);
        } else cases.push('all seven paths present: the exact scarf comparison command was reached');
        for (const input of inputs) {
          rmSync(marker, { force: true });
          rmSync(join(dependant, input), { recursive: true, force: true });
          if (input.endsWith('/layers.json') && !existsSync(dirname(join(dependant, input)))) probes.push(`${input} plant removed its parent directory, so it did not test a missing manifest inside an existing wrapper directory`);
          const missing = spawnSync('sh', ['-c', script], { cwd: candidate, encoding: 'utf8' });
          const named = `FAIL  RELEASE_DEPENDANT_INPUT: ../rig-parts/${input} is missing;`;
          if (spawnFailed(missing) || missing.status !== 1 || !missing.stderr.startsWith(named) || existsSync(marker)) {
            probes.push(`${input} missing: exit ${String(missing.status)}, comparison reached ${existsSync(marker)}, stderr ${JSON.stringify(missing.stderr)}; required exit 1 naming that path before the comparison`);
          } else cases.push(`${input} missing: named refusal before comparison`);
          supply(input);
        }
      } finally { rmSync(work, { recursive: true, force: true }); }
    }
    say('CUR129_THE_DOCUMENTED_RELEASE_SAMPLE_REFUSES_EACH_MISSING_INPUT_BEFORE_PACK_OR_INSTALL', probes.length === 0,
      probeDetail(probes.length === 0, probes, `${cases.length} readings of the exact RELEASING block: ${cases.join('; ')}`),
      'issue #1447: an obsolete example command cannot measure a dependant; the public scarf config names animations.json and each wrapper directory requires layers.json, so the documented step must name any missing sample asset before running the comparison');
  }

  // CUR130 — `verify:nova` hands the pool runner its three values and the prepared remote command, or refuses
  // by name before running it; and the remote command gives an upload with no `.git` one that lists it (issue #1474).
  {
    const probes: string[] = [];
    const cases: string[] = [];
    const work = mkdtempSync(join(harnessTemp(), 'rigc-verify-nova-'));
    try {
      const marker = join(work, 'runner.args');
      const runner = join(work, 'nova-run.sh');
      writeFileSync(runner, `#!/bin/sh\nfor a in "$@"; do printf '%s\\n' "$a"; done > '${marker}'\nexit 3\n`);
      chmodSync(runner, 0o755);
      const hand = (args: string[], env: NodeJS.ProcessEnv): { status: number | null; stderr: string; reached: string[] | null } => {
        rmSync(marker, { force: true });
        const r = spawnSync(process.execPath, [join(root, 'scripts', 'verify_nova.ts'), ...args], { cwd: work, encoding: 'utf8', env });
        return { status: r.status, stderr: r.stderr, reached: existsSync(marker) ? readFileSync(marker, 'utf8').trimEnd().split('\n') : null };
      };
      const env = { ...process.env, NOVA_RUN: runner };
      const full = ['--label', '#1474 full selftest', '--owner', 'a squad', '--session', 'a-session-id'];
      const ok = hand(full, env);
      const expected = ['--label', '#1474 full selftest', '--owner', 'a squad', '--session', 'a-session-id', '--', 'bash', '-c', VERIFY_NOVA_REMOTE];
      if (ok.status !== 3 || ok.reached?.join('\n') !== expected.join('\n')) probes.push(`all three given: exit ${String(ok.status)}, the runner was handed ${JSON.stringify(ok.reached)}; required exit 3 (the runner's) and ${JSON.stringify(expected)}`);
      else cases.push("all three given: the runner's exit 3 returned, the three values and the remote command passed through");
      for (const field of ['label', 'owner', 'session']) {
        for (const [what, args] of [
          ['absent', full.filter((_, k) => !(full[k] === `--${field}` || full[k - 1] === `--${field}`))],
          ['"unknown"', full.map((a, k) => (full[k - 1] === `--${field}` ? 'unknown' : a))],
          ['blank', full.map((a, k) => (full[k - 1] === `--${field}` ? ' ' : a))],
        ] as const) {
          const r = hand([...args], env);
          if (r.status !== 2 || r.reached !== null || !r.stderr.startsWith(`verify:nova: --${field} is missing, blank or "unknown"`)) probes.push(`--${field} ${what}: exit ${String(r.status)}, runner reached ${r.reached !== null}, stderr ${JSON.stringify(r.stderr.slice(0, 160))}; required exit 2 naming --${field} before the runner`);
          else cases.push(`--${field} ${what}: refused by name, the runner not started`);
        }
      }
      const nowhere = hand(full, { ...process.env, NOVA_RUN: join(work, 'not-there.sh') });
      if (nowhere.status !== 2 || !nowhere.stderr.includes('NOVA_RUN names') || nowhere.reached !== null) probes.push(`NOVA_RUN naming nothing: exit ${String(nowhere.status)}, stderr ${JSON.stringify(nowhere.stderr.slice(0, 160))}; required exit 2 naming NOVA_RUN`);
      else cases.push('NOVA_RUN naming nothing: refused by name');

      // The remote command, on an upload with no `.git`: `bun` is a stand-in that records its calls and, on
      // `run selftest`, what `git ls-files` lists — the call the cli suite died on.
      const upload = join(work, 'upload');
      const fakeBin = join(work, 'bin');
      mkdirSync(upload, { recursive: true });
      mkdirSync(fakeBin, { recursive: true });
      writeFileSync(join(upload, 'sent.txt'), 'x\n');
      writeFileSync(join(fakeBin, 'bun'), `#!/bin/sh\necho "$*" >> '${join(work, 'bun.calls')}'\nif [ "$2" = selftest ]; then git ls-files > '${join(work, 'listed')}'; exit 5; fi\n`);
      chmodSync(join(fakeBin, 'bun'), 0o755);
      const remote = spawnSync('bash', ['-c', VERIFY_NOVA_REMOTE], { cwd: upload, encoding: 'utf8', env: { ...process.env, PATH: `${fakeBin}${delimiter}${process.env.PATH ?? ''}`, GIT_CONFIG_GLOBAL: '/dev/null' } });
      const calls = existsSync(join(work, 'bun.calls')) ? readFileSync(join(work, 'bun.calls'), 'utf8').trimEnd().split('\n') : [];
      const listed = existsSync(join(work, 'listed')) ? readFileSync(join(work, 'listed'), 'utf8').trimEnd().split('\n') : [];
      if (remote.status !== 5 || calls.join('\n') !== 'run fetch-examples\nrun selftest' || listed.join('\n') !== 'sent.txt') {
        probes.push(`the remote command on an upload with no .git: exit ${String(remote.status)}, bun called ${JSON.stringify(calls)}, git ls-files listed ${JSON.stringify(listed)}; required exit 5 (the selftest's), fetch-examples then selftest, and ["sent.txt"] — ${remote.stderr.trim().slice(0, 200)}`);
      } else cases.push("the remote command on an upload with no .git: git ls-files lists what was sent, fetch-examples runs before selftest, and the selftest's exit 5 is the job's");
    } finally {
      rmSync(work, { recursive: true, force: true });
    }
    say('CUR130_VERIFY_NOVA_PREPARES_THE_UPLOAD_AND_REFUSES_A_JOB_WITH_NO_LABEL_OWNER_OR_SESSION_BEFORE_SENDING_IT', probes.length === 0,
      probeDetail(probes.length === 0, probes, `${cases.length} reading(s): ${cases.join('; ')}`),
      'issue #1474: the pool uploads a tree with no .git and no examples/, so the full selftest is sent through a hand that prepares both; a job the pool would refuse after the upload is refused here before it');
  }

  // Issue #1499: exercise the actual CLI before the upload boundary. Only the
  // network is substituted, by a child preload, so an offline selftest neither
  // downloads a runtime nor depends on today's GitHub availability.
  {
    const probes: string[] = [];
    const cases: string[] = [];
    const work = mkdtempSync(join(harnessTemp(), 'rigc-nova-bun-'));
    const version = '1.2.0'; // Published release; old enough to have no API asset digest.
    const asset = 'bun-linux-x64-baseline.zip';
    const url = `https://github.com/oven-sh/bun/releases/download/bun-v${version}/${asset}`;
    const sha256 = createHash('sha256').update('archive').digest('hex');
    try {
      const marker = join(work, 'runner.json');
      const requests = join(work, 'requests.jsonl');
      const runner = join(work, 'runner');
      const recorder = join(work, 'record.js');
      const preload = join(work, 'network.js');
      // Bun 1.2.0's -e argv contains [eval] and consumes the first forwarded
      // argument; a file has the ordinary argv shape on both supported lines.
      writeFileSync(recorder, `await Bun.write(${JSON.stringify(marker)}, JSON.stringify(process.argv.slice(2))); process.exit(3);\n`);
      writeFileSync(runner, `#!/bin/sh\nexec '${process.execPath}' '${recorder}' "$@"\n`);
      chmodSync(runner, 0o755);
      writeFileSync(preload, `
        import { appendFileSync } from 'node:fs';
        globalThis.fetch = async (url, init) => {
          appendFileSync(${JSON.stringify(requests)}, JSON.stringify([url, init.method]) + '\\n');
          const mode = process.env.NOVA_BUN_CONTROL;
          if (mode === 'offline') throw new Error('network unavailable');
          if (mode === 'unknown' || (mode === 'archive-404' && init.method === 'HEAD')) return new Response('', { status: 404 });
          const row = ${JSON.stringify(`${sha256}  ${asset}\n`)};
          const text = mode === 'missing' ? '' : mode === 'duplicate' ? row + row : mode === 'bad-hash' ? 'bad  ${asset}\\n' : row;
          return new Response(text);
        };
      `);
      const full = ['--label', '#1499 chosen Bun', '--owner', 'a squad', '--session', 'a-session-id'];
      const hand = (extra: string[], mode = 'ok'): { status: number | null; stderr: string; args: string[] | null; requests: string[][] } => {
        rmSync(marker, { force: true }); rmSync(requests, { force: true });
        const r = spawnSync(process.execPath, ['--preload', preload, join(root, 'scripts', 'verify_nova.ts'), ...full, ...extra], {
          cwd: work, encoding: 'utf8', env: { ...process.env, NOVA_RUN: runner, NOVA_BUN_CONTROL: mode },
        });
        return { status: r.status, stderr: r.stderr, args: existsSync(marker) ? JSON.parse(readFileSync(marker, 'utf8')) as string[] : null,
          requests: existsSync(requests) ? readFileSync(requests, 'utf8').trim().split('\n').map((s) => JSON.parse(s) as string[]) : [] };
      };
      const plain = hand([], 'offline');
      if (plain.status !== 3 || plain.requests.length !== 0 || plain.args?.join('\n') !== [...full, '--', 'bash', '-c', VERIFY_NOVA_REMOTE].join('\n')) probes.push(`default changed: ${JSON.stringify(plain)}`);
      else cases.push('default: byte-identical command, no release fetch, runner exit propagated');
      const pinned = verifyNovaRemote({ version, url, sha256 });
      const chosen = hand(['--bun', version]);
      const expectedRequests = [[url.replace(asset, 'SHASUMS256.txt'), 'GET'], [url, 'HEAD']];
      if (chosen.status !== 3 || chosen.args?.join('\n') !== [...full, '--', 'bash', '-c', pinned].join('\n') || JSON.stringify(chosen.requests) !== JSON.stringify(expectedRequests)) probes.push(`chosen version lost before the runner: ${JSON.stringify(chosen)}`);
      else cases.push('exact release manifest and archive checked before runner; pinned URL/digest and version reach job');
      for (const extra of [['--bun'], ['--bun', '--owner'], ['--bun', version, '--bun', version], ...['', ' ', 'latest', 'v1.2.0', '1.2', '01.2.0', '1.2.0-canary', '1.2.0;echo bad', '1.2.0\n'].map((v) => ['--bun', v])]) {
        const r = hand(extra);
        if (r.status !== 2 || r.args !== null || r.requests.length !== 0 || !r.stderr.startsWith('verify:nova: --bun')) probes.push(`malformed ${JSON.stringify(extra)} was not refused before fetch/upload: ${JSON.stringify(r)}`);
        else cases.push(`${JSON.stringify(extra)}: named refusal before fetch/upload`);
      }
      for (const [mode, value, text] of [
        ['unknown', '9999.0.0', 'HTTP 404'], ['missing', version, '0 row(s)'], ['duplicate', version, '2 row(s)'],
        ['bad-hash', version, 'no unambiguous valid checksum'], ['archive-404', version, 'HTTP 404'], ['offline', version, 'network unavailable'],
      ]) {
        const r = hand(['--bun', value], mode);
        if (r.status !== 2 || r.args !== null || !r.stderr.includes(`--bun "${value}"`) || !r.stderr.includes(text) || r.requests.length !== (mode === 'archive-404' ? 2 : 1)) probes.push(`${mode} was not refused by name before upload: ${JSON.stringify(r)}`);
        else cases.push(`${mode}: named refusal before upload`);
      }

      // Run the generated shell too: real SHA-256 reading, transport/extraction
      // stubs, and two Buns. The old PATH's Bun must never run. No git is needed
      // here: the upload already has a .git marker (CUR130 covers its absence).
      const bin = join(work, 'bin'); const tmp = join(work, 'temp'); const calls = join(work, 'calls');
      mkdirSync(bin); mkdirSync(tmp); writeFileSync(join(work, '.git'), 'prepared\n');
      const executable = (name: string, body: string): void => { const file = join(bin, name); writeFileSync(file, `#!/bin/sh\n${body}\n`); chmodSync(file, 0o755); };
      executable('uname', 'if [ "$1" = -s ]; then echo Linux; else echo x86_64; fi');
      executable('curl', 'if [ "$NOVA_BUN_CONTROL" = transport ]; then exit 22; fi; while [ "$1" != -o ]; do shift; done; printf archive > "$2"');
      executable('python3', `if [ "$NOVA_BUN_CONTROL" = extract ]; then exit 1; fi\nmkdir -p "$3/bun-linux-x64-baseline"\ncat > "$3/bun-linux-x64-baseline/bun" <<'BUN'\n#!/bin/sh\nif [ "$1" = --version ]; then if [ "$NOVA_BUN_CONTROL" = wrong ]; then echo 1.4.4; else echo 1.2.0; fi; exit 0; fi\nprintf '%s\\n' "$*" >> '${calls}'\nif [ "$2" = selftest ]; then exit 5; fi\nBUN\nchmod +x "$3/bun-linux-x64-baseline/bun"`);
      executable('bun', `echo fallback >> '${calls}'; exit 99`);
      // Portable checksum reader for the shell control, doing real hashing in
      // the Bun running the suite; Nova uses its installed sha256sum.
      executable('sha256sum', `exec '${process.execPath}' -e 'import {createHash} from "node:crypto"; const line = await Bun.stdin.text(); const [want, file] = line.trim().split(/\\s+/); process.exit(createHash("sha256").update(new Uint8Array(await Bun.file(file).arrayBuffer())).digest("hex") === want ? 0 : 1)'`);
      for (const mode of ['ok', 'corrupt', 'wrong', 'transport', 'extract']) {
        rmSync(calls, { force: true });
        const command = mode === 'corrupt' ? verifyNovaRemote({ version, url, sha256: '0'.repeat(64) }) : pinned;
        const r = spawnSync('bash', ['-c', command], { cwd: work, encoding: 'utf8', env: { ...process.env, PATH: `${bin}${delimiter}${process.env.PATH ?? ''}`, TMPDIR: tmp, NOVA_BUN_CONTROL: mode } });
        const read = existsSync(calls) ? readFileSync(calls, 'utf8') : '';
        const ok = mode === 'ok'
          ? r.status === 5 && r.stdout === 'verify:nova: Bun 1.2.0\n' && read === 'run fetch-examples\nrun selftest\n'
          : r.status === 2 && read === '' && r.stderr.includes('--bun 1.2.0');
        if (!ok || readdirSync(tmp).length !== 0) probes.push(`remote ${mode}: exit ${String(r.status)}, stdout ${JSON.stringify(r.stdout)}, stderr ${JSON.stringify(r.stderr)}, calls ${JSON.stringify(read)}, temporary files ${JSON.stringify(readdirSync(tmp))}`);
        else cases.push(`remote ${mode}: ${mode === 'ok' ? 'first line names selected Bun, both commands use it, selftest exit preserved' : 'refused before selftest'}; private runtime cleaned`);
      }
    } finally { rmSync(work, { recursive: true, force: true }); }
    say('CUR134_VERIFY_NOVA_PINS_BUN_AND_REFUSES_UNFETCHABLE_VERSIONS_BEFORE_UPLOAD', probes.length === 0,
      probeDetail(probes.length === 0, probes, `${cases.length} readings: ${cases.join('; ')}`),
      'issue #1499: a version-shaped string is not evidence of a fetchable release; the actual release checksum and archive must be resolved before the upload, and the downloaded bytes and runtime checked before the full selftest');
  }

  return bad;
}

/** The keywords after which a `/` opens a regex rather than divides. */
const REGEX_OPENING_KEYWORDS = ['return', 'typeof', 'instanceof', 'in', 'of', 'new', 'delete', 'void', 'case', 'do', 'else', 'yield', 'await'];

/** What a `/` may follow and still open a regex rather than be division. */
const BEFORE_REGEX = new RegExp(`[([{,;:!&|?+\\-*/%~^=<>]$|\\b(?:${REGEX_OPENING_KEYWORDS.join('|')})$`);

/**
 * How many characters before a `/` (trailing blanks dropped) `BEFORE_REGEX`
 * has to see to answer as it would over the whole prefix (issue #1121): the
 * longest keyword, plus the one character before it that decides its `\b`.
 * Derived from the keyword list, so a longer keyword widens it.
 *
 * ⚠️ The whole prefix is what the blanker used to copy and trim for EVERY `/`
 * in the file — quadratic in time and in garbage. On this file (6.8 MB) that
 * was 41 s and an 879 MB RSS high-water for one call, called twice per file by
 * `CUR32`, and it set the `currency` suite's peak at +1,466 MB. `CUR116` holds
 * the bounded reading to the whole-prefix one.
 */
const REGEX_LOOK_BEHIND = Math.max(...REGEX_OPENING_KEYWORDS.map((word) => word.length)) + 1;

/**
 * `source` with every comment and every string literal — single-quoted,
 * double-quoted and template — blanked to spaces, leaving newlines alone.
 *
 * Length- and line-preserving on purpose: the scan reports coordinates, and a
 * blanker that shortens the text reports them at the wrong lines. `CUR32`
 * checks that on the live population rather than trusting this sentence.
 *
 * ⚠️ Regex literals are recognised, and they have to be: `/'/` is a regex
 * holding a lone quote, and without the rule below it opens a string that runs
 * to the end of the file — which does not go red, it goes QUIET, taking every
 * site after it out of the scan. The heuristic is the ordinary one — a `/` is a
 * regex when what precedes it cannot end an expression — and `CUR34` plants
 * exactly that shape.
 *
 * 🔸 A template literal is blanked WHOLE, substitutions included, so source
 * written for another file to run is not scanned as if it were this file's.
 * That is a deliberate blind spot with an instrument behind it: the generated
 * fixture in `scripts/install_smoke.ts` is covered by `bun run smoke`'s
 * unusual-path case, which RUNS it from a path with a space in it rather than
 * reading it.
 */
function blankCommentsAndStrings(source: string, lookBehind: number = REGEX_LOOK_BEHIND): string {
  const out = source.split('');
  const blank = (from: number, to: number): void => {
    for (let k = from; k < to && k < out.length; k++) if (out[k] !== '\n') out[k] = ' ';
  };
  // What precedes a `/`, trailing blanks dropped. `Infinity` is the reading
  // this replaced — the whole prefix, copied and trimmed per `/` — kept only so
  // `CUR116` can hold the bounded reading to it.
  const before = (i: number): string => {
    if (lookBehind === Infinity) return source.slice(0, i).replace(/[ \t]+$/, '');
    let k = i;
    while (k > 0 && (source[k - 1] === ' ' || source[k - 1] === '\t')) k--;
    return source.slice(Math.max(0, k - lookBehind), k);
  };
  let i = 0;
  while (i < source.length) {
    const c = source[i];
    if (c === '/' && source[i + 1] === '/') {
      let j = i + 2;
      while (j < source.length && source[j] !== '\n') j++;
      blank(i, j);
      i = j;
    } else if (c === '/' && source[i + 1] === '*') {
      let j = i + 2;
      while (j < source.length && !(source[j] === '*' && source[j + 1] === '/')) j++;
      blank(i, Math.min(j + 2, source.length));
      i = j + 2;
    } else if (c === '/' && BEFORE_REGEX.test(before(i))) {
      let j = i + 1;
      let inClass = false;
      while (j < source.length && source[j] !== '\n' && (inClass || source[j] !== '/')) {
        if (source[j] === '\\') j++;
        else if (source[j] === '[') inClass = true;
        else if (source[j] === ']') inClass = false;
        j++;
      }
      blank(i + 1, j);
      i = j + 1;
    } else if (c === "'" || c === '"' || c === '`') {
      let j = i + 1;
      while (j < source.length && source[j] !== c) {
        if (source[j] === '\\') j++;
        j++;
      }
      blank(i + 1, j);
      i = j + 1;
    } else i++;
  }
  return out.join('');
}

/** A URL built from `import.meta.url`, read directly for its `.pathname`. */
const FILE_URL_PATHNAME_DIRECT = /new\s+URL\s*\([^()]*\bimport\.meta\.url\b[^()]*\)\s*\.pathname/g;
/** The same URL bound to a name first, whose `.pathname` is read further down. */
const FILE_URL_PATHNAME_BOUND = /\b(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*new\s+URL\s*\([^()]*\bimport\.meta\.url\b[^()]*\)/g;

/**
 * Every place in one module that turns a `file:` URL into a string by reading
 * its `.pathname` — the defect of issue #558, in the two forms it can take.
 *
 * ⭐ The criterion is `import.meta.url` and not `new URL`, which is what makes
 * this two-sided by construction rather than by a list of exceptions: a URL
 * built from `import.meta.url` is always a `file:` URL, so its percent-encoded
 * path is never what the caller wants, while `new URL(request.url).pathname` is
 * a URL doing a URL's job and is left alone.
 */
function fileUrlPathSites(path: string, text: string): string[] {
  const code = blankCommentsAndStrings(text);
  const lineAt = (at: number): number => code.slice(0, at).split('\n').length;
  const out: string[] = [];
  for (const hit of code.matchAll(FILE_URL_PATHNAME_DIRECT)) {
    out.push(`${path}:${lineAt(hit.index)} reads \`.pathname\` off a URL built from \`import.meta.url\``);
  }
  for (const bound of code.matchAll(FILE_URL_PATHNAME_BOUND)) {
    const name = bound[1];
    for (const hit of code.matchAll(new RegExp(`\\b${name}\\s*\\.pathname\\b`, 'g'))) {
      out.push(
        `${path}:${lineAt(hit.index)} reads \`${name}.pathname\`, and \`${name}\` is a URL built from ` +
          `\`import.meta.url\` at line ${lineAt(bound.index)}`,
      );
    }
  }
  return out;
}

/**
 * `source` with every brace-matched block whose head matches `opener` removed —
 * how `CUR18` takes a declaration out of a module without taking the module out.
 */
function cutBracedBlocks(source: string, opener: RegExp): string {
  let out = source;
  for (;;) {
    const head = opener.exec(out);
    if (head === null) return out;
    let depth = 0;
    let end = -1;
    for (let i = head.index + head[0].length - 1; i < out.length; i++) {
      if (out[i] === '{') depth++;
      else if (out[i] === '}' && --depth === 0) {
        end = i;
        break;
      }
    }
    // An unbalanced head would loop forever on the same match; stop instead.
    if (end === -1) return out;
    out = out.slice(0, head.index) + out.slice(end + 1);
  }
}

/**
 * The field names declared at depth 0 of `export interface <name>` in `source`,
 * or null when the source has no such interface.
 *
 * ⚠️ It reads the SOURCE rather than the type, because the type is gone by the
 * time anything here runs — which is the whole reason `RIG_KEYS` exists. Comments
 * go first (a `/** b?: number; *\/` inside one is not a field), then a brace
 * walk keeps nested object types out: only a `name:` or `name?:` sitting at the
 * interface's own level is a field of it.
 *
 * An `extends` clause carries the base's fields in, because the key sets are
 * about what a JSON object may hold and the base's fields are part of that.
 */
function interfaceFieldsIn(source: string, name: string): string[] | null {
  const head = new RegExp(`export interface ${name}(?: extends (\\w+))? \\{`).exec(source);
  if (head === null) return null;
  let depth = 0;
  let end = -1;
  for (let i = head.index + head[0].length - 1; i < source.length; i++) {
    if (source[i] === '{') depth++;
    else if (source[i] === '}' && --depth === 0) {
      end = i;
      break;
    }
  }
  if (end === -1) return null;
  const body = source
    .slice(head.index + head[0].length, end)
    .replace(/\/\*[\s\S]*?\*\//g, '')
    .replace(/\/\/[^\n]*/g, '');
  const fields: string[] = [];
  let level = 0;
  for (const raw of body.split('\n')) {
    const line = raw.trim();
    if (level === 0) {
      const field = /^(\w+)\??\s*:/.exec(line);
      if (field !== null) fields.push(field[1]);
    }
    for (const ch of line) {
      if (ch === '{' || ch === '(' || ch === '[') level++;
      if (ch === '}' || ch === ')' || ch === ']') level--;
    }
  }
  const base = head[1] === undefined ? [] : (interfaceFieldsIn(source, head[1]) ?? []);
  return [...base, ...fields];
}

/**
 * Each field of an exported interface with its declared type text, whitespace
 * collapsed — `interfaceFieldsIn`'s reading, carried one step further for the
 * type tables (issue #890). A type spanning lines is read to the `;` that closes
 * it at depth 0, so an inline object type such as `crop: { x: number; … }` comes
 * back whole; `inlineFieldTypes` reads that literal's own fields.
 */
function interfaceFieldTypesIn(source: string, name: string): Array<[string, string]> | null {
  const head = new RegExp(`export interface ${name}(?: extends (\\w+))? \\{`).exec(source);
  if (head === null) return null;
  let depth = 0;
  let end = -1;
  for (let i = head.index + head[0].length - 1; i < source.length; i++) {
    if (source[i] === '{') depth++;
    else if (source[i] === '}' && --depth === 0) {
      end = i;
      break;
    }
  }
  if (end === -1) return null;
  const body = source.slice(head.index + head[0].length, end);
  const base = head[1] === undefined ? [] : (interfaceFieldTypesIn(source, head[1]) ?? []);
  return [...base, ...inlineFieldTypes(body)];
}

/** The `name?: type;` fields of an object type's body, comments removed. */
function inlineFieldTypes(literalBody: string): Array<[string, string]> {
  const body = literalBody.replace(/\/\*[\s\S]*?\*\//g, '').replace(/\/\/[^\n]*/g, '');
  const out: Array<[string, string]> = [];
  let i = 0;
  while (i < body.length) {
    const field = /^\s*(\w+)\??\s*:\s*/.exec(body.slice(i));
    if (field === null) {
      i++;
      continue;
    }
    i += field[0].length;
    const start = i;
    let depth = 0;
    for (; i < body.length; i++) {
      const ch = body[i];
      if ('{([<'.includes(ch)) depth++;
      else if ('})]>'.includes(ch)) depth--;
      else if ((ch === ';' || ch === ',') && depth === 0) break;
    }
    out.push([field[1], body.slice(start, i).trim().replace(/\s+/g, ' ')]);
    i++;
  }
  return out;
}

/**
 * The checked type (`SPEC_VALUE_TYPES`' first twelve) a declared TypeScript type
 * spells, or `null` when it spells none of them — a union of literals, an
 * interface, a mixed union. `aliases` is `export type X = …;` text by name, so
 * `RigAttachmentName` (a `string`) and `EasingHandles` (four numbers) derive
 * through their declarations rather than through a list kept here.
 */
function checkedTypeOf(declared: string, aliases: ReadonlyMap<string, string>): string | null {
  let text = declared;
  for (let pass = 0; pass < 3; pass++) {
    text = text.replace(/\b[A-Z]\w*\b/g, (word) => {
      if (word === 'Array' || word === 'Record') return word;
      const rhs = aliases.get(word);
      return rhs !== undefined && checkedTypeOf(rhs, new Map()) !== null ? rhs : word;
    });
  }
  const number = /^(?:number|\[number(?:, number)*\]|number\[\]|Array<number>)$/;
  const t = text.trim();
  if (t === 'number' || t === 'string' || t === 'boolean') return t;
  if (/^(?:number \| null|null \| number)$/.test(t)) return 'number | null';
  if (/^(?:string \| null|null \| string)$/.test(t)) return 'string | null';
  if (t !== 'number' && number.test(t)) return 'number[]';
  if (/^(?:number\[\]|\[number(?:, number)*\]) \| null$/.test(t)) return 'number[] | null';
  if (t === 'string[]' || t === 'Array<string>') return 'string[]';
  if (/^(?:Array<\[number(?:, number)*\]>|number\[\]\[\])$/.test(t)) return 'number[][]';
  const map = /^Record<string, (.+)>$/.exec(t);
  if (map !== null) {
    const each = checkedTypeOf(map[1], new Map());
    if (each === 'number[]' || each === 'string[]' || each === 'string | null') return `map of ${each}`;
  }
  return null;
}

/** `export type X = …;` declarations of a module, by name. */
function typeAliasesIn(source: string): Map<string, string> {
  const aliases = new Map<string, string>();
  for (const m of source.matchAll(/export type (\w+) =\s*([^;]+);/g)) aliases.set(m[1], m[2].trim().replace(/\s+/g, ' '));
  return aliases;
}

// ---------------------------------------------------------------------------
// the gallery READMEs quote real command output (issue #415)
// ---------------------------------------------------------------------------
//
// ⭐ **Why this suite exists.** The currency gate above holds a doc's claims
// ABOUT the tool to the tool. This is the same class one surface over, and the
// surface is the one this project's audience actually reads: an agent that has
// never seen a rig opens `gallery/<name>/README.md` to learn what a run looks
// like, and a fenced block that no longer matches the tool is a wrong answer
// handed to exactly the reader who cannot check it.
//
// 🚨 It bit twice in one night. [#412](https://github.com/rig-c/core/issues/412)
// added one line and one suffix to what `build` prints for a depth mesh, and
// `gallery/look/README.md` — which quotes that block — went stale the moment it
// landed. Nothing went red. [#407](https://github.com/rig-c/core/issues/407)
// then regenerated the same README from a worktree that predated #412, so it
// landed stale again, and again nothing went red. A block repaired by hand is a
// block that will be stale again.
//
// The gap was visible rather than theoretical because these files are already
// HALF gated: `LS03` reads every gallery README and asserts that every
// *invocation* they ship is a measurement the tool will actually take. The
// commands were derived; the output beside them was not.
//
// **Scope: shape 1 of the three issue #415 names, deliberately.** A fenced block
// that is a transcript of a command the same README states. Left out on purpose,
// so a later reader knows the boundary was chosen and not missed: figures quoted
// in running prose (shape 2), and numbers that are arithmetic ABOUT the example
// rather than output of it (shape 3 — `selftest.ts` still carries one of those
// by hand, the `96 · cos(π/8) = 88.7 > 80` comment on `FAN_RIM_COVERING`).
//
// **How a block and its command are decided to belong together.** By its first
// line naming a record the run prints, and there are two ways a rigc report
// names one. Neither is a list written here — both are collected from the output
// of the runs themselves, so a name rigc stops printing stops being an anchor,
// and the floor below is what makes that loud instead of silent.
//
//  1. **A tag at rigc's own report gutter** — `MESH`, `DEFORM`, `MEMBER`, `PHYS`,
//     `PASS`, `SKIP`, `PROF`.
//  2. **The field a record head names itself with**, for the parts of the report
//     that are a tree rather than a gutter — `explain`'s `animations` and
//     `path constraints` sections, where a record is named `default/head/head.deform`
//     or `t=0.6` or `path constraints` and its detail hangs off it by indent.
//     A **record head** is derived, not described: a line the run prints with at
//     least one line deeper than it hanging off it — an interior node of the
//     report's own tree. Everything up to the first column gap is the anchor; the
//     rest of the line is content and is checked as content. (Issue #422.)
//
// 🚨 **Rule 2 is an addition to rule 1, and it must not become a relaxation of
// it.** The anchor has to be something that does NOT change when the block goes
// stale — the whole defect is that the block's CONTENT drifted. What keeps rule 2
// honest is the interior-node qualifier: a report's LEAF lines are the figures,
// so an anchor on one goes silent exactly when it goes stale, and that is the one
// failure this class cannot afford. ⚠️ Measured on this tree rather than argued:
// the stated runs print 340 indented
// `moved`/`area`/`stretch`/`winding`/`frame`/`skipped` rows (25 flex, 100 look,
// 168 nod, 28 portrait, 19 squash) and rule 2 reaches **none** of them, because
// none has anything hanging off it; over all 59 plain fenced blocks in the
// gallery it reaches 15, 9 of which rule 1 already had, so what it adds is
// exactly the 6 rule 1 cannot reach and nothing else. GT03 plants the loss of
// the anchor on every verified block under whichever rule found it, and requires
// that it fault NOTHING — a block that stops being a block is what the floor is
// for, not what a fault is for.
//
// What that leaves uncovered inside shape 1, stated rather than implied: blocks
// that are output of a different program altogether (`gallery/loop_seam.ts`, an
// example's `make_parts.ts`, a `bun -e` snippet). ⚠️ Two of the six that rule 2
// brought in were STALE when this suite was written — `nod`'s and `portrait`'s
// both still read `bezier[4]` on a hold segment that #376 taught the tool to
// emit as `stepped` — so that class was a real gap and not a theoretical one.
//
// 📌 **A block a run cannot reproduce declares itself**, the way a dated snapshot
// drops out of the currency gate: one line before the fence, opening on
// `DECLARATION_LEAD` below and giving its reason as the rest of that line —
// spelled once, there, for the reason the recipe grammar is. Every block that
// needs it is the same shape — lines lifted out of a run that does not print
// them adjacent, or a run cut short with an ellipsis. ⛔ No count of them here:
// `GT01` prints the declared set with each block's reason, and a tally beside it
// would be a hand-kept copy of a figure the run takes. One stood here and had
// drifted by one before anybody re-read it.
//
// ⭐ **And that line RENDERS**, which is the half of it a reader needs. This
// marker was an HTML comment, so a block the gate knew to be ABRIDGED read on
// the page as a complete transcript: not merely hidden — misleading. The recipe
// below had the same shape of defect the other way round, being the one thing on
// the page its reader would most want and the one thing they could not see.
//
// The reason is required (a marker with nothing after the lead is
// refused, as CUR01 refuses a `dated-record` marker with no date), the declared
// set is reported so it cannot grow quietly, and a declaration on a block that
// DOES reproduce is a fault — otherwise the marker would be a way to switch the
// gate off. A declaration also brings a block IN, for a block neither anchor
// rule can reach. ⚠️ Two declared blocks used to be in on that footing alone,
// because the tag anchor could not reach an `explain` record head; rule 2 reaches
// both of them now, so what still keeps them out of `verified` is the thing their
// declaration actually says — they are abridged, and an abridged block is not a
// contiguous run of anything.
//
// ⚠️ **Cost, measured rather than guessed.** The pool is one subprocess per
// stated command per example: `build` for all seven, `explain` for the six whose
// README names it, `build --profile rig-play` for the seven that mention that
// profile. Twenty runs, 6–18 s of wall clock depending on what else the machine
// is doing. It is NOT taken from `GALLERY_EXAMPLE_IS_GREEN`'s in-process
// `compile()` + `validate()`, which is the cheaper thing sitting right there:
// those lines are printed by `cli.ts`, so reading them out of the library would
// be the report agreeing with the report, and a change to the PRINTER — which is
// exactly what #412 was — would go unseen.
//
// The comparison is fair at all because emit is deterministic (`A18`) and every
// figure in these blocks is a function of the tree.

/** One fenced block of a gallery README, with the declaration that may precede it. */
interface GalleryBlock {
  /** 1-based line number of the opening fence. */
  line: number;
  /** The fence's info string — `json`, `sh`, or empty for a plain block. */
  info: string;
  /** The block's body, verbatim. */
  lines: string[];
  /** The reason the declaration above the fence gives, if there is one. */
  declared: string | null;
  /** The sentence the recipe above the fence states, unparsed, if there is one. */
  recipe: string | null;
}

// ── the two markers, and the one thing that is true of both ────────────────────
//
// 🔒 **A marker is one string: the line a reader reads IS the line this scanner
// parses.** Both of these used to be HTML comments, which render to nothing — so
// the recipe that says how to reproduce a refusal was invisible to the only
// audience that needs it, and, worse, a block declared ABRIDGED read on the page
// as a complete transcript.
//
// ⛔ The fix is NOT a comment for the scanner and a sentence for the reader. Two
// copies of one fact drifting apart is the defect every gate in this section was
// written for — #415, #422 and #429 each found the same shape again — so a marker
// with a machine half and a reader half would be that defect, committed by the
// gate against it. There is exactly one form, an author writes it as prose, and
// this scanner reads the characters they wrote.
//
// ⚠️ A second ACCEPTED spelling is the same defect one step removed, so the
// comment form is gone rather than deprecated and the migration is total. What
// that costs, measured rather than implied: a marker is ONE line however long the
// sentence runs, the longest in this gallery being 198 characters in
// `gallery/look` against the 191 of the comment it replaced. So nothing about
// the source shape has moved; what has moved is that the line renders.

/** Escape a literal so it can stand inside a pattern — the markers are prose, and prose has dots in it. */
function literalPattern(text: string): string {
  return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/**
 * The lead that makes a line a declaration — what a reader sees, and the whole of
 * what the scanner keys on. The reason is the rest of the line, verbatim.
 */
const DECLARATION_LEAD = '**No run reproduces this:**';
/** The escape hatch, and the lookback that finds it: the line above the fence, blank lines allowed. */
const TRANSCRIPT_DECLARATION = new RegExp(`^${literalPattern(DECLARATION_LEAD)}[ \\t]*(.*?)[ \\t]*$`);
const TRANSCRIPT_DECLARATION_LOOKBACK = 3;
/** A declaration shorter than this is not a reason, and a marker without a reason is refused. */
const TRANSCRIPT_REASON_MIN = 12;
/** `  TAG  ` — how every record and every verdict rigc prints begins, at the report gutter. */
const TRANSCRIPT_GUTTER = /^ {2}([A-Z][A-Z\d_]{1,9}) {2}\S/;
/** The same tag on a block's first line, where the gutter has already been taken off. */
const TRANSCRIPT_BLOCK_TAG = /^([A-Z][A-Z\d_]{1,9}) {2}\S/;
/**
 * A **section rule** — the third thing a block can open on, and the one printed
 * structure that carries no data at all: `── summary ──`,
 * `── heavy — candidate animation "heavy", 12 fps ──`.
 *
 * 🔒 The glyph run IS the anchor, deliberately, and not the words between the
 * rules. That is the strongest form of the qualifier rule 2 is held to — *the
 * anchor has to be something that does NOT change when the block goes stale* —
 * because a rule's drawing is the same string whatever the figures beneath it
 * do. ⚠️ Anchoring instead on the rules the runs are observed to PRINT was
 * measured and rejected, and the control is what rejected it: it reaches the
 * same reproducing block and no illustration, which looks tighter, and then the
 * adrift plant shows why it may not ship — under it the anchor IS the content,
 * so a first line edited away stops matching and the block leaves the
 * population silently instead of staying anchored and unreachable. That is the
 * relaxation rule 2's own header forbids, and the shape-only form is the one
 * that satisfies it.
 */
const TRANSCRIPT_SECTION_RULE = /^\s*─{2,}/;

/** How far in a report line sits — the only structure the tree half of a report has. */
function transcriptIndent(line: string): number {
  return line.length - line.trimStart().length;
}

/**
 * The field a report line names its record with: everything up to the first
 * column gap.
 *
 * ⭐ This is the SAME split the gutter tag is, generalised. A `DEFORM  idle  …`
 * line names its record `DEFORM` and the rest is content; an
 * `explain` timeline head names its record `default/head/head.deform` and the
 * `3 key(s)` beside it is content. Taking only the first field is what keeps the
 * anchor off the figures — a key count moving has to be a FAULT, not a silent
 * unanchoring.
 */
function transcriptAnchorField(line: string): string {
  return line.trimStart().split(/ {2,}/)[0];
}

/**
 * Every record head a run prints, by the field it names itself with.
 *
 * 🔒 A record head is an INTERIOR NODE of the report's own tree: a line with at
 * least one line hanging deeper off it. That qualifier is the whole of what keeps
 * this rule from being the loose anchor issue #422 forbids — a report's leaves
 * are its figures, and an anchor on a figure goes quiet on exactly the edit it
 * exists to catch. Derived from the run, never listed: a head rigc stops printing
 * stops being an anchor, and GT01's floor is what makes that loud.
 */
function transcriptRecordHeads(lines: string[]): Set<string> {
  const heads = new Set<string>();
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].replace(/\s+$/, '');
    if (line.trim() === '') continue;
    let next = i + 1;
    while (next < lines.length && lines[next].trim() === '') next++;
    if (next >= lines.length) continue;
    if (transcriptIndent(lines[next]) <= transcriptIndent(line)) continue;
    heads.add(transcriptAnchorField(line));
  }
  return heads;
}

/**
 * Does this block open on a record head, and carry at least one line of that
 * record's detail?
 *
 * The second half is not decoration: a head is a line something hangs off, so a
 * block quoting a head with nothing under it is not quoting a record. Requiring
 * the block to have that shape too is what stops the rule reaching a one-line
 * quotation whose first field happens to collide with a head's.
 */
function transcriptHeadAnchored(body: string[], heads: Set<string>): boolean {
  let next = 1;
  while (next < body.length && body[next].trim() === '') next++;
  if (next >= body.length) return false;
  if (transcriptIndent(body[next]) <= transcriptIndent(body[0])) return false;
  return heads.has(transcriptAnchorField(body[0]));
}

// ── the refusal half (issue #429) ───────────────────────────────────────────
//
// Everything above gates what a README quotes a GREEN run as printing, and
// #429 measured that it reaches no quoted REFUSAL at all — for two independent
// reasons. A refusal block carries no gutter tag and no record head to anchor
// on; and, the harder half, the command that prints it is not a command the
// README states, because reproducing a refusal needs a spec authored to be
// refused and the gallery's specs are authored to be correct. So the whole of
// the surface CLAUDE.md's first doctrine bullet calls the product was outside
// the gate: the wrap refusal's wording was changed in `src/compile.ts` with
// `gallery/look/README.md`'s verbatim quote left stale, and the suite ran green.
//
// 📌 **A refusal block states the edit that makes it**, on the line before the
// fence, in one sentence that cannot say anything else: a `from`, a `to`, the
// example spec they are replaced in, and the command that is then run.
//
// ⭐ **That sentence is written down exactly once** — `RECIPE_GRAMMAR` below —
// and everything else is generated from it: the pattern that parses an author's
// line, the shape a failure message shows them, and every probe GT05 builds. It
// is not spelled out again here, or in a message, or beside the marker, because
// the drift between two copies of one fact is the entire defect this family of
// gates exists to remove. `gallery/README.md` shows one filled in, and GT05
// checks that the one it shows parses and is a recipe a README really carries.
//
// It reads as prose because it renders as prose: the recipe is for the author
// who has to reproduce the refusal, and a recipe they cannot see is a recipe
// they do not have. ⚠️ The literal fields sit in code spans, which is what makes
// one string serve reader and scanner at once — so a field may not contain a
// backtick, and one that does faults by name rather than going quiet.
//
// ⛔ The bound such a declaration needs is a property of the GRAMMAR here, not a
// rule policed after the fact. There is no path in it — the file is
// `gallery/<example>/<rig|motion>.json` and the example has to be one this run
// discovered. There is no shell in it — the edit is a literal replace-all over
// that file's text into a temp directory the gate chooses, and the command is
// `bun cli.ts build` with the gate's own `--out`. A recipe that names anything
// else does not parse, and not parsing is a FAULT rather than a skip, so the
// grammar cannot be widened by writing something it does not accept.
//
// ⚠️ `build` is the only verb and that is deliberate: every refusal this gallery
// quotes is a `build` refusal, and a branch no data reaches is not a control —
// the reason `TC04` was deleted rather than kept. Widen it when a block needs it.
//
// ⭐ **The comparison is UNWRAPPED, and that is measured rather than chosen.**
// rigc prints a refusal on ONE line — the `local: false` message is 739
// characters of it — and every README wraps it to taste, `look` at about 110
// columns and `nod` at about 95. So the claim a block makes is not "these lines,
// in this order", which is what the green half checks; it is "this text, and the
// tool prints it as one line". The block's lines are trimmed and joined with a
// single space and the result must EQUAL a line the run printed. Equality and
// not prefix: an abridged quote is exactly the defect #423 found in
// `gallery/look`, and this rule's first run found two more of it.
//
// ⚠️ One normalisation, and only one: a `CompileError` attributed to an input
// file is printed with that file's `resolve()`d path in front of it, which is a
// different string on every machine and in every temp directory. The gate takes
// off exactly `${patched}: ` — the path of the file the recipe itself just
// wrote, so it is known rather than pattern-matched — and compares the rest
// character for character. A README therefore quotes such a message without a
// path, which is what `gallery/nod`'s wavelength block already did by hand.
//
// 🔒 **The recipe is not opt-in, or it would be the bypass.** The vocabulary a
// refusal announces itself with is DERIVED from these runs the way the gutter
// vocabulary is derived from the green ones: the error head at column 0
// (`rigc compile error`), and the gutter tags a refusal run prints that no green
// run does (which comes out as exactly `FAIL`). A block that opens on either and
// carries neither a recipe nor a declaration is a fault — it quotes a refusal
// and says nothing about how to make one.
//
// What that still leaves uncovered, stated rather than implied, because every
// clause of it was measured while writing this:
//
//  1. **`gallery/flex`'s three refusals are FRAGMENTS** — the body of a message
//     with `rigc compile error:` cut off the front — so nothing announces them;
//     and the edit behind two is not expressible as a literal replace-all (its
//     four `"generator"` lines are byte-identical, so no `from` selects one)
//     while the third needs the ART edited. Neither is a wording away.
//  2. **`docs/` quotes refusals too, and this scan is `gallery/` only.** Swept
//     2026-09-11, after issue #441: FIVE fenced refusal quotes live outside
//     the gallery — `README.md`, `docs/FACE.md`, `docs/INGEST.md`,
//     `docs/RIGGING.md`, and `bench/runs/2026-08-23-rung6-1/LOOP.md` — and
//     every unsealed one of them REPRODUCES.
//
//     ⚠️ This paragraph said EIGHT, then NINE, and said none of them was
//     reachable. Each reading was wrong, and the two corrections were the same
//     mistake twice: **"the spec is not in the tree" was read off the FILE
//     SYSTEM, and the specs were in the DOCUMENTS.** `README.md` spells `buoy`
//     out in its own fences, plates and all; `docs/RIGGING.md`'s Appendix does
//     the same for the rig behind its `A25` quote, down to the
//     `invariants.detached` edit that produces the file the quote names — and
//     that second one was still being called absent on the day the first had
//     already been measured, in a card whose whole subject is a claim nobody
//     re-derives. `docs/INGEST.md`'s `A00` quote reproduces from a command
//     stated in the fence above it, and `docs/FACE.md`'s `A39` quote from a
//     script over `gallery/portrait`, which is how it was caught printing a
//     triangle index the tool does not. The fifth is a landed run record,
//     sealed against editing by the ruling that seals every measure in
//     `bench/runs/` (#181), so the summarise remedy is forbidden there rather
//     than merely unattempted.
//
//     The four that really did come from specs nothing here contains are gone:
//     #441 replaced each with a summary of what the sentence says plus a
//     pointer to the `src/` module that builds it — which is all a transcript
//     nobody can rerun was ever worth. So the remainder is no longer a
//     mixture, and what it wants is a second grammar shape rather than a
//     declaration: a command stated ABOVE the block, which `docs/INGEST.md`
//     already satisfies while `README.md` and `docs/RIGGING.md` satisfy it
//     only as an Appendix a reader has to assemble. Whether the scan should
//     widen to take them is issue #468, which is measuring what that costs.
//  3. **A refusal quoted in running prose is out, and not for a reason this
//     rule could fix.** `docs/AUTHORING.md` quotes the `loop: true` wrap refusal
//     inside italics mid-sentence, with two backticks the author added around
//     `"loop": true`, and quotes another in a failure-map table CELL with
//     elisions and a U+2212 minus. Neither is a fenced block, so `galleryBlocks`
//     never sees either — they are #415's shape 2, left out there because a
//     quotation inside prose has nothing to anchor on. ⚠️ Note what that means
//     for the informal "a quote here may be abridged" convention the guide runs
//     on: it cannot become this file's declaration, because a declaration is an
//     escape FROM a check and shape 2 has no check to escape. Giving the guide
//     the marker first would leave it looking gated and not be — and now that
//     the marker renders, looking gated is what it would actually do.
//
//     🚨 **And shape 2 is where the damage turned out to be**, which is worth
//     stating here because this comment is where somebody deciding to widen a
//     gate will read. Issue #468 swept `docs/` to price exactly that widening
//     and declined it: the block grammar reaches 2 of the 18 green-anchored
//     blocks there, and — the deciding measurement — it catches **none** of the
//     stale ones the same sweep found. Of the defects that day, the two
//     heaviest were in shape 2 and no anchor rule could have reached either: an
//     `area` pair quoted at six sites across two files, reproducing at none,
//     with one of its two comparisons reversed in SIGN rather than merely
//     stale (#471); and a page's opening callout telling the reader to author
//     around a gap `A39` had half closed, on the page whose own §9.2 says so
//     (#472).
//
//     ⇒ The rule that falls out is not "widen the grammar" — the grammar is
//     already at its honest limit, and a quotation inside prose still has
//     nothing to anchor on. It is that **the fenced surface is the gated one,
//     so a figure that matters should be written INSIDE a fence, as a quote of
//     a stated command, or not written as a figure at all.** Both repairs #468
//     landed took the second road: two tallies were DELETED rather than
//     refreshed, because rigc prints no tally line and the number was arithmetic
//     wearing a transcript's clothes.
//
// ⚠️ **Cost, measured rather than guessed**, on the same footing as the green
// half's twenty runs: four recipe runs plus GT05's one deliberately-green probe,
// and they are cheap because they stop early — 0.29 s for a `CompileError`,
// which never reaches validation, and 0.56 s for the one that fails at `A39`
// after the whole gate has run. Each is memoised on the recipe's own text, so
// GT03's seventy-odd rescans add none.
//
// ⛔ And the rule this equality deliberately does NOT relax: markdown the author
// added inside the fence — the emphasis in case 3 is two characters of it — is a
// difference from what the tool printed and faults as one. Normalising markdown
// until things match is the knob that eventually swallows a real drift, so a
// fenced quote carries the tool's characters and nothing else.

/**
 * The recipe sentence, as the pieces it is made of.
 *
 * 🔒 One list, two products: the shape a failure message SHOWS an author and the
 * pattern that PARSES an author's line are generated from it, so the sentence the
 * gate teaches and the sentence the gate accepts cannot be different sentences.
 * That is the same one-string rule the marker itself obeys, one level in — a
 * hand-written copy of the grammar in an error message is a second surface, and
 * the trap's message used to be exactly that.
 *
 * The fields are delimited by code spans, which is what makes the sentence
 * parseable AND readable at once: a reader sees the literal to replace set in
 * code, and the scanner takes everything between the backticks. ⚠️ The bound that
 * buys is that a field cannot itself contain a backtick — a recipe whose `from`
 * does is not a recipe, and faults by name rather than going quiet.
 */
interface RecipeField {
  /** How the rest of this file addresses the field — never its position, so the sentence can be reordered. */
  name: 'from' | 'to' | 'example' | 'spec' | 'command';
  /** The placeholder a message shows in its place. */
  shown: string;
  /** What may stand there. Every field is delimited by code spans, so none may contain a backtick. */
  pattern: string;
}

const RECIPE_GRAMMAR: Array<string | RecipeField> = [
  'replace `',
  { name: 'from', shown: '<from>', pattern: '[^`]*' },
  '` with `',
  { name: 'to', shown: '<to>', pattern: '[^`]*' },
  '` in `gallery/',
  { name: 'example', shown: '<example>', pattern: '[^`/]*' },
  '/',
  { name: 'spec', shown: '<spec>', pattern: '[^`/.]*' },
  '.json`, then run `',
  { name: 'command', shown: 'build [--profile <name>]', pattern: '[^`]*' },
  '`.',
];
const RECIPE_FIELDS = RECIPE_GRAMMAR.filter((part): part is RecipeField => typeof part !== 'string');
/** The sentence, with its fields left as placeholders — what a message shows an author. */
const RECIPE_SHAPE = RECIPE_GRAMMAR.map((part) => (typeof part === 'string' ? part : part.shown)).join('');
/** The same sentence as the pattern that reads its five fields out. */
const RECIPE_BODY = new RegExp(
  `^${RECIPE_GRAMMAR.map((part) => (typeof part === 'string' ? literalPattern(part) : `(${part.pattern})`)).join('')}$`,
);

/**
 * Write a recipe sentence out with its fields filled in — the only way one is
 * spelled anywhere in this file, GT05's nine probes included.
 *
 * ⛔ By NAME rather than by position, and that is the whole of why it exists. A
 * probe that filled the fields in order would keep agreeing with a grammar whose
 * order had changed — `from` and `to` swapped would produce a sentence the parser
 * read back swapped, and every clause would stay green while the sentence a
 * README carries meant the opposite thing.
 */
function recipeSentence(values: Record<RecipeField['name'], string>): string {
  return RECIPE_GRAMMAR.map((part) => (typeof part === 'string' ? part : values[part.name])).join('');
}
/** The lead that makes a line a recipe. The sentence after it is `RECIPE_SHAPE`. */
const RECIPE_LEAD = '**Reproduce it:**';
/** The lead, and the sentence after it: which edit to a gallery spec prints this block. */
const REFUSAL_RECIPE = new RegExp(`^${literalPattern(RECIPE_LEAD)}[ \\t]*(.*?)[ \\t]*$`);
/** How a refusal announces itself at column 0, so the head itself can be collected from a run. */
const REFUSAL_ERROR_HEAD = /^(rigc [a-z]+ error):/;

interface RefusalRecipe {
  example: string;
  spec: 'rig' | 'motion';
  profile: string | null;
  from: string;
  to: string;
  /** The sentence after the marker's lead, for the cache key and for failure detail. */
  text: string;
}

/**
 * Parse a recipe, or say in one sentence why it is not one.
 *
 * Every rejection below is a FAULT at the call site rather than a reason to skip
 * the block: a marker that does not parse is an author who meant to gate
 * something, and treating it as absent is the one outcome that would be worse
 * than not having the marker at all.
 */
function parseRefusalRecipe(text: string, examples: Set<string>): RefusalRecipe | string {
  const fields = RECIPE_BODY.exec(text);
  if (fields === null) {
    return `is not the sentence a recipe is: it reads "${text}", where a recipe reads — ${RECIPE_SHAPE}`;
  }
  // Read out by name, for the reason `recipeSentence` fills them in by name.
  const field = (name: RecipeField['name']): string => fields[RECIPE_FIELDS.findIndex((f) => f.name === name) + 1];
  const [from, to, example, spec] = [field('from'), field('to'), field('example'), field('spec')];
  const words = field('command').split(/\s+/).filter((word) => word !== '');
  const [verb, ...rest] = words;
  if (!examples.has(example ?? '')) {
    return `names example "${example ?? ''}", which is not one of the ${examples.size} this run found (${[...examples].sort().join(', ')})`;
  }
  if (spec !== 'rig' && spec !== 'motion') {
    return `patches "${spec ?? ''}"; a recipe patches a gallery example's own \`rig\` or \`motion\` and nothing else`;
  }
  if (verb !== 'build') {
    return (
      `runs \`${verb ?? ''}\`; \`build\` is the only verb, because every refusal this gallery quotes is a build ` +
      'refusal and a branch no data reaches is not a control'
    );
  }
  let profile: string | null = null;
  if (rest.length === 2 && rest[0] === '--profile') profile = rest[1];
  else if (rest.length !== 0) return `carries [${rest.join(' ')}] after the verb; the only thing that may follow is \`--profile <name>\``;
  if (from === '') return 'has an empty <from>, so it would patch nothing and the run would be the example itself';
  if (to === '') return 'has an empty <to>; a blank field cannot be told from a typo, so it is refused rather than read as a deletion';
  return { example, spec, profile, from, to, text };
}

/** What one recipe printed. */
interface RefusalRun {
  /** Every line, right-trimmed only: the gutter is load-bearing for the tag vocabulary. */
  lines: string[];
  status: number | null;
  /** The file the recipe wrote — the one path prefix a message is allowed to carry. */
  patched: string;
  /** How many times `from` occurred. Zero is a recipe that patched nothing. */
  occurrences: number;
}

/**
 * Materialise the example into a temp directory with one spec patched, and build it.
 *
 * ⚠️ Everything but the patched file is SYMLINKED rather than copied, and that is
 * not a saving: a rig resolves `images` against its own directory, so a patched
 * rig sitting anywhere else would stop finding the art and the refusal under
 * measurement would be replaced by a missing-PNG one. Linking the whole example
 * beside the patch is what keeps the run the example's own.
 */
function runRefusalRecipe(galleryRoot: string, recipe: RefusalRecipe): RefusalRun {
  const src = join(galleryRoot, recipe.example);
  const dir = mkdtempSync(join(harnessTemp(), `rigc-refusal-${recipe.example}-`));
  for (const entry of readdirSync(src)) {
    if (entry === `${recipe.spec}.json`) continue;
    symlinkSync(join(src, entry), join(dir, entry));
  }
  const text = readFileSync(join(src, `${recipe.spec}.json`), 'utf8');
  const patched = join(dir, `${recipe.spec}.json`);
  const occurrences = text.split(recipe.from).length - 1;
  writeFileSync(patched, text.split(recipe.from).join(recipe.to));
  // A recipe whose `from` is not in the file describes the example itself, and
  // the caller faults on it — building it would be a green build nobody reads.
  if (occurrences === 0) return { lines: [], status: null, patched, occurrences };
  const argv = ['build', '--rig', join(dir, 'rig.json'), '--motion', join(dir, 'motion.json'), '--out', join(dir, 'build')];
  if (recipe.profile !== null) argv.push('--profile', recipe.profile);
  const result = runCli(argv);
  return {
    lines: `${result.stdout}${result.stderr}`.split('\n').map((line) => line.replace(/\s+$/, '')),
    status: result.status,
    patched,
    occurrences,
  };
}

/** The block as the one line the tool prints it on: every wrap taken back out. */
function refusalText(body: string[]): string {
  return body
    .map((line) => line.trim())
    .filter((line) => line !== '')
    .join(' ');
}

/**
 * The printed line closest to what the block claims, and whether it IS it.
 *
 * Reporting the divergence point rather than a verdict is the same bar the green
 * half is held to — "line N of the message reads X and the tool prints Y" is
 * actionable and "this block is stale" is not.
 */
function refusalMatch(body: string[], run: RefusalRun): { line: string; shared: number; equal: boolean } | null {
  const want = refusalText(body);
  const prefix = `${run.patched}: `;
  let best: { line: string; shared: number; equal: boolean } | null = null;
  for (const printed of run.lines) {
    const trimmed = printed.trim();
    if (trimmed === '') continue;
    const forms = trimmed.includes(prefix) ? [trimmed, trimmed.split(prefix).join('')] : [trimmed];
    for (const line of forms) {
      if (line === want) return { line, shared: want.length, equal: true };
      let shared = 0;
      while (shared < line.length && shared < want.length && line[shared] === want[shared]) shared++;
      if (best === null || shared > best.shared) best = { line, shared, equal: false };
    }
  }
  return best;
}

/**
 * How a refusal names itself, collected from the refusal runs and never listed.
 *
 * ⭐ The tag half is a DIFFERENCE, not a set: a failing build still prints
 * `MESH`, `PASS` and `SKIP` at the gutter, and anchoring on those would drag
 * every ordinary block into the refusal path. What names a refusal is a tag the
 * green runs never print, which on this tree comes out as exactly `FAIL` — and
 * comes out that way by subtraction rather than by anybody writing it down.
 */
function refusalVocabulary(runs: RefusalRun[], green: Set<string>): { heads: Set<string>; tags: Set<string> } {
  const heads = new Set<string>();
  const tags = new Set<string>();
  for (const run of runs) {
    for (const line of run.lines) {
      const head = REFUSAL_ERROR_HEAD.exec(line.trim());
      if (head !== null) heads.add(head[1]);
      const tag = TRANSCRIPT_GUTTER.exec(line);
      if (tag !== null && !green.has(tag[1])) tags.add(tag[1]);
    }
  }
  return { heads, tags };
}

/** Does this block open on something only a refusal prints? */
function refusalAnchored(body: string[], vocabulary: { heads: Set<string>; tags: Set<string> }): boolean {
  const first = body[0].trim();
  for (const head of vocabulary.heads) if (first.startsWith(`${head}:`)) return true;
  const tag = TRANSCRIPT_BLOCK_TAG.exec(first);
  return tag !== null && vocabulary.tags.has(tag[1]);
}

function galleryBlocks(text: string): GalleryBlock[] {
  const raw = text.split('\n');
  const out: GalleryBlock[] = [];
  let open: GalleryBlock | null = null;
  let fence: string | null = null;
  raw.forEach((line, i) => {
    const marker = /^ {0,3}(```+|~~~+)(.*)$/.exec(line);
    if (marker !== null) {
      if (open === null) {
        fence = marker[1][0];
        let declared: string | null = null;
        let recipe: string | null = null;
        // ⚠️ A marker does not stop the lookback, ordinary prose does — and
        // a marker IS prose now, so the two are told apart by the lead
        // each opens with and by nothing else. The two markers can be stacked,
        // and GT03 stacks them on purpose: a declaration above a block that
        // already carries a recipe, to show that declaring a reproducing block
        // away is still a fault. Breaking on the first marker found would
        // silently take the recipe off instead, and the plant would pass by
        // going quiet.
        for (let k = i - 1; k >= 0 && k >= i - TRANSCRIPT_DECLARATION_LOOKBACK; k--) {
          const found = TRANSCRIPT_DECLARATION.exec(raw[k]);
          if (found !== null) {
            if (declared === null) declared = found[1];
            continue;
          }
          const cooked = REFUSAL_RECIPE.exec(raw[k]);
          if (cooked !== null) {
            if (recipe === null) recipe = cooked[1];
            continue;
          }
          if (raw[k].trim() !== '') break;
        }
        open = { line: i + 1, info: marker[2].trim(), lines: [], declared, recipe };
      } else if (marker[1][0] === fence) {
        out.push(open);
        open = null;
        fence = null;
      }
      return;
    }
    if (open !== null) open.lines.push(line);
  });
  return out;
}

/**
 * Strip the blank edges and the common left margin, and nothing else.
 *
 * READMEs re-indent a quoted report to taste — `gallery/flex` keeps none of the
 * two-space gutter, `gallery/look` keeps all of it — so the margin is not part of
 * the claim. What IS part of it is the relative indentation inside the block,
 * which is how a record's continuation lines hang off it, so only the margin
 * every line shares comes off.
 */
function transcriptBody(lines: string[]): string[] {
  const body = lines.map((line) => line.replace(/\s+$/, ''));
  while (body.length > 0 && body[0] === '') body.shift();
  while (body.length > 0 && body[body.length - 1] === '') body.pop();
  if (body.length === 0) return [];
  const margin = Math.min(...body.filter((line) => line !== '').map((line) => line.length - line.trimStart().length));
  return body.map((line) => (line === '' ? '' : line.slice(margin)));
}

/** One command a README states, and what it printed. */
interface TranscriptRun {
  /** As the README spells it, which is what a failure detail has to name. */
  command: string;
  lines: string[];
  status: number | null;
  /** Trimmed line text → the offsets it occurs at, built on first use by `anchorsIn`. */
  anchors?: Map<string, number[]>;
}

/** Does the README state this command at all? `bun cli.ts explain`, `rigc explain`, or a bare `explain`. */
function readmeStates(readme: string, verb: string): boolean {
  return new RegExp(`(?:bun cli\\.ts|rigc)\\s+${verb}\\b|\`${verb}\``).test(readme);
}

/**
 * Run every command this example's README states, over the example's own spec.
 *
 * The third is what keeps a `--profile rig-play` verdict from being reported
 * stale: under the default profile those rules print `PROF`, not `PASS`, so a
 * README quoting the opt-in run would have nothing to match against.
 */
function transcriptRunsFor(example: string, readme: string, outDir: string): TranscriptRun[] {
  const spec = [
    '--rig',
    `gallery/${example}/rig.json`,
    '--motion',
    `gallery/${example}/motion.json`,
    '--out',
    outDir,
  ];
  const wanted: Array<[string, string[]]> = [['build', ['build', ...spec]]];
  if (readmeStates(readme, 'explain')) wanted.push(['explain', ['explain', ...spec]]);
  if (readme.includes('rig-play')) {
    wanted.push(['build --profile rig-play', ['build', ...spec, '--profile', 'rig-play']]);
  }
  return wanted.map(([command, argv]) => {
    const result = runCli(argv);
    return { command, lines: `${result.stdout}${result.stderr}`.split('\n'), status: result.status };
  });
}

/** What one README's transcript scan found. */
interface TranscriptScan {
  /** Blocks any anchor rule recognised as transcripts, plus the declared and the recipe-carrying ones. */
  found: number;
  /** Of those, how many each rule reached — reported so none of the three can go quiet. */
  byTag: number;
  byHead: number;
  byRecipe: number;
  verified: Array<{ where: string; command: string; lines: number; anchor: 'tag' | 'head' | 'recipe' }>;
  declared: Array<{ where: string; reason: string }>;
  faults: string[];
}

/**
 * The longest run of the block's own lines a stated command actually prints,
 * which is both the match test and the failure message.
 *
 * Reporting the FIRST line that diverges, and what the tool printed there
 * instead, is the whole difference between a detail somebody can act on and
 * "this block is stale" — the same bar every assertion in this repository is
 * held to.
 */
function bestTranscriptWindow(
  body: string[],
  runs: TranscriptRun[],
): { command: string; window: string[]; shared: number } | null {
  let best: { command: string; window: string[]; shared: number } | null = null;
  for (const run of runs) {
    // ⚡ Only the lines whose own trimmed text IS the block's first line can
    // start a match, and that is not a heuristic: a window matches only if every
    // line of it equals the block's after one common margin comes off both, and
    // a margin is spaces, so the two first lines agree once trimmed. Testing
    // every offset instead costs the whole suite about a minute over the plants.
    for (const i of anchorsIn(run, body[0].trimStart())) {
      if (i + body.length > run.lines.length) continue;
      const window = transcriptBody(run.lines.slice(i, i + body.length));
      if (window.length !== body.length) continue;
      let shared = 0;
      while (shared < body.length && window[shared] === body[shared]) shared++;
      if (best === null || shared > best.shared) best = { command: run.command, window, shared };
      if (shared === body.length) return best;
    }
  }
  return best;
}

/** The lines of a run whose trimmed text is `head`, indexed once per run. */
function anchorsIn(run: TranscriptRun, head: string): number[] {
  if (run.anchors === undefined) {
    run.anchors = new Map<string, number[]>();
    run.lines.forEach((line, i) => {
      const key = line.trimStart().replace(/\s+$/, '');
      const at = run.anchors?.get(key);
      if (at === undefined) run.anchors?.set(key, [i]);
      else at.push(i);
    });
  }
  return run.anchors.get(head) ?? [];
}

/**
 * The line the tool prints that comes closest to one a README claims it prints.
 *
 * Only reached when nothing anchors, which is the case where "no command prints
 * this" is true and useless — `gallery/flex`'s roster had gained an
 * `attachments=[…]` column, so every line was wrong from the same character on,
 * and naming that character is the whole difference between a detail somebody
 * can act on and one they have to go bisect by hand.
 */
function nearestPrintedLine(want: string, runs: TranscriptRun[]): { command: string; line: string } | null {
  let best: { command: string; line: string; shared: number } | null = null;
  for (const run of runs) {
    for (const raw of run.lines) {
      const line = raw.trimStart().replace(/\s+$/, '');
      let shared = 0;
      while (shared < line.length && shared < want.length && line[shared] === want[shared]) shared++;
      if (shared > 0 && (best === null || shared > best.shared)) best = { command: run.command, line, shared };
    }
  }
  return best === null ? null : { command: best.command, line: best.line };
}

/** Everything the refusal half of the scan needs, so the plants can reuse one set of runs. */
interface RefusalContext {
  /** The examples a recipe may name — the whole of what its grammar can address. */
  examples: Set<string>;
  /** What a refusal announces itself with, derived from the runs rather than listed. */
  vocabulary: { heads: Set<string>; tags: Set<string> };
  /** Run a recipe. Memoised by the caller: GT03 rescans the same READMEs 70-odd times. */
  run: (recipe: RefusalRecipe) => RefusalRun;
}

function scanGalleryTranscripts(
  where: string,
  readme: string,
  runs: TranscriptRun[],
  vocabulary: Set<string>,
  heads: Set<string>,
  refusal: RefusalContext,
): TranscriptScan {
  const scan: TranscriptScan = { found: 0, byTag: 0, byHead: 0, byRecipe: 0, verified: [], declared: [], faults: [] };
  for (const block of galleryBlocks(readme)) {
    if (block.info !== '') continue; // ```json / ```sh are spec and invocation, not output
    const body = transcriptBody(block.lines);
    if (body.length === 0) continue;
    const tag = TRANSCRIPT_BLOCK_TAG.exec(body[0]);
    // Any anchor is how a block gets picked up WITHOUT anybody saying so, and a
    // declaration is somebody saying so — a block that calls itself a transcript
    // is one, whatever it opens with. Because "declared and it reproduces" is a
    // fault, saying so is not free either.
    const byRecipe = block.recipe !== null;
    const byTag = !byRecipe && tag !== null && vocabulary.has(tag[1]);
    const byHead = !byRecipe && !byTag && transcriptHeadAnchored(body, heads);
    // 🔒 And the trap: a block that opens on something only a refusal prints is
    // IN whether or not anybody said so. That is the clause that stops the
    // recipe being opt-in — having no recipe, such a block has nothing to be
    // compared against, so it has to say why it has none.
    const trapped = !byRecipe && refusalAnchored(body, refusal.vocabulary);
    if (!byTag && !byHead && !byRecipe && !trapped && block.declared === null) continue;
    scan.found++;
    if (byTag) scan.byTag++;
    if (byHead) scan.byHead++;
    if (byRecipe) scan.byRecipe++;
    const at = `${where}:${block.line}`;

    // What the tool says, by whichever route this block claims. Each branch sets
    // the same three things, so the declaration rules below stay one chain.
    let command = '';
    let reproduces = false;
    let mismatch = '';
    if (byRecipe && block.recipe !== null) {
      const parsed = parseRefusalRecipe(block.recipe, refusal.examples);
      if (typeof parsed === 'string') {
        scan.faults.push(`${at}  carries a \`${RECIPE_LEAD}\` line that does not parse — it ${parsed}`);
        continue;
      }
      command = `build gallery/${parsed.example} with ${parsed.spec}.json's "${parsed.from}" -> "${parsed.to}"` +
        (parsed.profile === null ? '' : ` --profile ${parsed.profile}`);
      const run = refusal.run(parsed);
      if (run.occurrences === 0) {
        scan.faults.push(
          `${at}  recipe replaces "${parsed.from}" in gallery/${parsed.example}/${parsed.spec}.json, and that text ` +
            'is not in the file — so the run it names is the example itself, unedited',
        );
        continue;
      }
      if (run.status === 0) {
        scan.faults.push(
          `${at}  recipe's \`${command}\` replaced ${run.occurrences} occurrence(s) and exited 0: it quotes a ` +
            'refusal, and the edit it names no longer refuses anything',
        );
        continue;
      }
      const want = refusalText(body);
      const found = refusalMatch(body, run);
      reproduces = found !== null && found.equal;
      mismatch =
        found === null || found.shared === 0
          ? `${at}  quotes ${want.length} character(s) of refusal that its own recipe's run does not print, from the ` +
            `first character: "${want.slice(0, 100)}"`
          : `${at}  agrees with its recipe's run for ${found.shared} of ${want.length} character(s), and then the ` +
            `README reads "${want.slice(found.shared, found.shared + 70)}" where the tool prints ` +
            `"${found.line.slice(found.shared, found.shared + 70)}"`;
    } else if (trapped) {
      command = 'no recipe';
      mismatch =
        `${at}  opens on something only a refusal prints ("${body[0].trim().slice(0, 70)}") and says nothing ` +
        `about how to make one: put \`${RECIPE_LEAD} ${RECIPE_SHAPE}\` on the line above the fence, or ` +
        `\`${DECLARATION_LEAD} <why>\` if no edit to a gallery spec produces it`;
    } else {
      const best = bestTranscriptWindow(body, runs);
      reproduces = best !== null && best.shared === body.length;
      command = best?.command ?? '';
      if (best === null || best.shared === 0) {
        const near = nearestPrintedLine(body[0].trimStart(), runs);
        mismatch =
          `${at}  quotes ${body.length} line(s) of ` +
          `${byTag && tag !== null ? `\`${tag[1]}\`` : byHead ? `\`${transcriptAnchorField(body[0])}\`` : 'tool'} ` +
          `output whose first line no command this README states prints: "${body[0].trim()}"` +
          (near === null ? '' : `; the closest \`${near.command}\` prints is "${near.line}"`);
      } else if (!reproduces) {
        mismatch =
          `${at}  line ${best.shared + 1} of ${body.length} reads "${body[best.shared].trim()}" and ` +
          `\`${best.command}\` prints "${best.window[best.shared].trim()}"`;
      }
    }

    if (block.declared !== null) {
      if (block.declared.length < TRANSCRIPT_REASON_MIN) {
        scan.faults.push(
          `${at}  declares itself a transcript no run reproduces and gives no reason for it ` +
            `("${block.declared}"): a marker is an as-of annotation, so it has to say as of what`,
        );
      } else if (reproduces) {
        scan.faults.push(
          `${at}  is declared unreproducible ("${block.declared}") and \`${command}\` prints it verbatim — ` +
            'a declaration is the escape for a block the tool cannot print, not a way to stop checking one it can',
        );
      } else {
        scan.declared.push({ where: at, reason: block.declared });
      }
    } else if (reproduces) {
      scan.verified.push({
        where: at,
        command,
        lines: body.length,
        anchor: byRecipe ? 'recipe' : byTag ? 'tag' : 'head',
      });
    } else {
      scan.faults.push(mismatch);
    }
  }
  return scan;
}

/**
 * The three ways a quoted transcript goes stale, planted on EVERY block this
 * suite verifies rather than on one chosen by hand (issue #415's red-first bar).
 *
 * ⭐ Structural, no literal: the figure to bump is found by walking for the last
 * digit run, the line to drop is an interior one, and the suffix is a token
 * nothing prints. That is the same rule the fixture mutants obey — reintroducing
 * a measured number here is how a suite stops being runnable when the numbers
 * move. Each returns `null` where it does not apply, and a block only one line
 * long has no interior to drop.
 */
const TRANSCRIPT_PLANTS: Array<{ name: string; plant: (lines: string[]) => string[] | null }> = [
  {
    name: 'a figure the tool prints, changed by one',
    plant: (lines) => {
      for (let i = lines.length - 1; i >= 0; i--) {
        const digits = [...lines[i].matchAll(/\d+/g)];
        if (digits.length === 0) continue;
        const last = digits[digits.length - 1];
        const bumped = String(Number(last[0]) + 1);
        const next = [...lines];
        next[i] = `${lines[i].slice(0, last.index)}${bumped}${lines[i].slice(last.index + last[0].length)}`;
        return next;
      }
      return null;
    },
  },
  {
    name: 'a line the tool prints, dropped',
    plant: (lines) => (lines.length < 3 ? null : [...lines.slice(0, 1), ...lines.slice(2)]),
  },
  {
    name: 'a suffix the tool does not print, appended',
    plant: (lines) => [...lines.slice(0, -1), `${lines[lines.length - 1]} and a bit more`],
  },
];

/**
 * Take the block's ANCHOR off its first line — whichever of the two rules found
 * it — and nothing else.
 *
 * ⛔ This plant is the one that has to fault NOTHING. A block that stops being
 * recognisable does not go red, it goes quiet, and GT01's floor is the only thing
 * that sees it. The first two rules anchor on the first field of the first line,
 * so one edit serves both: flip the case of its first letter. `DEFORM` becomes
 * `dEFORM`, which no run prints at the gutter; `t=0.6` becomes `T=0.6`, which no
 * run prints as a record head. Structural, no literal — and it deliberately
 * leaves the rest of the line alone, so what is being demonstrated is the loss of
 * the ANCHOR rather than a content edit that would fault for the ordinary reason.
 *
 * 🚨 **A section rule needs its own edit, and finding that out is the whole of
 * what the third rule cost.** Its anchor is the glyph run and not a letter, so
 * the case flip lands on the WORD between the rules — `── summary ──` becomes
 * `── Summary ──`, which is still a section rule, still anchored, and the plant
 * reports a block that would not go quiet. That the existing control caught it
 * rather than passing over it is the argument for having written the control at
 * all: breaking the leading glyph is what takes the anchor off here.
 *
 * Returns `null` for a first field with no letter in it, which the caller counts
 * rather than skips: a plant that cannot be made is not a plant that passed.
 */
function transcriptWithoutItsAnchor(lines: string[]): string[] | null {
  const first = lines.findIndex((line) => line.trim() !== '');
  if (first < 0) return null;
  const line = lines[first];
  const margin = transcriptIndent(line);
  if (TRANSCRIPT_SECTION_RULE.test(line)) {
    const next = [...lines];
    next[first] = `${line.slice(0, margin)}-${line.slice(margin + 1)}`;
    return next;
  }
  const at = transcriptAnchorField(line).search(/[A-Za-z]/);
  if (at < 0) return null;
  const letter = line[margin + at];
  const flipped = letter === letter.toLowerCase() ? letter.toUpperCase() : letter.toLowerCase();
  const next = [...lines];
  next[first] = `${line.slice(0, margin + at)}${flipped}${line.slice(margin + at + 1)}`;
  return next;
}

/**
 * The report tags `gallery/README.md`'s own prose names, and how many places it
 * names them in.
 *
 * ⭐ By paragraph rather than by line, because the sentence wraps and the list
 * wraps with it. The phrase it keys on is the one the sentence exists to define,
 * so a rewrite that drops it takes the count to zero — which GT04 reads as a
 * fault, not as agreement. That is the whole point of returning the count.
 */
function reportTagsNamedIn(text: string): { paragraphs: number; tags: string[] } {
  const paragraphs = text.split(/\n[ \t]*\n/).filter((block) => /report tag/i.test(block));
  const tags = new Set<string>();
  for (const block of paragraphs) for (const m of block.matchAll(/`([A-Z][A-Z\d_]{1,9})`/g)) tags.add(m[1]);
  return { paragraphs: paragraphs.length, tags: [...tags].sort() };
}

/**
 * The line a report closes on — `  ..    <N> assertions: …` (issue #568).
 *
 * A LOCATOR and not a claim: what it picks out of the run is read for its words,
 * never for its figures, so the vocabulary GT64 scans with follows whatever the
 * summary comes to say.
 */
const REPORT_SUMMARY_LINE = /^ {2}\.{2} {2,}\d+ assertions: /;

/**
 * The two count words the gallery pages used that no `build` run prints.
 *
 * ⛔ Written down because they cannot be derived, and that is the point rather
 * than the exception: a figure spelled in a word the tool never produces is a
 * figure with nothing to compare it against, which is how all ten of #609's
 * sentences went stale while the run one line away printed the truth. The rest
 * of the vocabulary comes off `REPORT_SUMMARY_LINE`, so it follows the tool.
 */
const PROSE_ONLY_COUNT_WORDS = ['ran', 'excluded'];

/** One page's figures stated in prose, and the same pairings that stand inside a fence. */
interface ProseFigureScan {
  /** `page:line  …` for every figure outside a fenced block — the fault list, and the message. */
  outside: string[];
  /** The same pairings inside a fence. The floor reads this: a pattern that stopped matching zeroes both. */
  inside: number;
  /** Lines outside a fence that were looked at, so a scan that read nothing cannot report clean. */
  lines: number;
}

function scanProseFigures(pages: Array<[string, string]>, figure: RegExp): ProseFigureScan {
  const scan: ProseFigureScan = { outside: [], inside: 0, lines: 0 };
  for (const [where, text] of pages) {
    let fence: string | null = null;
    text.split('\n').forEach((line, i) => {
      const marker = /^ {0,3}(```+|~~~+)/.exec(line);
      if (marker !== null) {
        if (fence === null) fence = marker[1][0];
        else if (marker[1][0] === fence) fence = null;
        return;
      }
      const hits = [...line.matchAll(figure)].map((m) => m[0]);
      if (fence !== null) {
        scan.inside += hits.length;
        return;
      }
      scan.lines++;
      if (hits.length === 0) return;
      scan.outside.push(
        `${where}:${i + 1}  states ${hits.map((hit) => `"${hit}"`).join(', ')} in prose, where nothing re-runs the ` +
          `command: ${line.trim().slice(0, 90)}`,
      );
    });
  }
  return scan;
}

/** Splice an edited block body back into the README text it came from. */
function plantIntoReadme(readme: string, block: GalleryBlock, edited: string[]): string {
  const raw = readme.split('\n');
  return [...raw.slice(0, block.line), ...edited, ...raw.slice(block.line + block.lines.length)].join('\n');
}

/** The bounds GT05 formerly kept outside its failure list; each falling term now names its reading (issue #1447). */
function refusalRecipeBoundFaults(read: { recipeBlocks: number; notDragged: number; elisionProbes: number; namedHeads: number; namedTags: number }): string[] {
  return [
    ...floorProbes([
      [read.recipeBlocks, 4, `${read.recipeBlocks} verified refusal recipe block(s)`],
      [read.notDragged, 14, `${read.notDragged} stated-command block(s) kept outside the refusal path`],
      [read.elisionProbes, 4, `${read.elisionProbes} path-elision probe(s)`],
      [read.namedHeads, 1, `${read.namedHeads} error head(s) named in gallery/README.md`],
      [read.namedTags, 1, `${read.namedTags} refusal verdict(s) named in gallery/README.md`],
    ], 'so the refusal recipe control did not measure its required population'),
    ...(read.elisionProbes === read.recipeBlocks ? [] : [`${read.elisionProbes} path-elision probe(s) for ${read.recipeBlocks} verified refusal recipe block(s); required one per block`]),
  ];
}

function runGalleryTranscriptSuite(): number {
  console.log('\n── what a gallery README QUOTES the tool as printing (issue #415) ──');
  let bad = 0;
  const say = (name: string, ok: boolean, detail: string, why: string): void => {
    bad += reportCase(name, ok, detail, why);
  };

  const root = import.meta.dir;
  const galleryRoot = join(root, 'gallery');
  if (!existsSync(galleryRoot)) {
    console.log('  INFO  no gallery/ directory, so no quoted transcript was checked in this run.');
    return bad;
  }
  const examples = readdirSync(galleryRoot)
    .filter(
      (name) =>
        existsSync(join(galleryRoot, name, 'README.md')) &&
        existsSync(join(galleryRoot, name, 'rig.json')) &&
        existsSync(join(galleryRoot, name, 'motion.json')),
    )
    .sort();

  const readmes = new Map<string, string>();
  const pools = new Map<string, TranscriptRun[]>();
  const unstated: string[] = [];
  const broken: string[] = [];
  for (const example of examples) {
    const readme = readFileSync(join(galleryRoot, example, 'README.md'), 'utf8');
    readmes.set(example, readme);
    // Shape 1 is "a command the same README states", so the pool is derived from
    // the README rather than assumed: an example whose README never hands a
    // stranger a `build` line is not one this gate has a command for.
    if (!new RegExp(`bun cli\\.ts build[^\\n]*--rig gallery/${example}/rig\\.json`).test(readme)) {
      unstated.push(example);
      continue;
    }
    const runs = transcriptRunsFor(example, readme, mkdtempSync(join(harnessTemp(), `rigc-transcript-${example}-`)));
    for (const run of runs) {
      if (run.status !== 0 || run.lines.length < 20) {
        broken.push(`gallery/${example}: \`${run.command}\` exited ${run.status} with ${run.lines.length} line(s)`);
      }
    }
    pools.set(example, runs);
  }

  const vocabulary = new Set<string>();
  for (const runs of pools.values()) {
    for (const run of runs) {
      for (const line of run.lines) {
        const tag = TRANSCRIPT_GUTTER.exec(line);
        if (tag !== null) vocabulary.add(tag[1]);
      }
    }
  }

  // 🔒 The gutter vocabulary is one report-wide alphabet, so it is pooled across
  // every example. Record heads are NOT: `default/head/head.deform` is a name out
  // of one rig, and letting one example's names anchor another example's blocks
  // would be a rule looser than the thing it is derived from. Per example.
  const headsBy = new Map<string, Set<string>>();
  for (const [example, runs] of pools) {
    const heads = new Set<string>();
    for (const run of runs) for (const head of transcriptRecordHeads(run.lines)) heads.add(head);
    headsBy.set(example, heads);
  }

  // --- the refusal runs (issue #429) ----------------------------------------
  //
  // One subprocess per DISTINCT recipe, memoised on the recipe's own text: GT03
  // rescans each README once per plant, and re-running a build for every one of
  // those would be seventy builds instead of the four the gallery asks for.
  // ⚠️ The cache is the reason a recipe's identity is its text — two blocks that
  // state the same edit are the same run, and two that differ by one character
  // are not.
  const recipeNames = new Set(examples);
  const recipeRuns = new Map<string, RefusalRun>();
  const runRecipe = (recipe: RefusalRecipe): RefusalRun => {
    const cached = recipeRuns.get(recipe.text);
    if (cached !== undefined) return cached;
    const fresh = runRefusalRecipe(galleryRoot, recipe);
    recipeRuns.set(recipe.text, fresh);
    return fresh;
  };
  // The vocabulary has to exist before the first scan, because the trap that
  // makes the recipe non-optional reads it — so every recipe in the tree is
  // parsed and run here, ahead of any block being looked at. A recipe that does
  // not parse is not skipped: the scan below faults on it by name, and this pass
  // simply has nothing to run for it.
  for (const readme of readmes.values()) {
    for (const block of galleryBlocks(readme)) {
      if (block.info !== '' || block.recipe === null) continue;
      const parsed = parseRefusalRecipe(block.recipe, recipeNames);
      if (typeof parsed !== 'string') runRecipe(parsed);
    }
  }
  const refusalVocab = refusalVocabulary([...recipeRuns.values()], vocabulary);
  const refusal: RefusalContext = { examples: recipeNames, vocabulary: refusalVocab, run: runRecipe };

  const scans = new Map<string, TranscriptScan>();
  for (const [example, runs] of pools) {
    scans.set(
      example,
      scanGalleryTranscripts(
        `gallery/${example}/README.md`,
        readmes.get(example) ?? '',
        runs,
        vocabulary,
        headsBy.get(example) ?? new Set<string>(),
        refusal,
      ),
    );
  }
  const found = [...scans.values()].reduce((n, scan) => n + scan.found, 0);
  const byTag = [...scans.values()].reduce((n, scan) => n + scan.byTag, 0);
  const byHead = [...scans.values()].reduce((n, scan) => n + scan.byHead, 0);
  const byRecipe = [...scans.values()].reduce((n, scan) => n + scan.byRecipe, 0);
  const verified = [...scans.values()].flatMap((scan) => scan.verified);
  const declared = [...scans.values()].flatMap((scan) => scan.declared);
  const faults = [...scans.values()].flatMap((scan) => scan.faults);
  const covered = [...scans].filter(([, scan]) => scan.verified.length > 0).map(([example]) => example);
  const runCount = [...pools.values()].reduce((n, runs) => n + runs.length, 0);

  // --- GT01: the derivation floor, asserted before anything about content ----
  //
  // 🔒 CUR01's argument, and it is the one that matters most here. Every step
  // above can come back empty — a gallery with no example, a README that stops
  // stating its own build line, a command that starts failing, a gutter tag the
  // tool renames, a record head it restructures — and each of those makes GT02
  // below pass while reading nothing. A scanner that silently matched no block
  // would report a clean tree, which is the one failure a gate like this cannot
  // afford. ⭐ The anchor rules are floored SEPARATELY, because a floor on their
  // sum would let one of them go to zero while the others grew — and issue #429
  // added a third population and two more derived sets to keep that way up.
  // ⚠️ `headCount >= 100` below is a SMOKE floor, chosen against an observed 281
  // and not a measured bound. Nobody has established how far it could honestly
  // fall on a smaller gallery; it is there to catch the head derivation returning
  // nothing at all, which is the failure that would make rule 2 silently stop
  // anchoring. Do not read it as a budget.
  const headCount = [...headsBy.values()].reduce((n, heads) => n + heads.size, 0);
  // 🚨 Every floor is a PROBE and not a conjunct — `DQ01`'s clause, applied to
  // its untouched twin (issue #496). Sixteen terms stood in this verdict and
  // the detail's ternary read TWO of them, `unstated` and `broken`.
  //
  // ⭐ What that cost is worth stating precisely, because it is not what `GT03`
  // cost and the two get filed together: the paragraph this used to print on a
  // floor failure is not a false sentence. It interpolates every floored
  // quantity, so a reader of that FAIL got all thirteen VALUES — and not one
  // BOUND, so which of them fell was the one thing the line did not carry. A
  // trace with no bound, rather than a clean sweep reported over a broken one.
  // The repair is the bound, printed on the row whose floor is the one that
  // went, and nothing else about the line changes.
  //
  // 🔸 One line would have done it for a control with ONE floor: `RD02` binds
  // `over ${rows.length} of 12 row(s)` in front of both its branches and its
  // reader is served. That idiom does not scale to thirteen — every green run
  // would carry thirteen bounds nobody reads, and the FAIL would still make the
  // reader compare thirteen pairs by eye to find the one that moved.
  //
  // ⛔ Nothing here is a new assertion or a relaxed one: the rows below are the
  // same sixteen terms, with the same thresholds, in one list the detail reads.
  const derivation = [
    ...unstated.map(
      (example) =>
        `gallery/${example}/README.md no longer states a \`bun cli.ts build --rig gallery/${example}/rig.json\` ` +
        'line, so this gate has no command to hold its blocks to',
    ),
    ...broken.map((one) => `a command a README states did not run: ${one}`),
    ...(pools.size === examples.length
      ? []
      : [
          `${pools.size} pool(s) of runs came back over ${examples.length} example(s), so an example was read and ` +
            'then went missing between the two',
        ]),
    ...floorProbes(
      [
        [examples.length, 5, `${examples.length} gallery example(s) were read`],
        [runCount, 14, `${runCount} run(s) of the commands their READMEs state supplied the vocabulary`],
        [vocabulary.size, 5, `${vocabulary.size} gutter tag(s) came out of those runs`],
        [headCount, 100, `${headCount} record head(s) came out of them`],
        [found, 25, `${found} quoted transcript(s) were anchored`],
        [byTag, 14, `${byTag} of them by a gutter tag`],
        [byHead, 6, `${byHead} of them by a record head`],
        [byRecipe, 4, `${byRecipe} of them by a refusal recipe`],
        [recipeRuns.size, 4, `${recipeRuns.size} distinct refusal recipe(s) ran`],
        [refusalVocab.heads.size, 1, `${refusalVocab.heads.size} name(s) at column 0 came out of those refusal runs`],
        [
          refusalVocab.tags.size,
          1,
          `${refusalVocab.tags.size} gutter tag(s) are left after subtracting the green vocabulary from them`,
        ],
        [verified.length, 18, `${verified.length} block(s) reproduced verbatim`],
        [covered.length, 6, `${covered.length} example(s) hold at least one block that reproduced`],
      ],
      'so one END of this derivation came back thinner than it has ever been, and the scan below would be reading ' +
        'less than it used to while still reporting a clean tree',
    ),
  ];
  const held = derivation.length === 0;
  say(
    'GT01_THE_TRANSCRIPT_SCAN_READ_THE_GALLERY_THE_TOOL_AND_THE_BLOCKS',
    held,
    probeDetail(
      held,
      derivation,
      `${examples.length} example(s), ${runCount} stated command run(s), gutter vocabulary ` +
        `{${[...vocabulary].sort().join(' ')}} and ${headCount} record head(s) the runs print; ` +
        `${recipeRuns.size} refusal recipe run(s), which name themselves ` +
        `{${[...refusalVocab.heads].sort().join(' ')}} at column 0 and ` +
        `{${[...refusalVocab.tags].sort().join(' ')}} at the gutter; ` +
        `${found} quoted transcript(s) found — ${byTag} by a gutter tag, ${byHead} by a record head, ` +
        `${byRecipe} by a refusal recipe — ` +
        `${verified.length} reproduced verbatim across ${covered.length} example(s) (${covered.join(', ')}), ` +
        `${declared.length} declared unreproducible ` +
        `(${declared.map((d) => `${d.where} — ${d.reason}`).join('; ') || 'none'})`,
      (count) => `${count} check(s) over this derivation did not hold:`,
    ),
    'every end of this can come back empty: one anchor is a tag the tool prints, one is a record head it prints ' +
      'and one is an edit to a gallery spec, so a renamed tag, a restructured section or a spec that stops ' +
      'refusing takes every block anchored on it out of the scan at once, and the pool is the commands a README ' +
      'states, so a rewritten quickstart takes the whole example out. The refusal vocabulary is derived from the ' +
      'recipe runs the same way, and it is floored on its two halves separately because the tag half is a ' +
      'SUBTRACTION from the green one — if a green run started printing `FAIL` the subtraction would empty and ' +
      'the trap would stop trapping. The floors are one per rule, never one on their sum — and since issue #496 ' +
      'each one is a ROW in the list this detail prints rather than a conjunct of the verdict, because the ' +
      'paragraph above carries every floored VALUE and not one of the bounds, so the run that breached one ' +
      'printed thirteen numbers and no way to tell which of them had stopped clearing its floor',
  );

  // --- GT02: the blocks themselves ------------------------------------------
  say(
    'GT02_EVERY_QUOTED_TRANSCRIPT_IS_A_RUN_OF_THE_COMMAND_ITS_README_STATES',
    faults.length === 0,
    faults.length === 0
      ? `${verified.filter((v) => v.anchor !== 'recipe').length} block(s) — ` +
        `${verified.filter((v) => v.anchor !== 'recipe').reduce((n, v) => n + v.lines, 0)} line(s) — each a ` +
        'contiguous run of the output of the command it sits beside (' +
        `${[...new Set(verified.filter((v) => v.anchor !== 'recipe').map((v) => `\`${v.command}\``))].join(', ')}); ` +
        `${verified.filter((v) => v.anchor === 'recipe').length} refusal block(s) — ` +
        `${verified.filter((v) => v.anchor === 'recipe').reduce((n, v) => n + v.lines, 0)} wrapped line(s) — each ` +
        'unwrapped to exactly one line its own recipe\'s run prints (' +
        `${verified.filter((v) => v.anchor === 'recipe').map((v) => v.where.replace('gallery/', '')).join(', ')}); ` +
        `and ${declared.length} declared block(s) that none of those runs prints, as declared`
      : `${faults.length} quoted transcript(s) the tool no longer prints:\n          ${faults.join('\n          ')}`,
    'the positive half is load-bearing: a check that only reported failures would pass a tool that had stopped ' +
      'printing anything at all, so the line count and the commands are named. #412 added one line and one ' +
      'suffix to a depth-mesh report and #407 regenerated the same README from a worktree that predated it — ' +
      'twice stale in one night, twice green. #429 added the refusal half and its first run found three more: a ' +
      'FAIL verdict whose triangle indices had drifted, a message abridged at an ellipsis, and one carrying a ' +
      "machine's own temp path",
  );

  // --- GT03: the scanner against the ways a transcript goes stale -----------
  //
  // Red-first, on every block GT02 verifies rather than on one chosen by hand,
  // and two-sided: the planted spelling must fault and the tree's own must not
  // (GT02 is that half). The last plant is the one that motivates GT01 — take
  // the ANCHOR off a block's first line and the block does not fault, it
  // silently stops being a block at all. ⭐ Since #422 that plant runs over both
  // anchor rules with one edit, because both anchor on the first line's first
  // field: it flips the case of that field's first letter, which un-tags a
  // gutter record and un-names a record head alike.
  const misses: string[] = [];
  let planted = 0;
  let silenced = 0;
  let unplantable = 0;
  let unrecipe = 0;
  for (const [example, runs] of pools) {
    const readme = readmes.get(example) ?? '';
    const heads = headsBy.get(example) ?? new Set<string>();
    const verifiedHere = new Map(
      (scans.get(example)?.verified ?? []).map((v) => [v.where, v.anchor] as const),
    );
    const rescan = (text: string): TranscriptScan =>
      scanGalleryTranscripts(`gallery/${example}/README.md`, text, runs, vocabulary, heads, refusal);
    // ⚠️ Did THIS BLOCK fault — not "did anything fault" (issue #491). A fault
    // standing anywhere else in the same README satisfies a bare
    // `faults.length === 0` whatever the plant did, so a clause written that
    // way stops testing its plant the moment the example goes stale, which is
    // the one run it exists for. Measured with every plant in this loop
    // replaced by a no-op and one block the runs do not print appended to each
    // README: the absolute form printed PASS over 94 plants that faulted
    // nothing, and this form names all 94.
    //
    // 🔒 Attribution rather than the subtraction issue #486 used four lines
    // down, and the reason is a measurement rather than a preference: three of
    // these four plants MOVE LINES — the interior-line plant takes one out of
    // the block, and both declaration markers put one in above the fence — so
    // a fault standing lower in the file comes back with a different line
    // number in it and a string subtraction reads it as newly raised. Every
    // fault this scanner emits opens with the block's own name and two spaces,
    // which is what makes the stronger claim available at all.
    const faultedAt = (text: string, at: number): boolean =>
      raisedBy(rescan(text).faults, { at: `gallery/${example}/README.md:${at}  ` }).length > 0;
    for (const block of galleryBlocks(readme)) {
      const anchor = verifiedHere.get(`gallery/${example}/README.md:${block.line}`);
      if (anchor === undefined) continue;
      for (const { name, plant } of TRANSCRIPT_PLANTS) {
        const edited = plant(block.lines);
        if (edited === null) continue;
        planted++;
        // The plant replaces the block's body, so the fence it is named by has
        // not moved.
        if (!faultedAt(plantIntoReadme(readme, block, edited), block.line)) {
          misses.push(`gallery/${example}/README.md:${block.line}: ${name} — not faulted`);
        }
      }
      // The declaration is not a way to switch the gate off. ⚠️ Both markers go
      // in ABOVE the fence, so the block answers to one line further down in
      // the rescan — computed for the reason the declaration-removal plant in
      // the docs suite computes its own: reading the old name back would find
      // nothing and report a miss it could not explain.
      const declaredOnly = plantIntoReadme(readme, block, block.lines);
      const declaredLines = declaredOnly.split('\n');
      declaredLines.splice(block.line - 1, 0, `${DECLARATION_LEAD} lifted out of a run that does not print it`);
      planted++;
      if (!faultedAt(declaredLines.join('\n'), block.line + 1)) {
        misses.push(`gallery/${example}/README.md:${block.line}: declared while still reproducing — not faulted`);
      }
      // A marker with nothing after the colon is not a declaration.
      const emptyLines = declaredOnly.split('\n');
      emptyLines.splice(block.line - 1, 0, DECLARATION_LEAD);
      planted++;
      if (!faultedAt(emptyLines.join('\n'), block.line + 1)) {
        misses.push(`gallery/${example}/README.md:${block.line}: declared with no reason — not faulted`);
      }

      // 🚨 The last plant differs by anchor rule, and the difference is the whole
      // reason issue #429 exists. Take the anchor off a TAG- or HEAD-anchored
      // block and it goes quiet — no fault, one fewer block, only GT01's floor
      // between that and a clean tree. Take the RECIPE off a refusal block and it
      // must NOT go quiet: the trap reads it as a refusal quote with nothing
      // behind it and faults. That is the clause that keeps the recipe from being
      // an opt-in, and it is planted on every refusal block rather than argued.
      if (anchor === 'recipe') {
        const withoutRecipe = readme
          .split('\n')
          .filter((line, i) => !(i < block.line - 1 && i >= block.line - 1 - TRANSCRIPT_DECLARATION_LOOKBACK && REFUSAL_RECIPE.test(line)))
          .join('\n');
        planted++;
        // Taking the recipe off deletes whole lines above the fence, so the
        // block moves UP by however many came off — counted rather than assumed
        // at one, because the lookback window can hold more than one.
        const lifted = readme.split('\n').length - withoutRecipe.split('\n').length;
        if (withoutRecipe === readme) {
          unrecipe++;
        } else if (!faultedAt(withoutRecipe, block.line - lifted)) {
          misses.push(`gallery/${example}/README.md:${block.line}: its recipe removed — not faulted by the trap`);
        }
        continue;
      }
      // And the silent one: no anchor, no candidate, no fault — only the floor.
      const unanchored = transcriptWithoutItsAnchor(block.lines);
      if (unanchored === null) {
        unplantable++;
        continue;
      }
      const after = rescan(plantIntoReadme(readme, block, unanchored));
      const scan = scans.get(example);
      // ⚠️ Against this README's unplanted faults, not against zero — issue
      // #486, the third of four sites that had the same one line. "Quiet" is a
      // claim about what THIS EDIT raises; a block elsewhere in the same README
      // that had already gone stale is not this plant's doing, and the two are
      // the same number only while the example is green. This rescan is scoped
      // to one README rather than to the tree, so the standing fault has to be
      // in the same file — which five clauses in this very loop can put there.
      // Measured on a doubly-planted run — a copy of `look`'s `MESH head` block
      // appended to its own README one interior line short, leaving one standing
      // fault, and then this plant on top of it: the absolute form counted all
      // 14 of `look`'s unanchored plants as noisy when every one had gone quiet,
      // and this form counts none.
      const raisedByPlant = after.faults.filter((fault) => !(scan?.faults ?? []).includes(fault));
      if (scan === undefined || after.found !== scan.found - 1 || raisedByPlant.length !== 0) silenced++;
    }
  }

  // ⭐ `unplantable` is the one clause above that this gallery cannot make fire,
  // so it gets a mutant rather than standing as a line that is always true.
  //
  // It counts a verified block whose anchor field has no letter to flip — the
  // negative plant would then be a silent no-op, and a plant that does nothing is
  // a control that checks nothing. Measured: all 281 record heads the runs print
  // today name themselves with a field that has a letter in it, so no README in
  // this tree can reach the branch. That is exactly the shape `TC04` was DELETED
  // for — a control that passed the mutant it existed to catch — and the
  // difference here is that the branch is reachable by data the report could
  // plausibly grow (a record named by a number, beside the `t=0.6` it already
  // prints), not merely by an edit to this file. So it is exercised on a
  // synthetic report, through the same functions the real loop calls: a run that
  // prints one record named `12.5`, and a README quoting it.
  //
  // Two-sided, because a probe that only showed `null` would also be satisfied by
  // a helper that returned `null` for everything: the same block with a letter in
  // its anchor field has to come back plantable.
  const synthetic = (name: string): { body: string[]; scan: TranscriptScan } => {
    const body = [`  ${name}  a record this report names without a letter`, '        one line of detail under it'];
    const runs: TranscriptRun[] = [{ command: 'a synthetic run', lines: ['', ...body, ''], status: 0 }];
    return {
      body,
      // No gutter vocabulary at all, so only rule 2 can anchor this and a pass
      // cannot be the tag rule quietly standing in for it.
      scan: scanGalleryTranscripts(
        'synthetic',
        ['```', ...body, '```'].join('\n'),
        runs,
        new Set<string>(),
        transcriptRecordHeads(runs[0].lines),
        refusal,
      ),
    };
  };
  const letterless = synthetic('12.5');
  const lettered = synthetic('v12.5');
  const built = (probe: { scan: TranscriptScan }): boolean =>
    probe.scan.verified.length === 1 && probe.scan.byHead === 1 && probe.scan.faults.length === 0;
  const counterProbes = [
    ...(built(letterless) && built(lettered)
      ? []
      : ['the synthetic probes did not build a verified head-anchored block, so they say nothing about the counter']),
    ...(transcriptWithoutItsAnchor(letterless.body) === null
      ? []
      : ['a verified block whose anchor field has no letter was still plantable, so `unplantable` is a clause that cannot fire']),
    ...(transcriptWithoutItsAnchor(lettered.body) !== null
      ? []
      : ['the same block with a letter in its anchor field was NOT plantable, so the counter would swallow every block']),
  ];

  // 🚨 Every floor is a PROBE and not a conjunct — `DQ01`'s clause, applied
  // backwards to the control that predates it (issue #493). Four of the seven
  // terms of the old verdict were read by the detail's ternary and three were
  // not: `planted >= 78`, `silenced === 0` and the population floor lived in
  // the boolean alone, so a run failing on any of those three printed the
  // sentence saying every plant behaved. ⭐ Note where the old FAIL branch had
  // a clause for `silenced` and it still could not print: the parenthetical
  // existed, and the ternary that selects that branch did not read the counter,
  // so the one run it was written for never reached it. Measured on #486's
  // doubly-planted run, where which conjunct had failed had to be DERIVED from
  // the clean sentence's own figures rather than read off the line.
  //
  // ⛔ Nothing here is a new assertion or a relaxed one: the rows below are the
  // same seven terms, with the same thresholds, in a list the detail reads.
  const probes = [
    ...misses,
    ...counterProbes,
    ...(silenced === 0
      ? []
      : [
          `${silenced} of the unanchored plant(s) did not drop out cleanly — the block stayed in the scan, or ` +
            'the plant raised a fault its own README was not already carrying',
        ]),
    ...(unplantable === 0 ? [] : [`${unplantable} verified block(s) had no anchor letter to take off`]),
    ...(unrecipe === 0 ? [] : [`${unrecipe} refusal block(s) had no recipe line the plant could find`]),
    ...(planted >= 78
      ? []
      : [
          `only ${planted} edit(s) were planted over ${verified.length} verified block(s), where 78 is the floor, ` +
            'so a plant stopped being APPLIED rather than stopped being caught',
        ]),
    ...(verified.length > 0 ? [] : ['not one block is verified, which is not a population to plant on']),
  ];

  say(
    'GT03_THE_SCANNER_FAULTS_EVERY_WAY_A_QUOTED_TRANSCRIPT_GOES_STALE',
    probes.length === 0,
    probes.length === 0
      ? `${planted} planted edit(s) over the ${verified.length} verified block(s) — a figure bumped, an interior ` +
        'line dropped, a suffix appended, a reproducing block declared away, and a declaration with no reason — ' +
        'each faulted; and taking the anchor off a first line — the gutter tag on ' +
        `${verified.filter((v) => v.anchor === 'tag').length} of them, the record head's own name on ` +
        `${verified.filter((v) => v.anchor === 'head').length} — faulted NOTHING on those ` +
        `${verified.filter((v) => v.anchor !== 'recipe').length}, dropping each silently out of the scan, which is ` +
        "what GT01's floors are for; while taking the RECIPE off each of the " +
        `${verified.filter((v) => v.anchor === 'recipe').length} refusal block(s) faulted every time, which is the ` +
        'opposite behaviour and the reason the recipe is not an opt-in; and the guard that says every one of them ' +
        'actually RECEIVED that plant is itself shown to fire, on a synthetic record this gallery cannot produce — ' +
        'one named `12.5`, with no letter in it to take off'
      : `${planted} edit(s) were planted and ${probes.length} check(s) over them did not hold:\n          ` +
        probes.join('\n          '),
    'a scanner is a vocabulary of shapes and a shape that stops matching goes silent, not red. #412 was a line ' +
      'and a suffix; a figure moving is the same defect a third way, and the declaration has to be refused on a ' +
      'block that reproduces or it becomes the bypass. #422 added a second anchor rule and this is what holds it ' +
      'to the same bar: the new rule has to go quiet in exactly the way the old one does, never louder and never ' +
      'more forgiving. #429 added a third that must do the opposite — a refusal quote whose recipe is gone is ' +
      'still recognisably a refusal quote, so the trap has to catch it rather than let it drop. ⚠️ Every floor ' +
      'here is a row in one list rather than a conjunct of the verdict, for the reason issue #493 names: the ' +
      'clean sentence below says taking the anchor off faulted NOTHING, and while `silenced` sat in the ' +
      "boolean alone that was the sentence a run failing on `silenced` printed — the detail lying on precisely " +
      'the run it exists for',
  );

  // --- GT04: the vocabulary the gallery index NAMES, against the derived one --
  //
  // 🔒 `gallery/README.md` documents this convention, and documenting it means
  // writing the tag list down by hand while the scanner COLLECTS it from the
  // runs. That is this issue's own defect one turn later, in a file this suite
  // reads: the day `cli.ts` prints a new tag at the gutter the code learns it
  // and the paragraph does not. So the prose is derived too.
  //
  // The locator is a paragraph rather than a line, because the sentence wraps —
  // and it reports how many paragraphs it matched, because a locator that
  // silently matched none would compare an empty set against an empty set and
  // call the tree clean. Both directions are probed below: a tag the runs print
  // that the prose omits, a tag the prose names that no run prints, and the
  // reworded sentence that takes the locator to zero.
  {
    const index = existsSync(join(galleryRoot, 'README.md'))
      ? readFileSync(join(galleryRoot, 'README.md'), 'utf8')
      : '';
    const named = reportTagsNamedIn(index);
    const derived = [...vocabulary].sort();
    const disagree = (prose: string[], tags: string[]): string[] => [
      ...tags
        .filter((tag) => !prose.includes(tag))
        .map((tag) => `the runs print \`${tag}\` at the gutter and gallery/README.md does not name it`),
      ...prose
        .filter((tag) => !tags.includes(tag))
        .map((tag) => `gallery/README.md names \`${tag}\` as a report tag and no run prints one`),
    ];
    const faults = [
      ...(named.paragraphs === 1
        ? []
        : [`${named.paragraphs} paragraph(s) of gallery/README.md define a "report tag"; the locator needs exactly one`]),
      ...(named.tags.length >= 5 ? [] : [`the locator read ${named.tags.length} tag name(s) out of that paragraph`]),
      ...disagree(named.tags, derived),
    ];
    // A name nothing in the tree carries, so neither probe can pass by accident.
    const INVENTED = 'NOSUCHTAG';
    // ⚠️ Each probe asks whether the INJECTED name was faulted, not whether
    // anything was — issue #491, the same shape as the plant clauses two cases
    // up and a spelling neither of that sweep's rules reached, because the list
    // here is neither called `faults` nor produced by a rescan. A prose/runs
    // disagreement standing in the tree satisfies `length > 0` whatever the
    // injection did, so the red-first half of this case switches itself off on
    // exactly the run the case goes red. Measured with one invented tag added
    // to the prose side and the injected name replaced by one both sides
    // already carry: the absolute form left both probes silent, and this form
    // names both.
    const probes = [
      ...(disagree(named.tags, [...derived, INVENTED]).some((fault) => fault.includes(INVENTED))
        ? []
        : ['a tag the runs print and the prose omits was not faulted']),
      ...(disagree([...named.tags, INVENTED], derived).some((fault) => fault.includes(INVENTED))
        ? []
        : ['a tag the prose names and no run prints was not faulted']),
      ...(reportTagsNamedIn(index.replace(/report tag/gi, 'report label')).paragraphs === 0
        ? []
        : ['the locator still found its paragraph after the phrase it keys on was reworded away']),
    ];
    say(
      'GT04_THE_REPORT_TAGS_GALLERY_README_NAMES_ARE_THE_ONES_THE_RUNS_PRINT',
      faults.length === 0 && probes.length === 0 && derived.length > 0,
      faults.length === 0 && probes.length === 0
        ? `gallery/README.md's one "report tag" paragraph names ${named.tags.length} tag(s) — ` +
          `${named.tags.map((tag) => `\`${tag}\``).join(', ')} — and that is exactly the gutter vocabulary the ` +
          `${runCount} stated run(s) print; red-first both ways, plus the reworded sentence that takes the ` +
          'locator to zero paragraphs'
        : [...faults, ...probes].join('\n          '),
      'the paragraph that explains this gate would otherwise be the next thing it fails to cover: the scanner ' +
        'collects the vocabulary and the prose spells it out, so a new report tag teaches the code and leaves ' +
        'the documentation wrong. That is #360 exactly, one surface further in',
    );
  }

  // --- GT05: the refusal recipe's own bounds (issue #429) --------------------
  //
  // GT02 says the refusal blocks reproduce and GT03 says every way of breaking
  // one faults. This is the other half of #429's bar: that the new path did not
  // reach anything it has no business reaching, and that each of the ways the
  // grammar refuses a recipe actually fires. Four probes, every one of them
  // two-sided, because a refusal-only check passes a parser that refuses
  // everything — which is the shape `ERT05` was written for.
  {
    const recipeBlocks = verified.filter((v) => v.anchor === 'recipe');
    const statedAt = new Set(verified.filter((v) => v.anchor !== 'recipe').map((v) => v.where));

    // ① Not dragged in. No block a STATED command already reproduces may look
    // like a refusal to the trap, and none may carry a recipe: the refusal path
    // is a second population, not a wider net over the first one.
    const dragged: string[] = [];
    let notDragged = 0;
    for (const [example, readme] of readmes) {
      for (const block of galleryBlocks(readme)) {
        if (block.info !== '') continue;
        const body = transcriptBody(block.lines);
        if (body.length === 0) continue;
        const at = `gallery/${example}/README.md:${block.line}`;
        if (!statedAt.has(at)) continue;
        notDragged++;
        if (refusalAnchored(body, refusalVocab)) dragged.push(`${at} reads as a refusal to the trap`);
        if (block.recipe !== null) dragged.push(`${at} reproduces from a stated command and carries a recipe too`);
      }
    }

    // ② The grammar. One well-formed recipe has to parse — otherwise every
    // rejection below is satisfied by a parser that rejects everything — and
    // each way of stepping outside the bound has to come back as a sentence.
    const anExample = [...recipeNames].sort()[0] ?? '';
    // Every probe below is the grammar filled in, never a sentence typed out
    // beside it: a change to the sentence has to reach these or they would go on
    // testing a spelling no README carries.
    const aRecipe = (over: Partial<Record<RecipeField['name'], string>>): string =>
      recipeSentence({ from: 'a', to: 'b', example: anExample, spec: 'rig', command: 'build', ...over });
    const wellFormed = parseRefusalRecipe(aRecipe({ command: 'build --profile rig-play' }), recipeNames);
    const malformed: Array<[string, string]> = [
      ['a line that is not the sentence at all', `${anExample} rig build | a | b`],
      ['an example this run never found', aRecipe({ example: 'no-such-example' })],
      ['a file that is neither spec', aRecipe({ spec: 'atlas' })],
      ['a verb that is not build', aRecipe({ command: 'explain' })],
      ['an argument the bound does not allow', aRecipe({ command: 'build --out /tmp/anywhere' })],
      ['nothing to replace', aRecipe({ from: '' })],
      ['nothing to replace it with', aRecipe({ to: '' })],
    ];
    const grammar = [
      ...(typeof wellFormed === 'string'
        ? [`a well-formed recipe did not parse: it ${wellFormed}`]
        : []),
      ...malformed
        .filter(([, text]) => typeof parseRefusalRecipe(text, recipeNames) !== 'string')
        .map(([why]) => `a recipe naming ${why} parsed anyway`),
    ];

    // ③ The two ways a recipe can be well-formed and still say nothing. Both go
    // through the whole scan rather than through the parser, because both are
    // properties of the RUN: an edit that is not in the file, and an edit that
    // leaves the build green. The second costs one green build and there is no
    // way to see the clause fire without paying it.
    const probeScan = (recipeText: string): TranscriptScan =>
      scanGalleryTranscripts(
        'probe',
        `${RECIPE_LEAD} ${recipeText}\n\`\`\`\nrigc compile error: a line no run prints\n\`\`\``,
        [],
        vocabulary,
        new Set<string>(),
        refusal,
      );
    const absent = probeScan(aRecipe({ from: 'a string no rig spec in this gallery contains', to: 'x' }));
    const green = probeScan(aRecipe({ from: '"name"', to: '"name"' }));
    const runs = [
      ...(absent.faults.some((f) => f.includes('is not in the file'))
        ? []
        : ['a recipe whose `from` is not in the spec was not faulted']),
      ...(green.faults.some((f) => f.includes('exited 0'))
        ? []
        : ['a recipe whose edit leaves the build green was not faulted']),
    ];

    // ④ The one normalisation is not a wildcard. The gate takes the patched
    // file's own path off a message; it must not take any other path off, or the
    // comparison would quietly stop reading the part of a message that names
    // what was wrong.
    const foreign: string[] = [];
    let elisionProbes = 0;
    for (const [example, readme] of readmes) {
      for (const block of galleryBlocks(readme)) {
        if (block.info !== '' || block.recipe === null) continue;
        const at = `gallery/${example}/README.md:${block.line}`;
        if (!recipeBlocks.some((v) => v.where === at)) continue;
        const parsed = parseRefusalRecipe(block.recipe, recipeNames);
        if (typeof parsed === 'string') continue;
        const run = refusal.run(parsed);
        const body = transcriptBody(block.lines);
        elisionProbes++;
        if (refusalMatch(body, run)?.equal !== true) foreign.push(`${at} stopped matching its own run`);
        const withForeignPath = [`/somewhere/else/${parsed.spec}.json: ${body[0].trim()}`, ...body.slice(1)];
        if (refusalMatch(withForeignPath, run)?.equal === true) {
          foreign.push(`${at} still matched with a path the recipe never wrote in front of it`);
        }
      }
    }

    // ⑤ GT04's rule, one surface further in — and the answer to "what does this
    // change make stale next?". `gallery/README.md` now explains the recipe, and
    // explaining it means writing down what announces a refusal while the code
    // COLLECTS it from the runs. So the prose is derived too: the paragraph that
    // names them is located by the phrase it exists to define, its count is
    // reported so a locator that matched nothing cannot compare empty against
    // empty, and the documented example recipe has to be one this tree really
    // carries rather than an invented one that no longer parses.
    //
    // ⭐ **Both markers are shown there, so both examples are checked here.** The
    // declaration's was not, and that was the gap this card walked into: the
    // index carried a hand-typed `transcript:` comment that nothing compared to
    // anything, so the day the marker changed shape the paragraph teaching it
    // would have gone on teaching the old one. It is held to exactly the recipe's
    // bar — the example parses as a declaration, and it is one a README really
    // carries.
    const index = existsSync(join(galleryRoot, 'README.md'))
      ? readFileSync(join(galleryRoot, 'README.md'), 'utf8')
      : '';
    const announces = index.split(/\n[ \t]*\n/).filter((para) => /announces a refusal/i.test(para));
    const namedHeads = new Set(announces.flatMap((p) => [...p.matchAll(/`(rigc [a-z]+ error):?`/g)].map((m) => m[1])));
    const namedTags = new Set(announces.flatMap((p) => [...p.matchAll(/`([A-Z][A-Z\d_]{1,9})`/g)].map((m) => m[1])));
    const disagree = (prose: Set<string>, derived: Set<string>, what: string): string[] => [
      ...[...derived].filter((x) => !prose.has(x)).map((x) => `the runs print \`${x}\` as ${what} and gallery/README.md does not name it`),
      ...[...prose].filter((x) => !derived.has(x)).map((x) => `gallery/README.md names \`${x}\` as ${what} and no refusal run prints one`),
    ];
    // The two names nothing in this tree can print, which the red-first pair at
    // the end of this list injects and then looks for by name.
    const NOHEAD = 'rigc nosuch error';
    const NOVERDICT = 'NOSUCHTAG';
    // Both markers are one anchored line, so the index is read line by line for them.
    const documented = [...index.matchAll(new RegExp(REFUSAL_RECIPE.source, 'gm'))].map((m) => m[1]);
    const shownDeclarations = [...index.matchAll(new RegExp(TRANSCRIPT_DECLARATION.source, 'gm'))].map((m) => m[1]);
    const carriedDeclarations = new Set(declared.map((d) => d.reason));
    const prose = [
      ...(announces.length === 1
        ? []
        : [`${announces.length} paragraph(s) of gallery/README.md say what "announces a refusal"; the locator needs exactly one`]),
      ...disagree(namedHeads, refusalVocab.heads, 'an error head'),
      ...disagree(namedTags, refusalVocab.tags, 'a refusal verdict'),
      ...(documented.length === 1 ? [] : [`gallery/README.md shows ${documented.length} example recipe(s); it should show exactly one`]),
      ...documented
        .filter((text) => typeof parseRefusalRecipe(text, recipeNames) === 'string')
        .map((text) => `the recipe gallery/README.md shows does not parse: "${text}"`),
      ...documented
        .filter((text) => ![...recipeRuns.keys()].includes(text))
        .map((text) => `the recipe gallery/README.md shows is not one any README carries: "${text}"`),
      ...(shownDeclarations.length === 1
        ? []
        : [`gallery/README.md shows ${shownDeclarations.length} example declaration(s); it should show exactly one`]),
      ...shownDeclarations
        .filter((reason) => reason.length < TRANSCRIPT_REASON_MIN)
        .map((reason) => `the declaration gallery/README.md shows gives no reason: "${reason}"`),
      ...shownDeclarations
        .filter((reason) => !carriedDeclarations.has(reason))
        .map((reason) => `the declaration gallery/README.md shows is not one any README carries: "${reason}"`),
      // Red-first both ways, on a name nothing in the tree can print — and
      // each probe asks whether THAT name was faulted rather than whether
      // anything was, for the reason `GT04`'s pair states (issue #491).
      ...(disagree(namedHeads, new Set([...refusalVocab.heads, NOHEAD]), 'an error head').some((f) => f.includes(NOHEAD))
        ? []
        : ['an error head the runs print and the prose omits was not faulted']),
      ...(disagree(new Set([...namedTags, NOVERDICT]), refusalVocab.tags, 'a refusal verdict').some((f) => f.includes(NOVERDICT))
        ? []
        : ['a verdict the prose names and no refusal run prints was not faulted']),
      ...(index.replace(/announces a refusal/gi, 'introduces a refusal').split(/\n[ \t]*\n/).filter((p) => /announces a refusal/i.test(p)).length === 0
        ? []
        : ['the locator still found its paragraph after the phrase it keys on was reworded away']),
    ];

    const trouble = [...dragged, ...grammar, ...runs, ...foreign, ...prose,
      ...refusalRecipeBoundFaults({ recipeBlocks: recipeBlocks.length, notDragged, elisionProbes, namedHeads: namedHeads.size, namedTags: namedTags.size }),
    ];
    const held = trouble.length === 0;
    say(
      'GT05_THE_REFUSAL_RECIPE_REACHES_REFUSALS_AND_NOTHING_ELSE',
      held,
      probeDetail(held, trouble,
          `${notDragged} block(s) a stated command already reproduces: none reads as a refusal to the trap and ` +
          `none carries a recipe; ${malformed.length} way(s) of stepping outside the recipe grammar each refused ` +
          'by name with a well-formed one parsing beside them; a recipe whose `from` is absent and one whose edit ' +
          `leaves the build green each faulted; on all ${elisionProbes} refusal block(s) the path elision ` +
          'matched the run it came from and refused a path the recipe never wrote; and the one paragraph of ' +
          'gallery/README.md that says what announces a refusal names ' +
          `{${[...namedHeads].sort().join(' ')}} and {${[...namedTags].sort().join(' ')}}, which is exactly what ` +
          `the recipe runs print, with the ${documented.length} recipe and the ${shownDeclarations.length} ` +
          'declaration it shows as examples each being one a README really carries'),
      'the recipe widens what may be RUN, so the thing to prove is that it did not widen what COUNTS. Every ' +
        'clause here is two-sided on purpose: a parser that refused every recipe would satisfy the grammar half, ' +
        'a matcher that equalled nothing would satisfy the elision half, and both would leave the gate reading ' +
        'nothing while printing a clean line. The last clause is GT04 one surface further in and it is the answer ' +
        'to what this change makes stale next — documenting the recipe means writing down what announces a ' +
        'refusal, so the paragraph that does is derived from the same runs the code reads',
    );
  }

  // GT07 — the actual FAIL line names only missing bounds, even when the former trouble list was empty.
  {
    const base = { recipeBlocks: 4, notDragged: 14, elisionProbes: 4, namedHeads: 1, namedTags: 1 };
    const probes = refusalRecipeBoundFaults(base);
    const plants = [
      { read: { ...base, recipeBlocks: 3 }, names: ['3 verified refusal recipe block(s)', 'floor is 4'] },
      { read: { ...base, notDragged: 13 }, names: ['13 stated-command block(s)', 'floor is 14'] },
      { read: { ...base, elisionProbes: 3 }, names: ['3 path-elision probe(s)', 'floor is 4'] },
      { read: { ...base, namedHeads: 0 }, names: ['0 error head(s)', 'floor is 1'] },
      { read: { ...base, namedTags: 0 }, names: ['0 refusal verdict(s)', 'floor is 1'] },
      { read: { ...base, recipeBlocks: 5 }, names: ['4 path-elision probe(s) for 5 verified refusal recipe block(s)', 'required one per block'] },
    ];
    const cases: string[] = [];
    for (const plant of plants) {
      const faults = refusalRecipeBoundFaults(plant.read);
      if (!plant.names.every((name) => faults.some((fault) => fault.includes(name)))) probes.push(`bound plant ${JSON.stringify(plant.read)} did not name ${plant.names.join(' and ')}: ${faults.join('; ')}`);
      else cases.push(faults.join('; '));
      const held = faults.length === 0;
      const lines: string[] = [];
      const print = console.log;
      let result = 0;
      console.log = (...args: unknown[]): void => { lines.push(args.map(String).join(' ')); };
      try { result = reportCase('GT05_PLANTED_BOUND', held, probeDetail(held, faults, 'POSITIVE_FORM_PLANTED_BY_GT07'), 'ORIGIN_PLANTED_BY_GT07'); }
      finally { console.log = print; }
      const out = lines.join('\n');
      if (result !== 1 || !out.startsWith('  FAIL  GT05_PLANTED_BOUND: ') || !plant.names.every((name) => out.includes(name)) || out.includes('POSITIVE_FORM_PLANTED_BY_GT07') || out.includes('ORIGIN_PLANTED_BY_GT07')) {
        probes.push(`bound plant printed ${JSON.stringify(out)}, required FAIL naming only its missing bounds`);
      }
    }
    say('GT07_A_REFUSAL_RECIPE_BOUND_FAILURE_PRINTS_ONLY_THE_BOUND_THAT_FAILED', probes.length === 0,
      probeDetail(probes.length === 0, probes, `positive bounds clean; ${cases.length} bound plants captured the actual FAIL line: ${cases.join('; ')}`),
      'issue #1447: the verdict and explanation formerly read different predicates; each unchanged floor and the coverage equality must enter the same fault list');
  }

  // --- GT06: the edit a recipe states is spelled once (issue #443) ----------
  //
  // 🚨 The defect this closes was in the tree while #442 was written, one
  // directory over: `gallery/nod/README.md` carried the recipe's own
  // replace-all a second time, as a `sed` one-liner in a ```sh fence directly
  // above the block. Both copies were real — measured rather than assumed, the
  // `sed` lines ran and produced exactly the quoted refusals — and only one of
  // them was checked, because the scan skips a fence with an info string. Two
  // copies of one fact with a gate on one of them is #415, #422 and #429 in
  // turn, and this is the fourth.
  //
  // ⛔ The remedy is removal and not a second checker. A gate over the copy
  // would keep both spellings alive and make the tree agree with itself; what
  // this case asserts is that the copy is GONE and cannot come back, which is
  // why it reads the fences the transcript scan cannot see and nothing else.
  //
  // ⭐ What it deliberately does NOT refuse: a command that mentions a recipe's
  // `from`. `gallery/nod` keeps the green half of its own bracket, which the
  // recipe grammar structurally cannot express — a recipe whose edit leaves the
  // build green is a fault one case up — and the sweeps
  // beside it patch the same fields to other values. A rule that refused those
  // would be refusing every command in the gallery that touches a spec, which
  // is the `ERT05` shape: a check that refuses everything tells nothing from
  // nothing. The line is both halves of one edit on one line.
  //
  // ⚠️ **`gallery/README.md` is outside this scan, and the reason is a
  // measurement rather than an oversight.** The index shows one filled-in recipe
  // inside a ```markdown fence, so it carries both halves of an edit on one line
  // and this rule would read it as a copy. It is not one: `GT05` already requires
  // that example to parse AND to be a recipe some README really carries, so it is
  // DERIVED from this population rather than a second unchecked spelling of it.
  // Widening the scan here would fault the one copy in the gallery already gated.
  {
    const recipes: RefusalRecipe[] = [];
    for (const readme of readmes.values()) {
      for (const block of galleryBlocks(readme)) {
        if (block.info !== '' || block.recipe === null) continue;
        const parsed = parseRefusalRecipe(block.recipe, recipeNames);
        if (typeof parsed !== 'string') recipes.push(parsed);
      }
    }
    const restates = (line: string, recipe: RefusalRecipe): boolean =>
      line.includes(recipe.from) && line.includes(recipe.to);

    const copies: string[] = [];
    const infoStrings = new Set<string>();
    let skippedFences = 0;
    let mentions = 0;
    for (const [example, readme] of readmes) {
      for (const block of galleryBlocks(readme)) {
        if (block.info === '') continue;
        skippedFences++;
        infoStrings.add(block.info);
        block.lines.forEach((line, k) => {
          for (const recipe of recipes) {
            if (restates(line, recipe)) {
              copies.push(
                `gallery/${example}/README.md:${block.line + 1 + k} spells a recipe's whole edit a second time, ` +
                  `in a \`${block.info}\` fence this scan skips — the recipe is "${recipe.text}"`,
              );
            } else if (line.includes(recipe.from)) mentions++;
          }
        });
      }
    }

    // Red-first, on a command GENERATED from a recipe rather than typed here:
    // the one that was deleted is the one the rule has to catch, and generating
    // it is the only way this probe cannot drift away from the grammar.
    const one = recipes[0];
    const probes =
      one === undefined
        ? ['no recipe was parsed, so the rule was probed against nothing']
        : [
            ...(restates(`sed 's/${one.from}/${one.to}/g' gallery/${one.example}/${one.spec}.json > /tmp/x.json`, one)
              ? []
              : ['a command spelling a whole recipe edit was not caught']),
            ...(restates(`sed 's/${one.from}/whatever else/g' gallery/${one.example}/${one.spec}.json`, one)
              ? ['a command naming only the recipe\'s `from` was caught, so the rule refuses commands that copy nothing']
              : []),
            ...(restates(`bun cli.ts build --rig gallery/${one.example}/rig.json --out /tmp/x`, one)
              ? ['a command naming neither half of the edit was caught']
              : []),
          ];

    say(
      'GT06_THE_EDIT_A_REFUSAL_RECIPE_STATES_IS_SPELLED_ONCE',
      copies.length === 0 && probes.length === 0 && recipes.length >= 4 && skippedFences >= 10,
      copies.length === 0 && probes.length === 0
        ? `${skippedFences} fence(s) this scan skips — {${[...infoStrings].sort().join(' ')}} — read against the ` +
          `${recipes.length} recipe(s) the gallery carries: none spells one of their edits a second time, while ` +
          `${mentions} line(s) name a recipe's \`from\` and patch it to something else, which is the half the ` +
          'rule has to leave alone'
        : [...copies, ...probes].join('\n          '),
      'a refusal recipe is checked to the character and a shell line beside it is checked not at all, so the two ' +
        'spellings of one edit drift apart and the ungated one is the one a reader copies. #442 made both of them ' +
        'visible and that is how this became legible at all: before it, the recipe was an HTML comment and only ' +
        'the `sed` line was on the page, so there was nothing for a reader to compare',
    );
  }

  // --- GT64/GT65: the same figures, said in PROSE instead of quoted ---------
  //
  // Everything above holds what a README QUOTES. It reaches nothing a README
  // merely SAYS — and five pages said their verdict rather than quoting it:
  // *"20 assertions ran, 6 skipped"* in a table cell, with the run one line away
  // printing seven (issue #609). Every one of those ten figures was stale, and
  // none of them was stale by much, which is the shape that survives a reader.
  //
  // ⭐ The repair is the quoted block those pages now carry, and this is the
  // clause that keeps the repair from being undone by an author who finds a
  // sentence tidier than a fence. It is the pair to GT02: that one says a quoted
  // figure has to reproduce, this one says a figure has to be quoted.
  //
  // 🔒 Two-sided, because "no page states it" is satisfied for free by a scanner
  // that matches nothing. The same words appear INSIDE the quoted blocks on every
  // one of those pages, so the run reports that count too — a pattern that had
  // stopped matching would take both sides to zero at once, and the floor reads
  // the inside one.
  //
  // ⚠️ What it cannot do is name a synonym nobody has used yet. The report's own
  // half of the vocabulary is derived from the summary line the runs print, so it
  // follows the tool; the two words beside it are prose the tool never printed,
  // which is why they cannot be derived and exactly why the sentences drifted —
  // a figure written in a word no run produces has nothing to be compared with.
  {
    const summaryLines = [...pools.values()]
      .flatMap((runs) => runs.flatMap((run) => run.lines))
      .filter((line) => REPORT_SUMMARY_LINE.test(line));
    const derived = new Set(
      summaryLines.flatMap((line) => [...line.matchAll(/\b\d+\s+([a-z][a-z-]*)/g)].map((m) => m[1])),
    );
    const words = [...new Set([...derived, ...PROSE_ONLY_COUNT_WORDS])].sort();
    const figure = new RegExp(`\\b\\d+\\s+(?:\\*\\*)?(?:${words.join('|')})\\b`, 'g');

    const index = join(galleryRoot, 'README.md');
    const pages: Array<[string, string]> = [
      ...(existsSync(index) ? ([['gallery/README.md', readFileSync(index, 'utf8')]] as Array<[string, string]>) : []),
      ...[...readmes].map(([example, text]) => [`gallery/${example}/README.md`, text] as [string, string]),
    ];
    const scan = scanProseFigures(pages, figure);

    say(
      'GT64_NO_GALLERY_README_STATES_A_RUN_FIGURE_IN_PROSE',
      scan.outside.length === 0 && pages.length >= 2 && derived.size >= 4 && summaryLines.length > 0 && scan.inside > 0,
      summaryLines.length === 0 || derived.size < 4
        ? `the count vocabulary was read off ${summaryLines.length} summary line(s) and came back as ` +
          `{${[...derived].sort().join(' ')}} — this case cannot conclude anything`
        : scan.outside.length === 0
          ? `${pages.length} page(s), ${scan.lines} line(s) outside a fence: none pairs a figure with any of ` +
            `{${words.join(' ')}}, while ${scan.inside} such pairing(s) stand inside quoted blocks, which is where ` +
            'the transcript gate above re-runs the command and compares them'
          : scan.outside.join('\n          '),
      'issue #609: the five pages that stated their verdict in a sentence had all ten figures wrong, and the ' +
        'selftest printed the right ones one line away from them every run. A count a page keeps by hand is a ' +
        'claim nothing measures — CLAUDE.md *The selftest and its fixtures*, and the reason the repair is a quoted ' +
        'block rather than a re-taken sentence',
    );

    // The positive control, and the two ways this rule could be wrong rather
    // than merely unfired: it could fault a figure that IS quoted, and it could
    // fault any figure at all rather than the report's own words.
    //
    // ⚠️ The sentence carries TWO pairings, not one, and the quoted plant is
    // counted rather than incremented for that reason — this case failed on its
    // first run asserting `inside + 1` against an inside count that had moved by
    // two. The figure is read off the plant with the same pattern the scan uses,
    // so a plant reworded later still reconciles.
    const PLANTED = '18 assertions ran, 7 skipped';
    const FOREIGN = ' 18 widgets ran, 7 sprockets';
    const plantedPairs = [...PLANTED.matchAll(figure)].length;
    const victim = pages[pages.length - 1];
    const plantedProse = scanProseFigures(
      [...pages.slice(0, -1), [victim[0], `${victim[1]}\n\n| a claim | ${PLANTED} |\n`]],
      figure,
    );
    const plantedQuoted = scanProseFigures(
      [...pages.slice(0, -1), [victim[0], `${victim[1]}\n\n\`\`\`\n${PLANTED}\n\`\`\`\n`]],
      figure,
    );
    const plantedForeign = scanProseFigures(
      [...pages.slice(0, -1), [victim[0], `${victim[1]}\n\n| a claim |${FOREIGN} |\n`]],
      figure,
    );
    const plants = [
      ...(plantedPairs > 0 ? [] : [`the planted sentence "${PLANTED}" pairs no figure with any of the scanned words`]),
      ...(plantedProse.outside.length === scan.outside.length + 1
        ? []
        : [`a prose figure planted in ${victim[0]} moved the fault count from ${scan.outside.length} to ${plantedProse.outside.length}`]),
      ...(plantedProse.outside.some((fault) => fault.startsWith(`${victim[0]}:`))
        ? []
        : ['the planted fault was not reported against the page it was planted in']),
      ...(plantedQuoted.outside.length === scan.outside.length
        ? []
        : ['the same sentence inside a fence was faulted, so the rule does not mean what it says']),
      ...(plantedQuoted.inside === scan.inside + plantedPairs
        ? []
        : [
            `the same sentence inside a fence moved the quoted count from ${scan.inside} to ${plantedQuoted.inside}, ` +
              `where its own ${plantedPairs} pairing(s) say it should read ${scan.inside + plantedPairs}`,
          ]),
      ...(plantedForeign.outside.length === scan.outside.length
        ? []
        : ['a figure paired with words no report prints was faulted, so the rule keys on digits rather than on the report']),
    ];
    say(
      'GT65_THE_PROSE_FIGURE_SCAN_FAULTS_A_PLANT_AND_LEAVES_A_QUOTED_ONE_ALONE',
      plants.length === 0 && pages.length >= 2,
      // ⚠️ The page count is bound in front of BOTH branches, because it is the
      // floor this whole probe stands on and the clean branch had no value for
      // it: with the gallery README set reduced to one page on disk the old
      // sentence printed `on gallery/walk/README.md: "…" faults in prose by page
      // and line, …` — the everything-is-fine line, on the run where the set it
      // scans had collapsed (issue #498). GT64 one case above prints the same
      // count, which is what makes the pair readable.
      `over ${pages.length} page(s), and the floor is 2 — one page is a plant with nothing beside it: ` +
      (plants.length === 0
        ? `on ${victim[0]}: "${PLANTED}" faults in prose by page and line, the same sentence inside a fence does ` +
          `not and joins the ${plantedQuoted.inside} quoted pairing(s) instead, and "${FOREIGN.trim()}" faults nowhere`
        : plants.join('\n          ')),
      'a scan that faults everything and a scan that faults nothing both leave GT64 printing PASS. The middle ' +
        'plant is the load-bearing one: the repair for #609 is to move these figures INTO quoted blocks, so a rule ' +
        'that faulted them there would forbid the fix it exists to protect',
    );
  }

  return bad;
}

// ---------------------------------------------------------------------------
// seeing the result — `rigc render` and `rigc preview` (issues #216, #226)
// ---------------------------------------------------------------------------
//
// ⭐ Why this suite exists and what it is aimed at. Every other control in this
// file asks whether the artifact is RIGHT; these ask whether anybody can LOOK at
// it. A rig whose head sits visibly off its torso passes the whole gate, loads in
// `spine-core` and steps numerically clean — the offsets are the ones the spec
// asked for — so looking is the only remedy there is, and until #216 the package
// had no command that looked.
//
// 🚨 The load-bearing case is R04, and it is a REGRESSION control rather than a
// feature one. `A19` learned in #215 that indexed and greyscale art carrying a
// `tRNS` chunk is ordinary transparent art (PT01–PT07 above), so such a part builds
// and validates green — while `decodePng` still refused colour types 0 and 3, and
// `src/render.ts` reads its pages through exactly that decoder. Shipping a "see
// what you built" command on top of it would have rebuilt #215's wall one step
// further along: green from `build`, refused by the picture. R04 walks the whole
// path a stranger walks, on the art the tools they own actually write.
//
// The rig deliberately mixes colour types — an indexed+tRNS `block.png` beside a
// truecolour+alpha `marker.png` — because one page of each is what proves the
// expansion happens per page rather than per file format.

/** The probe rig's art, translated 40 units across one second: 13 frames at 12 fps. */
const SLIDE_MOTION = {
  spec: 'rigc-motion/1',
  archetype: 'static_probe',
  cut: 'static_probe',
  easings: {},
  animations: {
    slide: {
      duration: 1,
      loop: false,
      tracks: [
        {
          bone: 'block',
          property: 'translatex',
          keys: [
            { t: 0, v: [0] },
            { t: 1, v: [40] },
          ],
        },
      ],
    },
  },
};

/** Every `f####.png` in a frame directory, in index order. */
function frameFiles(dir: string): string[] {
  return readdirSync(dir)
    .filter((f) => /^f\d{4}\.png$/.test(f))
    .sort();
}

/**
 * The functions on the generic side of `src/render.ts`'s posing seam (issue
 * #965): everything that samples, frames or exports a pose through `Poser`.
 */
const SEAM_GENERIC = ['sampleAnimation', 'sampleSetupPose', 'sampleAll', 'framingViewport', 'geometryFileOf', 'nonFinitePoseOf', 'drawResolver', 'frameOf'] as const;

/**
 * Which of `SEAM_GENERIC` names an identifier render.ts imports from
 * spine-core (read off `importing`, `src/render.ts`), read off `text` — since
 * issue #1052 `src/render_shared.ts`, where the samplers moved and which links
 * nothing of the runtime; a function the text no longer declares is a fault
 * too, so a rename cannot empty the scan.
 */
function seamLeaks(importing: string, text: string): { names: string[]; faults: string[] } {
  const block = /import\s*\{([^}]*)\}\s*from\s*'@esotericsoftware\/spine-core'/.exec(importing)?.[1] ?? '';
  const names = block
    .split(',')
    .map((entry) => entry.trim().replace(/^type\s+/, ''))
    .filter((name) => /^\w+$/.test(name));
  const faults: string[] = [];
  for (const fn of SEAM_GENERIC) {
    const at = text.search(new RegExp(`\\nfunction ${fn}\\(|\\nexport function ${fn}\\(`));
    if (at < 0) {
      faults.push(`render_shared.ts declares no function ${fn}`);
      continue;
    }
    const end = text.indexOf('\n}\n', at);
    const body = text.slice(at, end < 0 ? text.length : end).split('\n').filter((line) => !/^\s*(\/\/|\*|\/\*\*)/.test(line)).join('\n');
    const hit = names.filter((name) => new RegExp(`\\b${name}\\b`).test(body));
    if (hit.length > 0) faults.push(`${fn} names ${hit.join(', ')} from spine-core`);
  }
  return { names, faults };
}

function runSeeItSuite(): number {
  console.log('\n── seeing the result: render + preview (issues #216, #226) ──');
  let bad = 0;
  const say = (name: string, ok: boolean, detail: string, why: string): void => {
    bad += reportCase(name, ok, detail, why);
  };

  // --- the artifact, built through the CLI on deliberately mixed colour types ---
  const dirs = writeProbeRig();
  writeTypedPng(join(dirs.dir, 'block.png'), 12, 8, { colourType: 3, trns: true });
  const motionPath = join(dirs.dir, 'probe.motion.json');
  writeFileSync(motionPath, `${JSON.stringify(SLIDE_MOTION, null, 2)}\n`);
  const build = runCli([
    'build',
    '--rig', dirs.rigPath,
    '--motion', motionPath,
    '--images', dirs.dir,
    '--out', dirs.outDir,
  ]);
  say(
    'R04_INDEXED_ART_BUILDS_AND_THEN_RENDERS',
    build.status === 0,
    `build exit=${String(build.status)} on a rig whose block.png is colour type 3 + tRNS`,
    'issue #226: the gate accepts this art since #215, and the renderer read it through a decoder that did not',
  );

  const framesDir = join(dirs.dir, 'frames');
  const render = runCli(['render', '--candidate', dirs.outDir, '--animation', 'slide', '--out', framesDir]);
  const set = join(framesDir, 'slide');
  const files = render.status === 0 && existsSync(set) ? frameFiles(set) : [];
  say(
    'R01_RENDER_WRITES_THE_SAMPLED_FRAME_SERIES',
    render.status === 0 && files.length === 13,
    render.status === 0
      ? `${files.length} frame(s) in ${set} (1.000s at ${PROTOCOL_FPS} fps samples to 13)`
      : `render exit=${String(render.status)}: ${render.stderr.split('\n')[0]}`,
    'the frame series is the cheapest possible answer to "did I get what I authored", and #226 sat on its path',
  );

  // The sidecar is what makes the directory a frame SET, so the pictures are
  // measured against IT rather than against a number this file repeats.
  let sidecar: FramesSidecar | null = null;
  if (existsSync(join(framesDir, FRAMES_SIDECAR))) {
    sidecar = JSON.parse(readFileSync(join(framesDir, FRAMES_SIDECAR), 'utf8')) as FramesSidecar;
  }
  const plates = files.map((f) => readPlate(join(set, f)));
  const expected = sidecar ? [sidecar.viewport.pixelWidth, sidecar.viewport.pixelHeight] : [0, 0];
  // ⚠️ `expected` is the DECLARED size, so a detail that prints it is printing the
  // sidecar back rather than the pictures. The probe rows below carry what each
  // plate measured, which is the half the old sentence could not say (issue #498).
  let sizeProbes: string[];
  let sizeClean: string;
  if (sidecar === null) {
    sizeProbes = [`no ${FRAMES_SIDECAR} beside the frames, so nothing declares a size to hold a picture to`];
    sizeClean = 'unreachable while there is no sidecar: the row above names that instead';
  } else {
    sizeProbes = [
      ...floorProbes(
        [[plates.length, 1, `${plates.length} frame(s) were read off disk and measured`]],
        'so the comparison below ran over no pictures at all and a set could agree with its own box off nothing',
      ),
      ...firstFew(
        plates.flatMap((plate, i) =>
          plate.width === expected[0] && plate.height === expected[1]
            ? []
            : [`${files[i]} measures ${plate.width}x${plate.height} and the sidecar declares ${expected[0]}x${expected[1]}`],
        ),
        'frame(s)',
      ),
      ...(sidecar.sets.length === 1
        ? sidecar.sets[0].sampled === files.length
          ? []
          : [`the sidecar declares ${sidecar.sets[0].sampled} frame(s) sampled and ${files.length} are on disk`]
        : [
            `the sidecar declares ${sidecar.sets.length} set(s) where this reads one, so the sampled count has no ` +
              'single set to come off',
          ]),
    ];
    sizeClean =
      `${files.length} frame(s), every one MEASURED at ${expected[0]}x${expected[1]} — the size the sidecar's one ` +
      `set declares, whose sampled count is the same ${files.length}`;
  }
  const sizeHeld = sizeProbes.length === 0;
  say(
    'R02_EVERY_FRAME_IS_THE_SIZE_THE_SIDECAR_DECLARES',
    sizeHeld,
    probeDetail(sizeHeld, sizeProbes, sizeClean),
    'a frame set whose pictures are not the size its own box says is unreadable by `check` and by a human with a ' +
      'ruler. ⚠️ The detail is a probe list because the figure it used to print was the sidecar\'s own: measured, a ' +
      'plate at the wrong size took this FAIL and printed "N frame(s) at WxH" where WxH was the DECLARED size — the ' +
      'answer the control wanted, handed back with nothing in the sentence having measured a plate (issue #498)',
  );

  // Motion, not merely files: 13 identical pictures is what a renderer that never
  // advanced the pose would also write, and it would pass every count above.
  let moved = 0;
  if (plates.length > 1) {
    for (let i = 0; i < plates[0].data.length; i++) moved += Math.abs(plates[0].data[i] - plates[plates.length - 1].data[i]);
  }
  say(
    'R03_THE_FRAMES_ACTUALLY_MOVE',
    moved > 0 && existsSync(join(set, SHEET_FILE)),
    `|f0000 − f${String(files.length - 1).padStart(4, '0')}| = ${moved} across the plate, and ${SHEET_FILE} is beside them`,
    'a series of identical stills passes every count a frame set has; only comparing two of them can tell',
  );

  // The decoder itself, at the level the fix lives: one control per colour type
  // `tools/plate.ts` could not write and therefore never met until #226.
  const probe = mkdtempSync(join(harnessTemp(), 'rigc-decode-'));
  writeTypedPng(join(probe, 'indexed.png'), 8, 4, { colourType: 3, trns: true });
  writeTypedPng(join(probe, 'grey.png'), 8, 4, { colourType: 0, trns: true });
  // 8x8 rather than 8x4: `writeGreyAlphaPng` makes a two-pixel transparent border,
  // and at height 4 there is no interior left for the opaque half of the control.
  writeGreyAlphaPng(join(probe, 'greyalpha.png'), 8, 8);
  const indexed = readPlate(join(probe, 'indexed.png'));
  const grey = readPlate(join(probe, 'grey.png'));
  const greyAlpha = readPlate(join(probe, 'greyalpha.png'));
  // The fixtures put palette entry 0 (and greyscale 30) on the "off" squares and
  // declare exactly those invisible, so the checkerboard's two halves are the two
  // alpha answers — a decoder that ignored tRNS would return 255 everywhere.
  const expansions =
    indexed.get(0, 0)[3] === 255 &&
    indexed.get(4, 0)[3] === 0 &&
    indexed.get(0, 0).slice(0, 3).join() === '220,210,200' &&
    grey.get(0, 0)[3] === 255 &&
    grey.get(4, 0)[3] === 0 &&
    grey.get(0, 0).slice(0, 3).join() === '220,220,220' &&
    greyAlpha.get(0, 0)[3] === 0 &&
    greyAlpha.get(4, 4)[3] === 255;
  say(
    'R05_DECODE_EXPANDS_PALETTES_AND_GREYSCALE_TO_RGBA',
    expansions,
    `indexed ${JSON.stringify(indexed.get(0, 0))}/${JSON.stringify(indexed.get(4, 0))}, ` +
      `greyscale ${JSON.stringify(grey.get(0, 0))}/${JSON.stringify(grey.get(4, 0))}, ` +
      `greyscale+alpha ${JSON.stringify(greyAlpha.get(0, 0))}/${JSON.stringify(greyAlpha.get(4, 4))}`,
    'every one of these threw `unsupported colour type` before #226, and the gate had been accepting them since #215',
  );

  // A colour type that is not one still has to be refused: the fix must not have
  // replaced a false refusal with a decoder that reads anything it is handed.
  let refused = '';
  try {
    const ihdr = new Uint8Array(13);
    new DataView(ihdr.buffer).setUint32(0, 1);
    new DataView(ihdr.buffer).setUint32(4, 1);
    ihdr[8] = 8;
    ihdr[9] = 5; // not a PNG colour type at all
    const bytes = [PNG_SIGNATURE, pngChunk('IHDR', ihdr), pngChunk('IEND', new Uint8Array(0))];
    const flat = new Uint8Array(bytes.reduce((n, b) => n + b.length, 0));
    let at = 0;
    for (const b of bytes) {
      flat.set(b, at);
      at += b.length;
    }
    decodePng(flat);
  } catch (err) {
    refused = (err as Error).message;
  }
  say(
    'R06_A_COLOUR_TYPE_THAT_IS_NOT_ONE_IS_STILL_REFUSED',
    /unsupported colour type 5/.test(refused),
    refused || 'colour type 5 decoded without complaint',
    'widening a decoder is only a fix while the things it must not read still fail loudly',
  );

  // --- preview: one file, everything in it, and the player referenced not copied
  const html = join(dirs.dir, 'preview.html');
  const preview = runCli(['preview', '--candidate', dirs.outDir, '--out', html]);
  const page = preview.status === 0 && existsSync(html) ? readFileSync(html, 'utf8') : '';
  // Read through `existsSync` rather than straight: a build that failed above must
  // leave this suite reporting FAIL lines, not dying on an ENOENT — a crash here
  // would take every case after it with it and print no verdict at all.
  const readIfThere = (path: string): string => (existsSync(path) ? readFileSync(path, 'utf8') : '');
  const atlasText = readIfThere(join(dirs.outDir, 'skeleton.atlas'));
  const skeletonText = readIfThere(join(dirs.outDir, 'skeleton.json'));
  const pageNames = atlasText === '' ? [] : atlasPageNames(atlasText);
  const pageCount = pageNames.length;
  const imageUris = page.split('data:image/png;base64,').length - 1;
  const carries = (mime: string, body: string): boolean =>
    page.includes(`data:${mime};base64,${Buffer.from(body, 'utf8').toString('base64')}`);
  // "byte for byte" is a CLAIM, and the old detail made it in the branch a run
  // that had just refuted it reached: only `preview.status` picked the branch, so
  // a page missing the atlas printed the sentence saying it was in there (#498).
  //
  // The page count is bound rather than written twice: the row states the bound
  // beside the value found, and a bound spelled once cannot drift from itself.
  const SPILLED_PAGES = 2;
  const embedProbes = [
    ...(preview.status === 0 ? [] : [`preview exit=${String(preview.status)}: ${preview.stderr.split('\n')[0]}`]),
    ...(skeletonText === ''
      ? ['no skeleton.json was written beside the candidate, so there is nothing on disk to find in the page']
      : carries('application/json', skeletonText)
        ? []
        : ['the skeleton.json on disk is NOT in the page as an application/json data URI, so what it embeds is not ' +
            'this artifact byte for byte']),
    ...(carries('text/plain', atlasText)
      ? []
      : ['the skeleton.atlas on disk is NOT in the page as a text/plain data URI, so what it embeds is not this ' +
          'artifact byte for byte']),
    ...(imageUris === pageCount
      ? []
      : [`${imageUris} image data URI(s) are in the page against ${pageCount} page(s) the atlas names`]),
    ...(pageCount === SPILLED_PAGES
      ? []
      : [`${pageCount} atlas page(s) came off the built candidate where this fixture spills onto ${SPILLED_PAGES}, ` +
          'so the count above would be agreeing with a number that had itself moved']),
  ];
  const embedHeld = embedProbes.length === 0;
  say(
    'P01_PREVIEW_EMBEDS_THE_WHOLE_ARTIFACT',
    embedHeld,
    probeDetail(
      embedHeld,
      embedProbes,
      `skeleton and atlas embedded byte for byte, ${imageUris} image data URI(s) for ${pageCount} atlas page(s)`,
    ),
    'a preview missing one page is a file that opens and draws the wrong picture — the failure this command exists to catch',
  );

  // The keys are what the player asks for, so they are as load-bearing as the
  // bytes: a page embedded under a name nothing requests is not embedded.
  // 🚨 This detail had no branch at all, so it printed the same sentence on both
  // verdicts — and the sentence was the WANTED key list, spelled from the names
  // the atlas declares rather than from anything found in the page. A run with
  // the atlas key missing printed `"skeleton.atlas"` as one of the keys (#498).
  const keyProbes = [
    ...floorProbes(
      [[pageCount, 1, `${pageCount} page name(s) came off the atlas to look for`]],
      'so "every page name is a key" would be true of a page carrying no page keys whatsoever',
    ),
    ...firstFew(
      pageNames
        .filter((name) => !page.includes(JSON.stringify(name).slice(1, -1)))
        .map((name) => `the atlas names page "${name}" and the page carries no key spelling it`),
      'page name(s)',
    ),
    ...(page.includes(SKELETON_KEY)
      ? []
      : [`the page carries no "${SKELETON_KEY}" key, which is the name the player asks the skeleton for`]),
    ...(page.includes(ATLAS_KEY)
      ? []
      : [`the page carries no "${ATLAS_KEY}" key, which is the name the player asks the atlas for`]),
  ];
  const keyHeld = keyProbes.length === 0;
  say(
    'P02_THE_EMBEDDED_KEYS_ARE_THE_NAMES_THE_PLAYER_ASKS_FOR',
    keyHeld,
    probeDetail(
      keyHeld,
      keyProbes,
      `the page carries a rawDataURIs key for each of ${JSON.stringify([SKELETON_KEY, ATLAS_KEY, ...pageNames])}`,
    ),
    "`config.atlas` has no directory part, so the player asks for each page under the name the ATLAS spells — not its basename",
  );

  // ⚖️ The licence line, as a machine check rather than as a note somebody has to
  // remember: the player is referenced by URL and nothing Esoteric owns is copied
  // into the page. A vendored player would be hundreds of kilobytes of it.
  const referenced = /<script src="https:\/\/unpkg\.com\/@esotericsoftware\/spine-player@[^"]+"><\/script>/.test(page);
  // ⚠️ The half this control is named for — NEVER VENDORED — was the half the old
  // detail did not mention, and it had no branch either: a page with a player
  // copied into it FAILED and printed "player loaded by <script src>" (#498).
  const playerProbes = [
    ...(referenced
      ? []
      : ['no <script src="https://unpkg.com/@esotericsoftware/spine-player@…"> in the page, so the player is not ' +
          'referenced by URL']),
    ...(page.includes('SpinePlayer = class')
      ? [`the page carries \`SpinePlayer = class\`, so a player is VENDORED into these ${(page.length / 1024).toFixed(1)} KiB`]
      : []),
    ...(page.includes('spine-runtimes-license')
      ? []
      : ['the page does not name the Spine Runtimes licence']),
  ];
  const playerHeld = playerProbes.length === 0;
  say(
    'P03_THE_PLAYER_IS_REFERENCED_AND_NEVER_VENDORED',
    playerHeld,
    probeDetail(
      playerHeld,
      playerProbes,
      `player loaded by <script src>, page is ${(page.length / 1024).toFixed(1)} KiB with no player copied into it, ` +
        'and it names the Spine Runtimes licence',
    ),
    'NOTICE.md: the Spine Runtimes are Esoteric Software\'s and rigc redistributes none of them',
  );

  // --- both commands are discoverable, which is half of shipping them ----------
  const renderHelp = runCli(['render', '--help']);
  const previewHelp = runCli(['preview', '--help']);
  const topLevel = runCli([]);
  // 🔸 `probeDetail` rather than `RD02`'s line (issue #498). Seven terms and
  // the sentence carried two exit codes and then a claim — *"both named in the
  // bare-invocation usage"* — which IS one of the terms, with the two phrases
  // each `--help` is read for named nowhere at all. Planted with the bare
  // invocation writing its usage to stdout instead of stderr, it printed
  // `render --help ok, preview --help ok, both named in the bare-invocation
  // usage` on a run where NEITHER was named there.
  const discoverable = [
    ...(renderHelp.status === 0 ? [] : [`\`render --help\` exited ${String(renderHelp.status)}, not 0`]),
    ...(renderHelp.stdout.includes('--animation') ? [] : ['`render --help` does not spell `--animation`']),
    ...(renderHelp.stdout.includes('frame series') ? [] : ['`render --help` does not say what it writes — no "frame series" in it']),
    ...(previewHelp.status === 0 ? [] : [`\`preview --help\` exited ${String(previewHelp.status)}, not 0`]),
    ...(previewHelp.stdout.includes('.html') ? [] : ['`preview --help` does not name the `.html` it writes']),
    ...(topLevel.stderr.includes('rigc render') ? [] : ['the bare-invocation usage does not name `rigc render`']),
    ...(topLevel.stderr.includes('rigc preview') ? [] : ['the bare-invocation usage does not name `rigc preview`']),
  ];
  const discoverableHeld = discoverable.length === 0;
  say(
    'P04_BOTH_COMMANDS_ARE_IN_THE_HELP',
    discoverableHeld,
    probeDetail(
      discoverableHeld,
      discoverable,
      `render --help ${renderHelp.status === 0 ? 'ok' : 'FAILED'}, preview --help ${previewHelp.status === 0 ? 'ok' : 'FAILED'}, ` +
        'both named in the bare-invocation usage',
      (count) => `${count} way(s) the two commands are not discoverable:`,
    ),
    'issue #216 is a discoverability failure as much as a capability one — the renderer already existed and no command exposed it',
  );

  // An animation this skeleton does not have must be refused BY NAME, with the
  // ones it does have listed: the flag is the one place a typo is silent.
  const wrong = runCli(['render', '--candidate', dirs.outDir, '--animation', 'nope', '--out', framesDir]);
  say(
    'P05_AN_UNKNOWN_ANIMATION_IS_REFUSED_AND_THE_REAL_ONES_LISTED',
    wrong.status === 2 && /no animation "nope"/.test(wrong.stderr) && /slide/.test(wrong.stderr),
    `exit=${String(wrong.status)} stderr=${JSON.stringify(wrong.stderr.split('\n')[0])}`,
    'silently rendering every animation because one name was misspelled is a report about the wrong shot',
  );

  // --- R10-R12: which skin is being looked at — issue #571 -------------------
  //
  // 🚨 `render` posed a skeleton and never set a skin, so it drew the DEFAULT
  // skin and nothing else — and `check`, which compares `render`'s frames, drew
  // the default skin on both sides. On a rig whose named skins carry the
  // contested art that is a comparison of blank against blank, and the ninth
  // editor round trip read exactly that: `check` 0.0000 on a rig where the whole
  // construct under test lives in the named skins. The zero was true and empty
  // at once, which is the shape this repository exists to convert into a name.
  //
  // ⭐ The fixture is two named skins filling ONE slot with the same art at two
  // places, plus a slot the DEFAULT skin fills that neither of them touches. It
  // is built that way so both halves of the claim are measurable on it and
  // neither is a number written here: what the skins disagree about must differ
  // between the two renders, and what they share must not. (#567 is why the
  // shared entry is in the default skin rather than in both named ones: a
  // placeholder the default skin and a named skin both fill is refused.)
  const SKIN_PROBE_SKINS: Record<string, Record<string, Record<string, Record<string, unknown>>>> = {
    default: { block: { block: { image: 'block.png' } } },
    left: { marker: { marker: { image: 'marker.png', x: -20 } } },
    right: { marker: { marker: { image: 'marker.png', x: 20 } } },
  };
  /** Everything below is derived off the table above, never off the names in it. */
  const namedSkins = Object.keys(SKIN_PROBE_SKINS).filter((name) => name !== 'default');
  const slotsOfSkin = (name: string): string[] => Object.keys(SKIN_PROBE_SKINS[name] ?? {});
  /** Slots more than one NAMED skin fills — what two renders must disagree about. */
  const contestedSlots = [...new Set(namedSkins.flatMap(slotsOfSkin))].filter(
    (slot) => namedSkins.filter((name) => slotsOfSkin(name).includes(slot)).length > 1,
  );
  /** Slots only the DEFAULT skin fills — what two renders must agree about. */
  const sharedSlots = slotsOfSkin('default').filter((slot) => !namedSkins.some((n) => slotsOfSkin(n).includes(slot)));

  const skinDirs = writeProbeRig({ skins: SKIN_PROBE_SKINS });
  const skinMotion = join(skinDirs.dir, 'probe.motion.json');
  writeFileSync(skinMotion, `${JSON.stringify(SLIDE_MOTION, null, 2)}\n`);
  const skinBuild = runCli([
    'build',
    '--rig', skinDirs.rigPath,
    '--motion', skinMotion,
    '--images', skinDirs.dir,
    '--out', skinDirs.outDir,
    '--copy-images',
  ]);
  const skinPosable =
    skinBuild.status === 0 && existsSync(join(skinDirs.outDir, 'skeleton.json'))
      ? loadPosable(join(skinDirs.outDir, 'skeleton.json'), join(skinDirs.outDir, 'skeleton.atlas'), skinDirs.outDir)
      : null;
  /** `slot -> its posed world vertices`, for one skin or for no skin at all. */
  const posedUnder = (skin: string | undefined): Map<string, string> => {
    const out = new Map<string, string>();
    if (skinPosable === null) return out;
    for (const piece of sampleSetupPose(skinPosable.data, skin === undefined ? undefined : { skin })[0].pieces) {
      out.set(piece.slot, piece.world.map((n) => n.toFixed(4)).join(','));
    }
    return out;
  };
  const noSkin = posedUnder(undefined);
  const perSkin = new Map(namedSkins.map((name) => [name, posedUnder(name)]));
  const [skinA, skinB] = namedSkins;
  const geometryProbes = [
    ...(skinBuild.status === 0 && skinPosable !== null
      ? []
      : [`the two-skin fixture did not build: exit=${String(skinBuild.status)} ${skinBuild.stderr.split('\n')[0]}`]),
    ...floorProbes(
      [
        [contestedSlots.length, 1, `${contestedSlots.length} slot(s) are filled by more than one named skin`],
        [sharedSlots.length, 1, `${sharedSlots.length} slot(s) are filled by the default skin alone`],
        [namedSkins.length, 2, `${namedSkins.length} named skin(s) are in the fixture`],
      ],
      'so the comparison below would be true of a fixture that cannot tell the two skins apart at all',
    ),
    // The reproduction, pinned: with no skin the contested slot draws NOTHING.
    // Not a defect — it is what the default skin honestly holds — but it is the
    // reason the flag has to exist, so it is measured rather than remembered.
    ...contestedSlots.flatMap((slot) =>
      noSkin.has(slot)
        ? [`slot "${slot}" draws with no skin set, and the fixture puts its art in named skins only`]
        : [],
    ),
    // What the skins disagree about has to differ.
    ...contestedSlots.flatMap((slot) => {
      const a = perSkin.get(skinA)?.get(slot);
      const b = perSkin.get(skinB)?.get(slot);
      if (a === undefined || b === undefined) {
        return [`slot "${slot}" draws under ${a === undefined ? skinA : skinB} not at all, so the two cannot differ`];
      }
      return a === b ? [`slot "${slot}" poses identically under "${skinA}" and "${skinB}" — no skin was applied`] : [];
    }),
    // And what they share must not.
    ...sharedSlots.flatMap((slot) => {
      const a = perSkin.get(skinA)?.get(slot);
      const b = perSkin.get(skinB)?.get(slot);
      if (a === undefined || b === undefined) {
        return [`slot "${slot}" is the default skin's and vanished under ${a === undefined ? skinA : skinB}`];
      }
      return a === b ? [] : [`slot "${slot}" is filled by the default skin alone and yet poses differently under the two skins`];
    }),
  ];
  const geometryHeld = geometryProbes.length === 0;
  say(
    'R10_A_SKIN_CHANGES_WHAT_IT_FILLS_AND_LEAVES_WHAT_IT_SHARES_ALONE',
    geometryHeld,
    probeDetail(
      geometryHeld,
      geometryProbes,
      `with no skin set ${noSkin.size} of the fixture's ${skinPosable?.data.slots.length ?? 0} slot(s) draw; under ` +
        `each of [${namedSkins.join(', ')}] ${perSkin.get(skinA)?.size ?? 0} do. The ${contestedSlots.length} ` +
        `contested slot([${contestedSlots.join(', ')}]) draws nothing without a skin and poses differently under ` +
        `the two; the ${sharedSlots.length} shared slot([${sharedSlots.join(', ')}]) poses identically under both`,
    ),
    'the skin is the difference between a picture of this rig and a picture of a different one, and until #571 ' +
      'nothing in this tool could ask for either. Both halves are needed: a "skin" that redrew everything would ' +
      'satisfy the first clause and be a different bug',
  );

  // The CLI path, and the metadata that stops a silent mis-comparison. `check`
  // reads the skin back off frames.json, so a candidate posed under one skin and
  // frames rendered under another is a REFUSAL rather than a number.
  const framesA = join(skinDirs.dir, 'frames-a');
  const renderA = runCli(['render', '--candidate', skinDirs.outDir, '--skin', skinA, '--out', framesA]);
  const sidecarA: FramesSidecar | null = existsSync(join(framesA, FRAMES_SIDECAR))
    ? (JSON.parse(readFileSync(join(framesA, FRAMES_SIDECAR), 'utf8')) as FramesSidecar)
    : null;
  const checkJson = join(skinDirs.dir, 'check-a.json');
  const checkA = runCli([
    'check', '--candidate', skinDirs.outDir, '--frames', framesA, '--skin', skinA, '--json', checkJson,
  ]);
  const checkReport: { skin?: unknown; referenceSkin?: unknown } | null =
    existsSync(checkJson) ? (JSON.parse(readFileSync(checkJson, 'utf8')) as { skin?: unknown }) : null;
  const crossed = runCli(['check', '--candidate', skinDirs.outDir, '--frames', framesA, '--skin', skinB]);
  const silent = runCli(['check', '--candidate', skinDirs.outDir, '--frames', framesA]);
  const carriedProbes = [
    ...(renderA.status === 0 ? [] : [`render --skin ${skinA} exited ${String(renderA.status)}: ${renderA.stderr.split('\n')[0]}`]),
    ...(sidecarA?.skin === skinA
      ? []
      : [`${FRAMES_SIDECAR} records skin ${JSON.stringify(sidecarA?.skin ?? null)} where the render asked for ${JSON.stringify(skinA)}`]),
    ...(checkA.status === 0 ? [] : [`check --skin ${skinA} exited ${String(checkA.status)}: ${checkA.stderr.split('\n')[0]}`]),
    ...(new RegExp(`skin\\s+candidate ${skinA}\\s+frames ${skinA}`).test(checkA.stdout)
      ? []
      : ['the check report header does not name the skin on both sides']),
    ...(checkReport?.skin === skinA && checkReport?.referenceSkin === skinA
      ? []
      : [
          `check.json says skin=${JSON.stringify(checkReport?.skin ?? null)} referenceSkin=` +
            `${JSON.stringify(checkReport?.referenceSkin ?? null)}, and both should be ${JSON.stringify(skinA)}`,
        ]),
    ...(crossed.status === 1 && crossed.stderr.includes(skinA) && crossed.stderr.includes(skinB)
      ? []
      : [
          `a ${skinB} candidate against ${skinA} frames exited ${String(crossed.status)} and its message names ` +
            `${[skinA, skinB].filter((n) => crossed.stderr.includes(n)).length}/2 of the two skins`,
        ]),
    ...(silent.status === 1 && silent.stderr.includes(skinA)
      ? []
      : [`a candidate posed under NO skin against ${skinA} frames exited ${String(silent.status)} instead of refusing`]),
  ];
  const carriedHeld = carriedProbes.length === 0;
  say(
    'R11_CHECK_CARRIES_THE_SKIN_AND_REFUSES_A_COMPARISON_ACROSS_TWO',
    carriedHeld,
    probeDetail(
      carriedHeld,
      carriedProbes,
      `render --skin ${skinA} wrote "${sidecarA?.skin}" into ${FRAMES_SIDECAR}; check --skin ${skinA} agreed ` +
        `(exit=${String(checkA.status)}, report skin=${JSON.stringify(checkReport?.skin)} referenceSkin=` +
        `${JSON.stringify(checkReport?.referenceSkin)}); --skin ${skinB} against those frames exited ` +
        `${String(crossed.status)} naming both, and no --skin at all exited ${String(silent.status)}`,
    ),
    'a figure whose subject is unstated is not a figure. The refusals are the half that cannot be got by reading ' +
      'the report: a skin-A candidate scored against skin-B frames produces a perfectly well-formed MAE about the ' +
      'difference between two skins, and nothing in it looks wrong',
  );

  // A skin the skeleton does not declare is a typo, and a typo that renders is a
  // report about a rig nobody asked for. Both commands refuse by name, and both
  // list what would have worked — `render` as a usage error, `check` as a check
  // error, which is the exit each of them already uses for its own kind of miss.
  const declaredNames = Object.keys(SKIN_PROBE_SKINS);
  const badRender = runCli(['render', '--candidate', skinDirs.outDir, '--skin', 'nope', '--out', join(skinDirs.dir, 'frames-nope')]);
  const badCheck = runCli(['check', '--candidate', skinDirs.outDir, '--frames', framesA, '--skin', 'nope']);
  const namesIn = (text: string): string[] => declaredNames.filter((name) => new RegExp(`\\b${name}\\b`).test(text));
  const refusalProbes = [
    ...(badRender.status === 2 && /no skin "nope"/.test(badRender.stderr)
      ? []
      : [`render --skin nope exited ${String(badRender.status)} saying ${JSON.stringify(badRender.stderr.split('\n')[0].slice(0, 120))}`]),
    ...(namesIn(badRender.stderr).length === declaredNames.length
      ? []
      : [
          `render's refusal names ${namesIn(badRender.stderr).length} of the ${declaredNames.length} declared ` +
            `skin(s) — [${namesIn(badRender.stderr).join(', ')}]`,
        ]),
    ...(badCheck.status === 1 && /no skin "nope"/.test(badCheck.stderr)
      ? []
      : [`check --skin nope exited ${String(badCheck.status)} saying ${JSON.stringify(badCheck.stderr.split('\n')[0].slice(0, 120))}`]),
    ...(namesIn(badCheck.stderr).length === declaredNames.length
      ? []
      : [
          `check's refusal names ${namesIn(badCheck.stderr).length} of the ${declaredNames.length} declared ` +
            `skin(s) — [${namesIn(badCheck.stderr).join(', ')}]`,
        ]),
    ...(existsSync(join(skinDirs.dir, 'frames-nope'))
      ? ['render wrote a frame directory for a skin the skeleton does not declare']
      : []),
  ];
  const refusalHeld = refusalProbes.length === 0;
  say(
    'R12_AN_UNDECLARED_SKIN_IS_REFUSED_BY_NAME_WITH_THE_DECLARED_ONES',
    refusalHeld,
    probeDetail(
      refusalHeld,
      refusalProbes,
      `render exit=${String(badRender.status)} and check exit=${String(badCheck.status)} on --skin nope, each ` +
        `naming all ${declaredNames.length} declared skin(s) [${declaredNames.join(', ')}], and no frame directory ` +
        'was written',
    ),
    "everything in a rig spec resolves by name and a miss is refused by name. spine-core's own by-name setter " +
      'throws `Skin not found: <name>` and lists nothing, which tells an author their name is wrong and not one ' +
      'that would have worked',
  );

  // --- R13-R15: a clipping attachment masks what it clips (issue #844) ------
  //
  // `piecesOf` skipped a clipping attachment as "draws no pixel", so every slot
  // it clips drew whole: a blink read as irises over closed lids, and `check`
  // blamed the rig for it. Everything below is counted off rendered pixels and
  // the clip's own posed polygon, which spine-core computes — never off the
  // numbers in the fixture table, which only choose a polygon smaller than both
  // parts so each of them has pixels to lose.
  const clipped = writeClipProbe('clipped');
  const bare = writeClipProbe('bare');
  const ended = writeClipProbe('ended');
  const clipBuilds = [clipped, bare, ended].flatMap((probe) =>
    probe.posable === null ? [`the "${probe.variant}" clip fixture did not build: ${probe.buildError}`] : [],
  );

  // R13 — inside the clip, nothing of the clipped slot is drawn outside the polygon.
  const clippedBlock = clipSlotPixels(clipped, 'block');
  const bareBlock = clipSlotPixels(bare, 'block');
  const maskProbes = [
    ...clipBuilds,
    ...(clippedBlock.outside === 0
      ? []
      : [`slot "block" draws ${clippedBlock.outside} px outside the clip polygon with the clip on — the clip was not applied`]),
    ...floorProbes(
      [
        [clippedBlock.inside, 1, `slot "block" draws ${clippedBlock.inside} px inside the polygon with the clip on`],
        [bareBlock.outside, 1, `slot "block" draws ${bareBlock.outside} px outside the polygon with the clip removed`],
      ],
      'so a clip that erased the whole slot, or a fixture whose part never reached past the polygon, would read as a ' +
        'working mask',
    ),
  ];
  const maskHeld = maskProbes.length === 0;
  say(
    'R13_A_CLIP_REMOVES_EVERY_PIXEL_OF_ITS_SLOT_OUTSIDE_THE_POLYGON',
    maskHeld,
    probeDetail(
      maskHeld,
      maskProbes,
      `slot "block" under the clip draws ${clippedBlock.inside} px inside its posed polygon and 0 outside it; the ` +
        `same skeleton with the clip removed draws ${bareBlock.outside} px outside it`,
      (count) => `${count} thing(s) the clip did not do:`,
    ),
    'issue #844: the runtime removes these pixels and the rasteriser drew them, so every figure `check` took over a ' +
      'masked slot was a figure about pixels no player shows — and it was silent',
  );

  // R14 — the clip ends AT its end slot: that slot is clipped, the next one is not.
  const endedMarker = clipSlotPixels(ended, 'marker');
  const bareMarker = clipSlotPixels(bare, 'marker');
  const endedBlock = clipSlotPixels(ended, 'block');
  const endProbes = [
    ...clipBuilds,
    ...(endedMarker.outside === 0
      ? []
      : [`the end slot "marker" draws ${endedMarker.outside} px outside the polygon — the clip ended before it`]),
    ...floorProbes(
      [[bareMarker.outside, 1, `slot "marker" draws ${bareMarker.outside} px outside the polygon with the clip removed`]],
      'so the end slot being clipped would be true of a part the polygon never cut',
    ),
    ...(endedBlock.pixels !== null && endedBlock.pixels.equals(bareBlock.pixels ?? Buffer.alloc(0))
      ? []
      : [
          `slot "block", drawn after the end slot, renders ${endedBlock.pixels === null ? 'nothing' : 'a different frame'} ` +
            `from the same slot with no clip at all (${endedBlock.outside} px outside the polygon against ` +
            `${bareBlock.outside})`,
        ]),
  ];
  const endHeld = endProbes.length === 0;
  say(
    'R14_THE_CLIP_ENDS_AT_ITS_END_SLOT_AND_THE_SLOT_AFTER_IT_IS_DRAWN_WHOLE',
    endHeld,
    probeDetail(
      endHeld,
      endProbes,
      `with the clip ending at "marker", "marker" draws 0 px outside the polygon (${bareMarker.outside} without the ` +
        'clip) and "block", drawn after it, is byte-identical to the frame of a skeleton with no clip',
      (count) => `${count} thing(s) the end slot did wrong:`,
    ),
    'spine-webgl ends a clip with `clipEnd(slot)` AFTER drawing each slot, so the end slot is inside the mask and the ' +
      'one after it is not; a clip that ran on, or stopped one slot short, is the same silence R13 exists for',
  );

  // R15 — the framing box counts what the clip removes.
  const framingOf = (probe: ClipProbe): string =>
    probe.posable === null ? 'none' : JSON.stringify(framingViewport(probe.posable.data, 256));
  const boxOf = (probe: ClipProbe): string =>
    probe.posable === null ? 'none' : JSON.stringify(unionBounds([sampleSetupPose(probe.posable.data)]));
  const framingProbes = [
    ...clipBuilds,
    ...(framingOf(clipped) === framingOf(bare)
      ? []
      : [`the clipped skeleton frames to ${framingOf(clipped)} and the same one unclipped to ${framingOf(bare)}`]),
    // The sensitivity half: the drawn geometry has to shrink, or equal framings
    // would be true of a clip that never cut anything the box could see.
    ...(boxOf(clipped) !== boxOf(bare)
      ? []
      : ['the clipped pieces span the same box as the unclipped ones, so equal framings prove nothing about the clip']),
  ];
  const framingHeld = framingProbes.length === 0;
  say(
    'R15_A_CLIP_MOVES_NO_PIXEL_OF_THE_FRAMING',
    framingHeld,
    probeDetail(
      framingHeld,
      framingProbes,
      `clipped and unclipped skeletons frame to the same viewport ${framingOf(clipped)}, while their drawn pieces ` +
        `span ${boxOf(clipped)} against ${boxOf(bare)}`,
      (count) => `${count} way(s) the clip reached the framing:`,
    ),
    'the viewport is a property of the shot, like the one `--slot`/`--hide` keep: framed on clipped geometry, adding ' +
      'or keying a mask would move every pixel it leaves drawn and strand every frames.json already written for the rig',
  );

  // --- R16–R17: the posing seam (issue #965, step 3a of #380) ---------------
  //
  // Every sampler poses through `Poser`, so the core-backed poser of #968 can
  // be handed to them as a second implementation. R16 holds that the samplers
  // draw what the poser hands them and nothing else — a relay changes no byte,
  // a poser that moves its pieces moves exactly those — and R17 that the
  // samplers' own bodies name nothing from spine-core, which is what "behind
  // one interface" means in text.
  const seamProbes: string[] = [];
  let seamDetail = 'the probe rig did not build';
  if (build.status !== 0) seamProbes.push(`the probe rig did not build (exit ${String(build.status)}), so no poser was measured`);
  else {
    const seamPosable = loadPosable(join(dirs.outDir, 'skeleton.json'), join(dirs.outDir, 'skeleton.atlas'), dirs.outDir);
    const spine = spinePoser(seamPosable.data);
    const relay: Poser = { ...spine };
    const shift = (posed: Posed): Posed => ({
      ...posed,
      pieces: (draw) => posed.pieces(draw).map((piece) => ({ ...piece, world: piece.world.map((v, i) => (i % 2 === 0 ? v + 1 : v)) })),
    });
    const shifted: Poser = {
      ...spine,
      setup: (skin) => shift(spine.setup(skin)),
      animation: (name, skin, fps, count, visit) => spine.animation(name, skin, fps, count, (i, posed) => visit(i, shift(posed))),
    };
    const plainBox = framingViewport(seamPosable.data, 256);
    if (plainBox === null) seamProbes.push('the probe rig framed to nothing');
    else {
      const sampling = { bones: true, geometry: true };
      const plain = sampleAll(seamPosable.data, PROTOCOL_FPS, sampling);
      const relayed = sampleAll(relay, PROTOCOL_FPS, sampling);
      const moved = sampleAll(shifted, PROTOCOL_FPS, sampling);
      const pngs = (sets: Map<string, Frame[]>): Buffer[] =>
        [...sets.values()].flat().map((frame) => Buffer.from(renderFrame(frame, seamPosable.pages, plainBox, BACKGROUND).data));
      const [plainPngs, relayPngs, movedPngs] = [pngs(plain), pngs(relayed), pngs(moved)];
      const geometryOf = (source: Poser | typeof seamPosable.data, sets: Map<string, Frame[]>): string =>
        [...sets].map(([name, frames]) => geometryText(geometryFileOf(source, name, PROTOCOL_FPS, frames, plainBox, undefined))).join('');
      if (JSON.stringify(framingViewport(relay, 256)) !== JSON.stringify(plainBox)) seamProbes.push('a relaying poser framed to a different box');
      if (plainPngs.length === 0) seamProbes.push('the probe rig sampled no frame');
      if (relayPngs.length !== plainPngs.length || relayPngs.some((b, i) => !b.equals(plainPngs[i]))) seamProbes.push('a relaying poser drew a frame that differs from the spine-core path');
      if (geometryOf(relay, relayed) !== geometryOf(seamPosable.data, plain)) seamProbes.push('a relaying poser wrote a geometry file that differs from the spine-core path');
      const movedFrames = movedPngs.filter((b, i) => !b.equals(plainPngs[i])).length;
      if (movedFrames !== plainPngs.length) seamProbes.push(`a poser moving every piece one world unit right changed ${movedFrames} of ${plainPngs.length} frame(s)`);
      const plainUnion = unionBounds(plain.values());
      const movedUnion = unionBounds(moved.values());
      if (movedUnion.minX !== plainUnion.minX + 1 || movedUnion.maxX !== plainUnion.maxX + 1 || movedUnion.minY !== plainUnion.minY || movedUnion.maxY !== plainUnion.maxY) {
        seamProbes.push(`the moved poser's pieces span ${JSON.stringify(movedUnion)} against ${JSON.stringify(plainUnion)}; x should move by exactly one and y not at all`);
      }
      if (geometryOf(shifted, moved) !== geometryOf(seamPosable.data, plain)) seamProbes.push('moving the pieces moved the geometry file too, which reads attachments, not pieces');
      seamDetail =
        `${plainPngs.length} frame(s) of the probe rig: a poser relaying spine-core's draws every frame, the framing box and the ` +
        `geometry file byte-identical to the SkeletonData path; one moving every piece one world unit right changes ` +
        `${movedFrames} of ${plainPngs.length} frame(s) and moves the pieces' box by exactly (1, 0) while the geometry file, ` +
        'read off the attachments, stays byte-identical';
    }
  }
  const seamHeld = seamProbes.length === 0;
  say(
    'R16_THE_SAMPLERS_DRAW_WHAT_THE_POSER_HANDS_THEM_AND_NOTHING_ELSE',
    seamHeld,
    probeDetail(seamHeld, seamProbes, seamDetail),
    'issue #965: step 3 of #380 swaps the runtime behind render.ts, and the swap is only a second implementation of ' +
      'one interface if every sampler reads the pose through it. A relay changing no byte is the half that shows the ' +
      'seam costs nothing; a planted poser changing exactly its own pieces is the half that shows the samplers ' +
      'cannot be reading around it',
  );

  const renderText = readFileSync(join(import.meta.dir, 'src', 'render.ts'), 'utf8');
  const sharedText = readFileSync(join(import.meta.dir, 'src', 'render_shared.ts'), 'utf8');
  const cleanScan = seamLeaks(renderText, sharedText);
  const plantedScan = seamLeaks(
    renderText,
    sharedText.replace(/(export function sampleAnimation\([^)]*\)[^{]*\{\n)/, '$1  new Skeleton(poserOf(source) as unknown as SkeletonData);\n'),
  );
  const leakProbes = [
    ...cleanScan.faults,
    ...(cleanScan.names.length > 0 ? [] : ['no spine-core name was read off render.ts\'s import, so the scan looked for nothing']),
    ...(plantedScan.faults.some((f) => f.includes('sampleAnimation') && f.includes('Skeleton'))
      ? []
      : [`a \`new Skeleton(...)\` planted in sampleAnimation's body was read as ${JSON.stringify(plantedScan.faults)}`]),
  ];
  const leakHeld = leakProbes.length === 0;
  say(
    'R17_THE_SAMPLERS_BODIES_NAME_NOTHING_FROM_SPINE_CORE',
    leakHeld,
    probeDetail(
      leakHeld,
      leakProbes,
      `${SEAM_GENERIC.length} function(s) on the generic side of the seam (${SEAM_GENERIC.join(', ')}) name none of the ` +
        `${cleanScan.names.length} identifier(s) render.ts imports from spine-core; a \`new Skeleton(...)\` planted in ` +
        `sampleAnimation's body is named as ${JSON.stringify(plantedScan.faults[0] ?? '')}`,
    ),
    'issue #965: the seam is only a seam while the samplers cannot reach past it. A spine-core call added to a ' +
      'sampler would work, render the same bytes, and leave #968 a rewrite instead of a second implementation — ' +
      'silent in every other control, so it is named here',
  );
  for (const probe of [clipped, bare, ended]) rmSync(probe.dir, { recursive: true, force: true });

  return bad;
}

// ---------------------------------------------------------------------------
// render --geometry (issue #864)
// ---------------------------------------------------------------------------

/**
 * The per-triangle stretch a geometry file was designed for, computed off the
 * parsed file alone: for every mesh in `rest`, each triangle's largest
 * `posed edge / rest edge` over the frames that show it, and the worst one.
 *
 * ⭐ Written here the way a consumer that does not link spine-core would write it
 * — from `docs/AUTHORING.md` §8.5, reading nothing but the file — because that
 * is the claim `render --geometry` makes: the file is enough.
 */
function geometryStretch(file: GeometryFile): {
  ratio: number;
  slot: string;
  attachment: string;
  triangle: number;
  ids: number[];
  frame: number;
  triangles: number;
} {
  let worst = { ratio: -Infinity, slot: '', attachment: '', triangle: -1, ids: [] as number[], frame: -1, triangles: 0 };
  let triangles = 0;
  for (const rest of file.rest) {
    if (rest.kind !== 'mesh') continue;
    triangles += rest.triangles.length / 3;
    for (const frame of file.frames) {
      const posed = frame.attachments.find((a) => a.slot === rest.slot && a.attachment === rest.attachment);
      if (posed === undefined) continue;
      for (let t = 0; t * 3 < rest.triangles.length; t++) {
        const ids = rest.triangles.slice(t * 3, t * 3 + 3);
        let ratio = 0;
        for (const [i, j] of [[0, 1], [1, 2], [2, 0]] as const) {
          const length = (v: number[]): number =>
            Math.hypot(v[ids[j] * 2] - v[ids[i] * 2], v[ids[j] * 2 + 1] - v[ids[i] * 2 + 1]);
          const before = length(rest.vertices);
          if (before > 0) ratio = Math.max(ratio, length(posed.vertices) / before);
        }
        if (ratio > worst.ratio) worst = { ...worst, ratio, slot: rest.slot, attachment: rest.attachment, triangle: t, ids, frame: frame.index };
      }
    }
  }
  return { ...worst, triangles };
}

/** `vertices` carried into `bone`'s own frame: `[a b; c d]⁻¹ · (p − (worldX, worldY))` per vertex. */
function intoBoneFrame(bone: GeometryBone, vertices: number[]): number[] {
  const det = bone.a * bone.d - bone.b * bone.c;
  const out: number[] = [];
  for (let i = 0; i + 1 < vertices.length; i += 2) {
    const dx = vertices[i] - bone.worldX;
    const dy = vertices[i + 1] - bone.worldY;
    out.push((bone.d * dx - bone.b * dy) / det, (-bone.c * dx + bone.a * dy) / det);
  }
  return out;
}

/** The largest coordinate difference between two equal-length arrays, or Infinity when their lengths differ. */
function worstDifference(a: ArrayLike<number>, b: ArrayLike<number>): number {
  if (a.length !== b.length) return Infinity;
  let worst = 0;
  for (let i = 0; i < a.length; i++) worst = Math.max(worst, Math.abs(a[i] - b[i]));
  return worst;
}

/** The largest magnitude in an array — what a float32 rounding bound is scaled by. */
function largestMagnitude(values: ArrayLike<number>): number {
  let most = 0;
  for (let i = 0; i < values.length; i++) most = Math.max(most, Math.abs(values[i]));
  return most;
}

/** A skeleton's geometry file for one animation, exactly as `render --geometry` would print it, read back. */
function geometryOf(data: SkeletonData, animation: string, fps: number, fixed?: Viewport): GeometryFile {
  const viewport = fixed ?? framingViewport(data, 256);
  if (viewport === null) throw new Error('the probe posed nothing to frame');
  const frames = sampleAnimation(data, animation, fps, { bones: true, geometry: true });
  return JSON.parse(geometryText(geometryFileOf(data, animation, fps, frames, viewport, undefined))) as GeometryFile;
}

function runGeometryExportSuite(): number {
  console.log('\n── render --geometry: every frame\'s skinned vertices and bone world transforms (issue #864) ──');
  let bad = 0;
  const say = (name: string, ok: boolean, detail: string, why: string): void => {
    bad += reportCase(name, ok, detail, why);
  };
  const fps = PROTOCOL_FPS;

  // The deform probe: one authored 5x5 grid on a still bone, one yaw key at a
  // time on the frame grid, and the same grid under a run that deforms nothing.
  const KEY_TIME = 0.5;
  const YAW = 12;
  const turn = buildTurnRig([], { time: KEY_TIME, transform: { kind: 'yaw', radius: TURN_R, degrees: YAW } });
  const turnData = skeletonDataFromText(turn.result.skeletonText, turn.result.atlasText);
  const turnFile = geometryOf(turnData, 'turn', fps);
  const keyFrame = turnFile.frames.find((frame) => Math.abs(frame.time - KEY_TIME) < 1e-12);
  const headAt = (entries: AttachmentPose[] | undefined): AttachmentPose | undefined =>
    entries?.find((a) => a.slot === 'head' && a.attachment === 'head');
  const restHead = turnFile.rest.find((r) => r.slot === 'head' && r.attachment === 'head');

  // GY01 — at the key's own time, the export's vertices are the ones the deform survey posed.
  {
    const surveyed = surveyDeformKeys(turnData).keys.find(
      (k) => k.animation === 'turn' && k.slot === 'head' && Math.abs(k.time - KEY_TIME) < 1e-6 && k.moved > 0,
    );
    const posed = headAt(keyFrame?.attachments);
    const probes: string[] = [];
    let displacement = NaN;
    let vertex = -1;
    let stretch = NaN;
    let tolerance = NaN;
    if (keyFrame === undefined) probes.push(`no frame of the ${fps} fps export sits at the key's time ${KEY_TIME}s`);
    if (surveyed === undefined) probes.push(`surveyDeformKeys reported no moving key on head at ${KEY_TIME}s`);
    if (posed === undefined || restHead === undefined) probes.push('the export carries no head/head entry at the key frame or in rest');
    if (keyFrame !== undefined && worstDifference(
      keyFrame.bones.flatMap((b) => [b.a, b.b, b.c, b.d, b.worldX, b.worldY]),
      turnFile.setup.bones.flatMap((b) => [b.a, b.b, b.c, b.d, b.worldX, b.worldY]),
    ) !== 0) {
      probes.push('the bones moved between setup and the key frame, so frame minus rest is not the deform the survey measures');
    }
    if (surveyed !== undefined && posed !== undefined && restHead !== undefined) {
      // The survey poses into Float32Array; the export keeps the runtime's
      // doubles. Each side of a difference is then off by at most half a float32
      // ulp of the largest coordinate, so two of them bound the gap.
      tolerance = 2 * largestMagnitude(posed.vertices) * 2 ** -24;
      for (let v = 0; v * 2 < posed.vertices.length; v++) {
        const d = Math.hypot(posed.vertices[v * 2] - restHead.vertices[v * 2], posed.vertices[v * 2 + 1] - restHead.vertices[v * 2 + 1]);
        if (d > (Number.isNaN(displacement) ? -1 : displacement)) {
          displacement = d;
          vertex = v;
        }
      }
      if (!(Math.abs(displacement - surveyed.maxDisplacement) <= tolerance)) {
        probes.push(`the export's largest displacement is ${displacement} and the survey's ${surveyed.maxDisplacement} (tolerance ${tolerance.toExponential(2)})`);
      }
      // The yaw moves every vertex of one column alike, so the largest
      // displacement is a tie across rows and each side breaks it at whichever
      // vertex its own rounding puts first. What must agree is that the
      // survey's vertex is one of the export's largest.
      const at = surveyed.maxDisplacementVertex;
      const theirs = Math.hypot(posed.vertices[at * 2] - restHead.vertices[at * 2], posed.vertices[at * 2 + 1] - restHead.vertices[at * 2 + 1]);
      if (!(Math.abs(theirs - displacement) <= tolerance)) {
        probes.push(`the survey's most-displaced vertex ${at} moves ${theirs} in the export, not the export's largest ${displacement} (vertex ${vertex})`);
      }
      const extreme = surveyed.stretchMax;
      const sigma = extreme === null ? null : stretchSingularValues(restHead.vertices, posed.vertices, restHead.triangles, extreme.triangle);
      stretch = sigma?.max ?? NaN;
      // The same float32 half-ulps, over the shortest rest edge a singular value divides by.
      const shortest = Math.min(...[...Array(restHead.triangles.length / 3).keys()].flatMap((t) =>
        [[0, 1], [1, 2], [2, 0]].map(([i, j]) => Math.hypot(
          restHead.vertices[restHead.triangles[t * 3 + j] * 2] - restHead.vertices[restHead.triangles[t * 3 + i] * 2],
          restHead.vertices[restHead.triangles[t * 3 + j] * 2 + 1] - restHead.vertices[restHead.triangles[t * 3 + i] * 2 + 1],
        ))));
      const stretchTolerance = (4 * tolerance) / shortest;
      if (extreme === null || !(Math.abs(stretch - extreme.value) <= stretchTolerance)) {
        probes.push(`σ₁ of triangle ${extreme?.triangle ?? '?'} from the export is ${stretch} and the survey's ${extreme?.value ?? 'none'} (tolerance ${stretchTolerance.toExponential(2)})`);
      }
    }
    const held = probes.length === 0;
    say(
      'GY01_AT_A_DEFORM_KEYS_OWN_TIME_THE_EXPORT_HOLDS_THE_VERTICES_THE_DEFORM_SURVEY_POSED',
      held,
      probeDetail(
        held,
        probes,
        `frame ${keyFrame?.index ?? '?'} (t=${keyFrame?.time ?? '?'}s) of the ${fps} fps export against the survey's key ` +
          `at ${KEY_TIME}s: largest displacement ${displacement} at vertex ${vertex} (survey ${surveyed?.maxDisplacement} at ` +
          `${surveyed?.maxDisplacementVertex}, one of the same column's tie), σ₁ ${stretch} (survey ${surveyed?.stretchMax?.value}); tolerance ` +
          `${tolerance.toExponential(2)} = two float32 half-ulps of the largest coordinate, since the survey poses into Float32Array`,
      ),
      'issue #864: the export is posed by the renderer\'s stepping and the survey by a fresh state at the key\'s time — ' +
        'two recipes, so agreement on the frame both claim is what makes either a measurement of the same pose',
    );
  }

  // GY02 — the setup entry is the rest geometry, and every bone composes its parent's world with its own setup local.
  const SETUP_DEGREES = 30;
  const SPIN_DEGREES = 90;
  const spin = ((): { data: SkeletonData; dir: string; build: ReturnType<typeof runCli> } => {
    const dirs = writeProbeRig({
      bones: [
        { name: 'root' },
        { name: 'block', parent: 'root', x: 7, y: -3, rotation: SETUP_DEGREES, scaleX: 1.5, scaleY: 0.8, length: 12 },
      ],
    });
    const motionPath = join(dirs.dir, 'spin.motion.json');
    writeFileSync(
      motionPath,
      `${JSON.stringify({
        spec: 'rigc-motion/1',
        archetype: 'static_probe',
        cut: 'static_probe',
        easings: {},
        animations: {
          spin: { duration: 1, loop: false, tracks: [{ bone: 'block', property: 'rotate', keys: [{ t: 0, v: [0] }, { t: 1, v: [SPIN_DEGREES] }] }] },
        },
      }, null, 2)}\n`,
    );
    const build = runCli(['build', '--rig', dirs.rigPath, '--motion', motionPath, '--images', dirs.dir, '--out', dirs.outDir]);
    const posable = build.status === 0 ? loadPosable(join(dirs.outDir, 'skeleton.json'), join(dirs.outDir, 'skeleton.atlas'), dirs.outDir) : null;
    return { data: posable?.data ?? turnData, dir: dirs.dir, build };
  })();
  {
    const probes: string[] = [];
    if (spin.build.status !== 0) probes.push(`the spin probe did not build (exit ${String(spin.build.status)}): ${spin.build.stderr.trim().slice(0, 200)}`);
    const spinFile = geometryOf(spin.data, spin.build.status === 0 ? 'spin' : 'turn', fps);
    let composed = 0;
    let worstCompose = 0;
    for (const file of [turnFile, spinFile]) {
      for (const shown of file.setup.attachments) {
        const rest = file.rest.find((r) => r.slot === shown.slot && r.attachment === shown.attachment);
        if (rest === undefined || worstDifference(rest.vertices, shown.vertices) !== 0) {
          probes.push(`${file.animation}: setup's ${shown.slot}/${shown.attachment} is ${rest === undefined ? 'missing from rest' : 'not bit-identical to its rest entry'}`);
        }
      }
      const data = file === turnFile ? turnData : spin.data;
      for (const declared of file.bones) {
        const world = file.setup.bones.find((b) => b.name === declared.name);
        const bone = data.findBone(declared.name)?.setupPose ?? null;
        if (world === undefined || bone === null) {
          probes.push(`${file.animation}: bone ${declared.name} has no setup entry`);
          continue;
        }
        // An `inherit: normal` bone's local matrix, written out from its setup
        // fields rather than read off its world. Through the runtime's own
        // `cosDeg`/`sinDeg`: its degree-to-radian factor is built on
        // `MathUtils.PI = 3.1415927`, so `cos 90°` is -2.3e-8 there and not 0,
        // and a control on `Math.PI` would measure that constant, not the
        // composition.
        const la = MathUtils.cosDeg(bone.rotation + bone.shearX) * bone.scaleX;
        const lb = MathUtils.cosDeg(bone.rotation + 90 + bone.shearY) * bone.scaleY;
        const lc = MathUtils.sinDeg(bone.rotation + bone.shearX) * bone.scaleX;
        const ld = MathUtils.sinDeg(bone.rotation + 90 + bone.shearY) * bone.scaleY;
        const parent = declared.parent === null ? null : file.setup.bones.find((b) => b.name === declared.parent);
        const p = parent ?? { a: 1, b: 0, c: 0, d: 1, worldX: 0, worldY: 0 };
        const expected = [
          p.a * la + p.b * lc, p.a * lb + p.b * ld, p.c * la + p.d * lc, p.c * lb + p.d * ld,
          p.a * bone.x + p.b * bone.y + p.worldX, p.c * bone.x + p.d * bone.y + p.worldY,
        ];
        const gap = worstDifference(expected, [world.a, world.b, world.c, world.d, world.worldX, world.worldY]);
        composed++;
        worstCompose = Math.max(worstCompose, gap);
        if (!(gap <= 1e-9)) probes.push(`${file.animation}: bone ${declared.name}'s world is ${gap.toExponential(2)} from its parent's world times its setup local`);
      }
    }
    // The turn grid's rest, against the rig spec's own vertices carried by the
    // head bone's setup world transform — an unweighted mesh's vertices are in
    // its slot bone's space. Beside it, how far that is from the naive
    // "spec plus (400, 400)", which is the runtime's cos 90° again.
    const headSetup = turnFile.setup.bones.find((b) => b.name === 'head');
    const specLocal = TURN_ORDER.flatMap((id) => [TURN_COLUMNS[id % TURN_COLUMNS.length], TURN_ROWS[Math.floor(id / TURN_COLUMNS.length)]]);
    const specRest = headSetup === undefined ? [] : specLocal.flatMap((value, i) => i % 2 === 1 ? [] : [
      headSetup.a * value + headSetup.b * specLocal[i + 1] + headSetup.worldX,
      headSetup.c * value + headSetup.d * specLocal[i + 1] + headSetup.worldY,
    ]);
    const specGap = restHead === undefined ? Infinity : worstDifference(restHead.vertices, specRest);
    const naiveGap = restHead === undefined ? Infinity : worstDifference(restHead.vertices, specLocal.map((value) => value + 400));
    if (!(specGap <= 1e-9)) probes.push(`the turn grid's rest vertices are ${specGap} from the rig spec's vertices under the head bone's setup world transform`);
    // An attachment the setup pose does not show still gets a rest entry: the
    // head slot swaps to a region a quarter of the way in and back.
    const swapped = buildTurnRig([], {
      deformKeys: [{ t: 0 }, { t: 1 }],
      swapTo: 'away',
      tracks: [{ slot: 'head', property: 'attachment', keys: [{ t: 0, v: 'head' }, { t: 0.25, v: 'away' }, { t: 0.75, v: 'head' }] }],
    });
    const swapFile = geometryOf(skeletonDataFromText(swapped.result.skeletonText, swapped.result.atlasText), 'turn', fps);
    const awayRest = swapFile.rest.find((r) => r.slot === 'head' && r.attachment === 'away');
    const awayFrames = swapFile.frames.flatMap((f) => f.attachments.filter((a) => a.slot === 'head' && a.attachment === 'away'));
    if (swapFile.setup.attachments.some((a) => a.attachment === 'away')) probes.push('the swap probe shows "away" at setup, so its rest entry proves nothing');
    if (awayRest === undefined || awayRest.kind !== 'region' || awayFrames.length === 0) {
      probes.push(`the swap probe's rest ${awayRest === undefined ? 'has no' : `has a ${awayRest.kind}`} "away" entry over ${awayFrames.length} frame(s) that show it`);
    } else if (awayFrames.some((a) => worstDifference(a.vertices, awayRest.vertices) !== 0)) {
      probes.push('"away" sits on a still bone and is rigid, yet a frame\'s corners are not its rest corners bit for bit');
    }
    rmSync(swapped.dir, { recursive: true, force: true });
    const blockSetup = spinFile.setup.bones.find((b) => b.name === 'block');
    // 1e-6°: the runtime's π is 3.1415927, 1.5e-8 relative off, which is 4.4e-7° at 30°.
    if (blockSetup === undefined || Math.abs(Math.atan2(blockSetup.c, blockSetup.a) / (Math.PI / 180) - SETUP_DEGREES) > 1e-6) {
      probes.push('the spin probe\'s block bone does not sit at its 30° setup rotation, so the composition was checked on a trivial matrix');
    }
    const held = probes.length === 0;
    say(
      'GY02_THE_SETUP_ENTRY_IS_THE_REST_GEOMETRY_AND_EVERY_BONE_COMPOSES_ITS_PARENTS_WORLD_WITH_ITS_LOCAL',
      held,
      probeDetail(
        held,
        probes,
        `every attachment the setup pose shows is bit-identical to its rest entry on both probes, and a region the setup ` +
          `pose does not show has one too, equal to the ${awayFrames.length} frame(s) that swap to it; the turn grid's rest is ` +
          `the rig spec's ${TURN_ORDER.length} vertices under the head bone's world transform to ${specGap.toExponential(2)} ` +
          `(and ${naiveGap.toExponential(2)} from the spec plus (400, 400), since the runtime's cos 90° is ` +
          `${MathUtils.cosDeg(90).toExponential(2)}); ${composed} bone(s) — one at ${SETUP_DEGREES}°, x1.5/x0.8, offset (7, -3) — ` +
          `compose parent·local to ${worstCompose.toExponential(2)} (tolerance 1e-9)`,
      ),
      'a stretch ratio divides by the rest edge and a bone frame inverts the world matrix, so a rest that is not the ' +
        'setup pose or a world transform that is not the parent\'s times the local would make both formulas measure a pose nobody authored',
    );

    // GY03 — a region on a rotating bone is exactly still in that bone's frame.
    const stillProbes: string[] = [];
    let residual = 0;
    let travelled = 0;
    let turned = 0;
    const markerRest = spinFile.rest.find((r) => r.slot === 'marker');
    const boneOf = spinFile.slots.find((s) => s.name === 'marker')?.bone;
    const reference = boneOf === undefined || markerRest === undefined
      ? null
      : intoBoneFrame(spinFile.setup.bones.find((b) => b.name === boneOf) ?? spinFile.setup.bones[0], markerRest.vertices);
    for (const frame of spinFile.frames) {
      const bone = frame.bones.find((b) => b.name === boneOf);
      const marker = frame.attachments.find((a) => a.slot === 'marker');
      if (bone === undefined || marker === undefined || reference === null || markerRest === undefined) continue;
      residual = Math.max(residual, worstDifference(intoBoneFrame(bone, marker.vertices), reference));
      travelled = Math.max(travelled, worstDifference(marker.vertices, markerRest.vertices));
      turned = Math.max(turned, Math.abs(Math.atan2(bone.c, bone.a) - Math.atan2(spinFile.setup.bones.find((b) => b.name === boneOf)?.c ?? 0, spinFile.setup.bones.find((b) => b.name === boneOf)?.a ?? 1)) / (Math.PI / 180));
    }
    const STILL = 1e-9;
    if (reference === null) stillProbes.push('the spin export carries no marker region, or no slot table entry naming its bone');
    if (boneOf !== 'block') stillProbes.push(`the slot table hangs marker from ${String(boneOf)} rather than the rig spec's "block"`);
    if (!(residual <= STILL)) stillProbes.push(`marker's corners move ${residual.toExponential(2)} in block's own frame across the spin (tolerance ${STILL})`);
    stillProbes.push(...floorProbes(
      [[travelled, 1, `marker's corners travel ${travelled} world units across the spin`], [turned, SPIN_DEGREES - 1e-6, `block turns ${turned}° across the spin, keyed to ${SPIN_DEGREES}°`]],
      'so being still in the bone frame would be true of a region that never moved',
    ));
    const stillHeld = stillProbes.length === 0;
    say(
      'GY03_A_REGION_ON_A_ROTATING_BONE_IS_STILL_IN_THAT_BONES_OWN_FRAME',
      stillHeld,
      probeDetail(
        stillHeld,
        stillProbes,
        `block turns ${turned.toFixed(3)}° over ${spinFile.frames.length} frames and marker's corners travel ` +
          `${travelled.toFixed(3)} world units; carried by the inverse of block's world transform they move ` +
          `${residual.toExponential(2)} (tolerance ${STILL}, far above double rounding and far below a pixel)`,
      ),
      'issue #864 (b): a face read in the head\'s frame is the second judgement the export exists for, and it is the ' +
        'inverse of a world transform applied to a region\'s corners — which has to hold exactly where nothing but the bone moved',
    );
  }

  // GY04 — two exports are byte-identical, and --geometry changes no other file.
  {
    const work = buildRootIn(turn.dir, 'rigc-geometry-');
    const candidate = join(work, 'turn');
    const built = runCli(['build', '--rig', turn.opts.rigPath, '--motion', turn.opts.motionPath, '--images', turn.opts.imagesDir ?? turn.dir, '--out', candidate]);
    const renderInto = (name: string, extra: string[]): ReturnType<typeof runCli> =>
      runCli(['render', '--candidate', candidate, ...extra, '--out', join(work, name)]);
    const first = renderInto('first', ['--geometry']);
    const second = renderInto('second', ['--geometry']);
    const plain = renderInto('plain', []);
    const filesOf = (name: string): string[] =>
      existsSync(join(work, name))
        ? readdirSync(join(work, name), { recursive: true }).map(String).filter((f) => statSync(join(work, name, f)).isFile()).sort()
        : [];
    const probes: string[] = [];
    for (const [label, run] of [['build', built], ['first', first], ['second', second], ['plain', plain]] as const) {
      if (run.status !== 0) probes.push(`${label} exited ${String(run.status)}: ${(run.stderr || run.stdout).trim().slice(0, 200)}`);
    }
    const geometryFiles = filesOf('first').filter((f) => basename(f) === GEOMETRY_FILE);
    const differing = filesOf('first').filter((f) => !existsSync(join(work, 'second', f)) || !readFileSync(join(work, 'first', f)).equals(readFileSync(join(work, 'second', f))));
    if (differing.length > 0) probes.push(`two --geometry runs differ in ${differing.join(', ')}`);
    const others = filesOf('first').filter((f) => basename(f) !== GEOMETRY_FILE);
    const moved = others.filter((f) => !existsSync(join(work, 'plain', f)) || !readFileSync(join(work, 'first', f)).equals(readFileSync(join(work, 'plain', f))));
    if (moved.length > 0) probes.push(`--geometry changed ${moved.join(', ')} against a plain render`);
    if (filesOf('plain').length !== others.length) probes.push(`a plain render wrote ${filesOf('plain').length} file(s) and a --geometry render ${others.length} beside its geometry`);
    const written = geometryFiles.length === 0 ? null : (JSON.parse(readFileSync(join(work, 'first', geometryFiles[0]), 'utf8')) as GeometryFile);
    const sidecar = existsSync(join(work, 'first', FRAMES_SIDECAR))
      ? (JSON.parse(readFileSync(join(work, 'first', FRAMES_SIDECAR), 'utf8')) as FramesSidecar)
      : null;
    if (written === null || sidecar === null) probes.push(`the --geometry run wrote ${geometryFiles.length} ${GEOMETRY_FILE} and ${sidecar === null ? 'no' : 'a'} ${FRAMES_SIDECAR}`);
    else {
      if (JSON.stringify(written.viewport) !== JSON.stringify(sidecar.viewport)) probes.push(`${GEOMETRY_FILE}'s viewport ${JSON.stringify(written.viewport)} is not ${FRAMES_SIDECAR}'s ${JSON.stringify(sidecar.viewport)}`);
      const pngs = filesOf('first').filter((f) => dirname(f) === dirname(geometryFiles[0]) && /^f\d{4}\.png$/.test(basename(f))).length;
      if (written.frames.length !== pngs) probes.push(`${GEOMETRY_FILE} carries ${written.frames.length} frame(s) beside ${pngs} PNG(s)`);
      if (written.spec !== GEOMETRY_SPEC || written.coordinates !== GEOMETRY_COORDINATES) probes.push(`the header says spec ${written.spec}, coordinates ${written.coordinates}`);
      if (JSON.stringify(written) !== JSON.stringify(turnFile)) probes.push(`the CLI's ${GEOMETRY_FILE} is not the library's geometryFileOf for the same skeleton`);
    }
    const held = probes.length === 0;
    say(
      'GY04_TWO_GEOMETRY_EXPORTS_ARE_BYTE_IDENTICAL_AND_CHANGE_NO_OTHER_FILE',
      held,
      probeDetail(
        held,
        probes,
        `two \`render --geometry\` runs agree byte for byte over ${filesOf('first').length} file(s); the ${others.length} ` +
          `beside ${GEOMETRY_FILE} are the plain render's bytes; its viewport is ${FRAMES_SIDECAR}'s and it carries one ` +
          `frame per PNG (${written?.frames.length ?? 0})`,
      ),
      'A18\'s contract, extended to the export: a consumer diffs two geometry files to find what moved, and a file ' +
        'that differed run to run would report motion that is not there — while a flag that nudged the pictures would change the frames it describes',
    );

    // GY05 — an unknown animation is refused by name on the export path too.
    const unknown = renderInto('unknown', ['--geometry', '--animation', 'no-such-take']);
    const unknownHeld =
      unknown.status === 2 &&
      unknown.stderr.includes('no animation "no-such-take" in this skeleton; it has [turn]') &&
      filesOf('unknown').length === 0;
    say(
      'GY05_AN_UNKNOWN_ANIMATION_IS_REFUSED_BY_NAME_ON_THE_GEOMETRY_PATH_AND_NOTHING_IS_WRITTEN',
      unknownHeld,
      `exit ${String(unknown.status)}, ${filesOf('unknown').length} file(s) written: ${JSON.stringify(unknown.stderr.split('\n')[0])}`,
      'the export is the same command as the pictures, so it must fail the same way — a geometry file for an animation ' +
        'nobody asked for is a set of numbers about the wrong take',
    );

    // GY06 — a slot subset and the export are refused together.
    const subsetProbes: string[] = [];
    for (const [flag, value] of [['--slot', 'head'], ['--hide', 'head']] as const) {
      const run = renderInto(`subset${flag}`, ['--geometry', flag, value]);
      if (run.status !== 2 || !run.stderr.includes(`--geometry takes no ${flag}`) || filesOf(`subset${flag}`).length > 0) {
        subsetProbes.push(`--geometry ${flag} ${value} exited ${String(run.status)} writing ${filesOf(`subset${flag}`).length} file(s): ${JSON.stringify(run.stderr.split('\n')[0])}`);
      }
    }
    const subsetAlone = renderInto('subset-alone', ['--slot', 'head']);
    if (subsetAlone.status !== 0) subsetProbes.push(`--slot head without --geometry exited ${String(subsetAlone.status)}, so the refusal is not the pairing's`);
    const subsetHeld = subsetProbes.length === 0;
    say(
      'GY06_GEOMETRY_WITH_A_SLOT_SUBSET_IS_REFUSED_BY_NAME_AND_WRITES_NOTHING',
      subsetHeld,
      probeDetail(
        subsetHeld,
        subsetProbes,
        '--geometry with --slot and with --hide each exit 2 naming the pair and write nothing; --slot head alone renders',
      ),
      'the geometry is the whole pose whatever a picture leaves out, so beside a subset\'s frames it would describe ' +
        'slots those frames do not draw — refused rather than written, since the whole-rig run writes the same file',
    );
    rmSync(work, { recursive: true, force: true });
  }

  // GY07 — the stretch formula, off the file alone: the closed form on the yawed grid, exactly 1 where nothing deforms.
  {
    const ratios = columnRatios(turnShifts(YAW));
    const expected = Math.max(1, ...ratios);
    const widest = ratios.indexOf(Math.max(...ratios));
    const measured = geometryStretch(turnFile);
    const flat = buildTurnRig([], { deformKeys: [{ t: 0 }, { t: 1 }] });
    const flatFile = geometryOf(skeletonDataFromText(flat.result.skeletonText, flat.result.atlasText), 'turn', fps);
    const still = geometryStretch(flatFile);
    const columns = measured.ids.map((v) => turnColumn(v));
    const probes: string[] = [];
    if (!(Math.abs(measured.ratio - expected) < 1e-5)) probes.push(`the worst ratio is ${measured.ratio} where the closed form gives ${expected}`);
    if (!(expected > 1)) probes.push(`the closed form's widest column pair scales by ${expected}, so a stretch of 1 would pass`);
    if (Math.min(...columns) !== widest || Math.max(...columns) !== widest + 1) {
      probes.push(`the worst triangle ${measured.triangle} [${measured.ids.join(', ')}] spans columns ${columns.join(', ')}, not the widened pair ${widest}–${widest + 1}`);
    }
    if (measured.frame !== keyFrame?.index) probes.push(`the worst frame is ${measured.frame}, not the key's frame ${keyFrame?.index ?? '?'}`);
    if (still.ratio !== 1) probes.push(`an animation that deforms nothing reads ${still.ratio} rather than exactly 1`);
    if (measured.triangles === 0 || still.triangles === 0) probes.push(`the rest tables carry ${measured.triangles} and ${still.triangles} mesh triangle(s)`);
    rmSync(flat.dir, { recursive: true, force: true });
    const held = probes.length === 0;
    say(
      'GY07_THE_STRETCH_FORMULA_OFF_THE_FILE_READS_THE_CLOSED_FORM_AND_EXACTLY_ONE_WHERE_NOTHING_DEFORMS',
      held,
      probeDetail(
        held,
        probes,
        `a ${YAW}° yaw widens column pair ${widest}–${widest + 1} by x${expected.toFixed(6)}; the file alone names ` +
          `${measured.slot}/${measured.attachment} triangle ${measured.triangle} [${measured.ids.join(', ')}] at frame ` +
          `${measured.frame}, ratio x${measured.ratio.toFixed(6)} (tolerance 1e-5, the float32 offsets); the same grid ` +
          `under keys that deform nothing reads x${still.ratio} over ${still.triangles} triangle(s)`,
      ),
      'rig-parts #31 reads texture stretch off this file and nothing else, so the formula AUTHORING §8 states has to ' +
        'find the triangle a closed form predicts and say exactly 1 where the pose never moved a vertex',
    );
  }

  // GY08 — a number the file cannot hold is refused by name, before anything is written.
  {
    const planted = turn.result.skeletonText.replace(/"x":\s*400/, '"x": 1e309');
    const probes: string[] = [];
    if (planted === turn.result.skeletonText) probes.push('the plant found no `"x": 400` to replace, so nothing was broken');
    let refused = '';
    try {
      // A box of its own: framing an infinite pose refuses it itself (issue
      // #873, GY09), and the refusal under test is the export's, not the framing's.
      geometryOf(skeletonDataFromText(planted, turn.result.atlasText), 'turn', fps, viewportFor(0, 0, 1, 1, 256));
    } catch (err) {
      refused = err instanceof GeometryError ? err.message : `not a GeometryError: ${(err as Error).message}`;
    }
    if (!/slot "head" attachment "head" vertex \d+ has x Infinity/.test(refused) && !/bone "head" has worldX Infinity/.test(refused)) {
      probes.push(`the planted infinity was answered ${JSON.stringify(refused || 'with a file')}`);
    }
    const held = probes.length === 0;
    say(
      'GY08_A_POSE_THAT_IS_NOT_FINITE_IS_REFUSED_BY_NAME_RATHER_THAN_WRITTEN_AS_NULL',
      held,
      probeDetail(held, probes, `a head bone at x=1e309 is refused: ${JSON.stringify(refused)}; the unplanted skeleton exports (GY01, GY07)`),
      'JSON.stringify writes NaN and Infinity as null, and a consumer reading null as a coordinate measures a hole ' +
        'as geometry — the silence this repository converts into a named failure',
    );
  }

  // --- GY09–GY13: a pose that is not finite, through the CLI (issue #873) ---
  // Before #873 `framingViewport` answered `null` for an overflow as it does for
  // a skeleton that draws nothing, so `render` printed "posed no drawable
  // attachment" over an attachment that was there, and GY08's sentence was
  // reachable only through the library. One bone overflowing beside finite ones
  // reached neither: its box was finite on one side and `render` wrote a
  // NaN-by-NaN frame set with exit 0. Each plant below is the emitted file with
  // one number edited, the way GY08 plants it — the rig spec route is not used,
  // because a motion key of 1e309 is refused by the compiler by name.
  {
    const work = buildRootIn(turn.dir, 'rigc-nonfinite-');
    const candidate = join(work, 'turn');
    const built = runCli(['build', '--rig', turn.opts.rigPath, '--motion', turn.opts.motionPath, '--images', turn.opts.imagesDir ?? turn.dir, '--out', candidate]);
    const skeletonPath = join(candidate, 'skeleton.json');
    const emitted = built.status === 0 && existsSync(skeletonPath) ? readFileSync(skeletonPath, 'utf8') : '';
    // A string no emitted file carries, swapped for a literal JSON reads as Infinity.
    const OVERFLOW = '__rigc_overflow__';
    type Emitted = {
      bones: Array<Record<string, unknown>>;
      slots: Array<Record<string, unknown>>;
      skins: Array<{ name: string; attachments: Record<string, unknown> }>;
      animations: Record<string, { bones?: Record<string, Record<string, unknown>> }>;
    };
    const plant = (name: string, edit: (skeleton: Emitted) => void): string => {
      const dir = join(work, name);
      mkdirSync(dir, { recursive: true });
      for (const file of existsSync(candidate) ? readdirSync(candidate) : []) {
        if (file !== 'skeleton.json') writeFileSync(join(dir, file), readFileSync(join(candidate, file)));
      }
      const skeleton = JSON.parse(emitted) as Emitted;
      edit(skeleton);
      writeFileSync(join(dir, 'skeleton.json'), JSON.stringify(skeleton, null, 2).replaceAll(`"${OVERFLOW}"`, '1e309'));
      return dir;
    };
    const boneNamed = (skeleton: Emitted, name: string): Record<string, unknown> => {
      const bone = skeleton.bones.find((b) => b.name === name);
      if (bone === undefined) throw new Error(`the turn probe emits no bone "${name}"`);
      return bone;
    };
    const setupPlant = plant('setup', (sk) => {
      boneNamed(sk, 'head').x = OVERFLOW;
    });
    // A second bone carrying a copy of the head mesh, at +1e309, beside the finite head.
    const strayPlant = plant('stray', (sk) => {
      sk.bones.push({ name: 'stray', parent: 'root', x: OVERFLOW, y: 0 });
      sk.slots.push({ name: 'stray', bone: 'stray', attachment: 'head' });
      const skin = sk.skins.find((k) => k.name === 'default');
      if (skin !== undefined) skin.attachments.stray = skin.attachments.head;
    });
    // A rotate key that overflows half a framing step after the deform key, with
    // every frame before it finite. Off the grid on purpose: the sampler reaches
    // a frame by adding its step, and 30 steps of 1/60 land a hair under 0.5 —
    // measured, a key AT 0.5 was first non-finite at frame 31, not 30.
    const KEY_AT = KEY_TIME + 1 / (2 * FRAMING_FPS);
    const keyPlant = plant('key', (sk) => {
      const bones = (sk.animations.turn.bones ??= {});
      bones.head = { ...(bones.head ?? {}), rotate: [{ time: KEY_AT, value: OVERFLOW }] };
    });
    const emptyPlant = plant('empty', (sk) => {
      for (const slot of sk.slots) delete slot.attachment;
    });
    const refusalOf = (run: ReturnType<typeof runCli>): string =>
      run.stderr.split('\n').find((line) => line.startsWith('rigc render: '))?.slice('rigc render: '.length) ?? '';
    const filesUnder = (dir: string): string[] =>
      existsSync(dir) ? readdirSync(dir, { recursive: true }).map(String).filter((f) => statSync(join(dir, f)).isFile()).sort() : [];
    const renderOf = (dir: string, out: string, extra: string[] = []): ReturnType<typeof runCli> =>
      runCli(['render', '--candidate', dir, ...extra, '--out', join(work, out)]);
    // The library's own sentence for the same file, at the framing's rate and on a box of its own.
    const exportSays = (dir: string, fpsFor: number): string => {
      try {
        const data = skeletonDataFromText(readFileSync(join(dir, 'skeleton.json'), 'utf8'), readFileSync(join(dir, 'skeleton.atlas'), 'utf8'));
        geometryOf(data, 'turn', fpsFor, viewportFor(0, 0, 1, 1, 256));
        return '';
      } catch (err) {
        return err instanceof GeometryError ? err.message : `not a GeometryError: ${(err as Error).message}`;
      }
    };
    const buildProbe = built.status === 0 && emitted !== '' ? [] : [`the turn probe did not build: exit ${String(built.status)}`];

    // GY09 — the whole rig at 1e309: refused by the bone and its value, nothing written.
    {
      const run = renderOf(setupPlant, 'out-setup');
      const said = refusalOf(run);
      const probes = [...buildProbe];
      if (run.status !== 1) probes.push(`render exited ${String(run.status)}, not 1 (the exit a GeometryError takes)`);
      if (!said.includes('bone "head" has worldX Infinity')) probes.push(`render said ${JSON.stringify(said || run.stderr.trim().slice(0, 200))}`);
      if (run.stderr.includes('posed no drawable attachment')) probes.push('render still said "posed no drawable attachment" over an attachment that is there');
      const written = filesUnder(join(work, 'out-setup'));
      if (written.length > 0) probes.push(`render wrote ${written.length} file(s): ${written.slice(0, 3).join(', ')}`);
      const held = probes.length === 0;
      say(
        'RF89_A_RIG_POSED_TO_INFINITY_IS_REFUSED_BY_THE_BONE_AND_ITS_VALUE_NOT_AS_NOTHING_TO_DRAW',
        held,
        probeDetail(held, probes, `head bone at x=1e309: exit ${String(run.status)}, ${JSON.stringify(said)}; nothing written`),
        'issue #873: the framing answered null for an overflow as for an empty skeleton, so render sent an agent ' +
          'looking for a missing attachment when the attachment was there and posed to a number no box can hold',
      );
    }

    // GY10 — one bone at 1e309 beside a finite one: refused, where it once wrote NaN-sized frames with exit 0.
    {
      const run = renderOf(strayPlant, 'out-stray');
      const said = refusalOf(run);
      const probes = [...buildProbe];
      if (run.status !== 1) probes.push(`render exited ${String(run.status)}, not 1`);
      if (!said.includes('bone "stray" has worldX Infinity')) probes.push(`render said ${JSON.stringify(said || run.stderr.trim().slice(0, 200))}`);
      if (run.stdout.includes('NaN')) probes.push(`render printed NaN on stdout: ${JSON.stringify(run.stdout.split('\n').find((l) => l.includes('NaN')))}`);
      const written = filesUnder(join(work, 'out-stray'));
      if (written.length > 0) probes.push(`render wrote ${written.length} file(s), frames and contact sheet among them: ${written.slice(0, 3).join(', ')}`);
      const held = probes.length === 0;
      say(
        'RF90_ONE_BONE_AT_INFINITY_BESIDE_FINITE_ONES_IS_REFUSED_RATHER_THAN_FRAMED_AT_NAN_BY_NAN',
        held,
        probeDetail(held, probes, `a stray bone at x=1e309 carrying a copy of the head mesh: exit ${String(run.status)}, ${JSON.stringify(said)}; nothing written`),
        'issue #873, measured before the change: the union box was finite on its minimum and Infinity on its ' +
          'maximum, which the null test did not read, and render wrote 13 frames and a contact sheet at NaNxNaN px with exit 0',
      );
    }

    // GY11 — the positive control: a skeleton that draws nothing keeps its own sentence and exit.
    {
      const run = renderOf(emptyPlant, 'out-empty');
      const probes = [...buildProbe];
      if (run.status !== 2) probes.push(`render exited ${String(run.status)}, not 2 (the UsageError exit)`);
      if (!run.stderr.includes('posed no drawable attachment in any animation or in its setup pose')) {
        probes.push(`render said ${JSON.stringify(run.stderr.trim().split('\n').slice(0, 3).join(' | '))}`);
      }
      if (refusalOf(run) !== '') probes.push(`an empty skeleton was refused as an overflow: ${JSON.stringify(refusalOf(run))}`);
      const held = probes.length === 0;
      say(
        'RF91_A_SKELETON_THAT_DRAWS_NOTHING_STILL_SAYS_POSED_NO_DRAWABLE_ATTACHMENT',
        held,
        probeDetail(held, probes, `every slot's setup attachment removed: exit ${String(run.status)}, "posed no drawable attachment"`),
        'issue #873: the empty case is the one the sentence is true of, and tools/editor_roundtrip.ts reads it — with ' +
          'exit 2 — as the SKIP for a rig with no picture, so it must not move while the overflow leaves it',
      );
    }

    // GY12 — check, with the planted file as its candidate, names the same fault.
    {
      const frames = join(work, 'frames');
      const reference = runCli(['render', '--candidate', candidate, '--out', frames]);
      const runs = [
        ['setup', setupPlant, 'bone "head" has worldX Infinity'],
        ['stray', strayPlant, 'bone "stray" has worldX Infinity'],
        ['key', keyPlant, 'bone "head" has a NaN'],
      ] as const;
      const probes = [...buildProbe];
      if (reference.status !== 0) probes.push(`the reference render exited ${String(reference.status)}`);
      const seen: string[] = [];
      for (const [label, dir, fault] of runs) {
        const run = runCli(['check', '--candidate', dir, '--frames', frames]);
        const line = run.stderr.split('\n').find((l) => l.startsWith('rigc check error: ')) ?? '';
        const lead = 'rigc check error: the candidate is posed to a number that is not finite, so no frame of it can be compared: ';
        const sentence = line.startsWith(lead) ? line.slice(lead.length) : '';
        seen.push(`${label}: exit ${String(run.status)} ${JSON.stringify(sentence)}`);
        if (run.status !== 1) probes.push(`${label}: check exited ${String(run.status)}, not 1`);
        if (!sentence.includes(fault)) probes.push(`${label}: check said ${JSON.stringify(line || run.stdout.trim().slice(0, 200))}`);
        // The same derivation at check's own rate: the frames' fps, not the framing's.
        const exported = exportSays(dir, PROTOCOL_FPS);
        if (sentence !== exported) probes.push(`${label}: check's sentence ${JSON.stringify(sentence)} is not the export's at ${PROTOCOL_FPS} fps ${JSON.stringify(exported)}`);
      }
      const held = probes.length === 0;
      say(
        'RF92_CHECK_REFUSES_A_CANDIDATE_POSED_TO_INFINITY_IN_THE_EXPORTS_OWN_SENTENCE',
        held,
        probeDetail(held, probes, seen.join('; ')),
        'issue #873, measured before the change on a planted candidate: an overflowing root read "posed no drawable ' +
          'attachment", and an overflowing leaf or a rotation at 1e309 exited 0 with the part missing from every frame',
      );
    }

    // GY13 — one sentence: render, render --geometry and the library export agree to the byte, twice.
    {
      const probes = [...buildProbe];
      const seen: string[] = [];
      for (const [label, dir] of [['setup', setupPlant], ['stray', strayPlant], ['key', keyPlant]] as const) {
        const plain = refusalOf(renderOf(dir, `rf93-${label}-plain`));
        const again = refusalOf(renderOf(dir, `rf93-${label}-again`));
        const geometry = refusalOf(renderOf(dir, `rf93-${label}-geometry`, ['--geometry']));
        const exported = exportSays(dir, FRAMING_FPS);
        seen.push(`${label}: ${JSON.stringify(plain)}`);
        if (plain === '') probes.push(`${label}: render refused nothing`);
        if (plain !== again) probes.push(`${label}: two runs said ${JSON.stringify(plain)} and ${JSON.stringify(again)}`);
        if (plain !== geometry) probes.push(`${label}: render said ${JSON.stringify(plain)} and render --geometry ${JSON.stringify(geometry)}`);
        if (plain !== exported) probes.push(`${label}: render said ${JSON.stringify(plain)} and the export at ${FRAMING_FPS} fps ${JSON.stringify(exported)}`);
      }
      // The key plant must be found at its own key, not at frame 0: the frames before it are finite.
      const keyed = refusalOf(renderOf(keyPlant, 'rf93-key-where'));
      const firstBad = Math.ceil(KEY_AT * FRAMING_FPS);
      const at = `animation "turn" frame ${firstBad} at ${FRAMING_FPS} fps (t=${(firstBad / FRAMING_FPS).toFixed(4)}s)`;
      if (!keyed.startsWith(`${at}: `)) probes.push(`the key plant was placed at ${JSON.stringify(keyed.split(':')[0])}, not ${JSON.stringify(at)}`);
      const held = probes.length === 0;
      say(
        'RF93_RENDER_RENDER_GEOMETRY_AND_THE_EXPORT_REFUSE_ONE_OVERFLOW_IN_ONE_SENTENCE_EVERY_RUN',
        held,
        probeDetail(held, probes, seen.join('; ')),
        'issue #873: the sentence has one derivation (`nonFiniteSentence`), and holding the three callers equal on ' +
          'three plants — a setup bone, a leaf beside finite bones, a key — is what stops a second one from forking off',
      );
    }
    rmSync(work, { recursive: true, force: true });
  }

  // --- GY14–GY19: a pose whose every drawn vertex sits at one point (issue #997) ---
  // Measured on main before the change, through both posers: a rig whose one
  // drawn slot hangs from a `skin: true` bone that only a non-default skin names,
  // rendered with no --skin, drew that slot through the zero matrix — all eight
  // corner numbers 0 — so the framing box was the one point (0, 0), finite, and
  // not null. `maxSide / 0` gave a scale of Infinity, `0 · Infinity` a width of
  // NaN, and render printed "NaNxNaNpx", wrote 0x0 PNGs and a frames.json
  // viewport of width 0 and scale null, and exited 0. A static rig whose one bone
  // is scaled to 0 reached the same file by the other road: every vertex at the
  // bone's origin. The rigs are built through the rig spec, so both posers run.
  {
    const work = mkdtempSync(join(harnessTemp(), 'rigc-unframeable-'));
    const oneSlot = [{ name: 'block', bone: 'block', attachment: 'block' }];
    const defaultSkin = { block: { block: { image: 'block.png' } } };
    const unposedRig = writeProbeRig({
      bones: [{ name: 'root' }, { name: 'block', parent: 'root', x: 0, y: 0, length: 12, skin: true }],
      slots: oneSlot,
      skins: { default: defaultSkin, extra: { bones: ['block'], attachments: {} } },
    });
    // The same picture with the bone posed under every skin — check's reference frames.
    const posedRig = writeProbeRig({
      bones: [{ name: 'root' }, { name: 'block', parent: 'root', x: 0, y: 0, length: 12 }],
      slots: oneSlot,
      skins: { default: defaultSkin },
    });
    const collapsedRig = writeProbeRig({
      bones: [{ name: 'root' }, { name: 'block', parent: 'root', x: 10, y: 5, length: 12, scaleX: 0, scaleY: 0 }],
      slots: oneSlot,
      skins: { default: defaultSkin },
    });
    const slide = {
      slide: { duration: 1, loop: false, tracks: [{ bone: 'root', property: 'translatex', keys: [{ t: 0, v: [0] }, { t: 1, v: [40] }] }] },
    };
    const buildOf = (dirs: ProbeDirs, animations: Record<string, unknown>): string[] => {
      const motionPath = join(dirs.dir, 'probe.motion.json');
      writeFileSync(
        motionPath,
        `${JSON.stringify({ spec: 'rigc-motion/1', archetype: 'static_probe', cut: 'static_probe', easings: {}, animations }, null, 2)}\n`,
      );
      const built = runCli(['build', '--rig', dirs.rigPath, '--motion', motionPath, '--images', dirs.dir, '--out', dirs.outDir]);
      return built.status === 0 ? [] : [`${basename(dirs.dir)} did not build: exit ${String(built.status)} ${built.stderr.trim().split('\n').pop() ?? ''}`];
    };
    const buildProbe = [...buildOf(unposedRig, slide), ...buildOf(posedRig, slide), ...buildOf(collapsedRig, {})];
    const filesUnder = (dir: string): string[] =>
      existsSync(dir) ? readdirSync(dir, { recursive: true }).map(String).filter((f) => statSync(join(dir, f)).isFile()).sort() : [];
    const refusalOf = (run: ReturnType<typeof runCli>, command: string): string =>
      run.stderr.split('\n').find((line) => line.startsWith(`rigc ${command}: `))?.slice(`rigc ${command}: `.length) ?? '';
    const renderOf = (dir: string, out: string, extra: string[] = []): ReturnType<typeof runCli> =>
      runCli(['render', '--candidate', dir, ...extra, '--out', join(work, out)]);
    // The library's own refusal: `framingViewport` over the Spine data, or over the core poser with the data beside it.
    const libraryOf = (dir: string, through: 'data' | 'core' | 'core without the rig'): string => {
      try {
        const posable = loadPosable(join(dir, 'skeleton.json'), join(dir, 'skeleton.atlas'), dir);
        if (through === 'data') {
          framingViewport(posable.data, 256);
        } else {
          const choice = candidatePosers(posable.data, join(dir, 'skeleton.json'), join(dir, 'skeleton.atlas'), 'core');
          if (choice.core === null) return `no core poser: ${choice.why}`;
          framingViewport(choice.core, 256, undefined, through === 'core' ? skinRosterOf(posable.data) : undefined);
        }
        return '';
      } catch (err) {
        if (!(err instanceof GeometryError)) return `not a GeometryError: ${(err as Error).message}`;
        return err instanceof UnframeablePoseError ? err.message : `a GeometryError but not an UnframeablePoseError: ${err.message}`;
      }
    };
    const NAMED = 'slot "block" on bone "block", which skin "extra" poses';

    // GY14 — the probe through render, both posers: refused by the slot, its bone and the skin that poses it; nothing written.
    {
      const probes = [...buildProbe];
      const seen: string[] = [];
      for (const [label, extra] of [['core', []], ['spine', ['--poser', 'spine']]] as const) {
        const out = `gy14-${label}`;
        const run = renderOf(unposedRig.outDir, out, [...extra]);
        const said = refusalOf(run, 'render');
        seen.push(`${label}: exit ${String(run.status)}`);
        if (run.status !== 2) probes.push(`${label}: render exited ${String(run.status)}, not 2`);
        if (!said.startsWith('under no skin, ') || !said.includes(NAMED)) {
          probes.push(`${label}: render said ${JSON.stringify(said || run.stderr.trim().slice(0, 200))}`);
        }
        if (run.stderr.includes('posed no drawable attachment')) probes.push(`${label}: render said "posed no drawable attachment" over a slot that drew`);
        if (run.stdout.includes('NaN')) probes.push(`${label}: render printed NaN: ${JSON.stringify(run.stdout.split('\n').find((l) => l.includes('NaN')))}`);
        const written = filesUnder(join(work, out));
        if (written.length > 0) probes.push(`${label}: render wrote ${written.length} file(s): ${written.slice(0, 3).join(', ')}`);
      }
      const held = probes.length === 0;
      say(
        'RF133_A_POSE_WHOSE_EVERY_DRAWN_BONE_IS_UNPOSED_IS_REFUSED_BY_SLOT_BONE_AND_SKIN_AND_WRITES_NOTHING',
        held,
        probeDetail(held, probes, `${seen.join(', ')}; "${NAMED}"; nothing written`),
        'issue #997: the framing box over a slot drawn through the zero matrix was the one point (0, 0), and render ' +
          'wrote 0x0 frames with exit 0 on both posers — a wrong file on disk, and a console line nobody reads saying NaNxNaNpx',
      );
    }

    // GY15 — one sentence: render twice, both posers, render --geometry, check and the library agree to the byte.
    {
      const probes = [...buildProbe];
      const reference = join(work, 'gy15-reference');
      const referenced = runCli(['render', '--candidate', posedRig.outDir, '--out', reference]);
      if (referenced.status !== 0) probes.push(`the reference render exited ${String(referenced.status)}`);
      const plain = refusalOf(renderOf(unposedRig.outDir, 'gy15-plain'), 'render');
      const checked = runCli(['check', '--candidate', unposedRig.outDir, '--frames', reference]);
      const said: Array<[string, string]> = [
        ['a second render', refusalOf(renderOf(unposedRig.outDir, 'gy15-again'), 'render')],
        ['render --poser spine', refusalOf(renderOf(unposedRig.outDir, 'gy15-spine', ['--poser', 'spine']), 'render')],
        ['render --geometry', refusalOf(renderOf(unposedRig.outDir, 'gy15-geometry', ['--geometry']), 'render')],
        ['check', refusalOf(checked, 'check')],
        ['framingViewport over the data', libraryOf(unposedRig.outDir, 'data')],
        ['framingViewport over the core poser', libraryOf(unposedRig.outDir, 'core')],
      ];
      if (plain === '') probes.push('render refused nothing');
      if (checked.status !== 2) probes.push(`check exited ${String(checked.status)}, not 2`);
      for (const [label, sentence] of said) {
        if (sentence !== plain) probes.push(`${label} said ${JSON.stringify(sentence)}, render ${JSON.stringify(plain)}`);
      }
      for (const out of ['gy15-plain', 'gy15-again', 'gy15-spine', 'gy15-geometry']) {
        const written = filesUnder(join(work, out));
        if (written.length > 0) probes.push(`${out} holds ${written.length} file(s)`);
      }
      const held = probes.length === 0;
      say(
        'RF134_RENDER_BOTH_POSERS_GEOMETRY_CHECK_AND_THE_LIBRARY_REFUSE_AN_UNPOSED_POSE_IN_ONE_SENTENCE',
        held,
        probeDetail(held, probes, `${said.length + 1} callers, one sentence: ${JSON.stringify(plain)}`),
        'issue #997: the sentence has one derivation (`unframeableSentence`), and holding every caller equal to it is ' +
          'what stops a second from forking off — as #873 held the non-finite one',
      );
    }

    // GY16 — check names the skin rather than measuring an empty picture.
    {
      const probes = [...buildProbe];
      const reference = join(work, 'gy16-reference');
      const referenced = runCli(['render', '--candidate', posedRig.outDir, '--out', reference]);
      if (referenced.status !== 0) probes.push(`the reference render exited ${String(referenced.status)}`);
      const run = runCli(['check', '--candidate', unposedRig.outDir, '--frames', reference]);
      const said = refusalOf(run, 'check');
      if (run.status !== 2) probes.push(`check exited ${String(run.status)}, not 2`);
      if (!said.includes(NAMED)) probes.push(`check said ${JSON.stringify(said || run.stderr.trim().slice(0, 200))}`);
      if (run.stderr.includes('drew no pixel')) probes.push('check still said "drew no pixel", which is true and silent on the skin');
      const held = probes.length === 0;
      say(
        'RF135_CHECK_REFUSES_A_CANDIDATE_WHOSE_EVERY_DRAWN_BONE_IS_UNPOSED_BY_THE_SKIN_THAT_POSES_IT',
        held,
        probeDetail(held, probes, `check against the posed rig's frames: exit ${String(run.status)}, names "${NAMED}"`),
        'issue #997, measured before the change: check read "the candidate drew no pixel in any frame that was ' +
          'compared", exit 1 — true, and the reason, a skin the run did not pose, went unsaid',
      );
    }

    // GY17 — the plant: the framing as it was before #997 writes a frame with no size, and the probe reads it.
    {
      const probes = [...buildProbe];
      let detail = '';
      try {
        const posable = loadPosable(join(unposedRig.outDir, 'skeleton.json'), join(unposedRig.outDir, 'skeleton.atlas'), unposedRig.outDir);
        // A copy of the pre-#997 tail of `framingViewport`: the union box, padded, scaled — no question asked of its extent.
        const sets = posable.data.animations.map((a) => sampleAnimation(posable.data, a.name, FRAMING_FPS, { unclipped: true }));
        const box = unionBounds(sets);
        const pad = Math.max(box.maxX - box.minX, box.maxY - box.minY) * PAD;
        const old = viewportFor(box.minX - pad, box.minY - pad, box.maxX + pad, box.maxY + pad, 256);
        const frame = sampleAnimation(posable.data, 'slide', PROTOCOL_FPS)[0];
        const planted = join(work, 'gy17-planted.png');
        renderFrame(frame, posable.pages, old, BACKGROUND).writePng(planted);
        const header = readPngHeader(planted);
        const size = header.info === null ? `unreadable: ${header.problem}` : `${header.info.width}x${header.info.height}`;
        // The probe every control above leans on: a frame has a size of at least one pixel each way.
        const hasSize = header.info !== null && header.info.width >= 1 && header.info.height >= 1;
        if (hasSize) probes.push(`the planted framing wrote a ${size} frame, so the size probe cannot tell it from a good one`);
        const refused = libraryOf(unposedRig.outDir, 'data');
        if (refused === '') probes.push('the framing as it stands framed the probe rather than refusing it');
        detail = `the old framing: scale ${String(old.scale)}, ${String(old.width)}x${String(old.height)} px, a ${size} PNG read red; the framing now refuses it`;
      } catch (err) {
        probes.push(`the plant did not run: ${(err as Error).message}`);
      }
      const held = probes.length === 0;
      say(
        'RF136_THE_PRE_997_FRAMING_PLANTED_BACK_WRITES_A_FRAME_WITH_NO_SIZE_AND_THE_SIZE_PROBE_READS_IT',
        held,
        probeDetail(held, probes, detail),
        'issue #997: a gate nobody has seen fail is not a gate — the plant is the framing with the refusal taken ' +
          'out, and the probe that reads frame sizes has to see its 0x0 file as the fault',
      );
    }

    // GY18 — the positive control: the same rig under the skin that poses the bone renders frames of a real size.
    {
      const probes = [...buildProbe];
      const out = join(work, 'gy18-extra');
      const run = renderOf(unposedRig.outDir, 'gy18-extra', ['--skin', 'extra']);
      if (run.status !== 0) probes.push(`render --skin extra exited ${String(run.status)}: ${run.stderr.trim().slice(0, 200)}`);
      const sidecarPath = join(out, FRAMES_SIDECAR);
      const sidecar = existsSync(sidecarPath) ? (JSON.parse(readFileSync(sidecarPath, 'utf8')) as FramesSidecar) : null;
      if (sidecar === null) probes.push(`no ${FRAMES_SIDECAR} was written`);
      const wide = sidecar?.viewport.pixelWidth ?? 0;
      const high = sidecar?.viewport.pixelHeight ?? 0;
      if (!(Number.isInteger(wide) && Number.isInteger(high) && wide >= 1 && high >= 1)) probes.push(`${FRAMES_SIDECAR} says ${String(wide)}x${String(high)} px`);
      const pngs = filesUnder(out).filter((f) => /f\d{4}\.png$/.test(f));
      if (pngs.length === 0) probes.push('no frame was written');
      for (const png of pngs) {
        const header = readPngHeader(join(out, png));
        if (header.info === null || header.info.width !== wide || header.info.height !== high) {
          probes.push(`${png} is ${header.info === null ? header.problem : `${header.info.width}x${header.info.height}`}, the sidecar ${wide}x${high}`);
          break;
        }
      }
      const held = probes.length === 0;
      say(
        'RF137_THE_SAME_RIG_UNDER_THE_SKIN_THAT_POSES_ITS_BONE_RENDERS_FRAMES_OF_A_REAL_SIZE',
        held,
        probeDetail(held, probes, `--skin extra: exit 0, ${pngs.length} frame(s) of ${wide}x${high} px, the size ${FRAMES_SIDECAR} records`),
        'issue #997: the refusal is about the skin posed, not the rig — the skin the sentence names is the one that draws it',
      );
    }

    // GY19 — the other road to one point: a bone scaled to 0 is refused in the second sentence, not the first.
    {
      const probes = [...buildProbe];
      const seen: string[] = [];
      const POINT = 'every drawn vertex sits at the one point';
      for (const [label, extra] of [['core', []], ['spine', ['--poser', 'spine']]] as const) {
        const out = `gy19-${label}`;
        const run = renderOf(collapsedRig.outDir, out, [...extra]);
        const said = refusalOf(run, 'render');
        seen.push(`${label}: exit ${String(run.status)}`);
        if (run.status !== 2) probes.push(`${label}: render exited ${String(run.status)}, not 2`);
        if (!said.includes(POINT) || !said.includes('slot "block" on bone "block"') || said.includes('unposed')) {
          probes.push(`${label}: render said ${JSON.stringify(said || run.stderr.trim().slice(0, 200))}`);
        }
        const written = filesUnder(join(work, out));
        if (written.length > 0) probes.push(`${label}: render wrote ${written.length} file(s)`);
      }
      // Without the Spine data a poser cannot say a bone is unposed, and says the point instead.
      const bare = libraryOf(unposedRig.outDir, 'core without the rig');
      if (!bare.startsWith(`under no skin, ${POINT} (0, 0)`)) probes.push(`the core poser without the rig said ${JSON.stringify(bare)}`);
      const held = probes.length === 0;
      say(
        'RF138_A_POSE_COLLAPSED_TO_ONE_POINT_BY_ITS_BONES_IS_REFUSED_BY_THE_POINT_NOT_BY_A_SKIN',
        held,
        probeDetail(held, probes, `${seen.join(', ')}: "${POINT}", nothing written; a bare core poser says the point too`),
        'issue #997, measured before the change: a static rig whose one bone has scale 0 wrote a 0x0 frame with exit 0 ' +
          'as well — the two sentences are what tells a reader to change a skin from what tells them to change a bone',
      );
    }

    // --- GY20–GY22: the framing box is over the slots that pose (issue #1000) ---
    // Measured on main before the change, through both posers: a rig with one
    // posed slot `live` at (30, 20) and one drawn slot `block` on a `skin: true`
    // bone no posed skin activates framed at 256x94 — the unposed slot's eight
    // zeros sat in the union box and pulled it to the origin, where nothing is
    // drawn — and the same rig without `block` at 256x55. A slot below an
    // active bone, on a child the skin leaves unposed, did the same.
    const liveBone = { name: 'live', parent: 'root', x: 30, y: 20, length: 12 };
    const liveSlot = { name: 'live', bone: 'live', attachment: 'live' };
    const liveArt = { live: { image: 'block.png' } };
    // The posed slot alone: the box every rig below must frame to.
    const liveRig = writeProbeRig({
      bones: [{ name: 'root' }, liveBone],
      slots: [liveSlot],
      skins: { default: { live: liveArt } },
    });
    const mixedRig = writeProbeRig({
      bones: [{ name: 'root' }, { name: 'block', parent: 'root', x: 0, y: 0, length: 12, skin: true }, liveBone],
      slots: [...oneSlot, liveSlot],
      skins: { default: { ...defaultSkin, live: liveArt }, extra: { bones: ['block'], attachments: {} } },
    });
    // Unposed BELOW a posed chain: `arm` is active, its child `hand` is skin-required and unnamed, and the slot
    // hangs from `finger`, a bone with no skin flag of its own that is unposed only because its parent is.
    const belowRig = writeProbeRig({
      bones: [
        { name: 'root' },
        { name: 'arm', parent: 'root', x: -20, y: -10, length: 12 },
        { name: 'hand', parent: 'arm', x: 5, y: 0, length: 12, skin: true },
        { name: 'finger', parent: 'hand', x: 3, y: 0, length: 6 },
        liveBone,
      ],
      slots: [{ name: 'finger', bone: 'finger', attachment: 'block' }, liveSlot],
      skins: { default: { finger: { block: { image: 'block.png' } }, live: liveArt }, extra: { bones: ['hand'], attachments: {} } },
    });
    const framingProbe = [...buildOf(liveRig, slide), ...buildOf(mixedRig, slide), ...buildOf(belowRig, slide)];
    const viewportOf = (out: string): string => {
      const path = join(work, out, FRAMES_SIDECAR);
      return existsSync(path) ? JSON.stringify((JSON.parse(readFileSync(path, 'utf8')) as FramesSidecar).viewport) : 'none';
    };
    const sizeOf = (viewport: string): string => {
      if (viewport === 'none') return 'none';
      const v = JSON.parse(viewport) as FramesSidecar['viewport'];
      return `${v.pixelWidth}x${v.pixelHeight}`;
    };
    // Every frame PNG under `a` byte-equal to the same path under `b` — the poser's name in frames.json aside.
    const framesDiffer = (a: string, b: string): string[] => {
      const pngs = filesUnder(join(work, a)).filter((f) => f.endsWith('.png'));
      const other = filesUnder(join(work, b)).filter((f) => f.endsWith('.png'));
      if (pngs.length === 0) return [`${a} holds no PNG`];
      if (pngs.join('|') !== other.join('|')) return [`${a} holds ${pngs.length} PNG(s), ${b} ${other.length}`];
      return pngs.filter((f) => !readFileSync(join(work, a, f)).equals(readFileSync(join(work, b, f)))).map((f) => `${a}/${f} differs from ${b}'s`);
    };
    const libraryBox = (dir: string, through: 'data' | 'core'): string => {
      try {
        const posable = loadPosable(join(dir, 'skeleton.json'), join(dir, 'skeleton.atlas'), dir);
        if (through === 'data') return JSON.stringify(framingViewport(posable.data, 256));
        const choice = candidatePosers(posable.data, join(dir, 'skeleton.json'), join(dir, 'skeleton.atlas'), 'core');
        if (choice.core === null) return `no core poser: ${choice.why}`;
        return JSON.stringify(framingViewport(choice.core, 256, undefined, skinRosterOf(posable.data)));
      } catch (err) {
        return `threw: ${(err as Error).message}`;
      }
    };
    const liveRun = renderOf(liveRig.outDir, 'gy20-live');
    if (liveRun.status !== 0) framingProbe.push(`the posed slot alone: render exited ${String(liveRun.status)}`);
    const liveBox = viewportOf('gy20-live');
    const liveLibrary = libraryBox(liveRig.outDir, 'data');

    // GY20/GY21 — a drawn slot on an unposed bone beside a posed one, and one below a posed chain: framed to the posed slot alone.
    for (const [code, rig, label, why] of [
      [
        'RF139_A_DRAWN_SLOT_ON_A_BONE_THE_SKIN_LEAVES_UNPOSED_IS_NOT_IN_THE_FRAMING_BOX_THROUGH_EITHER_POSER',
        mixedRig,
        'gy20',
        'issue #1000, measured before the change: the unposed slot drew no pixel, yet its eight zeros sat in the union box — ' +
          '256x94 frames through both posers where the posed slot alone gives 256x55, every frame of the shot framed to the origin',
      ],
      [
        'RF140_A_DRAWN_SLOT_BELOW_AN_ACTIVE_BONE_ON_A_CHILD_THE_SKIN_LEAVES_UNPOSED_IS_NOT_IN_THE_FRAMING_BOX_EITHER',
        belowRig,
        'gy21',
        'issue #1000: "unposed" is the bone and every ancestor (`unposedBones`), so a slot on a plain bone below a ' +
          'skin-required one is off the box as well — the half the runtime\'s own `active` flag does not say',
      ],
    ] as const) {
      const probes = [...framingProbe];
      for (const [poser, extra] of [['core', []], ['spine', ['--poser', 'spine']]] as const) {
        const run = renderOf(rig.outDir, `${label}-${poser}`, [...extra]);
        if (run.status !== 0) probes.push(`${poser}: render exited ${String(run.status)}: ${run.stderr.trim().slice(0, 200)}`);
        const box = viewportOf(`${label}-${poser}`);
        if (box !== liveBox) probes.push(`${poser}: framed to ${sizeOf(box)} ${box}, the posed slot alone to ${sizeOf(liveBox)} ${liveBox}`);
      }
      // Both posers draw the same bytes, and the unposed slot adds no pixel to the posed slot's frames.
      probes.push(...framesDiffer(`${label}-core`, `${label}-spine`), ...framesDiffer(`${label}-core`, 'gy20-live'));
      for (const through of ['data', 'core'] as const) {
        const box = libraryBox(rig.outDir, through);
        if (box !== liveLibrary) probes.push(`framingViewport over the ${through} said ${box}, over the posed slot alone ${liveLibrary}`);
      }
      // The same rig under the skin that poses the bone counts the slot again: the box follows the skin, not the name.
      const posedUnder = renderOf(rig.outDir, `${label}-extra`, ['--skin', 'extra']);
      if (posedUnder.status !== 0) probes.push(`--skin extra: render exited ${String(posedUnder.status)}`);
      else if (viewportOf(`${label}-extra`) === liveBox) probes.push('--skin extra framed to the posed slot alone, though it poses the other slot too');
      const held = probes.length === 0;
      say(
        code,
        held,
        probeDetail(
          held,
          probes,
          `both posers framed to ${sizeOf(liveBox)}, the posed slot's own box, frames byte-identical to it; ` +
            `--skin extra, which poses the slot, frames to ${sizeOf(viewportOf(`${label}-extra`))}`,
        ),
        why,
      );
    }

    // GY22 — the plant: the box counted over every drawn slot again, as before #1000, reads the origin-pulled frame.
    {
      const probes = [...framingProbe];
      let detail = '';
      try {
        const posable = loadPosable(join(mixedRig.outDir, 'skeleton.json'), join(mixedRig.outDir, 'skeleton.atlas'), mixedRig.outDir);
        // A copy of the pre-#1000 box: every drawn piece, the unposed slot's included.
        const sets = posable.data.animations.map((a) => sampleAnimation(posable.data, a.name, FRAMING_FPS, { unclipped: true }));
        const box = unionBounds(sets);
        const pad = Math.max(box.maxX - box.minX, box.maxY - box.minY) * PAD;
        const old = viewportFor(box.minX - pad, box.minY - pad, box.maxX + pad, box.maxY + pad, 256);
        const now = framingViewport(posable.data, 256);
        const alone = JSON.parse(liveLibrary) as ReturnType<typeof framingViewport>;
        const oldSize = `${old.width}x${old.height}`;
        const aloneSize = alone === null ? 'none' : `${alone.width}x${alone.height}`;
        if (JSON.stringify(old) === liveLibrary) probes.push('the planted box is the posed slot\'s own, so the controls above cannot tell the two apart');
        if (!(box.minX <= 0 && box.minY <= 0)) probes.push(`the planted box does not reach the origin: (${box.minX}, ${box.minY})`);
        if (JSON.stringify(now) !== liveLibrary) probes.push(`the framing as it stands said ${JSON.stringify(now)}, not the posed slot's ${liveLibrary}`);
        detail = `the old box reaches (${box.minX}, ${box.minY}) and frames ${oldSize}; the posed slot alone and the framing now ${aloneSize}`;
      } catch (err) {
        probes.push(`the plant did not run: ${(err as Error).message}`);
      }
      const held = probes.length === 0;
      say(
        'RF141_THE_PRE_1000_BOX_OVER_EVERY_DRAWN_SLOT_PLANTED_BACK_IS_PULLED_TO_THE_ORIGIN_AND_READ',
        held,
        probeDetail(held, probes, detail),
        'issue #1000: a gate nobody has seen fail is not a gate — the plant is the box with the unposed slot counted ' +
          'again, and it has to differ from the box the controls above hold',
      );
    }
    rmSync(work, { recursive: true, force: true });
    for (const dirs of [unposedRig, posedRig, collapsedRig, liveRig, mixedRig, belowRig]) rmSync(dirs.dir, { recursive: true, force: true });
  }

  rmSync(turn.dir, { recursive: true, force: true });
  rmSync(spin.dir, { recursive: true, force: true });
  return bad;
}

/** The clip fixture's polygon, in the bone's own space: smaller than both parts, so each has pixels to lose. */
const CLIP_PROBE_POLYGON = [-2, -2, 2, -2, 2, 2, -2, 2];

/**
 * Which clip fixture: `clipped` masks `block` (clip → block → marker, ending at
 * block); `bare` is the same skeleton with the clip slot left empty; `ended`
 * masks `marker` and ends there, with `block` drawn after it.
 */
type ClipVariant = 'clipped' | 'bare' | 'ended';

interface ClipProbe {
  variant: ClipVariant;
  dir: string;
  outDir: string;
  posable: Posable | null;
  buildError: string;
}

/** The static probe rig with a clipping slot added, built through the CLI. */
function writeClipProbe(variant: ClipVariant): ClipProbe {
  const end = variant === 'ended' ? 'marker' : 'block';
  const mask = { name: 'mask', bone: 'block', ...(variant === 'bare' ? {} : { attachment: 'mask' }) };
  const parts =
    variant === 'ended'
      ? [{ name: 'marker', bone: 'block', attachment: 'marker' }, { name: 'block', bone: 'block', attachment: 'block' }]
      : [{ name: 'block', bone: 'block', attachment: 'block' }, { name: 'marker', bone: 'block', attachment: 'marker' }];
  const dirs = writeProbeRig({
    slots: [mask, ...parts],
    skins: {
      default: {
        block: { block: { image: 'block.png' } },
        marker: { marker: { image: 'marker.png' } },
        mask: {
          mask: { type: 'clipping', vertexCount: CLIP_PROBE_POLYGON.length / 2, vertices: CLIP_PROBE_POLYGON, end },
        },
      },
    },
  });
  // The empty clip slot states its emptiness: the compiler guesses no setup pose.
  const motion = variant === 'bare' ? { ...SLIDE_MOTION, setup: { mask: { attachment: null } } } : SLIDE_MOTION;
  const motionPath = join(dirs.dir, 'probe.motion.json');
  writeFileSync(motionPath, `${JSON.stringify(motion, null, 2)}\n`);
  const build = runCli([
    'build', '--rig', dirs.rigPath, '--motion', motionPath, '--images', dirs.dir, '--out', dirs.outDir, '--copy-images',
  ]);
  const skeletonPath = join(dirs.outDir, 'skeleton.json');
  const posable =
    build.status === 0 && existsSync(skeletonPath)
      ? loadPosable(skeletonPath, join(dirs.outDir, 'skeleton.atlas'), dirs.outDir)
      : null;
  return {
    variant,
    dir: dirs.dir,
    outDir: dirs.outDir,
    posable,
    buildError: `exit=${String(build.status)} ${build.stderr.split('\n')[0]}`,
  };
}

/**
 * One slot of a clip fixture drawn alone at its setup pose, on the whole rig's
 * grid, and its drawn pixels split by the clip's POSED polygon — which spine-core
 * computes off the skeleton, so the split is measured rather than restated from
 * `CLIP_PROBE_POLYGON`. A pixel counts as outside only when its centre is outside
 * the polygon by more than a millionth of a pixel: a centre on the boundary is the
 * rasteriser's fill rule to decide, not a leak.
 */
function clipSlotPixels(probe: ClipProbe, slot: string): { inside: number; outside: number; pixels: Buffer | null } {
  if (probe.posable === null) return { inside: 0, outside: 0, pixels: null };
  const { data, pages } = probe.posable;
  const viewport = framingViewport(data, 256);
  if (viewport === null) return { inside: 0, outside: 0, pixels: null };
  const plate = renderFrame(sampleSetupPose(data, { slots: [slot] })[0], pages, viewport, BACKGROUND);

  const skeleton = new Skeleton(data);
  skeleton.setupPose();
  skeleton.update(0);
  skeleton.updateWorldTransform(Physics.reset);
  const maskSlot = skeleton.findSlot('mask');
  const clip = data.defaultSkin?.getAttachment(data.findSlot('mask')?.index ?? -1, 'mask');
  if (maskSlot === null || !(clip instanceof ClippingAttachment)) return { inside: 0, outside: 0, pixels: null };
  const world = new Array<number>(clip.worldVerticesLength).fill(0);
  clip.computeWorldVertices(skeleton, maskSlot, 0, clip.worldVerticesLength, world, 0, 2);
  const project = projector(viewport);
  const polygon: Array<[number, number]> = [];
  for (let i = 0; i < world.length; i += 2) polygon.push(project(world[i], world[i + 1]));

  const edgeDistance = (px: number, py: number): number => {
    let best = Infinity;
    for (let i = 0; i < polygon.length; i++) {
      const [ax, ay] = polygon[i];
      const [bx, by] = polygon[(i + 1) % polygon.length];
      const t = Math.max(0, Math.min(1, ((px - ax) * (bx - ax) + (py - ay) * (by - ay)) / ((bx - ax) ** 2 + (by - ay) ** 2)));
      best = Math.min(best, Math.hypot(px - (ax + t * (bx - ax)), py - (ay + t * (by - ay))));
    }
    return best;
  };
  const contains = (px: number, py: number): boolean => {
    let odd = false;
    for (let i = 0, j = polygon.length - 1; i < polygon.length; j = i++) {
      const [xi, yi] = polygon[i];
      const [xj, yj] = polygon[j];
      if (yi > py !== yj > py && px < ((xj - xi) * (py - yi)) / (yj - yi) + xi) odd = !odd;
    }
    return odd;
  };
  let inside = 0;
  let outside = 0;
  for (let y = 0; y < plate.height; y++) {
    for (let x = 0; x < plate.width; x++) {
      const [r, g, b, a] = plate.get(x, y);
      if (r === BACKGROUND[0] && g === BACKGROUND[1] && b === BACKGROUND[2] && a === BACKGROUND[3]) continue;
      if (contains(x + 0.5, y + 0.5) || edgeDistance(x + 0.5, y + 0.5) <= 1e-6) inside++;
      else outside++;
    }
  }
  return { inside, outside, pixels: Buffer.from(plate.data) };
}

// ---------------------------------------------------------------------------
// reading a pose frame — pose (issue #241)
// ---------------------------------------------------------------------------
//
// ⭐ Why this suite can exist at all, and what shape that gives it. Every number
// `rigc pose` prints is an estimate of something nobody wrote down: it is handed
// a picture and loose parts and it has to work out where each part sits. So the
// only honest way to check it is to build the picture from placements we DO know
// — a rig with chosen bone angles, rendered by `src/render.ts` — and then ask the
// estimator, which never sees the rig, whether it can read them back.
//
// 🔒 The ground truth is derived from the posed quads and the viewport, not from
// the numbers in the rig spec: three corners of a region and its own UVs give the
// affine map from part pixels to frame pixels, and the placement is that map's
// centre, rotation and scale. That keeps the yardstick on the side of the drawing
// rather than the side of the arithmetic — a compiler bug that moved the art would
// move the truth with it, and the estimator would still have to agree.
//
// ⚠️ The tolerances are the METHOD FLOOR of a raster compare, and they are stated
// here with what was measured rather than left as round numbers. The frame is a
// bilinear resampling of the part with its edge pixels dropped below half
// coverage, so the pixels the estimator matches are not the part's pixels; and the
// objective charges for every part pixel that lands off the figure while charging
// nothing for figure left uncovered, which puts the optimum a fraction inside the
// true silhouette. Measured on this fixture, re-baselined 2026-09-03 under the
// premultiplied objective (issue #306): translation within 0.16 px, rotation
// within 0.27°, scale 0.8–3.1% LOW on every one of five parts — a consistent
// sign, which is what a systematic half-pixel of silhouette looks like over a
// part 30 px across. The bars below sit a few times clear of each. ⚠️ The scale
// band was 2–4% and the translation 0.12 px when first stated; two of the three
// intervening moves are not #306's — this fixture's arm plate grew from 10x26 to
// 10x30 with `chainfit`, and the frame it is read out of is rendered by
// `bilinear`, which #301 moved. #306's own contribution is the narrowing: the two
// arms come in 2.8% and 3.1% low where they were 3.4% and 3.6%.
const POSE_TOLERANCE = { translate: 1, rotateDeg: 2, scaleRatio: 0.08 };

/** A checkerboard, for parts whose interior has to be identifiable. */
function poseChecker(w: number, h: number, a: RGBA, b: RGBA, band: number): Plate {
  const p = new Plate(w, h);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) p.set(x, y, (Math.floor(x / band) + Math.floor(y / band)) % 2 === 0 ? a : b);
  }
  return p;
}

/**
 * A smoothly shaded ball of concentric rings.
 *
 * Rotation-symmetric on purpose — that is the degree of freedom `pose` has to
 * report as free — while the ring spacing still pins its SCALE, so the control is
 * about rotation alone and not about a uniform disc nothing can size.
 */
function poseBall(size: number): Plate {
  const p = new Plate(size, size);
  const r = size / 2 - 1;
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const d = Math.hypot(x + 0.5 - size / 2, y + 0.5 - size / 2);
      if (d > r + 0.5) continue;
      const wave = (Math.cos((d / r) * Math.PI * 3) + 1) / 2;
      p.set(x, y, [
        Math.round(60 + wave * 150),
        Math.round(160 + wave * 60),
        Math.round(90 + wave * 40),
        Math.round(255 * Math.max(0, Math.min(1, r + 0.5 - d))),
      ]);
    }
  }
  return p;
}

/** One placement in frame pixels, the shape both the truth and the estimate take. */
interface PosePlacementTruth {
  x: number;
  y: number;
  rotationDeg: number;
  scale: number;
}

/**
 * The affine map one posed region applies to its own page, read off three corners.
 *
 * `world` carries the corners in spine-core's order and `uvs` carries the same
 * corners' page coordinates, so multiplying one basis by the other's inverse gives
 * the map without this file needing to know how the atlas packed the region — a
 * rotated or trimmed region would change both sides together.
 */
function poseTruthOf(piece: Piece, page: Plate, project: (wx: number, wy: number) => [number, number]): PosePlacementTruth {
  const part = (i: number): [number, number] => [piece.uvs[i * 2] * page.width, piece.uvs[i * 2 + 1] * page.height];
  const frame = (i: number): [number, number] => project(piece.world[i * 2], piece.world[i * 2 + 1]);
  const [p0, p1, p2] = [part(1), part(0), part(2)];
  const [f0, f1, f2] = [frame(1), frame(0), frame(2)];
  const e1p = [p1[0] - p0[0], p1[1] - p0[1]];
  const e2p = [p2[0] - p0[0], p2[1] - p0[1]];
  const e1f = [f1[0] - f0[0], f1[1] - f0[1]];
  const e2f = [f2[0] - f0[0], f2[1] - f0[1]];
  const det = e1p[0] * e2p[1] - e1p[1] * e2p[0];
  const a = (e1f[0] * e2p[1] - e2f[0] * e1p[1]) / det;
  const b = (e2f[0] * e1p[0] - e1f[0] * e2p[0]) / det;
  const c = (e1f[1] * e2p[1] - e2f[1] * e1p[1]) / det;
  const d = (e2f[1] * e1p[0] - e1f[1] * e2p[0]) / det;
  const tx = f0[0] - (a * p0[0] + b * p0[1]);
  const ty = f0[1] - (c * p0[0] + d * p0[1]);
  return {
    x: a * (page.width / 2) + b * (page.height / 2) + tx,
    y: c * (page.width / 2) + d * (page.height / 2) + ty,
    rotationDeg: (Math.atan2(c, a) * 180) / Math.PI,
    scale: Math.sqrt(Math.abs(a * d - b * c)),
  };
}

/** How far one estimate is from one truth, in the three units the tolerances are stated in. */
function poseDelta(got: PosePlacement, want: PosePlacementTruth): { translate: number; rotateDeg: number; scaleRatio: number } {
  let turn = (((got.rotationDeg - want.rotationDeg) % 360) + 360) % 360;
  if (turn > 180) turn -= 360;
  return {
    translate: Math.hypot(got.x - want.x, got.y - want.y),
    rotateDeg: Math.abs(turn),
    scaleRatio: Math.abs(got.scale / want.scale - 1),
  };
}

function poseWithin(d: { translate: number; rotateDeg: number; scaleRatio: number }): boolean {
  return (
    d.translate <= POSE_TOLERANCE.translate &&
    d.rotateDeg <= POSE_TOLERANCE.rotateDeg &&
    d.scaleRatio <= POSE_TOLERANCE.scaleRatio
  );
}

function poseSay(d: { translate: number; rotateDeg: number; scaleRatio: number }): string {
  return `Δpos ${d.translate.toFixed(2)}px Δrot ${d.rotateDeg.toFixed(2)}° Δscale ${(d.scaleRatio * 100).toFixed(1)}%`;
}

/**
 * The fixture: five plates, a rig that poses them at chosen angles, and one
 * rendered frame with the placements it implies.
 *
 * ⚠️ The viewport is built by hand rather than by `framingViewport`, and the scale
 * 1.15 is the reason. A fitted viewport lands wherever the figure's bounds put it,
 * which for this rig is a scale outside `pose`'s own default window — the control
 * would then be measuring the window rather than the estimator. 1.15 also sits
 * deliberately BETWEEN two rungs of the coarse scale ladder (1.0 and 1.26), so a
 * pass means the refinement actually moved rather than landing on a rung.
 *
 * The two arms carry the SAME plate at mirrored angles. That is the ambiguity
 * control: one PNG, two places in the picture that explain it equally well, and
 * the instrument must report both rather than pick.
 *
 * `headScale`, when given, draws the head's attachment at that `scaleX`/`scaleY`
 * — the frame #719's landing measured and #737 is about: one picture at 1.15
 * frame pixels per unit whose parts do NOT all share that scale, so one part's
 * truth can sit outside a window that holds the rest. Absent, the rig spec is
 * the one this fixture has always written, byte for byte.
 */
function buildPoseFixture(headScale?: number): {
  dir: string;
  parts: string;
  framePath: string;
  clearPath: string;
  truth: Map<string, PosePlacementTruth>;
} {
  const dir = mkdtempSync(join(harnessTemp(), 'rigc-pose-'));
  const parts = join(dir, 'parts');
  mkdirSync(parts, { recursive: true });

  const torso = poseChecker(24, 36, [60, 90, 160, 255], [110, 140, 200, 255], 6);
  torso.rect(0, 0, 24, 4, [220, 60, 60, 255]);
  torso.writePng(join(parts, 'torso.png'));

  const arm = poseChecker(10, 30, [200, 160, 60, 255], [150, 110, 30, 255], 5);
  arm.rect(0, 0, 10, 3, [40, 40, 40, 255]);
  arm.writePng(join(parts, 'arm.png'));

  const head = poseChecker(22, 22, [230, 200, 170, 255], [200, 160, 130, 255], 11);
  head.rect(2, 4, 5, 4, [30, 30, 30, 255]);
  head.rect(15, 4, 5, 4, [30, 30, 30, 255]);
  head.writePng(join(parts, 'head.png'));

  poseBall(32).writePng(join(parts, 'ball.png'));

  // The three decoys. None of them is in the rig, so none of them is in the
  // picture, and each has to come back refused for its own reason.
  poseChecker(20, 20, [255, 0, 255, 255], [0, 255, 255, 255], 4).writePng(join(parts, 'foreign.png'));
  poseChecker(700, 700, [10, 10, 10, 255], [250, 250, 250, 255], 40).writePng(join(parts, 'toobig.png'));
  new Plate(16, 16).writePng(join(parts, 'blank.png'));

  const rigPath = join(dir, 'pose.rig.json');
  writeFileSync(
    rigPath,
    `${JSON.stringify(
      {
        spec: 'rigc-rig/1',
        name: 'pose_probe',
        skeleton: { width: 200, height: 200 },
        bones: [
          { name: 'root' },
          { name: 'torso', parent: 'root', x: 0, y: 0 },
          { name: 'head', parent: 'torso', x: 0, y: 34 },
          // Inboard enough that each arm covers part of the torso: the torso is
          // then the occlusion control, measured rather than asserted.
          { name: 'arm_l', parent: 'torso', x: -15, y: 8, rotation: 35 },
          { name: 'arm_r', parent: 'torso', x: 15, y: 8, rotation: -35 },
          { name: 'ball', parent: 'torso', x: 0, y: -34 },
        ],
        slots: [
          { name: 'torso', bone: 'torso', attachment: 'torso' },
          { name: 'head', bone: 'head', attachment: 'head' },
          { name: 'arm_l', bone: 'arm_l', attachment: 'arm_l' },
          { name: 'arm_r', bone: 'arm_r', attachment: 'arm_r' },
          { name: 'ball', bone: 'ball', attachment: 'ball' },
        ],
        skins: {
          default: {
            torso: { torso: { image: 'torso.png' } },
            head: {
              head:
                headScale === undefined
                  ? { image: 'head.png' }
                  : { image: 'head.png', scaleX: headScale, scaleY: headScale },
            },
            arm_l: { arm_l: { image: 'arm.png' } },
            arm_r: { arm_r: { image: 'arm.png' } },
            ball: { ball: { image: 'ball.png' } },
          },
        },
      },
      null,
      2,
    )}\n`,
  );
  const motionPath = join(dir, 'pose.motion.json');
  writeFileSync(
    motionPath,
    `${JSON.stringify({ spec: 'rigc-motion/1', archetype: 'pose_probe', cut: 'pose_probe', easings: {}, animations: {} }, null, 2)}\n`,
  );
  const outDir = join(dir, 'spine');
  const built = compile({ rigPath, motionPath, outDir, imagesDir: parts });
  mkdirSync(outDir, { recursive: true });
  writeFileSync(join(outDir, 'skeleton.json'), built.skeletonText);
  writeFileSync(join(outDir, 'skeleton.atlas'), built.atlasText);

  const posable = loadPosable(join(outDir, 'skeleton.json'), join(outDir, 'skeleton.atlas'), outDir);
  const frames = sampleSetupPose(posable.data);
  const bounds = unionBounds([frames]);
  const scale = 1.15;
  const pad = 12;
  const worldW = bounds.maxX - bounds.minX + pad * 2;
  const worldH = bounds.maxY - bounds.minY + pad * 2;
  const viewport = viewportOfSize(
    bounds.minX - pad,
    bounds.minY - pad,
    worldW,
    worldH,
    scale,
    Math.round(worldW * scale),
    Math.round(worldH * scale),
  );
  const plate = renderFrame(frames[0], posable.pages, viewport, BACKGROUND);
  const framePath = join(dir, 'poseA.png');
  plate.writePng(framePath);

  // The same picture with the flat ground knocked out to transparency, so the
  // other branch of background detection has something real to read.
  const clear = new Plate(plate.width, plate.height);
  for (let y = 0; y < plate.height; y++) {
    for (let x = 0; x < plate.width; x++) {
      const c = plate.get(x, y);
      clear.set(x, y, c[0] === BACKGROUND[0] && c[1] === BACKGROUND[1] && c[2] === BACKGROUND[2] ? [0, 0, 0, 0] : c);
    }
  }
  const clearPath = join(dir, 'poseA_clear.png');
  clear.writePng(clearPath);

  const project = projector(viewport);
  const truth = new Map<string, PosePlacementTruth>();
  for (const piece of frames[0].pieces) {
    const page = posable.pages.get(piece.page);
    if (piece.kind !== 'region' || !page) continue;
    truth.set(piece.slot, poseTruthOf(piece, page, project));
  }
  return { dir, parts, framePath, clearPath, truth };
}

/**
 * Two copies of one plate side by side — the shape PO02's fixture does not have
 * (issue #1519).
 *
 * ⭐ PO02's arms are one span apart and 70° apart in rotation, and that shape was
 * caught by the coarse grid releases before 1.4.0 used: a quarter-span stride
 * with two cells of suppression. This one is a pair of legs: centres
 * `distanceSpans` of the plate's span apart, `apartDeg` apart in rotation, and
 * the same scale — which that grid collapsed onto ONE placement, printed
 * `PLACE` with no alternate and the other leg tens of pixels off its truth,
 * because the second basin fell between two anchors and the suppression radius
 * swallowed it. So PO02 passed on those releases while a picture of this shape
 * was being read wrong, and only a fixture of this shape can hold the grid.
 *
 * The geometry is the selftest's own, not a copy of the picture it was found
 * on: an 18x34 plate at 1.1 frame px per unit, 0.6 span and 6° apart. It was
 * picked because its NEIGHBOURS behave the same — at 1.1, every distance from
 * 0.55 to 0.65 span and every angle from 3° to 8° gave both legs on the current
 * grid and one on the planted one — so a later change to the search moves this
 * control only by moving the shape's whole neighbourhood.
 *
 * `secondScale`, when given, draws the second copy at that scale: two far
 * places at DIFFERENT sizes, the other reading of an ambiguity (PO35).
 *
 * `halfTurn` draws a plate that a half-turn maps onto itself, pixel for pixel —
 * 18x30 in 6 px checks, three by five cells, so the turn moves every cell by an
 * even count and keeps its colour, with the dark band at BOTH ends — so the
 * search's own quarter- and half-turn polish finds a second fit at a copy's
 * own centre (issue #1526). Not round, so `rotationFree` does not take it.
 */
function buildTwinPoseFixture(o: { distanceSpans: number; apartDeg: number; secondScale?: number; halfTurn?: boolean }): {
  dir: string;
  parts: string;
  framePath: string;
  truth: [PosePlacementTruth, PosePlacementTruth];
} {
  const dir = mkdtempSync(join(harnessTemp(), 'rigc-pose-twins-'));
  const parts = join(dir, 'parts');
  mkdirSync(parts, { recursive: true });
  const leg = poseChecker(18, o.halfTurn === true ? 30 : 34, [70, 120, 60, 255], [120, 170, 90, 255], 6);
  if (o.halfTurn === true) leg.rect(0, 0, leg.width, 5, [60, 40, 30, 255]);
  leg.rect(0, leg.height - 5, leg.width, 5, [60, 40, 30, 255]);
  leg.writePng(join(parts, 'leg.png'));
  const apart = o.distanceSpans * Math.max(leg.width, leg.height);
  const second = o.secondScale === undefined ? { image: 'leg.png' } : { image: 'leg.png', scaleX: o.secondScale, scaleY: o.secondScale };
  const rigPath = join(dir, 'twins.rig.json');
  writeFileSync(
    rigPath,
    `${JSON.stringify(
      {
        spec: 'rigc-rig/1',
        name: 'twin_probe',
        skeleton: { width: 200, height: 200 },
        bones: [
          { name: 'root' },
          { name: 'leg_a', parent: 'root', x: -apart / 2, y: 0, rotation: o.apartDeg / 2 },
          { name: 'leg_b', parent: 'root', x: apart / 2, y: 0, rotation: -o.apartDeg / 2 },
        ],
        slots: [
          { name: 'leg_a', bone: 'leg_a', attachment: 'leg' },
          { name: 'leg_b', bone: 'leg_b', attachment: 'leg' },
        ],
        skins: { default: { leg_a: { leg: { image: 'leg.png' } }, leg_b: { leg: second } } },
      },
      null,
      2,
    )}\n`,
  );
  const motionPath = join(dir, 'twins.motion.json');
  writeFileSync(
    motionPath,
    `${JSON.stringify({ spec: 'rigc-motion/1', archetype: 'twin_probe', cut: 'twin_probe', easings: {}, animations: {} }, null, 2)}\n`,
  );
  const outDir = join(dir, 'spine');
  const built = compile({ rigPath, motionPath, outDir, imagesDir: parts });
  mkdirSync(outDir, { recursive: true });
  writeFileSync(join(outDir, 'skeleton.json'), built.skeletonText);
  writeFileSync(join(outDir, 'skeleton.atlas'), built.atlasText);
  const posable = loadPosable(join(outDir, 'skeleton.json'), join(outDir, 'skeleton.atlas'), outDir);
  const frames = sampleSetupPose(posable.data);
  const bounds = unionBounds([frames]);
  // Off the coarse ladder's rungs for the reason `buildPoseFixture` gives.
  const scale = 1.1;
  const pad = 12;
  const worldW = bounds.maxX - bounds.minX + pad * 2;
  const worldH = bounds.maxY - bounds.minY + pad * 2;
  const viewport = viewportOfSize(bounds.minX - pad, bounds.minY - pad, worldW, worldH, scale, Math.round(worldW * scale), Math.round(worldH * scale));
  const framePath = join(dir, 'twins.png');
  renderFrame(frames[0], posable.pages, viewport, BACKGROUND).writePng(framePath);
  const project = projector(viewport);
  const truthOf = (slot: string): PosePlacementTruth => {
    const piece = frames[0].pieces.find((p) => p.slot === slot);
    const page = piece === undefined ? undefined : posable.pages.get(piece.page);
    if (piece === undefined || page === undefined || piece.kind !== 'region') throw new Error(`internal: the twin fixture posed no region "${slot}"`);
    return poseTruthOf(piece, page, project);
  };
  return { dir, parts, framePath, truth: [truthOf('leg_a'), truthOf('leg_b')] };
}

/** Each truth's nearest reported placement, by centre, as the three tolerances measure it. */
function poseNearestEach(
  found: readonly PosePlacement[],
  truths: readonly PosePlacementTruth[],
): ({ translate: number; rotateDeg: number; scaleRatio: number } | null)[] {
  return truths.map((t) => {
    let best: { translate: number; rotateDeg: number; scaleRatio: number } | null = null;
    for (const p of found) {
      const d = poseDelta(p, t);
      if (best === null || d.translate < best.translate) best = d;
    }
    return best;
  });
}

function runPoseSuite(): number {
  console.log('\n── reading a pose frame: pose (issue #241) ──');
  let bad = 0;
  const say = (name: string, ok: boolean, detail: string, why: string): void => {
    bad += reportCase(name, ok, detail, why);
  };

  const fixture = buildPoseFixture();
  const report = estimatePose({ imagesDir: fixture.parts, framePath: fixture.framePath });
  const byName = new Map(report.parts.map((p) => [p.part, p]));
  const want = (slot: string): PosePlacementTruth => {
    const t = fixture.truth.get(slot);
    if (!t) throw new Error(`internal: the fixture posed no slot "${slot}"`);
    return t;
  };

  // --- the placements themselves -------------------------------------------
  {
    const singles: [string, string][] = [
      ['torso.png', 'torso'],
      ['head.png', 'head'],
      ['ball.png', 'ball'],
    ];
    const rows = singles.map(([file, slot]) => {
      const got = byName.get(file)?.placement;
      return { file, ok: got !== undefined && got !== null, delta: got ? poseDelta(got, want(slot)) : null };
    });
    const ok = rows.every((r) => r.ok && r.delta !== null && poseWithin(r.delta));
    say(
      'PO01_KNOWN_PLACEMENTS_ARE_READ_BACK_OUT_OF_THE_PICTURE',
      ok,
      rows.map((r) => `${r.file}: ${r.delta ? poseSay(r.delta) : 'no placement'}`).join('  ·  '),
      'the whole command is this claim; a `pose` that cannot recover a placement it was shown is a plausible-number generator',
    );
  }

  // --- two identical limbs --------------------------------------------------
  {
    const arm = byName.get('arm.png');
    const found = arm?.placement ? [arm.placement, ...arm.alternates] : [];
    const nearest = (slot: string): { translate: number; rotateDeg: number; scaleRatio: number } | null => {
      const t = want(slot);
      let best: { translate: number; rotateDeg: number; scaleRatio: number } | null = null;
      for (const p of found) {
        const d = poseDelta(p, t);
        if (best === null || d.translate < best.translate) best = d;
      }
      return best;
    };
    const left = nearest('arm_l');
    const right = nearest('arm_r');
    const ok =
      arm !== undefined &&
      arm.ambiguous &&
      arm.alternates.length >= 1 &&
      left !== null &&
      right !== null &&
      poseWithin(left) &&
      poseWithin(right);
    say(
      'PO02_TWO_IDENTICAL_LIMBS_COME_BACK_AS_TWO_PLACEMENTS',
      ok,
      arm === undefined
        ? 'arm.png is not in the report'
        : `ambiguous=${arm.ambiguous}, ${1 + arm.alternates.length} placement(s); ` +
          `arm_l ${left ? poseSay(left) : 'unmatched'}; arm_r ${right ? poseSay(right) : 'unmatched'}`,
      'picking one of two equally good optima silently is the failure this instrument was specified to refuse',
    );
  }

  // --- PO34–PO35: twins a fraction of a span apart (issue #1519) -------------
  {
    const twins = buildTwinPoseFixture({ distanceSpans: 0.6, apartDeg: 6 });
    // 🌱 The plant is the grid releases before 1.4.0 searched on — a quarter-span
    // stride and two cells of suppression, the pair of numbers that, put back
    // alone, made a pair of legs come back as one placement (issue #1517).
    const planted: PoseCoarseGrid = { ...COARSE_GRID, strideFraction: COARSE_GRID.strideFraction * 2, suppressionCells: COARSE_GRID.suppressionCells / 2 };
    const read = (grid: PoseCoarseGrid) => {
      const part = estimatePose({ imagesDir: twins.parts, framePath: twins.framePath, coarseGrid: grid }).parts[0];
      const found = part?.placement ? [part.placement, ...part.alternates] : [];
      const [a, b] = poseNearestEach(found, twins.truth);
      const held = part !== undefined && part.ambiguous && a !== null && b !== null && poseWithin(a) && poseWithin(b);
      const says =
        part === undefined
          ? 'leg.png is not in the report'
          : `ambiguous=${part.ambiguous}, ${found.length} placement(s); leg_a ${a ? poseSay(a) : 'unmatched'}; ` +
            `leg_b ${b ? poseSay(b) : 'unmatched'}`;
      return { part, held, says };
    };
    const tree = read(COARSE_GRID);
    const plant = read(planted);
    say(
      'PO34_TWINS_SIX_TENTHS_OF_A_SPAN_APART_COME_BACK_AS_TWO_PLACEMENTS',
      tree.held && !plant.held,
      `two copies of leg.png 0.6 span and 6° apart at one scale: ${tree.says}. With the coarse grid planted at ` +
        `stride ${planted.strideFraction} of the span and suppression ${planted.suppressionCells} cell(s) — the grid ` +
        `releases before 1.4.0 searched on: ${plant.says}${plant.held ? ' — the plant did NOT fire' : ''}`,
      'PO02\'s twins are a span and 70° apart, a shape the old grid already caught, so it passed while a pair of ' +
        'legs 0.6 span apart was printed as one confident placement with the other leg tens of pixels off (issue #1519)',
    );

    // ⭐ The reading has two branches for an ambiguity above the floor, and each
    // is held on a picture of its own shape AND on a forged alternate that must
    // move it to the other one — so neither branch passes by never being taken.
    const eyes = buildTwinPoseFixture({ distanceSpans: 1.6, apartDeg: 6, secondScale: 0.92 });
    const eyesPart = estimatePose({ imagesDir: eyes.parts, framePath: eyes.framePath }).parts[0];
    const ROUTE = 'MOTION.md §2.2 🔀';
    const WINDOW = 'tells the two apart';
    const branch = (reading: string): 'route' | 'window' | 'neither' =>
      reading.includes(ROUTE) && !reading.includes(WINDOW) ? 'route' : reading.includes(WINDOW) && !reading.includes(ROUTE) ? 'window' : 'neither';
    // 📍 Twins whose plate a half-turn maps onto itself (issue #1526): the
    // search's own turn polish keeps a second fit at a copy's own centre, which
    // put the nearest alternate 0 spans from the best and sent this shape to the
    // window sentence until the margin was grouped into places. One span apart,
    // between neighbours at 0.6 and 1.6 that read the same way.
    const turned = buildTwinPoseFixture({ distanceSpans: 1, apartDeg: 6, halfTurn: true });
    const turnedPart = estimatePose({ imagesDir: turned.parts, framePath: turned.framePath }).parts[0];
    const replant = (
      part: typeof eyesPart | undefined,
      forge: (best: PosePlacement, alt: PosePlacement) => PosePlacement,
      samePlaceSpans?: number,
    ): string => {
      if (part?.placement == null || part.legibility === null) return '';
      const best = part.placement;
      const span = Math.max(part.legibility.width, part.legibility.height) * best.scale;
      const forged = part.alternates.map((alt) => forge(best, alt));
      return legibilityReading(part.legibility, 'ambiguous', repeatedPlaces(best, forged, span, samePlaceSpans));
    };
    // 🔒 The one judge every shape and every plant goes through: a reading that
    // is not the branch its shape has is a fault named by what was read.
    type Branch = 'route' | 'window';
    const misread = (what: string, reading: string, want: Branch): string[] =>
      branch(reading) === want ? [] : [`${what}: read ${branch(reading)}, wanted ${want}`];
    const other = (b: Branch): Branch => (b === 'route' ? 'window' : 'route');
    const twinPart = tree.part;
    const twinReading = twinPart?.legibility?.reading ?? '';
    const eyesReading = eyesPart?.legibility?.reading ?? '';
    const turnedReading = turnedPart?.legibility?.reading ?? '';
    const cli = runCli(['pose', '--images', twins.parts, '--frame', twins.framePath, '--out', join(twins.dir, 'pose.json')]);
    const guide = readFileSync(resolve(import.meta.dir, 'docs/AUTHORING.md'), 'utf8');
    // Each plant names the shape it forges and that shape's own branch; it is
    // caught when the judge, asked for that branch, names the OTHER one.
    const plants: [string, string, Branch][] = [
      [
        `the twins' alternate moved off the best's scale by twice the ${REPEAT_SCALE_RATIO} bar`,
        replant(twinPart, (best, alt) => ({ ...alt, scale: best.scale * (1 + 2 * REPEAT_SCALE_RATIO) })),
        'route',
      ],
      ["the twins' alternate moved onto the best's centre", replant(twinPart, (best, alt) => ({ ...alt, x: best.x, y: best.y })), 'route'],
      ["the far pair's alternate put at the best's scale", replant(eyesPart, (best, alt) => ({ ...alt, scale: best.scale })), 'window'],
      [
        'the turned twins with the grouping into places planted out (radius 0, the minimum over every alternate)',
        replant(turnedPart, (_best, alt) => alt, 0),
        'route',
      ],
    ];
    const probes: string[] = [];
    if (!(twinPart?.ambiguous ?? false) || twinPart?.legibility?.floor !== 'above') probes.push('the twins are not an ambiguity above the floor');
    probes.push(...misread('the twins', twinReading, 'route').map((f) => `${f}: ${JSON.stringify(twinReading)}`));
    if (!(cli.stdout.includes(twinReading) && twinReading !== '')) probes.push("the twins' reading is not on the console");
    if (!(guide.includes(twinReading) && twinReading !== '')) probes.push("the twins' reading is not quoted in AUTHORING §11.5");
    if (!(eyesPart?.ambiguous ?? false) || eyesPart?.legibility?.floor !== 'above') probes.push('the far pair at two scales is not an ambiguity above the floor');
    probes.push(...misread('the far pair', eyesReading, 'window').map((f) => `${f}: ${JSON.stringify(eyesReading)}`));
    // The turned case is only this case if the margin really holds a turned fit
    // at a copy's own centre — read off what the search reported.
    const turnedFound = turnedPart?.placement ? [turnedPart.placement, ...turnedPart.alternates] : [];
    const turnedSpan = turnedPart?.legibility == null || turnedPart.placement === null ? 0 : turnedPart.legibility.span;
    const turnedPairs = turnedFound.flatMap((p, i) =>
      turnedFound
        .slice(i + 1)
        .filter((q) => Math.hypot(p.x - q.x, p.y - q.y) < REPEAT_DISTANCE_SPANS * turnedSpan && Math.abs(normaliseDegrees(p.rotationDeg - q.rotationDeg)) >= 45)
        .map((q) => `${p.rotationDeg.toFixed(1)}°/${q.rotationDeg.toFixed(1)}°`),
    );
    if (!(turnedPart?.ambiguous ?? false) || turnedPart?.legibility?.floor !== 'above') probes.push('the turned twins are not an ambiguity above the floor');
    if (turnedPairs.length === 0) probes.push(`the turned twins' margin holds no turned fit at one centre: ${turnedFound.length} placement(s)`);
    probes.push(...misread('the turned twins', turnedReading, 'route').map((f) => `${f}: ${JSON.stringify(turnedReading)}`));
    for (const [what, reading, shape] of plants) {
      if (raisedBy(misread(what, reading, shape), { at: `${what}: read ${other(shape)},` }).length === 0) {
        probes.push(`${what}: not caught — read ${branch(reading)} where the shape reads ${shape}`);
      }
    }
    const eyesFound = eyesPart?.placement ? [eyesPart.placement, ...eyesPart.alternates] : [];
    const eyesScales = eyesFound.map((p) => p.scale.toFixed(3)).join(' and ');
    const held = probes.length === 0;
    say(
      'PO35_AN_AMBIGUITY_OF_ONE_SIZE_IN_TWO_PLACES_NAMES_THE_UNORDERED_SET_AND_NOT_A_WINDOW',
      held,
      probeDetail(
        held,
        probes,
        `the twins read the 🔀 route, on the console and quoted in §11.5; the far pair at scales ${eyesScales} reads ` +
          `the window; the turned twins, ${turnedFound.length} placements with ${turnedPairs.length} turned pair(s) at ` +
          `one centre (${turnedPairs.join(', ')}), read the 🔀 route; planted — ` +
          `${plants.map(([what, reading]) => `${what}: ${branch(reading)}`).join('; ')}`,
      ),
      'a left/right pair cut from one drawing sits at one scale, so no --scale window separates it, and a --rotation ' +
        'window that "resolves" it does so by excluding one place — the sentence offering a window there sends the ' +
        'reader to the one remedy that picks the answer instead of reading it (issue #1519); and a turned fit the ' +
        'search keeps at a copy\'s own centre is not another place, or that remedy comes back for every part a ' +
        'half-turn maps onto itself (issue #1526)',
    );
    rmSync(twins.dir, { recursive: true, force: true });
    rmSync(eyes.dir, { recursive: true, force: true });
    rmSync(turned.dir, { recursive: true, force: true });
  }

  // --- rotation as a degree of freedom -------------------------------------
  {
    const ball = byName.get('ball.png');
    const others = report.parts.filter((p) => p.part !== 'ball.png' && p.part !== 'blank.png');
    const ok =
      ball !== undefined &&
      ball.rotationFree &&
      ball.rotationSelfSimilarity <= ROTATION_FREE_TOLERANCE &&
      others.every((p) => !p.rotationFree);
    say(
      'PO03_A_ROUND_PART_REPORTS_ROTATION_AS_FREE_AND_NOTHING_ELSE_DOES',
      ok,
      `ball self-residual ${ball?.rotationSelfSimilarity ?? 'n/a'} (tolerance ${ROTATION_FREE_TOLERANCE}); ` +
        `others: ${others.map((p) => `${p.part} ${p.rotationSelfSimilarity}`).join(', ')}`,
      'a ball has no rotation to get right; reporting one is a made-up number and refusing the part is worse',
    );
  }

  // --- the three refusals ---------------------------------------------------
  {
    const foreign = byName.get('foreign.png');
    const ok =
      foreign !== undefined &&
      foreign.refusal?.reason === 'no-match' &&
      foreign.refusal.detail.includes('foreign.png') &&
      // Still reported: a refusal here names why not to trust a number, it does
      // not hide it, and an agent that disagrees has to be able to read past it.
      foreign.placement !== null &&
      foreign.placement.residual > DEFAULT_MAX_RESIDUAL;
    say(
      'PO04_A_PART_THAT_IS_IN_NO_PICTURE_IS_REFUSED_BY_NAME',
      ok,
      foreign === undefined
        ? 'foreign.png is not in the report'
        : `${foreign.refusal?.reason ?? 'accepted'}: best residual ${foreign.placement?.residual ?? 'n/a'} against ${DEFAULT_MAX_RESIDUAL}`,
      'the alternative is a confident placement for a part that is not there, which is the one output an agent cannot detect',
    );
  }

  {
    const big = byName.get('toobig.png');
    const ok =
      big !== undefined &&
      big.refusal?.reason === 'larger-than-canvas' &&
      big.placement === null &&
      big.refusal.detail.includes('700x700');
    say(
      'PO05_A_PART_THE_CANVAS_CANNOT_HOLD_IS_REFUSED_BY_NAME',
      ok,
      big === undefined ? 'toobig.png is not in the report' : `${big.refusal?.reason ?? 'accepted'}: ${big.refusal?.detail ?? ''}`,
      'nothing was searched, so a placement here would be arithmetic about a case that does not exist',
    );
  }

  {
    const blank = byName.get('blank.png');
    const ok = blank !== undefined && blank.refusal?.reason === 'empty-part' && blank.placement === null;
    say(
      'PO06_A_PART_WITH_NO_MATERIAL_IS_REFUSED_BY_NAME',
      ok,
      blank === undefined ? 'blank.png is not in the report' : `${blank.refusal?.reason ?? 'accepted'}: ${blank.refusal?.detail ?? ''}`,
      'an all-transparent PNG divides by a zero footprint; the honest answer names the file',
    );
  }

  // --- occlusion ------------------------------------------------------------
  {
    const torso = byName.get('torso.png');
    const arm = byName.get('arm.png');
    const ok =
      torso?.placement != null &&
      arm?.placement != null &&
      poseWithin(poseDelta(torso.placement, want('torso'))) &&
      // The arms cover part of it, so its residual and its unexplained share are
      // both well above an unoccluded part's while the PLACEMENT is unmoved.
      torso.placement.unexplained > arm.placement.unexplained * 3 &&
      torso.placement.residual > arm.placement.residual * 2;
    say(
      'PO07_OCCLUSION_RAISES_THE_RESIDUAL_WITHOUT_MOVING_THE_PLACEMENT',
      ok,
      torso?.placement == null || arm?.placement == null
        ? 'torso.png or arm.png has no placement'
        : `torso residual ${torso.placement.residual} unexplained ${torso.placement.unexplained} at ` +
          `${poseSay(poseDelta(torso.placement, want('torso')))}; unoccluded arm ${arm.placement.residual}/${arm.placement.unexplained}`,
      'the documented caveat is exactly this pair of facts; if the residual did not move, the caveat is fiction, and if the placement did, the number is not a trust signal',
    );
  }

  // --- background detection -------------------------------------------------
  {
    const clear = estimatePose({ imagesDir: fixture.parts, framePath: fixture.clearPath });
    const clearByName = new Map(clear.parts.map((p) => [p.part, p]));
    const same = (['torso.png', 'head.png', 'ball.png'] as const).every((file) => {
      const a = byName.get(file)?.placement;
      const b = clearByName.get(file)?.placement;
      return a != null && b != null && Math.hypot(a.x - b.x, a.y - b.y) <= 0.5 && Math.abs(a.scale / b.scale - 1) <= 0.02;
    });
    const ok = clear.frame.background.kind === 'transparent' && report.frame.background.kind === 'colour' && same;
    say(
      'PO08_A_TRANSPARENT_GROUND_AND_A_FLAT_ONE_READ_THE_SAME',
      ok,
      `flat ground: ${report.frame.background.kind} ${JSON.stringify(report.frame.background.colour)}; ` +
        `knocked out: ${clear.frame.background.kind}; placements agree: ${same}`,
      'the objective needs to know where the picture has nothing in it; a ground it misreads turns the silhouette signal off silently',
    );
  }

  // --- the window the report says it searched -------------------------------
  //
  // ⚠️ Two halves, and the first one is deliberately NOT "a wrong window is
  // refused". It is not: a checkerboard shrunk to a third of its size still sits
  // inside the blob it came from and explains those pixels well enough to clear
  // the refusal threshold. That is the honest limit of a footprint-only objective
  // and the reason the window is a reported field rather than an implementation
  // detail — an agent that narrowed it wrongly can see that it did.
  {
    const wrong = estimatePose({ imagesDir: fixture.parts, framePath: fixture.framePath, scale: { min: 0.2, max: 0.4 } });
    const inside = wrong.parts.every(
      (p) => p.placement === null || (p.placement.scale >= 0.2 - 1e-9 && p.placement.scale <= 0.4 + 1e-9),
    );
    const stated = wrong.search.scale.min === 0.2 && wrong.search.scale.max === 0.4;
    const right = estimatePose({ imagesDir: fixture.parts, framePath: fixture.framePath, scale: { min: 1.1, max: 1.25 } });
    const rows = (['torso.png', 'head.png', 'ball.png'] as const).map((file) => {
      const got = right.parts.find((p) => p.part === file)?.placement ?? null;
      const slot = file.replace('.png', '');
      return { file, delta: got ? poseDelta(got, want(slot)) : null };
    });
    const recovered = rows.every((r) => r.delta !== null && poseWithin(r.delta));
    say(
      'PO09_THE_SEARCH_WINDOW_IS_A_PROMISE_THE_REPORT_KEEPS',
      inside && stated && recovered,
      `--scale 0.2,0.4: every reported scale inside it = ${inside}, report states it = ${stated}; ` +
        `--scale 1.1,1.25: ${rows.map((r) => `${r.file} ${r.delta ? poseSay(r.delta) : 'no placement'}`).join('  ·  ')}`,
      'a polish free to walk outside the ladder would report a scale nobody searched, and a narrowed window that stopped working would make the flag useless',
    );
  }

  // --- the command ----------------------------------------------------------
  {
    const out = join(fixture.dir, 'pose.json');
    const run = runCli(['pose', '--images', fixture.parts, '--frame', fixture.framePath, '--out', out]);
    let written: { spec?: string; parts?: unknown[] } | null = null;
    if (existsSync(out)) written = JSON.parse(readFileSync(out, 'utf8')) as { spec?: string; parts?: unknown[] };
    const help = runCli(['pose', '--help']);
    const missing = runCli(['pose', '--images', join(fixture.dir, 'nope'), '--frame', fixture.framePath]);
    const ok =
      run.status === 0 &&
      written?.spec === POSE_SPEC &&
      (written.parts?.length ?? 0) === 7 &&
      run.stdout.includes('AMBIG') &&
      run.stdout.includes('REFUSE') &&
      help.status === 0 &&
      help.stdout.includes('--frame') &&
      help.stdout.includes('--max-residual') &&
      missing.status === 2 &&
      missing.stderr.includes('no parts directory at');
    say(
      'PO10_THE_COMMAND_WRITES_ITS_REPORT_AND_REFUSES_A_BAD_PATH',
      ok,
      `pose exit=${String(run.status)} spec=${written?.spec ?? 'none'} parts=${written?.parts?.length ?? 0}; ` +
        `--help exit=${String(help.status)}; missing dir exit=${String(missing.status)} ` +
        `${JSON.stringify(missing.stderr.split('\n')[0])}`,
      'the JSON is the whole product — an agent reads it and never sees the table — and a mistyped directory must not read as an empty pose',
    );
  }

  // --- the same picture, read twice -----------------------------------------
  // The objective divides now (issue #306: the tap is premultiplied, so each
  // colour is weighted by its own material and the sum divided back out), and a
  // division is where a search picks up an order-of-summation dependence. The
  // report is what an agent writes a rig from, so "the same picture twice" has to
  // mean the same numbers and not the same numbers to a tolerance.
  {
    const twice = estimatePose({ imagesDir: fixture.parts, framePath: fixture.framePath });
    const first = JSON.stringify(report.parts);
    const second = JSON.stringify(twice.parts);
    say(
      'PO11_THE_SAME_PICTURE_READ_TWICE_REPORTS_THE_SAME_NUMBERS',
      first === second,
      `${report.parts.length} part(s) re-read from the same frame: ` +
        `${first === second ? 'byte-identical' : `DIFFERENT (${first.length} vs ${second.length} chars)`}`,
      'a placement an agent cannot reproduce is not a measurement, and `src/` is specified to hold no clock and ' +
        'no randomness — this is the assertion that says the arithmetic obeys that too',
    );
  }

  // --- PO12–PO16: the window as a promise the whole report keeps (#719) ------
  //
  // ⭐ The sitting that found this ran `pose` on eleven parts against a frame
  // rendered at 0.311 frame pixels per part pixel, with the default window whose
  // floor is 0.5. All eleven were refused, all eleven at `scale=0.500`, and the
  // message named the residual and the threshold and not the wall — so the one
  // remedy that could work was the one thing the refusal did not mention. The
  // same sitting then narrowed `--rotation` to `-5,5` and read placements back
  // at 91.2°, −86.2° and 90.3° under a line that said `rotation -5°–5°`.
  //
  // 🔑 Both are one defect wearing two faces: a window that is REPORTED without
  // being APPLIED, and a window that is APPLIED without being REPORTED at the
  // one moment it decided the answer.
  //
  // The windows below are placed against the fixture's own truth rather than at
  // numbers typed here — "a fifth above the true scale", "twenty degrees past
  // the true turn" — so the cases move with the fixture instead of pinning it.
  const truthScale = want('torso').scale;
  const truthTurn = Math.abs(want('arm_l').rotationDeg);
  const to3 = (n: number): number => Math.round(n * 1000) / 1000;
  const partPath = (file: string): string => join(fixture.parts, file);

  /**
   * The wall sentences that are TRUE of one reported placement.
   *
   * ⚠️ Derived from the reported numbers and the caller's own window, never from
   * the module's idea of what counts as "at the wall": the clamp writes the bound
   * itself, so equality is the whole test and an epsilon here would be this file
   * agreeing with the code about the one thing it is checking. A rotation window
   * is compared plainly because every window below sits inside (−180, 180], which
   * is the range a reported angle is normalised into.
   */
  const wallsOf = (
    p: PosePlacement,
    scale: { min: number; max: number },
    rotation: { minDeg: number; maxDeg: number },
  ): string[] => {
    const out: string[] = [];
    const scaleWindow = `${scale.min},${scale.max}`;
    if (scale.max > scale.min) {
      if (p.scale === scale.min) out.push(windowEdgeNote('scale', 'floor', p.scale.toFixed(3), scaleWindow));
      else if (p.scale === scale.max) out.push(windowEdgeNote('scale', 'ceiling', p.scale.toFixed(3), scaleWindow));
    }
    const turnWindow = `${rotation.minDeg},${rotation.maxDeg}`;
    const said = `${p.rotationDeg.toFixed(1)}°`;
    if (rotation.maxDeg > rotation.minDeg && rotation.maxDeg - rotation.minDeg < 360) {
      if (p.rotationDeg === rotation.minDeg) out.push(windowEdgeNote('rotation', 'floor', said, turnWindow));
      else if (p.rotationDeg === rotation.maxDeg) out.push(windowEdgeNote('rotation', 'ceiling', said, turnWindow));
    }
    return out;
  };

  /** How many wall sentences a refusal detail carries, by the clause every one of them ends on. */
  const wallClauses = (detail: string): number => detail.split('— the truth may lie ').length - 1;

  const FULL_TURN = { minDeg: -180, maxDeg: 180 };

  /**
   * Every refusal in one run, against the walls its own placement stands on.
   *
   * Two-sided by construction: a detail missing a wall it is on and a detail
   * naming a wall it is not on are both reported, and the second is the reason
   * the count of clauses is compared rather than their presence.
   */
  const wallFaults = (
    what: string,
    run: PoseReport,
    scale: { min: number; max: number },
    rotation: { minDeg: number; maxDeg: number },
  ): { faults: string[]; named: string[] } => {
    const faults: string[] = [];
    const named: string[] = [];
    for (const part of run.parts) {
      if (part.refusal?.reason !== 'no-match' || part.placement === null) continue;
      const want = wallsOf(part.placement, scale, rotation);
      const detail = part.refusal.detail;
      for (const sentence of want) {
        if (detail.includes(sentence)) named.push(`${part.part} ${JSON.stringify(sentence)}`);
        else faults.push(`${what}: ${part.part} stopped on a wall and its refusal does not say so — ${JSON.stringify(detail)}`);
      }
      const carried = wallClauses(detail);
      if (carried !== want.length) {
        faults.push(
          `${what}: ${part.part} stands on ${want.length} wall(s) of this window and its refusal names ` +
            `${carried} — ${JSON.stringify(detail)}`,
        );
      }
    }
    return { faults, named };
  };

  // --- PO12: a refusal that stopped on a wall names the wall ----------------
  {
    const lowFloor = { min: to3(truthScale * 1.2), max: to3(truthScale * 1.75) };
    const highCeiling = { min: to3(truthScale * 0.78), max: to3(truthScale * 0.87) };
    const pastTurn = { minDeg: to3(truthTurn + 20), maxDeg: to3(truthTurn + 60) };
    const beforeTurn = { minDeg: to3(-(truthTurn + 60)), maxDeg: to3(-(truthTurn + 20)) };
    // A bar tight enough that a part held away from its own answer is refused
    // rather than reported flat, stated as a fraction of the shipped one so the
    // two move together.
    const tight = DEFAULT_MAX_RESIDUAL / 5;
    const solid = [partPath('torso.png'), partPath('ball.png')];
    const absent = [partPath('foreign.png')];
    const runs: {
      what: string;
      run: PoseReport;
      scale: { min: number; max: number };
      rotation: { minDeg: number; maxDeg: number };
      wall: string;
    }[] = [
      {
        what: `--scale ${lowFloor.min},${lowFloor.max}, whose floor is above the true ${to3(truthScale)}`,
        run: estimatePose({ imagesDir: fixture.parts, framePath: fixture.framePath, parts: solid, scale: lowFloor }),
        scale: lowFloor,
        rotation: FULL_TURN,
        wall: `the floor of --scale ${lowFloor.min},${lowFloor.max}`,
      },
      {
        what: `--scale ${highCeiling.min},${highCeiling.max}, whose ceiling is below the true ${to3(truthScale)}`,
        run: estimatePose({
          imagesDir: fixture.parts,
          framePath: fixture.framePath,
          parts: solid,
          scale: highCeiling,
          maxResidual: tight,
        }),
        scale: highCeiling,
        rotation: FULL_TURN,
        wall: `the ceiling of --scale ${highCeiling.min},${highCeiling.max}`,
      },
      {
        what: `--rotation ${pastTurn.minDeg},${pastTurn.maxDeg}, a window past the true ${to3(truthTurn)}°`,
        run: estimatePose({
          imagesDir: fixture.parts,
          framePath: fixture.framePath,
          parts: absent,
          rotation: pastTurn,
          maxResidual: tight,
        }),
        scale: { min: 0.5, max: 2 },
        rotation: pastTurn,
        wall: `the floor of --rotation ${pastTurn.minDeg},${pastTurn.maxDeg}`,
      },
      {
        what: `--rotation ${beforeTurn.minDeg},${beforeTurn.maxDeg}, a window short of the true −${to3(truthTurn)}°`,
        run: estimatePose({
          imagesDir: fixture.parts,
          framePath: fixture.framePath,
          parts: absent,
          rotation: beforeTurn,
          maxResidual: tight,
        }),
        scale: { min: 0.5, max: 2 },
        rotation: beforeTurn,
        wall: `the ceiling of --rotation ${beforeTurn.minDeg},${beforeTurn.maxDeg}`,
      },
    ];
    const probes: string[] = [];
    const notes: string[] = [];
    for (const one of runs) {
      const { faults, named } = wallFaults(one.what, one.run, one.scale, one.rotation);
      probes.push(...faults);
      const onThisWall = named.filter((row) => row.includes(one.wall));
      if (onThisWall.length === 0) {
        probes.push(
          `${one.what} was chosen to drive a refusal onto ${one.wall} and drove none — ` +
            `${one.run.parts.map((p) => `${p.part} ${p.refusal?.reason ?? 'placed'} at scale ${p.placement?.scale ?? 'n/a'} rotation ${p.placement?.rotationDeg ?? 'n/a'}`).join(', ')}`,
        );
        continue;
      }
      notes.push(`${one.wall}: ${onThisWall[0]}`);
    }
    const held = probes.length === 0;
    say(
      'PO12_A_REFUSAL_WHOSE_BEST_PLACEMENT_STOPPED_ON_A_WALL_OF_THE_WINDOW_NAMES_THE_WALL',
      held,
      probeDetail(held, probes, `four windows placed against the fixture's own truth — ${notes.join(' · ')}`),
      'eleven parts of one frame came back refused at the floor of a window that could not reach the art, and the ' +
        'message named the residual and the threshold. An author reading it has every reason to change the frame ' +
        'or the threshold and none to change the one thing that was wrong, because the report never said the ' +
        'answer had stopped against a wall rather than settled',
    );
  }

  // --- PO13: and a placement inside the window is left alone ----------------
  //
  // 🔒 The other half, and the half that decides whether the sentence above is
  // worth reading. A wall named on every refusal is a wall named on none: the
  // parts of a correct run sit at whatever scale explains them, and a window an
  // author chose to bracket the answer puts placements near its edges on
  // purpose. The plant is the same frame and the same part under a window whose
  // floor is moved onto the answer it already found — nothing about the picture
  // changes, only whether the answer is against a wall.
  {
    const refused = report.parts.filter((p) => p.refusal?.reason === 'no-match' && p.placement !== null);
    const interior = refused.filter(
      (p) => wallsOf(p.placement as PosePlacement, { min: 0.5, max: 2 }, FULL_TURN).length === 0,
    );
    const probes: string[] = [];
    if (interior.length === 0) {
      probes.push(
        'the default window refused nothing away from its own walls, so this run cannot say whether the sentence ' +
          'is conditional at all',
      );
    }
    for (const part of interior) {
      const detail = part.refusal?.detail ?? '';
      if (wallClauses(detail) !== 0) {
        probes.push(`${part.part} was refused inside the window and its detail names a wall anyway — ${JSON.stringify(detail)}`);
      }
      if (!detail.includes('--max-residual')) {
        probes.push(`${part.part}'s refusal stopped naming the threshold it was refused against — ${JSON.stringify(detail)}`);
      }
    }
    for (const part of report.parts) {
      if (part.refusal !== null) continue;
      const said = [part.refusal ?? '', ...part.notes].join(' ');
      if (wallClauses(said) !== 0) probes.push(`${part.part} was placed, not refused, and a wall is named over it — ${JSON.stringify(said)}`);
    }
    // The plant: the same part, the same frame, a floor moved onto the answer.
    let plantNote = '';
    const victim = interior[0];
    if (victim !== undefined && victim.placement !== null) {
      const onTheWall = { min: victim.placement.scale, max: to3(victim.placement.scale * 2) };
      const moved = estimatePose({
        imagesDir: fixture.parts,
        framePath: fixture.framePath,
        parts: [victim.path],
        scale: onTheWall,
      });
      const after = moved.parts[0]?.refusal?.detail ?? '';
      const wanted = windowEdgeNote('scale', 'floor', onTheWall.min.toFixed(3), `${onTheWall.min},${onTheWall.max}`);
      if (!after.includes(wanted)) {
        probes.push(
          `${victim.part} under --scale ${onTheWall.min},${onTheWall.max}, whose floor is the answer it already ` +
            `found, is refused without naming the wall — ${JSON.stringify(after)}`,
        );
      } else {
        plantNote =
          `and the same part under --scale ${onTheWall.min},${onTheWall.max} — its own answer made the floor — ` +
          `is refused with ${JSON.stringify(wanted)}`;
      }
    }
    const held = probes.length === 0;
    say(
      'PO13_A_REFUSAL_THAT_SETTLED_INSIDE_THE_WINDOW_NAMES_NO_WALL',
      held,
      probeDetail(
        held,
        probes,
        `${interior.length} of ${refused.length} refusal(s) under the default window settled away from both walls ` +
          `and none of them names one, no placed part carries the sentence anywhere, ${plantNote}`,
      ),
      'a warning printed on every refusal is a warning nobody reads, and this one would be easy to write that ' +
        'way — the two flags have four walls between them and a refused part is usually near one. The claim is ' +
        'conditional or it is noise',
    );
  }

  // --- PO14: a window narrower than the coarse step is divided, not swallowed -
  //
  // ⭐ The measurement the card asked for first, and it refutes the reading the
  // card put first. `--rotation -5,5` does NOT collapse to one angle under a 15°
  // step: the old ladder marched from the floor and then appended the ceiling, so
  // it searched exactly two angles ten degrees apart — and printed `step 15°`,
  // a resolution no run of it ever had. The ladder now divides the window, so the
  // number printed is the number walked.
  //
  // 🔑 Through the real command, because `--rotation` is parsed on the way in:
  // "a legal window still runs" is a fact about the flag, not about the module.
  {
    const narrow = { minDeg: -COARSE_ROTATION_STEP / 3, maxDeg: COARSE_ROTATION_STEP / 3 };
    const out = join(fixture.dir, 'pose-narrow.json');
    const run = runCli([
      'pose',
      '--images',
      fixture.parts,
      '--frame',
      fixture.framePath,
      '--rotation',
      `${narrow.minDeg},${narrow.maxDeg}`,
      '--out',
      out,
    ]);
    const written = existsSync(out) ? (JSON.parse(readFileSync(out, 'utf8')) as PoseReport) : null;
    const probes: string[] = [];
    if (run.status !== 0) probes.push(`a window narrower than the coarse step was not run: exit ${String(run.status)} ${JSON.stringify(run.stderr.split('\n')[0])}`);
    if (written === null) probes.push(`no report was written to ${out}`);
    let note = '';
    if (written !== null) {
      const ladder = written.search.rotation;
      const span = narrow.maxDeg - narrow.minDeg;
      if (ladder.degrees.length < 2) {
        probes.push(`the window was searched at ${ladder.degrees.length} angle(s): ${ladder.degrees.join(', ')}`);
      }
      if (ladder.degrees.some((deg) => deg < narrow.minDeg - 1e-9 || deg > narrow.maxDeg + 1e-9)) {
        probes.push(`the ladder leaves its own window: ${ladder.degrees.join(', ')}`);
      }
      if (Math.abs(ladder.stepDeg * (ladder.degrees.length - 1) - span) > 1e-9) {
        probes.push(`${ladder.degrees.length} angle(s) at ${ladder.stepDeg}° do not span the ${span}° window`);
      }
      if (!(ladder.stepDeg < COARSE_ROTATION_STEP)) {
        probes.push(`the applied step ${ladder.stepDeg}° is not below the ${COARSE_ROTATION_STEP}° ceiling the window is narrower than`);
      }
      const escaped = written.parts.flatMap((part) =>
        (part.placement === null ? [] : [part.placement, ...part.alternates])
          .filter((p) => p.rotationDeg < narrow.minDeg - 1e-6 || p.rotationDeg > narrow.maxDeg + 1e-6)
          .map((p) => `${part.part} at ${p.rotationDeg}°`),
      );
      probes.push(...firstFew(escaped.map((row) => `a placement outside the searched window was reported: ${row}`), 'placement(s)'));
      note =
        `${ladder.degrees.length} angle(s) — ${ladder.degrees.join('°, ')}° — at a step of ${ladder.stepDeg}°, under ` +
        `the ${COARSE_ROTATION_STEP}° ceiling the window is narrower than, and not one of the ` +
        `${written.parts.reduce((n, part) => n + (part.placement === null ? 0 : 1 + part.alternates.length), 0)} ` +
        'placement(s) reported leaves it';
    }
    // ⭐ And the ceiling as an INVARIANT rather than as one window's figure.
    // Dividing a window into a ROUNDED number of steps passes everything above —
    // a window narrower than the constant still divides into one step — while
    // giving a 20° window a 20° step, which is the constant bounding nothing.
    // Every window a caller may name, walked as the pure function it is.
    const coarser: string[] = [];
    for (let span = 1; span <= 360; span++) {
      const rungs = rotationLadder(-span / 2, span / 2);
      const step = rungs.length > 1 ? rungs[1] - rungs[0] : 0;
      if (step > COARSE_ROTATION_STEP + 1e-9) coarser.push(`a ${span}° window is walked at ${step}°`);
    }
    probes.push(...firstFew(coarser, 'window(s)'));
    if (note !== '') note = `${note}; and no window from 1° to 360° is walked at a step above ${COARSE_ROTATION_STEP}°`;
    const held = probes.length === 0;
    say(
      'PO14_A_ROTATION_WINDOW_NARROWER_THAN_THE_COARSE_STEP_IS_DIVIDED_AND_NOTHING_REPORTED_LEAVES_IT',
      held,
      probeDetail(held, probes, note),
      'the constant was documented as the step and used as one, which left two ways for the reported step to be a ' +
        'different number from the walked one; and the polish clamped its scale to the window while leaving the ' +
        'rotation free to walk out of it, so a ten-degree window came back with 28.1° in it',
    );
  }

  // --- PO15: the line printed is the ladder walked --------------------------
  //
  // 🌱 The plant is the branch point's own field: `stepDeg` set to the constant
  // while the ladder beside it is untouched. That is not an invented defect, it
  // is what this file measured before the repair — and a reading that passes it
  // is a reading that would have passed the report the exam candidate read.
  {
    const reading = (run: PoseReport): string[] => {
      const faults: string[] = [];
      const line = poseLines(run).find((row) => row.includes('search '));
      if (line === undefined) return ['the report prints no `search` line at all'];
      const clause = searchRotationClause(run.search.rotation);
      if (!line.includes(clause)) faults.push(`the printed line does not carry ${JSON.stringify(clause)} — ${JSON.stringify(line.trim())}`);
      const ladder = run.search.rotation;
      if (ladder.degrees.length !== ladder.steps) faults.push(`the line counts ${ladder.steps} step(s) over a ladder of ${ladder.degrees.length}`);
      for (let i = 1; i < ladder.degrees.length; i++) {
        const gap = ladder.degrees[i] - ladder.degrees[i - 1];
        if (Math.abs(gap - ladder.stepDeg) > 1e-9) {
          faults.push(`the line states one step of ${ladder.stepDeg}° over a ladder that walks ${gap}° between angle ${i} and ${i + 1}`);
          break;
        }
      }
      if (ladder.degrees.length > 0 && ladder.degrees[0] !== ladder.minDeg) {
        faults.push(`the line opens the window at ${ladder.minDeg}° and the ladder opens at ${ladder.degrees[0]}°`);
      }
      const last = ladder.degrees[ladder.degrees.length - 1];
      const wraps = ladder.maxDeg - ladder.minDeg >= 360 - 1e-9;
      // A full turn's ladder drops the duplicate endpoint, so the angle that
      // closes the window is one step past the last one it holds.
      const reach = wraps ? last + ladder.stepDeg : last;
      if (ladder.degrees.length > 0 && Math.abs(reach - ladder.maxDeg) > 1e-9) {
        faults.push(`the line closes the window at ${ladder.maxDeg}° and the ladder reaches ${reach}°`);
      }
      return faults;
    };
    const narrow = estimatePose({
      imagesDir: fixture.parts,
      framePath: fixture.framePath,
      parts: [partPath('ball.png')],
      rotation: { minDeg: -COARSE_ROTATION_STEP / 3, maxDeg: COARSE_ROTATION_STEP / 3 },
    });
    const probes: string[] = [];
    for (const [what, run] of [
      ['the default full turn', report],
      ['a window narrower than the coarse step', narrow],
    ] as const) {
      probes.push(...reading(run).map((fault) => `${what}: ${fault}`));
    }
    // Two plants, on the DATA the reading is taken from. The first is the field
    // this repair replaced; the second moves one rung out of the window.
    const planted = (edit: (run: PoseReport) => PoseReport, what: string): void => {
      const before = reading(narrow);
      const raised = raisedBy(reading(edit(structuredClone(narrow))), { was: before });
      if (raised.length === 0) probes.push(`${what} was read as agreeing with its own line`);
    };
    planted((run) => {
      run.search.rotation.stepDeg = COARSE_ROTATION_STEP;
      return run;
    }, `a report stating the ${COARSE_ROTATION_STEP}° constant as the step it walked`);
    planted((run) => {
      run.search.rotation.degrees[run.search.rotation.degrees.length - 1] += COARSE_ROTATION_STEP;
      return run;
    }, 'a ladder whose last angle sits outside the window the line names');
    const held = probes.length === 0;
    say(
      'PO15_THE_SEARCH_LINE_PRINTED_IS_THE_LADDER_THE_RUN_WALKED',
      held,
      probeDetail(
        held,
        probes,
        `the full turn prints ${JSON.stringify(searchRotationClause(report.search.rotation))} and the narrow ` +
          `window ${JSON.stringify(searchRotationClause(narrow.search.rotation))}; each is the ladder beside it, ` +
          `angle for angle. The same reading faults a report carrying the ${COARSE_ROTATION_STEP}° constant as its ` +
          'step, and one whose last angle was pushed out of the window',
      ),
      '§11.3 calls `search` every window and threshold that was applied, which makes the line a promise rather ' +
        'than a courtesy. A caller who reads `rotation -5°–5° step 15°` and then reads `rot=91.2°` has been told ' +
        'two things that cannot both be true and has no way to find out which',
    );
  }

  // --- PO16: where the quarter turns came from ------------------------------
  //
  // ⭐ The card offered two readings of the 91° placements — a step that
  // swallowed the window, or a symmetric part matched a quarter turn off — and
  // the measurement says the second, with the polish as its carrier. The ladder
  // searched its two endpoints honestly; what left the window was the explicit
  // `[90, 180, 270]` seed pass, which is not a ladder rung at all, and a polish
  // that clamped its scale to the window and let its rotation walk.
  //
  // This is that pair as a fact rather than a story: the family is still probed
  // where the window contains it, and is not where the window does not.
  {
    const probes: string[] = [];
    const quarterTurnsOf = (run: PoseReport): string[] =>
      run.parts.flatMap((part) =>
        part.placement === null
          ? []
          : part.alternates
              .filter((alt) =>
                [90, 180, 270].some(
                  (turn) =>
                    Math.abs(
                      normaliseDegrees(alt.rotationDeg - ((part.placement as PosePlacement).rotationDeg + turn)),
                    ) <= 5,
                ),
              )
              .map((alt) => `${part.part} ${(part.placement as PosePlacement).rotationDeg}° and ${alt.rotationDeg}°`),
      );
    const wide = quarterTurnsOf(report);
    if (wide.length === 0) {
      probes.push(
        'a window spanning the whole turn reported no pair of optima a quarter or a half turn apart, so this run ' +
          'cannot say the family is probed at all',
      );
    }
    const narrow = estimatePose({
      imagesDir: fixture.parts,
      framePath: fixture.framePath,
      parts: [partPath('foreign.png'), partPath('arm.png')],
      rotation: { minDeg: -COARSE_ROTATION_STEP / 3, maxDeg: COARSE_ROTATION_STEP / 3 },
    });
    probes.push(
      ...quarterTurnsOf(narrow).map(
        (row) => `a window ten degrees wide reported two optima a quarter turn apart: ${row}`,
      ),
    );
    const held = probes.length === 0;
    say(
      'PO16_THE_QUARTER_TURN_FAMILY_IS_PROBED_WHERE_THE_WINDOW_HOLDS_IT_AND_NOT_WHERE_IT_DOES_NOT',
      held,
      probeDetail(
        held,
        probes,
        `over the whole turn ${wide.length} pair(s) of optima sit a quarter or a half turn apart — ${wide[0] ?? 'none'} — ` +
          'and inside a window ten degrees wide not one does',
      ),
      'a part that is its own mirror after a quarter turn has to be reported at both angles, and the translation ' +
        'scan cannot see the second — so the seeds are added by hand, outside the ladder. That is exactly why they ' +
        'reached a report whose window excluded them, and why taking them out of a narrowed window is a different ' +
        'change from clamping the polish',
    );
  }

  // --- PO17–PO19: an ACCEPTED placement on a wall says so (#737) ------------
  //
  // ⭐ #719 put the wall on a refusal and kept it off an accepted placement, on
  // the argument that a window chosen to bracket the answer puts correct
  // placements NEAR its edges. Near is not on, and that is measured rather than
  // argued: the refinement is clamped, so a value the window held IS the bound,
  // while a correct placement that settled inside stops short of it. These three
  // hold the mark to exactly the placements that stand on a wall — the card's
  // own frame, where the truth is past the ceiling; the closely bracketed ones,
  // which must stay unmarked; and a window with no interior, which has no wall.

  /**
   * The walls one reported placement stands on, derived here from the reported
   * numbers and the caller's own window — never from `placementWalls`, which is
   * the thing being checked. Equality is the whole test for the reason `wallsOf`
   * gives, and a `rotationFree` part's `0°` is a placeholder no window held.
   */
  const marksOf = (
    part: PoseReport['parts'][number],
    scale: { min: number; max: number },
    rotation: { minDeg: number; maxDeg: number },
  ): PoseWall[] => {
    const p = part.placement;
    if (p === null) return [];
    const out: PoseWall[] = [];
    if (scale.max > scale.min) {
      if (p.scale === scale.min) out.push({ axis: 'scale', edge: 'floor', window: `${scale.min},${scale.max}` });
      else if (p.scale === scale.max) out.push({ axis: 'scale', edge: 'ceiling', window: `${scale.min},${scale.max}` });
    }
    if (!part.rotationFree && rotation.maxDeg > rotation.minDeg && rotation.maxDeg - rotation.minDeg < 360) {
      const window = `${rotation.minDeg},${rotation.maxDeg}`;
      if (p.rotationDeg === rotation.minDeg) out.push({ axis: 'rotation', edge: 'floor', window });
      else if (p.rotationDeg === rotation.maxDeg) out.push({ axis: 'rotation', edge: 'ceiling', window });
    }
    return out;
  };
  const sayWall = (w: PoseWall): string => `the ${w.edge} of --${w.axis} ${w.window}`;
  /** The console line a part's own placement is printed on. */
  const placedLine = (lines: readonly string[], file: string): string =>
    lines.find((row) => /^ {2}(PLACE|AMBIG|REFUSE)/.test(row) && row.slice(9).startsWith(`${file} `)) ?? '';

  /**
   * Every part of one run against the walls its own placement stands on, in the
   * field, beside the value on the console line, and in the notes — two-sided,
   * so a mark missing from a wall and a mark on a placement that settled inside
   * are both faults.
   */
  const markFaults = (
    what: string,
    run: PoseReport,
    lines: readonly string[],
    scale: { min: number; max: number },
    rotation: { minDeg: number; maxDeg: number },
  ): string[] => {
    const faults: string[] = [];
    for (const part of run.parts) {
      const want = marksOf(part, scale, rotation);
      const got = part.walls ?? [];
      if (JSON.stringify(got) !== JSON.stringify(want)) {
        faults.push(`${what}: ${part.part} stands on ${want.length} wall(s) and its \`walls\` is ${JSON.stringify(got)}`);
      }
      if (part.placement === null || part.refusal !== null) continue;
      const line = placedLine(lines, part.part);
      const beside = (line.match(/ \(the (floor|ceiling) of --/g) ?? []).length;
      if (beside !== want.length) {
        faults.push(`${what}: ${part.part} stands on ${want.length} wall(s) and its console line names ${beside} — ${JSON.stringify(line.trim())}`);
      }
      for (const wall of want) {
        const value = wall.axis === 'scale' ? `scale=${part.placement.scale.toFixed(3)}` : `°`;
        if (!line.includes(`${value} (${sayWall(wall)})`)) {
          faults.push(`${what}: ${part.part}'s console line does not carry "(${sayWall(wall)})" beside its ${wall.axis} — ${JSON.stringify(line.trim())}`);
        }
      }
      const noted = part.notes.filter((n) => n.includes('stopped ON a wall')).length;
      if (noted !== (want.length > 0 ? 1 : 0)) {
        faults.push(`${what}: ${part.part} stands on ${want.length} wall(s) and ${noted} note(s) say it stopped on one`);
      }
    }
    return faults;
  };

  const doubledHead = 2;
  const doubled = buildPoseFixture(doubledHead);
  const doubledOut = join(doubled.dir, 'pose-doubled.json');
  const doubledRun = runCli(['pose', '--images', doubled.parts, '--frame', doubled.framePath, '--out', doubledOut]);
  const doubledReport = existsSync(doubledOut) ? (JSON.parse(readFileSync(doubledOut, 'utf8')) as PoseReport) : null;
  const doubledLines = doubledRun.stdout.split('\n');
  const defaultWindow = { min: DEFAULT_SCALE_MIN, max: DEFAULT_SCALE_MAX };

  // --- PO17: the card's frame marks the part the ceiling held ---------------
  {
    const probes: string[] = [];
    const truthHead = doubled.truth.get('head')?.scale ?? NaN;
    const reading = (run: PoseReport | null, lines: readonly string[]): string[] => {
      const faults: string[] = [];
      if (run === null) return [`no report was written to ${doubledOut}`];
      const head = run.parts.find((p) => p.part === 'head.png');
      if (head === undefined || head.placement === null) return ['head.png has no placement in the doubled frame'];
      if (head.refusal !== null) {
        faults.push(`head.png was refused rather than accepted, which is #719's case and not this one — ${head.refusal.detail}`);
      }
      const want = { axis: 'scale', edge: 'ceiling', window: `${DEFAULT_SCALE_MIN},${DEFAULT_SCALE_MAX}` };
      if (JSON.stringify(head.walls ?? []) !== JSON.stringify([want])) {
        faults.push(`head.png at scale ${head.placement.scale} carries walls ${JSON.stringify(head.walls ?? null)}`);
      }
      const line = placedLine(lines, 'head.png');
      const clause = `scale=${DEFAULT_SCALE_MAX.toFixed(3)} (the ceiling of --scale ${DEFAULT_SCALE_MIN},${DEFAULT_SCALE_MAX})`;
      if (!line.includes(clause)) faults.push(`the console line does not carry ${JSON.stringify(clause)} — ${JSON.stringify(line.trim())}`);
      if (!head.notes.some((n) => n.includes('stopped ON a wall') && n.includes(`the ceiling of --scale ${DEFAULT_SCALE_MIN},${DEFAULT_SCALE_MAX}`))) {
        faults.push(`no note on head.png says its placement stopped on the ceiling — ${JSON.stringify(head.notes)}`);
      }
      return faults;
    };
    if (doubledRun.status !== 0) probes.push(`pose on the doubled frame exited ${String(doubledRun.status)}`);
    if (!(truthHead > DEFAULT_SCALE_MAX)) {
      probes.push(`the doubled head's truth ${truthHead} is not above the default ceiling ${DEFAULT_SCALE_MAX}, so this frame no longer poses the case`);
    }
    const standing = reading(doubledReport, doubledLines);
    probes.push(...standing);
    // Two plants on the DATA the reading is taken from: the field emptied, and
    // the console line printed as the branch point printed it.
    if (doubledReport !== null) {
      const unmarked = structuredClone(doubledReport);
      for (const part of unmarked.parts) part.walls = [];
      if (raisedBy(reading(unmarked, doubledLines), { was: standing }).length === 0) {
        probes.push('a report whose head.png carries no `walls` was not caught');
      }
      const bare = doubledLines.map((row) => row.replace(/ \(the (floor|ceiling) of --\w+ [^)]*\)/g, ''));
      if (raisedBy(reading(doubledReport, bare), { was: standing }).length === 0) {
        probes.push('a console line with the wall clause stripped was not caught');
      }
    }
    const head = doubledReport?.parts.find((p) => p.part === 'head.png');
    const held = probes.length === 0;
    say(
      'PO17_AN_ACCEPTED_PLACEMENT_THE_WINDOW_HELD_ON_ITS_CEILING_SAYS_SO',
      held,
      probeDetail(
        held,
        probes,
        `one frame at 1.15 px/unit with the head drawn at scaleX/scaleY ${doubledHead}: truth ${to3(truthHead)}, ` +
          `accepted at residual ${head?.placement?.residual ?? 'n/a'} and printed ${JSON.stringify(placedLine(doubledLines, 'head.png').trim())}; ` +
          'the same report with `walls` emptied, and the same line with its clause stripped, are each faulted',
      ),
      'the report had the fact in hand and printed `PLACE head.png scale=2.000` over a part whose truth was 2.30 — ' +
        'an author reading it had no reason to suspect the number was the window\'s rather than the picture\'s',
    );
  }

  // --- PO18: the mark is on the wall and not near it -------------------------
  //
  // 🔒 The half that decides whether the mark is worth reading. A window whose
  // CEILING is each part's own truth brackets the answer as closely as a window
  // can, and the estimator settles a fraction inside it (its scale bias is low):
  // those are the legitimate near-edge placements #719 feared marking, and they
  // must carry nothing. Every part of every run is held two-sided — a missing
  // mark and a mark on a placement that settled inside are both faults.
  {
    const probes: string[] = [];
    const runs: { what: string; run: PoseReport; lines: string[]; scale: { min: number; max: number }; rotation: { minDeg: number; maxDeg: number } }[] = [
      { what: 'the fixture under the default window', run: report, lines: poseLines(report), scale: defaultWindow, rotation: FULL_TURN },
    ];
    if (doubledReport !== null) {
      runs.push({ what: 'the doubled frame under the default window', run: doubledReport, lines: doubledLines, scale: defaultWindow, rotation: FULL_TURN });
    }
    const near: string[] = [];
    for (const [file, slot] of [
      ['torso.png', 'torso'],
      ['head.png', 'head'],
      ['ball.png', 'ball'],
    ] as const) {
      const truth = want(slot).scale;
      const capped = { min: to3(truth / 1.5), max: to3(truth) };
      const run = estimatePose({ imagesDir: fixture.parts, framePath: fixture.framePath, parts: [partPath(file)], scale: capped });
      runs.push({ what: `${file} under --scale ${capped.min},${capped.max}, whose ceiling is its truth`, run, lines: poseLines(run), scale: capped, rotation: FULL_TURN });
      const p = run.parts[0]?.placement;
      if (run.parts[0]?.refusal === null && p != null && poseWithin(poseDelta(p, want(slot))) && p.scale < capped.max) {
        near.push(`${file} ${p.scale} (${((1 - p.scale / capped.max) * 100).toFixed(2)}% short of ${capped.max})`);
      }
    }
    if (near.length === 0) {
      probes.push('no correct placement settled close under a ceiling at its own truth, so this run cannot say "near" is left alone');
    }
    const standing = runs.flatMap((r) => markFaults(r.what, r.run, r.lines, r.scale, r.rotation));
    probes.push(...standing);
    // The two mutants the card names, planted on the reports rather than on the
    // reading: a module that marks every placement, and one that marks none.
    if (doubledReport !== null) {
      const everyone = structuredClone(doubledReport);
      for (const part of everyone.parts) {
        if (part.placement !== null) part.walls = [{ axis: 'scale', edge: 'ceiling', window: `${DEFAULT_SCALE_MIN},${DEFAULT_SCALE_MAX}` }];
      }
      const loud = markFaults('every placement marked', everyone, poseLines(everyone), defaultWindow, FULL_TURN);
      if (raisedBy(loud, { at: 'every placement marked' }).length === 0) probes.push('a report marking every placement was not caught');
      const none = structuredClone(doubledReport);
      for (const part of none.parts) part.walls = [];
      const quiet = markFaults('no placement marked', none, poseLines(none), defaultWindow, FULL_TURN);
      if (raisedBy(quiet, { at: 'no placement marked' }).length === 0) probes.push('a report marking no placement was not caught');
    }
    const marked = runs.reduce((n, r) => n + r.run.parts.filter((p) => (p.walls ?? []).length > 0).length, 0);
    const placed = runs.reduce((n, r) => n + r.run.parts.filter((p) => p.placement !== null).length, 0);
    const held = probes.length === 0;
    say(
      'PO18_A_PLACEMENT_THAT_SETTLED_INSIDE_THE_WINDOW_CARRIES_NO_MARK_HOWEVER_CLOSE_TO_A_WALL',
      held,
      probeDetail(
        held,
        probes,
        `${marked} of ${placed} placement(s) over ${runs.length} run(s) carry a wall, each the one its numbers stand on; ` +
          `under a ceiling at the part's own truth ${near.join(', ')} — correct, close, and unmarked; a report marking ` +
          'every placement and one marking none are each faulted',
      ),
      'a mark on every placement near an edge is a mark nobody reads, and a window chosen to bracket the answer puts ' +
        'correct placements there on purpose. The mark is worth reading only if it is on the wall and nowhere else',
    );
  }

  // --- PO19: a window with no interior has no wall to be at ------------------
  //
  // #719's rule, now held for an accepted placement too: being at the only value
  // a window has says nothing about where the answer is. The plant is the same
  // part at the same value as the FLOOR of a window that has an interior —
  // which the estimator's low scale bias holds there, and which is marked.
  {
    const probes: string[] = [];
    const truth = to3(want('head').scale);
    const pinned = { min: truth, max: truth };
    const upright = { minDeg: 0, maxDeg: 0 };
    const single = estimatePose({
      imagesDir: fixture.parts,
      framePath: fixture.framePath,
      parts: [partPath('head.png'), partPath('torso.png')],
      scale: pinned,
      rotation: upright,
    });
    probes.push(...markFaults(`--scale ${truth},${truth} --rotation 0,0`, single, poseLines(single), pinned, upright));
    const onBoth = single.parts.filter((p) => p.placement?.scale === truth && p.placement.rotationDeg === 0).length;
    if (onBoth !== single.parts.length) {
      probes.push(`only ${onBoth} of ${single.parts.length} part(s) sit at the window's one value, so the case is not the one named`);
    }
    const floored = { min: truth, max: to3(truth * 1.5) };
    const opened = estimatePose({
      imagesDir: fixture.parts,
      framePath: fixture.framePath,
      parts: [partPath('head.png')],
      scale: floored,
    });
    const openedWalls = opened.parts[0]?.walls ?? [];
    if (!openedWalls.some((w) => w.axis === 'scale' && w.edge === 'floor')) {
      probes.push(
        `head.png at the same value as the floor of --scale ${floored.min},${floored.max} was not marked on the floor ` +
          `(scale ${opened.parts[0]?.placement?.scale ?? 'n/a'}, walls ${JSON.stringify(openedWalls)}), so the plant was not caught`,
      );
    }
    const held = probes.length === 0;
    say(
      'PO19_A_WINDOW_WITH_NO_INTERIOR_MARKS_NOTHING',
      held,
      probeDetail(
        held,
        probes,
        `under --scale ${truth},${truth} --rotation 0,0 ${onBoth} part(s) sit at the window's only value and none is ` +
          `marked; the head at the same value as the floor of --scale ${floored.min},${floored.max} is marked ` +
          `${JSON.stringify(openedWalls.map((w) => sayWall(w)))}`,
      ),
      'a window that is one value is a caller fixing that value, not a search that ran into a bound — marking it ' +
        'would print a warning over the one placement the caller asked for exactly',
    );
  }

  // --- which of the two readings a refusal is (issue #857) -----------------
  //
  // ⭐ One synthetic frame, two parts, one sentence each. A plain block of one
  // colour is laid on the ground, and the two parts are the two ends of the
  // question the issue asked: a PLAIN part cut from inside that block — it fits
  // anywhere in it, so the search cannot tell its placements apart, and at
  // 40 px it is over the floor's span, so it is its plainness being read — and a
  // loud, large checker the frame does not hold at all. The first must be read
  // as "too small or too plain", the second as "the cut is the suspect", and
  // each sentence must carry the figures it was chosen by. `--scale 1,1` holds
  // the span at the part's own size, so which side of the floor each lands on
  // is a fact about the part rather than about a scale the search wandered to.
  {
    const dir = mkdtempSync(join(harnessTemp(), 'rigc-pose-legible-'));
    const plainColour: RGBA = [70, 120, 180, 255];
    const frame = new Plate(320, 240);
    for (let y = 0; y < frame.height; y++) for (let x = 0; x < frame.width; x++) frame.set(x, y, BACKGROUND);
    for (let y = 40; y < 200; y++) for (let x = 40; x < 280; x++) frame.set(x, y, plainColour);
    const framePath = join(dir, 'frame.png');
    frame.writePng(framePath);
    const plain = new Plate(40, 28);
    for (let y = 0; y < plain.height; y++) for (let x = 0; x < plain.width; x++) plain.set(x, y, plainColour);
    const plainPath = join(dir, 'plain.png');
    plain.writePng(plainPath);
    const loud = poseChecker(200, 150, [0, 0, 0, 255], [255, 255, 255, 255], 4);
    const loudPath = join(dir, 'loud.png');
    loud.writePng(loudPath);
    const read = estimatePose({ imagesDir: dir, framePath, parts: [plainPath, loudPath], scale: { min: 1, max: 1 } });
    const plainPart = read.parts.find((p) => p.part === 'plain.png');
    const loudPart = read.parts.find((p) => p.part === 'loud.png');
    const cli = runCli(['pose', '--images', dir, '--frame', framePath, '--scale', '1,1', '--out', join(dir, 'pose.json')]);
    // The guide teaches these two sentences by quoting them, so each control
    // also asks the page for its sentence verbatim: a reworded message goes red
    // here until §11.5 is reworded with it.
    const guide = readFileSync(resolve(import.meta.dir, 'docs/AUTHORING.md'), 'utf8');

    {
      const l = plainPart?.legibility ?? null;
      const reading = l?.reading ?? '';
      const figures = l === null ? [] : [`${l.width}x${l.height} px`, `texture ${l.texture}`, `${l.candidates} candidate(s)`];
      const ok =
        plainPart !== undefined &&
        (plainPart.ambiguous || plainPart.refusal !== null) &&
        l !== null &&
        l.texture === 0 &&
        l.floor === 'below' &&
        reading.includes('below the measured floor') &&
        reading.includes('too plain for pose') &&
        Math.max(l.width, l.height) >= POSE_FLOOR.span &&
        figures.every((f) => reading.includes(f)) &&
        cli.stdout.includes(reading) &&
        guide.includes(reading);
      say(
        'PO20_A_PLAIN_PART_THE_SEARCH_CANNOT_PIN_IS_READ_AS_BELOW_THE_FLOOR_WITH_ITS_FIGURES',
        ok,
        plainPart === undefined
          ? 'plain.png is not in the report'
          : `ambiguous=${plainPart.ambiguous} refused=${plainPart.refusal !== null} floor=${l?.floor ?? 'n/a'}; ` +
              `on the console: ${cli.stdout.includes(reading) && reading !== ''}, quoted in §11.5: ` +
              `${guide.includes(reading) && reading !== ''}; ${JSON.stringify(reading)}`,
        'a correct cut of a plain sleeve and a wrong part end in the same verdict; without the part\'s own size and ' +
          'texture beside the floor, the user cannot tell which one they are holding (issue #857)',
      );
    }
    {
      const l = loudPart?.legibility ?? null;
      const reading = l?.reading ?? '';
      const detail = loudPart?.refusal?.detail ?? '';
      const ok =
        loudPart !== undefined &&
        loudPart.refusal?.reason === 'no-match' &&
        l !== null &&
        l.floor === 'above' &&
        l.span === 200 &&
        reading.includes('above the measured floor') &&
        reading.includes('the cut (or the search window) is the suspect') &&
        reading.includes(`texture ${l.texture}`) &&
        detail.endsWith(reading) &&
        cli.stdout.includes(reading) &&
        guide.includes(reading);
      say(
        'PO21_A_LEGIBLE_PART_THAT_IS_REFUSED_NAMES_THE_CUT_AS_THE_SUSPECT',
        ok,
        loudPart === undefined
          ? 'loud.png is not in the report'
          : `${loudPart.refusal?.reason ?? 'accepted'} floor=${l?.floor ?? 'n/a'} span=${l?.span ?? 'n/a'}; ` +
              `in the detail: ${detail.endsWith(reading) && reading !== ''}, quoted in §11.5: ` +
              `${guide.includes(reading) && reading !== ''}; ${JSON.stringify(reading)}`,
        'the other half of the same sentence: a part with size and texture to spare that still matched nowhere is ' +
          'evidence about the cut, and calling it "too plain" would send the user to the wrong remedy',
      );
    }
    rmSync(dir, { recursive: true, force: true });
  }

  // --- PO22: three cells of the measured floor, re-measured -----------------
  //
  // 🔒 `POSE_FLOOR` is a number read off `tools/pose_floor.ts`'s grid, and a
  // number read off a run is a number that stops being true silently the day
  // the search changes. The full grid is hundreds of `pose` runs and is not a
  // control; these are three of its cells — one scene, one size, the plainest,
  // a blurred and the native texture — and they hold the two claims §11.5 makes:
  // the flat cell is below the floor, part for part, and places at most the
  // floor's own failure share; the native cell is above it for most of its
  // parts and places more than the floor's under-share. ⚠️ Fetched art, so an
  // absent `examples/` is a HOLE here and never a pass.
  if (!floorCorpusPresent(INGEST_CORPUS_ROOT)) {
    console.log(`  SKIP  PO22 did not run: no ${FLOOR_EXAMPLE} export under ${INGEST_CORPUS_ROOT}.`);
    console.log('          run `bun run fetch-examples` and re-run this suite.');
    console.log('          ⚠️ This is a HOLE in this run, not a pass — the floor §11.5 states was not re-measured at all.');
    console.log(`  SKIP  PO23–PO25 did not run: no ${FLOOR_EXAMPLE} export under ${INGEST_CORPUS_ROOT}.`);
    console.log('          ⚠️ A HOLE as well — the coarse pass (issue #865) was not measured on the art it was fixed on.');
    console.log(`  SKIP  PO28–PO30 did not run: no ${FLOOR_EXAMPLE} export under ${INGEST_CORPUS_ROOT}.`);
    console.log('          ⚠️ A HOLE as well — the refinement (issue #877) was not measured on the trials it was fixed on.');
  } else {
    const { posable, scenes } = loadFloorScenes(INGEST_CORPUS_ROOT);
    const scene = scenes.slice(0, 1);
    const slots = new Map(scene.map((sc) => [sc.name, floorSlots(posable, sc)]));
    const work = mkdtempSync(join(harnessTemp(), 'rigc-pose-floor-'));
    const cell = (texture: FloorTexture): FloorCell => floorCell(posable, scene, slots, 32, texture, work);
    const [flat, blurred, native] = [cell('flat'), cell('blur2'), cell('native')];
    rmSync(work, { recursive: true, force: true });
    const share = (c: FloorCell): number => c.found / Math.max(1, c.trials.length);
    const below = (c: FloorCell): number => c.trials.filter((t) => t.legibility?.floor === 'below').length;
    const probes: string[] = [];
    if (flat.trials.length === 0) probes.push('the flat cell took no trials');
    if (below(flat) !== flat.trials.length) probes.push(`${flat.trials.length - below(flat)} flat part(s) read as above the floor`);
    if (share(flat) > FLOOR_FAIL_RATE) probes.push(`the flat cell placed ${flat.found}/${flat.trials.length}, over the floor's ${FLOOR_FAIL_RATE}`);
    if (below(native) * 2 > native.trials.length) probes.push(`${below(native)}/${native.trials.length} native part(s) read as below the floor`);
    if (share(native) <= POSE_FLOOR.rateBelow) {
      probes.push(`the native cell placed ${native.found}/${native.trials.length}, no better than the floor's under-share ${POSE_FLOOR.rateBelow}`);
    }
    if (share(blurred) < share(flat)) probes.push(`the blurred cell placed fewer than the flat one`);
    const held = probes.length === 0;
    say(
      'PO22_THREE_CELLS_OF_THE_MEASURED_FLOOR_STILL_SAY_WHAT_THE_FLOOR_SAYS',
      held,
      probeDetail(
        held,
        probes,
        `${FLOOR_EXAMPLE} ${scene[0].name} at 32 px: flat ${flat.found}/${flat.trials.length} found, ${below(flat)} below the ` +
          `floor; blur2 ${blurred.found}/${blurred.trials.length}; native ${native.found}/${native.trials.length}, ` +
          `${native.trials.length - below(native)} above — against detail ${POSE_FLOOR.detail}, under-share ${POSE_FLOOR.rateBelow}`,
      ),
      'a floor is a measurement, and a measurement nobody repeats is a number that goes on being printed after the ' +
        'search it measured has changed underneath it',
    );

    // --- PO23–PO25: the coarse pass sends the true basin down (issue #865) --
    //
    // ⭐ The trial the card was opened on: the setup pose's front fist at 48 px,
    // native texture. On the quarter-span grid the truth scored 0.035 and the
    // search came back ambiguous between two placements 173 px off at 0.148 —
    // the basin fell between two anchor cells and, on its own rung, ranked
    // fifth. It must now be FOUND, which is neither ambiguous nor wrong.
    const fistDir = mkdtempSync(join(harnessTemp(), 'rigc-pose-fist-'));
    const fist = floorTrial(posable, scene[0], 'front-fist', 48, 'native', join(fistDir, 'a'));
    const fistAgain = floorTrial(posable, scene[0], 'front-fist', 48, 'native', join(fistDir, 'b'));
    rmSync(fistDir, { recursive: true, force: true });
    say(
      'PO23_THE_FIST_THE_COARSE_PASS_USED_TO_STEP_OVER_PLACES_AT_ITS_TRUTH',
      fist.outcome === 'found' && fist.error !== null && fist.error <= FLOOR_WITHIN_PX,
      `${FLOOR_EXAMPLE} ${scene[0].name} front-fist at 48 px, native: ${fist.outcome}, ` +
        `${fist.error === null ? 'nothing placed' : `${fist.error.toFixed(2)} px from the truth`} (bar ${FLOOR_WITHIN_PX} px); ` +
        `residual at the truth ${fist.truthResidual.toFixed(4)}, best reported ${fist.legibility?.best ?? 'n/a'}`,
      'a truth that scores four times better than the answer reported is the search failing, not the part — and the ' +
        'grid it was measured on is the only place that failure could be seen (issue #865)',
    );

    // ⭐ What the lever promises, stated on cells this suite already measured:
    // a failure that remains is not the SEARCH's. A trial is `missed` when the
    // truth scores better than everything reported and nothing reported is on
    // it; on the quarter grid the native gun in this very cell was one.
    const cells = [flat, blurred, native];
    const missed = cells.flatMap((c) => c.trials.filter((t) => t.missed).map((t) => `${c.texture} ${t.slot}`));
    const failed = cells.reduce((n, c) => n + c.trials.length - c.found, 0);
    say(
      'PO24_NO_FAILURE_IN_THE_MEASURED_FLOOR_CELLS_IS_A_TRUTH_THE_SEARCH_MISSED',
      missed.length === 0 && failed > 0,
      probeDetail(
        missed.length === 0 && failed > 0,
        missed.map((m) => `${m} at 32 px: the truth scores better than every placement reported and none is on it`),
        `${failed} failed trial(s) over the flat, blur2 and native cells at 32 px, none of them a search miss — each ` +
          'is the objective preferring another placement, or the truth reported and tied',
      ),
      'a failure the search could fix and a failure it cannot read the same in a table of found counts; only the ' +
        'residual at the truth tells them apart, and the floor is only a floor of plainness if the misses are gone',
    );

    const same = JSON.stringify(fist) === JSON.stringify(fistAgain);
    say(
      'PO25_THE_FINER_COARSE_GRID_READS_THE_SAME_TRIAL_TWICE_THE_SAME',
      same,
      `front-fist at 48 px run twice through the whole trial: ${same ? 'byte-identical' : 'DIFFERENT'} ` +
        `(${fist.outcome}, ${fist.error?.toFixed(3) ?? 'n/a'} px)`,
      'PO11 reads the fixture twice on the grid it happens to use; this reads twice a part whose answer depends on ' +
        'the finer grid and the wider minima list, so an order dependence in either would show here first',
    );

    // --- PO28–PO30: the refinement keeps the basin it reached (issue #877) --
    //
    // ⭐ The four trials #865's finer grid placed and then lost to the
    // refinement. Three reached full resolution with the truth's candidate
    // ranked first or second and stopped 1.6–3.8 px off it at a shrunk scale,
    // on a point every single-axis probe scores worse and a joint move scores
    // better; the fourth, the 24 px shin, had its truth's candidate ranked 15th
    // at the 2x level and cut. Each must now be FOUND — placed within the bar
    // and not ambiguous — rather than merely within 2 px of an answer.
    const walk = scenes.find((sc) => sc.name.startsWith('walk'));
    const lostDir = mkdtempSync(join(harnessTemp(), 'rigc-pose-877-'));
    const four: [string, string, number][] = [
      [scene[0].name, 'front-shin', 24],
      [walk?.name ?? '', 'front-upper-arm', 48],
      [walk?.name ?? '', 'goggles', 48],
      [scene[0].name, 'goggles', 96],
    ];
    const shinTrace: PoseTrace = { levels: [], measured: [] };
    const againTrace: PoseTrace = { levels: [], measured: [] };
    const placed = four.map(([frame, slot, size], i) => {
      const sc = scenes.find((x) => x.name === frame);
      if (sc === undefined) throw new Error(`internal: the floor corpus has no scene "${frame}"`);
      return { frame, slot, size, trial: floorTrial(posable, sc, slot, size, 'native', join(lostDir, String(i)), i === 0 ? shinTrace : undefined) };
    });
    const goggles = scenes.find((x) => x.name === four[3][0]);
    const gogglesAgain =
      goggles === undefined ? null : floorTrial(posable, goggles, 'goggles', 96, 'native', join(lostDir, 'again'), againTrace);
    rmSync(lostDir, { recursive: true, force: true });
    const fourOk = placed.every((p) => p.trial.outcome === 'found' && p.trial.error !== null && p.trial.error <= FLOOR_WITHIN_PX);
    say(
      'PO28_THE_FOUR_TRIALS_THE_REFINEMENT_LOST_AFTER_865_PLACE_AT_THEIR_TRUTH',
      fourOk,
      probeDetail(
        fourOk,
        placed
          .filter((p) => !(p.trial.outcome === 'found' && p.trial.error !== null && p.trial.error <= FLOOR_WITHIN_PX))
          .map(
            (p) =>
              `${p.frame} ${p.slot} at ${p.size} px, native: ${p.trial.outcome}, ` +
              `${p.trial.error === null ? 'nothing placed' : `${p.trial.error.toFixed(2)} px`} (bar ${FLOOR_WITHIN_PX} px), ` +
              `truth ${p.trial.truthResidual.toFixed(4)} against best ${p.trial.legibility?.best ?? 'n/a'}`,
          ),
        placed.map((p) => `${p.frame} ${p.slot} ${p.size} px: ${p.trial.error?.toFixed(2) ?? 'n/a'} px`).join('; ') +
          ` — every one found, within ${FLOOR_WITHIN_PX} px and not ambiguous`,
      ),
      'a basin the search reached and then walked out of is the search failing on the last step it takes, and these ' +
        'four are where #865 measured it doing so',
    );

    // The shin was the one lost to the cutoff rather than to a polish, so this
    // reads WHERE it survived: its truth's candidate ranks past twelve at some
    // level — the count this was before #877 — and the next level still takes it.
    const OLD_REFINE_CANDIDATES = 12;
    const shin = placed[0].trial;
    const past = shin.search.findIndex((l) => l.rank >= OLD_REFINE_CANDIDATES && l.carried && l.distance <= FLOOR_WITHIN_PX);
    const carriedOk = past >= 0 && shin.outcome === 'found';
    say(
      'PO29_A_CANDIDATE_RANKED_PAST_THE_OLD_TWELVE_IS_CARRIED_TO_THE_ANSWER',
      carriedOk,
      carriedOk
        ? `${placed[0].frame} front-shin at 24 px: the truth's candidate ranks #${shin.search[past].rank} at the ` +
            `${shin.search[past].reduction}x level, ${shin.search[past].distance.toFixed(2)} px off, is carried, and the trial ` +
            `is found ${shin.error?.toFixed(2)} px from the truth`
        : `${placed[0].frame} front-shin at 24 px: ${shin.outcome}; per level ${searchLine(shin)}`,
      'a cutoff by rank is a guess about which candidates can still win, and on this trial the one it cut was the ' +
        'truth — the rank is read off the trace, so the survival is measured rather than inferred from the answer',
    );

    const traceSame = gogglesAgain !== null && JSON.stringify(placed[3].trial) === JSON.stringify(gogglesAgain);
    say(
      'PO30_THE_ESCAPING_POLISH_READS_THE_SAME_TRIAL_TWICE_THE_SAME',
      traceSame && againTrace.levels.length > 0,
      `${four[3][0]} goggles at 96 px, native, run twice through the whole trial (the second with a trace kept): ` +
        `${traceSame ? 'byte-identical' : 'DIFFERENT'} (${placed[3].trial.outcome}, ${placed[3].trial.error?.toFixed(3) ?? 'n/a'} px, ` +
        `${againTrace.levels.length} level(s) traced)`,
      'the escape restarts a polish from a point chosen by comparing residuals, which is exactly where an order ' +
        'dependence would enter; this trial takes that path, so it would show here first',
    );
  }

  // --- PO31–PO32: the stationary post MOTION.md §6 reads (issue #886) ------
  //
  // ⭐ Natural art rather than a grid trial, and self-contained: the page's own
  // `bun -e` fences carry the three plates and the two pictures as base64, so
  // this reads them out of `docs/MOTION.md` and writes them where §6 does. On
  // pose A under `--scale 0.85,1.2` the page recorded the post at (79.9, 148.6),
  // -0.1°, scale 0.975, residual 0.0589 — the answer of the search before
  // issue #876, measured with the objective this one uses. After #876 and #877
  // the search settled at scale 0.917, 2.25 px off, at 0.0649, while the old
  // placement still scores 0.0589: a miss by the objective's own measure. The
  // half-rung escape stepped from 0.917 to 1.029, past the basin and onto the
  // cliff a part that fills its image has above its truth; the quarter lands in
  // it. The bar is the grid's own `FLOOR_WITHIN_PX` from the old placement and a
  // residual within a tenth of `AMBIGUITY_ABSOLUTE` of what the old placement
  // scores — main's answer fails both (2.25 px, 0.0060 above), the lever passes
  // both (0.10 px, 0.0004). The old placement is scored through the trace's
  // probe at full resolution, whose sample set is every pixel of this part:
  // 14x96 is 1,344 pixels, under the 2,048 the polish level samples.
  {
    const page = readFileSync(resolve(import.meta.dir, 'docs/MOTION.md'), 'utf8');
    const fence = (name: string): Buffer | null => {
      const m = page.match(new RegExp(`"${name.replace(/[.]/g, '\\.')}": "([A-Za-z0-9+/=]+)"`));
      return m === null ? null : Buffer.from(m[1], 'base64');
    };
    const files = ['parts/post.png', 'parts/arm.png', 'parts/flag.png', 'poseA.png'];
    const missing = files.filter((f) => fence(f) === null);
    const dir = mkdtempSync(join(harnessTemp(), 'rigc-pose-886-'));
    mkdirSync(join(dir, 'parts'));
    for (const f of files) {
      const bytes = fence(f);
      if (bytes !== null) writeFileSync(join(dir, f), bytes);
    }
    const old = { x: 79.9, y: 148.6, rotationDeg: -0.1, scale: 0.975 };
    const read = (trace?: PoseTrace): PoseReport | null =>
      missing.length > 0
        ? null
        : estimatePose({ imagesDir: join(dir, 'parts'), framePath: join(dir, 'poseA.png'), scale: { min: 0.85, max: 1.2 }, trace });
    const trace: PoseTrace = { probe: old, levels: [], measured: [] };
    const first = read(trace);
    const again = read();
    rmSync(dir, { recursive: true, force: true });
    const post = first?.parts.find((p) => p.part === 'post.png')?.placement ?? null;
    const levels = trace.levels.filter((l) => l.part === 'post.png');
    const full = levels.find((l) => l.level === 0) ?? null;
    const atOld = full?.probeResidual ?? null;
    const off = post === null ? null : Math.hypot(post.x - old.x, post.y - old.y);
    const gap = post === null || atOld === null ? null : post.residual - atOld;
    const bar = AMBIGUITY_ABSOLUTE / 10;
    const ok = post !== null && off !== null && gap !== null && off <= FLOOR_WITHIN_PX && gap <= bar;
    say(
      'PO31_THE_STATIONARY_POST_OF_MOTION_6_IS_PLACED_WHERE_THE_OLD_SEARCH_FOUND_IT',
      ok,
      missing.length > 0
        ? `docs/MOTION.md no longer carries ${missing.join(', ')} in a fence, so §6's inputs cannot be rebuilt`
        : post === null || off === null || gap === null
          ? `post.png: no placement, or no full-resolution probe in the trace (${levels.length} level(s) traced)`
          : `post.png on pose A, --scale 0.85,1.2: x ${post.x} y ${post.y} rot ${post.rotationDeg}° scale ${post.scale}, ` +
            `residual ${post.residual}; the old placement (${old.x}, ${old.y}, ${old.rotationDeg}°, ${old.scale}) scores ` +
            `${atOld?.toFixed(5)} — ${off.toFixed(2)} px from it (bar ${FLOOR_WITHIN_PX} px) and ${gap.toFixed(5)} above it ` +
            `(bar ${bar})`,
      'a placement the objective scores lower was inside the window the caller named, and the search settled beside it; ' +
        'a caller reading a stationary part twice then sees 0.917 and 0.995 and has no way to tell a miss from a moved part',
    );

    // The new path must be the one taken, or the pass above says nothing about
    // it: the winning full-resolution polish accepted an escape by the quarter
    // rung. And, as PO30 does for the half, the whole read twice is the same.
    const quarter = 2 ** (1 / (4 * SCALE_STEPS_PER_OCTAVE)) - 1;
    const winner = full === null || full.polished.length === 0 ? -1 : full.polished.reduce((bi, c, i, a) => (c.residual < a[bi].residual ? i : bi), 0);
    const escaped = full !== null && winner >= 0 && full.paths[winner].some((s) => s.escape && Math.abs(s.scale - quarter) < 1e-9);
    const same = first !== null && again !== null && JSON.stringify(first.parts) === JSON.stringify(again.parts);
    say(
      'PO32_THE_QUARTER_RUNG_ESCAPE_IS_TAKEN_AND_READS_THE_SAME_TWICE',
      escaped && same,
      `post.png's winning full-resolution polish ${escaped ? 'took' : 'did NOT take'} a scale escape of ${quarter.toFixed(4)}; ` +
        `the three parts read twice: ${same ? 'byte-identical' : 'DIFFERENT'}`,
      'the escape picks the better of two re-fits by comparing residuals, which is where an order dependence would enter, ' +
        'and a control that passes without the new path being taken holds nothing about it',
    );
  }

  // --- PO26–PO27: the refinement, read through its trace (issue #877) -----
  //
  // 🔍 The card said the polish "leaves a basin it is in and settles on a worse
  // residual", and named two cures: never accept a worse residual, or restart
  // from the best point seen. The trace answered it before either was built: a
  // polish accepts a probe only when it scores strictly lower on its own level's
  // objective, so a rise from one level to the next is a change of objective
  // (another sample set on another plate), never a step taken uphill. This holds
  // the invariant that made the card's first cure unnecessary — on the fixture,
  // no generated art needed — and holds the trace to not changing the answer.
  {
    const trace: PoseTrace = { levels: [], measured: [] };
    const traced = estimatePose({ imagesDir: fixture.parts, framePath: fixture.framePath, trace });
    const found = polishRegressions(trace);
    const polishes = trace.levels.reduce((n, l) => n + l.paths.length, 0);
    const steps = trace.levels.reduce((n, l) => n + l.paths.reduce((m, p) => m + p.length, 0), 0);
    // The same reader must name a polish forged to walk uphill, or its silence
    // above says nothing. The first polish that moved at all gets its first
    // step pushed above where it started.
    const forged: PoseTrace = JSON.parse(JSON.stringify(trace)) as PoseTrace;
    const moved = forged.levels.find((l) => l.paths.some((p) => p.length > 0));
    const seed = moved === undefined ? -1 : moved.paths.findIndex((p) => p.length > 0);
    if (moved !== undefined) moved.paths[seed][0].residual = moved.starts[seed] + 0.01;
    const caught = polishRegressions(forged);
    const held = found.length === 0 && steps > 0 && moved !== undefined && caught.length > 0;
    say(
      'PO26_NO_POLISH_ENDS_ON_A_WORSE_RESIDUAL_THAN_IT_STARTED_FROM',
      held,
      probeDetail(
        held,
        [
          ...found,
          ...(steps === 0 ? ['the trace recorded no accepted move at all, so there was nothing to hold'] : []),
          ...(moved !== undefined && caught.length === 0 ? ['a polish forged to walk uphill was not named'] : []),
        ],
        `${polishes} polish(es) over ${trace.levels.length} level(s) of ${traced.parts.length} part(s), ${steps} accepted ` +
          `move(s), every one strictly below the point before it; a forged uphill step is named: ${caught[0] ?? 'n/a'}`,
      ),
      'a search that could report a point worse than one it had already stood on is a search whose answer depends on ' +
        'where it happened to stop — and it is the premise issue #877 opened on, measured false before any cure was built',
    );

    const plain = JSON.stringify(report.parts);
    const same = JSON.stringify(traced.parts) === plain;
    const narrowed = estimatePose({ imagesDir: fixture.parts, framePath: fixture.framePath, trace: { levels: [], measured: [] }, rotation: { minDeg: -5, maxDeg: 5 } });
    const differs = JSON.stringify(narrowed.parts) !== plain;
    say(
      'PO27_A_TRACED_SEARCH_REPORTS_WHAT_AN_UNTRACED_ONE_DOES',
      same && differs,
      `${traced.parts.length} part(s) read with a trace and without: ${same ? 'byte-identical' : 'DIFFERENT'}; ` +
        `the same comparison on a run with the rotation window narrowed to -5,5: ${differs ? 'different, as it must be' : 'IDENTICAL — the comparison cannot fail'}`,
      'the trace is an instrument pointed at the search, and an instrument that moves what it measures reports a ' +
        'search nobody ran without it',
    );

    // --- PO33: the coarse row the trace keeps is the field's own (issue #892) --
    //
    // 🔍 The measurement #892 asked for — how often the seed nearest the truth
    // reaches refinement carrying a half-turn, and by how much the truth's
    // rotation lost its cell — is read off `coarseRotations`, which the trace
    // recomputes rather than copies out of the field. So the row is only
    // evidence if it IS the field: every coarse seed's carried rung must be the
    // least value of its row and equal the residual the seed carries, bit for
    // bit. A row forged to put another rung below the carried one must be named.
    {
      const rows = trace.levels.filter((l) => l.coarseRotations !== null);
      const seeds = rows.reduce((n, l) => n + l.seeds.length, 0);
      const found = coarseRowDisagreements(trace);
      const forged: PoseTrace = JSON.parse(JSON.stringify(trace)) as PoseTrace;
      const target = forged.levels.find((l) => l.coarseRotations !== null && l.coarseRotations.ladder.length > 1 && l.seeds.length > 0);
      if (target !== undefined && target.coarseRotations !== null) {
        const row = target.coarseRotations.residuals[0];
        const carried = target.coarseRotations.ladder.findIndex((r) => Math.abs(normaliseDegrees(r) - target.seeds[0].rotationDeg) < 1e-9);
        row[carried === 0 ? 1 : 0] = target.seeds[0].residual / 2;
      }
      const caught = coarseRowDisagreements(forged);
      const held = found.length === 0 && seeds > 0 && target !== undefined && caught.length > 0;
      say(
        'PO33_THE_TRACED_COARSE_ROW_IS_THE_FIELD_EACH_SEED_WAS_PICKED_FROM',
        held,
        probeDetail(
          held,
          [
            ...found,
            ...(seeds === 0 ? ['the trace recorded no coarse row at all, so there was nothing to hold'] : []),
            ...(target === undefined ? ['no coarse row had two rungs to forge'] : []),
            ...(target !== undefined && caught.length === 0 ? ['a row forged to put another rung below the carried one was not named'] : []),
          ],
          `${seeds} coarse seed(s) over ${rows.length} part(s): each carries the least rung of its traced row, at the residual ` +
            `it was handed down with; a forged row is named: ${caught[0] ?? 'n/a'}`,
        ),
        'a rotation table read off a row the search never used would measure an arithmetic nobody ran — and the ' +
          'table is what decided that the coarse field needs no second rotation (issue #892)',
      );
    }
  }

  return bad;
}

/**
 * Every coarse seed whose traced row disagrees with the field it came from: the
 * rung it carries is not the least of its row, or its value there is not the
 * residual the seed was handed down with — by part and seed.
 */
function coarseRowDisagreements(trace: PoseTrace): string[] {
  const out: string[] = [];
  for (const level of trace.levels) {
    const rows = level.coarseRotations;
    if (rows === null) continue;
    level.seeds.forEach((seed, i) => {
      const row = rows.residuals[i];
      const at = rows.ladder.findIndex((r) => Math.abs(normaliseDegrees(r) - seed.rotationDeg) < 1e-9);
      const least = Math.min(...row);
      if (at < 0) out.push(`${level.part} coarse seed ${i}: carries ${seed.rotationDeg}°, which is not a rung of the ladder`);
      else if (row[at] !== seed.residual) out.push(`${level.part} coarse seed ${i}: its row reads ${row[at]} at ${seed.rotationDeg}°, the seed carries ${seed.residual}`);
      else if (row[at] !== least) {
        out.push(`${level.part} coarse seed ${i}: carries ${seed.rotationDeg}° at ${row[at].toFixed(5)}, but its row has ${least.toFixed(5)} at ${rows.ladder[row.indexOf(least)]}°`);
      }
    });
  }
  return out;
}

/**
 * Every polish in a trace that took a step no lower than the point before it,
 * or ended anywhere but on its last accepted point — by part, level and seed.
 */
function polishRegressions(trace: PoseTrace): string[] {
  const out: string[] = [];
  for (const level of trace.levels) {
    level.paths.forEach((path, seed) => {
      let before = level.starts[seed];
      path.forEach((step, k) => {
        if (!(step.residual < before)) {
          out.push(`${level.part} level ${level.level} seed ${seed} step ${k}: ${step.residual.toFixed(5)} after ${before.toFixed(5)}`);
        }
        before = step.residual;
      });
      if (level.polished[seed].residual !== before) {
        out.push(
          `${level.part} level ${level.level} seed ${seed}: ended at ${level.polished[seed].residual.toFixed(5)}, ` +
            `its last accepted point ${before.toFixed(5)}`,
        );
      }
    });
  }
  return out;
}

// ---------------------------------------------------------------------------
// the pose oracle: tools/pose_oracle.ts, held the way pose_floor is (issue #909)
// ---------------------------------------------------------------------------

/** The oracle's command in a child process, as a caller runs it. */
function runOracle(args: string[]): { status: number | null; stdout: string; stderr: string } {
  const result = spawnSync(process.execPath, ['tools/pose_oracle.ts', ...args], { cwd: import.meta.dir, encoding: 'utf8' });
  return { status: result.status, stdout: result.stdout, stderr: result.stderr };
}

/**
 * The bone a planted setup rotation should be named by: the last bone in
 * skeleton order that no other bone reads — it has no child, and no constraint
 * takes it as its target, source, slot bone or slider bone. A physics
 * constraint's own bone qualifies, since under `Physics.none` the constraint
 * does nothing. Chosen off the skeleton rather than by name, so the plant does
 * not know which rig it is in.
 */
function unreadBone(data: SkeletonData): string | null {
  const read = new Set<string>();
  for (const bone of data.bones) if (bone.parent) read.add(bone.parent.name);
  for (const c of data.constraints) {
    if (c instanceof IkConstraintData) read.add(c.target.name);
    else if (c instanceof TransformConstraintData) read.add(c.source.name);
    else if (c instanceof PathConstraintData) read.add(c.slot.boneData.name);
    else if (c instanceof SliderData && c.bone !== null) read.add(c.bone.name);
  }
  const candidates = data.bones.filter((b) => b.parent !== null && !read.has(b.name));
  return candidates.length === 0 ? null : candidates[candidates.length - 1].name;
}

function runPoseOracleSuite(): number {
  console.log('\n── pose-oracle: the exam\'s pose oracle in the tree, dumped, compared and graded (issue #909) ──');
  let bad = 0;
  const say = (name: string, ok: boolean, detail: string, why: string): void => {
    bad += reportCase(name, ok, detail, why);
  };
  const tol = { xy: ORACLE_DEFAULT_TOL, m: ORACLE_DEFAULT_TOL };

  // The build every generated row reads: the ingest coverage probe, through
  // `rigc build` itself, so the directory is the one the command writes. It
  // is the rig in this file that carries every field the dump added — a mesh
  // and a linked mesh, a clipping attachment, an event, a draw-order key, two
  // dark colours, a physics constraint and a second skin.
  const probe = writeIngestProbe();
  // Inside the probe's own directory (issue #1127), so the build's page names spell no temp directory.
  const work = buildRootFor(probe.home, 'rigc-pose-oracle-');
  const buildDir = join(work, 'build');
  const built = runCli(['build', '--rig', probe.rigPath, '--motion', probe.motionPath, '--out', buildDir, ...(probe.imagesDir === undefined ? [] : ['--images', probe.imagesDir])]);
  const buildOk = built.status === 0 && existsSync(join(buildDir, 'skeleton.json')) && existsSync(join(buildDir, 'skeleton.atlas'));
  const dumpAt = (dir: string, out: string, extra: string[] = []): ReturnType<typeof runOracle> => runOracle(['dump', dir, '--out', out, ...extra]);
  const readDump = (path: string): OracleDump | null => (existsSync(path) ? asOracleDump(JSON.parse(readFileSync(path, 'utf8')), path) : null);

  // --- POR01: two dumps of one build are byte-identical, and they carry every field --
  const noneA = join(work, 'none-a.json');
  const noneB = join(work, 'none-b.json');
  const stepA = join(work, 'step-a.json');
  const stepB = join(work, 'step-b.json');
  const runs = buildOk
    ? [dumpAt(buildDir, noneA), dumpAt(buildDir, noneB), dumpAt(buildDir, stepA, ['--physics', 'step']), dumpAt(buildDir, stepB, ['--physics', 'step'])]
    : [];
  const none = readDump(noneA);
  const step = readDump(stepA);
  {
    const probes: string[] = [];
    if (!buildOk) probes.push(`rigc build of the probe did not write a build: exit ${built.status}, ${built.stderr.slice(0, 200)}`);
    runs.forEach((run, i) => {
      if (run.status !== 0) probes.push(`dump ${i + 1} exited ${run.status}: ${run.stderr.slice(0, 200)}`);
    });
    const same = (a: string, b: string): boolean => existsSync(a) && existsSync(b) && readFileSync(a).equals(readFileSync(b));
    if (buildOk && !same(noneA, noneB)) probes.push('two --physics none dumps of one build differ in their bytes');
    if (buildOk && !same(stepA, stepB)) probes.push('two --physics step dumps of one build differ in their bytes');
    const samples = none === null ? [] : [none.setup, ...none.animations.flatMap((a) => a.samples)];
    const count = {
      meshes: samples.reduce((s, x) => s + x.attachments.filter((a) => a[2] === 'mesh').length, 0),
      regions: samples.reduce((s, x) => s + x.attachments.filter((a) => a[2] === 'region').length, 0),
      clips: samples.reduce((s, x) => s + x.clips.length, 0),
      events: none === null ? 0 : none.animations.flatMap((a) => a.samples).reduce((s, x) => s + x.events.length, 0),
      darks: samples.reduce((s, x) => s + x.slots.filter((slot) => slot[6] !== null).length, 0),
      physics: none?.physics.length ?? 0,
      skins: none?.skins.length ?? 0,
    };
    for (const [field, n] of Object.entries(count)) {
      if (none !== null && n === 0) probes.push(`the dump carries no ${field}, so its byte identity says nothing about them`);
    }
    if (none !== null && count.skins < 2) probes.push(`the dump names ${count.skins} skin(s); the probe declares two`);
    const held = probes.length === 0;
    say(
      'POR01_TWO_DUMPS_OF_ONE_BUILD_ARE_BYTE_IDENTICAL_UNDER_BOTH_PHYSICS_MODES',
      held,
      probeDetail(
        held,
        probes,
        `the ingest coverage probe, built by \`rigc build\` and dumped four times: ${existsSync(noneA) ? statSync(noneA).size : 0} bytes under ` +
          `--physics none twice and ${existsSync(stepA) ? statSync(stepA).size : 0} under --physics step twice, each pair equal to the byte, over ` +
          `${none?.bones.length} bones, ${count.regions} region and ${count.meshes} mesh vertex rows, ${count.clips} clip ` +
          `polygon(s), ${count.events} fired event(s), ${count.darks} dark colour(s), ${count.physics} physics block(s) ` +
          `and ${count.skins} skins`,
      ),
      'the brief\'s row (a), and the contract a second dumper is held to: the document is only comparable byte for ' +
        'byte if the same input writes the same bytes, and a determinism claim over fields the dump did not carry would ' +
        'be a claim about nothing — so the fields are counted beside it',
    );
  }

  // --- POR02: a dump compared with itself reads IDENTICAL and exits 0 --
  {
    const probes: string[] = [];
    const cases = buildOk ? [noneA, stepA].map((p) => [p, runOracle(['compare', p, p === noneA ? noneB : stepB])] as const) : [];
    for (const [path, run] of cases) {
      const last = run.stdout.trim().split('\n').pop() ?? '';
      if (run.status !== 0) probes.push(`${basename(path)} against its twin exited ${run.status}: ${run.stderr.slice(0, 200)}`);
      if (!last.startsWith('IDENTICAL')) probes.push(`${basename(path)} against its twin ended ${JSON.stringify(last)}`);
    }
    if (!buildOk) probes.push('no build to dump');
    const held = probes.length === 0;
    say(
      'POR02_A_DUMP_COMPARED_WITH_ITS_TWIN_READS_IDENTICAL_AND_EXITS_0',
      held,
      probeDetail(
        held,
        probes,
        `both twins compared through the command: exit 0, ${cases.map(([, run]) => run.stdout.trim().split('\n').pop()).join(' / ')}`,
      ),
      'the positive control the mutants below stand beside: a comparator that never said IDENTICAL would name every ' +
        'plant and prove nothing about any of them',
    );
  }

  // --- POR03: one bone's setup rotation moved 1°, named by bone, animation and sample --
  {
    const probes: string[] = [];
    const skeletonText = buildOk ? readFileSync(join(buildDir, 'skeleton.json'), 'utf8') : '';
    const atlasText = buildOk ? readFileSync(join(buildDir, 'skeleton.atlas'), 'utf8') : '';
    const data = buildOk ? loadOracleData(skeletonText, atlasText, 'the probe build') : null;
    const bone = data === null ? null : unreadBone(data);
    let run: ReturnType<typeof runOracle> | null = null;
    let named = 0;
    let rows = 0;
    if (data !== null && bone === null) probes.push('the probe has no bone that no other bone or constraint reads');
    if (data !== null && bone !== null) {
      const raw = JSON.parse(skeletonText) as { bones: Array<{ name: string; rotation?: number }> };
      const was = raw.bones.find((b) => b.name === bone)?.rotation ?? 0;
      const mutantDir = join(work, 'mutant');
      mkdirSync(mutantDir, { recursive: true });
      writeFileSync(join(mutantDir, 'skeleton.json'), writeBoneRotation(skeletonText, bone, was + 1));
      writeFileSync(join(mutantDir, 'skeleton.atlas'), atlasText);
      const mutantPath = join(work, 'mutant.json');
      const dumped = dumpAt(mutantDir, mutantPath);
      if (dumped.status !== 0) probes.push(`the mutant did not dump: ${dumped.stderr.slice(0, 200)}`);
      run = runOracle(['compare', noneA, mutantPath]);
      if (run.status !== 1) probes.push(`compare exited ${run.status} on the mutant, not 1`);
      if (!run.stdout.includes(`DIFF — first difference: the setup pose: bone "${bone}"`)) {
        probes.push(`the verdict line does not name bone "${bone}" at the setup pose: ${JSON.stringify(run.stdout.trim().split('\n').pop())}`);
      }
      const mutant = readDump(mutantPath);
      if (none !== null && mutant !== null) {
        const c = compareDumps(none, mutant, tol);
        for (const row of c.rows) {
          rows++;
          const sample = row.name === '(setup)' ? 'the setup pose' : `animation "${row.name}" t=${none.animations.find((a) => a.name === row.name)?.samples[0]?.t}`;
          const first = row.findings[0] ?? '';
          if (first.startsWith(`${sample}: bone "${bone}"`)) named++;
          else probes.push(`${row.name}: the first difference is ${JSON.stringify(first.slice(0, 160))}, not bone "${bone}" at ${sample}`);
          if (!run.stdout.includes(row.name === '(setup)' ? '(setup)' : JSON.stringify(row.name))) probes.push(`the printed report has no row for ${row.name}`);
        }
      }
    }
    const held = probes.length === 0 && rows > 0;
    say(
      'POR03_A_SETUP_ROTATION_MOVED_ONE_DEGREE_IS_NAMED_BY_BONE_ANIMATION_AND_SAMPLE',
      held,
      probeDetail(
        held,
        probes,
        `bone "${bone}" — the last bone no other bone or constraint reads — turned 1° in a copy of the build: compare ` +
          `exits 1, and the first difference in each of the ${rows} row(s) (the setup pose and every animation) is that ` +
          `bone at that row's first sample (${named}/${rows})`,
      ),
      'the brief\'s row (b): the smallest plant a rig spec could plausibly carry by mistake, and the three names an ' +
        'agent needs to act on it. The bone is the last one nothing else reads, so being FIRST in every row is a claim ' +
        'the comparator has to earn — any bone ahead of it in skeleton order that moved would be a comparator that ' +
        'reports noise',
    );
  }

  // --- POR04: a planted difference in each field the dump added is named, alone --
  {
    const probes: string[] = [];
    const planted: string[] = [];
    const nudge = 2 / ORACLE_GRID;
    const plant = (label: string, edit: (d: OracleDump) => string | null, expect: string): void => {
      if (none === null) return;
      const copy = JSON.parse(JSON.stringify(none)) as OracleDump;
      const miss = edit(copy);
      if (miss !== null) {
        probes.push(`${label}: ${miss}`);
        return;
      }
      const c = compareDumps(none, copy, tol);
      const all = [...c.document, ...c.rows.flatMap((r) => r.findings)];
      if (c.identical) probes.push(`${label}: compare read IDENTICAL over the plant`);
      else if (all.length !== 1) probes.push(`${label}: ${all.length} differences named, not the one planted: ${all.slice(0, 3).join(' | ')}`);
      else if (!all[0].includes(expect)) probes.push(`${label}: named ${JSON.stringify(all[0].slice(0, 160))}, which does not say ${JSON.stringify(expect)}`);
      else planted.push(label);
    };
    const firstSample = (d: OracleDump, has: (s: OracleSample) => boolean): OracleSample | null =>
      d.animations.flatMap((a) => a.samples).find(has) ?? null;
    plant('a mesh vertex moved 2e-6', (d) => {
      const s = firstSample(d, (x) => x.attachments.some((a) => a[2] === 'mesh'));
      const row = s?.attachments.find((a) => a[2] === 'mesh');
      if (!row || row[3][0] === null) return 'no mesh row to plant into';
      row[3][0] = (row[3][0] as number) + nudge;
      return null;
    }, 'vertex 0 moved 0.000002');
    plant('two draw-order entries swapped', (d) => {
      const s = firstSample(d, (x) => x.drawOrder.length >= 2);
      if (!s) return 'no draw order of two slots';
      [s.drawOrder[0], s.drawOrder[1]] = [s.drawOrder[1], s.drawOrder[0]];
      return null;
    }, 'draw order differs from position 0');
    plant('a fired event renamed', (d) => {
      const s = firstSample(d, (x) => x.events.length > 0);
      if (!s) return 'no sample fires an event';
      s.events[0][0] = `${s.events[0][0]}_renamed`;
      return null;
    }, 'events fired');
    plant('a clip polygon vertex moved 2e-6', (d) => {
      const s = firstSample(d, (x) => x.clips.length > 0);
      if (!s || s.clips[0][3][0] === null) return 'no clip to plant into';
      s.clips[0][3][0] = (s.clips[0][3][0] as number) + nudge;
      return null;
    }, 'vertex 0 moved 0.000002');
    plant('a clip end slot changed', (d) => {
      const s = firstSample(d, (x) => x.clips.length > 0);
      if (!s) return 'no clip to plant into';
      s.clips[0][2] = `${s.clips[0][2]}_elsewhere`;
      return null;
    }, 'end slot');
    plant('a dark colour moved 2e-6', (d) => {
      const s = firstSample(d, (x) => x.slots.some((slot) => slot[6] !== null && slot[6][0] !== null && (slot[6][0] as number) < 1));
      const slot = s?.slots.find((x) => x[6] !== null && x[6][0] !== null && (x[6][0] as number) < 1);
      if (!slot || slot[6] === null) return 'no dark colour below 1 to plant into';
      slot[6][0] = (slot[6][0] as number) + nudge;
      return null;
    }, 'dark colour');
    const held = probes.length === 0 && planted.length > 0;
    say(
      'POR04_A_PLANT_IN_EACH_FIELD_THE_DUMP_ADDED_IS_NAMED_AND_NOTHING_ELSE_IS',
      held,
      probeDetail(
        held,
        probes,
        `${planted.length} plants, each at two steps of the grid, each the ONE difference compare names: ${planted.join('; ')}`,
      ),
      'the dump grew five kinds of number the prototype never compared — world vertices, draw order, events, clip ' +
        'polygons and their end slots, dark colours — and a field nobody has seen go red is not compared, it is ' +
        'carried. "Alone" is the half that keeps a plant from passing by making everything noisy',
    );
  }

  // --- POR05: an ill-conditioned bone is excluded with its descendants, counted, never compared --
  {
    const probes: string[] = [];
    let detail = '';
    if (none !== null) {
      const parentOf = new Map(none.setup.bones.map((b) => [b[0], b[8]]));
      const collapsed = none.setup.bones.find((b) => b[8] !== null && none.setup.bones.some((c) => c[8] === b[0]))?.[0] ?? null;
      if (collapsed === null) probes.push('the probe has no bone with both a parent and a child');
      else {
        const under = (name: string): boolean => {
          for (let at: string | null = name; at !== null; at = parentOf.get(at) ?? null) if (at === collapsed) return true;
          return false;
        };
        const subtree = none.setup.bones.filter((b) => under(b[0])).map((b) => b[0]);
        const child = subtree.find((n) => n !== collapsed) ?? null;
        const outside = none.setup.bones.find((b) => !under(b[0]))?.[0] ?? null;
        const copy = JSON.parse(JSON.stringify(none)) as OracleDump;
        const row = (name: string): BoneRow => copy.setup.bones.find((b) => b[0] === name) as BoneRow;
        const c0 = row(collapsed);
        [c0[3], c0[4], c0[5], c0[6]] = [0, 0, 0, 0];
        if (child !== null) row(child)[1] = (row(child)[1] as number) + 1;
        const quiet = compareDumps(none, copy, tol);
        const setupRow = quiet.rows[0];
        if (child === null) probes.push(`bone "${collapsed}" has no descendant to move`);
        if (!quiet.identical) probes.push(`a collapsed "${collapsed}" and its moved child read ${quiet.first}`);
        if (setupRow.excluded !== subtree.length) {
          probes.push(`the setup row excluded ${setupRow.excluded} bone(s); "${collapsed}" and its descendants are ${subtree.length}`);
        }
        if (outside === null) probes.push('no bone outside the collapsed subtree to move');
        else {
          row(outside)[1] = (row(outside)[1] as number) + 1;
          const loud = compareDumps(none, copy, tol);
          if (loud.identical || !(loud.first ?? '').includes(`bone "${outside}"`)) {
            probes.push(`bone "${outside}", outside the subtree, moved 1 and compare read ${loud.first ?? 'IDENTICAL'}`);
          }
        }
        detail =
          `bone "${collapsed}"'s matrix zeroed and its descendant "${child}" moved 1 in one document: IDENTICAL with ` +
          `${setupRow.excluded} bone(s) excluded at the setup pose (${subtree.join(', ')}); the same move on "${outside}", ` +
          'outside that subtree, is named';
      }
    } else probes.push('no dump to plant into');
    const held = probes.length === 0;
    say(
      'POR05_AN_ILL_CONDITIONED_BONE_IS_EXCLUDED_WITH_ITS_DESCENDANTS_AND_COUNTED',
      held,
      probeDetail(held, probes, detail),
      'the rule the exam\'s calibration derived, and the one clause of this comparator that makes a difference NOT ' +
        'count — so it is the clause that most needs a fence: it reaches exactly the collapsed bone and what hangs ' +
        'under it, and a move one bone outside it is still named',
    );
  }

  // --- POR06: a bad input exits 2, by name, and writes nothing --
  {
    const probes: string[] = [];
    const emptyDir = join(work, 'empty');
    mkdirSync(emptyDir, { recursive: true });
    const notOracle = join(work, 'not-oracle.json');
    writeFileSync(notOracle, '{"spec":"rigc-frames/1"}\n');
    const out = join(work, 'refused.json');
    const cases: Array<[string, string[], string]> = [
      ['a phase that does not exist', ['dump', buildDir, '--out', out, '--phase', 'sideways'], '--phase "sideways" is not one of grid, off, irr, dense'],
      ['--dt without stepping', ['dump', buildDir, '--out', out, '--dt', '1/60'], '--physics none steps nothing'],
      ['a skin the rig does not declare', ['dump', buildDir, '--out', out, '--skin', 'nosuch'], '--skin "nosuch": no such skin; this skeleton declares [default, alt]'],
      ['a directory rigc did not build', ['dump', emptyDir, '--out', out], 'has no skeleton.json and no skeleton.atlas'],
      ['a document that is not an oracle dump', ['compare', notOracle, noneA], 'spec is "rigc-frames/1", not "pose-oracle/4"'],
      ['two dumps posed under different options', ['compare', noneA, stepA], 'posed under different options'],
    ];
    for (const [label, args, expect] of cases) {
      const run = runOracle(args);
      if (run.status !== 2) probes.push(`${label}: exit ${run.status}, not 2`);
      if (!run.stderr.includes(expect)) probes.push(`${label}: stderr ${JSON.stringify(run.stderr.trim().slice(0, 200))} does not say ${JSON.stringify(expect)}`);
      if (existsSync(out)) {
        probes.push(`${label}: ${basename(out)} was written by a refused run`);
        rmSync(out);
      }
    }
    const held = probes.length === 0;
    say(
      'POR06_A_BAD_INPUT_EXITS_2_BY_NAME_AND_WRITES_NOTHING',
      held,
      probeDetail(held, probes, `${cases.length} refusals, each exit 2 with its sentence and no file written: ${cases.map(([l]) => l).join('; ')}`),
      'exit 2 is the third answer the brief asks for — not IDENTICAL, not DIFF, but "these two cannot be compared" — ' +
        'and a comparison across two sampling schedules would print a DIFF that is a fact about the flags',
    );
  }

  // --- POR07: stepping moves the physics bone's subtree and nothing else --
  {
    const probes: string[] = [];
    let moved: string[] = [];
    let worst = 0;
    if (none !== null && step !== null && none.physics.length > 0) {
      const physicsBones = new Set(none.physics.map((p) => p.bone));
      const parentOf = new Map(none.setup.bones.map((b) => [b[0], b[8]]));
      const underPhysics = (name: string): boolean => {
        for (let at: string | null = name; at !== null; at = parentOf.get(at) ?? null) if (physicsBones.has(at)) return true;
        return false;
      };
      const c = compareDumps({ ...none, options: step.options }, step, tol);
      worst = c.worstXy + c.worstM;
      const named = c.rows.flatMap((r) => r.findings).map((f) => /: bone "([^"]+)"/.exec(f)?.[1] ?? null);
      moved = [...new Set(named.filter((n): n is string => n !== null))].sort();
      if (c.identical) probes.push('the stepped dump is IDENTICAL to the unstepped one, so stepping stepped nothing');
      const stray = moved.filter((n) => !underPhysics(n));
      if (stray.length > 0) probes.push(`bones outside every physics constraint's subtree moved: ${stray.join(', ')}`);
      const other = c.rows.flatMap((r) => r.findings).filter((f) => !/: bone "/.test(f));
      if (other.length > 0) probes.push(`stepping changed something other than bones: ${other.slice(0, 3).join(' | ')}`);
    } else probes.push(none === null || step === null ? 'no dumps to compare' : 'the probe declares no physics constraint');
    const held = probes.length === 0;
    say(
      'POR07_STEPPED_PHYSICS_MOVES_THE_PHYSICS_BONES_AND_NOTHING_THEY_DO_NOT_CARRY',
      held,
      probeDetail(
        held,
        probes,
        `--physics step against --physics none on the probe: bones named ${moved.join(', ')} — each a physics ` +
          `constraint's bone or under one — worst Δxy+Δabcd ${worst.toFixed(6)}`,
      ),
      'the stepped phase is new, and a stepping loop that forgot `update(delta)` would dump byte-identically twice ' +
        'and match itself for ever; comparing it with the unstepped dump is what shows it simulates, and the ' +
        'subtree clause is what shows it simulates only what the constraints hold',
    );
  }

  // --- POR08/POR09: the public examples' rebuilds against their exports --
  //
  // ⚠️ Fetched art, so an absent `examples/` is a HOLE here and never a pass.
  // The reading held is the one measured when this landed: IDENTICAL on every
  // export, in three phases and stepped. A rigc change that moves it is the
  // gate issue #380 is built on turning red, which is the point.
  const corpus = corpusExports();
  if (corpus.length === 0) {
    console.log(`  SKIP  POR08–POR09 did not run: no editor export under ${INGEST_CORPUS_ROOT}.`);
    console.log('          run `bun run fetch-examples` and re-run this suite.');
    console.log(
      '          ⚠️ This is a HOLE in this run, not a pass — no rigc rebuild was posed against the export it was read ' +
        'from, so the reproduction the oracle was promoted for did not happen here.',
    );
  } else {
    const PHASES: OraclePhase[] = ['grid', 'off', 'irr'];
    const reach = { events: 0, clips: 0, meshes: 0, stepped: 0, skins: 0, exports: 0 };
    // A rebuild's atlas names each page by its path from the build directory (`rewritePageNames` in src/atlas.ts) — where the file sits, not
    // which drawing it is — so the page UVs' page cell (issue #967) is compared by its file name here; every UV still at the tolerance below.
    const pageFile = (rows: OracleSample['uvs']): OracleSample['uvs'] => rows.map((x) => [x[0], x[1], basename(x[2]), x[3]]);
    const pagesByFile = (d: OracleDump): OracleDump => ({ ...d, setup: { ...d.setup, uvs: pageFile(d.setup.uvs) }, animations: d.animations.map((a) => ({ ...a, samples: a.samples.map((x) => ({ ...x, uvs: pageFile(x.uvs) })) })) });
    for (const entry of corpus) {
      const sourceText = readFileSync(entry.path, 'utf8');
      const decompiled = ingest(JSON.parse(sourceText) as Record<string, unknown>, {
        name: entry.name,
        art: 'none',
        source: basename(entry.path),
        version: packageVersion(),
      });
      const root = mkdtempSync(join(harnessTemp(), `rigc-oracle-${entry.name}-`));
      writeFileSync(join(root, 'rig.json'), `${JSON.stringify(decompiled.rig, null, 2)}\n`);
      writeFileSync(join(root, 'motion.json'), `${JSON.stringify(decompiled.motion, null, 2)}\n`);
      // The pack is found by resolving, as IG16 finds it: the first one the
      // rebuild compiles and gates green against.
      let rebuilt: CompileResult | null = null;
      let pack = '';
      for (const [index, candidate] of entry.packs.entries()) {
        const outDir = join(root, `B${index}`);
        mkdirSync(outDir, { recursive: true });
        try {
          const b = compile({ rigPath: join(root, 'rig.json'), motionPath: join(root, 'motion.json'), outDir, atlasInPath: candidate });
          const verdict = validate({
            skeletonText: b.skeletonText,
            atlasText: b.atlasText,
            atlasDir: outDir,
            declaredDurations: b.declaredDurations,
            modelText: threadedModel(b, b.atlasText),
            rig: b.rig,
            profile: 'spine',
          });
          if (verdict.failures.length > 0) continue;
          rebuilt = b;
          pack = candidate;
          break;
        } catch {
          // Another pack may cover it; the case line names the none that did.
        }
      }
      rmSync(root, { recursive: true, force: true });
      const readings: string[] = [];
      let held = rebuilt !== null;
      let boneSamples = 0;
      let vertices = 0;
      if (rebuilt !== null) {
        const ours = loadOracleData(rebuilt.skeletonText, rebuilt.atlasText, `the rebuild of ${entry.label}`);
        const theirs = loadOracleData(sourceText, readFileSync(pack, 'utf8'), entry.label);
        const graded: Array<[string, OracleOptions]> = [
          ...PHASES.map((phase): [string, OracleOptions] => [phase, { phase, samples: ORACLE_DEFAULT_SAMPLES, skin: 'all', physics: 'none', dt: null }]),
          ['grid stepped', { phase: 'grid', samples: ORACLE_DEFAULT_SAMPLES, skin: 'all', physics: 'step', dt: parseDt(ORACLE_DEFAULT_DT) }],
        ];
        for (const [label, options] of graded) {
          const a = dumpSkeleton(ours, options);
          const b = dumpSkeleton(theirs, options);
          const c = compareDumps(pagesByFile(a), pagesByFile(b), tol);
          boneSamples += c.boneSamples;
          vertices += c.rows.reduce((s, r) => s + r.vertices, 0);
          if (!c.identical || c.boneSamples === 0) held = false;
          readings.push(`${label} ${c.identical ? 'IDENTICAL' : `DIFF (${c.first})`}`);
          if (label === 'grid') {
            const samples = b.animations.flatMap((x) => x.samples);
            reach.events += samples.reduce((s, x) => s + x.events.length, 0);
            reach.clips += samples.reduce((s, x) => s + x.clips.length, 0);
            reach.meshes += samples.reduce((s, x) => s + x.attachments.filter((x2) => x2[2] === 'mesh').length, 0);
            reach.skins = Math.max(reach.skins, b.skins.length);
          }
          if (options.physics === 'step' && b.physics.length > 0) {
            const unstepped = dumpSkeleton(theirs, { ...options, physics: 'none', dt: null });
            if (!compareDumps({ ...unstepped, options: b.options }, b, tol).identical) reach.stepped++;
          }
        }
        reach.exports++;
      }
      say(
        `POR08_A_PUBLIC_EXAMPLES_RIGC_REBUILD_POSES_AS_ITS_EXPORT_AT_THE_READING_MEASURED[${entry.label}]`,
        held,
        rebuilt === null
          ? `NO REBUILD — none of the ${entry.packs.length} pack(s) beside the export compiled and gated green`
          : `ingest → build through ${basename(pack)}, posed beside the export: ${readings.join(', ')}; ` +
              `${boneSamples} bone-sample(s) and ${vertices} vertex-sample(s) compared`,
        'the brief\'s row (c) and §6 step 0b\'s gate: the exam read IDENTICAL on its production rigs, and this is the ' +
          'same instrument on the public ones. The reading is held as measured — IDENTICAL on every export, in the ' +
          'grid, off and irr phases and stepped — rather than assumed, so a rigc change that moves one names the ' +
          'export, the phase and the first difference',
      );
    }
    const probes: string[] = [];
    if (reach.exports !== corpus.length) probes.push(`${corpus.length - reach.exports} export(s) were not rebuilt, so their fields went ungraded`);
    for (const [field, n] of [['fired event', reach.events], ['clip polygon', reach.clips], ['mesh vertex row', reach.meshes], ['stepped physics export', reach.stepped]] as const) {
      if (n === 0) probes.push(`no export compared a ${field}`);
    }
    const held = probes.length === 0;
    say(
      'POR09_THE_CORPUS_GRADES_EVERY_FIELD_THE_DUMP_ADDED_OR_NAMES_THE_HOLE',
      held,
      probeDetail(
        held,
        probes,
        `over ${reach.exports} export(s): ${reach.events} fired event(s), ${reach.clips} clip polygon(s), ` +
          `${reach.meshes} mesh vertex row(s) compared at grid, and ${reach.stepped} export(s) whose stepped pose ` +
          'differs from its unstepped one — stepping was graded where it does something',
      ),
      '§4\'s rule for a population: a construct no row uses is a HOLE, not a pass. What the exports cannot grade — ' +
        'posing under one of several skins, when none of them declares a second — is printed below this line ' +
        'rather than folded into the green',
    );
    if (reach.skins < 2) {
      console.log(
        `          ⚠️ HOLE: no export under ${INGEST_CORPUS_ROOT} declares more than ${reach.skins} skin, so posing ` +
          'under one skin (--skin <name>) is graded by no public row — only the probe above carries two.',
      );
    }
  }

  // --- POR10: the slot row's blend mode, read off a hand-written skeleton stating every mode, and the spec's number --
  {
    const probes: string[] = [];
    let detail = '';
    // Per slot: the blend the Spine file states (undefined: none) and the mode the header says the runtime reads.
    const stated: Array<[string, string | undefined, string | null]> = [
      ['unstated', undefined, 'Normal'],
      ['normal', 'normal', 'Normal'],
      ['additive', 'additive', 'Additive'],
      ['multiply', 'multiply', 'Multiply'],
      ['screen', 'screen', 'Screen'],
      ['upperFirst', 'Additive', 'Additive'],
      ['upperAll', 'ADDITIVE', null],
    ];
    const skeletonText = JSON.stringify({
      skeleton: { spine: '4.3.13' }, bones: [{ name: 'root' }],
      slots: stated.map(([name, blend]) => ({ name, bone: 'root', attachment: 'r', ...(blend === undefined ? {} : { blend }) })),
      skins: [{ name: 'default', attachments: Object.fromEntries(stated.map(([name]) => [name, { r: { width: 4, height: 4 } }])) }],
      // An animation keying every slot's colour: the mode is the slot's data, and no sample moves it.
      animations: { tint: { slots: Object.fromEntries(stated.map(([name]) => [name, { rgba: [{ time: 0, color: 'ff000080' }, { time: 1, color: '00ff00ff' }] }])) } },
    });
    const atlasText = 'page.png\n\tsize: 64, 64\nr\n\tbounds: 0, 0, 4, 4\n';
    try {
      const data = loadOracleData(skeletonText, atlasText, 'the blend probe');
      const dump = dumpSkeleton(data, { phase: 'grid', samples: 3, skin: 'all', physics: 'none', dt: null });
      const poses = [dump.setup, ...dump.animations.flatMap((a) => a.samples)];
      for (const pose of poses) {
        for (const [name, , mode] of stated) {
          const row = pose.slots.find((x) => x[0] === name);
          if (row === undefined || row.length !== 9 || row[8] !== mode) probes.push(`slot "${name}" reads ${JSON.stringify(row?.[8])} in a ${row?.length ?? 0}-cell row, not ${JSON.stringify(mode)} in 9`);
        }
      }
      // The header's field list, held: the pose carries no mode, the slot's data does.
      const skeleton = new Skeleton(data);
      skeleton.setupPose();
      const poseFields = Object.keys(skeleton.slots[0].appliedPose).sort();
      const POSE_FIELDS = ['attachment', 'color', 'darkColor', 'deform', 'sequenceIndex'];
      if (JSON.stringify(poseFields) !== JSON.stringify(POSE_FIELDS)) probes.push(`a slot's pose carries [${poseFields.join(', ')}], not the header's [${POSE_FIELDS.join(', ')}] — a field the row may have to carry`);
      if (!('blendMode' in data.slots[0])) probes.push('the slot data carries no blendMode, where the dumper reads it');
      // A plant in one sample's blend is the one difference named.
      const copy = JSON.parse(JSON.stringify(dump)) as OracleDump;
      const target = copy.animations[0].samples[1].slots.find((x) => x[0] === 'additive');
      if (target === undefined) probes.push('no additive row to plant into');
      else {
        target[8] = 'Screen';
        const c = compareDumps(dump, copy, tol);
        const all = [...c.document, ...c.rows.flatMap((r) => r.findings)];
        if (all.length !== 1 || !all[0].includes('slot "additive" blend "Additive" vs "Screen"')) probes.push(`the planted blend read ${c.identical ? 'IDENTICAL' : `${all.length} difference(s): ${all.slice(0, 2).join(' | ')}`}`);
      }
      // The spec's number: a document one step older is refused by name, not compared on the cells it has.
      const current = join(work, 'blend-2.json');
      const older = join(work, 'blend-1.json');
      writeFileSync(current, dumpText(dump));
      writeFileSync(older, dumpText({ ...dump, spec: 'pose-oracle/2' }));
      const refused = runOracle(['compare', older, current]);
      if (refused.status !== 2 || !refused.stderr.includes('spec is "pose-oracle/2", not "pose-oracle/4"')) probes.push(`a pose-oracle/2 document: exit ${refused.status}, stderr ${JSON.stringify(refused.stderr.trim().slice(0, 160))}`);
      detail = `${stated.length} slots stating none, the four modes, one with its first letter upper-cased and one all upper-case read [${stated.map((x) => String(x[2])).join(', ')}] in the setup row and in each of ${poses.length - 1} samples of an animation keying their colour; the pose's fields [${poseFields.join(', ')}] carry no mode; a blend planted in one sample is the one difference named; a document one spec older exits 2 by name`;
    } catch (err) {
      probes.push(`the blend probe did not load or pose: ${(err as Error).message}`);
    }
    const held = probes.length === 0;
    say(
      'POR10_THE_SLOT_ROW_CARRIES_THE_BLEND_MODE_THE_RUNTIME_READS_AND_THE_SPEC_NUMBER_MOVED_WITH_IT',
      held,
      probeDetail(held, probes, detail),
      'issue #933: the row carried the attachment, the colours and the path and no blend mode, so 36 corpus slots stating one were never judged. The mode is the slot\'s data, read off `SlotData.blendMode`; the pose\'s own field list is held here so a runtime that poses a new slot field turns this red. compare reads a row by position, so a new cell moves the spec to /2 and a /1 reader refuses it rather than read IDENTICAL over the cell it cannot see',
    );
  }

  rmSync(work, { recursive: true, force: true });
  return bad;
}

// ---------------------------------------------------------------------------
// rigc's own core: src/core/, the second dumper (issue #925, step 2a of #380)
// ---------------------------------------------------------------------------

// Its own statement, so the suite lands as one hunk (the convention the
// slider-reader suite states at its imports).
import { activeBones, CORE_CONSTRAINT_KINDS, CORE_DUMPER, CoreInputError, foldBlend, foldInheritMode, gridRound, NOT_ADMITTED, poseSetup, readBlend, readColour, readModel, shownAttachment, viewColours, type CompiledDocument, type CoreStated, type CoreBlendMode, type CorePlant, type SetupEvaluator, type ShownResolution } from './src/core/index.ts';
import { compiledDeformedWorldVertices, compiledWeightedOf, compiledWorldVertices, compileWeightedVertices, deformedWorldVertices, EXACT_COORDS, regionCorners, worldVertices, type CompiledWeightedVertices, type MeshArrays, type VertexPoser, type WeightedVertices as CoreWeightedVertices } from './src/core/vertices.ts';
import { clipShapeOf, clipThrough, clipTriangles, convexPieces, signedArea2, type ClipReading, type ClipShape, type TriangleClipper } from './src/core/clipping.ts';
import { asOracleDocument, blockOf, coreDump, ORACLE_BLOCKS, OracleInputError, sampleTime as oracleSampleTime, type OracleDocument, type SlotRow } from './tools/pose_oracle.ts';
import { runRecipe } from './tools/emit_hashes.ts';
import { CORE_RAW_WALK, corePoser, firstPageDifference, type CorePoserPlants, type CoreRawWalk, type PieceArrays } from './src/render_core.ts';
import type { FramingSets, MakeCorePoser } from './src/render_shared.ts';
import { animationCensusOf, animationReachLines, attachmentReachLines, buildRecipes, CLIPPED_CENSUS_FIELDS, clippedReachLines, GATE_BLOCKS, REMAINDER_CENSUS_BLOCKS, timelineKindLines, type GateBlock, censusOf, CONSTRAINT_CENSUS_FIELDS, constraintCensusOf, constraintKindLines, constraintReachLines, GATE_OPTIONS, gateBuild, gateBuilt, gateVerdict, PATH_CENSUS_FIELDS, pathCensusOf, pathReachLines, reachLines, slotCensusOf, slotReachLines, STEPPED_CENSUS_FIELDS, STEPPED_OPTIONS, steppedCensusOf, steppedReachLines, type AnimationCensusField, type BuiltRow, type ConstraintCensusField, type PathCensusField, type SteppedCensusField } from './tools/core_gate.ts';
import { BEZIER_SIXTH, bezierPolyline, BONE_TIMELINE_KINDS, channelAt, keyIndexAt, posedBoneRows, sampleTime, SLOT_TIMELINE_KINDS, type ChannelEvaluator, type SamplePhase, type TimelinePlant } from './src/core/animation.ts';
// The core entry's Bézier evaluation (issue #1417), its own statement so CA12 lands as one hunk.
import { bezierPolyline as entryBezierPolyline, BEZIER_PIECES as ENTRY_BEZIER_PIECES } from './src/core/entry.ts';
import { BEZIER_PIECES } from './src/core/animation.ts';
import { attachmentStates, DEFORM_CURVE_END, deformAt, deformPercent, heldArray, SEQUENCE_MODES as CORE_SEQUENCE_MODES, sequenceFrameAt, type CoreDeformKey } from './src/core/deform.ts';
import { drawOrderAt } from './src/core/draw_order.ts';
import { eventsFired, type CoreEventRow } from './src/core/events.ts';
import { physicsState, stepPhysics, stepSchedule, type CorePhysicsRecord } from './src/core/constraints_physics.ts';
import { physicsScaleCases } from './tools/physics_scale_cases.ts';
import { modeMatrix, worldTransforms, type CoreInheritMode, type CoreWorld, type WorldArithmetic } from './src/core/world.ts';
import { ADMITTED_CONSTRAINT_KINDS, TRANSFORM_PROPERTIES, type ConstraintPlant, type CoreConstraintRecord, type CoreTransformRecord } from './src/core/constraints.ts';
// The per-skin view (issue #932), its own statements so the CN controls land as one hunk.
import { CORE_ALL_SKINS, lookupSkins } from './src/core/skins.ts';
import { underSkin } from './src/core/index.ts';
import { skinReachLines } from './tools/core_gate.ts';
import { boundsOfTexts } from './tools/core_gate.ts';
// The page UVs (issue #967), its own statements so the CU controls land as one hunk.
import { computeUvs, frameRegionName, meshPageUvs, readUvSequences, regionPageUvs, type UvReading } from './src/core/uvs.ts';
