/** The constraint kinds no cut of construct 5 poses yet — what a skipped row names. */
const LATER_KINDS: readonly string[] = CORE_CONSTRAINT_KINDS.filter((k) => !ADMITTED_CONSTRAINT_KINDS.includes(k));
/** How a detail names what a skipped row declares: the later kinds, or that none is left (since issue #938's path cut, every kind is posed). */
const LATER_WORDS = LATER_KINDS.length === 0 ? 'a constraint of a later kind (none is left)' : `a ${LATER_KINDS.join(', ')} constraint`;

/** What `readModel` refuses `text` with, or '' when it reads it. */
function coreRefusal(text: string): string {
  try {
    readModel(text);
    return '';
  } catch (err) {
    return err instanceof CoreInputError ? err.message : `not a CoreInputError: ${(err as Error).message}`;
  }
}

/**
 * What a core-suite control holding a corpus floor prints (issue #1004).
 *
 * Two states used to print the same FAIL: a corpus that is on the machine and
 * reaches nothing — a fault of the tree, since a construct no row uses is never
 * a pass — and a corpus that is not on the machine at all, which is the run's
 * state and which every other corpus suite reports as a HOLE by name. So the
 * verdict reads WHO is absent: a HOLE only when the corpus is (`hole` is the
 * note `treeRecipes` wrote) and every unmet probe is a floor only a corpus row
 * can clear. A floor unmet with the corpus present is a FAIL, and so is any
 * other probe whatever the corpus — a gallery row that reads DIFF is a fault on
 * every machine.
 */
type CorpusCaseVerdict = 'PASS' | 'FAIL' | 'HOLE';
function corpusCaseVerdict(probes: readonly string[], floors: ReadonlySet<string>, hole: string | null): CorpusCaseVerdict {
  if (probes.length === 0) return 'PASS';
  return hole !== null && probes.every((probe) => floors.has(probe)) ? 'HOLE' : 'FAIL';
}

/** The lines a core control prints for a HOLE: a `SKIP` gutter, never PASS or FAIL, then each floor and the sentence every corpus suite prints. */
function corpusHoleLines(name: string, probes: readonly string[]): string[] {
  return [
    `  SKIP  ${name}: not measured — every probe it left unmet needs a corpus row, and the example corpus is not on this machine`,
    ...probes.map((probe) => `          ${probe}`),
    '          run `bun run fetch-examples` and re-run this suite.',
    '          ⚠️ This is a HOLE in this run, not a pass — the gallery rows alone cannot reach what this control holds a corpus row to.',
  ];
}

/**
 * Every core control that went through `sayCorpus` in this run, with its verdict and whether the core suite found
 * the corpus absent — what `TY22` reads of the run it is part of. Recorded rather than re-read off the disk, so
 * `TY22` builds no path under `examples/` and does not enrol its own suite as a corpus reader in `TY20`.
 */
const CORE_CORPUS_CASES: Array<{ name: string; verdict: CorpusCaseVerdict; absent: boolean }> = [];

/** Module specifiers the core may not import, as a value or as a type: the runtime, and every impure door. */
const CORE_FORBIDDEN_MODULES: readonly RegExp[] = [
  /^@esotericsoftware\/spine-core(\/|$)/,
  /^(node:)?(child_process|net|http|https|http2|dgram|dns|tls|fs|fs\/promises|os|worker_threads|cluster|perf_hooks)$/,
];
/** Calls the core may not make: a clock, randomness, the network, the process. */
const CORE_FORBIDDEN_CALLS: ReadonlyArray<readonly [RegExp, string]> = [
  [/\bDate\.now\s*\(|\bnew\s+Date\b/, 'a clock'],
  [/\bperformance\.now\s*\(/, 'a clock'],
  [/\bMath\.random\s*\(/, 'randomness'],
  [/\bfetch\s*\(/, 'the network'],
  [/\bprocess\.|\bBun\./, 'the process'],
];

/** Every module specifier a source text names: static and type imports, re-exports, dynamic imports, requires. */
function specifiersOf(code: string): Array<{ spec: string; typeOnly: boolean }> {
  const out: Array<{ spec: string; typeOnly: boolean }> = [];
  for (const m of code.matchAll(/\b(import|export)\s+(type\s+)?[^;'"]*?\bfrom\s*['"]([^'"]+)['"]/g)) out.push({ spec: m[3], typeOnly: m[2] !== undefined });
  for (const m of code.matchAll(/\bimport\s*['"]([^'"]+)['"]/g)) out.push({ spec: m[1], typeOnly: false });
  for (const m of code.matchAll(/\b(?:import|require)\s*\(\s*['"]([^'"]+)['"]\s*\)/g)) out.push({ spec: m[1], typeOnly: false });
  return out;
}

/**
 * The core's tree rule over a population of `path -> text`: every file under
 * `src/core/`, and every module under `src/` it reaches by a value import,
 * names no forbidden module and makes no forbidden call; the core itself also
 * imports nothing outside `src/`. Comments are not code (`codeOnly`).
 */
function coreTreeProblems(population: ReadonlyMap<string, string>, prefix = 'src/core/'): string[] {
  const problems: string[] = [];
  const core = [...population.keys()].filter((p) => p.startsWith(prefix)).sort();
  const seen = new Set<string>();
  const queue = [...core];
  while (queue.length > 0) {
    const rel = queue.shift() as string;
    if (seen.has(rel)) continue;
    seen.add(rel);
    const text = population.get(rel);
    if (text === undefined) {
      problems.push(`${rel} is imported by the core and is not in the population read`);
      continue;
    }
    const code = codeOnly(text);
    const inCore = rel.startsWith(prefix);
    for (const { spec, typeOnly } of specifiersOf(code)) {
      if (CORE_FORBIDDEN_MODULES.some((re) => re.test(spec)) && (inCore || !typeOnly)) problems.push(`${rel} imports "${spec}"${inCore ? '' : ', and the core reaches it'}`);
      if (!spec.startsWith('.')) continue;
      const target = join(dirname(rel), spec).split('\\').join('/');
      if (inCore && target === 'src/transform.ts') problems.push(`${rel} imports "${spec}" — the compiler's adapter, which itself calls the core's evaluator (issue #1015, under the runtime's arithmetic since #1021), so the core reaching it would be a cycle`);
      if (!target.startsWith('src/')) {
        if (inCore) problems.push(`${rel} imports "${spec}", outside src/`);
        continue;
      }
      if (!typeOnly) queue.push(target);
    }
    for (const [re, what] of CORE_FORBIDDEN_CALLS) if (re.test(code)) problems.push(`${rel} reaches ${what} (${re.source})`);
  }
  if (core.length === 0) problems.push(`no file under ${prefix} was read, so the rule held nothing`);
  return problems;
}

/** Every `.ts` file under `src/`, read off the disk (a file not yet committed included), repo-relative. */
function srcPopulation(root: string): Map<string, string> {
  const out = new Map<string, string>();
  const walk = (rel: string): void => {
    for (const entry of readdirSync(join(root, rel), { withFileTypes: true })) {
      const child = `${rel}/${entry.name}`;
      if (entry.isDirectory()) walk(child);
      else if (entry.name.endsWith('.ts')) out.set(child, readFileSync(join(root, child), 'utf8'));
    }
  };
  walk('src');
  return out;
}

/** The functions that form the oracle's bone rows (`CO62`): `stepRows` rounds them, the two exports hand them out. */
const ROW_FORMING = new Set(['stepRows', 'posedBoneWorld', 'posedBoneRows']);
/** The modules a walk — batch, scan or live — steps through past its timelines (`CO62`). */
const WALK_MODULES = new Set(['src/core/raw.ts', 'src/core/track.ts', 'src/core/tracks.ts']);
/** The module the walk's bone poser lives in, and the sample's (`CO62`). */
const BONE_POSER_MODULE = 'src/core/animation.ts';

/** The name of the function, method or `const` a node sits in, innermost first; `(module)` at the top level. */
function enclosingName(node: ts.Node): string {
  for (let at: ts.Node | undefined = node.parent; at !== undefined; at = at.parent) {
    if ((ts.isFunctionDeclaration(at) || ts.isMethodDeclaration(at)) && at.name !== undefined) return at.name.getText();
    if (ts.isVariableDeclaration(at) && at.initializer !== undefined && (ts.isArrowFunction(at.initializer) || ts.isFunctionExpression(at.initializer))) return at.name.getText();
    if (ts.isPropertyAssignment(at) && (ts.isArrowFunction(at.initializer) || ts.isFunctionExpression(at.initializer))) return at.name.getText();
  }
  return '(module)';
}

/** Each bare-identifier call in a source, with the function it sits in and its line. */
function bareCallsIn(path: string, text: string): Array<{ caller: string; callee: string; line: number }> {
  const tree = ts.createSourceFile(path, text, ts.ScriptTarget.Latest, true);
  const out: Array<{ caller: string; callee: string; line: number }> = [];
  const visit = (node: ts.Node): void => {
    if (ts.isCallExpression(node) && ts.isIdentifier(node.expression)) out.push({ caller: enclosingName(node), callee: node.expression.text, line: tree.getLineAndCharacterOfPosition(node.getStart()).line + 1 });
    ts.forEachChild(node, visit);
  };
  visit(tree);
  return out;
}

/**
 * Where a walk forms the oracle's bone rows (`CO62`), by the chain of calls
 * that reaches them. A walk's modules (`WALK_MODULES`) must call none of
 * `ROW_FORMING`, and no function of the bone poser's module they call may
 * reach one through that module's own calls — the call graph is read off the
 * tree, so the walk's entries are not named here. `formed` lists every other
 * call of `ROW_FORMING`: the sites where the rows are the reason — the
 * sample's, and the readers outside a walk.
 */
function rowFormingCalls(population: ReadonlyMap<string, string>): { faults: string[]; formed: string[]; entries: string[] } {
  const faults: string[] = [];
  const formed: string[] = [];
  const poser = bareCallsIn(BONE_POSER_MODULE, population.get(BONE_POSER_MODULE) ?? '');
  const callees = new Map<string, Array<{ callee: string; line: number }>>();
  for (const c of poser) callees.set(c.caller, [...(callees.get(c.caller) ?? []), { callee: c.callee, line: c.line }]);
  const defined = new Set(callees.keys());
  const entries = new Set<string>();
  for (const path of WALK_MODULES) {
    for (const c of bareCallsIn(path, population.get(path) ?? '')) {
      if (ROW_FORMING.has(c.callee)) faults.push(`${path}:${c.line}: ${c.caller} calls ${c.callee}`);
      else if (defined.has(c.callee)) entries.add(c.callee);
    }
  }
  // Breadth first from each entry, through the poser module's own functions; a row-forming call on the way is a fault, named by its chain.
  const reached = new Map<string, string[]>([...entries].map((e) => [e, [e]]));
  const queue = [...entries];
  while (queue.length > 0) {
    const fn = queue.shift() as string;
    const chain = reached.get(fn) as string[];
    for (const { callee, line } of callees.get(fn) ?? []) {
      if (ROW_FORMING.has(callee)) faults.push(`${BONE_POSER_MODULE}:${line}: a walk reaches ${callee} through ${[...chain, callee].join(' → ')}`);
      else if (defined.has(callee) && !reached.has(callee)) {
        reached.set(callee, [...chain, callee]);
        queue.push(callee);
      }
    }
  }
  for (const [path, text] of population) {
    if (!path.startsWith('src/core/') || WALK_MODULES.has(path)) continue;
    for (const c of bareCallsIn(path, text)) if (ROW_FORMING.has(c.callee) && !(path === BONE_POSER_MODULE && reached.has(c.caller))) formed.push(`${path}:${c.line}: ${c.caller} calls ${c.callee}`);
  }
  return { faults, formed, entries: [...entries].sort() };
}

/**
 * The comment blocks of a TypeScript source (issue #1015): runs of lines that
 * start a comment (`/*`, `*`, `//`), each with its first line (1-based) and its
 * text with the markers taken off and the lines joined — so a phrase wrapped
 * across two lines is still one phrase.
 */
function commentBlocks(text: string): Array<{ line: number; text: string }> {
  const lines = text.split('\n');
  const out: Array<{ line: number; text: string }> = [];
  let start = -1;
  const flush = (end: number): void => {
    if (start < 0) return;
    const joined = lines.slice(start, end).map((l) => l.trim().replace(/^(\/\*\*?|\*\/|\*|\/\/)\s?/, '')).join(' ');
    out.push({ line: start + 1, text: joined.replace(/\s+/g, ' ') });
    start = -1;
  };
  lines.forEach((l, i) => {
    const t = l.trim();
    if (t.startsWith('*') || t.startsWith('/*') || t.startsWith('//')) {
      if (start < 0) start = i;
    } else flush(i);
  });
  flush(lines.length);
  return out;
}

/** A runtime source file named in a text: a CamelCase stem that is one of spine-core's exports, then `.js` or `.ts`. */
function runtimeFileCitations(text: string, runtimeNames: ReadonlySet<string>): string[] {
  return [...text.matchAll(/\b([A-Z][A-Za-z0-9]*)\.(?:js|ts)\b/g)].filter((m) => runtimeNames.has(m[1])).map((m) => m[0]);
}

/**
 * The phrasings issue #1015's sixteen used to say a routine here copies a
 * runtime routine. A participle after an article ("a transcribed name") is an
 * adjective on a noun, not a claim about code, and is left out.
 */
const TRANSCRIPTION_CLAIMS: ReadonlyArray<RegExp> = [
  /(?<!\b(?:[Aa]n?|[Tt]he) )\b(?:[Tt]ranscrib(?:e|es|ed|ing)|TRANSCRIB(?:E|ES|ED|ING))\b/,
  /\b[Aa] transcription of\b/,
  /\bwritten (?:straight )?off\b/i,
  /\bline for line\b/i,
  /\bterm for term\b/i,
  /\bmirrors\b[^.]*\bexactly\b/i,
  /\bthe runtime's own predicate\b/i,
];

/**
 * Every comment block under `src/` that cites a runtime source file and claims a
 * routine copies a runtime routine — one of `TRANSCRIPTION_CLAIMS`, or "is
 * `Name.member`" with `Name` a spine-core export — and every file under
 * `src/core/` that cites a runtime source file at all (issue #1015).
 */
/**
 * Every string literal under `src/core/` and in `src/render_core.ts` that is,
 * or holds as a word, a name the runtime package exports at module level —
 * each by its file, line and the name (issue #1054, #1011's second ask). The
 * core speaks the document's words; a class name of the runtime's in one of
 * its strings is the runtime's vocabulary in the module that is to replace it.
 * Template literals' fixed parts are read the same way.
 */
function runtimeExportsInCoreStrings(population: ReadonlyMap<string, string>, runtimeNames: ReadonlySet<string>): string[] {
  const out: string[] = [];
  for (const [path, text] of population) {
    if (!path.startsWith('src/core/') && path !== 'src/render_core.ts') continue;
    const tree = ts.createSourceFile(path, text, ts.ScriptTarget.Latest, true);
    const visit = (node: ts.Node): void => {
      if (ts.isStringLiteral(node) || ts.isNoSubstitutionTemplateLiteral(node) || ts.isTemplateHead(node) || ts.isTemplateMiddle(node) || ts.isTemplateTail(node)) {
        const named = [node.text, ...node.text.split(/[^A-Za-z0-9_$]+/)].find((word) => runtimeNames.has(word));
        if (named !== undefined) out.push(`${path}:${tree.getLineAndCharacterOfPosition(node.getStart()).line + 1}: the string ${JSON.stringify(node.text.slice(0, 80))} names the runtime's export ${named}`);
      }
      ts.forEachChild(node, visit);
    };
    visit(tree);
  }
  return out;
}

/**
 * What the string clause above does not hold, measured: the identifiers under
 * `src/core/` and in `src/render_core.ts` that spell a module-level export of
 * the runtime, and those that spell a member of an exported class's prototype —
 * the counts `CO23` prints beside the clause it does hold.
 */
function runtimeNamesAsCoreIdentifiers(population: ReadonlyMap<string, string>, exportsNamed: ReadonlySet<string>, members: ReadonlySet<string>): { exports: string[]; members: string[] } {
  const exportHits = new Set<string>();
  const memberHits = new Set<string>();
  for (const [path, text] of population) {
    if (!path.startsWith('src/core/') && path !== 'src/render_core.ts') continue;
    const tree = ts.createSourceFile(path, text, ts.ScriptTarget.Latest, true);
    const visit = (node: ts.Node): void => {
      if (ts.isIdentifier(node)) {
        if (exportsNamed.has(node.text)) exportHits.add(node.text);
        if (members.has(node.text)) memberHits.add(node.text);
      }
      ts.forEachChild(node, visit);
    };
    visit(tree);
  }
  return { exports: [...exportHits].sort(), members: [...memberHits].sort() };
}

function transcriptionClaims(population: ReadonlyMap<string, string>, runtimeNames: ReadonlySet<string>): string[] {
  const problems: string[] = [];
  for (const [rel, text] of [...population].sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))) {
    if (rel.startsWith('src/core/')) {
      const cited = runtimeFileCitations(text, runtimeNames);
      if (cited.length > 0) problems.push(`${rel} cites the runtime's source file(s) ${[...new Set(cited)].join(', ')}, and the core was written from measurement`);
    }
    for (const block of commentBlocks(text)) {
      const cited = runtimeFileCitations(block.text, runtimeNames);
      if (cited.length === 0) continue;
      const phrase =
        TRANSCRIPTION_CLAIMS.map((re) => block.text.match(re)?.[0]).find((m) => m !== undefined) ??
        [...block.text.matchAll(/\bis `([A-Z][A-Za-z0-9]*)\.[A-Za-z_]\w*`/g)].find((m) => runtimeNames.has(m[1]))?.[0];
      if (phrase !== undefined) problems.push(`${rel}:${block.line}: "${phrase}", in a comment citing ${[...new Set(cited)].join(', ')}`);
    }
  }
  return problems;
}

// ---------------------------------------------------------------------------
// the seeded generator every random population draws from (issue #952)
// ---------------------------------------------------------------------------

/**
 * The selftest's seeded generator: Marsaglia's xorshift32 with the shift
 * triple (13, 17, 5) — "Xorshift RNGs", Journal of Statistical Software 8(14),
 * 2003, which lists that triple among the full-period ones. The step is a
 * bijection on the 2^32 − 1 nonzero 32-bit states with all of them on one
 * cycle, so the period is 2^32 − 1 = 4,294,967,295 from every seed — walked
 * once from state 1 back to state 1 in 4,294,967,295 steps when this was
 * written — and, the draw being the state, no two draws within a period are
 * equal. The seed enters through murmur3's 32-bit finaliser (`fmix32`), itself
 * a bijection with 0 its one fixed point, so neighbouring seeds (95621,
 * 95622, …) do not start on neighbouring states, whose first draws the linear
 * step would keep correlated. Every operation is a 32-bit integer operation
 * (`^`, `<<`, `>>>`, `Math.imul`) and the draw is the state over 2^32, exact
 * in a double: one seed is one sequence on every machine (`RG02`).
 *
 * ⚠️ What it replaced (issue #952): `s = (s * 1103515245 + 12345) % 2^31`
 * carried in doubles, copied three times. The product reaches 2^61, past the
 * 53 bits a double holds exactly, so the multiplication rounded and the map
 * was not the LCG its constants name (period 2^31): from every seed the file
 * used, the orbit fell within 927 to 8,888 draws into one cycle of 10,466
 * states, so a population drawing more than that re-drew its own sequence —
 * the constraint populations of 1,200, 400 and 900 rigs held 437, 102 and 176
 * distinct rigs. `RG03` holds the old map to the probe this one passes.
 *
 * Each generator made here is recorded with the draws taken from it, so that
 * `RG01` measures the populations that actually ran rather than a list kept
 * beside them.
 */
const SEEDED_DRAWS: Array<{ seed: number; draws: number }> = [];
const XORSHIFT32_PERIOD = 2 ** 32 - 1;

/** murmur3's 32-bit finaliser: a bijection on 32-bit integers, 0 its fixed point. */
function fmix32(h: number): number {
  h >>>= 0;
  h ^= h >>> 16;
  h = Math.imul(h, 0x85ebca6b);
  h ^= h >>> 13;
  h = Math.imul(h, 0xc2b2ae35);
  h ^= h >>> 16;
  return h >>> 0;
}

/** One xorshift32 step (13, 17, 5) on a nonzero 32-bit state. */
function xorshift32Step(x: number): number {
  x ^= x << 13;
  x ^= x >>> 17;
  x ^= x << 5;
  return x >>> 0;
}

/** The first state of a seed, or a refusal naming it: 0 is the step's fixed point, and a seed past 32 bits would be read as another. */
function seededState(seed: number): number {
  if (!Number.isInteger(seed) || seed < 1 || seed > XORSHIFT32_PERIOD) {
    throw new Error(`seededRandom: seed ${seed} is not an integer from 1 to ${XORSHIFT32_PERIOD} — 0 is xorshift32's fixed point, where every draw is 0, and a seed past 32 bits would be read as another seed`);
  }
  return fmix32(seed);
}

/** The draws of one seed in (0, 1), not recorded — what the `RG` controls probe with. */
function unrecordedRandom(seed: number): () => number {
  let x = seededState(seed);
  return () => {
    x = xorshift32Step(x);
    return x / 4294967296;
  };
}

/** The draws of one seed in (0, 1), recorded in `SEEDED_DRAWS` — what every population in this file draws from. */
function seededRandom(seed: number): () => number {
  const draw = unrecordedRandom(seed);
  const record = { seed, draws: 0 };
  SEEDED_DRAWS.push(record);
  return () => {
    record.draws += 1;
    return draw();
  };
}

/** The generator this one replaced, kept as `RG03`'s plant: the float64 product rounds past 2^53. */
function replacedLcg(seed: number): () => number {
  let s = seed;
  return () => {
    s = (s * 1103515245 + 12345) % 2147483648;
    return s / 2147483648;
  };
}

/** The first draw (1-based) equal to an earlier one within `length` draws, or null — the probe `RG01` passes and `RG03` fails. */
function firstRepeatedDraw(draw: () => number, length: number): number | null {
  const seen = new Set<number>();
  for (let i = 1; i <= length; i++) {
    const v = draw();
    if (seen.has(v)) return i;
    seen.add(v);
  }
  return null;
}

/** The replaced map's first repeated draw from a seed (1-based), by Brent's cycle search on its states — no bound assumed. */
function replacedFirstRepeat(seed: number): { tail: number; period: number } {
  const step = (s: number): number => (s * 1103515245 + 12345) % 2147483648;
  let power = 1;
  let lambda = 1;
  let tortoise = step(seed);
  let hare = step(tortoise);
  while (tortoise !== hare) {
    if (power === lambda) {
      tortoise = hare;
      power *= 2;
      lambda = 0;
    }
    hare = step(hare);
    lambda += 1;
  }
  let t = step(seed);
  let h = step(seed);
  for (let i = 0; i < lambda; i++) h = step(h);
  let tail = 0;
  while (t !== h) {
    t = step(t);
    h = step(h);
    tail += 1;
  }
  return { tail, period: lambda };
}

/** xorshift32 from its definition in BigInt arithmetic — a second implementation sharing no code with the one above. */
function bigintXorshift(seed: number, shifts: readonly [bigint, bigint, bigint] = [13n, 17n, 5n]): () => number {
  const M = 0xffffffffn;
  let h = BigInt(seed) & M;
  h ^= h >> 16n;
  h = (h * 0x85ebca6bn) & M;
  h ^= h >> 13n;
  h = (h * 0xc2b2ae35n) & M;
  h ^= h >> 16n;
  let x = h;
  return () => {
    x = (x ^ (x << shifts[0])) & M;
    x = x ^ (x >> shifts[1]);
    x = (x ^ (x << shifts[2])) & M;
    return Number(x) / 4294967296;
  };
}

/** `n` draws as their float64 bytes. */
function drawBytes(draw: () => number, n: number): Buffer {
  const out = new Float64Array(n);
  for (let i = 0; i < n; i++) out[i] = draw();
  return Buffer.from(out.buffer);
}

/**
 * The generator's own suite (issue #952). Registered after every suite that
 * draws, so `RG01` reads the draws the run actually took; a partial run that
 * ran none of them prints `RG01` as a SKIP and a HOLE.
 */
function runSeededRandomSuite(): number {
  console.log('\n── seeded-random: every random population draws from xorshift32, whose period exceeds every population (issue #952) ──');
  let bad = 0;
  const say = (name: string, ok: boolean, detail: string, why: string): void => {
    bad += reportCase(name, ok, detail, why);
  };
  const bySeed = new Map<number, { instances: number; draws: number; most: number }>();
  for (const r of SEEDED_DRAWS) {
    const was = bySeed.get(r.seed) ?? { instances: 0, draws: 0, most: 0 };
    bySeed.set(r.seed, { instances: was.instances + 1, draws: was.draws + r.draws, most: Math.max(was.most, r.draws) });
  }
  const seeds = [...bySeed.keys()].sort((a, b) => a - b);
  // Each seed in use is drawn past both what the run took from it and the replaced map's first repeat from it.
  const reach = new Map(seeds.map((s) => {
    const old = replacedFirstRepeat(s);
    return [s, { length: Math.max(bySeed.get(s)?.most ?? 0, old.tail + old.period + 1), old }] as const;
  }));

  // --- RG01: every seed the run drew from, drawn past the old period and past its use, repeats nothing --
  if (seeds.length === 0) {
    console.log('  SKIP  RG01 did not run: no suite in this run drew from seededRandom (name core or deform-core beside seeded-random in --only).');
    console.log('          ⚠️ This is a HOLE in this run, not a pass — that no population re-drew its own sequence was not measured here.');
  } else {
    const probes: string[] = [];
    let longest = { seed: 0, draws: 0 };
    let total = 0;
    let probed = 0;
    for (const s of seeds) {
      const use = bySeed.get(s);
      const r = reach.get(s);
      if (use === undefined || r === undefined) continue;
      total += use.draws;
      if (use.most > longest.draws) longest = { seed: s, draws: use.most };
      if (use.most >= XORSHIFT32_PERIOD) probes.push(`seed ${s}: one generator drew ${use.most} times, not below the period ${XORSHIFT32_PERIOD}`);
      const at = firstRepeatedDraw(unrecordedRandom(s), r.length);
      probed += r.length;
      if (at !== null) probes.push(`seed ${s}: draw ${at} of ${r.length} repeats an earlier one`);
    }
    const ok = probes.length === 0;
    say(
      'RG01_EVERY_SEED_THE_RUN_DREW_FROM_REPEATS_NOTHING_PAST_THE_OLD_PERIOD_AND_ITS_OWN_USE',
      ok,
      probeDetail(ok, probes, `${SEEDED_DRAWS.length} generator(s) over ${seeds.length} seed(s) took ${total} draws this run, the most from one generator ${longest.draws} (seed ${longest.seed}); each seed drawn afresh to the larger of its own use and the replaced map's first repeat from it — ${probed} draws in all — and not one draw equals an earlier one of its seed; the period is ${XORSHIFT32_PERIOD}`),
      'issue #952: the replaced generator fell into one cycle of 10,466 states from every seed, so a population drawing more re-drew itself and counted the same rig more than once. Read off the generators the run made, not off a list of seeds kept beside them',
    );
  }

  // --- RG02: one seed is one sequence — two generators, and a second implementation, byte for byte --
  {
    const probes: string[] = [];
    const REFERENCE_DRAWS = 4096;
    // A seed's reach by the rule `reach` applies: the run's own use of it, else the replaced map's first repeat from it.
    const reachOf = (s: number): number => {
      const known = reach.get(s)?.length;
      if (known !== undefined) return known;
      const old = replacedFirstRepeat(s);
      return old.tail + old.period + 1;
    };
    // Issue #998: a seed whose reach is below the reference length was drawn over fewer draws than the reference
    // and read as a disagreement that did not exist. The first such seed from 1 is found here rather than typed,
    // and compared like every other seed — it has to read green.
    let short = 1;
    while (reachOf(short) >= REFERENCE_DRAWS) short += 1;
    const fixed = [1, short, XORSHIFT32_PERIOD];
    const all = [...new Set([...fixed, ...seeds])].sort((a, b) => a - b);
    // Every seed is drawn over the larger of its reach and the reference length, and its BigInt twin over the same
    // count: the first REFERENCE_DRAWS of every seed are compared however short its reach, and so is every draw
    // its reach carries past them.
    const drawn = (s: number): number => Math.max(reachOf(s), REFERENCE_DRAWS);
    const differs = (bytes: Buffer, twin: () => number): boolean => !bytes.equals(drawBytes(twin, bytes.length / 8));
    let compared = 0;
    let longest = { seed: 0, n: 0 };
    for (const s of all) {
      const n = drawn(s);
      const a = drawBytes(unrecordedRandom(s), n);
      const b = drawBytes(unrecordedRandom(s), n);
      if (!a.equals(b)) probes.push(`seed ${s}: two generators differ within ${n} draws`);
      if (differs(a, bigintXorshift(s))) probes.push(`seed ${s}: the BigInt implementation differs within ${n} draws`);
      compared += n;
      if (n > longest.n) longest = { seed: s, n };
    }
    // The plants: each must disagree, or the comparison measures nothing where it claims to.
    // The reference with one shift changed.
    const plantedShift = drawBytes(bigintXorshift(1, [12n, 17n, 5n]), REFERENCE_DRAWS);
    const planted = plantedShift.equals(drawBytes(unrecordedRandom(1), REFERENCE_DRAWS));
    if (planted) probes.push('the BigInt reference with shift 13 made 12 still agrees with the generator');
    // The twin wrong at one draw alone, halved there.
    const wrongAt = (twin: () => number, at: number): (() => number) => {
      let i = 0;
      return () => {
        i += 1;
        const v = twin();
        return i === at ? v / 2 : v;
      };
    };
    // Past the short seed's own reach, at the last reference draw — what comparing over the reach alone would miss.
    const shortReach = reachOf(short);
    if (!differs(drawBytes(unrecordedRandom(short), drawn(short)), wrongAt(bigintXorshift(short), REFERENCE_DRAWS))) {
      probes.push(`seed ${short} (reach ${shortReach}): the BigInt twin wrong at draw ${REFERENCE_DRAWS} alone still agrees`);
    }
    // Past the reference length, at the last draw of the longest reach — what comparing over the reference alone would miss.
    if (longest.n <= REFERENCE_DRAWS) {
      probes.push(`no seed reaches past ${REFERENCE_DRAWS} draws, so a disagreement beyond them could not be planted`);
    } else if (!differs(drawBytes(unrecordedRandom(longest.seed), longest.n), wrongAt(bigintXorshift(longest.seed), longest.n))) {
      probes.push(`seed ${longest.seed}: the BigInt twin wrong at draw ${longest.n} alone, its last, still agrees`);
    }
    const ok = probes.length === 0;
    say(
      'RG02_ONE_SEED_IS_ONE_SEQUENCE_BYTE_FOR_BYTE_AND_A_SECOND_IMPLEMENTATION_AGREES',
      ok,
      probeDetail(ok, probes, `${all.length} seed(s) — 1, ${short} (the first whose reach, ${shortReach} draws, is below ${REFERENCE_DRAWS}), ${XORSHIFT32_PERIOD} and every seed this run drew from — each drawn twice to the same float64 bytes over the larger of its reach and ${REFERENCE_DRAWS}, ${compared} draws in all, and every one of them equal to a BigInt implementation written from the definition; that implementation disagrees with its first shift 12 instead of 13, wrong at draw ${REFERENCE_DRAWS} of seed ${short} alone, and wrong at draw ${longest.n} of seed ${longest.seed} alone`),
      'determinism is a contract (A18\'s rule for the selftest\'s own inputs): the same seed has to be the same population on every machine, and a 32-bit integer step whose draw is exact in a double is what makes that true; the BigInt twin shares no operator with it',
    );
  }

  // --- RG03: the plant — the replaced map, under RG01's probe, repeats on every seed --
  {
    const probes: string[] = [];
    const checked = seeds.length > 0 ? seeds : [1, 7, 9381, 12345];
    const cycles = new Set<number>();
    let earliest = { seed: 0, at: Number.POSITIVE_INFINITY };
    let latest = { seed: 0, at: 0 };
    for (const s of checked) {
      const old = reach.get(s)?.old ?? replacedFirstRepeat(s);
      const length = reach.get(s)?.length ?? old.tail + old.period + 1;
      const at = firstRepeatedDraw(replacedLcg(s), length);
      cycles.add(old.period);
      if (at === null) probes.push(`seed ${s}: the replaced map repeated nothing within ${length} draws`);
      else {
        if (at !== old.tail + old.period + 1) probes.push(`seed ${s}: the probe found the repeat at draw ${at}, the cycle search at ${old.tail + old.period + 1}`);
        if (at < earliest.at) earliest = { seed: s, at };
        if (at > latest.at) latest = { seed: s, at };
      }
    }
    const ok = probes.length === 0;
    say(
      'RG03_THE_REPLACED_GENERATOR_REPEATS_UNDER_THE_SAME_PROBE_ON_EVERY_SEED',
      ok,
      probeDetail(ok, probes, `the replaced \`(s * 1103515245 + 12345) % 2^31\` in doubles, over ${checked.length} seed(s): each repeats at the draw the cycle search predicts, from draw ${earliest.at} (seed ${earliest.seed}) to draw ${latest.at} (seed ${latest.seed}), onto cycle length(s) ${[...cycles].sort((a, b) => a - b).join(', ')} — the probe RG01 passes is red on it`),
      'a gate nobody has seen fail is not a gate: RG01\'s probe is only worth its green if it goes red on the generator the card measured, at the draw a second method (Brent\'s cycle search) predicts',
    );
  }

  // --- RG04: a seed that is not a 32-bit nonzero integer is refused by name --
  {
    const probes: string[] = [];
    const refusals: string[] = [];
    for (const s of [0, -1, 1.5, 2 ** 32, Number.NaN]) {
      try {
        unrecordedRandom(s);
        probes.push(`seed ${s} was accepted`);
      } catch (err) {
        const message = (err as Error).message;
        if (!message.startsWith(`seededRandom: seed ${s} is not an integer from 1 to ${XORSHIFT32_PERIOD}`)) probes.push(`seed ${s} refused as "${message}"`);
        else refusals.push(String(s));
      }
    }
    for (const s of [1, XORSHIFT32_PERIOD]) {
      try {
        const v = unrecordedRandom(s)();
        if (!(v > 0 && v < 1)) probes.push(`seed ${s}'s first draw is ${v}, not in (0, 1)`);
      } catch (err) {
        probes.push(`seed ${s} was refused: ${(err as Error).message}`);
      }
    }
    const ok = probes.length === 0;
    say(
      'RG04_A_SEED_THAT_IS_NOT_A_NONZERO_32_BIT_INTEGER_IS_REFUSED_BY_NAME',
      ok,
      probeDetail(ok, probes, `seeds ${refusals.join(', ')} each refused naming the seed and the range; 1 and ${XORSHIFT32_PERIOD}, the range's ends, accepted with a first draw inside (0, 1)`),
      'never invent a value: seed 0 would be a generator drawing 0 for ever, and a seed past 32 bits would silently be another seed — both are refused by name rather than mapped to something nearby',
    );
  }
  return bad;
}

/** The core suite: `src/core/`'s reader and setup pose, the second dumper in `tools/pose_oracle.ts`, compare's absences, the gate's instrument and the tree rule. */
