        properties: { rotate: { to: { rotate: { max: 100 } } }, x: { to: { x: { max: 100 } } }, y: { to: { y: { max: 100 } } }, scaleX: { to: { scaleX: {} } }, scaleY: { to: { scaleY: {} } }, shearY: { to: { shearY: { max: 100 } } } },
        mixRotate: 0.5,
