        const parentOf = new Map(bones.map((b) => [b.name as string, b.parent as string | undefined]));
        const below = (top: string, x: string): boolean => {
          for (let at = parentOf.get(x); at !== undefined; at = parentOf.get(at)) if (at === top) return true;
          return false;
        };
