// ---------------------------------------------------------------------------
// what each of the twelve slider readers can produce (issue #420, stage 1)
// ---------------------------------------------------------------------------
//
// 🔒 `docs/AUTHORING.md` §3.5.2.1 states a table: for each of the six
// `FromProperty` readers, under each `local` flag, the floor and ceiling of what
// the reader can return. A documented table nobody derives is exactly the defect
// the CUR gates were built for — four of five cards in #380's checklist were the
// same shape, *the repository makes a claim about itself and nothing derives it*
// — so this suite re-measures every cell through spine-core and compares.
//
// ⭐ It is TWO-SIDED, and that is the whole design. A containment check alone
// passes a table that has been loosened to `[-1e9, 1e9]`, and a tightness check
// alone passes one that has been narrowed until the readings fall outside it. So
// RD04 says nothing left the stated bound and RD05 says each stated end is
// actually reached. RD06 is the third side — the eighteen ends the table calls
// `none` have to genuinely run away, because a table that quietly bounded them is
// a table that would licence refusing every non-`rotate` slider.
//
// ⚠️ The derivation is asserted BEFORE any of it (RD01). A scanner that stops
// matching goes silent, not red: if the table were renamed, reformatted or
// deleted, an unchecked scan would find zero rows and report twelve agreements
// out of zero comparisons.
//
// The imports are their own statement rather than additions to the block at the
// top of the file, so this suite lands as one contiguous hunk.
import {
  FromRotate,
  FromScaleX,
  FromScaleY,
  FromShearY,
  FromX,
  FromY,
  MathUtils,
  SliderData,
} from '@esotericsoftware/spine-core';

/**
 * The six property names the rig spec offers, in `RIG_FROM_PROPERTIES` order.
 *
 * ⚠️ A function and not a `const`, because this suite is appended AFTER `main()`
 * is called: a module-level binding down here is in its temporal dead zone when
 * the suite runs, and a function declaration is hoisted. Found by running it.
 */
function readerProperties(): string[] {
  return ['rotate', 'x', 'y', 'scaleX', 'scaleY', 'shearY'];
}

/** One row of the table `docs/AUTHORING.md` §3.5.2.1 states. */
interface ReaderRow {
  line: number;
  property: string;
  local: boolean;
  reader: string;
  /** `null` = the cell says `none`. */
  floor: number | null;
  ceiling: number | null;
}

/**
 * Parse the table out of the shipped guide.
 *
 * The row form is fixed and narrow on purpose: five cells, the first one of the
 * six property names in backticks and the second `true` or `false` in backticks.
 * A table that stops matching that form yields zero rows, which RD01 refuses.
 */
function readerTableRows(text: string): { rows: ReaderRow[]; faults: string[] } {
  const rows: ReaderRow[] = [];
  const faults: string[] = [];
  const props = new Set(readerProperties());
  const bare = (cell: string): string => cell.replace(/[`*]/g, '').trim();
  text.split('\n').forEach((line, i) => {
    if (!line.trimStart().startsWith('|')) return;
    const cells = line.trim().replace(/^\|/, '').replace(/\|$/, '').split('|').map((c) => c.trim());
    if (cells.length !== 5) return;
    const property = bare(cells[0]);
    const flag = bare(cells[1]);
    if (!props.has(property) || (flag !== 'true' && flag !== 'false')) return;
    const at = `docs/AUTHORING.md:${i + 1}`;
    // `` `FromScaleX`, world `` — the class and the branch, cross-checked here.
    const reads = /^`(From[A-Za-z]+)`,\s*(world|local)$/.exec(cells[2].trim());
    if (reads === null) {
      faults.push(`${at}  the "Reads" cell is ${JSON.stringify(cells[2])}; wanted \`FromX\`, world|local`);
      return;
    }
    if (reads[2] !== (flag === 'true' ? 'local' : 'world')) {
      faults.push(`${at}  the "Reads" cell says ${reads[2]} and the \`"local"\` cell says ${flag}`);
      return;
    }
    // `none`, or a backticked number followed by `reached` / `approached`.
    const bound = (cell: string, which: string): { value: number | null } | null => {
      if (bare(cell) === 'none') return { value: null };
      const found = /^`(-?[\d.]+)`,\s*(reached|approached)$/.exec(cell.trim());
      if (found === null) {
        faults.push(
          `${at}  the ${which} cell is ${JSON.stringify(cell)}; wanted \`none\` or \`<number>\`, reached|approached`,
        );
        return null;
      }
      return { value: Number(found[1]) };
    };
    const floor = bound(cells[3], 'floor');
    const ceiling = bound(cells[4], 'ceiling');
    if (floor === null || ceiling === null) return;
    rows.push({ line: i + 1, property, local: flag === 'true', reader: reads[1], floor: floor.value, ceiling: ceiling.value });
  });
  return { rows, faults };
}

/** The bone fields a reader probe writes. */
interface ReaderFields {
  rotation?: number;
  x?: number;
  y?: number;
  scaleX?: number;
  scaleY?: number;
  shearX?: number;
  shearY?: number;
}

/** The rig the suite measures through: twelve sliders on one bone. */
function readerFixtureRig(pinned: boolean): Record<string, unknown> {
  const constraints: Array<Record<string, unknown>> = [];
  if (pinned) {
    constraints.push({
      name: 'pin',
      type: 'transform',
      bones: ['src'],
      source: 'driver',
      properties: {
        rotate: { to: { rotate: {} } },
        scaleX: { to: { scaleX: {} } },
        scaleY: { to: { scaleY: {} } },
        shearY: { to: { shearY: {} } },
      },
      mixRotate: 1,
      mixScaleX: 1,
      mixScaleY: 1,
      mixShearY: 1,
    });
  }
  for (const property of readerProperties()) {
    for (const local of [false, true]) {
      constraints.push({
        name: `${property}-${local ? 'local' : 'world'}`,
        type: 'slider',
        animation: 'wave',
        bone: 'src',
        property,
        from: 0,
        to: 0,
        // ⚠️ Not decorative. A smaller `scale` puts the `rotate` world dial's own
        // range past 360°, which `src/compile.ts` refuses by name — the fixture
        // would not build at all. That refusal firing on this file's first draft
        // is the shortest available proof that the guard is live.
        scale: 0.005,
        local,
      });
    }
  }
  return {
    bones: [
      { name: 'root' },
      { name: 'gp', parent: 'root', x: 0, y: 0 },
      { name: 'parent', parent: 'gp', x: 0, y: 0 },
      { name: 'src', parent: 'parent', x: 0, y: 0, length: 10 },
      { name: 'driver', parent: 'root', x: 0, y: 0, length: 10 },
      { name: 'flag', parent: 'root', x: 20, y: 0, length: 10 },
      { name: 'block', parent: 'root', x: 0, y: 0, length: 12 },
    ],
    constraints,
  };
}

/** The motion spec the reader fixture's sliders apply. */
function readerFixtureMotion(): Record<string, unknown> {
  return {
    spec: 'rigc-motion/1',
    archetype: 'static_probe',
    cut: 'static_probe',
    easings: {},
    animations: {
      wave: {
        duration: 1,
        loop: false,
        tracks: [{ bone: 'flag', property: 'rotate', keys: [{ t: 0, v: [0] }, { t: 1, v: [30] }] }],
      },
    },
  };
}

/** Compile the reader fixture and parse it back through spine-core. */
function readerFixture(pinned: boolean): { data: SkeletonData; sliders: Map<string, SliderData> } {
  const dirs = writeProbeRig(readerFixtureRig(pinned));
  const motionPath = join(dirs.dir, 'probe.motion.json');
  writeFileSync(motionPath, `${JSON.stringify(readerFixtureMotion(), null, 2)}\n`);
  const result = compile({ rigPath: dirs.rigPath, motionPath, outDir: dirs.outDir, imagesDir: dirs.dir });
  const data = skeletonDataFromText(result.skeletonText, result.atlasText);
  const sliders = new Map<string, SliderData>();
  for (const constraint of data.constraints) {
    if (constraint instanceof SliderData) sliders.set(constraint.name, constraint);
  }
  return { data, sliders };
}

/**
 * One reading, taken the way `Slider.update` takes it: set up, write the local
 * pose, run the world transform, and — only under `local` —
 * `validateLocalTransform`, which is the call that decides whether the local
 * branch reads the number the author wrote or a decomposition of what the
 * constraints left behind (RD10).
 */
function readerValue(data: SkeletonData, slider: SliderData, src: ReaderFields, driver: ReaderFields = {}): number {
  const skeleton = new Skeleton(data);
  skeleton.setupPose();
  skeleton.update(0);
  const put = (name: string, fields: ReaderFields): void => {
    const bone = skeleton.findBone(name);
    if (bone === null) throw new Error(`reader suite: the fixture has no bone "${name}"`);
    const pose = bone.pose;
    if (fields.rotation !== undefined) pose.rotation = fields.rotation;
    if (fields.x !== undefined) pose.x = fields.x;
    if (fields.y !== undefined) pose.y = fields.y;
    if (fields.scaleX !== undefined) pose.scaleX = fields.scaleX;
    if (fields.scaleY !== undefined) pose.scaleY = fields.scaleY;
    if (fields.shearX !== undefined) pose.shearX = fields.shearX;
    if (fields.shearY !== undefined) pose.shearY = fields.shearY;
  };
  put('src', src);
  put('driver', driver);
  skeleton.updateWorldTransform(Physics.reset);
  const bone = skeleton.findBone('src');
  if (bone === null) throw new Error('reader suite: the fixture has no bone "src"');
  if (slider.local) bone.appliedPose.validateLocalTransform(skeleton);
  return slider.property.value(skeleton, bone.appliedPose, slider.local, [0, 0, 0, 0, 0, 0]);
}

/**
 * The seam and extreme poses the table's six bounded ends come off, plus the two
 * that drive every field to ±1e9 so the eighteen `none` ends have somewhere to
 * run to. Each is measured in `bench/studies/2026-09-06-readers`.
 */
function readerSeamPoses(): ReaderFields[] {
  return [
    { rotation: -1e-14 },
    { rotation: 0 },
    { scaleX: 0, scaleY: 0 },
    { rotation: -1e-14, shearX: 0, shearY: -89.99999999999999, scaleX: -1, scaleY: -1 },
    { rotation: -179.999999999, shearX: 179.999999999, shearY: 89.999999999, scaleX: -1, scaleY: -1 },
    { rotation: 1e9, x: 1e9, y: 1e9, scaleX: 1e9, scaleY: 1e9, shearX: 0, shearY: 1e9 },
    { rotation: -1e9, x: -1e9, y: -1e9, scaleX: -1e9, scaleY: -1e9, shearX: 0, shearY: -1e9 },
  ];
}

/**
 * The pose lattice, fixed rather than seeded — this is a control, not the study.
 * The axes straddle every branch the six readers have: the `atan2` seams at 0°
 * and ±180°, both signs of every scale, and a zero scale.
 */
function readerSweepPoses(): ReaderFields[] {
  const angles = [-540, -270, -180.0001, -180, -179.9999, -90, -0.0001, 0, 0.0001, 90, 179.9999, 180, 180.0001, 360, 1000];
  const scales = [-3, -1, 0, 1e-9, 1, 3];
  const shifts = [-1000, 0, 1000];
  const out: ReaderFields[] = [];
  for (const rotation of angles) {
    for (const shearY of angles) {
      for (const scaleX of scales) {
        out.push({
          rotation,
          shearY,
          shearX: rotation,
          scaleX,
          scaleY: -scaleX,
          x: shifts[out.length % 3],
          y: shifts[(out.length + 1) % 3],
        });
      }
    }
  }
  return out;
}

/**
 * A slider by name, or a throw. There are exactly twelve and they are named by
 * construction, so a miss is a broken fixture rather than a case to fall back
 * from — and a fallback here would be the "default that measures the wrong
 * thing" this repository names in its own doctrine.
 */
function readerSlider(sliders: Map<string, SliderData>, name: string): SliderData {
  const found = sliders.get(name);
  if (found === undefined) throw new Error(`reader suite: the fixture has no slider "${name}"`);
  return found;
}

/** The next representable double above `x`, by incrementing its bit pattern. */
function readerNextDoubleAbove(x: number): number {
  const view = new DataView(new ArrayBuffer(8));
  view.setFloat64(0, x);
  view.setBigUint64(0, view.getBigUint64(0) + 1n);
  return view.getFloat64(0);
}

/**
 * Where `value += 360` starts rounding a negative reading up to exactly 360 —
 * **bisected on the runtime's own expression, never computed.**
 *
 * 🚨 The bisection exists because the arithmetic was wrong. This figure was once
 * `(360 * Number.EPSILON) / 2` = 3.997e-14: `Number.EPSILON` is the ulp of
 * **1.0**, the spacing of the binade `[1, 2)`, and 360 lives in `[256, 512)`
 * where the spacing is `256 · EPSILON`. The interval it supported claimed
 * readings the reader does not produce — the exact failure the suite is about, in
 * the suite. Bisecting `v + 360 === 360` models nothing and cannot be wrong by a
 * binade.
 */
function readerWrapThreshold(): { misses: number; reaches: number; bracketMisses: boolean; bracketReaches: boolean } {
  const reaches360 = (v: number): boolean => v + 360 === 360;
  const from = -1e-13;
  const to = -0;
  let lo = from;
  let hi = to;
  for (let step = 0; step < 4096; step++) {
    const mid = (lo + hi) / 2;
    if (mid === lo || mid === hi) break;
    if (reaches360(mid)) hi = mid;
    else lo = mid;
  }
  // The bracket is asserted rather than assumed: both ends are facts about the
  // arithmetic and either could move under a different engine.
  return { misses: lo, reaches: hi, bracketMisses: !reaches360(from), bracketReaches: reaches360(to) };
}

/** An extreme by cell key, or a throw — every row is fed before any is read. */
function readerExtreme(extremes: Map<string, number>, key: string): number {
  const found = extremes.get(key);
  if (found === undefined) throw new Error(`reader suite: no extreme recorded for ${key}`);
  return found;
}

function runSliderReaderSuite(): number {
  console.log('\n── what each of the twelve slider readers can produce, against the table (issue #420) ──');
  let bad = 0;
  const say = (name: string, ok: boolean, detail: string, why: string): void => {
    bad += reportCase(name, ok, detail, why);
  };

  const authoring = readFileSync(join(import.meta.dir, 'docs', 'AUTHORING.md'), 'utf8');
  const { rows, faults } = readerTableRows(authoring);
  const wanted: string[] = [];
  for (const property of readerProperties()) for (const local of [false, true]) wanted.push(`${property}/${local}`);
  const seen = rows.map((r) => `${r.property}/${r.local}`);
  const missing = wanted.filter((k) => !seen.includes(k));
  const duplicated = seen.filter((k, i) => seen.indexOf(k) !== i);

  // --- RD01: the derivation floor -------------------------------------------
  say(
    'RD01_the_readers_table_in_the_shipped_guide_is_FOUND_and_every_cell_parses',
    rows.length === 12 && faults.length === 0 && missing.length === 0 && duplicated.length === 0,
    `parsed ${rows.length} row(s) out of docs/AUTHORING.md` +
      (missing.length ? `; missing ${missing.join(', ')}` : '') +
      (duplicated.length ? `; duplicated ${duplicated.join(', ')}` : '') +
      (faults.length ? `; ${faults.length} unparseable cell(s): ${faults.join(' | ')}` : ''),
    'every case below compares a measurement against these rows, so a table that was renamed, reformatted or ' +
      'deleted would leave them all agreeing with nothing. A scanner that stops matching goes silent, not red — ' +
      'this is the clause that makes it red',
  );

  const { data, sliders } = readerFixture(false);
  const keyOf = (row: ReaderRow): string => `${row.property}-${row.local ? 'local' : 'world'}`;

  // --- RD02: the readers are the ones rigc's own `property` produced ---------
  const classes: Record<string, (p: unknown) => boolean> = {
    FromRotate: (p) => p instanceof FromRotate,
    FromX: (p) => p instanceof FromX,
    FromY: (p) => p instanceof FromY,
    FromScaleX: (p) => p instanceof FromScaleX,
    FromScaleY: (p) => p instanceof FromScaleY,
    FromShearY: (p) => p instanceof FromShearY,
  };
  const readerMismatch = rows
    .filter((row) => {
      if (!sliders.has(keyOf(row))) return true;
      const slider = readerSlider(sliders, keyOf(row));
      const test = classes[row.reader];
      return test === undefined || !test(slider.property) || slider.local !== row.local;
    })
    .map(
      (row) =>
        `${row.property}/${row.local} wants ${row.reader}, got ` +
        `${sliders.has(keyOf(row)) ? readerSlider(sliders, keyOf(row)).property.constructor.name : 'no slider'}`,
    );
  // ⚠️ Every detail below names the ROW COUNT as well as the disagreement.
  // Without it a run whose table lost eleven rows prints "all 1 rows agree" next
  // to a FAIL, which is a detail reciting the wanted answer — the thing PS37's
  // comment says not to write.
  const over = `over ${rows.length} of 12 row(s)`;
  say(
    'RD02_every_row_names_the_reader_CLASS_the_parser_actually_built_from_that_property',
    rows.length === 12 && readerMismatch.length === 0,
    readerMismatch.length === 0
      ? `${over}: every one agrees by \`instanceof\`, on a skeleton rigc compiled from the six \`property\` strings`
      : `${over}: ${readerMismatch.join('; ')}`,
    'the table is about spine-core classes and a rig spec names them with strings. If `SkeletonJson` ever mapped ' +
      '`scaleX` to a different class, every bound below would be measured off the wrong reader and still agree ' +
      'with itself',
  );

  // --- RD03: the basis — a slider cannot pass anything but zeros -------------
  const liveSkeleton = new Skeleton(data);
  liveSkeleton.setupPose();
  liveSkeleton.update(0);
  liveSkeleton.updateWorldTransform(Physics.reset);
  const liveSliders = liveSkeleton.constraints.filter((c) => c instanceof Slider);
  const sliderOffsets = (Slider as unknown as { offsets: number[] }).offsets;
  say(
    'RD03_the_offsets_array_a_slider_hands_its_reader_is_all_zeros',
    liveSliders.length === 12 && sliderOffsets.length === 6 && sliderOffsets.every((v) => v === 0),
    `${liveSliders.length} live Slider(s); \`Slider.offsets\` = [${sliderOffsets.join(', ')}]`,
    'every world row of the table is stated FOR ZERO OFFSETS — with a non-zero array the two scale floors move to ' +
      'the offset and the `rotate` circle moves bodily once the offset leaves [-360, 360]. `Slider.offsets` is a ' +
      'private static, so a slider cannot reach that, and this is the clause that says so rather than a comment',
  );

  // --- the measurement every remaining case reads ---------------------------
  const poses = [...readerSweepPoses(), ...readerSeamPoses()];
  const low = new Map<string, number>();
  const high = new Map<string, number>();
  let negativeScaleWorld = 0;
  for (const row of rows) {
    if (!sliders.has(keyOf(row))) continue;
    const slider = readerSlider(sliders, keyOf(row));
    const key = `${row.property}/${row.local}`;
    for (const pose of poses) {
      const value = readerValue(data, slider, pose);
      if (!Number.isFinite(value)) continue;
      if (!low.has(key) || value < readerExtreme(low, key)) low.set(key, value);
      if (!high.has(key) || value > readerExtreme(high, key)) high.set(key, value);
      if (!row.local && (row.property === 'scaleX' || row.property === 'scaleY') && value < 0) negativeScaleWorld++;
    }
  }
  const READER_TOLERANCE = 1e-6;
  const READER_AWAY = 1e6;

  // --- RD04: nothing left the stated bound ----------------------------------
  const escaped: string[] = [];
  for (const row of rows) {
    const key = `${row.property}/${row.local}`;
    if (row.floor !== null && readerExtreme(low, key) < row.floor - READER_TOLERANCE) {
      escaped.push(`${key} read ${readerExtreme(low, key)}, below the stated floor ${row.floor}`);
    }
    if (row.ceiling !== null && readerExtreme(high, key) > row.ceiling + READER_TOLERANCE) {
      escaped.push(`${key} read ${readerExtreme(high, key)}, above the stated ceiling ${row.ceiling}`);
    }
  }
  say(
    'RD04_no_reading_over_the_sweep_left_the_bound_its_row_states',
    rows.length === 12 && escaped.length === 0,
    `${over}, ${poses.length} pose(s) each = ${poses.length * rows.length} readings: ` +
      (escaped.length === 0 ? 'none outside' : escaped.join('; ')),
    'the containment half. On its own it would pass a table loosened to [-1e9, 1e9], which is what RD05 is for',
  );

  // --- RD05: and every stated end is actually REACHED -----------------------
  const slack: string[] = [];
  let ends = 0;
  for (const row of rows) {
    const key = `${row.property}/${row.local}`;
    if (row.floor !== null) {
      ends++;
      if (Math.abs(readerExtreme(low, key) - row.floor) > READER_TOLERANCE) {
        slack.push(`${key} floor states ${row.floor}, lowest measured ${readerExtreme(low, key)}`);
      }
    }
    if (row.ceiling !== null) {
      ends++;
      if (Math.abs(readerExtreme(high, key) - row.ceiling) > READER_TOLERANCE) {
        slack.push(`${key} ceiling states ${row.ceiling}, highest measured ${readerExtreme(high, key)}`);
      }
    }
  }
  say(
    'RD05_every_stated_end_is_REACHED_by_a_measured_pose_and_not_merely_respected',
    ends === 6 && slack.length === 0,
    `${over}, ${ends} of 6 bounded end(s): ` +
      (slack.length === 0
        ? `each within ${READER_TOLERANCE} of a measured extreme — ` +
          rows
            .filter((r) => r.floor !== null || r.ceiling !== null)
            .map(
              (r) =>
                `${r.property}/${r.local} [${readerExtreme(low, `${r.property}/${r.local}`)}, ` +
                `${readerExtreme(high, `${r.property}/${r.local}`)}]`,
            )
            .join(', ')
        : slack.join('; ')),
    'the tightness half, and the one that catches the opposite drift: a bound nobody reaches is a bound nobody ' +
      'measured. The count is asserted too, because a table that lost a bounded row would leave the survivors ' +
      'agreeing among themselves',
  );

  // --- RD06: the `none` ends genuinely run away — the negative control ------
  const notFar: string[] = [];
  let nones = 0;
  for (const row of rows) {
    const key = `${row.property}/${row.local}`;
    if (row.floor === null) {
      nones++;
      if (!(readerExtreme(low, key) < -READER_AWAY)) notFar.push(`${key} floor says none, lowest measured ${readerExtreme(low, key)}`);
    }
    if (row.ceiling === null) {
      nones++;
      if (!(readerExtreme(high, key) > READER_AWAY)) notFar.push(`${key} ceiling says none, highest measured ${readerExtreme(high, key)}`);
    }
  }
  say(
    'RD06_every_none_end_runs_past_1e6_including_all_six_local_rows',
    nones === 18 && notFar.length === 0,
    `${over}, ${nones} of 18 unbounded end(s): ` +
      (notFar.length === 0
        ? `all past ±${READER_AWAY} — the six \`local\` rows read ` +
          rows
            .filter((r) => r.local)
            .map(
              (r) =>
                `${r.property} [${readerExtreme(low, `${r.property}/true`)}, ` +
                `${readerExtreme(high, `${r.property}/true`)}]`,
            )
            .join(', ')
        : notFar.join('; ')),
    '⛔ the load-bearing negative control. `local: true` takes a different branch entirely, and if it were bounded ' +
      'too then a compiler that refused every non-`rotate` slider would look correct against a suite that only ' +
      'tested refusals. This exact shape caught a real mutant in #410',
  );

  // --- RD07: the correction to #417's `[0, 360)` ----------------------------
  const rotateWorld = readerSlider(sliders, 'rotate-world');
  const at360 = readerValue(data, rotateWorld, { rotation: -1e-14 });
  const at0 = readerValue(data, rotateWorld, { rotation: 0 });
  const piDeg = Math.PI * MathUtils.radDeg;
  let holeLow = -Infinity;
  let holeHigh = Infinity;
  for (let i = 0; i <= 20000; i++) {
    const value = readerValue(data, rotateWorld, { rotation: 179.99 + i * 1e-6 });
    if (value <= 180 && value > holeLow) holeLow = value;
    if (value > 180 && value < holeHigh) holeHigh = value;
  }
  // The two exact ends of the hole are the two branches of `atan2` at ±π, and a
  // bone pointing along −x lands on one or the other by the SIGN OF THE ZERO in
  // `c`. Nothing else in this suite needs a signed zero.
  holeLow = Math.max(holeLow, readerValue(data, rotateWorld, { rotation: -0, shearX: -0, scaleX: -1 }));
  holeHigh = Math.min(holeHigh, readerValue(data, rotateWorld, { rotation: 0, shearX: 0, scaleX: -1 }));
  // 🔒 HOW FAR below zero the wrap reaches from, bisected — and compared against
  // the figure the guide prints. This number was narrated in this case's origin
  // string and asserted nowhere, which is #429's shape exactly; it was also
  // WRONG, by a binade. Both halves are fixed here: the threshold is measured,
  // and the doc's copy of it is inside the gate rather than beside it.
  const wrap = readerWrapThreshold();
  const halfUlp = (readerNextDoubleAbove(360) - 360) / 2;
  const statedThreshold = [...authoring.matchAll(/`\[(-[0-9.e-]+)°, 0°\)`/g)].map((found) => Number(found[1]));
  say(
    'RD07_the_rotate_world_wrap_REACHES_360_from_a_MEASURED_threshold_and_leaves_a_hole_at_180',
    at360 === 360 &&
      at0 === 0 &&
      Math.abs(holeLow - piDeg) < 1e-9 &&
      Math.abs(holeHigh - (360 - piDeg)) < 1e-9 &&
      holeHigh - holeLow > 5e-6 &&
      wrap.bracketMisses &&
      wrap.bracketReaches &&
      wrap.reaches === -halfUlp &&
      statedThreshold.length === 1 &&
      statedThreshold[0] === wrap.reaches,
    `a bone at -1e-14° reads ${at360} and at 0° reads ${at0}; the hole runs ${holeLow}..${holeHigh}, ` +
      `${(holeHigh - holeLow).toExponential(3)}° wide (π·radDeg = ${piDeg}); the wrap bisects to ` +
      `[${wrap.reaches}, 0) — largest miss ${wrap.misses} — and half an ulp of 360 off the representation is ` +
      `${halfUlp} (agree: ${wrap.reaches === -halfUlp}); docs/AUTHORING.md prints ` +
      `${statedThreshold.length === 1 ? statedThreshold[0] : `${statedThreshold.length} candidate interval(s)`}`,
    "issue #417 established the reader's range as `[0, 360)` and this measures `[0, 360]`: `if (value < 0) value " +
      '+= 360` on a reading a hair below zero ROUNDS, from -2.842170943040401e-14 up. ⚠️ That threshold was once ' +
      'written `(360 * Number.EPSILON) / 2` = 3.997e-14, which is 360/256 too large — `Number.EPSILON` is the ulp ' +
      'of 1.0 and 360 is in the binade [256, 512) — so the stated interval claimed readings the reader does not ' +
      'produce, which is this suite\'s own subject applied to this suite. It is bisected on `v + 360 === 360` now, ' +
      'cross-checked against the representation, and compared to the guide\'s copy so the figure is gated rather ' +
      'than narrated. Nothing about the compile guard changes — it refuses above 360 + 1e-6, so 360 was already ' +
      'inside the accepted set and this can only strengthen it',
  );

  // --- RD08: the scale floor is 0, attained, and the sign is gone -----------
  const degenerateX = readerValue(data, readerSlider(sliders, 'scaleX-world'), { scaleX: 0, scaleY: 0 });
  const degenerateY = readerValue(data, readerSlider(sliders, 'scaleY-world'), { scaleX: 0, scaleY: 0 });
  const mirrored = readerValue(data, readerSlider(sliders, 'scaleX-world'), { scaleX: -1 });
  const mirroredLocal = readerValue(data, readerSlider(sliders, 'scaleX-local'), { scaleX: -1 });
  say(
    'RD08_the_scale_world_floor_is_0_ATTAINED_and_a_negative_scale_reads_positive',
    degenerateX === 0 &&
      degenerateY === 0 &&
      Math.abs(mirrored - 1) < 1e-9 &&
      Math.abs(mirroredLocal + 1) < 1e-9 &&
      negativeScaleWorld === 0,
    `a zero-scale bone reads exactly ${degenerateX} / ${degenerateY}; \`scaleX: -1\` reads ${mirrored} in world and ` +
      `${mirroredLocal} in local; negative world-scale readings over the sweep: ${negativeScaleWorld}`,
    'issue #420 asked whether the floor is genuinely 0 and whether 0 is ATTAINED or only approached. It is ' +
      'attained — by a degenerate bone, exactly — so the floor is a closed end and a range whose bottom is 0 is ' +
      'legal. The second half is what a refusal has to say instead of "out of range": the sign is not clipped, it ' +
      'is lost to `Math.sqrt`, so the author gets the mirror of their dial rather than a dead half',
  );

  // --- RD09: `local: true` is never the thing that gets refused -------------
  const localRange = (property: string, local: boolean): Record<string, unknown> => ({
    bones: [
      { name: 'root' },
      { name: 'block', parent: 'root', x: 0, y: 0, length: 12 },
      { name: 'dial', parent: 'root', x: 0, y: 40, length: 10 },
      { name: 'flag', parent: 'root', x: 40, y: 0, length: 20 },
    ],
    constraints: [
      { name: 'axis', type: 'slider', animation: 'wave', bone: 'dial', property, from: 0, to: 0.5, scale: 0.033333, local },
    ],
  });
  const localMotion = readerFixtureMotion();
  const refusedLocal: string[] = [];
  for (const property of readerProperties()) {
    const message = refusal(writeProbeRig(localRange(property, true)), localMotion);
    if (message !== null) refusedLocal.push(`${property}: ${message}`);
  }
  const worldRotateRefused = refusal(writeProbeRig(localRange('rotate', false)), localMotion);
  say(
    'RD09_the_same_range_compiles_under_local_true_for_all_six_while_the_rotate_world_twin_is_refused',
    refusedLocal.length === 0 && worldRotateRefused !== null && worldRotateRefused.includes('below 0°'),
    refusedLocal.length === 0
      ? 'six `local: true` sliders over -15°..15° all compiled; the `rotate` `local: false` twin was ' +
        (worldRotateRefused === null ? 'NOT refused — it compiled' : `refused: ${worldRotateRefused.slice(0, 120)}…`)
      : refusedLocal.join(' | '),
    '⛔ the compiler-side half of RD06, and it is not vacuous only because the twin IS refused: -15°..15° is ' +
      'exactly the range #405 refuses under `local: false`. Whatever stage 2 adds for the scale floor, this case ' +
      'has to keep passing for all six properties',
  );

  // --- RD10: `local: true` is a passthrough only on a free bone -------------
  const pinned = readerFixture(true);
  const freeRotate = readerValue(data, readerSlider(sliders, 'rotate-local'), { rotation: -500 });
  const pinnedRotate = readerValue(pinned.data, readerSlider(pinned.sliders, 'rotate-local'), { rotation: -500 }, { rotation: -500 });
  const freeScale = readerValue(data, readerSlider(sliders, 'scaleX-local'), { scaleX: -2 });
  const pinnedScale = readerValue(pinned.data, readerSlider(pinned.sliders, 'scaleX-local'), { scaleX: -2 }, { scaleX: -2 });
  say(
    'RD10_a_constrained_bone_reads_a_DECOMPOSITION_on_the_local_branch_not_the_authored_number',
    freeRotate === -500 && Math.abs(pinnedRotate + 140) < 1e-4 && freeScale === -2 && Math.abs(pinnedScale - 2) < 1e-9,
    `rotation -500 reads ${freeRotate} on a free bone and ${pinnedRotate} on one a transform constraint drives; ` +
      `scaleX -2 reads ${freeScale} free and ${pinnedScale} constrained`,
    '`Slider.update` calls `bone.appliedPose.validateLocalTransform` first, and on a bone a constraint moved that ' +
      'recomputes the local pose from the world matrix — `atan2Deg` for the angles, `Math.sqrt` for `scaleX`. The ' +
      'producible SET is unbounded either way, so the table stands; what does not is "`local: true` reads the ' +
      'number you authored", which is the repair every one of these refusals wants to name',
  );

  return bad;
}

// ---------------------------------------------------------------------------
// the scripts a document STATES still do what the page says (issue #477)
// ---------------------------------------------------------------------------
//
// ⭐ **Why this suite exists, and why it is not the transcript gate one surface
// over.** `GT01`–`GT06` hold what a page QUOTES to what the tool prints, and
// `CUR01`–`CUR11` hold what a page SAYS ABOUT the tool to the tool. Neither of
// them runs a page's own scripts, and `LS03` — which reads a gallery README's
// invocations — does not either, because a `bun -e` snippet is not a rigc
// invocation. So the tree had an instrument for a doc's output and one for a
// doc's claims, and nothing that ran a doc's commands.
//
// 🚨 It cost a week. `docs/FACE.md` §9.2 states three builds of
// `gallery/portrait`, two of them driven by a `bun -e` script that writes a
// variant motion spec. Script (a) built its deform run as one row of five shifts
// repeated five times — the mesh's own column order, correct while the vertex
// list was row-major. [#375](https://github.com/rig-c/core/issues/375)
// renumbered that list along its outline walk on 2026-09-04 and the script went
// on writing the same five values at the same POSITIONS in a list where a
// position no longer meant a column. A `vertices` run is positional by format,
// so scattered shifts are a perfectly legal deform: the build stayed green,
// nothing on the page moved, and the section spent a week demonstrating
// something other than what it says (#471).
//
// ⭐ **A stale figure shows up at one site; a broken command shows up at every
// figure it feeds.** That one script fed §9.2's comparison table and §9.3's
// `check` row, and the two stayed consistent with each other while diverging
// from the tool — which is why comparing a transcript against one of them is a
// weak signal and running the command is a strong one.
//
// **What this asks, and it is deliberately the cheaper question.** Not *are the
// figures current* — that is #468's business and #474's clause covers the fenced
// half of it — but **does the command still do what the page says it does?** The
// claims it checks are verdicts: `A39_DEFORM_KEEPS_TRIANGLE_WINDING` PASS on one
// build and FAIL on another, and the emit rule under them, `refused, and nothing
// written`. Not one figure is read.
//
// ⚠️ **The reach of that, measured rather than implied, because the limit is the
// first thing a later reader will need.** Reproducing the broken script (a)
// verbatim and running this gate's own comparison: `A35 PASS`, `A39 PASS`, exit
// 0, artifact written — **exactly what the page states for it**, so this suite
// does NOT catch the 2026-09-04 defect it was written after. What it does catch
// is the 2026-09-03 one, which is the same class the other way up: both scripts
// had gone silent, build (b) came back green where the page says FAIL, and this
// suite reports that on the same run. ⇒ A verdict claim is falsifiable exactly
// where the page's own verdict differs from the build the script would produce
// if it did nothing at all — for (b) it does, for (a) it does not. Closing (a)
// needs a figure or a render, and both are a different cost class.
//
// **How the population is derived, one clause at a time and never a list.** The
// universe is `git ls-files` filtered to markdown — the repository's own answer
// to what is in the tree, so no document is left out by a judgement made here.
// Inside it, a script is a `bun -e '…'` statement of a fenced block. Everything
// that narrows it from there is a property of the script, and every script that
// falls out carries the reason it fell, printed by `DS01`:
//
//  1. it reads a path the repository does not carry — the boundary #429 and #441
//     both drew, and the reason `gallery/nod`'s third script is out: it reads
//     `gallery/nod/build/skeleton.json`, which is generated and gitignored;
//  2. it writes no file under a name the page spells, which is what a script
//     that only prints figures looks like, and what a base64 art-writer looks
//     like too (`Bun.write(p, …)` names nothing);
//  3. no rigc command in its fence reads what it writes — one fence is one
//     runnable unit, and a page whose next step is "save this JSON block under
//     this name" is stating an authoring step rather than a command;
//  4. its product is not somewhere this runner can redirect, or its command
//     carries shell quoting this runner does not parse;
//  5. the fence gives it no `(x)` label, or no table of its own page opens a
//     column on that label, or that column states no assertion verdict.
//
// ⚠️ **The population is thin, and it is stated rather than hidden** — `DS01`
// prints the counts it derives on every run (documents, fences, scripts, and
// which of them are verified), its floor is what makes it loud if it goes
// thinner, and the reasons above are what a later reader needs in order to
// widen it deliberately. 🔸 A hand-kept restatement of those counts stood here
// and had drifted from the run; it is deleted rather than retyped, for the
// reason issue #634 gives and #617 landed against in the file header.
//
// **How a claim is read, and why it is a verdict and never a figure.** A fence
// labels a script `# (a) …`; a table on the same page opens a column on `(a)`;
// a row of that table whose first cell names exactly one assertion states that
// assertion's verdict in every column. So the claim is `A39 PASS` for the build
// script (a) feeds and `A39 FAIL` for script (b)'s, and it is compared against
// the run's own gutter line — the same `  PASS  A39_…` the tool prints for
// everybody. 🔒 A row whose cell carries digits contributes nothing: the reader
// takes `PASS` or `FAIL` and stops, which is what keeps this from drifting into
// #468 with extra steps.
//
// ⚠️ **Every path a document hardcodes under `/tmp/` is redirected into the
// round's own directory**, and a script that writes anywhere else is out of
// reach rather than run. §9.2 states `/tmp/swapped.motion.json`: two runs of
// `bun run selftest` at once would share it and one would read the other's file.
// Nothing is written into the repository, and nothing survives the round.
//
// **What is NOT in scope, stated so the boundary reads as chosen.** §9.2's good
// build is not run here: its stated command renders 57 frames and writes both
// its artifacts INTO the repository, and the same build is already gated by
// `GALLERY_EXAMPLE_IS_GREEN[portrait/rig-play]` — which the page itself says,
// leaving the tally to the tool. §9.3's `check` row needs
// `gallery/portrait/render/`, generated and gitignored, and a gate that renders
// per run is a different cost class. Both of those are the `good` column and the
// unmapped columns `DS01` counts.
//
// ⚠️ **Cost, measured rather than guessed.** One round is every verified script
// followed by every command that reads one — 4 subprocesses today — and there
// are four rounds: the tree's own, one per script with its write dropped, and
// one with the products rotated. **Sixteen runs, 1.6–2.8 s of wall clock** over
// five measurements, depending on what else the machine is doing. The two cheap
// plants cost nothing at all: a flipped verdict and a removed label are re-read
// off the outcomes already taken.

/**
 * The one prefix this runner can redirect, and therefore the only place a
 * verified script may write.
 *
 * ⚠️ A function and not a `const`, because this suite is appended AFTER `main()`
 * is called: a module-level binding down here is in its temporal dead zone when
 * the suite runs, and a function declaration is hoisted. The same reason
 * `readerProperties` above is one.
 */
function docScratchPrefix(): string {
  return '/tmp/';
}

/** One statement of a fenced block — a comment, a script, or a command. */
interface DocStatement {
  /** 1-based line of its first line. */
  line: number;
  text: string;
  comment: boolean;
}

/**
 * The statements of a fenced block.
 *
 * A statement runs to the end of its line unless a single quote is still open or
 * the line ends on a continuation, which is the whole of the shell this needs: a
 * document states a script as one `bun -e '…'` and nothing here nests.
 *
 * ⚠️ Comment lines come off BEFORE the quote count, and that is not tidiness.
 * §9.2's own label reads `# (a) INVERT ONE BAND: give the two far columns each
 * other's shift.` — one apostrophe — and a counter that read it would swallow
 * the script below into the comment and find no script at all.
 */
function docStatements(body: readonly string[], first: number): DocStatement[] {
  const out: DocStatement[] = [];
  let held: string[] = [];
  let at = first;
  let quotes = 0;
  for (let i = 0; i < body.length; i++) {
    const line = body[i];
    if (held.length === 0 && /^\s*#/.test(line)) {
      out.push({ line: first + i, text: line, comment: true });
      continue;
    }
    if (held.length === 0) at = first + i;
    held.push(line);
    quotes += (line.match(/'/g) ?? []).length;
    if (quotes % 2 !== 0 || /\\$/.test(line)) continue;
    if (held.join('\n').trim() !== '') out.push({ line: at, text: held.join('\n'), comment: false });
    held = [];
  }
  if (held.length > 0 && held.join('\n').trim() !== '') out.push({ line: at, text: held.join('\n'), comment: false });
  return out;
}

/** One fenced block of a document, whatever its info string. */
interface DocFence {
  file: string;
  line: number;
  body: string[];
}

/** Every fenced block of one document. */
function docFences(file: string, text: string): DocFence[] {
  const out: DocFence[] = [];
  const lines = text.split('\n');
  let open: { line: number; body: string[] } | null = null;
  for (let i = 0; i < lines.length; i++) {
    if (!/^```/.test(lines[i])) {
      if (open !== null) open.body.push(lines[i]);
      continue;
    }
    if (open === null) open = { line: i + 1, body: [] };
    else {
      out.push({ file, line: open.line, body: open.body });
      open = null;
    }
  }
  return out;
}

/** One `bun -e` script a document states, and everything derived about it. */
interface DocScript {
  /** The page and the line its `bun -e` statement opens on — what a failure detail has to name. */
  where: string;
  file: string;
  /** The letter its fence labels it with, or null when the fence states none. */
  label: string | null;
  /** The line that label sits on, so a plant can take it off. */
  labelLine: number | null;
  /** The JS between the quotes, which is what actually runs. */
  source: string;
  /** Literal paths it reads and writes. A path built out of a variable is neither. */
  reads: string[];
  writes: string[];
  /** The tool statement in the same fence that reads its product, as the page spells it. */
  command: string | null;
  /** That command as argv, with `bun`, `cli.ts` and `rigc` taken off the front. */
  argv: string[];
  /** The `--out` it names, which is where "nothing written" is actually read. */
  out: string | null;
  /** Why this script is out of this gate's reach, or null when it is inside it. */
  reason: string | null;
}

/** One verdict a page states for one script, read off a table of the page's own. */
interface DocClaim {
  /** The page and the line of the table row the verdict is stated on. */
  where: string;
  file: string;
  label: string;
  assertion: string;
  verdict: 'PASS' | 'FAIL';
}

/** A markdown table, split into cells. */
interface DocTable {
  line: number;
  head: string[];
  rows: Array<{ line: number; cells: string[] }>;
}

/** One row of a markdown table, split on its pipes. */
function docTableCells(row: string): string[] {
  const trimmed = row.trim();
  return trimmed.slice(1, trimmed.length - 1).split('|').map((cell) => cell.trim());
}

/**
 * A cell with its decoration taken off — emphasis, code ticks, and whatever a
 * page puts in FRONT of what the cell names (`🆕 `). Everything after that is
 * content and is read as content.
 */
function docPlainCell(cell: string): string {
  return cell.replace(/\*\*/g, '').replace(/`/g, '').replace(/^[^\p{L}\p{N}(]*/u, '').trim();
}

/** Every markdown table of one document. */
function docTables(text: string): DocTable[] {
  const lines = text.split('\n');
  const out: DocTable[] = [];
  for (let i = 0; i < lines.length; i++) {
    if (!/^\|/.test(lines[i]) || !/^\|[\s:|-]+\|$/.test(lines[i + 1] ?? '')) continue;
    const rows: DocTable['rows'] = [];
    for (let j = i + 2; j < lines.length && /^\|/.test(lines[j]); j++) {
      rows.push({ line: j + 1, cells: docTableCells(lines[j]) });
    }
    out.push({ line: i + 1, head: docTableCells(lines[i]), rows });
  }
  return out;
}

/** What one scan of the documents found. */
interface DocScriptScan {
  /** Documents read. */
  files: number;
  /** Documents that state at least one script. */
  stating: string[];
  /** Fenced blocks that state at least one script. */
  fences: number;
  scripts: DocScript[];
  claims: DocClaim[];
  /** Tables some script's label maps onto. */
  tables: number;
  /** Columns of those tables no script's label names — the builds this gate does not run. */
  unmapped: number;
  faults: string[];
}

/**
 * Everything the documents say about the scripts they state.
 *
 * 🔒 The narrowing is the interesting half and every step of it is a property of
 * the script rather than a name on a list, because a hand-kept population is the
 * next thing to drift and this repository has a judgement about that. What a
 * script that falls out carries is the reason, which is what lets `DS01` print
 * the shape of the population instead of only its size.
 */
function scanDocScripts(docs: ReadonlyMap<string, string>, treeRoot: string): DocScriptScan {
  /** How a document states a script. The only form any page in this tree uses. */
  const lead = /^bun -e '/;
  /** How a fence labels one, so a table can open a column on the same thing. */
  const labelOf = /^#\s*\(([a-z])\)\s/;
  /** How a document states the tool: as this repository runs it, or as an installed reader does. */
  const toolStatement = /^(?:bun cli\.ts|rigc)\s+[a-z-]+\b/;
  const scratch = docScratchPrefix();
  const scan: DocScriptScan = {
    files: docs.size,
    stating: [],
    fences: 0,
    scripts: [],
    claims: [],
    tables: 0,
    unmapped: 0,
    faults: [],
  };
  const labelled = new Map<string, DocScript[]>();
  for (const [file, text] of docs) {
    let statesOne = false;
    for (const fence of docFences(file, text)) {
      const statements = docStatements(fence.body, fence.line + 1);
      if (!statements.some((one) => !one.comment && lead.test(one.text))) continue;
      scan.fences++;
      statesOne = true;
      for (let i = 0; i < statements.length; i++) {
        const statement = statements[i];
        if (statement.comment || !lead.test(statement.text)) continue;
        let label: string | null = null;
        let labelLine: number | null = null;
        for (let k = i - 1; k >= 0 && statements[k].comment; k--) {
          const found = labelOf.exec(statements[k].text.trim());
          if (found !== null) {
            label = found[1];
            labelLine = statements[k].line;
          }
        }
        const opens = statement.text.indexOf("'");
        const closes = statement.text.lastIndexOf("'");
        const source = closes > opens ? statement.text.slice(opens + 1, closes) : '';
        const reads = [...statement.text.matchAll(/Bun\.file\(\s*"([^"]+)"/g)].map((m) => m[1]);
        const writes = [...statement.text.matchAll(/Bun\.write\(\s*"([^"]+)"/g)].map((m) => m[1]);
        const consumer = statements
          .slice(i + 1)
          .find((one) => !one.comment && toolStatement.test(one.text) && writes.some((path) => one.text.includes(path)));
        const command = consumer?.text ?? null;
        const flat = command === null ? '' : command.replace(/\\\n\s*/g, ' ').replace(/\s+/g, ' ').trim();
        const argv =
          flat === '' ? [] : flat.split(' ').filter((token) => token !== 'bun' && token !== 'cli.ts' && token !== 'rigc');
        const outAt = argv.indexOf('--out');
        const stray = writes.find((path) => !path.startsWith(scratch));
        const script: DocScript = {
          where: `${file}:${statement.line}`,
          file,
          label,
          labelLine,
          source,
          reads,
          writes,
          command,
          argv,
          out: outAt >= 0 ? (argv[outAt + 1] ?? null) : null,
          reason: null,
        };
        const missing = reads.find((path) => !existsSync(join(treeRoot, path)));
        script.reason =
          missing !== undefined
            ? `it reads \`${missing}\`, which the repository does not carry`
            : writes.length === 0
              ? 'it writes no file under a name the page spells, so nothing in its fence can read what it made'
              : writes.length > 1
                ? `it writes ${writes.length} files under names the page spells, and the rotated-products plant below moves one product per script`
                : command === null
                  ? 'no rigc command in its fence reads what it writes'
                  : /["']/.test(flat)
                    ? 'the command beside it carries shell quoting this runner does not parse'
                    : script.out === null
                      ? 'the command beside it names no `--out`, so there is nowhere to read "nothing written" from'
                      : stray !== undefined
                        ? `it writes \`${stray}\`, which is not under \`${scratch}\` and so is not somewhere this runner can redirect`
                        : /\/tmp(?!\/)/.test(`${statement.text} ${flat}`)
                          ? `it or its command names \`/tmp\` without a trailing slash, which this runner cannot redirect into a directory of its own`
                          : label === null
                            ? 'the fence gives it no `(x)` label, so no column of any table names it'
                            : null;
        scan.scripts.push(script);
        if (script.reason === null && label !== null) {
          const bucket = labelled.get(file) ?? [];
          bucket.push(script);
          labelled.set(file, bucket);
        }
      }
    }
    if (statesOne) scan.stating.push(file);
  }

  // The claims. A label maps to a column of a table on its own page, and a row
  // whose first cell names exactly one assertion states that assertion's verdict
  // in every column of it.
  for (const [file, scripts] of labelled) {
    const tables = docTables(docs.get(file) ?? '');
    const used = new Set<number>();
    for (const script of scripts) {
      const label = script.label ?? '';
      const opens = (table: DocTable): boolean => table.head.some((cell) => docPlainCell(cell).startsWith(`(${label})`));
      const hits = tables.filter(opens);
      if (hits.length === 0) {
        script.reason = `no table in \`${file}\` opens a column on \`(${label})\`, so its page states no verdict for it`;
        continue;
      }
      if (hits.length > 1) {
        scan.faults.push(
          `${script.where}: ${hits.length} tables in \`${file}\` open a column on \`(${label})\` (lines ` +
            `${hits.map((table) => table.line).join(', ')}), so which of them states this script's verdicts is undecided`,
        );
        continue;
      }
      const table = hits[0];
      used.add(table.line);
      const column = table.head.findIndex((cell) => docPlainCell(cell).startsWith(`(${label})`));
      let stated = 0;
      for (const row of table.rows) {
        const names = [...row.cells[0].matchAll(/`(A\d\d_[A-Z\d_]+)`/g)].map((m) => m[1]);
        if (names.length !== 1) continue;
        const verdict = /\b(PASS|FAIL)\b/.exec(row.cells[column] ?? '');
        if (verdict === null) continue;
        stated++;
        scan.claims.push({
          where: `${file}:${row.line}`,
          file,
          label,
          assertion: names[0],
          verdict: verdict[1] === 'FAIL' ? 'FAIL' : 'PASS',
        });
      }
      if (stated === 0) {
        script.reason = `the table at \`${file}:${table.line}\` opens a column on \`(${label})\` and states no assertion verdict in it`;
      }
    }
    scan.tables += used.size;
    for (const table of tables) {
      if (!used.has(table.line)) continue;
      scan.unmapped += table.head.filter(
        (cell, at) =>
          at > 0 && cell.trim() !== '' && !scripts.some((one) => docPlainCell(cell).startsWith(`(${one.label ?? ''})`)),
      ).length;
    }
  }
  return scan;
}

/** The verified scripts of a scan, in the order the documents state them. */
function verifiedDocScripts(scan: DocScriptScan): DocScript[] {
  return scan.scripts.filter((script) => script.reason === null);
}

/** What one command a document states actually did. */
interface DocOutcome {
  /** The exit status of the script that fed it. */
  scriptStatus: number | null;
  /** The exit status of the command itself. */
  status: number | null;
  /** Assertion → the verdict the run printed for it. A FAIL anywhere wins. */
  verdicts: Map<string, string>;
  /** Whether the `--out` the command names is there afterwards. */
  wrote: boolean;
  /** What the tool said when it refused, so a detail can quote it. */
  stderr: string;
}

/**
 * Run one round: every verified script, then every command that reads one.
 *
 * ⚠️ The scripts go first as a group rather than each before its own command,
 * and the licence for that is asserted rather than assumed — `DS01` requires
 * that no script in the population reads another's product, which makes the two
 * orders the same execution. What it buys is the rotated-products plant: a
 * script handed its neighbour's path has to be able to write it before the
 * neighbour's command goes looking, or that plant would only ever measure a
 * missing file, which is the plant beside it.
 *
 * ⚠️ Every `/tmp/` a document hardcodes is redirected into this round's own
 * directory, which is removed afterwards. Two runs of `bun run selftest` at once
 * would otherwise share `/tmp/swapped.motion.json` and one would read the
 * other's; and a script the page points at the repository is refused by
 * `scanDocScripts` rather than run, so nothing here writes into the tree.
 */
function runDocScriptRound(
  scripts: readonly DocScript[],
  edits: ReadonlyMap<string, string>,
  treeRoot: string,
): Map<string, DocOutcome> {
  /** The gutter line every verdict of a rigc report is printed on. */
  const verdictLine = /^ {2}(PASS|FAIL|SKIP) {2}(A\d\d_[A-Z\d_]+)/;
  const dir = mkdtempSync(join(harnessTemp(), 'rigc-doc-script-'));
  const outcomes = new Map<string, DocOutcome>();
  try {
    const here = (text: string): string => text.split(docScratchPrefix()).join(`${dir}/`);
    const scriptStatus = new Map<string, number | null>();
    for (const script of scripts) {
      const run = spawnSync(process.execPath, ['-e', here(edits.get(script.where) ?? script.source)], {
        cwd: treeRoot,
        encoding: 'utf8',
      });
      scriptStatus.set(script.where, run.status);
    }
    for (const script of scripts) {
      const run = spawnSync(process.execPath, ['cli.ts', ...script.argv.map(here)], {
        cwd: treeRoot,
        encoding: 'utf8',
      });
      const verdicts = new Map<string, string>();
      for (const line of `${run.stdout}`.split('\n')) {
        const found = verdictLine.exec(line);
        if (found === null) continue;
        if (found[1] === 'FAIL' || !verdicts.has(found[2])) verdicts.set(found[2], found[1]);
      }
      outcomes.set(script.where, {
        scriptStatus: scriptStatus.get(script.where) ?? null,
        status: run.status,
        verdicts,
        wrote: script.out !== null && existsSync(here(script.out)),
        stderr: `${run.stderr}`.trim(),
      });
    }
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
  return outcomes;
}

/**
 * Everything the runs disagree with the pages about.
 *
 * Three clauses per script and not one of them is a figure: the verdict every
 * claim states, read off the run's own gutter; the tool's emit rule, read off
 * two channels that cannot agree by accident — the exit status and whether the
 * `--out` is there; and the page's own `refused, and nothing written`, taken
 * from the verdicts the page states and from nothing else.
 */
function judgeDocScripts(
  scripts: readonly DocScript[],
  claims: readonly DocClaim[],
  outcomes: ReadonlyMap<string, DocOutcome>,
): string[] {
  const faults: string[] = [];
  for (const script of scripts) {
    const outcome = outcomes.get(script.where);
    if (outcome === undefined) {
      faults.push(`${script.where}: nothing ran it, so nothing here says whether its page is still right about it`);
      continue;
    }
    if (outcome.scriptStatus !== 0) {
      faults.push(`${script.where}: the script itself exited ${String(outcome.scriptStatus)} rather than running to the end`);
    }
    const mine = claims.filter((one) => one.file === script.file && one.label === script.label);
    for (const claim of mine) {
      const got = outcome.verdicts.get(claim.assertion) ?? 'nothing at all';
      if (got !== claim.verdict) {
        faults.push(
          `${claim.where}: the page states ${claim.assertion} ${claim.verdict} for the build \`${script.where}\` feeds, ` +
            `and \`${(script.command ?? '').split('\n')[0].trim()}\` printed ${got}`,
        );
      }
    }
    if ((outcome.status === 0) !== outcome.wrote) {
      faults.push(
        `${script.where}: the build exited ${String(outcome.status)} and ${outcome.wrote ? 'wrote' : 'did not write'} ` +
          `\`${script.out ?? ''}\`, so its status and its artifact disagree about whether it was refused`,
      );
    }
    const refused = mine.some((claim) => claim.verdict === 'FAIL');
    if (refused === outcome.wrote) {
      faults.push(
        `${script.where}: the page states ` +
          `${refused ? 'a FAIL, so this build is refused and writes nothing' : 'no FAIL, so this build is green'}, and it ` +
          `${outcome.wrote ? 'wrote' : 'wrote nothing'} (exit ${String(outcome.status)}` +
          `${outcome.stderr === '' ? '' : `; ${outcome.stderr}`})`,
      );
    }
  }
  return faults;
}

/** A document with one line blanked to a bare `#` — how the label plant is applied. */
function docWithBlankedLine(text: string, line: number): string {
  const lines = text.split('\n');
  lines[line - 1] = '#';
  return lines.join('\n');
}

/** A script that stops writing anything: every `Bun.write` line taken off it. */
function scriptWithoutItsWrite(source: string): string {
  return source
    .split('\n')
    .filter((line) => !line.includes('Bun.write('))
    .join('\n');
}

/** A script that writes somebody else's product instead of its own. */
function scriptWritingInstead(script: DocScript, path: string): string {
  return script.source.split(`"${script.writes[0]}"`).join(`"${path}"`);
}

function runDocScriptSuite(): number {
  console.log('\n── the scripts a shipped document STATES, run (issue #477) ──');
  let bad = 0;
  const say = (name: string, ok: boolean, detail: string, why: string): void => {
    bad += reportCase(name, ok, detail, why);
  };

  const root = import.meta.dir;
  // The universe is the repository's own answer to what is in the tree. A skip
  // list here would be the hand-kept population this whole suite is arranged to
  // avoid, and `git ls-files` needs none: what is untracked or ignored — the
  // corpus, `node_modules`, a private symlink — is simply not in it.
  const listed = spawnSync('git', ['ls-files', '-z'], { cwd: root, encoding: 'buffer', maxBuffer: 256 * 1024 * 1024 });
  const treeFault =
    listed.error !== undefined || listed.status !== 0
      ? `git could not list the tracked files (${listed.error?.message ?? `exit ${String(listed.status)}: ${listed.stderr.toString('utf8').trim()}`})`
      : null;
  const docs = new Map<string, string>();
  if (treeFault === null) {
    for (const path of listed.stdout.toString('utf8').split('\u0000')) {
      if (path.endsWith('.md') && existsSync(join(root, path))) docs.set(path, readFileSync(join(root, path), 'utf8'));
    }
  }

  const scan = scanDocScripts(docs, root);
  const verified = verifiedDocScripts(scan);
  const outcomes = runDocScriptRound(verified, new Map(), root);
  const faults = judgeDocScripts(verified, scan.claims, outcomes);

  // --- DS01: the derivation floor, asserted before anything about content ---
  //
  // 🔒 Every end of this can come back empty and none of them goes red on its
  // own: a document that stops fencing its script, a fence that stops stating
  // the command beside it, a table renamed or reflowed, a label dropped, an
  // assertion renamed. Each of those takes a script out of the scan and leaves
  // `DS02` passing over nothing at all, which is the one failure a runner like
  // this cannot afford. ⭐ The floors are one per step and never one on their
  // sum, for `GT01`'s reason: a total that still clears its floor is exactly how
  // one step that went to zero stays hidden.
  //
  // ⚠️ `files >= 50` is a SMOKE floor against an observed 108, not a measured
  // bound — it is there to catch the listing coming back empty, which is what a
  // missing `git` looks like. Do not read it as a budget.
  const assertions = new Set(scan.claims.map((claim) => claim.assertion));
  const unreached = [...assertions].filter(
    (name) => ![...outcomes.values()].some((outcome) => outcome.verdicts.has(name)),
  );
  const products = new Set(verified.flatMap((script) => script.writes));
  const chained = verified.filter((script) => script.reads.some((path) => products.has(path)));
  // 🚨 Every floor is a PROBE and not a conjunct — `DQ01`'s clause, applied to
  // the second untouched twin (issue #496). Nine terms stood in this verdict
  // and the detail's ternary read ONE, `derivation`.
  //
  // ⭐ As in `GT01`, and worth the same precision: the sentence below is not a
  // false one. It interpolates all eight floored quantities, so a FAIL carried
  // every VALUE and no BOUND — the reader was told what the scan found and not
  // which floor it had stopped clearing. What moves is the bound, onto the row
  // for the step that went.
  //
  // ⛔ Nothing here is a new assertion or a relaxed one: the rows are the same
  // nine terms with the same thresholds, in one list the detail reads.
  const derivation = [
    ...(treeFault === null ? [] : [treeFault]),
    ...scan.faults,
    ...unreached.map(
      (name) =>
        `a table states a verdict for \`${name}\`, and not one of the runs prints that name — so the row is prose ` +
        'rather than a claim about this tool',
    ),
    ...chained.map(
      (script) =>
        `${script.where} reads another verified script's product, so running the scripts of a round before its ` +
        'commands is no longer the order the page states',
    ),
    ...floorProbes(
      [
        [scan.files, 50, `${scan.files} tracked markdown file(s) were read`],
        [scan.stating.length, 4, `${scan.stating.length} of them state a script`],
        [scan.fences, 5, `${scan.fences} fence(s) came off those pages`],
        [scan.scripts.length, 7, `${scan.scripts.length} script(s) came out of those fences`],
        [scan.tables, 1, `${scan.tables} table(s) of stated verdicts were found`],
        [scan.claims.length, 4, `${scan.claims.length} stated verdict(s) came off those tables`],
        [assertions.size, 2, `${assertions.size} distinct assertion(s) are named by them`],
        [verified.length, 2, `${verified.length} script(s) are verified and run here`],
      ],
      'so one STEP of this derivation came back thinner than it has ever been, and `DS02` below would be reporting ' +
        'a clean tree over less than it used to read',
    ),
  ];
  const reasons = scan.scripts.filter((script) => script.reason !== null);
  const held = derivation.length === 0;
  say(
    'DS01_THE_DOC_SCRIPT_SCAN_READ_THE_DOCUMENTS_THE_SCRIPTS_AND_THE_VERDICTS_STATED_FOR_THEM',
    held,
    probeDetail(
      held,
      derivation,
      `${scan.files} tracked markdown file(s) read, ${scan.stating.length} of which state a script ` +
        `(${scan.stating.join(', ')}); ${scan.fences} fence(s), ${scan.scripts.length} script(s), of which ` +
        `${verified.length} are run here and ${reasons.length} are out of reach — ` +
        `${reasons.map((script) => `${script.where} (${script.reason ?? ''})`).join('; ')}. The ${verified.length} ` +
        `verified: ${verified.map((script) => `${script.where} \`(${script.label ?? ''})\``).join(', ')}, holding ` +
        `${scan.claims.length} stated verdict(s) over ${assertions.size} assertion(s) ` +
        `{${[...assertions].sort().join(' ')}} off ${scan.tables} table(s), whose other ${scan.unmapped} column(s) ` +
        'no script of this population feeds',
    ),
    'a scanner is a vocabulary of shapes and a shape that stops matching goes quiet, not red. Five separate ' +
      'derivations stand between a document and a claim here — the fence, the script, the command that reads its ' +
      'product, the label, and the table column that opens on that label — and any one of them emptying leaves ' +
      'the check below reporting a clean tree over nothing. The out-of-reach set is printed rather than counted ' +
      'because it is the part a later reader has to widen deliberately: the scripts this tree states are a thin ' +
      'population and only a few of them are runnable, and the honest response to that is to say which ones are ' +
      'out of reach and why, not to stretch the grammar until the number looks better. ⚠️ Three cardinals stood ' +
      'in this sentence and two of them had drifted from the population the sentence above derives on every run, ' +
      'so they are deleted rather than retyped (issue #634) — and the cardinal that stood in "all eight figures" ' +
      'below went with them, for the same reason. ⚠️ Every floor here is a row in that same list rather than a conjunct of ' +
      'the verdict, for issue #493\'s reason: the sentence above is the one a run failing on a floor used to ' +
      'print, and it carries every figure without carrying one of the floors they are held to',
  );

  // --- DS02: the claims themselves ------------------------------------------
  //
  // The positive half is load-bearing exactly as `GT02`'s is: a check that only
  // reported disagreements would pass a runner that had stopped running
  // anything, so what each command was and what it printed is named here.
  say(
    'DS02_EVERY_SCRIPT_A_DOCUMENT_STATES_STILL_GETS_THE_VERDICT_ITS_PAGE_GIVES_IT',
    faults.length === 0 && verified.length > 0,
    faults.length > 0
      ? `${faults.length} disagreement(s) between a page and a run:\n          ${faults.join('\n          ')}`
      : verified.length === 0
        ? 'not one script was verified, so this line would be a pass over nothing at all'
        : `${verified.length} script(s) ran to the end and the ${verified.length} command(s) they feed reported ` +
          `${scan.claims.length} stated verdict(s) unchanged — ` +
          verified
            .map((script) => {
              const outcome = outcomes.get(script.where);
              const mine = scan.claims.filter((claim) => claim.file === script.file && claim.label === script.label);
              return (
                `\`(${script.label ?? ''})\` ${mine.map((claim) => `${claim.assertion} ${claim.verdict}`).join(', ')}, ` +
                `exit ${String(outcome?.status)} and ` +
                `${outcome?.wrote === true ? `wrote \`${script.out ?? ''}\`` : 'nothing written'}`
              );
            })
            .join('; '),
    'the two rows of §9.2\'s table this reads are claims the page makes in WORDS — one build passes A39 and one ' +
      'is refused by it — so no figure is compared and none has to be. That is the whole difference between this ' +
      'and the transcript gate: a stale figure shows up at one site, and a broken command shows up at every ' +
      'figure it feeds. Script (a) fed §9.2\'s table AND §9.3\'s `check` row for a week while agreeing with ' +
      'neither the tool nor itself, and nothing in the tree ran it',
  );

  // --- DS03: the runner against the ways a stated script stops matching -----
  //
  // Red-first, on every verified script rather than on one chosen by hand, and
  // four-sided. Two plants are free — they are re-read off the outcomes already
  // taken — and two cost a round each.
  //
  // ⭐ The label plant is the one that motivates `DS01`: take a script's label
  // off and it does not go red, it stops being a script this suite knows about.
  // That has to fault NOTHING and drop exactly one, which is the shape `GT03`
  // holds its own anchor plant to.
  const misses: string[] = [];
  let planted = 0;
  let silenced = 0;

  for (let i = 0; i < scan.claims.length; i++) {
    const flipped = scan.claims.map((claim, at) =>
      at === i ? { ...claim, verdict: (claim.verdict === 'PASS' ? 'FAIL' : 'PASS') as 'PASS' | 'FAIL' } : claim,
    );
    planted++;
    // ⚠️ Against what the unplanted run already judges, not against zero —
    // issue #491, and the inverse of the correction the label plant below
    // carries. A page this run already disagrees with leaves a fault standing
    // whatever this flip does, so the absolute form reports the flip as caught
    // without testing it. Measured with every flip replaced by a no-op and
    // every verdict in the tree flipped to leave one standing disagreement per
    // page: the absolute form printed PASS over four flips that changed
    // nothing, and this form names all four. Spelled through `raisedBy` since
    // issue #506, which is the same subtraction with the question in front of
    // it rather than behind.
    if (raisedBy(judgeDocScripts(verified, flipped, outcomes), { was: faults }).length === 0) {
      misses.push(`${scan.claims[i].where}: ${scan.claims[i].assertion} for \`(${scan.claims[i].label})\` flipped — not faulted`);
    }
  }

  for (const script of verified) {
    const edited = new Map(docs);
    const before = docs.get(script.file) ?? '';
    const after = docWithBlankedLine(before, script.labelLine ?? 0);
    planted++;
    if (after === before) {
      misses.push(`${script.where}: its label line could not be taken off, so the plant changed nothing`);
      continue;
    }
    edited.set(script.file, after);
    const again = scanDocScripts(edited, root);
    const left = verifiedDocScripts(again);
    // ⚠️ Against what the unplanted run already judges, not against zero —
    // issue #486, the fourth of four sites, and one layer up: the list here is
    // a JUDGEMENT rather than a scan's `faults`, and the shape is the same
    // because `faults` above is that same judgement over the unplanted tree.
    // Taking a label off has to raise nothing NEW; a verdict a page was already
    // wrong about is not something this plant did. Measured on a doubly-planted
    // run — every verdict `docs/FACE.md` states for
    // `A35_DEFORM_KEYS_FIT_THE_ATTACHMENT` flipped, leaving the page
    // disagreeing with the run, and then this plant on top of it: the absolute
    // form reported `(and 2 unlabelled script(s) did not drop out cleanly)` on
    // both scripts when both had dropped out cleanly, and this form reports
    // neither.
    const raisedByPlant = judgeDocScripts(left, again.claims, outcomes).filter((fault) => !faults.includes(fault));
    if (
      raisedByPlant.length !== 0 ||
      left.length !== verified.length - 1 ||
      again.scripts.length !== scan.scripts.length
    ) {
      silenced++;
    }
  }

  for (const script of verified) {
    const edited = scriptWithoutItsWrite(script.source);
    planted++;
    if (edited === script.source) {
      misses.push(`${script.where}: it has no \`Bun.write\` line to take off, so the plant changed nothing`);
      continue;
    }
    const round = runDocScriptRound(verified, new Map([[script.where, edited]]), root);
    // ⚠️ Against the unplanted judgement, not against zero — issue #491. The
    // judge here is scoped to one script, and so is the standing fault it can
    // be satisfied by: a page already wrong about the verdicts of THIS script
    // leaves this clause reporting nothing whatever the edit did. `faults` is
    // that same judgement over the whole verified set, and because the judge
    // walks scripts independently, what it holds for this one is exactly the
    // baseline to take off.
    if (raisedBy(judgeDocScripts([script], scan.claims, round), { was: faults }).length === 0) {
      misses.push(`${script.where}: its write dropped — not faulted`);
    }
  }

  {
    const edits = new Map<string, string>();
    for (let i = 0; i < verified.length; i++) {
      const mine = verified[i];
      const theirs = verified[(i + 1) % verified.length].writes[0];
      const edited = scriptWritingInstead(mine, theirs);
      planted++;
      if (edited === mine.source) {
        misses.push(`${mine.where}: its product could not be rotated to \`${theirs}\`, so the plant changed nothing`);
        continue;
      }
      edits.set(mine.where, edited);
    }
    if (edits.size === verified.length) {
      const round = runDocScriptRound(verified, edits, root);
      for (const script of verified) {
        // Against the unplanted judgement, for the reason the write plant above
        // gives — issue #491.
        if (raisedBy(judgeDocScripts([script], scan.claims, round), { was: faults }).length === 0) {
          misses.push(`${script.where}: the products rotated — not faulted`);
        }
      }
    }
  }

  // 🚨 The floors are rows in this list and not conjuncts of the verdict, for
  // `DQ01`'s reason and issue #493's measurement: the clean sentence below says
  // the label plant "faulted nothing on all N of them", and with `planted >= 8`
  // in the boolean alone that was the sentence a run short of its plants
  // printed. ⛔ Same four terms, same thresholds — only the detail changes.
  const probes = [
    ...misses,
    ...(silenced === 0 ? [] : [`${silenced} unlabelled script(s) did not drop out cleanly`]),
    ...(planted >= 8
      ? []
      : [
          `only ${planted} edit(s) were planted over ${verified.length} verified script(s), where 8 is the floor, ` +
            'so a plant stopped being APPLIED rather than stopped being caught',
        ]),
    ...(verified.length > 0 ? [] : ['not one script is verified, which is not a population to plant on']),
  ];
  say(
    'DS03_THE_RUNNER_FAULTS_EVERY_WAY_A_STATED_SCRIPT_STOPS_DOING_WHAT_ITS_PAGE_SAYS',
    probes.length === 0,
    probes.length === 0
      ? `${planted} planted edit(s) over ${verified.length} verified script(s) and ${scan.claims.length} stated ` +
        'verdict(s) — every verdict flipped in turn, every script\'s write dropped, and the products rotated so ' +
        'each build reads what its neighbour wrote — each faulted by name; and taking a script\'s LABEL off ' +
        `faulted nothing on all ${verified.length} of them, dropping each silently out of the verified set while ` +
        `all ${scan.scripts.length} script(s) are still found, which is what DS01's floor is for`
      : `${planted} edit(s) were planted and ${probes.length} check(s) over them did not hold:\n          ` +
        probes.join('\n          '),
    'a runner that reports clean while running nothing is the failure this whole family is written against, so ' +
      'the plants are two kinds on purpose. The flipped verdict and the rotated products break the COMPARISON and ' +
      'the SCRIPT respectively, and both have to be loud. The dropped write is the shape the 2026-09-03 defect ' +
      'had — a script that quietly stopped producing anything — and the label plant is the opposite requirement: ' +
      'it must go quiet, because a script that stops being labelled stops being one this suite can hold to ' +
      'anything, and only a floor can see that — which is why the floor that says the plant RAN is a row here ' +
      'rather than a conjunct nothing prints',
  );

  // --- DS04–DS06: the renumbering a stated script's product has to survive --
  //
  // ⭐ **What the three cases above cannot see, and it is the more expensive
  // class.** `DS02` compares a page's VERDICT against a run's gutter line, so a
  // claim is falsifiable exactly where the page's verdict differs from the
  // build the script would produce doing nothing at all. For §9.2's build (b)
  // it does — the page says `A39 FAIL` — and for (a) it does not. Script (a) as
  // it shipped 2026-09-04 → 09-11 put through `DS02`'s own comparison reports
  // `A35 PASS`, `A39 PASS`, exit 0, artifact written: **exactly what the page
  // states for it**. A script that goes QUIET is caught above; a script that
  // stays GREEN while doing something else is not, and that is the one #471
  // cost a week.
  //
  // **The property, and why it is read off the product rather than off a
  // sentence.** §9.2's own comment states it in words — *a `vertices` run is
  // positional, so a script that assumes the list's order rather than reading
  // it breaks in silence the day the list is renumbered* — and issue #479
  // refused to gate that sentence, because a subject picked out of one comment
  // in one document is a hand-kept list wearing a derivation. So the subject
  // here is not the sentence. It is **every script whose product is a
  // `vertices` run**, which is a property of the artifact the script writes and
  // is read off that artifact every run.
  //
  // ⚠️ **That population is ONE script today, and the size is not the
  // objection.** What makes a population hand-kept is that a member was chosen,
  // and nothing is chosen here: the day a second page's script writes a motion
  // spec with a positional run it joins without an edit, and the day §9.2's
  // stops writing one the floor below goes red rather than the case going
  // quiet. The alternative issue #479 records — the property becomes something
  // a script DECLARES, the way a block declares itself unreproducible to
  // `GT01` — was rejected for the reverse reason: `GT01`'s marker is an OPT-OUT
  // of a population already derived, and a declaration here would be an
  // OPT-IN. A script that assumes its list's order and declares nothing is
  // precisely the defect, so the gate's subject would become the author's
  // memory. #471's script would not have declared.
  //
  // 🔒 **The renumbering is derived from the refusal, not from the mesh.**
  // `checkHullOrder` states two clauses and nothing else: the outline vertices
  // are the first `hull` of the list, and they trace the walk in order — either
  // direction, since it is the same polygon. Read as a specification rather
  // than as two error messages, that says the accepted relabelings are exactly
  // **any dihedral map of the outline walk onto itself, times any permutation
  // at all of the interior**, because the interior is what neither clause
  // mentions. The family below is one representative per generator of that
  // group plus their composite, built from `traceOutline`'s own walk — and it
  // is re-asked of the permuted list through `checkHullOrder` itself, so the
  // day a clause is added about the interior this window REFUSES by name
  // instead of quietly permuting something the compiler no longer accepts.
  //
  // ⚠️ `checkHullOrder` is not the only reader of a vertex list — `meshEdges`,
  // the deform runs, `A21` and `A39` all index into it — so passing that
  // function is not the claim. Each renumbering is BUILT, through the page's
  // own command, and `DS04` holds it to green with its artifact on disk.
  //
  // **Two-sided, and the negative half is the load-bearing one.** A permutation
  // check that faults on everything is the "test only refusals" failure: what
  // makes the positive reading mean anything is that a script which resolves
  // each shift through the vertex's own coordinate reports **0 of N** under
  // every one of these, while the run it writes has visibly moved (`DS05`
  // prints both figures side by side, and a renumbering that moved the product
  // in no way is a row rather than a pass).
  //
  // ⚠️ **Cost, measured rather than guessed.** One baseline run of each
  // subject, then a script run and a build per renumbering, then a script run
  // per renumbering for the plant — **thirteen subprocesses** on this tree,
  // about the same again as the four rounds above.
  /**
   * The phrase the moved-offset row is recognised by. It is a `const` and not
   * a repeated literal because the plant below has to name the row it needs
   * rather than take any new fault — which is the defect that clause shipped
   * with for one run.
   */
  const MOVED_OFFSET_ROW = 'differ after un-permuting';
  const renumberRoot = mkdtempSync(join(harnessTemp(), 'rigc-doc-renumber-'));
  const construction: string[] = [];
  const invariance: string[] = [];
  const plantMisses: string[] = [];
  const told: string[] = [];
  const measured: string[] = [];
  const refused: string[] = [];
  let subjectCount = 0;
  let familyNames: string[] = [];
  let permutedMeshes = 0;
  let plantsRun = 0;

  /** A parsed JSON object, as much of one as this window reads. */
  const asObject = (value: unknown): Record<string, unknown> | null =>
    typeof value === 'object' && value !== null && !Array.isArray(value) ? (value as Record<string, unknown>) : null;
  /** A list of numbers, or null where the field is something else. */
  const asNumbers = (value: unknown): number[] | null =>
    Array.isArray(value) && value.every((one) => typeof one === 'number') ? (value as number[]) : null;
  /** Whatever `JSON.parse` makes of this text, or null where it makes nothing. */
  const asJson = (text: string): unknown => {
    try {
      return JSON.parse(text) as unknown;
    } catch {
      return null;
    }
  };

  /** Every authored mesh of a parsed rig spec, under the path that names it. */
  const meshesOfRig = (node: unknown, path: readonly string[] = []): Array<{ at: string[]; att: Record<string, unknown> }> => {
    const here = asObject(node);
    if (here === null) return [];
    const mine =
      asNumbers(here.vertices) !== null && asNumbers(here.triangles) !== null ? [{ at: [...path], att: here }] : [];
    return [...mine, ...Object.keys(here).flatMap((key) => meshesOfRig(here[key], [...path, key]))];
  };

  /**
   * Every renumbering `checkHullOrder`'s two clauses leave open for one mesh,
   * as `newIndexOf[old]` maps. The walk and the interior both come out of
   * `traceOutline`, so nothing here knows a number about any particular mesh.
   */
  const renumberingsOf = (att: Record<string, unknown>): Map<string, number[]> => {
    const count = (asNumbers(att.vertices) ?? []).length / 2;
    const outline = traceOutline(count, asNumbers(att.triangles) ?? []);
    checkHullOrder(outline, count);
    const { hull, walk } = outline;
    const onWalk = new Set(walk);
    const interior = [...Array(count).keys()].filter((one) => !onWalk.has(one));
    const inside = interior.length;
    const map = (turn: number, flip: boolean, mirror: boolean): number[] => {
      const out = [...Array(count).keys()];
      walk.forEach((vertex, at) => {
        out[vertex] = walk[flip ? (hull - at + turn) % hull : (at + turn) % hull];
      });
      interior.forEach((vertex, at) => {
        out[vertex] = inside === 0 ? vertex : interior[mirror ? inside - 1 - at : at];
      });
      return out;
    };
    return new Map([
      ['the outline rotated one step along its walk', map(1, false, false)],
      ['the outline reflected', map(0, true, false)],
      ['the interior reversed', map(0, false, true)],
      ['the outline rotated and the interior reversed', map(1, false, true)],
    ]);
  };

  /** One mesh renumbered in place — every field that indexes its vertex list moved with it. */
  const renumberMesh = (att: Record<string, unknown>, newIndexOf: readonly number[]): void => {
    const vertices = asNumbers(att.vertices) ?? [];
    const uvs = asNumbers(att.uvs);
    const weights = Array.isArray(att.weights) ? (att.weights as unknown[]) : null;
    const movedVertices = [...vertices];
    const movedUvs = uvs === null ? null : [...uvs];
    const movedWeights = weights === null ? null : [...weights];
    for (let i = 0; i < newIndexOf.length; i++) {
      const to = newIndexOf[i];
      movedVertices[2 * to] = vertices[2 * i];
      movedVertices[2 * to + 1] = vertices[2 * i + 1];
      if (uvs !== null && movedUvs !== null) {
        movedUvs[2 * to] = uvs[2 * i];
        movedUvs[2 * to + 1] = uvs[2 * i + 1];
      }
      if (weights !== null && movedWeights !== null) movedWeights[to] = weights[i];
    }
    att.vertices = movedVertices;
    if (movedUvs !== null) att.uvs = movedUvs;
    if (movedWeights !== null) att.weights = movedWeights;
    att.triangles = (asNumbers(att.triangles) ?? []).map((one) => newIndexOf[one]);
    const edges = asNumbers(att.edges);
    if (edges !== null) att.edges = edges.map((one) => 2 * newIndexOf[one / 2]);
  };

  /** One positional deform key of a motion spec, as the fields a comparison needs. */
  interface DocDeformRun {
    /** `animation/slot/key`, which is what pairs a key with itself across two runs. */
    where: string;
    skin: string;
    slot: string;
    attachment: string | null;
    from: number;
    values: number[];
  }

  /** Every `vertices` key a motion spec states, or null where it is not one. */
  const deformRunsOf = (text: string): DocDeformRun[] | null => {
    const spec = asObject(asJson(text));
    const animations = spec === null ? null : asObject(spec.animations);
    if (animations === null) return null;
    const out: DocDeformRun[] = [];
    for (const name of Object.keys(animations)) {
      const body = asObject(animations[name]);
      const tracks = body === null || !Array.isArray(body.deform) ? [] : (body.deform as unknown[]);
      for (const one of tracks) {
        const track = asObject(one);
        const keys = track === null || !Array.isArray(track.keys) ? [] : (track.keys as unknown[]);
        keys.forEach((rawKey, at) => {
          const key = asObject(rawKey);
          const values = key === null ? null : asNumbers(key.vertices);
          if (key === null || values === null) return;
          out.push({
            where: `${name}/${String(track?.slot ?? '')}/key${at}`,
            skin: typeof track?.skin === 'string' ? track.skin : 'default',
            slot: typeof track?.slot === 'string' ? track.slot : '',
            attachment: typeof track?.attachment === 'string' ? track.attachment : null,
            from: typeof key.fromVertex === 'number' ? key.fromVertex : 0,
            values,
          });
        });
      }
    }
    return out;
  };

  /** The authored mesh one deform key indexes into, under the rig's own skin/slot/attachment path. */
  const meshPathOf = (rig: unknown, run: DocDeformRun): string[] | null => {
    const skins = asObject(asObject(rig)?.skins);
    const slot = asObject(asObject(skins?.[run.skin])?.[run.slot]);
    if (slot === null) return null;
    const authored = Object.keys(slot).filter((name) => {
      const att = asObject(slot[name]);
      return att !== null && asNumbers(att.vertices) !== null && asNumbers(att.triangles) !== null;
    });
    const wanted = run.attachment ?? (authored.length === 1 ? authored[0] : null);
    return wanted !== null && authored.includes(wanted) ? ['skins', run.skin, run.slot, wanted] : null;
  };

  /** One deform key as a full per-vertex offset table, zero where the run does not reach. */
  const offsetTable = (run: DocDeformRun, count: number): Array<[number, number]> => {
    const out: Array<[number, number]> = [...Array(count)].map((): [number, number] => [0, 0]);
    for (let i = 0; run.from + i < count && i * 2 + 1 < run.values.length; i++) {
      out[run.from + i] = [run.values[i * 2], run.values[i * 2 + 1]];
    }
    return out;
  };

  /**
   * Two products compared offset by offset, each one read at the index the
   * renumbering moved it to. `missing` is a key the second run does not state
   * at all, which is a different failure from a key whose numbers moved.
   */
  const compareProducts = (
    was: readonly DocDeformRun[],
    now: readonly DocDeformRun[] | null,
    mapOf: (run: DocDeformRun) => readonly number[] | null,
  ): { differ: number; total: number; worst: number; missing: number } => {
    let differ = 0;
    let total = 0;
    let worst = 0;
    let missing = 0;
    for (const run of was) {
      const map = mapOf(run);
      const mate = now?.find((one) => one.where === run.where) ?? null;
      if (map === null || mate === null) {
        missing++;
        continue;
      }
      const before = offsetTable(run, map.length);
      const after = offsetTable(mate, map.length);
      for (let i = 0; i < map.length; i++) {
        total++;
        const dx = Math.abs(after[map[i]][0] - before[i][0]);
        const dy = Math.abs(after[map[i]][1] - before[i][1]);
        if (dx > 1e-9 || dy > 1e-9) differ++;
        worst = Math.max(worst, dx, dy);
      }
    }
    return { differ, total, worst, missing };
  };

  /**
   * One script run into a directory of its own, with the product it wrote.
   *
   * ⚠️ The redirect is applied to the source AND to the path the product is
   * read back from, and that is not symmetry for its own sake. The first
   * version of the plant below wrote into the round's directory and looked for
   * its product under the literal `/tmp/` the page spells, where nothing was:
   * the plant then faulted as a MISSING key rather than as a moved offset, so
   * `DS06` printed green over a clause that had never run. It was found by
   * planting a plant that is not broken — the real script in the plant's
   * place — and watching `DS06` stay green where it had to go red.
   *
   * 🚨 **The redirect rewrites a page's own literal and nothing else, and the
   * rule that keeps it that way is ORDER: `here` runs on page text FIRST, and
   * a path already resolved inside `dir` is spliced in AFTER it, never
   * through it.** A rewrite of the prefix `/tmp/` is not idempotent, because
   * on a machine where `os.tmpdir()` IS `/tmp` the replacement text starts
   * with the pattern: running it over `<dir>/rig.json` yields
   * `<dir>/<dir-relative>/rig.json`. CI on ubuntu found exactly that, on a
   * tree whose macOS runs were green because `os.tmpdir()` there is under
   * `/var/folders/…` and the two never collided.
   *
   * ⭐ So this suite has to be run BOTH ways before it is believed, and the
   * second way is one environment variable:
   * `TMPDIR=/tmp/rigc-ci-sim bun run selftest` (create the directory first;
   * Bun's `os.tmpdir()` honours it). A green run under the default tmpdir is
   * half the measurement on this platform.
   */
  const runScriptInto = (
    script: DocScript,
    source: string,
    dir: string,
    rig: { from: string; to: string } | null,
  ): { status: number | null; product: string | null } => {
    const here = (text: string): string => text.split(docScratchPrefix()).join(`${dir}/`);
    const edited = rig === null ? here(source) : here(source).split(rig.from).join(rig.to);
    const ran = spawnSync(process.execPath, ['-e', edited], { cwd: root, encoding: 'utf8' });
    const at = here(script.writes[0] ?? '');
    return { status: ran.status, product: at !== '' && existsSync(at) ? readFileSync(at, 'utf8') : null };
  };

  try {
    // --- the population: a script whose PRODUCT is a positional run ---------
    interface RenumberSubject {
      script: DocScript;
      /** The `--rig` its own command names, which is what its run indexes into. */
      rig: string;
      rigText: string;
      /** Where the compiler would look for that rig's art — `src/compile.ts`'s own rule. */
      images: string;
      runs: DocDeformRun[];
      product: string;
      meshes: Map<string, string[]>;
    }
    const subjects: RenumberSubject[] = [];
    for (const script of verified) {
      const rigAt = script.argv.indexOf('--rig');
      const rig = rigAt >= 0 ? (script.argv[rigAt + 1] ?? null) : null;
      if (rig === null || !existsSync(join(root, rig))) {
        told.push(
          `${script.where}: its command names ` +
            `${rig === null ? 'no `--rig`, so nothing says which vertex list its run indexes into' : `\`--rig ${rig}\`, which the repository does not carry`}`,
        );
        continue;
      }
      const dir = mkdtempSync(join(renumberRoot, 'base-'));
      const first = runScriptInto(script, script.source, dir, null);
      const runs = first.product === null ? null : deformRunsOf(first.product);
      if (first.status !== 0 || first.product === null || runs === null) {
        told.push(`${script.where}: it wrote no product this window can read (exit ${String(first.status)})`);
        continue;
      }
      if (runs.length === 0) {
        told.push(`${script.where}: its product states no \`vertices\` key, so it writes no positional run to renumber under`);
        continue;
      }
      const copied = script.reads.find((path) => {
        const at = join(root, path);
        return existsSync(at) && (deformRunsOf(readFileSync(at, 'utf8')) ?? []).length > 0;
      });
      if (copied !== undefined) {
        told.push(
          `${script.where}: it reads \`${copied}\`, which states a \`vertices\` key itself, so a run it writes may ` +
            'be a copy rather than something it computed and this window cannot tell the two apart',
        );
        continue;
      }
      if (first.product.includes(docScratchPrefix())) {
        told.push(`${script.where}: its product names \`${docScratchPrefix()}\`, which the plant below cannot carry through a redirect`);
        continue;
      }
      const rigText = readFileSync(join(root, rig), 'utf8');
      const parsed = asJson(rigText);
      const meshes = new Map<string, string[]>();
      const unresolved: string[] = [];
      for (const run of runs) {
        const at = meshPathOf(parsed, run);
        if (at === null) unresolved.push(run.where);
        else meshes.set(run.where, at);
      }
      if (unresolved.length > 0) {
        told.push(
          `${script.where}: \`${rig}\` states no single authored mesh for ${unresolved.join(', ')}, so there is no ` +
            'vertex list to un-permute its offsets against',
        );
        continue;
      }
      const declared = asObject(parsed)?.images;
      subjects.push({
        script,
        rig,
        rigText,
        images: resolve(dirname(join(root, rig)), typeof declared === 'string' ? declared : '.'),
        runs,
        product: first.product,
        meshes,
      });
    }
    subjectCount = subjects.length;

    // --- the construction, re-asked of the compiler's own rule --------------
    const identityOf = (count: number): number[] => [...Array(count).keys()];
    for (const subject of subjects) {
      const rig = asJson(subject.rigText);
      const all = meshesOfRig(rig);
      if (familyNames.length === 0 && all.length > 0) {
        try {
          familyNames = [...renumberingsOf(all[0].att).keys()];
        } catch (err) {
          construction.push(`${subject.script.where}: \`${subject.rig}\` states a mesh this window cannot read an outline off — ${(err as Error).message}`);
        }
      }
      // 🔒 The two clauses, each planted against itself. A map that lifts an
      // interior vertex into the hull block and a map that swaps two
      // neighbours on the walk must BOTH be refused, on every authored mesh of
      // every subject — which is what says the family above is legal because
      // of the rule rather than in spite of it.
      for (const { at, att } of all) {
        const count = (asNumbers(att.vertices) ?? []).length / 2;
        let walk: number[] = [];
        let hull = 0;
        try {
          const outline = traceOutline(count, asNumbers(att.triangles) ?? []);
          walk = outline.walk;
          hull = outline.hull;
        } catch (err) {
          construction.push(`${subject.script.where}: \`${at.join('/')}\` has no outline to derive a renumbering from — ${(err as Error).message}`);
          continue;
        }
        const interior = [...Array(count).keys()].filter((one) => !walk.includes(one));
        for (const [what, illegal] of [
          [
            'an interior vertex lifted into the hull block',
            ((): number[] => {
              const out = identityOf(count);
              if (interior.length === 0) return out;
              out[walk[0]] = interior[0];
              out[interior[0]] = walk[0];
              return out;
            })(),
          ],
          [
            'two neighbours swapped on the outline walk',
            ((): number[] => {
              const out = identityOf(count);
              if (hull < 3) return out;
              out[walk[0]] = walk[1];
              out[walk[1]] = walk[0];
              return out;
            })(),
          ],
        ] as ReadonlyArray<readonly [string, number[]]>) {
          if (illegal.every((to, from) => to === from)) {
            construction.push(`${subject.script.where}: \`${at.join('/')}\` admits no map with ${what}, so that clause is untested on it`);
            continue;
          }
          const copy = asObject(asJson(JSON.stringify(att)));
          if (copy === null) continue;
          renumberMesh(copy, illegal);
          try {
            const again = traceOutline(count, asNumbers(copy.triangles) ?? []);
            checkHullOrder(again, count);
            construction.push(
              `${subject.script.where}: \`${at.join('/')}\` with ${what} is ACCEPTED by \`checkHullOrder\`, so the ` +
                'family below is no longer the set the compiler leaves open and this window is permuting by habit',
            );
          } catch (err) {
            refused.push(`${what} → ${(err as Error).message.split('.')[0]}`);
          }
        }
      }
    }

    // --- every renumbering: run it, build it, and compare the products ------
    interface RenumberRound {
      subject: RenumberSubject;
      name: string;
      maps: Map<string, number[]>;
      moved: number;
      product: DocDeformRun[] | null;
    }
    const rounds: RenumberRound[] = [];
    for (const subject of subjects) {
      for (const name of familyNames) {
        const rig = asJson(subject.rigText);
        const maps = new Map<string, number[]>();
        let moved = 0;
        for (const { at, att } of meshesOfRig(rig)) {
          let map: number[] | undefined;
          try {
            map = renumberingsOf(att).get(name);
          } catch (err) {
            construction.push(`${subject.script.where}: ${name} of \`${at.join('/')}\` could not be built — ${(err as Error).message}`);
            continue;
          }
          if (map === undefined) continue;
          maps.set(at.join('/'), map);
          renumberMesh(att, map);
          moved += map.filter((to, from) => to !== from).length;
          permutedMeshes++;
          try {
            const count = (asNumbers(att.vertices) ?? []).length / 2;
            checkHullOrder(traceOutline(count, asNumbers(att.triangles) ?? []), count);
          } catch (err) {
            construction.push(
              `${subject.script.where}: ${name} of \`${at.join('/')}\` is not a renumbering the compiler accepts — ` +
                `${(err as Error).message}. The rule this window derives the family from has moved`,
            );
          }
        }
        if (moved === 0) {
          construction.push(
            `${subject.script.where}: ${name} moved no vertex of \`${subject.rig}\`, so the comparison under it ` +
              'would hold whatever the script did',
          );
        }
        const dir = mkdtempSync(join(renumberRoot, 'perm-'));
        const rigPath = join(dir, 'rig.json');
        writeFileSync(rigPath, JSON.stringify(rig, null, 2));
        const ran = runScriptInto(subject.script, subject.script.source, dir, { from: subject.rig, to: rigPath });
        // ⚠️ Redirect first, splice second — see `runScriptInto`. Swapping
        // the rig in before the redirect fed `<dir>/rig.json` back through a
        // rewrite of `/tmp/` and doubled it wherever `os.tmpdir()` is `/tmp`.
        const argv = subject.script.argv
          .map((token) => token.split(docScratchPrefix()).join(`${dir}/`))
          .map((token, at) => (subject.script.argv[at] === subject.rig ? rigPath : token));
        const built = spawnSync(process.execPath, ['cli.ts', ...argv, '--images', subject.images], {
          cwd: root,
          encoding: 'utf8',
        });
        const out = (subject.script.out ?? '').split(docScratchPrefix()).join(`${dir}/`);
        const wrote = out !== '' && existsSync(out);
        if (built.status !== 0 || !wrote) {
          construction.push(
            `${subject.script.where}: \`${subject.rig}\` with ${name} exited ${String(built.status)} and ` +
              `${wrote ? 'wrote' : 'wrote nothing'} through the command its page states, so this renumbering is not ` +
              `one the whole compiler accepts${built.stderr.trim() === '' ? '' : ` — ${built.stderr.trim().split('\n')[0]}`}`,
          );
        }
        const product = ran.product === null ? null : deformRunsOf(ran.product);
        rounds.push({ subject, name, maps, moved, product });
        if (ran.status !== 0) {
          invariance.push(`${subject.script.where}: under ${name} the script itself exited ${String(ran.status)} rather than running to the end`);
        }
      }
    }

    /**
     * What one round disagrees with its own unpermuted product about. `mapOf`
     * is the un-permutation; handing it the identity is what the third plant
     * below does, and it must not come back empty.
     */
    const judgeRound = (round: RenumberRound, mapOf: (run: DocDeformRun) => readonly number[] | null): string[] => {
      const seen = compareProducts(round.subject.runs, round.product, mapOf);
      const rows: string[] = [];
      if (seen.missing > 0) {
        rows.push(
          `${round.subject.script.where}: under ${round.name} its product states ${seen.missing} fewer \`vertices\` ` +
            'key(s) than the same script wrote on the tree as it stands',
        );
      }
      if (seen.differ > 0) {
        rows.push(
          `${round.subject.script.where}: under ${round.name} ${seen.differ} of ${seen.total} offset(s) ` +
            `${MOVED_OFFSET_ROW}, worst ${seen.worst.toFixed(4)} — so it wrote the same numbers at the same ` +
            'POSITIONS in a ' +
            'list whose positions moved, which is a script assuming its vertex list rather than reading it',
        );
      }
      return rows;
    };
    const unpermute = (round: RenumberRound) => (run: DocDeformRun): readonly number[] | null =>
      round.maps.get((round.subject.meshes.get(run.where) ?? []).join('/')) ?? null;

    for (const round of rounds) {
      invariance.push(...judgeRound(round, unpermute(round)));
      const moved = compareProducts(round.subject.runs, round.product, (run) => {
        const map = unpermute(round)(run);
        return map === null ? null : identityOf(map.length);
      });
      if (moved.differ === 0) {
        invariance.push(
          `${round.subject.script.where}: under ${round.name} the product it wrote is the same at every position as ` +
            'the one it wrote unpermuted, so nothing was measured and the clause above holds vacuously',
        );
      }
      measured.push(
        `${round.subject.script.where} \`(${round.subject.script.label ?? ''})\` under ${round.name}: ` +
          `${judgeRound(round, unpermute(round)).length === 0 ? '0' : 'some'} of ` +
          `${compareProducts(round.subject.runs, round.product, unpermute(round)).total} offset(s) differ after ` +
          `un-permuting, with ${round.moved} index/indices moved and the run itself ${moved.differ} of ${moved.total} ` +
          'different at its own positions',
      );
    }

    // --- the plants ---------------------------------------------------------
    //
    // ⭐ The first is the defect itself, generalised rather than transcribed:
    // a script that writes its run at fixed positions whatever the rig says.
    // It is built out of the subject's OWN product, so nothing broken is
    // written into this file and the plant cannot go stale against the script
    // it plants on. §9.2's script as it shipped 2026-09-04 is one instance of
    // it — measured on that exact source, 16 to 46 of 50 offsets differ.
    for (const subject of subjects) {
      const mine = rounds.filter((round) => round.subject === subject);
      for (const round of mine) {
        const dir = mkdtempSync(join(renumberRoot, 'plant-'));
        const rig = asJson(subject.rigText);
        for (const { at: where, att } of meshesOfRig(rig)) {
          const map = round.maps.get(where.join('/'));
          if (map !== undefined) renumberMesh(att, map);
        }
        const rigPath = join(dir, 'rig.json');
        writeFileSync(rigPath, JSON.stringify(rig, null, 2));
        // The page's OWN literal, redirected once inside `runScriptInto` —
        // the same order rule. Pre-redirecting it here is what doubled the
        // path under a `/tmp` tmpdir, and the product it carries is refused
        // above if it names the prefix itself.
        const positional =
          `await Bun.write(${JSON.stringify(subject.script.writes[0] ?? '')}, ${JSON.stringify(subject.product)});`;
        plantsRun++;
        const ran = runScriptInto(subject.script, positional, dir, { from: subject.rig, to: rigPath });
        const planted: RenumberRound = { ...round, product: ran.product === null ? null : deformRunsOf(ran.product) };
        // 🔒 The row it has to raise is named, not merely counted. The first
        // version of this clause took ANY new fault, and the one it got was
        // `missing` — the plant's product was being looked for where it had
        // not been written — so the offsets clause it exists for never ran and
        // the case printed green over it.
        const raised = raisedBy(judgeRound(planted, unpermute(planted)), { was: invariance });
        if (!raised.some((one) => one.includes(MOVED_OFFSET_ROW))) {
          plantMisses.push(
            `${subject.script.where}: a product written at fixed positions under ${round.name} — not faulted as ` +
              `a moved offset (${raised.length === 0 ? 'nothing was raised at all' : raised.join('; ')})`,
          );
        }
      }
      // The identity renumbering: the non-vacuity row above has to fire on it,
      // or a family that quietly stopped permuting anything would read green.
      const first = mine[0];
      if (first !== undefined) {
        const idle: RenumberRound = {
          ...first,
          name: 'the identity renumbering',
          maps: new Map([...first.maps].map(([where, map]) => [where, identityOf(map.length)])),
          moved: 0,
          product: subject.runs,
        };
        plantsRun++;
        const still = compareProducts(subject.runs, idle.product, (run) => {
          const map = unpermute(idle)(run);
          return map === null ? null : identityOf(map.length);
        });
        if (still.differ !== 0) {
          plantMisses.push(`${subject.script.where}: a renumbering that permutes nothing — not caught by the non-vacuity row`);
        }
        // And the un-permutation itself: compare a real round at raw positions
        // and it has to go red, or the comparison is not doing the work its
        // figure claims.
        plantsRun++;
        if (
          raisedBy(
            judgeRound(first, (run) => {
              const map = unpermute(first)(run);
              return map === null ? null : identityOf(map.length);
            }),
            { was: invariance },
          ).length === 0
        ) {
          plantMisses.push(`${subject.script.where}: the comparison run without un-permuting — not faulted`);
        }
      }
    }
  } finally {
    rmSync(renumberRoot, { recursive: true, force: true });
  }

  const constructionProbes = [
    ...construction,
    ...floorProbes(
      [
        [subjectCount, 1, `${subjectCount} stated script(s) write a \`vertices\` run this window can renumber under`],
        [familyNames.length, 4, `${familyNames.length} renumbering(s) came out of \`checkHullOrder\`'s two clauses`],
        [permutedMeshes, 4, `${permutedMeshes} authored mesh/meshes were renumbered across them`],
        [refused.length, 2, `${refused.length} illegal map(s) were refused by the compiler's own rule`],
      ],
      'so one step of this construction came back thinner than it has ever been, and the two cases below would be ' +
        'measuring a renumbering nothing derived',
    ),
  ];
  say(
    'DS04_THE_RENUMBERINGS_A_STATED_SCRIPTS_PRODUCT_IS_MEASURED_UNDER_ARE_THE_ONES_THE_COMPILER_ACCEPTS',
    constructionProbes.length === 0,
    probeDetail(
      constructionProbes.length === 0,
      constructionProbes,
      `${subjectCount} of the ${verified.length} verified script(s) write a \`vertices\` run — ` +
        `${told.length} do not and say why: ${told.join('; ')}. Each is renumbered ${familyNames.length} way(s) ` +
        `{${familyNames.join('; ')}}, ${permutedMeshes} authored mesh/meshes in all, every one re-asked of ` +
        '`checkHullOrder` and rebuilt green through the command its own page states; and the two clauses that rule ' +
        `states are planted against themselves — ${[...new Set(refused)].join(' | ')}`,
    ),
    'issue #479 refused to gate this on the sentence §9.2 states it in, because a subject picked out of one ' +
      'comment is a hand-kept list wearing a derivation. So the subject is the PRODUCT — a script that writes a ' +
      '`vertices` run — and the population is one today without being chosen: a second page that writes one joins ' +
      'with no edit here, and the floor goes red if this one stops. The renumbering is derived the same way: ' +
      "`checkHullOrder` says the outline comes first and traces its walk in order, and says NOTHING about the " +
      'interior, so the accepted set is the dihedral maps of that walk times any permutation of the interior. ' +
      'Deriving it rather than hardcoding "rotate inside the perimeter block" is what makes it break by REFUSING ' +
      'the day a clause is added — and passing that one function is not the claim, because `meshEdges`, the ' +
      'deform runs, `A21` and `A39` read the same list, which is why each renumbering is built rather than argued',
  );

  say(
    'DS05_A_STATED_SCRIPT_THAT_WRITES_A_VERTICES_RUN_WRITES_THE_SAME_GEOMETRY_UNDER_EVERY_ONE_OF_THEM',
    invariance.length === 0 && measured.length > 0,
    probeDetail(
      invariance.length === 0 && measured.length > 0,
      [
        ...invariance,
        ...(measured.length > 0 ? [] : ['not one renumbering was measured, so this line would be a pass over nothing at all']),
      ],
      `${measured.length} measurement(s) — ${measured.join('; ')}`,
    ),
    'this is the half `DS02` cannot reach: a verdict claim is falsifiable only where the page\'s verdict differs ' +
      'from the build the script would produce doing nothing, so a script that goes QUIET is caught above and one ' +
      'that stays GREEN while doing something else is not. A run is positional by format — that is `fromVertex`\'s ' +
      'whole job — and a GENERATOR of one has no reason to be, so the property under test is that renumbering the ' +
      'rig moves the product with it. ⚠️ The second figure on each line is the load-bearing one: it says the run ' +
      'DID move at its own positions, so 0 of N after un-permuting is a measurement rather than a tautology',
  );

  say(
    'DS06_A_SCRIPT_THAT_WRITES_ITS_RUN_AT_FIXED_POSITIONS_IS_FAULTED_BY_THE_RENUMBERING',
    plantMisses.length === 0 && plantsRun >= 6,
    probeDetail(
      plantMisses.length === 0 && plantsRun >= 6,
      [
        ...plantMisses,
        ...floorProbes(
          [[plantsRun, 6, `${plantsRun} plant(s) were applied over ${subjectCount} subject(s)`]],
          'so a plant stopped being APPLIED rather than stopped being caught',
        ),
      ],
      `${plantsRun} plant(s) over ${subjectCount} subject(s) — a product written at fixed positions whatever the rig ` +
        `says faulted under each of the ${familyNames.length} renumbering(s); a renumbering that permutes nothing is ` +
        'caught by the non-vacuity row rather than passing; and the comparison run WITHOUT its un-permutation ' +
        'faults, which is what says the un-permutation is doing the work its figure claims',
    ),
    'a permutation check that faults on everything is the "test only refusals" failure this repository already has ' +
      'a judgement about, so the two sides are stated together: the repaired script reports 0 of N under every ' +
      'legal renumbering and the positional one does not. The plant is built out of the subject\'s OWN product ' +
      'rather than transcribed from the script that shipped 2026-09-04, because a broken script written into this ' +
      'file goes stale against the page the day the page is edited, and what the defect IS — the same numbers at ' +
      'the same positions whatever the rig says — is exactly what a product replayed verbatim is',
  );

  return bad;
}

// ---------------------------------------------------------------------------
// the transcripts `docs/` and `README.md` quote, held to the commands those
// pages state (issue #468)
// ---------------------------------------------------------------------------
//
// ⭐ **Why this suite exists, and why it is not `GT01`–`GT06` with a wider
// glob.** The gallery gate holds a `gallery/*/README.md` block to a command that
// README states, and #429 drew its boundary at `gallery/` deliberately. Issue
// #468 priced widening it, ruled **no gate**, and was **reopened the same day**
// because the ruling was wrong in a way worth keeping: the report's
// recommendation said no stale block sat in the reachable set, while the
// report's own per-block table classified two that did — `docs/FACE.md`'s
// `DEFORM … key 1 t=0.620000` (**"does not reproduce"**, and reachable) and
// `docs/LADDER.md`'s `bench 3` (called unreachable while being described as
// reproducing for 38 of its 57 lines, which is not unreachable, it is failing).
// Both were then found by hand and repaired by hand (#473, #480). Removing that
// loop is the whole of what this suite is for.
//
// 🚨 **The root defect was a classification that put "not reachable" and
// "currently failing" in one bucket**, so nothing here shares a bucket: a block
// is **verified**, **declared**, **a HOLE**, or **unreachable with its reason
// printed**, and those four are counted and named separately.
//
// **How the population is derived, and it is never a list.**
//
//  1. The universe is `git ls-files` filtered to markdown, minus `gallery/`,
//     which `GT01`–`GT06` already hold. The repository's own answer to what is
//     in the tree, so nothing is left out by a judgement made here.
//  2. A **plain** fenced block (no info string) is output — the same split
//     `galleryBlocks` already makes, where `json` and `bash` are source.
//  3. It is anchored the two ways the gallery anchors one, through the same
//     functions: a gutter tag in the vocabulary the runs print
//     (`transcriptBlockTag`), or a **record head** those runs print
//     (`transcriptHeadAnchored`) — an interior node of the report's own tree.
//     And a third the gallery has no use for: a **section rule**
//     (`TRANSCRIPT_SECTION_RULE`), a printed structure that carries no data, so
//     neither of the first two can see it.
//     And a fourth, for the same reason: a **report header**, the bare
//     `rigc <verb>` line `pose`, `render`, `diff`, `check`, `vote`, `preview`
//     and `chainfit` open on (`docsQuoteHeaderField`, issue #887). Because a
//     header names a verb and not a run, a block it found is COMPARED only
//     where a run also prints the line under it.
//  4. A plain fence that no rule anchors and that opens the way only rigc's
//     output opens — the `..` gutter, or a header with nothing under it — is
//     **counted** as unreachable with that shape as its reason, and never
//     compared (`docsQuoteTranscriptShape`). Before issue #887 it left the
//     population without a word, which is how five `pose` blocks went stale
//     at #719 with nothing on the summary line moving.
//
// ⚠️ **Rule 3 is here because a fence opening on one went stale for a week and
// a hand pass caught it** — `docs/LADDER.md`'s `bench 3` summary, whose last
// continuation row had been missing since the day it was written (#475, then
// repaired by hand in #480), sitting directly above the measure table this gate
// already watches. It was measured before it was written rather than argued
// for, and the measurement is the one #468's ruling asks for: **of the fences
// this rule newly reaches, how many can a run be laid against?** Most of that
// population is inside the seal and drops out there; of what is left, the
// summary above reproduces and the rest are illustrations whose first line no
// stated command prints, so they land in `unreachable` and can never reach a
// fault. `DQ01` prints both sides of that every run — the rule's own count at
// the gutter, the sealed set, and each unreachable block with its reason — so
// no figure of it is written here.
//
// 🔸 The risk the rule was checked for and does not run: a hand-drawn box
// diagram anchoring as if it were output. The tree has one, in `docs/MOTION.md`,
// and its fence opens on the pipeline line above the box rather than on the
// rule, so nothing reaches it. Were that to change it would land in
// `unreachable` beside the illustrations, which is the same containment rule 2's
// own false positive is held to.
//
// ⚠️ **Rule 2 needs record heads POOLED across examples, which the gallery
// suite refuses inside itself**, and that relaxation has a measured cost rather
// than a theoretical one: it anchors the `340 × 380 plate` table in
// `docs/FACE.md`, hand-drawn and not tool output in any sense, because `head` is
// a record head in another example's run. **The decision is that a false
// positive may land in `unreachable` and may never land in a fault**, which is
// exactly what it does
// here — it is printed with the reason "its first line is printed by no run".
// The relaxation is worth its false positive because rule 2 is what reaches
// `docs/LADDER.md`'s `bench 3` block, one of the two the reopening comment
// names, and `docs/AUTHORING.md`'s `deform` rollup.
//
// **The command pairing, derived and never told.** 🔒 A told-command table is
// the hand-maintained list this repository has a standing judgment about, and
// #468's first measurement rejected the whole gate partly on those grounds. So
// the pool for a document is **every rigc invocation that document states in a
// fence with an info string**, and everything that narrows it is a property of
// the invocation, printed by `DQ01` for each one that falls out:
//
//  1. it is elided (`…`) or carries a `<placeholder>` no command of its own
//     fence writes — a shape, not a command;
//  2. it reads an absolute path, which is outside this repository;
//  3. it reads a path the repository does not carry. Split in two, because the
//     two mean different things: a path **the tree deliberately does not
//     track** — the fetched corpus, a build product — is a **HOLE**, and any
//     other absent path is simply out of reach. That split is asked of git in a
//     throwaway repository holding this repository's own `.gitignore`, never of
//     the live tree: `git check-ignore examples/…` answers off today's disk, and
//     in the worktree this was written in it refused outright with *"beyond a
//     symbolic link"*.
//
// ⚠️ **`--out` is redirected into the round's own directory and nothing else
// is**, which is the same rule `DS01`'s runner obeys one surface over. Two
// consequences, both stated because both are limits: a block quoting the `--out`
// path back cannot verify (rigc prints it, and the runner's path is not the
// page's), and a later command in the **same fence** reading what `--out` wrote
// is given the runner's directory **only where the page wrote a
// `<placeholder>`**. Where the page names a real directory the runner may not
// write to, that later command is out of reach instead. ⭐ One override is a
// redirection; two is a different recipe — and the measured cost of the rule is
// exactly `docs/FACE.md`'s two `render` runs and one `preview`, **20.4 s of
// 22.2 s**, feeding no anchored block.
//
// ⭐ **A page with a `setup` fence is the exception, and it is one rule rather
// than a second recipe** (issue #887; the fences and the reasons are at
// `docsQuoteSetupTag`). Its setup runs first, in an overlay directory of the
// round's own, and its invocations run inside that overlay: `--out` writes
// there under the page's own name and a later command reads it back by that
// name, which is what a reader's shell does. Every other page is run exactly as
// above. The printed paths that come out of either are compared under one
// relaxation, a token-leading `…/` (`docsQuoteSameLine`).
//
// **The verdict, and the floor that makes a thin one honest.** #468's closing
// argument against this gate was that a small verified set *"buys the appearance
// of coverage"*. The answer is `GT01`'s own mechanism: a partial scan that
// **publishes its own coverage** is not what this family refuses to be, a
// **silent** one is. So `DQ01` states how many blocks were found, how many
// verified, how many are a HOLE and how many are unreachable **with the reason
// for each**, and a run that verifies nothing exits non-zero rather than
// printing green.
//
// 🚨 **What this gate does and what it deliberately still does not, and the
// line between them is one measurement.** `GT02` faults a gallery block that is
// anchored and does not reproduce. Since issue #482 that rule stands here too,
// **scoped to the blocks a stated run actually COMPARED**: a block whose first
// line a command of its own page prints, which then diverges and carries no
// declaration, is a fault by name.
//
// ⛔ It reaches no further, and the boundary is not a matter of taste. The
// anchored population splits in two, and `DQ01` prints which each block is:
//
//  1. **compared** — a stated run prints the block's first line, so a window of
//     that run was laid against it line for line and a divergence is a finding
//     about the BLOCK. Four blocks were in this class with nothing said about
//     them; all four now carry a declaration and their reasons are below.
//  2. **never compared** — the first line is the page's own, not the tool's,
//     and no window was ever laid against it. "It does not reproduce" is then a
//     statement about the pool rather than about the block, and there are a
//     dozen of them: mesh rosters over rigs this repository does not carry, a
//     depth study's `grid` line, a faded-slot `DEFORM` record illustrating a
//     spec nothing in the tree holds. A rule reaching those would open by
//     demanding a dozen document repairs, which is the outcome issue #468 spent
//     a whole card refusing.
//
// 🔒 One value in `scanDocsQuotes` decides both which sentence a block's report
// gets and whether its divergence faults, so the scope cannot drift into class
// 2 without the printed reason changing with it — and `DQ03` plants both sides:
// a declaration pulled off a compared block must go red, a first line sent
// adrift must stay quiet.
//
// ⭐ **What the four declarations say, because they were measured one at a time
// and two of them are not what this comment used to claim.** All four are
// abridgements or assemblies of REAL runs, and none is an invented example:
//
// ⛔ Each is named by what it holds and by no line number. `DQ01` prints the
// declared set with each block's own coordinate and the reason its page shows a
// reader, so a coordinate written down here would be a second copy of a figure
// the run already takes — and `CUR12` refuses the whole form.
//
//  - `docs/AUTHORING.md`'s `group members` legend and the `group "features"`
//    record, byte-for-byte out of `explain portrait`, which prints two
//    `bone "faceshift"` records between them. ⚠️ This comment said the record
//    was *invented over a rig that is not `portrait`* and it is not:
//    `gallery/portrait/motion.json` declares `features` with exactly those six
//    members and the tool prints the record verbatim.
//  - the same page's `deform` legend and `head/head` keys 0 and 1, then the
//    `WORST` rollup, with the run's other six `DEFORM` records cut from
//    between: `head/head` keys 2 and 3 and all four of `hair_bang/hair_bang`.
//  - the same page's one-line-per-verdict-kind block, assembled. The `PASS` and
//    the `PROF` are byte-exact from the `build` the page states at §3.4; the
//    `SKIP` is a real message cut at an ellipsis and printed only under
//    `--profile rig-play`, which this page states no command for; the `FAIL`
//    is invented — no green build prints one, and its mesh, vertex and sum are
//    the doctrine's own example values.
//  - `docs/FACE.md`'s `MEMBER` record — the same one the first of these quotes,
//    with the five derivation lines the run prints between its head and its rows
//    cut away.
//
// 🔒 **The sealed subtree.** Three landed run records under `bench/runs/` carry
// anchored output and [#181](https://github.com/rig-c/core/issues/181)
// forbids repairing any measure or reading in them; one of the three is
// anchored by the two rules above. A gate whose population contains a record
// nobody may touch is publishing a figure it cannot act on, so the subtree is
// excluded **derivably**: one rendered marker line in the header of the
// directory's own README, in the family this tree already has three of
// (`DECLARATION_LEAD`, `RECIPE_LEAD`, `DATED_RECORD_MARKER`). Its floors come
// with the family — the reason is required, the excluded set is printed so it
// cannot grow quietly, and **a marker that excludes no block at all is a
// fault**, which is what stops it becoming a way to switch the gate off.
//
// ⚠️ **Cost, measured rather than guessed.** The vocabulary has to come from
// runs, and this suite builds its own gallery pool through `transcriptRunsFor`
// rather than reaching into `runGalleryTranscriptSuite`'s locals: 20 runs,
// ~1.6 s. The documents' own pool is 15 more, ~1.1 s, of which `bench 3` and
// the build that feeds it are 90 ms — cheap, and worth it, because that block
// is one of the two this card was reopened for. Every plant below is free: the
// rescans re-read the runs already taken. **35 subprocesses, ~2.7 s.**
// ⚠️ **The two overlay pages cost more than the rest together** (issue #887),
// measured one page at a time on the same tree at a load average near 6: run
// the old way, `docs/MOTION.md` was 4 runs in 0.5 s and `docs/INGEST.md` 11 in
// 2.3 s; in their overlays they are 9 runs in 20.9 s and 16 in 13.8 s. The
// difference is what the overlay reaches — five `pose` searches, and the
// renders and the `check` whose output the pages quote — and it is the price of
// those blocks being compared at all.
// ⚠️ Deriving the vocabulary from the documents' OWN runs instead was built and
// **rejected on measurement**: it costs the same (3.1 s), it drags `FAIL` into
// the green vocabulary — the tag the refusal half derives by SUBTRACTION from
// it — and, decisively, it is corpus-dependent, so a fresh clone would silently
// anchor 119 heads instead of 205 and the population would shrink rather than
// report a hole.

/**
 * The anchor RULES — the ways a fence in a document is recognised as output the
 * tool prints. The declaration marker is deliberately not among them: it names
 * a block the tool CANNOT print, and a declared block leaves this scan through
 * its own branch before either the verified list or the HOLE list, so it can
 * never be part of what a run reaches.
 *
 * ⭐ The floors below are one per entry here rather than one on their sum, and
 * that is the whole reason this is a list rather than three literals at the
 * floor table: a fourth rule cannot be added to the union without appearing in
 * the population those floors iterate, because the union is derived from this.
 *
 * ⚠️ A function rather than a `const`, for the reason `sealedSubtreeLead` below
 * is one: this region is appended AFTER `main()` is called, so a module-level
 * binding here is in its temporal dead zone when the suite runs.
 */
function docsAnchorRules(): readonly ('tag' | 'head' | 'rule' | 'header')[] {
  return ['tag', 'head', 'rule', 'header'];
}

/**
 * The fourth anchor rule's shape: a **report header**, the bare `rigc <verb>`
 * line seven commands open their report on (issue #887).
 *
 * ⭐ Shape-only, for the reason `TRANSCRIPT_SECTION_RULE` is: the header carries
 * no data — it names the verb and nothing else — so it is the same string
 * however stale the block beneath it goes, which is the qualifier every anchor
 * here is held to. It is read off the first FIELD rather than the whole line so
 * the adrift plant, which keeps the field and rewrites the rest, leaves it
 * anchored, exactly as it leaves a tag or a head.
 *
 * ⚠️ **Why a shape and not a vocabulary**, since the brief this was built from
 * asked for the second: `pose`'s tags could only enter the vocabulary from a
 * gallery example stating a `pose` run, and none can state one honestly. The
 * vocabulary's runner synthesises `build` and `explain` from the example's name
 * and runs nothing a README writes; `pose` places every PNG in `--images`, and
 * the gallery ships no directory holding one part; and measured over the
 * nearest candidate — `gallery/squash`'s sixteen parts against its own frame 0
 * — it took 32 s of CPU and placed **0 of 16** under the default window. The
 * header needs none of that, reaches `render`, `diff`, `check` and `vote`
 * blocks the vocabulary never could, and brings no tag with it, so `FAIL` —
 * the tag the refusal half derives by subtraction — cannot ride in on it.
 */
function docsQuoteHeaderField(): RegExp {
  return /^rigc [a-z][a-z-]*$/;
}

/** A block opening on a report header with at least one line of that report hanging under it. */
function docsQuoteHeaderAnchored(body: string[]): boolean {
  if (!docsQuoteHeaderField().test(transcriptAnchorField(body[0]))) return false;
  let next = 1;
  while (next < body.length && body[next].trim() === '') next++;
  return next < body.length && transcriptIndent(body[next]) > transcriptIndent(body[0]);
}

/**
 * Which shape only rigc's output opens on, for a block no anchor rule reached —
 * or null. The whole of issue #887's first defect is what this returns.
 *
 * 🚨 **A transcript that loses every anchor used to leave the population
 * without a word**, and five `pose` blocks went stale at #719 that way: none
 * was among the unreachable, and their page was not among the pages. So a block
 * that opens on the gutter's own `..` mark, or on a bare report header with
 * nothing under it, is COUNTED — as unreachable, with this shape as its reason
 * — and never compared, because a `..` line carries data and anchoring on one
 * is the loose anchor issue #422 forbids. What it buys is not a gate on the
 * block; it is that the summary can no longer hide one.
 */
function docsQuoteTranscriptShape(body: string[]): string | null {
  const field = transcriptAnchorField(body[0]);
  if (field === '..') return 'the `..` gutter mark every rigc report prints';
  if (docsQuoteHeaderField().test(field)) return `\`${field}\`, a report header, with no line of its report under it`;
  return null;
}

/** How a block was found: by one of the anchor rules, by its declaration alone, or by its shape alone. */
type DocsQuoteAnchor = ReturnType<typeof docsAnchorRules>[number] | 'declared' | 'shape';

/** One block of a document this gate can see, with how it was found. */
interface DocsQuoteBlock {
  file: string;
  /** 1-based line of the opening fence. */
  line: number;
  body: string[];
  anchor: DocsQuoteAnchor;
  declared: string | null;
}

/** One rigc invocation a document states, and whether this runner can run it. */
interface DocsQuoteCommand {
  file: string;
  line: number;
  /** As the page spells it, whitespace collapsed — what a failure detail has to name. */
  text: string;
  argv: string[];
  /** Index of `--out` in `argv`, or -1. Its value is the one thing the runner supplies. */
  outAt: number;
  /**
   * Which shape of unrunnable this is, or `null` for one that runs.
   *
   * ⭐ A field rather than a reading of the sentence, because `DQ01` reports the
   * out-of-reach set by KIND: 116 of them are stated in this tree, so spelling
   * each one out would bury the per-block reasons the floor is actually for
   * under a page of prose nobody reads. The kinds are the derivation's own
   * branches, so a branch that stops being taken shows up as a zero.
   */
  kind: 'elided' | 'placeholder' | 'quoted' | 'absolute' | 'absent' | 'untracked' | null;
  /** Why it is not run, in one sentence, or null. */
  reason: string | null;
  /** True when the reason is a path the tree deliberately does not track — a HOLE, not an absence. */
  hole: boolean;
}

/** What one pass over the tree found. */
interface DocsQuoteScan {
  found: number;
  byTag: number;
  byHead: number;
  byRule: number;
  byHeader: number;
  byDeclared: number;
  /** Counted by the shape it opens on, with no anchor rule behind it — never compared (issue #887). */
  byShape: number;
  verified: Array<{ where: string; command: string; lines: number; anchor: DocsQuoteBlock['anchor'] }>;
  /**
   * Declared unreproducible, and whether this run actually COMPARED it.
   *
   * ⭐ The flag is what makes the declaration-removal plant two-sided rather
   * than a formality: a declaration on a compared block is load-bearing, and
   * taking it off has to go red; a declaration on a block nothing here can
   * reach carries no gate, and taking it off has to change nothing. The pair
   * only means something if the two are told apart, and they are told apart by
   * the same value that decides the fault.
   */
  declared: Array<{ where: string; reason: string; compared: boolean }>;
  /**
   * Anchored, and the material its page's commands read is not on this disk.
   *
   * ⭐ Carries its anchor for the same reason `verified` does: what a run
   * reaches is verified PLUS these, and the floor on that is stated per anchor
   * rule. A corpus that is not fetched moves a block from one list to the
   * other without changing which rule found it, which is what lets the floor
   * be the same on a fresh clone as it is in CI.
   */
  holes: Array<{ where: string; why: string; anchor: DocsQuoteAnchor }>;
  /**
   * Anchored, not verified, not declared — and `compared` says which of the two
   * very different things that is. `false` is an illustration: its first line is
   * its own, nothing was measured against it, and the fault rule may never reach
   * it. `true` is a block a run DID print the first line of, which diverged and
   * declared nothing — a fault, and it is listed here as well because the fault
   * says the tree is wrong while this list says what the run measured.
   */
  unreachable: Array<{ where: string; why: string; compared: boolean }>;
  /** Blocks a sealed marker took out of the population, by the marker that took them. */
  excluded: Array<{ where: string; sealedBy: string }>;
  faults: string[];
}

/**
 * The lead that makes a line a sealed-subtree marker — what a reader reads, and
 * the whole of what this scanner keys on. The reason is the rest of the line.
 *
 * ⚠️ A function rather than a `const`, for the reason `docScratchPrefix` above
 * is one: this region is appended AFTER `main()` is called, so a module-level
 * binding here is in its temporal dead zone when the suite runs.
 */
function sealedSubtreeLead(): string {
  return '**A sealed subtree:**';
}

/** The lead, and whatever an author wrote after it — which has to be a reason. */
function sealedSubtreeLine(): RegExp {
  return new RegExp(`^${literalPattern(sealedSubtreeLead())}[ \\t]*(.*?)[ \\t]*$`);
}

/**
 * Which directories a marker seals, and every way a marker can be wrong.
 *
 * A marker seals the directory of the file it sits in, and everything below it,
 * so a run that lands tomorrow needs no action. It has to sit in the file's
 * header — `CURRENCY_HEADER_LINES`, the same window the dated-record marker
 * uses — because a declaration buried at the bottom of a long page is one the
 * reader it is written for will not meet.
 */
function sealedSubtrees(docs: Map<string, string>): {
  prefixes: Array<{ where: string; prefix: string; reason: string }>;
  faults: string[];
} {
  const prefixes: Array<{ where: string; prefix: string; reason: string }> = [];
  const faults: string[] = [];
  for (const [path, text] of docs) {
    const lines = text.split('\n');
    lines.forEach((line, i) => {
      const found = sealedSubtreeLine().exec(line);
      if (found === null) return;
      const where = `${path}:${i + 1}`;
      if (i >= CURRENCY_HEADER_LINES) {
        faults.push(
          `${where}  opens with \`${sealedSubtreeLead()}\` below the header — a marker seals a subtree and a ` +
            `reader has to meet it, so it belongs in the first ${CURRENCY_HEADER_LINES} lines or nowhere`,
        );
        return;
      }
      if (found[1].length < TRANSCRIPT_REASON_MIN) {
        faults.push(
          `${where}  seals a subtree and gives no reason for it ("${found[1]}"): the ruling that seals a ` +
            'subtree is the whole of what makes the exclusion checkable, so it has to be named',
        );
        return;
      }
      const dir = dirname(path);
      prefixes.push({ where, prefix: dir === '.' ? '' : `${dir}/`, reason: found[1] });
    });
  }
  return { prefixes, faults };
}

/**
 * The statements of one fenced block — a shell line at a time, a `\` at the end
 * of a line holding the next one open.
 *
 * Comments come off before anything else, which is what stops a `# (a) …` label
 * being read as part of the command below it.
 */
function docsQuoteStatements(body: readonly string[], first: number): Array<{ line: number; text: string }> {
  const out: Array<{ line: number; text: string }> = [];
  let held: string[] = [];
  let at = first;
  for (let i = 0; i < body.length; i++) {
    const line = body[i];
    if (held.length === 0 && /^\s*#/.test(line)) continue;
    if (held.length === 0) at = first + i;
    held.push(line.replace(/\s+#.*$/, ''));
    if (/\\\s*$/.test(line)) continue;
    const text = held.join(' ').replace(/\\\s+/g, ' ').replace(/\s+/g, ' ').trim();
    if (text !== '') out.push({ line: at, text });
    held = [];
  }
  if (held.length > 0) {
    const text = held.join(' ').replace(/\\\s+/g, ' ').replace(/\s+/g, ' ').trim();
    if (text !== '') out.push({ line: at, text });
  }
  return out;
}

/** How a page spells an invocation of this tool: from a checkout, or installed. */
function docsQuoteInvocation(): RegExp {
  return /^(?:bun cli\.ts|rigc)\s+([a-z][a-z-]*)\b/;
}

/**
 * Is this argument something the tool would have to open?
 *
 * A slash or an extension, because both forms appear: `gallery/squash/rig.json`
 * and `candidate.json`. Getting this wrong is not silent in the safe direction
 * — a path-shaped word this misses is one the runner passes through to a
 * command it then runs, which is how `--json report.json` would have written
 * into the checkout.
 */
function docsQuoteLooksLikePath(word: string): boolean {
  // A number list is not a path, whatever it ends in: `--viewport
  // 20.4013,31.8317,119.1974,153.8671` ends in `.8671` and was reported as a
  // path the repository does not carry until this line was here.
  if (/^[\d.,+-]+$/.test(word)) return false;
  return /\//.test(word) || /\.[A-Za-z0-9]{1,6}$/.test(word);
}

/**
 * Every rigc invocation a document states, with the reason each unrunnable one
 * is unrunnable.
 *
 * ⛔ Read out of fences that carry an info string ONLY. A plain fence is output,
 * which is the split the population itself is made on — and it is not a nicety:
 * `docs/INGEST.md` opens four transcripts with the bare line `rigc render`,
 * `rigc diff`, `rigc check`, `rigc pose`, which is the tool's own report header.
 * Reading those as invocations ran four commands that could only print usage.
 */
function docsQuoteCommands(file: string, text: string, root: string): DocsQuoteCommand[] {
  const out: DocsQuoteCommand[] = [];
  for (const block of galleryBlocks(text)) {
    if (block.info === '') continue;
    // A `<placeholder>` is resolvable only against an `--out` in its OWN fence:
    // one fence is one runnable unit, as `DS01`'s runner has it.
    const produced = new Set<string>();
    for (const statement of docsQuoteStatements(block.lines, block.line + 1)) {
      if (!docsQuoteInvocation().test(statement.text)) continue;
      const argv = statement.text.replace(docsQuoteInvocation(), '$1').split(' ');
      const outAt = argv.indexOf('--out');
      const command: DocsQuoteCommand = {
        file,
        line: statement.line,
        text: statement.text,
        argv,
        outAt,
        kind: null,
        reason: null,
        hole: false,
      };
      const falls = (kind: DocsQuoteCommand['kind'], reason: string): void => {
        command.kind = kind;
        command.reason = reason;
      };
      if (/[…]|\.\.\./.test(statement.text)) falls('elided', 'the command it states is elided');
      else {
        for (let i = 1; i < argv.length; i++) {
          // One layer of quotes around a word with no space in it is taken off
          // (issue #887): `'ref-big/light@4fps/f0002.png'` is one word however a
          // shell reads it, and it is the only quoting two of the tree's `pose`
          // commands carry. Anything a shell would read differently still falls.
          argv[i] = docsQuoteUnquoted(argv[i]);
          const word = argv[i];
          if (outAt >= 0 && i === outAt + 1) continue; // the one value this runner supplies
          if (produced.has(word)) continue;
          if (/[<>]/.test(word)) {
            falls('placeholder', `it reads \`${word}\`, a placeholder no \`--out\` of its own fence writes`);
            break;
          }
          if (/['"]/.test(word)) {
            falls('quoted', `it reads \`${word}\`, which carries shell quoting this runner does not parse`);
            break;
          }
          if (word.startsWith('-')) continue;
          if (!docsQuoteLooksLikePath(word)) continue;
          if (word.startsWith('/')) {
            falls('absolute', `it reads \`${word}\`, an absolute path outside this repository`);
            break;
          }
          if (!existsSync(join(root, word))) {
            // `absent` or `untracked` is settled below, in one call, once every
            // absent path is known: the two mean different things and only one
            // of them is a HOLE. The reason holds the bare path until then.
            falls('absent', word);
            break;
          }
        }
      }
      if (command.reason === null && outAt >= 0 && /^<[^<>]+>$/.test(argv[outAt + 1] ?? '')) {
        produced.add(argv[outAt + 1]);
      }
      out.push(command);
    }
  }
  return out;
}

/**
 * Which of these absent paths the repository deliberately does not track.
 *
 * 🔒 Asked of git, in a throwaway repository holding this repository's own
 * `.gitignore`, and never of the live tree. `git check-ignore` reads today's
 * disk: it answers IGNORED for `examples` only while that name happens to be a
 * real directory, and in the worktree this was written in — where it was a
 * symlink to one — it refused the whole query with *"beyond a symbolic link"*.
 * The same command in a repository with nothing in it but the ignore file
 * answers the question that was actually asked, which is about the RULES.
 */
function docsQuoteIgnored(paths: string[], root: string): { ignored: Set<string>; fault: string | null } {
  if (paths.length === 0) return { ignored: new Set<string>(), fault: null };
  const dir = mkdtempSync(join(harnessTemp(), 'rigc-docsquote-ignore-'));
  try {
    writeFileSync(join(dir, '.gitignore'), readFileSync(join(root, '.gitignore'), 'utf8'));
    const init = spawnSync('git', ['init', '-q', dir], { encoding: 'utf8' });
    if (init.error !== undefined || init.status !== 0) {
      return { ignored: new Set<string>(), fault: 'git could not make the throwaway repository the ignore rules are asked in' };
    }
    const asked = spawnSync('git', ['-C', dir, 'check-ignore', '--stdin'], { input: paths.join('\n'), encoding: 'utf8' });
    // Exit 1 means "none of them matched", which is an answer and not a failure.
    if (spawnFailed(asked) || (asked.status !== 0 && asked.status !== 1)) {
      return {
        ignored: new Set<string>(),
        fault: `git could not say which of ${paths.length} absent path(s) this repository deliberately does not track`,
      };
    }
    return { ignored: new Set(asked.stdout.split('\n').filter((line) => line !== '')), fault: null };
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

/**
 * What a git working copy looks like right now, as one string.
 *
 * 🚨 This suite runs commands **a document wrote for a reader who has a
 * checkout**, and the reader's checkout is where those commands are meant to
 * write. `--out` is the one value redirected, and the only thing standing
 * between the rest and this tree is that every other path-shaped argument has
 * to already exist: a `--json report.json` pointed at a file that DOES exist
 * would be run and would overwrite it. That is an argument, and an argument is
 * not a measurement — so the round is bracketed by this and a difference is a
 * fault. `DQ03` shows it firing, on a throwaway repository rather than on this
 * one, because a probe that proved it by dirtying the tree would be the defect.
 */
function docsQuoteWorkingCopy(dir: string): string {
  const seen = spawnSync('git', ['-C', dir, 'status', '--porcelain', '--untracked-files=all'], {
    encoding: 'utf8',
    maxBuffer: 64 * 1024 * 1024,
  });
  if (seen.error !== undefined || seen.status !== 0) return `git could not read the working copy at ${dir}`;
  return seen.stdout.split('\n').sort().join('\n');
}

/**
 * Run one document's pool, in the order the page states it.
 *
 * Memoised on the resolved argv with `--out`'s value blanked, so two pages
 * stating the same command are one subprocess — and two that differ by one flag
 * are not, which is why the key is the argv and not the page's own wording.
 */
function docsQuotePool(
  commands: readonly DocsQuoteCommand[],
  roundDir: string,
  memo: Map<string, { run: TranscriptRun; out: string | null }>,
): TranscriptRun[] {
  const produced = new Map<string, string>();
  const runs: TranscriptRun[] = [];
  for (const command of commands) {
    if (command.reason !== null) continue;
    const fresh = join(roundDir, `out-${memo.size}-${runs.length}`);
    const key = command.argv
      .map((word, i) => (command.outAt >= 0 && i === command.outAt + 1 ? '<out>' : (produced.get(word) ?? word)))
      .join(' ');
    const cached = memo.get(key);
    // 🔒 **A memoised run hands back the directory IT wrote, not a fresh name.**
    // The placeholder a later command reads has to name artifacts that exist, and
    // on a cache hit nothing writes to `fresh` — so registering `fresh` against
    // the placeholder pointed every reader of it at an empty path and the run
    // that reads it failed for a reason no page states. Found by issue #678: two
    // fences in `docs/AUTHORING.md` state the same `gallery/squash` build with
    // different `--out`s, and the second one's `render`/`check` were never run.
    const out = cached?.out ?? fresh;
    const argv = command.argv.map((word, i) =>
      command.outAt >= 0 && i === command.outAt + 1 ? out : (produced.get(word) ?? word),
    );
    if (command.outAt >= 0 && /^<[^<>]+>$/.test(command.argv[command.outAt + 1] ?? '')) {
      produced.set(command.argv[command.outAt + 1], out);
    }
    if (cached !== undefined) {
      runs.push(cached.run);
      continue;
    }
    const result = runCli(argv);
    const run: TranscriptRun = {
      command: command.text,
      lines: `${result.stdout}${result.stderr}`.split('\n'),
      status: result.status,
    };
    memo.set(key, { run, out: command.outAt >= 0 ? out : null });
    runs.push(run);
  }
  return runs;
}

// --- elided paths (issue #887) ---------------------------------------------
//
// 🔒 **`…/` at the start of a token stands for an absolute prefix, and for
// nothing else.** `pose`, `render` and `build` print the absolute paths they
// resolved, and a page cannot state an absolute path that is true on a reader's
// disk, so it writes `…/semaphore/poseA.png`. The rule that lets that compare is
// exact in every other respect: the tool's token has to be an ABSOLUTE path, the
// elision takes whole leading components off it and nothing else, and every
// character after `…/` has to be the tool's own. A `…/` inside a token is not an
// elision and compares as the literal it is, so it never matches.
//
// ⚠️ **Rejected: a `pose` flag printing paths relative to `--images`.** It
// would move the question rather than answer it: `render` and `build` print the
// same absolute paths and the pages elide them the same way, so every one of
// those verbs would need the flag, and each flag is a second output format the
// tool has to keep — for the benefit of this suite, which is the wrong direction
// for a gate to pull a product. The prefix rule costs one comparison and changes
// no output.

/** Does a page's line say what the tool printed, with a leading `…/` standing for an absolute prefix? */
function docsQuoteSameLine(page: string, tool: string): boolean {
  if (page === tool) return true;
  if (!page.includes('…/')) return false;
  return docsQuoteElision(page).test(tool);
}

/** The page's line as a pattern: literal throughout, except that a token-leading `…/` is `/` plus any whole components. */
function docsQuoteElision(page: string): RegExp {
  const pieces = page.split(/(?<=^|\s)…\//);
  return new RegExp(`^${pieces.map(literalPattern).join('\\/(?:\\S*\\/)?')}$`);
}

/**
 * `bestTranscriptWindow`, with the one relaxation above: a line matches when it
 * is the tool's line or the tool's line under a token-leading elision.
 *
 * ⚡ The fast path is kept wherever the first line carries no elision, which is
 * every block but the few that open on a path — the first line is then looked
 * up exactly, as before.
 */
function docsQuoteWindow(
  body: string[],
  runs: TranscriptRun[],
): { command: string; window: string[]; shared: number } | null {
  let best: { command: string; window: string[]; shared: number } | null = null;
  const head = body[0].trimStart();
  for (const run of runs) {
    const starts = head.includes('…/')
      ? run.lines
          .map((line, i) => (docsQuoteSameLine(head, line.trimStart().replace(/\s+$/, '')) ? i : -1))
          .filter((i) => i >= 0)
      : anchorsIn(run, head);
    for (const i of starts) {
      if (i + body.length > run.lines.length) continue;
      const window = transcriptBody(run.lines.slice(i, i + body.length));
      if (window.length !== body.length) continue;
      let shared = 0;
      while (shared < body.length && docsQuoteSameLine(body[shared], window[shared])) shared++;
      if (best === null || shared > best.shared) best = { command: run.command, window, shared };
      if (shared === body.length) return best;
    }
  }
  return best;
}

// --- setup fences (issue #887) ---------------------------------------------
//
// ⭐ **A fence whose info string carries the word `setup` is executed, before
// the page's invocations, in a directory of the round's own — and it is
// executed by THIS RUNNER, never by a shell.** Four statements are understood,
// the four the tree's pages actually state: `mkdir -p`, `cd`, `cp` and
// `bun -e '…'`, split on `&&`. Anything else is refused by name, and so is any
// path that would leave the directory: absolute, home-relative, carrying a
// `..`, or asking for an expansion the shell would have done.
//
// 🔒 **Why this and not "pages must state their inputs as files the tree
// ships".** The suite's bar is that a green run cannot depend on the reader's
// shell, and a runner that interprets four statements itself meets it exactly —
// there is no shell in the loop to depend on, and `bun` is the repository's own
// runtime. The alternative would move `docs/MOTION.md` §6's plates and frames
// into the tree and make the section runnable only from a checkout, when it is
// written so that a reader with nothing but the installed package can run it end
// to end; that is a regression in the product to make the gate's life easier,
// and it would rewrite a section another card owns.
//
// **What a page with a setup fence gets.** Its invocations run in that
// directory, from wherever the last `cd` left it, and the directory is an
// OVERLAY on the checkout: a path the setup or an earlier `--out` wrote is read
// from the overlay, any other path falls through to the checkout at the same
// relative place, and `--out` writes into the overlay under the name the page
// spells. So a later command reading what an earlier one wrote is reached with
// no placeholder — which is the reader's own model of a shell session, and the
// reason the redirection rule above cannot serve here.
//
// ⚠️ **What this cannot promise, stated because it is a limit and not a
// feature.** `bun -e` runs JavaScript, and a script can compute a path this
// runner never sees. What is refused is every string LITERAL in the script that
// escapes — an absolute path or a `..` — which is how the tree's scripts name
// what they write; a path built out of pieces is not read. The working-copy
// bracket around the round is what measures the checkout itself.

/** The word in a fence's info string that makes it setup this runner executes. */
function docsQuoteSetupTag(): string {
  return 'setup';
}

function docsQuoteIsSetup(info: string): boolean {
  return info.split(/\s+/).includes(docsQuoteSetupTag());
}

/** Why a path in a setup statement or an overlay `--out` would leave the round's directory, or null. */
function docsQuoteEscape(word: string): string | null {
  if (word.startsWith('/')) return 'it is an absolute path';
  if (word.startsWith('~')) return 'it is relative to a home directory';
  if (/[$`*?{}]/.test(word)) return 'it asks for an expansion a shell would perform and this runner does not';
  if (word.split('/').includes('..')) return 'it climbs out with `..`';
  return null;
}

/** One statement's parts, split on `&&` outside single quotes. */
function docsQuoteSetupParts(text: string): string[] {
  const parts: string[] = [];
  let held = '';
  let quoted = false;
  for (let i = 0; i < text.length; i++) {
    if (text[i] === "'") quoted = !quoted;
    if (!quoted && text.startsWith('&&', i)) {
      parts.push(held.trim());
      held = '';
      i++;
      continue;
    }
    held += text[i];
  }
  if (held.trim() !== '') parts.push(held.trim());
  return parts.filter((part) => part !== '');
}

/** A shell word with one layer of single quotes taken off, when the whole word is quoted and holds no space. */
function docsQuoteUnquoted(word: string): string {
  return /^'[^'"\s]*'$/.test(word) ? word.slice(1, -1) : word;
}

/** Where a path the page spells lives: the overlay if something wrote it there, else the checkout at the same place. */
function docsQuoteOverlayPath(word: string, cwd: string, sandbox: string, root: string): string | null {
  if (existsSync(join(cwd, word))) return join(cwd, word);
  const tree = join(root, relative(sandbox, cwd), word);
  return existsSync(tree) ? tree : null;
}

/**
 * Execute a page's setup fences, in page order, inside `sandbox`.
 *
 * Stops at the first statement it refuses or that fails, because every
 * statement after it may depend on it and a half-built directory is a
 * directory nothing on the page describes.
 */
function docsQuoteRunSetup(
  file: string,
  text: string,
  sandbox: string,
  root: string,
  ignored: ReadonlySet<string>,
): { cwd: string; ran: string[]; refusals: string[]; hole: string | null } {
  let cwd = sandbox;
  const ran: string[] = [];
  const refusals: string[] = [];
  for (const block of galleryBlocks(text)) {
    if (!docsQuoteIsSetup(block.info)) continue;
    for (const statement of docStatements(block.lines, block.line + 1)) {
      if (statement.comment) continue;
      for (const part of docsQuoteSetupParts(statement.text)) {
        const where = `${file}:${statement.line}`;
        const flat = part.replace(/\\\n\s*/g, ' ').replace(/\s+/g, ' ').trim();
        // A rigc invocation in a setup fence is the page's, and the pool runs it.
        if (docsQuoteInvocation().test(flat)) continue;
        const refuse = (why: string): { cwd: string; ran: string[]; refusals: string[]; hole: string | null } => {
          refusals.push(`${where}  the setup statement \`${flat.slice(0, 72)}\` is refused: ${why}`);
          return { cwd, ran, refusals, hole: null };
        };
        if (/^bun -e '/.test(part)) {
          const source = part.slice(part.indexOf("'") + 1, part.lastIndexOf("'"));
          // Only the two escapes a literal can spell. The rest of what
          // `docsQuoteEscape` refuses is shell syntax, and a script's literals
          // are data — base64, JSON — that carry braces and slashes of their own.
          for (const found of source.matchAll(/(["'`])((?:\\.|(?!\1)[^\\])*)\1/g)) {
            const literal = found[2];
            const why = /^[/~]/.test(literal)
              ? 'a script literal that starts at the root or a home directory writes outside the round'
              : literal.split('/').includes('..')
                ? 'a script literal carrying `..` climbs out of the round'
                : null;
            if (why !== null) return refuse(`its script names \`${literal.slice(0, 48)}\`, and ${why}`);
          }
          const run = spawnSync(process.execPath, ['-e', source], { cwd, encoding: 'utf8', timeout: 60_000 });
          if (run.error !== undefined || run.status !== 0) {
            return refuse(`its script exited ${String(run.status)}: ${`${run.stderr ?? ''}`.trim().split('\n')[0] ?? ''}`);
          }
          ran.push(`${where} bun -e`);
          continue;
        }
        const words = flat.split(' ').map(docsQuoteUnquoted);
        const [verb, ...args] = words;
        if (verb !== 'mkdir' && verb !== 'cd' && verb !== 'cp') {
          return refuse(
            `\`${verb}\` is not one of the four statements a setup fence may state — \`mkdir -p\`, \`cd\`, \`cp\` and ` +
              "`bun -e '…'` — and this runner hands nothing to a shell",
          );
        }
        const operands = verb === 'mkdir' ? args.filter((word) => word !== '-p') : args;
        for (const word of operands) {
          const why = word.startsWith('-') ? `\`${word}\` is a flag this runner does not implement` : docsQuoteEscape(word);
          if (why !== null) return refuse(`\`${word}\`: ${why}`);
        }
        if (verb === 'mkdir') {
          if (operands.length === 0) return refuse('it names no directory');
          for (const word of operands) mkdirSync(join(cwd, word), { recursive: true });
        } else if (verb === 'cd') {
          if (operands.length !== 1) return refuse(`it names ${operands.length} directories where \`cd\` takes one`);
          const next = join(cwd, operands[0]);
          if (!existsSync(next) || !statSync(next).isDirectory()) return refuse(`\`${operands[0]}\` is not a directory it made`);
          cwd = next;
        } else {
          if (operands.length < 2) return refuse('it names no source and destination');
          const target = operands[operands.length - 1];
          for (const source of operands.slice(0, -1)) {
            const from = docsQuoteOverlayPath(source, cwd, sandbox, root);
            // The fetched corpus absent is a HOLE, as it is for an invocation:
            // the setup stops, and nothing is refused, because nothing is wrong
            // with the page.
            if (from === null && ignored.has(source)) return { cwd, ran, refusals, hole: source };
            if (from === null || !statSync(from).isFile()) {
              return refuse(`\`${source}\` is not a file here or in the checkout`);
            }
            const into = join(cwd, target);
            const dest =
              target.endsWith('/') || (existsSync(into) && statSync(into).isDirectory()) ? join(into, basename(source)) : into;
            copyFileSync(from, dest);
          }
        }
        ran.push(`${where} ${verb}`);
      }
    }
  }
  return { cwd, ran, refusals, hole: null };
}

/** Every path a page's setup fences name outside a script, so git can be asked which of them it does not track. */
function docsQuoteSetupWords(text: string): string[] {
  const words: string[] = [];
  for (const block of galleryBlocks(text)) {
    if (!docsQuoteIsSetup(block.info)) continue;
    for (const statement of docStatements(block.lines, block.line + 1)) {
      if (statement.comment) continue;
      for (const part of docsQuoteSetupParts(statement.text)) {
        if (/^bun -e '/.test(part)) continue;
        for (const word of part.replace(/\\\n\s*/g, ' ').split(/\s+/).map(docsQuoteUnquoted)) {
          if (!word.startsWith('-') && docsQuoteEscape(word) === null && docsQuoteLooksLikePath(word)) words.push(word);
        }
      }
    }
  }
  return words;
}

/**
 * Run the pool of a page that has setup fences, inside its overlay.
 *
 * Every command the static pass did not refuse for its SHAPE is re-derived
 * here, after the setup and every earlier command have run, because what exists
 * is only known then: a path is resolved in the overlay first and the checkout
 * second, and a command reading a path in neither falls out with the static
 * reason for that path — a HOLE where git says the tree does not track it.
 */
function docsQuoteOverlayPool(
  file: string,
  text: string,
  commands: readonly DocsQuoteCommand[],
  roundDir: string,
  root: string,
  memo: Map<string, { run: TranscriptRun; out: string | null }>,
  ignored: ReadonlySet<string>,
): { runs: TranscriptRun[]; refusals: string[]; ran: string[] } {
  const sandbox = mkdtempSync(join(roundDir, 'overlay-'));
  const setup = docsQuoteRunSetup(file, text, sandbox, root, ignored);
  const runs: TranscriptRun[] = [];
  const refusals = [...setup.refusals];
  const produced = new Map<string, string>();
  for (const command of commands) {
    if (command.kind !== null && command.kind !== 'absent' && command.kind !== 'untracked') continue;
    const argv = [...command.argv];
    let why: { kind: DocsQuoteCommand['kind']; reason: string; hole: boolean } | null = null;
    for (let i = 1; i < argv.length; i++) {
      const word = argv[i];
      if (command.outAt >= 0 && i === command.outAt + 1) {
        if (/^<[^<>]+>$/.test(word)) {
          const fresh = mkdtempSync(join(sandbox, 'out-'));
          produced.set(word, fresh);
          argv[i] = fresh;
          continue;
        }
        const escapes = docsQuoteEscape(word);
        if (escapes !== null) {
          why = { kind: 'absolute', reason: `its \`--out ${word}\` would write outside the page's directory: ${escapes}`, hole: false };
          break;
        }
        continue;
      }
      const mapped = produced.get(word);
      if (mapped !== undefined) {
        argv[i] = mapped;
        continue;
      }
      if (word.startsWith('-') || !docsQuoteLooksLikePath(word)) continue;
      const at = docsQuoteOverlayPath(word, setup.cwd, sandbox, root);
      if (at === null) {
        // A setup that stopped on the fetched corpus takes every path it would
        // have written with it, and those are HOLEs for the same reason.
        const hole = ignored.has(word) || setup.hole !== null;
        why = {
          kind: hole ? 'untracked' : 'absent',
          reason: hole
            ? ignored.has(word)
              ? `it reads \`${word}\`, which this repository generates or fetches rather than tracking`
              : `it reads \`${word}\`, which its page's setup would have written from \`${setup.hole ?? ''}\` — ` +
                'which this repository generates or fetches rather than tracking'
            : `it reads \`${word}\`, which neither its page's setup nor the repository carries`,
          hole,
        };
        break;
      }
      // What the setup or an earlier command wrote is read where it was
      // written, under the name the page gave it; the checkout is read whole.
      if (!at.startsWith(`${sandbox}/`)) argv[i] = at;
    }
    if (why !== null) {
      command.kind = why.kind;
      command.reason = why.reason;
      command.hole = why.hole;
      continue;
    }
    command.kind = null;
    command.reason = null;
    command.hole = false;
    const result = spawnSync(process.execPath, [join(root, 'cli.ts'), ...argv], { cwd: setup.cwd, encoding: 'utf8' });
    const run: TranscriptRun = {
      command: command.text,
      lines: `${result.stdout}${result.stderr}`.split('\n'),
      status: result.status,
    };
    memo.set(`${file} (overlay) ${argv.join(' ')}`, { run, out: null });
    runs.push(run);
  }
  return { runs, refusals, ran: setup.ran };
}

/**
 * Every block, and its verdict — the whole of what `DQ01` reports and `DQ02`
 * and `DQ03` read.
 *
 * Takes the pool rather than making one, so the plants below rescan seventy
 * times and add not one subprocess.
 */
function scanDocsQuotes(
  docs: Map<string, string>,
  vocabulary: Set<string>,
  heads: Set<string>,
  commandsBy: Map<string, DocsQuoteCommand[]>,
  runsBy: Map<string, TranscriptRun[]>,
): DocsQuoteScan {
  const scan: DocsQuoteScan = {
    found: 0,
    byTag: 0,
    byHead: 0,
    byRule: 0,
    byHeader: 0,
    byDeclared: 0,
    byShape: 0,
    verified: [],
    declared: [],
    holes: [],
    unreachable: [],
    excluded: [],
    faults: [],
  };
  const sealed = sealedSubtrees(docs);
  scan.faults.push(...sealed.faults);
  for (const [file, text] of docs) {
    if (file.startsWith('gallery/')) continue;
    const commands = commandsBy.get(file) ?? [];
    const runs = runsBy.get(file) ?? [];
    // A HOLE is a document whose pool is empty BECAUSE the tree does not carry
    // what its commands read — never a document whose commands simply failed.
    const hole = runs.length === 0 && commands.some((command) => command.hole);
    for (const block of galleryBlocks(text)) {
      if (block.info !== '') continue;
      const body = transcriptBody(block.lines);
      if (body.length === 0) continue;
      const tag = TRANSCRIPT_BLOCK_TAG.exec(body[0]);
      const byTag = tag !== null && vocabulary.has(tag[1]);
      const byHead = !byTag && transcriptHeadAnchored(body, heads);
      const byRule = !byTag && !byHead && TRANSCRIPT_SECTION_RULE.test(body[0]);
      const byHeader = !byTag && !byHead && !byRule && docsQuoteHeaderAnchored(body);
      const shape =
        !byTag && !byHead && !byRule && !byHeader && block.declared === null ? docsQuoteTranscriptShape(body) : null;
      if (!byTag && !byHead && !byRule && !byHeader && block.declared === null && shape === null) continue;
      const at = `${file}:${block.line}`;
      const seal = sealed.prefixes.find((entry) => entry.prefix !== '' && file.startsWith(entry.prefix));
      if (seal !== undefined) {
        scan.excluded.push({ where: at, sealedBy: seal.where });
        continue;
      }
      scan.found++;
      // 🔒 Counted and never compared (issue #887): no rule anchored it, so
      // laying a run against it would be anchoring on its content. What it may
      // not do any more is leave the population in silence.
      if (shape !== null) {
        scan.byShape++;
        scan.unreachable.push({
          where: at,
          why:
            `it opens on ${shape}, and no anchor rule reaches it — no tag, record head, section rule or report ` +
            'header this gate knows names its first line, so no run was laid against it',
          compared: false,
        });
        continue;
      }
      const anchor: DocsQuoteBlock['anchor'] = byTag
        ? 'tag'
        : byHead
          ? 'head'
          : byRule
            ? 'rule'
            : byHeader
              ? 'header'
              : 'declared';
      if (byTag) scan.byTag++;
      else if (byHead) scan.byHead++;
      else if (byRule) scan.byRule++;
      else if (byHeader) scan.byHeader++;
      else scan.byDeclared++;

      const best = docsQuoteWindow(body, runs);
      const reproduces = best !== null && best.shared === body.length;
      // 🔒 **The one value that decides both the printed reason and the fault**,
      // because the fault rule below may reach exactly the blocks this run
      // COMPARED and no others. A block whose first line no run prints was never
      // compared — nothing was measured against it, so "it does not reproduce"
      // is not a finding about the block, it is a statement about the pool — and
      // faulting those would demand a repair of twelve illustrations on the
      // gate's first act, which is the outcome issue #468 spent a whole card
      // refusing. ⭐ Deriving the reason FROM this object rather than beside it
      // is what stops the scope drifting: there is no second expression to
      // disagree with, so a block the report calls "printed by no command" can
      // never be one the fault list names.
      // 🔒 **Sliced from where the two lines FIRST differ, for the reason the
      // `nearestPrintedLine` branch below already carries and this one did
      // not.** Two prefixes of a fixed width name the divergence only while it
      // falls inside them: every `bench` section-mean line in `docs/LADDER.md`
      // is past a hundred characters, so a one-digit drift in it printed the
      // SAME sixty-four characters twice and left a reader with a line number
      // and nothing else (issue #538). Measured on a planted `animations=0.936`
      // → `0.937` before this was written.
      // 🔒 **A report header says which verb printed the block and nothing
      // about which RUN** (issue #887), so for a block the header rule found,
      // "a stated command prints its first line" means the line under the
      // header. Measured before this clause existed: `docs/INGEST.md`'s
      // `rigc diff` block — whose own command reads a directory no stated
      // command writes — was compared against the page's OTHER `diff`,
      // diverged on the candidate path at line 2, and faulted as a stale quote
      // it is not.
      const comparedFrom = anchor === 'header' ? 2 : 1;
      const divergence =
        !reproduces && runs.length > 0 && best !== null && best.shared >= comparedFrom
          ? ((): { command: string; at: number; of: number; agree: number; page: string; tool: string } => {
              const page = body[best.shared].trim();
              const tool = best.window[best.shared].trim();
              let agree = 0;
              while (agree < page.length && agree < tool.length && page[agree] === tool[agree]) agree++;
              return {
                command: best.command,
                at: best.shared + 1,
                of: body.length,
                agree,
                page: page.slice(agree, agree + 64),
                tool: tool.slice(agree, agree + 64),
              };
            })()
          : null;
      if (block.declared !== null) {
        if (block.declared.length < TRANSCRIPT_REASON_MIN) {
          scan.faults.push(
            `${at}  declares itself a transcript no run reproduces and gives no reason for it ` +
              `("${block.declared}"): a marker is an as-of annotation, so it has to say as of what`,
          );
        } else if (reproduces) {
          scan.faults.push(
            `${at}  is declared unreproducible ("${block.declared}") and \`${best?.command ?? ''}\` prints it ` +
              'verbatim — a declaration is the escape for a block the tool cannot print, not a way to stop ' +
              'checking one it can',
          );
        } else {
          scan.declared.push({ where: at, reason: block.declared, compared: divergence !== null });
        }
        continue;
      }
      if (reproduces) {
        scan.verified.push({ where: at, command: best?.command ?? '', lines: body.length, anchor });
        continue;
      }
      if (hole) {
        scan.holes.push({
          where: at,
          anchor,
          why:
            `no command \`${file}\` states could run here — ` +
            commands
              .filter((command) => command.hole)
              .map((command) => `\`${command.text.slice(0, 60)}\`: ${command.reason ?? ''}`)
              .join('; '),
        });
        continue;
      }
      const near = runs.length === 0 ? null : nearestPrintedLine(body[0].trimStart(), runs);
      const why =
        divergence !== null
          ? `line ${divergence.at} of ${divergence.of} agrees for ${divergence.agree} character(s), and then ` +
            `the page reads "${divergence.page}" where \`${divergence.command.slice(0, 44)}\` prints ` +
            `"${divergence.tool}"`
          : runs.length === 0
            ? `no command \`${file}\` states can be run here, so nothing in this repository prints it`
            : `its first line is printed by no command this page states` +
              (near === null
                ? `: "${body[0].trim().slice(0, 96)}"`
                : (():
                    string => {
                    // 🔒 Where they FIRST differ, not the first 72 characters
                    // of each. The nearest line usually shares a long prefix
                    // — `MESH  head  authored 25 vertices …` against the same
                    // line with one figure moved — so two truncations print
                    // the same text and name nothing. The first `MESH` plant
                    // below produced exactly that before this branch existed.
                    const want = body[0].trim();
                    let shared = 0;
                    while (shared < want.length && shared < near.line.length && want[shared] === near.line[shared]) shared++;
                    return (
                      `; the closest \`${near.command.slice(0, 44)}\` prints agrees for ${shared} character(s), ` +
                      `and then the page reads "${want.slice(shared, shared + 60)}" where the tool prints ` +
                      `"${near.line.slice(shared, shared + 60)}"`
                    );
                  })());
      // 🔒 **`GT02`'s rule, and the whole of what scopes it is the line above.**
      // Anchored, compared and diverging, with no declaration ⇒ a fault. The
      // block still goes into `unreachable` beside it, because the fault says
      // the tree is wrong and the coverage line says what this run measured, and
      // those are two different reports of one fact rather than two facts.
      if (divergence !== null) {
        scan.faults.push(
          `${at}  ${why} — and no \`${DECLARATION_LEAD}\` line stands above the fence. A block whose first ` +
            'line a stated command DOES print was compared, so a divergence in it is either a stale quote to ' +
            're-take from the run or an abridgement to declare, and it may not be neither',
        );
      }
      scan.unreachable.push({ where: at, why, compared: divergence !== null });
    }
  }
  // 🔒 The seal's own floor, raised here rather than beside the call so a
  // rescan sees it: a marker that excludes nothing is a fault, not a no-op.
  // Without it the line would go on reading as an exclusion long after the
  // thing it excluded had moved, which is the shape every marker in this family
  // is floored against.
  for (const entry of sealed.prefixes) {
    if (entry.prefix === '') {
      scan.faults.push(
        `${entry.where}  seals the directory it sits in, and that is the repository root — a marker takes a ` +
          'SUBTREE out of this gate, never the whole tree',
      );
      continue;
    }
    if (scan.excluded.some((block) => block.sealedBy === entry.where)) continue;
    scan.faults.push(
      `${entry.where}  seals \`${entry.prefix}\` and no anchored block is in it, so the marker excludes nothing ` +
        'and would go on reading as an exclusion after the thing it excluded had gone',
    );
  }
  return scan;
}

/**
 * The floor on what a run REACHED — one row per anchor rule, never one on their
 * sum (issue #510).
 *
 * 🔒 **Why a bound and not a figure.** A block that stops reproducing while it
 * keeps its anchor faults in `DQ02` by name. What leaves silently is a block
 * whose own FIRST LINE drifts: it loses its anchor, nothing is laid against it,
 * and it falls out of this scan without a word. That departure is seen by a
 * floor or by nothing, and a floor written as a number is the one thing it
 * cannot be — the number would have to come off the run it bounds, which is the
 * check agreeing with itself, and a hand-kept one drifts under the tree the way
 * this comment's own predecessor did. So what is stated is a claim about the
 * population instead: **each anchor rule still reaches something.**
 *
 * ⭐ **`verified + hole` and never `verified` alone**, which is the clause that
 * makes a corpus-less machine honest rather than lenient. A missing corpus moves
 * a block between those two lists and changes neither its anchor nor this
 * count. ⚠️ Measured rather than assumed, because the two are NOT the same
 * population: on a run with the corpus every reachable block reproduces, and on
 * one without it the section-rule row reaches exactly one block and that block
 * is a HOLE — so the same rows over `verified` alone would report a rule
 * reaching nothing on a fresh clone, and the tightest floor here would be the
 * first to be lowered until it caught nothing.
 *
 * ⚠️ **What this narrows and what it still cannot see.** One floor on the sum
 * could be held by any block arriving anywhere; these are held only by a block
 * arriving under the SAME rule. That is narrower and it is not closed: a rule
 * reaching several blocks still hides one of them leaving. Closing it needs a
 * comparison against something that is not this run, which nothing in the tree
 * supplies — see the removal check in `.github/workflows/squash-text.yml`, which is that
 * comparison for a neighbouring population and lives outside the suite for
 * exactly the reason it cannot be built inside one.
 */
function docsQuoteReachFloors(scan: DocsQuoteScan): string[] {
  return floorProbes(
    docsAnchorRules().map((rule) => {
      const reproduced = scan.verified.filter((entry) => entry.anchor === rule).length;
      const holes = scan.holes.filter((entry) => entry.anchor === rule).length;
      return [
        reproduced + holes,
        1,
        `the ${rule} anchor reaches ${reproduced + holes} block(s) — ${reproduced} reproducing and ${holes} a HOLE`,
      ] as const;
    }),
    'so this rule found blocks and a run could be laid against none of them, which is the state a block leaving ' +
      'the scan silently arrives at',
  );
}

/** Splice an edited block body back into the document text it came from. */
function docsQuotePlant(text: string, block: GalleryBlock, edited: string[]): string {
  const raw = text.split('\n');
  return [...raw.slice(0, block.line), ...edited, ...raw.slice(block.line + block.lines.length)].join('\n');
}

/** The first `count` lines of a block that carry anything — what a comparison is keyed on. */
function docsQuoteKeyLines(lines: readonly string[], count: number): string {
  return lines
    .filter((line) => line.trim() !== '')
    .slice(0, count)
    .join('\n');
}


/**
 * Keep the block's ANCHOR and make its first line one no run prints.
 *
 * ⛔ The opposite requirement to the declaration-removal plant, and the reason
 * the fault rule can be said to be scoped rather than merely observed to be:
 * this leaves the block in the population, in the same anchor class, and takes
 * away the only thing that makes it comparable. Twelve blocks in `docs/` are in
 * exactly that state today — illustrations whose first line is theirs and not
 * the tool's — and if the rule reached them the gate's first act would be
 * demanding twelve document repairs, which is the outcome issue #468 refused.
 * So this plant has to leave the block UNREACHABLE and fault NOTHING.
 *
 * ⭐ Structural, no literal: the anchor is the first field, whatever it is, and
 * everything after it becomes a sentence rigc has no printer for. Both rules
 * read the first field only (`transcriptAnchorField`), and the head rule also
 * reads the indent of the line below, which this does not touch.
 */
function docsQuoteFirstLineAdrift(lines: readonly string[]): string[] | null {
  const first = lines.findIndex((line) => line.trim() !== '');
  if (first < 0) return null;
  const line = lines[first];
  const keep = transcriptIndent(line) + transcriptAnchorField(line).length;
  const next = [...lines];
  next[first] = `${line.slice(0, keep)}  a line this tool has no printer for`;
  return next;
}

function runDocsQuoteSuite(): { failures: number; holes: number } {
  console.log('\n── what `docs/` and `README.md` QUOTE the tool as printing (issue #468) ──');
  let bad = 0;
  const say = (name: string, ok: boolean, detail: string, why: string): void => {
    bad += reportCase(name, ok, detail, why);
  };

  const root = import.meta.dir;
  const listed = spawnSync('git', ['ls-files', '-z'], { cwd: root, encoding: 'buffer', maxBuffer: 256 * 1024 * 1024 });
  const treeFault =
    listed.error !== undefined || listed.status !== 0
      ? `git could not list the tracked files (${listed.error?.message ?? `exit ${String(listed.status)}: ${listed.stderr.toString('utf8').trim()}`})`
      : null;
  const docs = new Map<string, string>();
  if (treeFault === null) {
    for (const path of listed.stdout.toString('utf8').split('\u0000')) {
      if (path.endsWith('.md') && !path.startsWith('gallery/') && existsSync(join(root, path))) {
        docs.set(path, readFileSync(join(root, path), 'utf8'));
      }
    }
  }

  // Bracket everything that runs a subprocess: nothing this suite does may
  // reach the checkout, and that is measured rather than asserted.
  const copyBefore = docsQuoteWorkingCopy(root);

  // --- the vocabulary, from runs of the gallery's own stated commands -------
  const galleryRoot = join(root, 'gallery');
  const vocabulary = new Set<string>();
  const heads = new Set<string>();
  let galleryRuns = 0;
  let galleryExamples = 0;
  if (existsSync(galleryRoot)) {
    for (const example of readdirSync(galleryRoot).sort()) {
      const readmePath = join(galleryRoot, example, 'README.md');
      if (!existsSync(readmePath) || !existsSync(join(galleryRoot, example, 'rig.json'))) continue;
      const readme = readFileSync(readmePath, 'utf8');
      if (!new RegExp(`bun cli\\.ts build[^\\n]*--rig gallery/${example}/rig\\.json`).test(readme)) continue;
      galleryExamples++;
      const runs = transcriptRunsFor(example, readme, mkdtempSync(join(harnessTemp(), `rigc-docsquote-${example}-`)));
      galleryRuns += runs.length;
      for (const run of runs) {
        for (const line of run.lines) {
          const tag = TRANSCRIPT_GUTTER.exec(line);
          if (tag !== null) vocabulary.add(tag[1]);
        }
        for (const head of transcriptRecordHeads(run.lines)) heads.add(head);
      }
    }
  }

  // --- each document's own pool ---------------------------------------------
  const commandsBy = new Map<string, DocsQuoteCommand[]>();
  const absent = new Set<string>();
  // A page with a setup fence is run in an overlay (issue #887), where a path
  // absent from the checkout may be one its setup writes — so EVERY absent path
  // its commands name is asked about, not only the first, because the first
  // may turn out to exist once the setup has run.
  const overlaid = new Set([...docs].filter(([, text]) => galleryBlocks(text).some((block) => docsQuoteIsSetup(block.info))).map(([file]) => file));
  for (const [file, text] of docs) {
    const commands = docsQuoteCommands(file, text, root);
    for (const command of commands) if (command.kind === 'absent' && command.reason !== null) absent.add(command.reason);
    if (overlaid.has(file)) {
      for (const word of docsQuoteSetupWords(text)) if (!existsSync(join(root, word))) absent.add(word);
      for (const command of commands) {
        for (const word of command.argv.slice(1)) {
          if (word.startsWith('-') || /^[/~]|[<>'"…]/.test(word) || !docsQuoteLooksLikePath(word)) continue;
          if (!existsSync(join(root, word))) absent.add(word);
        }
      }
    }
    commandsBy.set(file, commands);
  }
  const asked = docsQuoteIgnored([...absent], root);
  for (const commands of commandsBy.values()) {
    for (const command of commands) {
      if (command.kind !== 'absent' || command.reason === null) continue;
      const path = command.reason;
      command.hole = asked.ignored.has(path);
      command.kind = command.hole ? 'untracked' : 'absent';
      command.reason = command.hole
        ? `it reads \`${path}\`, which this repository generates or fetches rather than tracking`
        : `it reads \`${path}\`, which the repository does not carry`;
    }
  }

  const roundDir = mkdtempSync(join(harnessTemp(), 'rigc-docsquote-round-'));
  const memo = new Map<string, { run: TranscriptRun; out: string | null }>();
  const runsBy = new Map<string, TranscriptRun[]>();
  const setupRefusals: string[] = [];
  const setupRan: string[] = [];
  for (const [file, commands] of commandsBy) {
    if (!overlaid.has(file)) {
      runsBy.set(file, docsQuotePool(commands, roundDir, memo));
      continue;
    }
    const pool = docsQuoteOverlayPool(file, docs.get(file) ?? '', commands, roundDir, root, memo, asked.ignored);
    runsBy.set(file, pool.runs);
    setupRefusals.push(...pool.refusals);
    setupRan.push(...pool.ran);
  }

  const copyAfter = docsQuoteWorkingCopy(root);

  const scan = scanDocsQuotes(docs, vocabulary, heads, commandsBy, runsBy);
  const stated = [...commandsBy.values()].reduce((n, commands) => n + commands.length, 0);
  const outOfReach = [...commandsBy.values()].flat().filter((command) => command.reason !== null);
  // By KIND rather than one sentence each: most of the invocations this tree
  // states fall out of it, and spelling them all out here would bury the
  // per-block reasons the floor exists for. A kind that stops being taken shows
  // up as a zero, which is the property a list of sentences would not have had
  // either. ⚠️ The count that stood in this sentence was wrong under both
  // readings it could have had — the run prints one figure with the corpus and
  // a larger one without — so the claim is kept and the number is the run's.
  const byKind = new Map<string, number>();
  for (const command of outOfReach) byKind.set(command.kind ?? '?', (byKind.get(command.kind ?? '?') ?? 0) + 1);
  // The ones that could have changed a verdict are named, and those are the
  // ones on a page that holds an anchored block.
  const pages = [...docs.keys()].filter((file) =>
    [...scan.verified, ...scan.declared, ...scan.holes, ...scan.unreachable].some((entry) => entry.where.startsWith(`${file}:`)),
  );
  const reachable = scan.verified.length + scan.holes.length;
  const sealed = sealedSubtrees(docs);

  // --- DQ01: the derivation floor, and the coverage this run publishes ------
  //
  // 🔒 `GT01`'s argument, and here it carries more than usual: this gate does
  // not fault a block that fails to reproduce, so a block leaving the verified
  // set is caught HERE or nowhere. Every step above can also come back empty —
  // a gallery that stops printing a tag, a page that stops stating its command,
  // a corpus that is not on disk — and each of those makes `DQ02` pass over
  // less while saying nothing. ⭐ The floors are one per step and never one on
  // their sum.
  //
  // ⚠️ **What a run REACHED is floored per anchor rule and never on their sum**
  // (issue #510), and the rows are in `docsQuoteReachFloors`. Each says the
  // same thing about a different rule — *this one still reaches a block* — and
  // that is a claim about the population rather than a figure off the run. The
  // rest of the table — `docs.size`, `heads.size` and their neighbours — are
  // smoke floors, there to catch a derivation returning nothing at all. Do not
  // read any of them as budgets.
  //
  // 🚨 **This clause used to be a number, and the number is how it failed.** It
  // read `reachable >= 6`, and its own comment said in so many words that the
  // floor was load-bearing and not a smoke floor — six blocks either way, one
  // departure taking it to five. The tree then grew past it in both directions
  // and nothing said so, because a bound cannot notice that its subject moved:
  // at the measurement that replaced this text the reach was nine with the
  // corpus and nine without, so a floor described as tight was carrying three
  // blocks of slack. ⛔ Raising it to nine would have bought one week of the
  // same thing. The bound has to be a claim the tree cannot outgrow.
  //
  // ⭐ **`verified + hole` and never `verified` alone**, which is what makes the
  // rows say the same thing on a fresh clone as in CI: a missing corpus moves a
  // block between those two lists and changes neither its anchor nor the count.
  // The two figures were taken with `examples/` present and with it deleted and
  // the per-rule reach is identical, so the clause that the sum is the same
  // either way survives its figures being removed. ⚠️ It still turns on
  // something thin: `docs/INGEST.md`'s pool survives a missing corpus because
  // ONE of its stated commands reads `bench/transcriptions/`, which is tracked
  // — so its unreachable blocks stay unreachable instead of becoming HOLEs.
  // Were that command to go they would flip, and under a sum the floor would
  // silently gain their slack on every corpus-less machine. Under a row per
  // rule they arrive in the rule that found them and the row says so.
  //
  // 🚨 **What a floor cannot do, stated because splitting it does not fix it.**
  // Issue #482 closed half of this: a block that stops reproducing while keeping
  // its anchor faults in `DQ02` by name. What is left is a block whose first
  // line drifts, and a floor sees that only where the rule it was found by has
  // nothing else to stand in for it. **If one block leaves a rule's set in the
  // same change that another enters it, the row holds and the run is green** —
  // narrower than the sum, which any arriving block anywhere could hold up, and
  // not closed. Closing it wants a comparison against a revision this run is not
  // allowed to see, which is a different instrument in a different place.
  //
  // ✅ **What the fault rule took away.** A block that stops reproducing while
  // keeping its anchor is now a fault in `DQ02`, by name, with the line it
  // diverged at — so the ordinary departure, a figure that moved under a quote
  // nobody re-took, no longer needs this clause at all.
  //
  // ⚠️ **What is left, and it is the sharper half.** A block whose OWN FIRST
  // LINE drifts loses its anchor: nothing is laid against it, the fault rule
  // correctly does not reach it, and it leaves the verified set silently — the
  // failure `GT01`'s header names, *an anchor on a leaf goes silent exactly when
  // it goes stale*. That departure shows up in these rows or nowhere, and `DQ04`
  // is what makes them a gate rather than a hope: it takes every reachable block
  // of a rule out of the tree in turn and reads the row that fires.
  //
  // ⛔ Raising the fault rule to reach an unanchored block is the other thing
  // that does not work: that is precisely the class-2 population the rule is
  // scoped away from, and it would fault a dozen illustrations to catch a
  // departure that has not yet happened.
  const derivation = [
    ...(treeFault === null ? [] : [treeFault]),
    ...(asked.fault === null ? [] : [asked.fault]),
    // A setup statement this runner refused, or one that failed, by name
    // (issue #887): the page's own directory could not be built, so what its
    // commands read is not what the page describes.
    ...setupRefusals,
    ...(copyBefore === copyAfter
      ? []
      : [
          'running the commands these pages state CHANGED the working copy, which a gate may never do — before ' +
            `the round git reported ${copyBefore.split('\n').length} line(s) and after it ${copyAfter.split('\n').length}: ` +
            copyAfter
              .split('\n')
              .filter((line) => !copyBefore.split('\n').includes(line))
              .join(', '),
        ]),
    ...scan.faults,
    // 🚨 Every floor is a PROBE and not a conjunct, and this repository has
    // already paid for that twice (`CUR09`, `TY12`): a floor in the verdict's
    // boolean with a detail that reads only the fault list makes the FAIL print
    // the sentence saying everything is fine. It happened here on the run this
    // was written, on the reach clause, which is the one the whole gate rests
    // on — the mutant said RED and the detail said clean.
    ...floorProbes(
      [
      [docs.size, 50, `${docs.size} tracked markdown file(s) outside \`gallery/\` were read`],
      [galleryExamples, 5, `${galleryExamples} gallery example(s) gave up their stated commands`],
      [galleryRuns, 14, `${galleryRuns} run(s) of those commands supplied the vocabulary`],
      [vocabulary.size, 5, `${vocabulary.size} gutter tag(s) came out of them`],
      [heads.size, 100, `${heads.size} record head(s) came out of them`],
      [stated, 100, `${stated} rigc invocation(s) were found stated in those pages`],
      [memo.size, 10, `${memo.size} distinct command(s) of them ran`],
      [scan.found, 18, `${scan.found} block(s) were anchored`],
      [scan.byTag, 12, `${scan.byTag} of them by a gutter tag`],
      [scan.byHead, 6, `${scan.byHead} of them by a record head`],
      // ⚠️ A smoke floor and deliberately not a tight one, which is the
      // opposite of the row above it. Most of what this rule reaches is
      // illustrations that can never fault, so holding the tree to their number
      // would turn an ordinary edit to a page of prose into a red run carrying
      // a message about an anchor rule — the shape of first action issue #468
      // refused. What has to be caught here is the rule reaching NOTHING; the
      // block a run IS laid against is held by that rule's own reach row below,
      // where it belongs.
      [scan.byRule, 1, `${scan.byRule} of them by a section rule`],
      [scan.byHeader, 1, `${scan.byHeader} of them by a report header`],
      [sealed.prefixes.length, 1, `${sealed.prefixes.length} sealed-subtree marker(s) were read`],
      [scan.excluded.length, 1, `${scan.excluded.length} block(s) were excluded by one`],
      [scan.verified.length, 1, `${scan.verified.length} block(s) reproduced`],
      ],
      'so a step of this derivation came back thinner than it has ever been',
    ),
    // The reach, one row per anchor rule. Read `docsQuoteReachFloors` for why
    // it is a claim about the population and not the number this run produced.
    ...docsQuoteReachFloors(scan),
  ];
  say(
    'DQ01_THE_DOCS_TRANSCRIPT_SCAN_READ_THE_TREE_THE_COMMANDS_AND_WHAT_IT_COULD_NOT_REACH',
    derivation.length === 0,
    derivation.length > 0
      ? derivation.join('\n          ')
      : `${docs.size} tracked markdown file(s) outside \`gallery/\`; the vocabulary comes from ${galleryRuns} run(s) ` +
        `of ${galleryExamples} gallery example(s) — {${[...vocabulary].sort().join(' ')}} at the gutter and ` +
        `${heads.size} record head(s). ${stated} rigc invocation(s) are stated in those pages and ${memo.size} ` +
        `distinct one(s) ran, ${setupRan.length} setup statement(s) having run first in the overlay of ` +
        `${overlaid.size} page(s) (${[...overlaid].sort().join(', ') || 'none'}); ${outOfReach.length} are out of reach — ` +
        `${[...byKind].sort().map(([kind, count]) => `${count} ${kind}`).join(', ')} — of which the ones on a page ` +
        `that holds an anchored block are:\n          ` +
        (outOfReach
          .filter((command) => pages.includes(command.file))
          .map((command) => `      ${command.file}:${command.line} — ${command.reason ?? ''}`)
          .join('\n          ') || '      none') +
        `\n          ${scan.found} anchored block(s) over ${pages.length} page(s) — ${scan.byTag} by a gutter tag, ` +
        `${scan.byHead} by a record head, ${scan.byRule} by a section rule, ${scan.byHeader} by a report header, ` +
        `${scan.byDeclared} by a declaration alone, ${scan.byShape} by the shape of its first line alone — of which ` +
        `${scan.verified.length} reproduce, ${scan.declared.length} are declared unreproducible, ` +
        `${scan.holes.length} are a HOLE and ${scan.unreachable.length} are unreachable. ` +
        `${reachable} block(s) were reached, and the floor on that is one row per anchor rule: ` +
        `${docsAnchorRules()
          .map(
            (rule) =>
              `${rule} ${scan.verified.filter((entry) => entry.anchor === rule).length}+` +
              `${scan.holes.filter((entry) => entry.anchor === rule).length}`,
          )
          .join(', ')} (reproducing + HOLE):\n          ` +
        [
          ...scan.holes.map((entry) => `HOLE  ${entry.where} (by ${entry.anchor}) — ${entry.why}`),
          // The declared set is printed with its reasons for the reason the
          // marker's own rule exists: a declaration nobody reads is a bypass,
          // and one this run could not reach is a marker holding no gate down.
          ...scan.declared.map(
            (entry) =>
              `DECL  ${entry.where} — ${entry.reason} [${entry.compared ? 'compared against a run and diverges' : 'never compared here'}]`,
          ),
          ...scan.unreachable.map((entry) => `      ${entry.where} — ${entry.why}`),
        ].join('\n          ') +
        `\n          ${scan.excluded.length} further block(s) are excluded as sealed records: ` +
        `${scan.excluded.map((entry) => `${entry.where} (by ${entry.sealedBy})`).join(', ')}` +
        (scan.holes.length === 0
          ? ''
          : '\n          ⚠️ Those HOLEs are not passes — this run did not check them. `bun run fetch-examples` gets the corpus.'),
    'the coverage IS the finding. This gate reaches a fraction of what `docs/` fences, and a partial scan that ' +
      'publishes its own coverage is not what this family refuses to be — a silent one is, which is why every ' +
      'unreachable block is printed with its reason rather than counted, and every declared one with the ' +
      'reason its page shows a reader. ⚠️ What this floor is still the ONLY witness of is narrower than it was ' +
      'before issue #482 and it is not nothing: a block that stops reproducing while KEEPING its anchor now ' +
      'faults in `DQ02`, but one whose own first line drifts is compared against nothing, leaves the verified ' +
      'set silently, and is seen here or nowhere — and seen here only if no other block enters under the SAME ' +
      'anchor rule in the same change, because the reach is floored one row per rule rather than on their sum ' +
      '(issue #510). The floor is a claim about the population and never a figure off this run: the number it ' +
      'used to be described a tight bound and was three blocks of slack by the time anybody re-took it. The ' +
      'sealed set is reported for the same reason, and a marker excluding nothing is a fault rather than a no-op',
  );

  // --- DQ02: the blocks themselves ------------------------------------------
  say(
    'DQ02_EVERY_DOCS_TRANSCRIPT_THIS_GATE_CAN_REACH_IS_STILL_A_RUN_OF_A_COMMAND_ITS_PAGE_STATES',
    scan.faults.length === 0 && scan.verified.length > 0,
    scan.faults.length > 0
      ? `${scan.faults.length} fault(s):\n          ${scan.faults.join('\n          ')}`
      : `${scan.verified.length} block(s) — ${scan.verified.reduce((n, entry) => n + entry.lines, 0)} line(s) — each ` +
        'a contiguous run of the output of a command its own page states: ' +
        `${scan.verified.map((entry) => `${entry.where} (${entry.lines}L, by ${entry.anchor}) <- \`${entry.command.slice(0, 60)}\``).join('; ')}` +
        `; and ${scan.declared.length} declared block(s) that no such run prints, as declared, of which ` +
        `${scan.declared.filter((entry) => entry.compared).length} were compared against a run and diverge — ` +
        'which is the set this check would fault if their declaration went',
    'the positive half is load-bearing exactly as `GT02`\'s is: a check that only reported failures would pass a ' +
      'runner that had stopped running anything, so each block, its length and the command it came from are ' +
      'named. 🔒 Since issue #482 `GT02`\'s own rule stands here too, scoped to what was actually COMPARED: a ' +
      'block whose first line a stated command does print, which then diverges and carries no declaration, is ' +
      `a fault. The scope is the whole of the care — ${scan.unreachable.filter((entry) => !entry.compared).length} ` +
      'blocks in these pages are anchored illustrations whose first line no run prints, they were never ' +
      'compared against anything, and a rule that reached them would make this gate\'s first act a demand for ' +
      'that many document repairs, which is what issue #468 spent a card refusing. The other faults are the ' +
      'two that would turn the declaration marker into a bypass — a ' +
      'reproducing block declared away, and a declaration with no reason — plus a sealed marker that is ' +
      'mis-placed or unreasoned',
  );

  // --- DQ03: the scanner against the ways a quoted transcript goes stale ----
  //
  // Red-first, `GT03`'s shape, on every block `DQ02` verifies rather than on one
  // chosen by hand. Three plants have to take a block OUT of the verified set
  // and name where it diverged; two have to FAULT; and the last has to fault
  // NOTHING, because a block that stops being anchored does not go red, it goes
  // quiet — which is the whole of what `DQ01`'s floor is for.
  //
  // 🔒 **Since issue #482 the fault rule needs its own pair, and the pair is the
  // whole of what makes "class B only" a claim rather than a hope.**
  //
  //  - **Taking a declaration off a COMPARED block has to go red** — that is the
  //    rule firing, and it is the one direction a declaration that quietly
  //    stopped being needed would hide. Taking one off a block this run could
  //    not reach has to change nothing, and the two are told apart by the flag
  //    the scan already carries rather than by a list here.
  //  - **A first line adrift has to stay quiet.** The block keeps its anchor and
  //    its place in the population and loses only its comparability, which is
  //    the state twelve `docs/` blocks are in for real. If the rule reached
  //    them the gate would open by demanding twelve document repairs.
  //  - And the three content plants get a clause they did not have: **a plant
  //    that leaves the first line alone cannot have cost the block its anchor**,
  //    so the scan compared it and the divergence has to be a fault. That test
  //    reads the plant's own edit rather than the scanner's verdict, which is
  //    what keeps it from being the check agreeing with itself.
  const misses: string[] = [];
  let planted = 0;
  let silenced = 0;
  let unplantable = 0;
  let adrift = 0;
  let pulled = 0;
  const rescan = (edited: Map<string, string>): DocsQuoteScan =>
    scanDocsQuotes(edited, vocabulary, heads, commandsBy, runsBy);
  const withText = (file: string, text: string): Map<string, string> => {
    const edited = new Map(docs);
    edited.set(file, text);
    return edited;
  };
  for (const entry of scan.verified) {
    const file = entry.where.slice(0, entry.where.lastIndexOf(':'));
    const line = Number(entry.where.slice(entry.where.lastIndexOf(':') + 1));
    const text = docs.get(file) ?? '';
    const block = galleryBlocks(text).find((candidate) => candidate.line === line);
    if (block === undefined) {
      misses.push(`${entry.where}: the verified block could not be found again to plant on`);
      continue;
    }
    for (const { name, plant } of TRANSCRIPT_PLANTS) {
      const edited = plant(block.lines);
      if (edited === null) continue;
      planted++;
      const after = rescan(withText(file, docsQuotePlant(text, block, edited)));
      const stillVerified = after.verified.some((candidate) => candidate.where === entry.where);
      const named = after.unreachable.find((candidate) => candidate.where === entry.where);
      if (stillVerified || named === undefined) {
        misses.push(
          `${entry.where}: ${name} — ${stillVerified ? 'still verified' : 'left the verified set without being named as unreachable'}`,
        );
      }
      // 🔒 Read off the PLANT rather than off the scan: an edit that did not
      // touch the first line left both anchor rules exactly as they were, so
      // this block was compared and the fault rule owes it a fault by name.
      // ⚠️ For a block the header rule found, the lines a comparison is keyed on
      // are the header AND the line under it (issue #887), so "left alone"
      // means both of them: dropping the line under a header takes the block
      // out of the compared set, which is the scope that rule is built with.
      const keyed = entry.anchor === 'header' ? 2 : 1;
      if (docsQuoteKeyLines(edited, keyed) === docsQuoteKeyLines(block.lines, keyed)) {
        if (!after.faults.some((fault) => fault.startsWith(`${entry.where}  `))) {
          misses.push(
            `${entry.where}: ${name} — the first line was left alone, so the block kept its anchor and was ` +
              'compared, and the divergence did not fault',
          );
        }
      }
    }
    // The anchor is kept and the comparability is taken away: unreachable, and
    // silent. This is the state the twelve illustrations are in.
    const wandered = docsQuoteFirstLineAdrift(block.lines);
    if (wandered === null) {
      misses.push(`${entry.where}: the block had no line to send its first one adrift`);
    } else {
      planted++;
      adrift++;
      const after = rescan(withText(file, docsQuotePlant(text, block, wandered)));
      const named = after.unreachable.find((candidate) => candidate.where === entry.where);
      // ⚠️ Against the unplanted scan's faults, not against zero. The claim is
      // about what THIS EDIT raises, and the two are the same number only on a
      // clean tree: measured on a run where one declaration had been pulled by
      // hand, an absolute clause reported all six of these plants broken when
      // every one of them had behaved.
      const raised = after.faults.filter((fault) => !scan.faults.includes(fault));
      if (after.found !== scan.found || named === undefined || raised.length !== 0) {
        misses.push(
          `${entry.where}: its first line sent adrift — the population went ${scan.found} -> ${after.found}, ` +
            `the block was ${named === undefined ? 'not named as unreachable' : 'named as unreachable'}, and ` +
            `${raised.length} new fault(s) were raised where none may be${raised.length === 0 ? '' : `: ${raised[0].slice(0, 120)}`}`,
        );
      }
    }
    // The declaration is not a way to switch the gate off.
    for (const [name, marker] of [
      ['declared while still reproducing', `${DECLARATION_LEAD} lifted out of a run that does not print it`],
      ['declared with no reason', DECLARATION_LEAD],
    ] as const) {
      const lines = text.split('\n');
      lines.splice(line - 1, 0, marker);
      planted++;
      const out = rescan(withText(file, lines.join('\n')));
      // ⚠️ Did THIS BLOCK fault — not "did anything fault" (issue #491). This
      // rescan covers every tracked page, so one stale block or one bad marker
      // anywhere in the tree satisfied the absolute form whatever the marker
      // did. Measured with both markers replaced by a blank line and a
      // sealed-subtree marker planted over the repository root to leave one
      // standing fault: the absolute form printed PASS over twelve markers
      // that faulted nothing, and this form names all twelve.
      //
      // 🔒 Attribution rather than subtracting the unplanted faults, because
      // the marker goes in ABOVE the fence: everything below it in this page
      // answers to a different line, so a standing fault there comes back as a
      // different string and a subtraction reads it as newly raised. The
      // block's own name moves by exactly the one line inserted.
      if (raisedBy(out.faults, { at: `${file}:${line + 1}  ` }).length === 0) {
        misses.push(`${entry.where}: ${name} — not faulted`);
      }
    }
    // And the silent one: no anchor, no candidate, no fault — only the floor.
    const unanchored = transcriptWithoutItsAnchor(block.lines);
    if (unanchored === null) {
      unplantable++;
      continue;
    }
    const after = rescan(withText(file, docsQuotePlant(text, block, unanchored)));
    // ⚠️ Against the unplanted scan's faults, not against zero — issue #486,
    // the same correction the adrift plant above already carries. "Quiet" is a
    // claim about what THIS EDIT raises, and a fault standing anywhere else in
    // the tree is not this plant's doing; the two are the same number only
    // while the whole suite is green, which is the one run this clause is not
    // for. Measured on a doubly-planted run — a sealed marker planted over the
    // repository root in `CONTRIBUTING.md` to leave one standing fault, and
    // then this plant on top of it: the absolute form reported
    // `6 unanchored block(s) did not drop out of the scan cleanly` when all six
    // had gone quiet, and this form reports none.
    const raisedByPlant = after.faults.filter((fault) => !scan.faults.includes(fault));
    if (after.found !== scan.found - 1 || raisedByPlant.length !== 0) silenced++;
  }

  // --- the declaration, taken off the blocks that carry one ------------------
  //
  // 🔒 The fault rule's own red-first, from the direction a real regression
  // comes from: somebody re-takes a quote, the marker above it stops being
  // true, and nothing in the tree notices. Two-sided on the flag the scan
  // carries — a declaration over a COMPARED block is holding a fault down and
  // has to go red when it goes; one over a block this run cannot reach is
  // holding nothing and has to change nothing.
  //
  // ⚠️ Deleting a line moves the fence up one, so the block answers to a
  // different name in the rescan. Computed rather than assumed: reading the old
  // name back would find nothing and pass this by reporting a miss it could not
  // explain.
  for (const entry of scan.declared) {
    const file = entry.where.slice(0, entry.where.lastIndexOf(':'));
    const line = Number(entry.where.slice(entry.where.lastIndexOf(':') + 1));
    const lines = (docs.get(file) ?? '').split('\n');
    let marker = -1;
    for (let k = line - 2; k >= 0 && k >= line - 2 - TRANSCRIPT_DECLARATION_LOOKBACK; k--) {
      if (TRANSCRIPT_DECLARATION.test(lines[k])) {
        marker = k;
        break;
      }
    }
    if (marker < 0) {
      misses.push(`${entry.where}: the declaration this block is declared by could not be found again to take off`);
      continue;
    }
    planted++;
    pulled++;
    const moved = `${file}:${line - 1}`;
    const after = rescan(withText(file, [...lines.slice(0, marker), ...lines.slice(marker + 1)].join('\n')));
    const faulted = after.faults.filter((fault) => fault.startsWith(`${moved}  `));
    if (entry.compared && faulted.length === 0) {
      misses.push(
        `${entry.where}: its declaration taken off — the block was compared against a run and diverges, so it ` +
          `must fault as ${moved}, and ${after.faults.length} fault(s) were raised naming none of it`,
      );
    }
    if (!entry.compared && faulted.length > 0) {
      misses.push(
        `${entry.where}: its declaration taken off — nothing here compared this block, so taking the marker off ` +
          `may change no verdict, and it faulted: ${faulted[0].slice(0, 120)}`,
      );
    }
  }

  // --- the working-copy bracket, shown firing somewhere it is safe to fire --
  //
  // ⭐ Two-sided on a throwaway repository, because the one place this clause
  // must never be demonstrated is the repository it protects: a probe that
  // proved the guard by dirtying the checkout would be the defect committed by
  // the check against it. Same function, same git, a directory nothing else
  // reads.
  {
    const probe = mkdtempSync(join(harnessTemp(), 'rigc-docsquote-probe-'));
    try {
      writeFileSync(join(probe, 'kept.txt'), 'a file the round leaves alone\n');
      spawnSync('git', ['init', '-q', probe], { encoding: 'utf8' });
      const clean = docsQuoteWorkingCopy(probe);
      planted++;
      if (docsQuoteWorkingCopy(probe) !== clean) {
        misses.push('the working-copy bracket reported a change over a directory nothing touched');
      }
      writeFileSync(join(probe, 'written-by-a-command.json'), '{}\n');
      planted++;
      if (docsQuoteWorkingCopy(probe) === clean) {
        misses.push('the working-copy bracket did not see a file a command wrote, so it would not see one here either');
      }
    } finally {
      rmSync(probe, { recursive: true, force: true });
    }
  }

  // --- and the sealed marker, held to the same bar ---------------------------
  //
  // ⭐ Two-sided, because the marker's danger is the opposite of a declaration's:
  // a declaration that stops being read makes a gate louder, and a SEAL that
  // stops being read makes it demand a repair #181 forbids — while a seal that
  // reads too widely makes it quiet. So: taking the marker off has to bring
  // exactly the excluded blocks back into the population and fault nothing;
  // stripping its reason has to fault; and moving it to a directory with no
  // anchored block in it has to fault as excluding nothing.
  const sealPlants: string[] = [];
  for (const entry of sealed.prefixes) {
    const file = entry.where.slice(0, entry.where.lastIndexOf(':'));
    const at = Number(entry.where.slice(entry.where.lastIndexOf(':') + 1));
    const text = docs.get(file) ?? '';
    const lines = text.split('\n');
    const mine = scan.excluded.filter((block) => block.sealedBy === entry.where).length;

    const removed = [...lines];
    removed.splice(at - 1, 1);
    planted++;
    const without = rescan(withText(file, removed.join('\n')));
    // ⚠️ Against the unplanted scan's faults, not against zero — issue #486,
    // and here the absolute form printed its own contradiction. On the
    // doubly-planted run above, with one standing fault in the tree, this
    // clause filed the real marker as a miss whose own sentence said the plant
    // had behaved: `taken off, the population moved from 22 to 23 where 23 was
    // the whole of what it sealed, and 1 fault(s) were raised`. The one fault
    // was the standing one, which this edit neither raised nor could have.
    const raisedByRemoval = raisedBy(without.faults, { was: scan.faults });
    if (without.found !== scan.found + mine || raisedByRemoval.length !== 0) {
      sealPlants.push(
        `${entry.where}: taken off, the population moved from ${scan.found} to ${without.found} where ` +
          `${scan.found + mine} was the whole of what it sealed, and ${raisedByRemoval.length} new fault(s) were raised`,
      );
    }

    const unreasoned = [...lines];
    unreasoned[at - 1] = sealedSubtreeLead();
    planted++;
    const bare = rescan(withText(file, unreasoned.join('\n')));
    // ⚠️ Did THIS MARKER fault — issue #491, the empty-seal clause below
    // already asks it this way. Stripping the reason rewrites one line in
    // place, so the marker keeps its name and the claim can be made about the
    // marker rather than about the tree.
    //
    // 🔒 And the unplanted faults come off as well, which the first run of the
    // repaired form is what found: a marker that is ALREADY faulting at its own
    // name satisfies attribution alone whatever this edit did, so a name is not
    // enough where the object being planted on can carry a fault of its own.
    // Nothing moves here, so subtracting by string is exact.
    if (raisedBy(bare.faults, { was: scan.faults, at: `${entry.where}  ` }).length === 0) {
      sealPlants.push(`${entry.where}: its reason stripped — not faulted`);
    }

    const buried = [...lines];
    buried.splice(at - 1, 1);
    buried.push(lines[at - 1]);
    planted++;
    const sunk = rescan(withText(file, buried.join('\n')));
    // ⚠️ Did THIS MARKER fault, at the line it was moved to — issue #491, and
    // here the absolute form was the worst of the three: moving the marker
    // UNSEALS its subtree, so every block it was holding out of the population
    // comes back and may fault on its own account. Those are the faults that
    // satisfied the old clause, and they are the ones that have nothing to do
    // with what this plant is about. The marker is lifted out and pushed onto
    // the end, so it answers to the last line of the page.
    const sunkAt = `${file}:${lines.length}`;
    if (raisedBy(sunk.faults, { was: scan.faults, at: `${sunkAt}  ` }).length === 0) {
      sealPlants.push(`${entry.where}: moved out of the header — not faulted`);
    }
  }
  // A marker over a directory this gate finds nothing in has to fault, and the
  // page it is planted on is picked off the run rather than named here: the
  // longest tracked page with no anchored block in it.
  {
    // ⚠️ The candidate is chosen by the marker's own reach — the DIRECTORY the
    // page sits in — and not by the page (issue #567). A marker seals
    // `dirname(path)` and everything below it, so the fault it has to raise is
    // "this PREFIX holds no anchored block"; picking the longest page that holds
    // none put the plant on `docs/SPEC_COVERAGE.md`, whose directory holds
    // several, and a legitimate marker faults nothing. The clause then reported
    // the plant as a miss — which is the honest direction, but it only reported
    // it because one page in another directory grew past it that day. A plant
    // whose validity depends on a length comparison is a plant that can stop
    // being one in silence.
    const sealsNothing = (file: string): boolean => {
      const dir = dirname(file);
      const prefix = dir === '.' ? '' : `${dir}/`;
      // The root is its own fault (a marker may not seal the whole tree), so a
      // page at the root can never be this plant's page.
      if (prefix === '') return false;
      return ![...pages, ...scan.excluded.map((block) => block.where)].some((where) => where.startsWith(prefix));
    };
    const idle = [...docs.keys()]
      .filter(sealsNothing)
      .sort((a, b) => (docs.get(b)?.length ?? 0) - (docs.get(a)?.length ?? 0))[0];
    planted++;
    if (idle === undefined) {
      sealPlants.push('no page without an anchored block was found, so the empty-seal clause was never exercised');
    } else {
      const lines = (docs.get(idle) ?? '').split('\n');
      // Immediately under the page's first line, which is where the marker's
      // own name comes from below: nothing standing can move ONTO that line,
      // because a splice here pushes everything at it downward.
      const below = 1;
      lines.splice(below, 0, `${sealedSubtreeLead()} a subtree with nothing in it, planted to watch the floor fire.`);
      const after = rescan(withText(idle, lines.join('\n')));
      // ⚠️ At the MARKER's name and against the unplanted scan (issue #506).
      // This read `startsWith(idle)` and nothing else, so it asked whether the
      // page faulted rather than whether the marker did — and a page carrying a
      // fault of its own answered yes whatever the plant did. The comment
      // beside the seal plants above already claimed this clause asked the
      // stronger question; it asked it of the file.
      const fired = raisedBy(after.faults, { was: scan.faults, at: `${idle}:${below + 1}  ` });
      if (fired.length === 0) sealPlants.push(`${idle}: a marker over a subtree with no anchored block — not faulted`);
    }
  }

  // 🚨 The floor is DERIVED and it is a probe, not a conjunct — both halves of
  // that were paid for on the run this was written. A literal `planted >= 30`
  // was correct with the corpus on disk and red without it, because a block
  // that becomes a HOLE takes its five plants with it; and because the clause
  // sat in the verdict's boolean while the detail's ternary read only `misses`,
  // the FAIL printed the sentence that says everything is fine. That is the
  // CUR09/TY12 shape exactly, twice caught before and now a third time, so the
  // rule is the one that catch produced: a floor belongs in the probe list the
  // detail prints, and its number comes off the run.
  //
  // Two plants per verified block are unconditional (a figure bumped and a
  // suffix appended — dropping an interior line needs three lines), two more
  // are the declaration pair, one is the first line sent adrift, one belongs to
  // each declared block, three belong to each sealed marker, and three stand
  // alone: the empty seal and the working copy's two sides.
  const floor = scan.verified.length * 5 + scan.declared.length + sealed.prefixes.length * 3 + 3;
  const probes = [
    ...misses,
    ...sealPlants,
    ...(silenced === 0 ? [] : [`${silenced} unanchored block(s) did not drop out of the scan cleanly`]),
    ...(unplantable === 0 ? [] : [`${unplantable} verified block(s) had no anchor letter to take off`]),
    ...(adrift === scan.verified.length
      ? []
      : [
          `${adrift} of ${scan.verified.length} verified block(s) had their first line sent adrift, so the plant ` +
            'that has to keep the fault rule off the illustrations was not applied to all of them',
        ]),
    // 🔒 Not a floor on the number of declarations — that would go red the day
    // somebody re-takes a quote and needs one fewer, which is the tree getting
    // better. What has to hold is that each one that EXISTS was planted on.
    ...(pulled === scan.declared.length
      ? []
      : [
          `${pulled} of ${scan.declared.length} declared block(s) had their declaration taken off, so a marker ` +
            'this run trusts was never shown to be holding anything',
        ]),
    ...(planted >= floor
      ? []
      : [
          `only ${planted} edit(s) were planted where ${floor} is what ${scan.verified.length} verified ` +
            `block(s), ${scan.declared.length} declared block(s) and ${sealed.prefixes.length} sealed marker(s) ` +
            'owe, so a plant stopped being applied rather than stopped being caught',
        ]),
    ...(scan.verified.length > 1 ? [] : ['one block or none is verified, which is not a population to plant on']),
  ];
  say(
    'DQ03_THE_SCANNER_FAULTS_EVERY_WAY_A_QUOTED_DOCS_TRANSCRIPT_GOES_STALE',
    probes.length === 0,
    probes.length === 0
      ? `${planted} planted edit(s) over the ${scan.verified.length} verified block(s), the ` +
        `${scan.declared.length} declared block(s) and the ${sealed.prefixes.length} sealed marker(s) — a ` +
        'figure bumped, an interior line dropped, a suffix appended, each taking its block out of the verified ' +
        'set and naming the line it diverged at, and each of those that left the first line alone also ' +
        'FAULTING, because a block that kept its anchor was compared; a reproducing block declared away and a ' +
        'declaration with no reason, each faulted; the declaration taken off each of the ' +
        `${scan.declared.filter((entry) => entry.compared).length} compared declared block(s), faulting by ` +
        `name every time, and off the ${scan.declared.filter((entry) => !entry.compared).length} this run ` +
        'cannot reach, faulting nothing; a marker with its reason stripped, a marker moved out of its header ' +
        'and a marker over a subtree holding no anchored block, each faulted; the marker taken off entirely, ' +
        `bringing exactly its ${scan.excluded.length} sealed block(s) back into the population and faulting ` +
        'nothing; the working-copy bracket shown to see a file a command wrote and to stay quiet over a ' +
        'directory nothing touched, on a throwaway repository rather than on this one; the first line sent ' +
        `ADRIFT on all ${adrift}, leaving each anchored, unreachable and faulting NOTHING, which is the state ` +
        `the ${scan.unreachable.filter((entry) => !entry.compared).length} illustrations are in and the whole ` +
        'of what scopes the fault rule; and ' +
        `taking the ANCHOR off a first line faulted NOTHING on all ${scan.verified.length}, dropping each ` +
        `silently out of the scan, which is what DQ01's floor is for`
      : `${probes.length} of ${planted} planted edit(s) did not do what they must:\n          ` +
        probes.join('\n          '),
    'a scanner is a vocabulary of shapes and a shape that stops matching goes silent, not red — and this gate ' +
      'has more ways to go silent than the gallery one, because its population is anchored across pages and its ' +
      'pool is bounded by what the tree carries. The three content plants have to name where the block ' +
      'diverged, since "this block is stale" is not a detail anybody can act on; the two declaration plants ' +
      'keep the marker from becoming a bypass; and the seal plants are two-sided in the direction that matters, ' +
      'because a seal that reads too widely silences the gate and one that stops being read makes it demand a ' +
      'repair issue #181 forbids. ⭐ The fault rule issue #482 added is held by a pair rather than by a ' +
      'sentence: taking a declaration off a COMPARED block goes red, sending a first line adrift goes quiet, ' +
      'and it is the second of those that says the rule stops at the blocks a run actually measured against — ' +
      'a rule that reached the rest would open by demanding a repair of every illustration in the guide. ' +
      '⚠️ The plant floor is a probe rather than a conjunct, and derived rather than ' +
      'typed: written as a literal it was correct with the corpus on disk and red without it, and written into ' +
      'the verdict\'s boolean alone it made the FAIL print the sentence that says every plant behaved',
  );

  // --- DQ04: the reach floors, seen firing and seen staying quiet ------------
  //
  // 🔒 **The floor `DQ03` keeps handing its silent plants to had never been
  // watched fire** (issue #510). `DQ01`'s reach clause is the only thing that
  // sees a block whose first line drifted out of the scan, and while it was one
  // number over a sum nothing had ever driven it below its bound — the bound
  // was three blocks under the run by the time anybody re-took it, so the plant
  // `DQ03` makes on every verified block could never have reached it.
  //
  // ⭐ **The plant is the whole of one rule's reach at once**, because that is
  // what the row claims: not that some number of blocks survives, but that this
  // ANCHOR RULE still reaches one. Exactly one row has to fire and it has to
  // name the rule, which is also what says the other rules' blocks were not
  // taken down with it.
  //
  // ⚠️ **And the half that states the cost.** Where a rule reaches more than one
  // block, unanchoring ONE of them has to leave every row quiet — the floor is
  // a bound and a bound with spares under it cannot see a single departure.
  // That is measured here rather than admitted in prose, so the day a tighter
  // instrument arrives this clause is what it has to contradict. The instrument
  // it wants is a comparison against another revision, which a suite that runs
  // from a fresh clone with no arguments cannot have — see the removal check in
  // `.github/workflows/squash-text.yml`.
  const reachProbes: string[] = [];
  const standing = docsQuoteReachFloors(scan);
  const reachedBy = (rule: string): string[] => [
    ...scan.verified.filter((entry) => entry.anchor === rule).map((entry) => entry.where),
    ...scan.holes.filter((entry) => entry.anchor === rule).map((entry) => entry.where),
  ];
  /** Take the anchor off each of these blocks, and say how many it could be taken off. */
  const unanchored = (wheres: readonly string[]): { edited: Map<string, string>; done: number } => {
    const edited = new Map(docs);
    let done = 0;
    for (const where of wheres) {
      const file = where.slice(0, where.lastIndexOf(':'));
      const line = Number(where.slice(where.lastIndexOf(':') + 1));
      const text = edited.get(file) ?? '';
      const block = galleryBlocks(text).find((candidate) => candidate.line === line);
      if (block === undefined) continue;
      const next = transcriptWithoutItsAnchor(block.lines);
      if (next === null) continue;
      edited.set(file, docsQuotePlant(text, block, next));
      done++;
    }
    return { edited, done };
  };
  const reachCases: string[] = [];
  for (const rule of docsAnchorRules()) {
    const blocks = reachedBy(rule);
    const whole = unanchored(blocks);
    // 🔒 Whether the plant EXISTS, bound rather than branched, because it is a
    // precondition and not the clause that decides the row below it: that row
    // is decided by what the plant raised and by nothing else. ⚠️ `RB04` reads
    // every early exit above a row as the row's guard and cannot tell those two
    // apart — it faulted this case on `blocks.length === 0` while the row was
    // already asking `raisedBy` — so the shape is worth recording rather than
    // arguing with: a precondition that answers "is there a plant" belongs in a
    // name, and the question "did MY plant fire" belongs in the `if`.
    const plantable = blocks.length > 0 && whole.done === blocks.length;
    if (!plantable) {
      reachProbes.push(
        `${rule}: ${blocks.length} block(s) are reached and the anchor could be taken off ${whole.done} of them, ` +
          'so this plant was never made',
      );
      continue;
    }
    // 🔒 Both marks, which is what `raisedBy` asks for from a plant that changes
    // the POPULATION: the subtraction keeps a row that was already standing from
    // counting as this plant's, and the attribution keeps another rule's row —
    // which this plant may not cause and the case would otherwise accept — from
    // standing in for the one being tested.
    const raised = raisedBy(docsQuoteReachFloors(rescan(whole.edited)), { was: standing, at: `the ${rule} anchor` });
    if (raised.length === 0) {
      reachProbes.push(
        `${rule}: all ${blocks.length} block(s) it reaches were unanchored and its floor row did not fire`,
      );
    }
    reachCases.push(`${rule} ${blocks.length}->0 fires`);
    if (blocks.length < 2) continue;
    const one = unanchored(blocks.slice(0, 1));
    const early = raisedBy(docsQuoteReachFloors(rescan(one.edited)), { was: standing });
    if (early.length > 0) {
      reachProbes.push(
        `${rule}: one of ${blocks.length} block(s) was unanchored and ${early.length} floor row(s) fired — a bound ` +
          `with ${blocks.length - 1} block(s) of room under it cannot have seen that, so something else is ` +
          `deciding this row: ${early[0].slice(0, 120)}`,
      );
    }
    reachCases.push(`${rule} ${blocks.length}->${blocks.length - 1} quiet`);
  }
  const reachHeld = reachProbes.length === 0;
  say(
    'DQ04_THE_REACH_FLOOR_OF_EVERY_ANCHOR_RULE_FIRES_WHEN_THAT_RULE_REACHES_NOTHING',
    reachHeld,
    probeDetail(
      reachHeld,
      reachProbes,
      `${standing.length} floor row(s) stand on the unplanted tree, and over ${docsAnchorRules().length} anchor ` +
        `rule(s): ${reachCases.join('; ')} — where each rule's whole reach unanchored fires its own row and ` +
        'nobody else\'s, and one block short of that fires nothing',
      (count) => `${count} of the reach floors did not answer their plant:`,
    ),
    'a floor nothing has driven below its bound is a sentence, not a gate — and this one was exactly that for as ' +
      'long as it was a number over a sum, because the number sat three blocks under the run and the plants ' +
      '`DQ03` already makes could never reach it. Stating the bound per anchor rule is what makes it plantable: ' +
      'the claim is that the rule reaches SOMETHING, so taking its whole reach away is a plant the tree can ' +
      'actually be put into. ⚠️ The quiet half is not a formality and it is not a boast: it measures what a ' +
      'bound cannot do, so a rule with spare blocks under it hides a single departure and this case says so in ' +
      'the same breath as the firing half',
  );

  // --- DQ05: the figures a page states BESIDE a gated transcript ------------
  //
  // 🚨 `docs/FACE.md` §8 states a slider's range in prose — a ceiling, a whole
  // degree, a seconds-per-degree and a duration — immediately beside a
  // transcript `DQ02` re-runs and compares line for line. The transcript is
  // gated and the four figures next to it were typed: this repository's own
  // `✅ applied` antipattern with a gate standing over it, filed on issue #399
  // rather than lost. Every one of them is derivable, and the page says so in
  // its own words: the ceiling is what `build` measures on that rig's depth
  // mesh, `max` is the largest whole degree strictly inside it, `from` is its
  // negative, and the animation runs `2 x max x scale`.
  //
  // 🔒 **The population is a rule and not a list**: a paragraph outside a fence
  // that quotes a slider constraint's `"from"`, `"max"` and `"scale"` inline.
  // A page that stops stating a range leaves the population, and so does one
  // that stops stating any figure this can compare — both report SKIP rather
  // than a pass, because a tree that improves must not go red and a gate with
  // nothing to measure must not print green.
  //
  // ⭐ **Which rig the paragraph is about is derived too.** The four quoted
  // fields have to name exactly one slider in one tracked gallery example, so a
  // paragraph quoting numbers no rig declares faults by name instead of being
  // compared against whatever happened to compile. The MESH is derived the same
  // way: the page's own ceiling figure has to be one a depth mesh of that rig
  // reports on both yaw ends, which is what makes the stated `±19.32°` the thing
  // under test rather than an input to it.
  //
  // ⚠️ **One correction to the shape #399 proposed.** It asks for
  // `max === Math.floor(ceiling)`, and the page's own rule is *the largest whole
  // degree strictly INSIDE the ceiling* — the two differ at a ceiling that lands
  // on a whole degree, where `floor` returns the ceiling itself and nothing is
  // strictly inside it. This derives the strict one and faults when the page's
  // `floor(…)` spelling stops agreeing with it, rather than gating the spelling
  // and inheriting its edge.
  interface RangeFigure {
    what: string;
    stated: string;
    derived: string;
  }
  interface RangeStatement {
    where: string;
    figures: RangeFigure[];
    faults: string[];
  }
  interface RangeScan {
    statements: RangeStatement[];
    /** Paragraphs that name a slider `max` and do NOT quote the whole constraint. */
    near: string[];
  }
  /** Fenced lines blanked, line numbering kept, so a paragraph still knows where it is. */
  const outsideFences = (text: string): string[] => {
    const lines = text.split('\n');
    let fenced = false;
    return lines.map((line) => {
      if (line.trimStart().startsWith('```')) {
        fenced = !fenced;
        return '';
      }
      return fenced ? '' : line;
    });
  };
  /** The four figures the prose states, each optional: a page may state fewer and must not state a wrong one. */
  const RANGE_FIGURES: ReadonlyArray<{ what: string; pattern: RegExp }> = [
    { what: 'the ceiling', pattern: /the ceiling is \*\*±([\d.]+)°\*\*/ },
    { what: 'the range', pattern: /the range is \*\*(-?[\d.]+)\*\*/ },
    { what: 'the seconds per degree', pattern: /\*\*([\d.]+) s per degree\*\*/ },
    { what: 'the duration', pattern: /= \*\*([\d.]+) s\*\*/ },
  ];
  const quotedField = (text: string, field: string): number | null => {
    const found = new RegExp(`"${field}":\\s*(-?[0-9.]+)`).exec(text);
    return found === null ? null : Number(found[1]);
  };
  /** The largest whole degree strictly inside a ceiling — the page's own rule, not `floor`. */
  const strictlyInside = (ceiling: number): number => (Number.isInteger(ceiling) ? ceiling - 1 : Math.floor(ceiling));
  /**
   * float64 noise over a derivation of two multiplications, which is what these
   * comparisons have to sit above.
   *
   * ⚠️ Not a tolerance chosen to make a case pass: `2 x 19 x 0.05` is
   * `1.9000000000000001` in binary floating point and a page that states `1.9`
   * states the right number. What a stale figure moves is a decimal digit, which
   * is fifteen orders of magnitude above this.
   */
  const rangeNoise = (value: number): number => Math.max(Math.abs(value), 1) * Number.EPSILON * 8;
  /** The same number without the binary tail, for a line a person reads. */
  const tidy = (value: number): string => String(Number(value.toPrecision(12)));

  const galleryDir = join(root, 'gallery');
  const gallerySliders: Array<{ example: string; rigPath: string; motionPath: string; slider: Record<string, unknown> }> = [];
  if (existsSync(galleryDir)) {
    for (const example of galleryExampleNames(galleryDir)) {
      const rigPath = join(galleryDir, example, 'rig.json');
      const spec = JSON.parse(readFileSync(rigPath, 'utf8')) as { constraints?: Array<Record<string, unknown>> };
      for (const constraint of spec.constraints ?? []) {
        if (constraint.type === 'slider') {
          gallerySliders.push({ example, rigPath, motionPath: join(galleryDir, example, 'motion.json'), slider: constraint });
        }
      }
    }
  }
  const rangeBuilds = new Map<string, CompileResult>();
  const buildOnce = (rigPath: string, motionPath: string): CompileResult => {
    const already = rangeBuilds.get(rigPath);
    if (already !== undefined) return already;
    const fresh = compile({ rigPath, motionPath, outDir: mkdtempSync(join(harnessTemp(), 'rigc-range-')) });
    rangeBuilds.set(rigPath, fresh);
    return fresh;
  };

  /** A paragraph naming a slider `max` at all, quoted or bare — the near-miss population. */
  const NAMES_A_MAX = /"?max"?:\s*-?[0-9.]+/;
  const RANGE_TOKENS = ['"from":', '"max":', '"scale":'];
  const scanSliderRanges = (pages: Map<string, string>): RangeScan => {
    const statements: RangeStatement[] = [];
    const near: string[] = [];
    for (const [file, text] of pages) {
      const lines = outsideFences(text);
      let start = 0;
      const paragraphs: Array<{ line: number; body: string }> = [];
      for (let i = 0; i <= lines.length; i++) {
        if (i === lines.length || lines[i].trim() === '') {
          if (i > start) paragraphs.push({ line: start + 1, body: lines.slice(start, i).join(' ') });
          start = i + 1;
        }
      }
      for (const paragraph of paragraphs) {
        const body = paragraph.body;
        const missing = RANGE_TOKENS.filter((token) => !body.includes(token));
        if (missing.length > 0) {
          // 🔒 Published rather than faulted, and `DQ01`'s reason: a partial scan
          // that says what it did not reach is not what this family refuses to
          // be — a silent one is. A second spelling of the same claim would need
          // its own phrase rules, which is the exception table this repository
          // has a judgment about, so it is named here instead of reached.
          if (NAMES_A_MAX.test(body)) {
            near.push(`${file}:${paragraph.line} names a slider max and quotes no ${missing.join(' / ')}, so it is not compared`);
          }
          continue;
        }
        const where = `${file}:${paragraph.line}`;
        const faults: string[] = [];
        const figures: RangeFigure[] = [];
        const quoted = {
          from: quotedField(body, 'from'),
          to: quotedField(body, 'to'),
          scale: quotedField(body, 'scale'),
          max: quotedField(body, 'max'),
        };
        if (quoted.from === null || quoted.to === null || quoted.scale === null || quoted.max === null) {
          faults.push(`${where}  quotes a slider constraint whose from/to/scale/max could not all be read from the paragraph`);
          statements.push({ where, figures, faults });
          continue;
        }
        const owners = gallerySliders.filter(
          (candidate) =>
            candidate.slider.from === quoted.from &&
            candidate.slider.to === quoted.to &&
            candidate.slider.scale === quoted.scale &&
            candidate.slider.max === quoted.max,
        );
        if (owners.length !== 1) {
          faults.push(
            `${where}  quotes "from": ${quoted.from}, "to": ${quoted.to}, "scale": ${quoted.scale}, "max": ${quoted.max}, ` +
              `and ${owners.length} slider(s) in the tracked gallery declare exactly that` +
              `${owners.length === 0 ? ' — the page states a constraint no example carries' : `: ${owners.map((o) => `${o.example}/${String(o.slider.name)}`).join(', ')}`}`,
          );
          statements.push({ where, figures, faults });
          continue;
        }
        const owner = owners[0];
        const built = buildOnce(owner.rigPath, owner.motionPath);
        const ceilings = built.meshes.flatMap((mesh) =>
          mesh.depth === undefined
            ? []
            : [{ slot: mesh.slot, positive: mesh.depth.ceiling.yaw.positive, negative: mesh.depth.ceiling.yaw.negative }],
        );
        const statedCeiling = RANGE_FIGURES[0].pattern.exec(body);
        let ceiling: number | null = null;
        if (statedCeiling !== null) {
          // The page's own precision decides the comparison: it states two
          // decimals, so two decimals of the measured ceiling is what has to
          // agree with it. Reading the precision off the figure is what keeps
          // this from being a rule about how a page must spell a number.
          const decimals = statedCeiling[1].split('.')[1]?.length ?? 0;
          const symmetric = ceilings.find(
            (entry) =>
              entry.positive !== null &&
              entry.negative !== null &&
              entry.positive.degrees.toFixed(decimals) === statedCeiling[1] &&
              entry.negative.degrees.toFixed(decimals) === statedCeiling[1],
          );
          if (symmetric === undefined) {
            faults.push(
              `${where}  states the ceiling as ±${statedCeiling[1]}°, and no depth mesh of ${owner.example} reports that ` +
                `on both yaw ends — ${ceilings.map((entry) => `${entry.slot} +${entry.positive?.degrees.toFixed(2) ?? 'none'} / -${entry.negative?.degrees.toFixed(2) ?? 'none'}`).join(', ') || 'the rig compiles no depth mesh at all'}`,
            );
          } else {
            ceiling = symmetric.positive!.degrees;
            figures.push({
              what: `${RANGE_FIGURES[0].what} (${owner.example} mesh "${symmetric.slot}")`,
              stated: `±${statedCeiling[1]}°`,
              derived: `±${ceiling.toFixed(5)}° measured, ±${ceiling.toFixed(decimals)}° at the page's own precision`,
            });
          }
        }
        if (ceiling !== null) {
          const inside = strictlyInside(ceiling);
          if (quoted.max !== inside) {
            faults.push(
              `${where}  quotes "max": ${quoted.max}, and the largest whole degree strictly inside the ${ceiling.toFixed(5)}° ` +
                `ceiling ${owner.example} measures is ${inside}`,
            );
          }
          if (Math.floor(ceiling) !== inside) {
            faults.push(
              `${where}  spells the rule \`floor(…)\` over a ceiling of exactly ${ceiling}°, where floor gives ${Math.floor(ceiling)} ` +
                `and the largest whole degree STRICTLY inside is ${inside} — the spelling and the rule beside it have parted`,
            );
          }
          if (quoted.from !== -quoted.max) {
            faults.push(`${where}  quotes "from": ${quoted.from} beside "max": ${quoted.max}, and the range the page derives is symmetric`);
          }
          figures.push({ what: 'the quoted "max"', stated: String(quoted.max), derived: String(inside) });
        }
        const derivedDuration = 2 * quoted.max * quoted.scale;
        const declared = built.declaredDurations[String(owner.slider.animation)];
        if (declared !== undefined && Math.abs(declared - derivedDuration) > rangeNoise(derivedDuration)) {
          faults.push(
            `${where}  derives a duration of 2 x ${quoted.max} x ${quoted.scale} = ${tidy(derivedDuration)}s, and animation ` +
              `"${String(owner.slider.animation)}" of ${owner.example} declares ${declared}s`,
          );
        }
        for (const rule of RANGE_FIGURES.slice(1)) {
          const found = rule.pattern.exec(body);
          if (found === null) continue;
          const derived =
            rule.what === 'the range' ? quoted.max : rule.what === 'the seconds per degree' ? quoted.scale : derivedDuration;
          if (Math.abs(Number(found[1]) - derived) > rangeNoise(derived)) {
            faults.push(`${where}  states ${rule.what} as ${found[1]}, and the rig it quotes derives ${tidy(derived)}`);
          }
          figures.push({ what: rule.what, stated: found[1], derived: tidy(derived) });
        }
        statements.push({ where, figures, faults });
      }
    }
    return { statements, near };
  };

  // ⚠️ EVERY tracked page, `gallery/` included — the suite's own `docs` map
  // drops those, and a path filter is not a rule. What decides membership here
  // has to be what a paragraph says, or a claim could move one directory and
  // leave the population without anything saying so.
  const rangePages = new Map<string, string>();
  if (treeFault === null) {
    for (const path of listed.stdout.toString('utf8').split('\u0000')) {
      if (path.endsWith('.md') && existsSync(join(root, path))) rangePages.set(path, readFileSync(join(root, path), 'utf8'));
    }
  }
  const rangeScan = scanSliderRanges(rangePages);
  const rangeStatements = rangeScan.statements;
  const rangeChecked = rangeStatements.reduce((n, statement) => n + statement.figures.length, 0);
  if (rangeStatements.length === 0 || rangeChecked === 0) {
    console.log(
      '  SKIP  DQ05_EVERY_FIGURE_A_PAGE_STATES_BESIDE_A_SLIDER_RANGE_IS_ONE_THE_RIG_IT_QUOTES_DERIVES  ' +
        `(over ${rangePages.size} tracked page(s), ${rangeStatements.length} paragraph(s) quote a slider constraint ` +
        `inline and ${rangeChecked} of their figures are ones this gate can derive, so it measured nothing` +
        `${rangeScan.near.length === 0 ? '' : `; ${rangeScan.near.length} paragraph(s) name a slider max and are not reached: ${rangeScan.near.join('; ')}`})`,
    );
  } else {
    // Red-first, `DQ03`'s shape and for `DQ03`'s reason: the plants edit the
    // page's own TEXT in memory rather than on disk, so the working copy is
    // never touched and the scanner is asked the question a stale page asks.
    // Five have to fault; the sixth has to fault NOTHING, because a paragraph
    // that stops quoting a constraint has left the population and a gate that
    // went red on that would go red exactly when a page improved.
    const bumpMatch = (text: string, pattern: RegExp): string | null => {
      const found = pattern.exec(text);
      if (found === null) return null;
      return (
        text.slice(0, found.index) +
        found[0].replace(found[1], String(Number(found[1]) + 1)) +
        text.slice(found.index + found[0].length)
      );
    };
    const rangePlants: Array<{ what: string; edit: (text: string) => string | null; faults: boolean }> = [
      ...RANGE_FIGURES.map((rule) => ({
        what: `${rule.what}, as the page states it, moved by one`,
        edit: (text: string): string | null => bumpMatch(text, rule.pattern),
        faults: true,
      })),
      {
        what: 'the `"max"` the paragraph quotes, moved by one',
        edit: (text: string): string | null => bumpMatch(text, /"max":\s*(-?[0-9.]+)/),
        faults: true,
      },
      {
        what: 'the `"scale"` key that makes the paragraph a range statement, removed',
        edit: (text: string): string | null => {
          const without = text.replace(/"scale":\s*-?[0-9.]+,\s*/, '');
          return without === text ? null : without;
        },
        faults: false,
      },
    ];
    const rangeRows: string[] = [];
    const rangeDrove: string[] = [];
    for (const statement of rangeStatements) {
      const file = statement.where.slice(0, statement.where.lastIndexOf(':'));
      const text = rangePages.get(file) ?? '';
      for (const plant of rangePlants) {
        const edited = plant.edit(text);
        if (edited === null) {
          rangeRows.push(`${statement.where}: ${plant.what} — the edit matched nothing, so this plant was never made`);
          continue;
        }
        const pages = new Map(rangePages);
        pages.set(file, edited);
        const after = scanSliderRanges(pages).statements.flatMap((entry) => entry.faults);
        if (plant.faults && after.length === 0) {
          rangeRows.push(`${statement.where}: ${plant.what} — the scan came back clean over the edited page`);
        }
        if (!plant.faults && after.length > 0) {
          rangeRows.push(
            `${statement.where}: ${plant.what} — the scan raised ${after.length} fault(s) over a page that simply ` +
              `stopped stating a range: ${after.join('; ')}`,
          );
        }
        rangeDrove.push(`${plant.what} -> ${after.length} fault(s)`);
      }
    }
    const rangeFaults = rangeStatements.flatMap((statement) => statement.faults);
    const rangeProbes = [...rangeFaults, ...rangeRows];
    const rangeHeld = rangeProbes.length === 0;
    say(
      'DQ05_EVERY_FIGURE_A_PAGE_STATES_BESIDE_A_SLIDER_RANGE_IS_ONE_THE_RIG_IT_QUOTES_DERIVES',
      rangeHeld,
      probeDetail(
        rangeHeld,
        rangeProbes,
        `${rangeStatements.length} paragraph(s) quote a slider constraint inline, over ${rangePages.size} tracked page(s) ` +
          `and ${gallerySliders.length} slider(s) the gallery declares; ${rangeChecked} figure(s) were derived and compared:\n          ` +
          rangeStatements
            .map(
              (statement) =>
                `${statement.where} — ${statement.figures.map((figure) => `${figure.what} ${figure.stated} (derived ${figure.derived})`).join(', ')}`,
            )
            .join('\n          ') +
          `\n          and each is driven: ${rangeDrove.join('; ')}` +
          (rangeScan.near.length === 0
            ? '\n          no other paragraph in the tree names a slider max, so nothing states this claim in a spelling ' +
              'the rule does not reach'
            : `\n          ⚠️ NOT REACHED — ${rangeScan.near.length} paragraph(s) state the same kind of claim in a ` +
              `spelling this rule does not compare, and this run did not check them: ${rangeScan.near.join('; ')}`),
        (count) => `${count} figure(s) or plant(s) did not answer:`,
      ),
      'the transcript beside this paragraph is machine-compared and the prose over it was typed, which is the exact ' +
        'pairing this repository has a settled judgment about — a checklist cannot catch a figure going stale, ' +
        'because the checklist is the thing that is wrong. Everything here is derived from two files nobody types: ' +
        'the ceiling `build` measures on the rig\'s own depth mesh, and the constraint that rig declares. ⚠️ The ' +
        'population rule is the care: it is what a paragraph QUOTES, so a page that stops making the claim leaves ' +
        'quietly and this SKIPs, and a page that keeps the claim over numbers no gallery rig declares is named ' +
        'rather than compared against whatever compiled. ⛔ What is deliberately NOT asserted is that any page ' +
        'still states a range at all — that clause would go red on the day the last hand-typed figure left the tree, ' +
        'which is the state this gate exists to reach',
    );
  }

  // --- DQ06: a transcript no anchor rule reaches is COUNTED (issue #887) -----
  //
  // 🚨 The defect this card opened on: five `pose` blocks left the population
  // in silence, so they went stale at #719 with the summary line unmoved. The
  // plant is a page the tree does not hold, with the three shapes a transcript
  // can open on and still have no run laid against it — the `..` gutter, a bare
  // header, and a header with its report under it on a page that states no
  // command — and each has to come back by path and line with its reason, the
  // population has to grow by exactly the plants, and nothing may fault.
  const shapeProbes: string[] = [];
  const shapePage = 'docs/DQ06_PLANTED_PAGE.md';
  const shapeFences: Array<{ lines: string[]; reason: string; rule: 'shape' | 'header' }> = [
    { lines: ['  ..    search  scale 0.5–2 in 7 step(s)'], reason: 'the `..` gutter mark', rule: 'shape' },
    { lines: ['rigc pose'], reason: 'a report header, with no line of its report under it', rule: 'shape' },
    { lines: ['rigc pose', '  ..    frame   …/poseA.png  (160x200)'], reason: 'nothing in this repository prints it', rule: 'header' },
  ];
  const shapeText: string[] = ['# a page planted by DQ06', ''];
  const shapeAt: number[] = [];
  for (const fence of shapeFences) {
    shapeAt.push(shapeText.length + 1);
    shapeText.push('```', ...fence.lines, '```', '');
  }
  const shapeScan = rescan(withText(shapePage, shapeText.join('\n')));
  const shapeGrew = shapeScan.found - scan.found;
  if (shapeGrew !== shapeFences.length) {
    shapeProbes.push(`the population went ${scan.found} -> ${shapeScan.found}, where the ${shapeFences.length} planted fence(s) owe +${shapeFences.length}`);
  }
  shapeFences.forEach((fence, i) => {
    const where = `${shapePage}:${shapeAt[i]}`;
    const named = shapeScan.unreachable.find((entry) => entry.where === where);
    if (named === undefined) shapeProbes.push(`${where}: not named as unreachable — it left the population in silence`);
    else if (!named.why.includes(fence.reason)) shapeProbes.push(`${where}: named, but not for its reason ("${fence.reason}"): ${named.why.slice(0, 120)}`);
    else if (named.compared) shapeProbes.push(`${where}: named as COMPARED, and nothing on its page runs anything`);
  });
  const owedShape = shapeFences.filter((fence) => fence.rule === 'shape').length;
  const owedHeader = shapeFences.filter((fence) => fence.rule === 'header').length;
  if (shapeScan.byShape - scan.byShape !== owedShape || shapeScan.byHeader - scan.byHeader !== owedHeader) {
    shapeProbes.push(
      `the counts moved by shape ${shapeScan.byShape - scan.byShape} and header ${shapeScan.byHeader - scan.byHeader}, ` +
        `where the plants owe +${owedShape} and +${owedHeader}`,
    );
  }
  const shapeRaised = raisedBy(shapeScan.faults, { was: scan.faults });
  if (shapeRaised.length !== 0) shapeProbes.push(`the plants raised ${shapeRaised.length} fault(s), where a block nothing compared may raise none: ${shapeRaised[0].slice(0, 120)}`);
  // And the same page with the fences' opening lines made prose-shaped: none of
  // them is a transcript any more, so none may be counted — the rule has to be
  // a shape, not "every plain fence".
  const proseText = shapeText.map((line) => (line === 'rigc pose' || line.startsWith('  ..') ? `  prose ${line.trim()}` : line));
  const proseScan = rescan(withText(shapePage, proseText.join('\n')));
  if (proseScan.found !== scan.found) {
    shapeProbes.push(`with the opening lines made prose, the population went ${scan.found} -> ${proseScan.found}, where a fence no shape names owes nothing`);
  }
  const shapeHeld = shapeProbes.length === 0;
  say(
    'DQ06_A_TRANSCRIPT_NO_ANCHOR_RULE_REACHES_IS_COUNTED_AS_UNREACHABLE_BY_NAME',
    shapeHeld,
    probeDetail(
      shapeHeld,
      shapeProbes,
      `${shapeFences.length} fence(s) planted on a page the tree does not hold took the population ${scan.found} -> ` +
        `${shapeScan.found}, each named by path and line — ` +
        shapeFences.map((_, i) => `${shapePage}:${shapeAt[i]} (${shapeScan.unreachable.find((entry) => entry.where === `${shapePage}:${shapeAt[i]}`)?.why.slice(0, 60) ?? ''}…)`).join('; ') +
        ` — and faulting nothing; the same fences opening on prose took it nowhere. On the tree itself ` +
        `${scan.byShape} block(s) are counted by their shape alone: ` +
        (scan.unreachable
          .filter((entry) => entry.why.startsWith('it opens on '))
          .map((entry) => entry.where)
          .join(', ') || 'none'),
      (count) => `${count} of the shape plants did not come back as they must:`,
    ),
    'issue #887: a transcript that loses every anchor is the one departure this gate could not see, because it is ' +
      'compared against nothing and so has nothing to fault — five `pose` blocks went stale that way at #719 with ' +
      'the summary unmoved and their page not among the pages. Counting such a block buys no gate on it; what it ' +
      'buys is that the summary line can never again hide one, and the shape it is counted by is one only rigc\'s ' +
      'own output opens on, so an ordinary fence of prose is not swept in — which is the half the prose plant holds',
  );

  // --- DQ07: a setup fence runs, and cannot leave its directory (issue #887) --
  //
  // ⭐ Two-sided, on the runner's own functions and a directory of its own: a
  // setup that writes a file has to be what lets the next invocation read it —
  // the same page with the tag taken off reaches nothing — and every way a
  // statement could reach outside the round is refused by name, with the
  // round's parent measured afterwards so a refusal that was printed while the
  // write still happened cannot pass.
  const setupProbes: string[] = [];
  const setupCases: string[] = [];
  {
    const probe = mkdtempSync(join(harnessTemp(), 'rigc-docsquote-setup-'));
    try {
      const page = 'docs/DQ07_PLANTED_PAGE.md';
      const written = [
        '```bash setup',
        'mkdir -p probe && cd probe',
        "bun -e 'await Bun.write(\"probe.json\", \"{}\")'",
        '```',
        '',
        '```bash',
        'rigc validate probe.json',
        '```',
        '',
      ].join('\n');
      for (const [tagged, text] of [
        [true, written],
        [false, written.replace('```bash setup', '```bash')],
      ] as const) {
        const commands = docsQuoteCommands(page, text, root);
        const pool = docsQuoteOverlayPool(page, text, commands, probe, root, new Map(), new Set());
        const read = pool.runs.some((run) => run.lines.some((line) => line.includes('/probe/probe.json')));
        if (tagged && (!read || commands.some((command) => command.reason !== null))) {
          setupProbes.push(
            `the tagged setup wrote probe/probe.json and \`rigc validate probe.json\` ${read ? 'read it but was still counted out of reach' : 'did not read it'}: ` +
              `${commands.map((command) => command.reason ?? 'ran').join('; ')}`,
          );
        }
        if (!tagged && (read || !commands.some((command) => command.kind === 'absent'))) {
          setupProbes.push('with the `setup` tag taken off, the invocation was still reached — so the tag is not what runs a setup');
        }
        setupCases.push(tagged ? `tagged: ${pool.ran.length} statement(s) ran, the invocation read what they wrote` : 'untagged: nothing ran and the invocation fell out as absent');
      }
      // The third field is what the case line prints, because one statement
      // names the round's own absolute path and a detail must not carry one.
      const escapes: Array<[string, string, string]> = [
        ['mkdir -p ../escaped', '`../escaped`', 'a `mkdir` with `..`'],
        ['cp gallery/README.md /tmp/escaped.md', '`/tmp/escaped.md`', 'a `cp` to an absolute path'],
        ['cp gallery/README.md ~/escaped.md', '`~/escaped.md`', 'a `cp` into a home directory'],
        ['cd /', '`/`', 'a `cd` to the root'],
        [`bun -e 'await Bun.write("${join(probe, 'escaped.txt')}", "x")'`, 'its script names', 'a script writing an absolute path'],
        ["bun -e 'await Bun.write(\"../escaped.txt\", \"x\")'", 'its script names', 'a script writing through `..`'],
        ['rm -rf probe', 'not one of the four statements', 'an `rm`'],
      ];
      for (const [statement, named, label] of escapes) {
        const sandbox = mkdtempSync(join(probe, 'overlay-'));
        const before = readdirSync(probe).sort().join(',');
        const setup = docsQuoteRunSetup(page, ['```bash setup', statement, '```', ''].join('\n'), sandbox, root, new Set());
        const after = readdirSync(probe).sort().join(',');
        if (setup.refusals.length !== 1 || !setup.refusals[0].includes(named)) {
          setupProbes.push(`${label} — ${setup.refusals.length === 0 ? 'not refused' : `refused without naming ${named}: ${setup.refusals[0].slice(0, 120)}`}`);
        }
        if (after !== before) setupProbes.push(`${label} — something was written beside the round's directory: ${after}`);
        setupCases.push(`${label} refused`);
      }
    } finally {
      rmSync(probe, { recursive: true, force: true });
    }
  }
  const setupHeld = setupProbes.length === 0;
  say(
    'DQ07_A_SETUP_FENCE_WRITES_WHAT_THE_NEXT_INVOCATION_READS_AND_CANNOT_LEAVE_ITS_DIRECTORY',
    setupHeld,
    probeDetail(
      setupHeld,
      setupProbes,
      `${setupCases.join('; ')}. On the tree, ${setupRan.length} setup statement(s) ran in the overlay of ` +
        `${overlaid.size} page(s): ${[...overlaid].sort().join(', ')}`,
      (count) => `${count} of the setup plants did not answer:`,
    ),
    'issue #887: `docs/MOTION.md` §6 writes its plates and frames with `bun -e`, and `docs/INGEST.md` its loose part ' +
      'with `mkdir`/`cp`, so their `pose` transcripts read files no rigc invocation makes. The runner executes the ' +
      'four statements a setup fence may state itself, so no shell is in the loop and a green run cannot depend on a ' +
      'reader\'s, and it refuses every path that climbs out — which is the half that has to be seen firing, because a ' +
      'runner that executes a page\'s statements is the one place this suite could write outside its round',
  );

  // --- DQ08: an elided path matches a prefix, and only a prefix (issue #887) --
  //
  // 🔒 The relaxation is one rule and it is held from both sides: the pairs
  // below are the rule's own statement, and the plant is its near miss on the
  // tree — every verified block with an elided path past the lines its
  // comparison is keyed on gets one character changed right after the `…/`,
  // and it has to leave the verified set AND fault by name, which is what says
  // an elision cannot absorb a difference it does not stand for.
  const elisionProbes: string[] = [];
  const elisionPairs: Array<[string, string, boolean, string]> = [
    ['  ..    frame   …/a/b.png  (1x1)', '  ..    frame   /x/y/a/b.png  (1x1)', true, 'a whole absolute prefix'],
    ['…/a/b.png', '/a/b.png', true, 'the root alone'],
    ['…/a/b.png', 'a/b.png', false, 'a relative path, which no elision stands for'],
    ['…/a/b.png', '/x/a/b.pnh', false, 'one character past the elision'],
    ['…/a', '/x/a/b', false, 'a SUFFIX left off, which an elision may not take'],
    ['x…/a', 'x/y/a', false, 'an ellipsis inside a token, which is not an elision'],
    ['…/b c', '/a b/b c', false, 'a prefix with a space in it, which no token has'],
  ];
  for (const [page, tool, want, what] of elisionPairs) {
    if (docsQuoteSameLine(page, tool) !== want) elisionProbes.push(`"${page}" against "${tool}" (${what}) — ${want ? 'did not match' : 'matched'}`);
  }
  let elisionPlanted = 0;
  const elisionOn: string[] = [];
  for (const entry of scan.verified) {
    const file = entry.where.slice(0, entry.where.lastIndexOf(':'));
    const line = Number(entry.where.slice(entry.where.lastIndexOf(':') + 1));
    const text = docs.get(file) ?? '';
    const block = galleryBlocks(text).find((candidate) => candidate.line === line);
    if (block === undefined) continue;
    const keyed = entry.anchor === 'header' ? 2 : 1;
    // Past the keyed lines, so the plant leaves the block compared: the
    // elided line a header block is keyed on is the one DQ03's adrift plant
    // already answers for.
    const carrying = block.lines.map((one, i) => (one.trim() === '' ? -1 : i)).filter((i) => i >= 0);
    const at = carrying.slice(keyed).reverse().find((i) => /(?:^|\s)…\/./.test(block.lines[i])) ?? -1;
    if (at < 0) continue;
    const edited = [...block.lines];
    const elided = /(^|\s)…\/(?=.)/.exec(edited[at]);
    if (elided === null) continue;
    const cut = elided.index + elided[1].length + 2;
    const was = edited[at][cut];
    edited[at] = `${edited[at].slice(0, cut)}${was === 'x' ? 'y' : 'x'}${edited[at].slice(cut + 1)}`;
    elisionPlanted++;
    elisionOn.push(entry.where);
    const after = rescan(withText(file, docsQuotePlant(text, block, edited)));
    if (after.verified.some((candidate) => candidate.where === entry.where)) {
      elisionProbes.push(`${entry.where}: one character after the elision on line ${at + 1} changed, and the block still reproduces`);
    } else if (!after.faults.some((fault) => fault.startsWith(`${entry.where}  `))) {
      elisionProbes.push(`${entry.where}: one character after the elision on line ${at + 1} changed, and nothing faulted`);
    }
  }
  if (elisionPlanted === 0) elisionProbes.push('no verified block carries an elided path past its keyed lines, so the near miss was never planted');
  const elisionHeld = elisionProbes.length === 0;
  say(
    'DQ08_AN_ELIDED_PATH_MATCHES_AN_ABSOLUTE_PREFIX_AND_A_ONE_CHARACTER_MISS_AFTER_IT_FAULTS',
    elisionHeld,
    probeDetail(
      elisionHeld,
      elisionProbes,
      `${elisionPairs.length} pair(s) state the rule — ${elisionPairs.map(([, , want, what]) => `${want ? 'matches' : 'refuses'} ${what}`).join('; ')} — ` +
        `and the near miss was planted on ${elisionPlanted} verified block(s), each leaving the verified set and faulting: ${elisionOn.join(', ')}`,
      (count) => `${count} of the elision checks did not answer:`,
    ),
    'issue #887: `pose`, `render` and `build` print the absolute paths they resolved and a page can only write ' +
      '`…/`, so without this rule an exact comparison could never equal a block that states a path. The rule is ' +
      'the narrowest that lets those compare — a token-leading elision, standing for whole leading components of an ' +
      'absolute path — and the near miss is what keeps it from being a loosening: a character wrong after the ' +
      'elision is wrong',
  );

  return { failures: bad, holes: scan.holes.length };
}
